function _G.BANETO_GetBasePath() --not documented
    if not BANETO_IsJin() and BANETO_Software() == "nn" then
        return "/scripts/baneto/"
    elseif BANETO_Software() == "nn" then
        return Tinkr.GetAppDirectory() .. "/baneto/"
    elseif BANETO_Software() == "tnk" then
        return "scripts/baneto/"
    end
end

function _G.BANETO_GetBasePathNoro()
    if not BANETO_IsJin() then
        return "/scripts/norotations/"
    else
        return Tinkr.GetAppDirectory() .. "/norotations/"
    end
end

function _G.BANETO_GetLocale()
    local r = ReadFile(BANETO_GetBasePath() .."logfiles/mode.txt")
    if not r or r == "0" then
        return GetLocale()
    elseif r and r == "1" then
        return "ruRU"
    elseif r and r == "2" then
        return "koKR"
    end
end

