    function _G.ObjectManager(objectstring) --global for noro
        if objectstring == "GameObject" then
            local count = Tinkr.GetGameObjectCount() or 0
            local t = {}
            for i=1,count do
                local object = Tinkr.GetGameObjectWithIndex(i)
                table.insert(t,object)
            end
            return t
        elseif objectstring == "Player" then
            local count = Tinkr.GetPlayerCount() or 0
            local t = {}
            for i=1,count do
                local object = Tinkr.GetPlayerWithIndex(i)
                table.insert(t,object)
            end
            return t
        elseif objectstring == "Unit" then
            local count = Tinkr.GetNpcCount() or 0
            local t = {}
            for i=1,count do
                local object = Tinkr.GetNpcWithIndex(i)
                table.insert(t,object)
            end
            return t
        end
    end

    function _G.Objects()
        local count, isUpdated, addedObjects, removedObjects = Tinkr.GetObjectCount()
        local t = {}
        if not count then
            count = 0
        end
        for i=1,count do
            local object = Tinkr.GetObjectWithIndex(i)
            table.insert(t,object)
        end
        return t
    end

