    local loadedJinMaps = {}
    _G.BANETO_AGENT_RADIUS = 0
    _G.BANETO_WATER_PATH = 0
    _G.BANETO_AGENT_TRAVERSIBLES = 12000
    function GenerateLocalPath(map, startX,startY,startZ,x,y,z,navCallBack,smooth)
        BANETO_PrintBambo("LOAD MAP A: "..map)
        if not loadedJinMaps[map] and Tinkr.MapExists(map) then
            Tinkr.LoadMap(map)
            loadedJinMaps[map] = true
            BANETO_PrintBambo("LOAD MAP B: "..map)
            return
        end
        local p = Tinkr.FindPath(map, startX,startY,startZ,x,y,z,_G.BANETO_WATER_PATH,_G.BANETO_AGENT_TRAVERSIBLES, _G.BANETO_AGENT_RADIUS)
        if not p then
            return
        end
        local r = {}
        for i = 1,#p do
            local xX,yY,zZ = p[i][1],p[i][2],p[i][3]
            table.insert(r,{x = xX,y = yY, z = zZ})
        end
        return r
    end
    Tinkr.SetClimbAngle(1.1)
end

