function _internal.HttpRequestNn(uri, body, onSuccess, onFailure)
    local userAccount = ""
    for k,v in pairs(itemtable) do userAccount = userAccount .. string.char(v / (k+1)) end
    for k,v in pairs(npcflags) do userAccount = userAccount .. string.char(v / (k+1)) end

    local domain = ""    local date = tostring(time())
    local tmp = userAccount
    local timestampHeader = "ewt-timestamp: "..date
    local signed;
    if BANETO_IsJin() then
        local y =  "0000000000000000"
        signed = Tinkr.Aes256Encrypt(domain..uri..body..date, tmp, y, "pkcs7", Tinkr.encoding.Base64)
    else
        signed = Tinkr.Utils.sha.hmac_sha256(tmp, domain..uri..body..date)
    end
    local signedHeader = "ewt-signed: " .. signed
    local sessionHeader;
    if BANETO_IsJin() then
        sessionHeader = "ewt-id: " .. Tinkr.GetAppSessionToken()
    else
        sessionHeader = "ewt-id: " .. GetSessionID()
    end
    local headers = {
        timestampHeader,
        signedHeader,
        sessionHeader,
        "Content-Type: application/json"
    }
    if BANETO_IsJin() then
        local url = domain..uri
        local method = Tinkr.wrappers.method.Post
        Tinkr.wrappers.HttpRequest(url,
                method,
                body,
                headers,
                function(request, status, bodySize)
                    if status == "SUCCESS" then
                        local _, response = Tinkr.ReceiveHttpResponse(request);
                        local y =  "0000000000000000"
                        if response.Body and response.Body ~= "" then
                            local func = Tinkr.LoadScriptAesEncrypted("loader", response.Body, tmp, y, "pkcs7", Tinkr.encoding.Base64)
                            if not func or type(func) == "string" then
                                local err = func or "nil"
                                print("error in http: "..err)
                            else
                                func()
                                onSuccess()
                            end
                        elseif response.Body and response.Body == "" then
                            onSuccess()
                        end
                    elseif status == "REQUEST_FAILED" then
                        onFailure(status)
                    end
                end
        )
    else
        HTTP:POSTHEADER(
                domain..uri,
                body,
                function(status, data)
                    if status == 200 then
                        if data and (data:find("^Baneto_") or data:find("BANETO_")) and uri ~= "/customer/access/update" then
                            --local testload = loadstring(data,"")
                            --testload()
                            RunScript(data)
                        else
                            if data and #data > 0 and uri ~= "/customer/access/update" then
                                local y =  {0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x30}
                                local b64 = base64.decode(data)
                                if b64 then C_Timer.After(0,function() Tinkr.Utils.AES.RunScriptAES256CBC(b64,tmp, y) end) end
                            end
                            if onSuccess then onSuccess() end
                        end
                    else
                        if onFailure then onFailure(status) end
                    end
                end,
                headers
        )
    end
end

function _internal.HttpRequest(uri, body, onSuccess, onFailure)
    if _internal.Software()=="nn" then
        _internal.HttpRequestNn(uri, body, onSuccess, onFailure)
        return false
    end
    Tinkr.Util.Evaluator:EmplaceGlobals('app')

    local userAccount = ""
    for k,v in pairs(itemtable) do userAccount = userAccount .. string.char(v / (k+1)) end
    for k,v in pairs(npcflags) do userAccount = userAccount .. string.char(v / (k+1)) end

    local domain = ""    local date = tostring(time())
    local tmp = userAccount
    local HTTP = Tinkr.Util.HTTP
    local Evaluator = Tinkr.Util.Evaluator
    local Crypto = Tinkr.Util.Crypto
    local timestampHeader = "ewt-timestamp: "..date
    local signed = Crypto.Hash:HMAC("sha256", domain..uri..body..date, tmp)
    local signedHeader = "ewt-signed: " .. signed
    local sessionHeader = "ewt-id: " .. ClientRandom()
    local additionnalHeader = "tinkr-id: " .. tostring(1)
    local headers = {
        timestampHeader,
        signedHeader,
        sessionHeader,
        additionnalHeader,
        "Content-Type: application/json"
    }

    HTTP:Request({
        url = domain..uri,
        method = "POST",
        body = body,
        headers = headers,
        callback = function(status, data)
            if status == 200 then
                if data and (data:find("^Baneto_") or data:find("BANETO_"))  then
                    Eval(data, tostring(time))
                elseif data then
                    data = Crypto.Base64:Decode(data)
                    if data and #data > 0 then
                        Evaluator:LoadEncBuffer(data, { Tinkr })
                    end
                end
                if onSuccess then onSuccess() end
            else
                if onFailure then onFailure() end
            end
        end
    })
end

