function _G.BANETO_SetSpeedVar(var)
    local writevar = "0";
    if var == "ruRU" then
        writevar = "1"
    elseif var == "koKR" then
        writevar = "2"
    end
    local r = ReadFile(BANETO_GetBasePath() .."logfiles/mode.txt")
    if (not r and writevar ~= "0") or (r and r ~= writevar) then
        BANETO_WriteFile(BANETO_GetBasePath() .."logfiles/mode.txt",writevar,false)
        -- BANETO_RunMacroText("/reload")
        reloadUi()
        C_Timer.After(3,reloadUi)
    end
end

function _G.reloadUi()
    if _internal.Software() == "nn" then
        Unlock("ReloadUI","")
    else
        ReloadUI()
    end
    -- BANETO_RunMacroText("/reload")
end

