function _G.BANETO_IsPaidListingInstalled(projectRaw,project,filesRaw,installmethod)
    if not installmethod or installmethod == "installAsProfile" then
        local dirExists = DirectoryExists(baneto_path_scripts_profiles .. project)
        if not dirExists then
            CreateDirectory(baneto_path_scripts_profiles  .. project)
            BANETO_PAID_PACK_RELOADER = true
        end
        local files = BANETO_SplitString(filesRaw, ",")
        if files then
            for i=1,#files do
                local file = files[i]
                if file and file ~= "" then
                    if not FileExists(baneto_path_scripts_profiles  .. project .."/"..file..".lua") then
                        BANETO_PAID_PACK_RELOADER = true
                        BANETO_PrintSuccess("Updating project: "..project)
                        WriteFile(baneto_path_scripts_profiles  .. project .."/"..file..".lua","BANETO_CommunityFile([["..projectRaw.."]],[["..file .."]])",false)
                    end
                end
            end
        end
    elseif installmethod and installmethod == "installAsPlugin" then
        local files = BANETO_SplitString(filesRaw, ",")
        if files then
            for i=1,#files do
                local file = files[i]
                if file and file ~= "" then
                    if not FileExists(baneto_path_scripts_plugins ..file..".lua") then
                        BANETO_PAID_PACK_RELOADER = true
                        BANETO_PrintSuccess("Updating project: "..project)
                        WriteFile(baneto_path_scripts_plugins ..file..".lua","BANETO_CommunityFile([["..projectRaw.."]],[["..file .."]])",false)
                    end
                end
            end
        end
    elseif installmethod and installmethod == "installAsNoro" and DirectoryExists(BANETO_GetBasePathNoro()) then
        local files = BANETO_SplitString(filesRaw, ",")

        local chosenclass;
        local _,_,class = UnitClass("player")
        if class == 1 then
            chosenclass = "warrior"
        elseif class == 2 then
            chosenclass = "paladin"
        elseif class == 3 then
            chosenclass = "hunter"
        elseif class == 4 then
            chosenclass = "rogue"
        elseif class == 5 then
            chosenclass = "priest"
        elseif class == 6 then
            chosenclass = "deathknight"
        elseif class == 7 then
            chosenclass = "shaman"
        elseif class == 8 then
            chosenclass = "mage"
        elseif class == 9 then
            chosenclass = "warlock"
        elseif class == 10 then
            chosenclass = "monk"
        elseif class == 11 then
            chosenclass = "druid"
        elseif class == 12 then
            chosenclass = "demonhunter"
        elseif class == 13 then
            chosenclass = "evoker"
        else
            chosenclass = "classMissing"

            end
        local folder = "retail"
        if files then
            for i=1,#files do
                local file = files[i]
                if file and file ~= "" then
                    if not FileExists(BANETO_GetBasePathNoro()..folder .. "/" .. chosenclass .."/" .. file .. ".json") then
                        BANETO_PAID_PACK_RELOADER = true
                        BANETO_PrintSuccess("Updating project: "..project)
                        WriteFile(BANETO_GetBasePathNoro()..folder .. "/" .. chosenclass .."/" .. file .. ".json",'{"projectForFile":"'..projectRaw..'","filename":"'..file..'"}',false)
                    end
                end
            end
        end
    end
end

function _G.BANETO_IsMyProjectInstalled(projectRaw,filesRaw,installmethod)
    BANETO_PrintBambo("Install check projects "..installmethod)
    local project = "Project "..projectRaw
    if not installmethod or installmethod == "Profiles" then
        local dirExists = DirectoryExists(baneto_path_scripts_profiles .. project)
        if dirExists then
            local files = BANETO_SplitString(filesRaw, ",")
            if files then
                for i=1,#files do
                    local file = files[i]
                    if file and file ~= "" then
                        if not FileExists(baneto_path_scripts_profiles  .. project .."/"..file..".lua") then
                            BANETO_PAID_PACK_RELOADER = true
                            WriteFile(baneto_path_scripts_profiles  .. project .."/"..file..".lua","BANETO_CommunityFile([["..projectRaw.."]],[["..file .."]])",false)
                        end
                    end
                end
            end
        else
            CreateDirectory(baneto_path_scripts_profiles  .. project)
            BANETO_PAID_PACK_RELOADER = true
        end
    elseif installmethod and installmethod == "Plugins" then
        local files = BANETO_SplitString(filesRaw, ",")
        if files then
            for i=1,#files do
                local file = files[i]
                if file and file ~= "" then
                    if not FileExists(baneto_path_scripts_plugins ..file..".lua") then
                        BANETO_PAID_PACK_RELOADER = true
                        WriteFile(baneto_path_scripts_plugins ..file..".lua","BANETO_CommunityFile([["..projectRaw.."]],[["..file .."]])",false)
                    end
                end
            end
        end
    elseif installmethod and installmethod == "Noros" then
        local files = BANETO_SplitString(filesRaw, ",")

        local chosenclass;
        local _,_,class = UnitClass("player")
        if class == 1 then
            chosenclass = "warrior"
        elseif class == 2 then
            chosenclass = "paladin"
        elseif class == 3 then
            chosenclass = "hunter"
        elseif class == 4 then
            chosenclass = "rogue"
        elseif class == 5 then
            chosenclass = "priest"
        elseif class == 6 then
            chosenclass = "deathknight"
        elseif class == 7 then
            chosenclass = "shaman"
        elseif class == 8 then
            chosenclass = "mage"
        elseif class == 9 then
            chosenclass = "warlock"
        elseif class == 10 then
            chosenclass = "monk"
        elseif class == 11 then
            chosenclass = "druid"
        elseif class == 12 then
            chosenclass = "demonhunter"
        elseif class == 13 then
            chosenclass = "evoker"
        else
            chosenclass = "classMissing"
        end
        local folder = "retail"
        if files then
            for i=1,#files do
                local file = files[i]
                if file and file ~= "" then
                    if not FileExists(BANETO_GetBasePathNoro()..folder .. "/" .. chosenclass .."/" .. file .. ".json") then
                        BANETO_PAID_PACK_RELOADER = true
                        WriteFile(BANETO_GetBasePathNoro()..folder .. "/" .. chosenclass .."/" .. file .. ".json",'{"projectForFile":"'..projectRaw..'","filename":"'..file..'"}',false)
                    end
                end
            end
        end
    end
end
