ownedProjectsBnt = {}
function _G.BANETO_RegisterMyProject(project, profiles)
    table.insert(ownedProjectsBnt,{project,profiles})

    local profilebutton = CreateFrame("Button", nil, panelProjects)
    profilebutton:SetPoint("Top", panelProjects, "Top", 0, jsonsStartYProjects)
    profilebutton:SetWidth(291)
    profilebutton:SetHeight(20)
    profilebutton:SetNormalFontObject("GameFontNormalSmall")
    profilebutton:SetText("|cffC6C5C3"..project)
    profilebutton:SetFrameLevel(37)
    profilebutton:SetScript("OnClick",
          function()
             StaticPopup_Show("projectselector"..project)
          end
    )

    StaticPopupDialogs["projectselector"..project] = {
        text = "Install & update project: " ..project .." as ... ?",
        button1 = "As profile",
        button2 = "As plugin",
        button3 = "As NoRo",
        OnAccept = function()
            C_Timer.NewTicker(0.01,function()
                BANETO_IsMyProjectInstalled(project,profiles,"Profiles")
            end,550)
        end,
        OnCancel = function()
            C_Timer.NewTicker(0.01,function()
                BANETO_IsMyProjectInstalled(project,profiles,"Plugins")
            end,550)
        end,
        OnAlt = function()
            C_Timer.NewTicker(0.01,function()
                BANETO_IsMyProjectInstalled(project,profiles,"Noros")
            end,550)
        end,
        timeout = 0,
        whileDead = true,
        hideOnEscape = true,
    }

    local htexButtonMain = profilebutton:CreateTexture()
    htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
    htexButtonMain:SetAllPoints()
    profilebutton:SetHighlightTexture(htexButtonMain)

    local ntexButtonMain = profilebutton:CreateTexture()
    ntexButtonMain:SetColorTexture(0.3, 0.5, 0.9, 0.2)

    ntexButtonMain:SetAllPoints()
    profilebutton:SetNormalTexture(ntexButtonMain)

    jsonsStartYProjects = jsonsStartYProjects - 20
end
