function _G.BANETO_JsonEncode(string)
    if _internal.Software() == "nn" then
        local JSON = Tinkr.Utils.JSON
        return JSON.encode(string)
    elseif _internal.Software() == "tnk" then
        return json.encode(string)
    end
end

function _G.BANETO_JsonDecode(string)
    if _internal.Software() == "nn" then
        local JSON = Tinkr.Utils.JSON
        return JSON.decode(string)
    elseif _internal.Software() == "tnk" then
        return json.decode(string)
    end
end

function _G.BANETO_BreathChecker()

	if MirrorTimer1 and MirrorTimer1:IsVisible() and IsSwimming() and not BANETO_HasBuff("player",1066) then
		if not BANETO_BREATH_TIMESTAMP then
			BANETO_BREATH_TIMESTAMP = GetTime()+45
		elseif BANETO_BREATH_TIMESTAMP then
			if BANETO_BREATH_TIMESTAMP < GetTime() and not BANETO_BLOCK_BREATH_CHECK then
				BANETO_State = "BREATH"
				BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
			end
		end
	else
		BANETO_BREATH_TIMESTAMP = nil
		BANETO_BreathTooLow = nil
	end
end

function _G.BANETO_EDITOR_ChangeQuestType()

	local questtype = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:GetText()
	if questtype == "KillAndLoot" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("TalkTo")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
	elseif questtype == "TalkTo" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("GatherObject")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
	elseif	questtype == "GatherObject" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("UseItemOnLocation")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
	elseif	questtype == "UseItemOnLocation" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("GrindTo")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Grind To Level"])
	elseif	questtype == "GrindTo" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("UseItemOnNpc")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
		BANETO_PrintWarning("EXPLANATION: The first Quest Target ID is the Item Id, all other Quest Target IDs are considered mobs/npcs!")
	elseif	questtype == "UseItemOnNpc" then
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("FarmItemAndAcceptQuest")
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
		BANETO_PrintWarning("EXPLANATION: The first Quest Target ID is the Item Id, all other Quest Target IDs are considered mobs/npcs!")
    elseif	questtype == "FarmItemAndAcceptQuest" then
        BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("Escort")
        BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
        BANETO_PrintWarning("EXPLANATION: The first Quest Target ID is the NPC Id of the VIP that we want to follow/protect!")
    elseif	questtype == "Escort" then
        BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:SetText("KillAndLoot")
        BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTID:SetText(L["Quest ID"])
	end
end


