function _G.BANETO_GetZoneId()
    local mapId = C_Map.GetBestMapForUnit("player")
    return mapId
end

function _G.BANETO_GetMapId()
    local mapID = select(8, GetInstanceInfo())
    return mapID
end

function _G.BANETO_LoadCustomTravelProfile(profileName)

	for i=1, #BANETO_CUSTOM_TRAVELPOINTS do
		local x,y,z = BANETO_CUSTOM_TRAVELPOINTS[i][1],BANETO_CUSTOM_TRAVELPOINTS[i][2],BANETO_CUSTOM_TRAVELPOINTS[i][3]
		local tableMap = BANETO_CUSTOM_TRAVELPOINTS[i][4]
		local tableName = BANETO_CUSTOM_TRAVELPOINTS[i][5]
		if tableName == profileName then
			local currentMap = BANETO_GetMapId()
			if tableMap == currentMap then
				BANETO_DefineProfileName(profileName)
				BANETO_DefineProfileType("Traveling")
				BANETO_DefineProfileTravelVector(x,y,z)
				BANETO_HideAllMainFrames()
				return true
			elseif not BANETO_DEFINED_PROFILECONTINENT or (BANETO_DEFINED_PROFILECONTINENT and BANETO_DEFINED_PROFILECONTINENT ~= tableMap) then
			    BANETO_DEFINED_PROFILECONTINENT = tableMap
				BANETO_PrintWarning("You seem to be on the wrong continent (no mesh connection, we are trying to use offmesh now)!")
			end
		end
	end
end

function _G.BANETO_GetClosestKnownTaxi()

    if Unlocker("EWT") then
        local bestDistance = 99999999
        local bestMailX, bestMailY, bestMailZ = nil,nil,nil
        for i = 1, #BANETO_FLIGHTMASTER_KNOWNTABLE2 do
            local playerX, playerY, playerZ = ObjectPosition("player")
            local mailX, mailY, mailZ = BANETO_FLIGHTMASTER_KNOWNTABLE2[i][1],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][2],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][3]
            local distance = GetDistanceBetweenPositions(playerX, playerY, playerZ,mailX, mailY, mailZ)
            --[[ print(mailX .. "--" .. mailY .. "--" .. "--" .. mailZ)
            print(distance .. "distance variable")
            print(bestDistance .. "bestdistance variable")
            print(i .. " index")]]
            if distance < bestDistance then
                bestMailX = mailX
                bestMailY = mailY
                bestMailZ = mailZ
                bestDistance = distance
            end
            if i >= #BANETO_FLIGHTMASTER_KNOWNTABLE2 then
                return bestMailX,bestMailY,bestMailZ
            end
        end
    elseif Unlocker("LUA") then
        local bestDistance = 99999999
        local bestMailX, bestMailY, bestMailZ = nil,nil,nil
        for i = 1, #BANETO_FLIGHTMASTER_KNOWNTABLE2 do
            local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
            local mailX, mailY, mailZ = BANETO_FLIGHTMASTER_KNOWNTABLE2[i][1],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][2],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][3]
            local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,mailX, mailY, mailZ)
            --[[ print(mailX .. "--" .. mailY .. "--" .. "--" .. mailZ)
            print(distance .. "distance variable")
            print(bestDistance .. "bestdistance variable")
            print(i .. " index")]]
            if distance < bestDistance then
                bestMailX = mailX
                bestMailY = mailY
                bestMailZ = mailZ
                bestDistance = distance
            end
            if i >= #BANETO_FLIGHTMASTER_KNOWNTABLE2 then
                return bestMailX,bestMailY,bestMailZ
            end
        end
    end
end

function _G.BANETO_GetDistance3D(X, Y, Z, XX, YY, ZZ)
    local dist;
    if X and XX and Y and YY and Z and ZZ then
        dist = math.sqrt((X-XX)*(X-XX) + (Y-YY)*(Y-YY) + (Z-ZZ)*(Z-ZZ))
        if dist == nil then
            dist = 0
        end
        if (dist < 0 and dist > 0) then
            BANETO_PrintBambo("DISTANCE CALC ERROR -NAND!!!!!!!")
            return 0
        end
        return	dist
    end
end

