function _G.BANETO_AreSlavesAffectingCombat()
    if UnitAffectingCombat("player") or (UnitExists("party1") and UnitAffectingCombat("party1")) or (UnitExists("party2") and UnitAffectingCombat("party2")) or (UnitExists("party3") and UnitAffectingCombat("party3")) or (UnitExists("party4") and UnitAffectingCombat("party4"))    then
        return true
    end
end

function _G.BANETO_IsGroupAffectingCombat()
    if BANETO_DEFINED_PROFILE_TYPE == "Dungeon" then
        if UnitAffectingCombat("player") or (UnitExists("party1") and UnitAffectingCombat("party1")) or (UnitExists("party2") and UnitAffectingCombat("party2")) or (UnitExists("party3") and UnitAffectingCombat("party3")) or (UnitExists("party4") and UnitAffectingCombat("party4"))    then
            return true
        end
    end
end

function _G.BANETO_LoadTravelProfile(name)

	if name == "Arathi Highlands" then
		BANETO_DefineProfileName("Arathi Highlands")
		BANETO_DefineProfileType("Traveling")
		BANETO_DefineProfileTravelVector(-1551.0250244141,-2497.2944335938,54.455780029297)
    elseif name == "TAXI" then
        BANETO_DefineProfileName("TAXI")
        BANETO_DefineProfileType("Traveling")
        local x,y,z,id = BANETO_GetClosestKnownTaxi()
        BANETO_DefineProfileTravelVector(x,y,z)
        BANETO_Start()
	elseif name == "Badlands" then
