function _G.BANETO_GameObjectType(gameObject) --ONLY use GameObjects
    local objType
    if BANETO_Software() == "nn" then
        local rawobjType = GameObjectType(gameObject)
        objType = tonumber(rawobjType)
    elseif BANETO_Software() == "tnk" then
        objType = GameObjectType(gameObject)
    end
    return objType
end


function _G.BANETO_LoadBgProfile(name)
	BANETO_ClearProfileData()
	if name == "Arathi Basin" then
		BANETO_DefineProfileName("Arathi Basin")
		BANETO_DefineProfileType("Battleground")
	elseif name == "Warsong Gulch" then
		BANETO_DefineProfileName("Warsong Gulch")
		BANETO_DefineProfileType("Battleground")

	elseif name == "Alterac Valley" then
		BANETO_DefineProfileName("Alterac Valley")
		BANETO_DefineProfileType("Battleground")
	elseif name == "Multiqueue" then
		BANETO_DefineProfileName("Multiqueue")
		BANETO_DefineProfileType("Battleground")
	end
end

function _G.BANETO_GetCurrentLocationForBg()
	BAMBO_BG_CURRENTMAP = nil
	if not BAMBO_BG_CURRENTMAP then
		if Unlocker("LUA") then
			BAMBO_BG_CURRENTMAP = BANETO_GetMapId()
		elseif Unlocker("EWT") then
			BAMBO_BG_CURRENTMAP,_,_ = GetMapId()
		end
	end
	if BAMBO_BG_CURRENTMAP == 0 then
		return "Eastern Kingdoms"
	elseif BAMBO_BG_CURRENTMAP == 1 then
		return "Kalimdor"
	elseif BAMBO_BG_CURRENTMAP == 489 then
		return "Warsong Gulch"
	elseif BAMBO_BG_CURRENTMAP == 529 then --[[ -------------------------MIIISIIING can you type ctrl shift + R --]]
		return "Arathi Basin"
	elseif BAMBO_BG_CURRENTMAP == 30 then --[[ -------------------------MIIISIIING --]]
		return "Alterac Valley"
	end
end


function _G.BANETO_JoinBgBattlemasterInteract()
	if BattlefieldFrameJoinButton and BattlefieldFrameJoinButton:IsVisible() then
		if Unlocker("EWT") then
			BattlefieldFrameJoinButton:Click()
		elseif Unlocker("LUA") then
			__LB__.Unlock(JoinBattlefield,0)
		end
	end
end

function _G.BANETO_ResetBgValues()
	BANETO_BG_JOIN_DELAY = nil
	BANETO_BG_BLOCKMOUNT = nil
	BAMBO_BG_CURRENTMAP = nil
	BAMBO_BG_CURRENT_ROAM_INDEX = nil
end


function _G.BANETO_IsBgGateUp()

	if Unlocker("EWT") then
		for i = 1,countWMB do
			local object = GetObjectWithIndex(i)
			local name = ObjectName(object)
			local id = ObjectID(object)
			if BANETO_GetCurrentLocationForBg() == "Warsong Gulch" then
				if id == 179916 or id == 179918  then
					return true
				end
			else
				if id == 179916 or id == 179918 or id == 180322   then
					return true
				end
			end
		end
	elseif Unlocker("LUA") and lb then
		local objects = __LB__.GetObjects(150)
		for i=1, #objects do
			local id = BANETO_ObjectId(objects[i])
			if BANETO_GetCurrentLocationForBg() == "Warsong Gulch" then
				if id == 179916 or id == 179918  then
					return true
				end
			else
				if id == 179916 or id == 179918 or id == 180322   then
					return true
				end
			end
		end

	end

end




function _G.BANETO_IsTrainStateRequired()
	local _,className,_ = UnitClass("player")
	local currentLevel = UnitLevel("player")
	local money = GetMoney()
	if money > 200 then
		if currentLevel < 13 then
			if BANETO_SETTING_AUTOTRAINSPELLS == true and (currentLevel-BANETO_SETTING_LASTTRAINERVISITATLEVEL) > 1  then
				local classTrainerTable =  BANETO_GetClosestClassTrainer(className)
				if classTrainerTable then
					return true
				end
			end
		elseif currentLevel >= 13 then
			if BANETO_SETTING_AUTOTRAINSPELLS == true and (currentLevel-BANETO_SETTING_LASTTRAINERVISITATLEVEL) > 3  then
				local classTrainerTable =  BANETO_GetClosestClassTrainer(className)
				if classTrainerTable then
					return true
				end
			end
		end
	end
end

function _G.BANETO_IsProfTrainStateRequired()
	local _,className,_ = UnitClass("player")
	local currentLevel = UnitLevel("player")
	if currentLevel >= 5 and BANETO_BFA_SKILLCHECKFIX then
		local currentSkill1, currentCap1 = BANETO_GetProfessionSkill(L["Herbalism"])
		local currentSkill2, currentCap2 = BANETO_GetProfessionSkill(L["Skinning"])
		local currentSkill3, currentCap3 = BANETO_GetProfessionSkill(L["Mining"])
		--[[ HERBALISM CHECK --]]
		if BANETO_SETTING_HERBALISM_TRAIN == true and (not currentSkill1 or currentCap1-currentSkill1 < 10) then
			if currentCap1 ~= 300 then
				return true, "Herbalism"
			end
		end

		--[[ SKINNING CHECK --]]
		if BANETO_SETTING_SKINNING_TRAIN == true and (not currentSkill2 or currentCap2-currentSkill2 < 10) then
			if currentCap2 ~= 300 then
				return true, "Skinning"
			end
		end

		--[[ MINING CHECK --]]
		if BANETO_SETTING_MINING_TRAIN == true and (not currentSkill3 or currentCap3-currentSkill3 < 10) then
			if currentCap3 ~= 300 then
				return true, "Mining"
			end
		end
	end

end

function _G.BANETO_IsFleeNeeded()
    if BANETO_SETTING_RUNAWAY and BANETO_SETTING_RUNAWAY == true then
        if _G.BANETO_FORCE_FLEE then
            _G.BANETO_FORCE_FLEE = nil
            return true
        end
        if BANETO_UnitHealth("player") < BANETO_SETTING_FLEE_HP then
            return true
        end
        if BANETO_UnitMana("player") < BANETO_SETTING_FLEE_MP then
            return true
        end
        local enemiesActive = GetNumEnemiesAroundUnit("player",35)
        if enemiesActive and enemiesActive >= BANETO_SETTING_FLEE_COUNT then
            return true
        end
        if Unlocker("EWT") then
            if UnitExists("target") and BANETO_SETTING_RUNAWAY_ELITES and BANETO_SETTING_RUNAWAY_ELITES == true and (UnitClassification("target") == "elite" or UnitClassification("target") == "rareelite" or UnitClassification("target") == "rare") then
                return true
            end
        elseif Unlocker("LUA") then
            if UnitExists("target") and BANETO_SETTING_RUNAWAY_ELITES and BANETO_SETTING_RUNAWAY_ELITES == true and (UnlockedTargetClassification("target") == "elite" or UnlockedTargetClassification("target") == "rareelite" or UnlockedTargetClassification("target") == "rare") then
                return true
            end
        end
        if UnitExists("target") and BANETO_SETTING_RUNAWAY_BLACKLISTED and BANETO_SETTING_RUNAWAY_BLACKLISTED == true and IsUnitBlacklisted("target") then
            return true
        end
    end
end

