function _G.BANETO_IsReviveSecure()
    if BANETO_SETTING_RESSNEARCORPSE and BANETO_SETTING_RESSNEARCORPSE == true then
        return true
    end
	if IsIndoors() then
		local hostileEnemies = GetNumHostileEnemiesAroundUnit("player",BANETO_SETTING_RESS_SECURE_RANGE_INDOORS)
		if not hostileEnemies or hostileEnemies == 0 then
			return true
		end
	else
		local hostileEnemies = GetNumHostileEnemiesAroundUnit("player",BANETO_SETTING_RESS_SECURE_RANGE_OUTDOORS)
		if not hostileEnemies or hostileEnemies == 0 then
			return true
		end
	end
end


function _G.BANETO_GetRandomPointOnCircleNEW(centerX,centerY,centerZ,radius)
    if Unlocker("LUA") then
		local x,y,z = centerX,centerY,centerZ
		local randomX = math.random(x-radius,radius+x)
		local randomness = math.random(1,2)
		local randomY;
		if randomness == 1 then
			randomY = y + math.sqrt((radius*radius)-((randomX-x)*(randomX-x)))
		elseif randomness == 2 then
			randomY = y - math.sqrt((radius*radius)-((randomX-x)*(randomX-x)))
		end
		return randomX, randomY, z
	end
end


function _G.BANETO_GetRandomPointInCircleNEW(centerX,centerY,centerZ,radius)
		local newRadius = math.random(2,radius)
		return BANETO_GetRandomPointOnCircleNEW(centerX,centerY,centerZ,newRadius)
end

function _G.BANETO_GetRandomPointOnCircle(centerX,centerY,centerZ,radius)
    if Unlocker("LUA") then
		local x,y,z = centerX,centerY,centerZ
		local randomX = math.random(math.ceil(x-radius),math.floor(radius+x))
		local randomY = y + math.sqrt((radius*radius)-((randomX-x)*(randomX-x)))
        if tostring(randomY) == "nan" or tostring(randomY) == "NAN" or tostring(randomY) == "NaN" then
            --WriteFile(baneto_path_scripts_logfiles.. UnitGUID("player") .. ".lua","\nON CIRCLE: PROBLEM VALUE",true)
            return centerX,centerY,centerZ
        end
		if randomX == randomX and randomY == randomY then
		    --WriteFile(baneto_path_scripts_logfiles.. UnitGUID("player") .. ".lua","\nON CIRCLE: "..GetTime().. " X: "..tostring(randomX).." Y: "..tostring(randomY) .." Z: "..z,true)
		    return tonumber(randomX), tonumber(randomY), z
		end
	end
end

function _G.BANETO_GetRandomPointInCircle(centerX,centerY,centerZ,radius)
    if Unlocker("LUA") then
		local x,y,z = centerX,centerY,centerZ
		local d = math.random(2,radius)
		local randomX = math.random(math.ceil(x-d),math.floor(d+x))
		local randomY = y + math.sqrt((d*d)-((randomX-x)*(randomX-x)))
		if tostring(randomY) == "nan" or tostring(randomY) == "NAN" or tostring(randomY) == "NaN" then
		    --WriteFile(baneto_path_scripts_logfiles.. UnitGUID("player") .. ".lua","\nIN CIRCLE: PROBLEM VALUE",true)
		    return centerX,centerY,centerZ
		end
		if randomX == randomX and randomY == randomY then
		    --WriteFile(baneto_path_scripts_logfiles.. UnitGUID("player") .. ".lua","\nIN CIRCLE: "..GetTime().. " X: "..tostring(randomX).." Y: "..tostring(randomY) .." Z: "..z,true)
		    return tonumber(randomX), tonumber(randomY), z
		end
	end
end
function _G.BANETO_NumAvailableRunesDkRetail()
    local counter = 0
    for i = 1,6 do
        local start1, duration1, runeReady = GetRuneCooldown(i)
        if runeReady and runeReady == true then
            counter = counter+1
        end
    end
    return counter
end
function _G.BANETO_NumAvailableRunesDk(runeType)
    if runeType == "death" then
        local counter = 0
        for i = 1,6 do
            local runeType = GetRuneType(i)
            if runeType and runeType == 4 then
                counter = counter+1
            end
        end
        return counter
    end
    if runeType == "blood" then
        local start1, duration1, runeReady1 = GetRuneCooldown(1)
        local start2, duration2, runeReady2 = GetRuneCooldown(2)
        local count = 0;
        if runeReady1 and runeReady1 == true then
            count = count+1
        end
        if runeReady2 and runeReady2 == true then
            count = count+1
        end
        return count
    elseif runeType == "unholy" then
        local start1, duration1, runeReady1 = GetRuneCooldown(3)
        local start2, duration2, runeReady2 = GetRuneCooldown(4)
        local count = 0;
        if runeReady1 and runeReady1 == true then
            count = count+1
        end
        if runeReady2 and runeReady2 == true then
            count = count+1
        end
        return count
    elseif runeType == "frost" then
        local start1, duration1, runeReady1 = GetRuneCooldown(5)
        local start2, duration2, runeReady2 = GetRuneCooldown(6)
        local count = 0;
        if runeReady1 and runeReady1 == true then
            count = count+1
        end
        if runeReady2 and runeReady2 == true then
            count = count+1
        end
        return count
    end
end

