function _G.BANETO_StopMovement()
    --BANETO_PrintBambo("StopMovement2")
    if not _G.BANETO_MOVEMENTSTOPDELAYTIME or GetTime() > _G.BANETO_MOVEMENTSTOPDELAYTIME then
        _G.BANETO_MOVEMENTSTOPDELAYTIME = GetTime()+0.15
        if BANETO_IsDragonRiding() and IsFlying() then
            _G.BANETO_MOVEMENTSTOPDELAYTIME = GetTime()+0.5
        end
        if _internal.Software() == "tnk" then
            Eval("MoveForwardStop()","smth")
            if not BANETO_IsDragonRiding() then
                Eval("MoveAndSteerStop()","smth")
            end
            Eval("StrafeLeftStop()","smth")
            if not UnitCastingInfo("player") and not UnitChannelInfo("player") and 0 < BANETO_GetUnitSpeed("player")  then
                BANETO_MoveBackwardStart()
            end
            BANETO_MoveBackwardStop()
        else
            Unlock("MoveForwardStop","")
            Unlock("StrafeLeftStop","")
            if not BANETO_IsDragonRiding() then
                Unlock("MoveAndSteerStop","")
            end
            if not UnitCastingInfo("player") and not UnitChannelInfo("player") and 0 < BANETO_GetUnitSpeed("player")  then
                BANETO_MoveBackwardStart()
            end
            BANETO_MoveBackwardStop()
        end
        if not IsFlying() then
            if not stopturnwhenstopmoving or stopturnwhenstopmoving < GetTime()  then
                stopturnwhenstopmoving = GetTime()+5
                if _internal.Software() == "tnk" then
                    Eval("TurnRightStop()","smth")
                    Eval("TurnLeftStop()","smth")
                else
                    Unlock("TurnRightStop","")
                    Unlock("TurnLeftStop","")
                end
            end
        end
        BANETO_AscendStop()
        BANETO_DescendStop()
        if not BANETO_MOVEMENTSTOPDELAYTIME_DELETEPATH or BANETO_MOVEMENTSTOPDELAYTIME_DELETEPATH < GetTime() then
            waPath = nil
            BANETO_MOVEMENTSTOPDELAYTIME_DELETEPATH = GetTime()+4
        end
    end
end

