function _G.BANETO_FindMobsTargetingUsOrOurPet()
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local mobs = {}
    for i=1, #objects do
        local object = objects[i]
        if UnitAffectingCombat(object) then
            local targetOfObject = BANETO_UnitTarget(object)
            local addedToTable = false
            if targetOfObject == BANETO_Object("player") then
                table.insert(mobs,{object,"player"})
                addedToTable = true
            elseif targetOfObject == BANETO_Object("pet") then
                table.insert(mobs,{object,"pet"})
                addedToTable = true
            end
            if addedToTable == true and not BANETO_IsGuidContainedInEngagedList(object) then
                BANETO_AddMobToEngagedList(object)
            end
        end
    end
    return mobs
end

