function _G.BANETO_FollowerDungeonCustomCode()
    local m = BANETO_GetMapId()
    if m == 2451 then --ULDAMAN
        local molemachine = GetObjectWithId(193530)
        if molemachine and GetDistanceBetweenObjects(molemachine,"player") < 30 then
            BANETO_Print("ULDA: Molemachine Found")
            local x,y,z = BANETO_ObjectPosition(molemachine)
            if not BANETO_PlayerPosition(x,y,z,5) then
                BANETO_MeshTo(x,y,z)
                BANETO_Print("ULDA: Molemachine Move")
            else
                BANETO_StopMovement()
                if BANETO_GetUnitSpeed("player") == 0 then
                    BANETO_Interact(molemachine)
                    BANETO_Print("ULDA: Molemachine Interact")

                    if BANETO_IsGossipOptionAvailable(56364) then
                        C_GossipInfo.SelectOption(56364)
                    elseif BANETO_IsGossipOptionAvailable(56365) then
                        C_GossipInfo.SelectOption(56365)
                    end
                end
            end
        end
        local door = GetObjectWithId(376191)
        if door and GetDistanceBetweenObjects(door,"player") < 30 and (not UldaDoorDelay or UldaDoorDelay < GetTime()) then
            BANETO_Print("ULDA: Door Found")
            local x,y,z = BANETO_ObjectPosition(door)
            if not BANETO_PlayerPosition(x,y,z,5) then
                BANETO_MeshTo(x,y,z)
                BANETO_Print("ULDA: Door Move")
            else
                BANETO_StopMovement()
                if BANETO_GetUnitSpeed("player") == 0 then
                    BANETO_Interact(door)
                    BANETO_Print("ULDA: Door Interact")
                    UldaDoorDelay = GetTime()+120
                end
            end
            return true
        end
        local chest = GetObjectWithId(377460) or GetObjectWithId(377461)
        if chest and BANETO_GetFreeBagSlots() >= 6 and BANETO_SETTING_LOOTING == true then
            _G.dungeonFollowerAcceptDelay = GetTime()+5
            BANETO_Print("ULDA: Chest Found")
            local x,y,z = BANETO_ObjectPosition(chest)
            if not BANETO_PlayerPosition(x,y,z,5) then
                BANETO_MeshTo(x,y,z)
                BANETO_Print("ULDA: Chest Move")
            else
                BANETO_StopMovement()
                if BANETO_GetUnitSpeed("player") == 0 then
                    BANETO_Interact(chest)
                    BANETO_Print("ULDA: Chest Interact")
                end
            end
            return true
        end
    end
    if m == 2648 then -- THE ROOKERY
        local orb = GetObjectWithId(218839)
        if orb and GetDistanceBetweenObjects(orb,"player") < 50 and GetNumHostileEnemiesAroundUnit("player",80) == 1 then
            local x,y,z = BANETO_ObjectPosition(orb)
            if not BANETO_PlayerPosition(x,y,z,4) then
                BANETO_MeshTo(x,y,z)
                BANETO_Print("ROOKERY: Orb")
            else
                BANETO_Interact(orb)
            end
            return true
        end
        local rook = GetObjectWithId(209538)
        if rook and not orb and GetDistanceBetweenObjects(rook,"player") < 150 then
            local x,y,z = BANETO_ObjectPosition(rook)
            if not BANETO_PlayerPosition(x,y,z,4) then
                BANETO_MeshTo(x,y,z)
                BANETO_Print("ROOKERY: rook")
            else
                BANETO_DelayMeshPathing(18)
                BANETO_Interact(rook)
            end
            return true
        end
        local feather = GetObjectWithId(217339)
        if feather and not BANETO_HasBuff("player",434432) then
            local xP,yP,zP = BANETO_ObjectPosition("player")
            local x,y,z = BANETO_ObjectPosition(feather)
            if xP and x and y and z and zP and zP > z then
                if not BANETO_PlayerPosition(x,y,z,4) then
                    BANETO_Print("ROOKERY: Feather")
                    BANETO_ClickToMove(x,y,z)
                else
                    BANETO_Interact(feather)
                end
                return true
            end
        end
        if BANETO_HasBuff("player",434432) and not IsFalling() then
            local angle = BANETO_GetFacingValue(2787.2941894531,-1618.7730712891,288.48526000977)
            if angle then
                BANETO_SetPlayerAnglesLuabox(angle)
            end
            BANETO_MoveForwardStart()
            C_Timer.After(8,BANETO_MoveForwardStop)
            BANETO_Print("ROOKERY: Feather Hole")
            return true
        end
        if BANETO_HasBuff("player",434432) and IsFalling() then
            BANETO_MoveForwardStop()
            local angle = BANETO_GetFacingValue(2789.3522949219,-1623.4895019531,289.14422607422)
            if angle then
                BANETO_SetPlayerAnglesLuabox(angle)
            end
            return true
        end
        if BANETO_PlayerPosition(2879.8332519531,-1591.3232421875,137.21472167969,15) then
            BANETO_Print("ROOKERY: Hole")
            BANETO_ClickToMove(2855.7348632812,-1563.9020996094,-6.266471862793)
            return true
        end
    end
end

