function _G.BANETO_QueueFollowerDungeon()  --not documented
    if not followerDungeonDelay or followerDungeonDelay < GetTime() then
        followerDungeonDelay = GetTime()+15
        BANETO_LeaveLFG(1)
        SetLFGRoles(false,false,false,true)
        local lvl = UnitLevel("player")
        local cat = 1;
        local id;
        local name;
        if (lvl >= 80 or BANETO_FOLLOWER_DUNGEON_ID) and (not BANETO_FOLLOWER_DUNGEON_ID or BANETO_FOLLOWER_DUNGEON_ID == 2655) then
            id = 2655 -- DarkflameCleft
            name = "Darkflame Cleft (Goldfarm, 80)"
        elseif (lvl >= 73 or BANETO_FOLLOWER_DUNGEON_ID) and (not BANETO_FOLLOWER_DUNGEON_ID or BANETO_FOLLOWER_DUNGEON_ID == 2701) then
            id = 2701 -- The Stonevault
            name = "The Stonevault (73-80)"
        elseif (lvl >= 70 or BANETO_FOLLOWER_DUNGEON_ID) and (not BANETO_FOLLOWER_DUNGEON_ID or BANETO_FOLLOWER_DUNGEON_ID == 2653) then
            id = 2653 -- The Rookery
            name = "The Rookery (70-73)"
        elseif (lvl >= 10 or BANETO_FOLLOWER_DUNGEON_ID) and (not BANETO_FOLLOWER_DUNGEON_ID or BANETO_FOLLOWER_DUNGEON_ID == 2465) then
            id = 2465 -- ULDAMAN
            name = "Uldaman (10-70)"
        end
        local list = GetLFGQueuedList(1)
        if not list[id]  then
            BANETO_PrintState("Follower Dungeon Queue: "..id .. " " .. name)
            BANETO_JoinSingleLFG(cat,id)
        end
    end
end

