function _G.BANETO_TappedCheck()
    if BANETO_TARGET and UnitIsTapDenied(BANETO_TARGET) == true then
        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
        BANETO_PrintState("Blacklisting Mob GUID - Unit is tapped")
        BANETO_TARGET = nil
        BANETO_ClearTarget()
        BANETO_SpellStopCasting()
        BANETO_GroundPathDeleter()
        if UnitExists("pet") then
            BANETO_PetFollow()
            BANETO_StopPetAttack()
        end
    elseif UnitExists("target") and not UnitAffectingCombat("player")  and UnitIsTapDenied("target") == true and (not tapDeniedDebugger or tapDeniedDebugger < GetTime() ) then
        BANETO_TARGET = nil
        tapDeniedDebugger=GetTime()+2
        BANETO_PrintState("Clear target! - Unit is tapped")
        BANETO_ClearTarget()
        BANETO_SpellStopCasting()
        BANETO_GroundPathDeleter()
        if UnitExists("pet") then
            BANETO_PetFollow()
            BANETO_StopPetAttack()
        end
    end
end

