function _G.BANETO_Start()
    if not UnitGUID("player") then
        BANETO_PrintError("Bad game version. Update your game.")
        return false
    end
    BANETO_ClearRemotePaths()
    if _G.BINDING_HEADER_ELVUI then
        BANETO_PrintWarning("Disable ElvUI! Not compatible! Will cause double interacts and other bugs!!")
    end
    if BANETO_IsProfileLoaded() then
        local _,_,class = UnitClass("player")
        local travel = 783
        local travelform = 292629
        if IsFlying() then
            _G.BANETO_DRAGON_LEGIT = GetTime()+3
        end
        BANETO_WMB_STUCKPADDLE = nil
        if not IsFlying() and class == 11 and (BANETO_HasBuff("player",travel) or BANETO_HasBuff("player",travelform)) and not BANETO_SHAPESHIFT_INIT_FIXER and BANETO_FLYING_PROFILE and BANETO_FLYING_PROFILE == true then
            BANETO_CancelShapeshift()
            BANETO_SHAPESHIFT_INIT_FIXER = true
            BANETO_PrintState("Druid - cancel shapeshift on ground because of reload.")
        end
        if BANETO_RECORDING_UNSTUCKROUTE then
            BANETO_PrintError("Can not start baneto while recording unstuck routes!")
            return false
        end
        if usinglbsl then
            local ntexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            BANETO_EXECUTE_FLY_ASCEND = nil
            ntexStartstop2:SetTexture(GetItemIcon(13926))
            ntexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            ntexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetNormalTexture(ntexStartstop2)

            local htexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            htexStartstop2:SetTexture(GetItemIcon(13926))
            htexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            htexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetHighlightTexture(htexStartstop2)

            local ptexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            ptexStartstop2:SetTexture(GetItemIcon(13926))
            ptexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            ptexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetPushedTexture(ptexStartstop2)
        else
            local ntexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            ntexStartstop2:SetTexture(lbslpath .. "Textures/DropdownSymbolStop.blp")
            ntexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            ntexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetNormalTexture(ntexStartstop2)

            local htexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            htexStartstop2:SetTexture(lbslpath .. "Textures/DropdownSymbolStop.blp")
            htexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            htexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetHighlightTexture(htexStartstop2)

            local ptexStartstop2 = BANETO_BUTTON_STARTSTOP:CreateTexture()
            ptexStartstop2:SetTexture(lbslpath .. "Textures/DropdownSymbolStop.blp")
            ptexStartstop2:SetTexCoord(0, 0.955, 0, 0.955)
            ptexStartstop2:SetAllPoints()
            BANETO_BUTTON_STARTSTOP:SetPushedTexture(ptexStartstop2)
        end
        BANETO_DISCORD_DELAY = GetTime()+_G.BANETO_DISCORD_DELAY_LENGTH
        BANETO_DELAY_MESHPATHING = nil
        BANETO_PrintState("Baneto activated!")
        CURRENTSWARM_TIMER = nil
        SWITCHING_GROUND_TO_FLYING = 0
        _G.BANETO_SCAN_GATHER_COUNTER = {}
        BANETO_ISRUNNING = true
        DELAY_NEXT_SPOT = nil
        BANETO_CACHE_DIGSITES = nil
        if BANETO_SETTING_RELOGGING == true then
            BANETO_SetSettingBool("IsRelogBehaviorNeeded",true)
        end
        if BANETO_DEFINED_PROFILE_TYPE == "Grinding" then
            centerIndex = BANETO_GetCenterIndexForGrinder()
        end
        if not BANETO_WOWCLOSER_TIMESTAMP and BANETO_SETTING_WOWCLOSER_MINUTES and BANETO_SETTING_WOWCLOSER and BANETO_SETTING_WOWCLOSER == true then
            BANETO_WOWCLOSER_TIMESTAMP = GetTime()+(BANETO_SETTING_WOWCLOSER_MINUTES*60)
        end
        if not BANETO_WOWLOGOUT_TIMESTAMP and BANETO_SETTING_WOWOUTLOGGER_MINUTES and BANETO_SETTING_WOWOUTLOGGER and BANETO_SETTING_WOWOUTLOGGER == true then
            BANETO_WOWLOGOUT_TIMESTAMP = GetTime()+(BANETO_SETTING_WOWOUTLOGGER_MINUTES*60)
        end
        ewtPath = nil
        waPath = nil
        icecracks_index = nil
