        BANETO_TAXI_DELAYER_TOTALBLOCK = GetTime()+4
        BANETO_RETAIL_OFFMESH_ORIBOS_DOWN = nil
        BANETO_RETAIL_OFFMESH_ORIBOS_UP = nil
        BANETO_BLOCK_LOOTING = nil
        BANETO_SETTING_SECURITY_IDLEONTARGET_NEEDED = nil
        BANETO_SETTING_SECURITY_STEALTHONTARGET_NEEDED = nil
