        BANETO_DRUID_FORMFIX = nil
        BANETO_WOWCLOSER_WARNING_5MINUTE = nil
        BANETO_WOWCLOSER_WARNING_3MINUTE = nil
        BANETO_WOWCLOSER_WARNING_1MINUTE = nil
    elseif not BANETO_IsProfileLoaded() then
        BANETO_PrintError("There is no profile loaded, please visit the profile library!")
        if not BANETO_MAIN_FRAME_PROFILE_LIBRARY:IsVisible() then
            BANETO_BUTTON_LIBRARY:Click()
        end
    end

end


function _G.BANETO_IsLastProfileATaskInTaskmanager()
    if BANETO_TASK_MANAGER and #BANETO_TASK_MANAGER >= 2 then
        for i=1,#BANETO_TASK_MANAGER do
            local taskType,taskDuration,fileName,isLocal,taskNum = BANETO_TASK_MANAGER[i][1],BANETO_TASK_MANAGER[i][2],BANETO_TASK_MANAGER[i][3],BANETO_TASK_MANAGER[i][4],i
            if fileName == BANETO_SETTING_LASTLOADEDPROFILE then
                return true
            end
        end
    end
end

function _G.BANETO_StartTaskmanager()
    if not BANETO_ISRUNNING then
        BANETO_PrintSuccess("Taskmanager reset to task 1 and ready to be used!")
        BANETO_HideAllMainFrames()
        BANETO_TASK_MANAGER_FIRSTSTART = GetTime()
        local taskType,taskDuration,fileName,isLocal = BANETO_TASK_MANAGER[1][1],BANETO_TASK_MANAGER[1][2],BANETO_TASK_MANAGER[1][3],BANETO_TASK_MANAGER[1][4]
        if taskType == "Grind/Gather/Quest" then
            BANETO_LoadProfile(fileName)
        end
        BANETO_Start()
        if BANETO_ISRUNNING then
            BANETO_PrintSuccess("Taskmanager starting..")
        else
            BANETO_PrintError("Taskmanager failed..")
            BANETO_TASK_MANAGER_FIRSTSTART = nil
        end
    else
        BANETO_PrintError("Baneto is already running.")
    end
end

function _G.BANETO_CheckMammothSpammer()
    if BANETO_RETAIL_MAMMOTH_COUNTER and BANETO_RETAIL_MAMMOTH_COUNTER > 12 then
        BANETO_RETAIL_MAMMOTH_COUNTER = 0
        BANETO_PrintWarning("Mammoth for sell/repair/goods is buggy. Starting unstuck routine.")
        BANETO_Dismount()
        BANETO_WMB_STUCKPADDLE = true
    end
end

function _G.BANETO_GetCurrentTaskmanagerProfile()
    local addedDelay = 0
    if BANETO_TASK_MANAGER and #BANETO_TASK_MANAGER >= 2 and BANETO_TASK_MANAGER_FIRSTSTART then
        for i=1,#BANETO_TASK_MANAGER do
            local taskType,taskDuration,fileName,isLocal,taskNum = BANETO_TASK_MANAGER[i][1],BANETO_TASK_MANAGER[i][2],BANETO_TASK_MANAGER[i][3],BANETO_TASK_MANAGER[i][4],i
            if i ~= 1 then
                local taskDurationBefore = BANETO_TASK_MANAGER[i-1][2]
                addedDelay = addedDelay+(taskDurationBefore*60)
            end
            if BANETO_TASK_MANAGER_FIRSTSTART+(taskDuration*60)+addedDelay > GetTime()   then
                return taskType,taskDuration,fileName,isLocal,taskNum
            end
        end
    end
    return "endoftaskmanager"
end
