function _G.BANETO_AddTask(taskType,taskDuration,fileName,isLocal)
    if not BANETO_TASK_MANAGER then
        BANETO_TASK_MANAGER= { }
    end

    isLocal = true
    taskType = "Grind/Gather/Quest"
    table.insert(BANETO_TASK_MANAGER,{taskType,(taskDuration),fileName,isLocal})
    BANETO_VisualizeTask(fileName,taskDuration)
    BANETO_SaveSettings()
end

function _G.BANETO_GetCenterIndexInFlyingPath(path) --[[  closest centerIndex --]]
    local bestDistance = 99999999
    local bestI = nil
    for i in pairs(path) do
        if 5 > i then
            local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
            local centerX, centerY, centerZ = path[i]["x"],path[i]["y"],path[i]["z"]
            local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,centerX, centerY, centerZ)
            if distance < bestDistance then
                bestDistance = distance
                bestI = i
            end
            if i ==  #path then
                return bestI
            end
        end
    end
end

function _G.BANETO_GetCenterIndexInPath(path) --[[  closest centerIndex --]]
    local bestDistance = 99999999
    local bestI = nil
    local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
    for i = 1, #path do
        local centerX, centerY, centerZ = path[i][1],path[i][2],path[i][3]
        local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,centerX, centerY, centerZ)
        if distance < bestDistance then
            bestDistance = distance
            bestI = i
        end
        if i ==  #path then
            return bestI
        end
    end
end

