    local playerX, playerY, playerZ = BANETO_ObjectPosition(unit)
    for i = 1, #path do
        local centerX, centerY, centerZ = path[i].x,path[i].y,path[i].z
        local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,centerX, centerY, centerZ)
        if distance < bestDistance then
            bestDistance = distance
            bestI = i
        end
    end
    return bestI
end


function _G.BANETO_GetCenterIndexForGrinder() --[[  closest centerIndex --]]
    if _G.RASTINY_CENTERS_IN_ORDER then
        if not centerIndex or not #BANETO_DEFINED_CENTERS then
            return 1
        else
            local returnvalues = centerIndex+1
            if #BANETO_DEFINED_CENTERS < centerIndex then
                returnvalues = #BANETO_DEFINED_CENTERS
            end
            return returnvalues
        end
    end
    if _G.GRAND_CENTERS_IN_ORDER then
        if not centerIndex or not #BANETO_DEFINED_CENTERS then
            return 1
        else
            local returnvalues = centerIndex
            if #BANETO_DEFINED_CENTERS < centerIndex then
                returnvalues = #BANETO_DEFINED_CENTERS
            end
            return returnvalues
        end
    end
	if Unlocker("EWT") then
			local bestDistance = 99999999
			local bestI = nil
			for i = 1, #BANETO_DEFINED_CENTERS do
				local playerX, playerY, playerZ = ObjectPosition("player")
				local centerX, centerY, centerZ = BANETO_DEFINED_CENTERS[i][1],BANETO_DEFINED_CENTERS[i][2],BANETO_DEFINED_CENTERS[i][3]
				local distance = GetDistanceBetweenPositions(playerX, playerY, playerZ,centerX, centerY, centerZ)
				if distance < bestDistance then
					bestDistance = distance
					bestI = i
				end

				if i ==  #BANETO_DEFINED_CENTERS then
					return bestI
				end
			end
	elseif Unlocker("LUA") then
		local bestDistance = 99999999
		local bestI = nil
		for i = 1, #BANETO_DEFINED_CENTERS do
			local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
			local centerX, centerY, centerZ = BANETO_DEFINED_CENTERS[i][1],BANETO_DEFINED_CENTERS[i][2],BANETO_DEFINED_CENTERS[i][3]
			local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,centerX, centerY, centerZ)
			if distance < bestDistance then
				bestDistance = distance
				bestI = i
			end

			if i ==  #BANETO_DEFINED_CENTERS then
				return bestI
			end
		end
	end
end

