function _G.BANETO_SetFlightLog(bool)
    BANETO_PrintSuccess("Flight recorder is active and logging to logfiles/flightlog.txt")
    BANETO_FLIGHT_LOG = true
end
function _G.BANETO_FlightLog(logging)
    if IsFlying() and BANETO_FLIGHT_LOG == true then
         if not FileExists(BANETO_GetBasePath() .."logfiles/flightlog.txt") then
             WriteFile(BANETO_GetBasePath() .."logfiles/flightlog.txt","BEGIN OF FLIGHT LOG".. "\n",false)
         end
         if not newFlightLogSession then
            WriteFile(BANETO_GetBasePath() .."logfiles/flightlog.txt","NEW SESSION FOR FLIGHT LOG".. "\n",false)
            newFlightLogSession = true
         end
         local date = date()
         WriteFile(BANETO_GetBasePath() .."logfiles/flightlog.txt",date..":::" ..logging.. "\n",true)
    end
end

function _G.BANETO_TestDcA()
    if _internal.Software() == "nn"then
        BANETO_LBUPDATE_AFK = GetTime()+35
        LastHardwareAction(GetTime()*1000)
    end
    if _internal.Software() == "tnk" then
        BANETO_LBUPDATE_AFK = GetTime()+35
        SetLastHardwareActionTime(GetTime()*1000)
    end
end

function _G.BANETO_Stop()
    flyingPath = nil
    if OZ_RAREFARM_QUESTSCAN then
        BANETO_SetOZ_RAREFARM_QUESTSCAN()
    end

    if _internal.Software() == "tnk" then
        Eval("PitchUpStop()","")
        Eval("PitchDownStop()","")
    elseif _internal.Software() == "nn" then
        Unlock("PitchUpStop","")
        Unlock("PitchDownStop","")
    end

    waPathBufferCopy = nil
    nnAvoidPath = nil
    BANETO_EXECUTE_FLY_ASCEND = nil
    BANETO_LAST_GHOST_ENTER = nil
    BANETO_RESSSPIRIT_ONCE = nil
    if BANETO_FLYING_UNSTUCK_INPROCESS  then
        BANETO_FLYING_UNSTUCK_INPROCESS = nil
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            Eval("StrafeLeftStop()","somth")
        end
        if Unlocker("LUA") and _internal.Software() == "nn" then
            Unlock("StrafeLeftStop","")

        end
    end
    BANETO_TurnStop()
    C_Timer.After(0.5,BANETO_TurnStop)
    if usinglbsl then
        local ntexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        ntexStartstop:SetTexture(GetItemIcon(7971))
        ntexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        ntexStartstop:SetAllPoints()
        BANETO_BUTTON_STARTSTOP:SetNormalTexture(ntexStartstop)

        local htexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        htexStartstop:SetTexture(GetItemIcon(7971))
        htexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        htexStartstop:SetAllPoints()
        BANETO_BUTTON_STARTSTOP:SetHighlightTexture(htexStartstop)

        local ptexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        ptexStartstop:SetTexture(GetItemIcon(7971))
        ptexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        ptexStartstop:SetAllPoints()
        BANETO_BUTTON_STARTSTOP:SetPushedTexture(ptexStartstop)
    else
        local ntexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        ntexStartstop:SetTexture(lbslpath .. "Textures/DropdownSymbolStart.blp")
        ntexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        ntexStartstop:SetAllPoints()
        BANETO_BUTTON_STARTSTOP:SetNormalTexture(ntexStartstop)

        local htexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        htexStartstop:SetTexture(lbslpath .. "Textures/DropdownSymbolStart.blp")
        htexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        htexStartstop:SetAllPoints()
        BANETO_BUTTON_STARTSTOP:SetHighlightTexture(htexStartstop)

        local ptexStartstop = BANETO_BUTTON_STARTSTOP:CreateTexture()
        ptexStartstop:SetTexture(lbslpath .. "Textures/DropdownSymbolStart.blp")
        ptexStartstop:SetTexCoord(0, 0.955, 0, 0.955)
        ptexStartstop:SetAllPoints()
 	    BANETO_BUTTON_STARTSTOP:SetPushedTexture(ptexStartstop)
    end
    if Unlocker("EWT") then
        AscendStop()
    elseif Unlocker("LUA") then
        BANETO_AscendStop()
    end
    waPath = nil
	BANETO_PrintState("Baneto paused!")
	BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2IDLE")
	BANETO_State = "IDLE"
	BANETO_TARGET = nil
	EWT_STUCK_PUSH_SENT = nil
	BANETO_UNSTUCK_ROUTE_ISACTIVE = nil
	BANETO_SetSettingBool("IsInQueueWaitProfile",false)
	BANETO_MAIL_DONE = nil
	BANETO_SETTING_RBG_RANDOM_JOINED = nil
	BANETO_SETTING_RBG_EPICRANDOM_JOINED = nil
	BANETO_ISRUNNING = false
	BANETO_ISRUNNING_1CLICKFARM = nil
    BANETO_FISH_SPOT_X = nil
    BANETO_FISH_SPOT_Y = nil
    BANETO_FISH_SPOT_Z = nil
    BANETO_FISH_SPOT_ANGLE = nil
	BANETO_STATUSUPDATE_TIMER = nil
	if BANETO_SETTING_RELOGBEHAVIORNEEDED == true then
		BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
	end
	BANETO_RBG_JOININGFINISHED = nil
