function _G.BANETO_ReloadLastProfile()
    if BANETO_IsLastProfileBattleground() then
        BANETO_LoadBgProfile(BANETO_SETTING_LASTLOADEDPROFILE)
    elseif string.find(BANETO_SETTING_LASTLOADEDPROFILE, 'OZ_WQ_') and not reloadedOzWqmProfile then
        local url1 = "https://onezero-profiles.com/oz/src/WQ/"..BANETO_SETTING_LASTLOADEDPROFILE..".lua"
        BANETO_PrintState("Reloading OZ WQ Profile: " .. BANETO_SETTING_LASTLOADEDPROFILE)
        HttpRequestCustom(url1)
        reloadedOzWqmProfile=true
    elseif BANETO_IsLastProfileDungeon() then
            BANETO_LoadDungeonProfileFromBackend(BANETO_SETTING_LASTLOADEDPROFILE)
    elseif BANETO_IsLastProfileQuesting() then
        BANETO_LoadLibraryQuest(BANETO_SETTING_LASTLOADEDPROFILE,1)
    elseif BANETO_IsLastProfileGrinding() then
        local faction,_ = UnitFactionGroup("player")
        if faction == "Alliance" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        elseif faction == "Horde" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        end
    elseif  BANETO_IsLastProfileGathering() then
        local faction,_ = UnitFactionGroup("player")
        if faction == "Alliance" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        elseif faction == "Horde" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        end
    elseif  BANETO_IsLastProfileGold() then
        local faction,_ = UnitFactionGroup("player")
        if faction == "Alliance" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        elseif faction == "Horde" then
            local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
            _internal.requestFile(myString)
        end
    elseif BANETO_IsLastProfileTraveling() then
        BANETO_LoadTravelProfile(BANETO_SETTING_LASTLOADEDPROFILE)
    elseif BANETO_SETTING_LASTLOADEDPROFILE == "1-CLICK-INSTANT-FARM" then
        BANETO_Load1ClickFarm()
    elseif BANETO_SETTING_LASTLOADEDPROFILE == "Slaveprotocol" then
        BANETO_DefineProfileName("Slaveprotocol")
        BANETO_DefineProfileType("Slavemode")
    elseif BANETO_SETTING_LASTLOADEDPROFILE == "Spot-Fishing" then
        BANETO_LoadFishy("spot")
    else
        if BANETO_SETTING_LASTLOADEDPROFILE ~= "ROTATION-ONLY-MODE" and not reloadedOzWqmProfile then
            BANETO_LoadProfile(BANETO_SETTING_LASTLOADEDPROFILE)
        end

    end
end

function _G.BANETO_ReloadAndStartLastProfile()

	if not BANETO_RELOADPROFILE_DELAY or BANETO_RELOADPROFILE_DELAY < GetTime() then
		BANETO_RELOADPROFILE_DELAY = GetTime()+5
		if not BANETO_IsProfileLoaded() then
			if BANETO_IsLastProfileBattleground() then
                BANETO_DefineProfileName("RetailBgQueue")
                BANETO_DefineProfileType("Battleground")
                BANETO_Start()
			elseif BANETO_IsLastProfileQuesting() then
				BANETO_LoadLibraryQuest(BANETO_SETTING_LASTLOADEDPROFILE,1)
			elseif BANETO_IsLastProfileGrinding() then
				local faction,_ = UnitFactionGroup("player")
				if faction == "Alliance" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				elseif faction == "Horde" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				end
			elseif  BANETO_IsLastProfileGathering() then
				local faction,_ = UnitFactionGroup("player")
				if faction == "Alliance" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				elseif faction == "Horde" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				end
			elseif  BANETO_IsLastProfileGold() then
				local faction,_ = UnitFactionGroup("player")
				if faction == "Alliance" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				elseif faction == "Horde" then
					local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
					_internal.requestFile(myString)
				end
		    elseif BANETO_IsLastProfileWqm() and not BANETO_WAITWQM_REQUEST  then
		        _internal.BANETO_WqmLoadProfile()
			elseif BANETO_IsLastProfileTraveling() then
				BANETO_LoadTravelProfile(BANETO_SETTING_LASTLOADEDPROFILE)
			elseif BANETO_SETTING_LASTLOADEDPROFILE == "1-CLICK-INSTANT-FARM" then
				BANETO_Load1ClickFarm()
			elseif BANETO_IsLastProfileEternal() then
				local myString = string.lower(BANETO_SETTING_LASTLOADEDPROFILE)
				_internal.requestFile(myString)
            elseif BANETO_SETTING_LASTLOADEDPROFILE == "Spot-Fishing" then
                BANETO_LoadFishy("spot")
			else
				if BANETO_SETTING_LASTLOADEDPROFILE ~= "ROTATION-ONLY-MODE" then
					BANETO_LoadProfile(BANETO_SETTING_LASTLOADEDPROFILE)
                else
                    BANETO_LoadRotaOnlyMode()
				end


			end
		else
			BANETO_Start()
		end
	end

end

