    function _G.BANETO_RetargetLowestHealthMob()
        if (BANETO_DEFINED_PROFILE_TYPE == "Battleground" or BANETO_SETTING_TARGET_PLAYERS == true) and not _G.BANETO_PRIEST_MULTIDOTINPROCESS and BANETO_SETTING_BGMODE_MOBFARM == false then
            if Unlocker("LUA") then
                local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
                local x,y,z = BANETO_ObjectPosition("player")
                local radius = BANETO_COMBAT_RANGE
                local bestHealth = 100000
                local bestMob = nil
                for i = 1, #objects do
                    local object = objects[i]
                    local x2,y2,z2 = BANETO_ObjectPosition(object)
                    local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                    if x and x2 then
                        if distance < radius and (UnlockedTargetReaction(object) == 4 or UnlockedTargetReaction(object) == 2) and UnitAffectingCombat(object)  then
                            local healthMob = BANETO_UnitHealth(object)
                            if healthMob < bestHealth and math.abs(healthMob-bestHealth) > 20 then
                                bestHealth = healthMob
                                bestMob = object
                            end
                        end
                    end
                end
                if bestMob and bestMob == Object("target") then
                    BANETO_PrintBambo("already targeting best PLAYER hp wise")
                elseif bestMob then
                    BANETO_PrintBambo("CHANGING TO best PLAYER hp wise")
                    BANETO_TARGET = bestMob
                    UnlockedTargetUnit(bestMob)
                end
            end
        elseif  not _G.BANETO_PRIEST_MULTIDOTINPROCESS then
            if Unlocker("LUA") then
                local objects = BANETO_OBJTS_TKR_ONLYUNITS
                local x,y,z = BANETO_ObjectPosition("player")
                local radius = 10
                local bestHealth = 100000
                local bestMob = nil
                for i = 1, #objects do
                    local object = objects[i]
                    local x2,y2,z2 = BANETO_ObjectPosition(object)
                    local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                    if x and x2 then
                        if distance < radius  and (UnlockedTargetReaction(object) == 2 or UnlockedTargetReaction(object) == 4) and UnlockedUnitAffectingCombat(object) and not UnitIsPlayer(object) and not UnitIsUnit(object,"pet") and not UnitIsTapDenied(object) and not BANETO_IsPetLuabox(object) then
                            local healthMob = BANETO_UnitHealth(object)
                            if healthMob < bestHealth and math.abs(healthMob-bestHealth) > 20 then
                                bestHealth = healthMob
                                bestMob = object
                            end
                        end
                    end
                end
                if bestMob and bestMob == Object("target") then
                    BANETO_PrintBambo("already targeting best mob hp wise")
                elseif bestMob then
                    BANETO_PrintBambo("CHANGING TO best mob hp wise")
                    BANETO_TARGET = bestMob
                    UnlockedTargetUnit(bestMob)
                end
            end
        end
    end


    function _G.BANETO_MultidotWithSpellId(debuff)
         local bombs = 0
         local bestObject;
         for i = 1,#BANETO_OBJTS_TKR_ONLYUNITS do
             local object = BANETO_OBJTS_TKR_ONLYUNITS[i]
             if object and UnitGUID(object) and BANETO_ObjectExists(object) then
                 local threat = BANETO_UnitTarget(object) == Object("player") or (UnitExists("pet") and BANETO_UnitTarget(object) == Object("pet")) or BANETO_UnitThreatSituation("player",object)
                 local hp = BANETO_UnitHealth(object)
                 local reaction = UnlockedTargetReaction(object)
                 if threat and hp > 0 and reaction <= 4 then
                     if not BANETO_HasDebuff(object,debuff) then
                        bestObject = object
                     end
                 end
             end
         end
         if bestObject then
            BANETO_TARGET = bestObject
            UnlockedTargetUnit(bestObject)
            return true
         end
    end
