    function _G.BANETO_AddMailbox(faction,mapname,x,y,z,minLevel,zoneId)
        if not minLevel then
            minLevel = 1
        end
        if not faction or not mapname or not x or not y or not z then
            BANETO_PrintError("Failed to add mailbox.")
            return false
        end
        local mapTranslated = BANETO_continentNames[mapname]
        if not mapTranslated then
            BANETO_PrintWarning("Failed to add mailbox on continent :" ..mapname)
            return
        end
        if faction == "Horde" then
            local tableOld = _G.BANETO_OBJECTS_MAILBOX_HORDE[mapTranslated]
            if not tableOld then
                _G.BANETO_OBJECTS_MAILBOX_HORDE[mapTranslated] = {}
                tableOld = _G.BANETO_OBJECTS_MAILBOX_HORDE[mapTranslated]
            end
            table.insert(tableOld,{x,y,z,minLevel,zoneId})
            _G.BANETO_OBJECTS_MAILBOX_HORDE[mapTranslated] = tableOld
        elseif faction == "Alliance" then
            local tableOld = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[mapTranslated]
            if not tableOld then
                _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[mapTranslated] = {}
                tableOld = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[mapTranslated]
            end
            table.insert(tableOld,{x,y,z,minLevel,zoneId})
            _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[mapTranslated] = tableOld
        end
    end

