function _G.BANETO_GroupHealing(percent,range)
    local targetFound = false
    BANETO_PrintBambo("test A")
    -- ÃberprÃ¼fe zuerst den Spieler selbst
    local playerHealthPercent = BANETO_GetUnitLostHealthPercent("player")
    if playerHealthPercent >= percent then
        UnlockedTargetUnit("player")
        targetFound = true
    end

    -- Wenn der Spieler nicht unter die Schwelle fÃ¤llt und er sich in einer Gruppe befindet,
    -- dann Ã¼berprÃ¼fe die restlichen Gruppenmitglieder
    if not targetFound and IsInGroup() then
        local numGroupMembers = GetNumGroupMembers()

        for i = 1, numGroupMembers do
            local unit = "party" .. i
            local healthPercent = BANETO_GetUnitLostHealthPercent(unit)
            if UnitExists(unit) and healthPercent >= percent and (not range or range >= GetDistanceBetweenObjects("player")) then
                UnlockedTargetUnit(unit)
                targetFound = true
                break
            end
        end
    end
    return targetFound
end

    function _G.BANETO_GetUnitLostHealthPercent(unit)
        local currentHealth = UnitHealth(unit)
        local maxHealth = UnitHealthMax(unit)
        if maxHealth > 0 then
            return (1 - (currentHealth / maxHealth)) * 100
        else
            return 0
        end
    end

    function _G.BANETO_GroupHasBuff(spellid)
        local targetFound = false


        if BANETO_HasBuff("player", spellid) then
            UnlockedTargetUnit("player")
            targetFound = true
        end

        if not targetFound and IsInGroup() then
            local numGroupMembers = GetNumGroupMembers()

            for i = 1, numGroupMembers do
                local unit = "party" .. i
                if BANETO_HasBuff(unit, spellid) then
                    UnlockedTargetUnit(unit)
                    targetFound = true
                    break
                end
            end
        end
        return targetFound
    end

    function _G.BANETO_FindDispell()

        -- ÃberprÃ¼fen, welche Zauber der Spieler kennt
        local canCleanseCurse = BANETO_IsSpellKnown(475) or BANETO_IsSpellKnown(2782)
        local canCleanseDisease = BANETO_IsSpellKnown(526) or BANETO_IsSpellKnown(528) or BANETO_IsSpellKnown(1152) or BANETO_IsSpellKnown(4987)
        local canCleanseMagic = BANETO_IsSpellKnown(4987) or BANETO_IsSpellKnown(527)
        local canCleansePoison = BANETO_IsSpellKnown(526) or BANETO_IsSpellKnown(1152) or BANETO_IsSpellKnown(4987) or BANETO_IsSpellKnown(8946) or BANETO_IsSpellKnown(2893)

        local numGroupMembers = GetNumGroupMembers()
        local targetFound = false

        local playerDebuff = (canCleanseMagic and BANETO_HasMagicCheck("player")) or
                             (canCleansePoison and BANETO_HasPoisonDebuffCheck("player")) or
                             (canCleanseDisease and BANETO_HasSicknessDebuffCheck("player")) or
                             (canCleanseCurse and BANETO_HasCurseDebuffCheck("player"))
        local playerHealth = BANETO_UnitHealth("player")

        if UnitExists("player") and playerDebuff and playerHealth > 0 then
            UnlockedTargetUnit("player")
            targetFound = true
        else
            for i = 1, numGroupMembers do
                local unit = "party" .. i
                local unitDebuff = (canCleanseMagic and BANETO_HasMagicCheck(unit)) or
                                   (canCleansePoison and BANETO_HasPoisonDebuffCheck(unit)) or
                                   (canCleanseDisease and BANETO_HasSicknessDebuffCheck(unit)) or
                                   (canCleanseCurse and BANETO_HasCurseDebuffCheck(unit))
                local unitHealth = BANETO_UnitHealth(unit)

                if UnitExists(unit) and unitDebuff and unitHealth > 0 then
                    UnlockedTargetUnit(unit)
                    targetFound = true
                    break
                end
            end
        end
        return targetFound
    end

