            for i=1,#BANETO_SETTING_MAILING_ALWAYSMAIL do
                local entry = BANETO_SETTING_MAILING_ALWAYSMAIL[i]
                if entry == itemname then
                    table.remove(BANETO_SETTING_MAILING_ALWAYSMAIL,i)
                    BANETO_PrintSuccess("Removed entry ".. itemname .." in Always Mail List!")
                    BANETO_SaveSettings()
                    BANETO_VisualizeAlwaysMailList()
                end
            end
        end
    end
