    function _G.BANETO_HasMammooth(id)
        for i = 1, GetNumCompanions("MOUNT") do
            local creatureID, creatureName, creatureSpellID, icon, issummoned, mountTypeID = GetCompanionInfo("MOUNT", i)
            if id == creatureSpellID then
                return true
            end
        end
    end
    function _G.BANETO_HasAnyMammooth()
        for i = 1, GetNumCompanions("MOUNT") do
            local creatureID, creatureName, creatureSpellID, icon, issummoned, mountTypeID = GetCompanionInfo("MOUNT", i)
            if creatureSpellID == 61424 or creatureSpellID == 122708 or creatureSpellID == 264058 then
                return true
            end
        end
    end
    function _G.BANETO_IsSpellKnown(spellid)
        local spellInfo = C_Spell.GetSpellInfo(spellid)
        if spellInfo and spellInfo.name then
            for i = 1, 500 do
                if GetSpellBookItemName(i,"spell") then

                    local spellBookSpellName,_ = GetSpellBookItemName(i,"spell")
                    if spellBookSpellName == spellInfo.name and not BANETO_IsSpellBlockedBySettings(spellid)  then
                        return true
                    end
                end
            end
            if UnitExists("pet") then
                for i = 1, 250 do
                    if GetSpellBookItemName(i,"pet") then

                        local spellBookSpellName,_ = GetSpellBookItemName(i,"pet")
                        if spellBookSpellName == spellInfo.name and not BANETO_IsSpellBlockedBySettings(spellid)  then
                            return true
                        end
                    end
                end
            end
        end
    end

    function _G.BANETO_IsSpellUsable(spellid)
        if spellid then
            local usableBool,manaBool = C_Spell.IsSpellUsable(spellid)
            local cooldown,_,_,_ = GetSpellCooldown(spellid)
            if usableBool == true and cooldown == 0 and not BANETO_IsSpellBlockedBySettings(spellid) then
                return true
            else
                return false
            end
        end
    end
    _G.BANETO_CUSTOM_COMBAT_RANGE = 0
    function _G.BANETO_GetCombatRange()
        return BANETO_COMBAT_RANGE
    end
    function _G.BANETO_CombatRangeModifier()
        if IsFlying() then
            if not BANETO_COMBAT_RANGE_BEFORE then
                BANETO_COMBAT_RANGE_BEFORE = BANETO_COMBAT_RANGE
                BANETO_COMBAT_RANGE = 12
            end
            return
        elseif not IsFlying() and BANETO_COMBAT_RANGE_BEFORE then
            BANETO_COMBAT_RANGE = BANETO_COMBAT_RANGE_BEFORE
            BANETO_COMBAT_RANGE_BEFORE = nil
            return
        end
        local _,_,class = UnitClass("player")
         if BANETO_CUSTOM_COMBAT_RANGE and BANETO_CUSTOM_COMBAT_RANGE > 0 then
            BANETO_COMBAT_RANGE = BANETO_CUSTOM_COMBAT_RANGE
            return false
        end

    if class == 12 then
        local spec = GetSpecialization()
        if spec and spec == 2 and BANETO_State ~= "FIGHTING" then
            if BANETO_COMBAT_RANGE ~= 22 then
                BANETO_COMBAT_RANGE = 22
            end
        else
            if BANETO_COMBAT_RANGE ~= 5 then
                BANETO_COMBAT_RANGE = 5
            end
        end
    end
        --[[ WARRIOR RANGE CHANGE FOR CHARGE --]]
	if class == 1 then
			--[[ CHARGE RANGE --]]
		local start, duration, enabled = GetSpellCooldown(100)
		if UnitLevel("player") >= 2 and (not duration or duration == 0) and UnitExists("target") and GetDistanceBetweenObjects("player","target") > 11.5  then
			if BANETO_COMBAT_RANGE ~= 22 then
				BANETO_COMBAT_RANGE = 22
			end
		else
			if  BANETO_COMBAT_RANGE ~= 5.5 then
				BANETO_COMBAT_RANGE = 5.5
			end
		end
	end


	if class == 8 then
		if BANETO_SETTING_MULTIPULL_COUNT and BANETO_SETTING_MULTIPULL_COUNT > 1 then
			if not HasWandEquipped() then
				if BANETO_COMBAT_RANGE ~= 5.5 then
					BANETO_COMBAT_RANGE = 5.5
				end
			end
			if BANETO_State == "FIGHTING" then
				if BANETO_COMBAT_RANGE ~= 5.5 then
					BANETO_COMBAT_RANGE = 5.5
				end
			elseif HasWandEquipped() then
				if BANETO_COMBAT_RANGE ~= 30 then
					BANETO_COMBAT_RANGE = 30
				end
			end
		else
			if BANETO_COMBAT_RANGE ~= 30 then
				BANETO_COMBAT_RANGE = 30
			end
		end
	end


	--[[ ROGUE RANGE CHANGE FOR STEALTHINGs --]]
	if class == 4 then

	end

	--[[ DRUID --]]
	if class == 11 then
		local boomkinBuff = 24858
        local spec = GetSpecialization()
		if BANETO_HasBuff("player",boomkinBuff) then
			if BANETO_COMBAT_RANGE ~= 41 then
				BANETO_COMBAT_RANGE = 41
			end
		elseif UnitLevel("player") >= 10 and not BANETO_HasBuff("player",boomkinBuff) and spec and spec == 3 and (BANETO_State == "FIGHTING" or BANETO_DEFINED_PROFILE_TYPE == "Slavemode") then
            if BANETO_COMBAT_RANGE ~= 4 then
                BANETO_COMBAT_RANGE = 4
            end
        elseif UnitLevel("player") >= 10 and not BANETO_HasBuff("player",boomkinBuff) and spec and spec == 2 then
            if BANETO_COMBAT_RANGE ~= 4 then
                BANETO_COMBAT_RANGE = 4
            end
		else
			if BANETO_COMBAT_RANGE ~= 30 then
				BANETO_COMBAT_RANGE = 30
			end
		end
	end

	--[[ SHAMAN --]]
	if class == 7 then
        local spec = GetSpecialization()
        if spec and spec == 2 then
            if BANETO_COMBAT_RANGE ~= 4 then
                BANETO_COMBAT_RANGE = 4
            end
        elseif spec and spec == 1 then
            if BANETO_COMBAT_RANGE ~= 30 then
                BANETO_COMBAT_RANGE = 30
            end
        elseif spec and spec == 3 then
            if BANETO_COMBAT_RANGE ~= 30 then
                BANETO_COMBAT_RANGE = 30
            end
        end
	end


    if not IsFlying() and BANETO_COMBAT_RANGE and BANETO_COMBAT_RANGE < 7 then
        if IsMounted() then
            if not BANETO_COMBAT_RANGE_BEFORE then
                BANETO_COMBAT_RANGE_BEFORE = BANETO_COMBAT_RANGE
                BANETO_COMBAT_RANGE = BANETO_COMBAT_RANGE+4
            end
            return
        elseif not IsMounted() and BANETO_COMBAT_RANGE_BEFORE then
            BANETO_COMBAT_RANGE = BANETO_COMBAT_RANGE_BEFORE
            BANETO_COMBAT_RANGE_BEFORE = nil
            return
        end
    end

end


_G.loadingFrame = CreateFrame("Frame")
loadingFrame:SetScript("OnUpdate",
	function(self)
		if not loadFightClassDelay or loadFightClassDelay < GetTime() then
            if not loadFightClassDelay and _internal.Software() == "nn" then
                loadFightClassDelay = GetTime()+0.5
                return false
            end
			loadFightClassDelay = GetTime()+3
			if not RotationString then
				local _,_,class = UnitClass("player")
				if class == 1 then
					_internal.requestFile("baneto_warrior")
					--[[ CHARGE warrior RANGE --]]
					if BANETO_IsSpellUsable(11578) then
						BANETO_COMBAT_RANGE = 22
					else
						BANETO_COMBAT_RANGE = 5.5
					end
				elseif class == 2 then
					_internal.requestFile("baneto_paladin")
					BANETO_COMBAT_RANGE = 5.5
				elseif class == 3 then
					_internal.requestFile("baneto_hunter")
					BANETO_COMBAT_RANGE = 34
				elseif class == 4 then
					_internal.requestFile("baneto_rogue")
					BANETO_COMBAT_RANGE = 5.5
				elseif class == 5 then
					_internal.requestFile("baneto_priest")
					BANETO_COMBAT_RANGE = 30
				elseif class == 7 then
					_internal.requestFile("baneto_shaman")
					BANETO_COMBAT_RANGE = 29
				elseif class == 8 then
					_internal.requestFile("baneto_mage")
					BANETO_COMBAT_RANGE = 30
				elseif class == 9 then
					_internal.requestFile("baneto_warlock")
					BANETO_COMBAT_RANGE = 30
				elseif class == 11 then
					_internal.requestFile("baneto_druid")
					BANETO_COMBAT_RANGE =  30
				elseif class == 13 then
					_internal.requestFile("baneto_evoker")
                    C_Timer.NewTicker(30,function()
                        if BANETO_GetState() == "FIGHTING" then
                            BANETO_PrintWarning("EVOKER BUG FIX!")
                            BANETO_CastSpell(357208,true)
                        end
                    end)
					BANETO_COMBAT_RANGE =  20
				elseif not BANETO_BFA_CLASS_INIT then
					BANETO_LoadSettings()
					BANETO_COMBAT_RANGE = 5
					BANETO_BFA_CLASS_INIT = true
				end
			end
		end
	end
)

function _G.BANETO_FindAttackerOfUnit(unit)
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    for i = 1, #objects do
        local object = objects[i]
        local targetOfObject = BANETO_UnitTarget(object)
        if targetOfObject == BANETO_Object(unit) and not UnitIsDeadOrGhost(object) and UnlockedUnitAffectingCombat(object) then
            return object
        end
    end
end

function _G.BANETO_AreSlavesCloseEnoughToMaster()
	local count = 1
	if UnitExists("party1") then
		count = count+1
	end
	if UnitExists("party2") then
		count = count+1
	end
	if UnitExists("party3") then
		count = count+1
	end
	if UnitExists("party4") then
		count = count+1
    end
    local currentdistancetocheck = 21
    local currentCount = GetNumFriendsAroundUnitPvp("player",currentdistancetocheck)
	if (currentCount and currentCount >= count-1) or (count and count == 1) then
        return true
	end
end

function _G.BANETO_SurvivalHunterRetailNewAoETarget()
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local x,y,z = BANETO_ObjectPosition("player")
    local radius = 25

    local bestMob = nil
    for i = 1, #objects do
        local object = objects[i]
        local x2,y2,z2 = BANETO_ObjectPosition(object)
        local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
        local serpent_sting = 259491
        local kill_command = 259489
        if x and x2 then
            if distance < radius and not BANETO_HasDebuff("target",serpent_sting) and not BANETO_HasDebuff("target",kill_command) and UnlockedUnitAffectingCombat(object) and not UnitIsPlayer(object) and not UnitIsUnit(object,"pet") and not UnitIsTapDenied(object) then
               bestMob = object
            end
        end
        if i == #objects then
            UnlockedTargetUnit(bestMob)
            BANETO_PrintBambo("TARGETING: SurvivalHunter")
        end
    end
end

