BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY_VALUE = 5
function _G.BANETO_EDITOR_RecordPath()
	if BANETO_EDITOR_GRINDGATHER_RECORDPATH == true then
		local speed,_,_,_ = GetUnitSpeed("player")
		if speed > 0 or BANETO_IsDragonRiding() then
			if not BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY then
				BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY = GetTime()
			end
			if BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY < GetTime() then
				BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY = GetTime() + BANETO_EDITOR_GRINDGATHER_RECORDPATH_DELAY_VALUE
				if Unlocker("EWT") then
					local x,y,z = ObjectPosition("player")
					local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_SPOTRANGE:GetText())
					table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,{x,y,z,radius})
