function _G.BANETO_FindClosestEditorSpot(x,y,z)
    for i = 1,#BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
        local spotX,spotY,spotZ = BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3]
        local d = BANETO_GetDistance3D(x,y,z,spotX,spotY,spotZ)
        if d < 6 then
            return i,"Center"
        end
    end
    for i = 1,#BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
        local spotX,spotY,spotZ = BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3]
        local d = BANETO_GetDistance3D(x,y,z,spotX,spotY,spotZ)
        if d < 6 then
            return i,"Blacklist"
        end
    end
end
WorldFrame:SetScript("OnMouseDown", function(self, button)
    if button == "LeftButton" then
        BANETO_MOUSE_LEFT_IS_DOWN = true
