function _G.BANETO_LastClick()
    if _internal.Software() == "tnk" then
        local Common = Tinkr.Common
        local clickX,clickY,clickZ = Common.ScreenToWorld(GetCursorPosition())
        return clickX,clickY,clickZ
    elseif _internal.Software() == "nn" and not BANETO_IsJin() then
        return LastTerrainClick()
    elseif _internal.Software() == "nn" and BANETO_IsJin() then
        local clickX,clickY,clickZ = Tinkr.ScreenToWorld(GetCursorPosition())
        return clickX,clickY,clickZ
    end
end

function _G.BANETO_EDITOR_RecordClick()
	if BANETO_EDITOR_GRINDGATHER_RECORDCLICK == true then
	    if _internal.Software() == "tnk" then
            clickX,clickY,clickZ = LastClickPosition()
        else
            clickX,clickY,clickZ = LastTerrainClick()
        end
		if clickX ~= 0 then
			if not storedX then
				storedX = clickX
			end
			if storedX ~= clickX then
				local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_SPOTRANGE:GetText())
				table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,{clickX,clickY,clickZ,radius})
				BANETO_PrintSuccess("Recorded Spot (Click)! X: " .. clickX .. " Y:" .. clickY .. " Z:" .. clickZ .. " RADIUS: " .. radius)
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
				storedX = nil
			end
		end
	end
end

function _G.BANETO_EDITOR_RecordTargetPosition()
	if Unlocker("EWT") then
		local x,y,z = ObjectPosition("target")
		local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_SPOTRANGE:GetText())
		if x then
			table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,{x,y,z,radius})
			BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
			BANETO_PrintSuccess("Recorded Spot (Target Location)! X: " .. x .. " Y:" .. y .. " Z:" .. z .. " RADIUS: " .. radius)
		else
			BANETO_PrintError("Select a Target! Spot NOT Recorded!")
		end
	elseif Unlocker("LUA") then
		local x,y,z = BANETO_ObjectPosition("target")
		local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_SPOTRANGE:GetText())
		if x then
			table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,{x,y,z,radius})
			BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
			BANETO_PrintSuccess("Recorded Spot (Target Location)! X: " .. x .. " Y:" .. y .. " Z:" .. z .. " RADIUS: " .. radius)
		else
			BANETO_PrintError("Select a Target! Spot NOT Recorded!")
		end
	end
end

function _G.BANETO_EDITOR_DeleteLastRecordedSpot()
	if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
		table.remove (BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS, #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
		BANETO_PrintSuccess("Deleted last Spot in Storage!")
	else
		BANETO_PrintError("No spots recorded! Can not delete anything.")
	end
end

function _G.BANETO_DeleteLastGlobalBlacklistArea()
	if #BANETO_GLOBAL_BLACKLIST_SPOTS > 0 then
		table.remove (BANETO_GLOBAL_BLACKLIST_SPOTS, #BANETO_GLOBAL_BLACKLIST_SPOTS)
