function _G.BANETO_ObjectName(unit) --not documented
    if unit then
        if unit == "player" or unit == "target" then
            return UnitName(unit)
        end
        local try = ObjectName(unit)
        if not try then
            try = UnitName(unit)
        end
        return try
    end
end


function _G.BANETO_EDITOR_BlacklistTargetId()
    if Unlocker("LUA") and UnitExists("target") then
		local id = BANETO_ObjectId("target")
		if id and id > 0 then
			if BANETO_EDITOR_IsTargetAlreadyBlacklisted(id) then
				BANETO_PrintError("Target ID is already blacklisted!")
			else
				table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS,{id})
				BANETO_PrintSuccess("Recorded Blacklist ID: " .. id .. " (" .. BANETO_ObjectName("target") .. ")")
			end
		else
			BANETO_PrintError("Select a Target! Blacklist ID NOT Recorded!")
		end
	end
end

