function _G.BANETO_EDITOR_IsTargetAlreadyBlacklisted(id)
	for i=1, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS do
		local idInTable = BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS[i][1]
		if idInTable == id then
			return true
		end
	end

end

function _G.BANETO_EDITOR_IsTargetAlreadyQuestTarget(id)
	for i=1, #BANETO_EDITOR_GRINDGATHER_STORAGE_QUESTTARGET_MOBS do
		local idInTable = BANETO_EDITOR_GRINDGATHER_STORAGE_QUESTTARGET_MOBS[i][1]
		if idInTable == id then
			return true
		end
	end

end

StaticPopupDialogs["clearuserlists"] = {
    text = "Do you want to clear this list?",
    button1 = "DELETE",
    button2 = "KEEP",
    OnAccept = function()
       BANETO_ClearUserList(userlisttoclear,true)
    end,
    timeout = 0,
    whileDead = true,
    hideOnEscape = true
}
function _G.BANETO_ClearUserList(listname,force)
    if not force then
        userlisttoclear = listname
        StaticPopup_Show("clearuserlists")
        return
    end
    if listname == "UsageItems" then
        BANETO_SETTING_USAGE_ITEMS = {}
        BANETO_VisualizeUsageList()
    elseif listname == "NeverMail" then
        BANETO_SETTING_MAILING_DONOTMAIL = {}
        BANETO_VisualizeDoNotMailList()
    elseif listname == "AlwaysMail" then
        BANETO_SETTING_MAILING_ALWAYSMAIL = {}
        BANETO_VisualizeAlwaysMailList()
    elseif listname == "Selling" then
        BANETO_SETTING_SELLING_DONOTSELL = {}
        BANETO_VisualizeDoNotSellList()
    elseif listname == "Disenchant" then
        BANETO_SETTING_DISENCHANT_DONOTDISENCHANT = {}
        BANETO_VisualizeDoNotDisenchantList()
    elseif listname == "BlacklistIds" then
        BANETO_GLOBAL_BLACKLIST_MOBS = {}
        BANETO_VisualizeGlobalMobIdBlacklist()
    elseif listname == "DeletingItems" then
        BANETO_SETTING_DELETING_ITEMS = {}
        BANETO_VisualizeDeleteList()
    elseif listname == "StorageItems" then
        BANETO_SETTING_STORE_ITEMS = {}
        BANETO_VisualizeStoreList()
    elseif listname == "CustomWorldObjects" then
        BANETO_GLOBAL_CUSTOM_OBJECTS = {}
        BANETO_VisualizeGlobalObjectList()
    end
    BANETO_SaveSettings()
    local clearedlist = userlisttoclear or listname
    BANETO_PrintSuccess("Cleared list: "..clearedlist)
end

