function _G.BANETO_EDITOR_BlacklistTargetPosition()
    if not UnitExists("target") then
        BANETO_PrintError("Please select a target first before adding blacklist areas to your editor profile!")
        return false
    end
	if Unlocker("EWT") then
		local x,y,z = ObjectPosition("target")
		local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_BLACKLISTRANGE:GetText())
		if radius > 0 then
			table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS,{x,y,z,radius})
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
			BANETO_PrintSuccess("Blacklisted Spot (Target Location)! X: " .. x .. " Y:" .. y .. " Z:" .. z .. " RADIUS: " .. radius)
		else
			BANETO_PrintError("Please adjust the Blacklist Radius before recording blacklist spots. Spot not recorded!")
		end
	elseif Unlocker("LUA") then
		local x,y,z = BANETO_ObjectPosition("target")
		local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_BLACKLISTRANGE:GetText())
		if radius > 0 then
			table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS,{x,y,z,radius})
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
			BANETO_PrintSuccess("Blacklisted Spot (Target Location)! X: " .. x .. " Y:" .. y .. " Z:" .. z .. " RADIUS: " .. radius)
		else
			BANETO_PrintError("Please adjust the Blacklist Radius before recording blacklist spots. Spot not recorded!")
		end
	end
end

