function _G.BANETO_EDITOR_DeleteLastRecordedBlacklistArea()
	if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
		table.remove (BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
		BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
		BANETO_PrintSuccess("Deleted last Spot in Storage!")
	else
		BANETO_PrintError("No spots recorded! Can not delete anything.")
	end
end

function _G.BANETO_PrepareEwtRelogger(username,password,realm,charnumber,loginacc)
	if not BANETO_EWTRELOGPREPARED and Unlocker("EWT") then
		SetSessionVariable('loginName', username)
		SetSessionVariable('loginPw', password)

		SetSessionVariable('loginRealm', realm)
		SetSessionVariable('loginChar', charnumber)
		if loginacc then
            SetSessionVariable('loginAcc', loginacc)
        end
		BANETO_EWTRELOGPREPARED = true
		BANETO_EWT_RELOGGER = true
		BANETO_PrintSuccess("Relog data procedure initialized!")
	end

end

function _G.BANETO_EDITOR_GRINDGATHER_SaveProfile()
	if Unlocker("LUA") then
		local profilename = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:GetText()
		if profilename ~= "" then
			if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
				WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","BANETO_DefineProfileName('"..profilename.."')" ,false)
				if BANETO_SUB_FRAME_TOOLS_ISFISHINGPROFILE and BANETO_SUB_FRAME_TOOLS_ISFISHINGPROFILE:GetChecked() then
				    WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineProfileType('Fishing')" ,true)
                else
				    WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineProfileType('Grinding')" ,true)
				end
                if BANETO_SUB_FRAME_TOOLS_INCLUDEZELEVATION and BANETO_SUB_FRAME_TOOLS_INCLUDEZELEVATION:GetChecked() then
                    WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\n_G.BANETO_DRAGONRIDING_ZOFFSET = 20" ,true)
                end
				for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineCenter(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL > 0 then
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineSellVendor(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL[1][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR > 0 then
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineRepairVendor(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR[1][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO > 0 then
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineAmmoVendor(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO[1][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS > 0 then
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineGoodsVendor(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS[1][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
					for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
						WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineBlacklist(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][4] .. ")" ,true)
					end
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS > 0 then
					for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS do
						WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBlacklistID(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS[i][1] .. ")" ,true)
					end
				end
				local continent = BANETO_GetMapId()
				WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineProfileContinent(" ..continent .. ")" ,true)

				local nextProfilename = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_NEXTPROFILENAME:GetText()
				local nextProfileLevel = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_NEXTPROFILELEVEL:GetText()
				if nextProfilename and nextProfilename ~= "" and nextProfilename ~= nil and nextProfileLevel and nextProfileLevel ~= nil and nextProfileLevel ~= "" then
					WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_SetNextLocalProfile([[" ..nextProfilename .. "]]," .. nextProfileLevel .. ")" ,true)
				end
                if BANETO_SUB_FRAME_TOOLS_INCLUDEUNSTUCKS and BANETO_SUB_FRAME_TOOLS_INCLUDEUNSTUCKS:GetChecked() then
                 if BANETO_UNSTUCK_ROUTES_TABLE then
                     for i=1, #BANETO_UNSTUCK_ROUTES_TABLE do
                         local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
                         for z=1, #cacheTable do
                             if Unlocker("LUA") then
                                 WriteFile(baneto_path_scripts_profiles.. profilename .. ".lua","\nBANETO_DefineProfileUnstuck("..i..","..cacheTable[z][1]..","..cacheTable[z][2]..","..cacheTable[z][3]..")",true)
                             end
                         end
                     end
                 end
                end
				BANETO_PrintSuccess("Saved profile to BANETO/Profiles/" .. profilename .. ".lua")
			else
				BANETO_PrintError("Record at least one Spot!")
			end
		else
			BANETO_PrintError("Set a profile name before saving!")
		end
	end
end

function _G.BANETO_EDITOR_QUESTER_SaveProfile()
	if Unlocker("LUA") then
		local profilename = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:GetText()
		if profilename ~= "" then
			if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
				WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","BANETO_DefineProfileName('"..profilename.."')" ,false)
				WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineProfileType('Questing')" ,true)
				for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineCenter(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][4] .. ")" ,true)
				end
                if BANETO_SUB_FRAME_TOOLS_INCLUDEZELEVATION and BANETO_SUB_FRAME_TOOLS_INCLUDEZELEVATION:GetChecked() then
                    WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\n_G.BANETO_DRAGONRIDING_ZOFFSET = 20" ,true)
                end
                if BANETO_SUB_FRAME_TOOLS_SKIPPULSE and BANETO_SUB_FRAME_TOOLS_SKIPPULSE:GetChecked() then
                    WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_SetToSkipPulseQuest()" ,true)
                end
                if BANETO_SUB_FRAME_TOOLS_SKIPTURNIN and BANETO_SUB_FRAME_TOOLS_SKIPTURNIN:GetChecked() then
                    WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_SetToSkipTurnInQuest()" ,true)
                end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_PICKUP > 0 then
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestPickupNPC(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_PICKUP[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_PICKUP[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_PICKUP[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_PICKUP[1][4] .. ")" ,true)
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_TURNIN > 0 then
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestTurninNPC(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_TURNIN[1][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_TURNIN[1][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_TURNIN[1][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_TURNIN[1][4] .. ")" ,true)
				end

				if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
					for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
						WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineBlacklist(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3] .. "," .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][4] .. ")" ,true)
					end
				end
				if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS > 0 then
					for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS do
						WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBlacklistID(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS[i][1] .. ")" ,true)
					end
				end

				if #BANETO_EDITOR_GRINDGATHER_STORAGE_QUESTTARGET_MOBS > 0 then
					for i = 1, #BANETO_EDITOR_GRINDGATHER_STORAGE_QUESTTARGET_MOBS do
						WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestTargetId(" .. BANETO_EDITOR_GRINDGATHER_STORAGE_QUESTTARGET_MOBS[i][1] .. ")" ,true)
					end
				end

				local currentQuestType = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_QUESTTYPE:GetText()
				WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestStepType([[" ..currentQuestType .. "]])" ,true)
				if currentQuestType ~= "GrindTo" then
					local questId = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID:GetText()
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestId(" ..questId .. ")" ,true)
				else
					local questId = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID:GetText()
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineGrindToLevelValue(" ..questId .. ")" ,true)
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineQuestId(" ..99999 .. ")" ,true)
				end



				local nextProfilename = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_NEXTPROFILENAME:GetText()
				if nextProfilename and nextProfilename ~= "" and nextProfilename ~= nil then
					WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_SetNextLocalQuestProfile([[" ..nextProfilename .. "]])" ,true)
				end
                if BANETO_SUB_FRAME_TOOLS_INCLUDEUNSTUCKS and BANETO_SUB_FRAME_TOOLS_INCLUDEUNSTUCKS:GetChecked() then
                    if BANETO_UNSTUCK_ROUTES_TABLE then
                        for i=1, #BANETO_UNSTUCK_ROUTES_TABLE do
                            local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
                            for z=1, #cacheTable do
                                if Unlocker("LUA") then
                                    WriteFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua","\nBANETO_DefineProfileUnstuck("..i..","..cacheTable[z][1]..","..cacheTable[z][2]..","..cacheTable[z][3]..")",true)
                                end
                            end
                        end
                    end
                end
				BANETO_PrintSuccess("Saved profile to BANETO/Profiles/Quests/" .. profilename .. ".lua")
			else
				BANETO_PrintError("Record at least one Spot!")
			end
		else
			BANETO_PrintError("Set a profile name before saving!")
		end
	end
end

function _G.BANETO_EDITOR_GRINDGATHER_LoadProfile()
	if Unlocker("LUA") then
		local name = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:GetText()
		if name ~= "" then
			local content = ReadFile(baneto_path_scripts_profiles.. name .. ".lua")
			if content then
                if string.find(content, "BANETO_DefineProfileType%('Dungeon'%)") or string.find(content, "BANETO_ExecuteCustom") or string.find(content, "_G.BANETO_ExecuteCustom")  then
                    BANETO_PrintError("Editing custom profiles is not possible ingame. Use notepad++ and edit the file.")
                    return
                end
			    if _internal.Software() == "tnk" then
				    Eval(content,"profileeditor")
                else
                    local load = loadstring(content,"")
                    --load()
                    RunScript(content)
                end

				--[[ RESTORE NAME --]]
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:SetText(name)

				--[[ RESTORE CENTERS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS = BANETO_DEFINED_CENTERS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)

				--[[ RESTORE NPCS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL = _G.BANETO_DEFINED_VENDOR_SELL
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR = _G.BANETO_DEFINED_VENDOR_REPAIR
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS = _G.BANETO_DEFINED_VENDOR_GOODS
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO = _G.BANETO_DEFINED_VENDOR_AMMO

				--[[ RESTORE BLACKLISTS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS = BANETO_DEFINED_BLACKLIST_SPOTS
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS = BANETO_DEFINED_BLACKLIST_MOBS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
				BANETO_MAINTEXTS_PROFILE:SetText("#ACACAC Profile selected!")
				BANETO_ClearProfileData()
				BANETO_PrintSuccess("Profile " .. name .. " ready for editing! Remember to save changes!")
                BANETO_EDITOR_MOVE_spotIndex = nil
                BANETO_EDITOR_MOVE_spotType = nil
			else
				BANETO_PrintError("Profile with name " .. name .. " not found in Baneto/Profiles/ !")
			end
		else
			BANETO_PrintError("Enter the name of the profile to load/edit!")
		end

	elseif Unlocker("LUA") and lb then
		local name = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:GetText()
		if name ~= "" then
			local content = __LB__.ReadFile("Interface/Addons/Baneto/Profiles/"..name..".lua")
			if content then
				__LB__.RunString(content)

				--[[ RESTORE NAME --]]
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:SetText(name)

				--[[ RESTORE CENTERS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS = BANETO_DEFINED_CENTERS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)

				--[[ RESTORE NPCS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL = _G.BANETO_DEFINED_VENDOR_SELL
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR = _G.BANETO_DEFINED_VENDOR_REPAIR
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS = _G.BANETO_DEFINED_VENDOR_GOODS
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO = _G.BANETO_DEFINED_VENDOR_AMMO

				--[[ RESTORE BLACKLISTS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS = BANETO_DEFINED_BLACKLIST_SPOTS
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS = BANETO_DEFINED_BLACKLIST_MOBS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
				BANETO_MAINTEXTS_PROFILE:SetText("#ACACAC Profile selected!")
				BANETO_ClearProfileData()
				BANETO_PrintSuccess("Profile " .. name .. " ready for editing! Remember to save changes!")
			else
				BANETO_PrintError("Profile with name " .. name .. " not found in Baneto/Profiles/ !")
			end
		else
			BANETO_PrintError("Enter the name of the profile to load/edit!")
		end
    elseif Unlocker("LUA") and CallSecureFunction then
		local name = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:GetText()
		if name ~= "" then
			local content = ReadFile(lbslpath..[[Profiles\\]].. name..".lua")
			if content then


				--[[ RESTORE NAME --]]
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_PROFILENAME:SetText(name)

				--[[ RESTORE CENTERS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS = BANETO_DEFINED_CENTERS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)

				--[[ RESTORE NPCS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_SELL = _G.BANETO_DEFINED_VENDOR_SELL
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_REPAIR = _G.BANETO_DEFINED_VENDOR_REPAIR
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_GOODS = _G.BANETO_DEFINED_VENDOR_GOODS
				BANETO_EDITOR_GRINDGATHER_STORAGE_VENDOR_AMMO = _G.BANETO_DEFINED_VENDOR_AMMO

				--[[ RESTORE BLACKLISTS --]]
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS = BANETO_DEFINED_BLACKLIST_SPOTS
				BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_MOBS = BANETO_DEFINED_BLACKLIST_MOBS
				BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
				BANETO_MAINTEXTS_PROFILE:SetText("#ACACAC Profile selected!")
				BANETO_ClearProfileData()
				BANETO_PrintSuccess("Profile " .. name .. " ready for editing! Remember to save changes!")
			else
				BANETO_PrintError("Profile with name " .. name .. " not found in Baneto/Profiles/ !")
			end
		else
			BANETO_PrintError("Enter the name of the profile to load/edit!")
		end
	end

end

