function _G.BANETO_WhyNotSkin(unit)
    print("SKIN CHECK DEBUG - CURRENT STATE: " .. BANETO_State)
    local id = lb.ObjectId(unit)
    print("here are the results for object with id: " .. id)
    local guid = UnitGUID(unit)
    if BANETO_IsGuidContainedInGuidSkinnedlist(guid) then
        print("match on: skinned list")
    end
    if BANETO_IsGuidContainedInGuidBlacklist(guid) then
        print("match on: guid black list")
    end
    if __LB__.UnitHasFlag(unit,67108864) then
        print("match on: skinning flag")
    end
    if IsUnitBlacklisted(unit) then
        print("match on: general blacklist")
    end
    if BANETO_IsUnitOnMesh(unit) then
        print("match on: mesh check")
    end
end

