function _G.BANETO_LoadPluginYtthack()
    local _,_,class = UnitClass("player")
    if class ~= 11 then
        return false
    end
    if BANETO_Customer() == "djannmafonse2" or BANETO_Customer() == "joshgooni" or BANETO_Customer() == "gaus132435"  or BANETO_Customer() == "clever_xd" then
        BANETO_PrintState("Ytthack - NoStopPulling - Init!")
        BANETO_PrintState("Ytthack - NoStopPulling - Druid Rotation Hook!")
        BANETO_YTT = true
        function _G.BANETO_RETAIL_LVL_ROTATION()
            local dotMoon = 326646
            local dotSun = 164815
            local astral = 191034
            local furyElune = 202770
            local celestialAlign = 194223
            BANETO_MultidottingRetail("druidbalance")
            if BANETO_IsSpellUsable(dotMoon) and BANETO_IsSpellKnown(dotMoon) and not BANETO_HasDebuff("target",dotMoon) then
                BANETO_CastSpell(dotMoon)
            elseif BANETO_IsSpellUsable(dotSun) and BANETO_IsSpellKnown(dotSun) and not BANETO_HasDebuff("target",dotSun) then
                BANETO_CastSpell(dotSun)
            elseif BANETO_IsSpellUsable(celestialAlign) and BANETO_IsSpellKnown(celestialAlign) and not BANETO_IsSpellOnCooldown(celestialAlign) and not BANETO_HasBuff("player",celestialAlign) then
                BANETO_CastSpell(celestialAlign)
            elseif BANETO_IsSpellUsable(furyElune) and BANETO_IsSpellKnown(furyElune) and not BANETO_IsSpellOnCooldown(furyElune) then
                BANETO_CastSpell(furyElune)
            elseif BANETO_IsSpellUsable(astral) and BANETO_IsSpellKnown(astral) and not BANETO_IsSpellOnCooldown(astral) and not BANETO_HasBuff("player",astral) and UnitPower("player",8) >= 50 then
                BANETO_CastSpell(astral)
            end
        end
    else
        BANETO_PrintError("You are not authorized for this plugin! (Ytthack NoStopPulling)")
    end
end

