function _G.BANETO_HowManyBagsAreEquipped()
    local bagCount = 0
    for i = 0, NUM_BAG_SLOTS do
        if GetContainerNumSlots(i) and GetContainerNumSlots(i) > 0 then
            bagCount = bagCount + 1
        end
    end
    return bagCount-1
end
function _G.BANETO_DeleteItem(itemid)
    local shouldDelete = true
	if Unlocker("LUA") then
		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				local id = GetContainerItemID(i, z)
				if id then
					if id == itemid and shouldDelete == true then
					    shouldDelete = false
					    if _internal.Software() == "tnk" then
                            Eval("PickupContainerItem(".. i .. "," .. z .. ")","smoth")
                            Eval("DeleteCursorItem()","smoth")
						end
                        if _internal.Software() == "nn" then
                            Unlock("PickupContainerItem",i,z)
                            Unlock("DeleteCursorItem","")
                        end
                    end
				end
			end
		end
	end
end
_G.BANETO_CUSTOM_ITEM_USAGE_DELAY = 3600
function _G.BANETO_CustomUsageItems()
    if not BANETO_CUSTOM_ITEM_USAGE_TABLE then
        BANETO_CUSTOM_ITEM_USAGE_TABLE = {}
    end
	if Unlocker("LUA") and not MerchantFrame:IsVisible() then
		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				local id = GetContainerItemID(i, z)
				if id then
					local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
						  itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
						  isCraftingReagent = GetItemInfo(id)
                    local startTime, durationTimerCustom, enable = GetItemCooldown(id)
                    if itemName and (not BANETO_CUSTOM_ITEM_USAGE_TABLE[itemName] or BANETO_CUSTOM_ITEM_USAGE_TABLE[itemName] < GetTime()) and BANETO_IsItemInUsageList(itemName) and durationTimerCustom and durationTimerCustom == 0 then
                        BANETO_UseItem(id)
                        BANETO_PrintState("Custom item usage: "..itemName)
                        BANETO_CUSTOM_ITEM_USAGE_TABLE[itemName] = GetTime()+_G.BANETO_CUSTOM_ITEM_USAGE_DELAY
                    end
				end
			end
		end
	end
end
function _G.BANETO_DeleteCursorItem()
    if _internal.Software() == "tnk" then
