function _G.BANETO_GetPointInfrontOfVectorWithDistanceAndAngle(distance,x,y,z,angle)
    if Unlocker("LUA") then
        local facing = angle
        if facing then
            if 0 < facing and facing <= math.pi/2 then
                local alpha = (90-(facing/(math.pi/2))*90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi/2 < facing and facing <= math.pi then
                local alpha = ((facing/(math.pi))*180-90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi < facing and facing <= 3*math.pi/2 then
                local alpha = (270-(facing/(3*math.pi/2))*270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y - b
                return xNew,yNew,z
            elseif 3*math.pi/2 < facing and facing <= 2*math.pi then
                local alpha = ((facing/(2*math.pi))*360-270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y - b
                return xNew,yNew,z
            end
        end
    end
end

