function _G.BANETO_SlopeJumper()
    if not baneto_SlopeJumperDelay or baneto_SlopeJumperDelay < GetTime() then
        baneto_SlopeJumperDelay = GetTime()
        xSlope,ySlope,zSlope = BANETO_GetPointInfrontOfUsWithDistance(2)
        xSlope2,ySlope2,zSlope2 = BANETO_GetPointInfrontOfUsWithDistance(3)
        local speed = BANETO_GetUnitSpeed("player")
        local destination = BANETO_GetLuaBoxDestination()
        if destination and destination[1] and destination[2] and destination[3] and not _G.BANETO_BLOCK_SLOPE_JUMPS and not BANETO_IsDragonRiding() and not IsSwimming() and not IsFlying() and not IsFalling() and not BANETO_UNSTUCK_ROUTE_ISACTIVE then
            local destX,destY,destZ =  destination[1], destination[2], destination[3]
            local x1,y1,z1 = BANETO_ObjectPosition("player")
            local distance = BANETO_GetDistance3D(destX,destY,destZ,x1,y1,z1)
            if Unlocker("LUA") and distance and distance > 9 and xSlope and ySlope and zSlope and xSlope2 and ySlope2 and zSlope2 and speed and speed > 0  then
                zSlope = zSlope+0.9
                zSlope2 = zSlope2+3
                local x1,y1,z1 = BANETO_ObjectPosition("player")
                local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+0.9, xSlope,ySlope,zSlope, hitFlags)
                local xH2, yH2, zH2 = BANETO_TraceLine(x1, y1, z1+3, xSlope2,ySlope2,zSlope2, hitFlags)
                if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 and ((not xH2 or xH2 == 0) and (not yH2 or yH2 == 0)  and (not zH2 or zH2 == 0)) then
                    BANETO_PrintState("Obstacle infront? Slope Jump!")
                    SWITCHING_GROUND_TO_FLYING = 0
                    BANETO_JumpOrAscendStart()
                    baneto_SlopeJumperDelay = GetTime()+20
                    if IsIndoors() then
                        baneto_SlopeJumperDelay = GetTime()+25
                    end
                end
            end
        end
    end
end
