function _G.BANETO_GetAllPlayerTalents()
    local playerTalents = {}

    for tabIndex = 1, GetNumSpecializations() do
        for talentIndex = 1, GetNumTalents(tabIndex) do
            local name, _, _, _, selected, _, spellID = GetTalentInfo(tabIndex, talentIndex)
            if selected then
                table.insert(playerTalents, {name = name, spellID = spellID})
            end
        end
    end

    return playerTalents
end


function _G.BANETO_PlayerHasTalent(talentName)
    local playerTalents = BANETO_GetAllPlayerTalents()

    for _, talent in ipairs(playerTalents) do
        if talent.name == talentName then
            return true
        end
    end

    return false
end

