function _G.BANETO_CheckNinjaSwarm()
    if BANETO_SETTING_ANTININJAGATHER and BANETO_SETTING_ANTININJAGATHER == true and BANETO_TARGET then
        local id = BANETO_ObjectId(BANETO_TARGET)
        if id and BANETO_IsFishingSwarm(id) and not UnitCastingInfo("player") then
            for i = 1,#BANETO_OBJTS_TKR_ONLYPLAYERS do
                local playerIter = BANETO_OBJTS_TKR_ONLYPLAYERS[i]
                local distance = GetDistanceBetweenObjects(playerIter,BANETO_TARGET)
                if distance and distance < 25  and not UnitOnTaxi(playerIter) and distance ~= 0 and playerIter ~= BANETO_Object("player") and UnitGUID(playerIter) and BANETO_ObjectName(playerIter) ~= "" and BANETO_ObjectName(playerIter) ~= " " then
                    local nameA = BANETO_ObjectName(playerIter) or "playerName"
                    local nameB = BANETO_ObjectName(BANETO_TARGET) or "nodeName"
                    if nameA and nameA ~= "Unknown" then
                        BANETO_PrintState("Ninja swarm node detected, if this is wrong, please report in discord: ".. nameB .. " " .. nameA .. " distance: ".. distance)
                        return true
                    end
                end
            end
        end
    end
end

function _G.BANETO_CheckNinjaGather()
    if BANETO_SETTING_ANTININJAGATHER and BANETO_SETTING_ANTININJAGATHER == true and BANETO_TARGET then
        local id = BANETO_ObjectId(BANETO_TARGET)
        if id and BANETO_IsGatheringNode(id) and not UnitCastingInfo("player") then
            for i = 1,#BANETO_OBJTS_TKR_ONLYPLAYERS do
                local playerIter = BANETO_OBJTS_TKR_ONLYPLAYERS[i]
                local distance = GetDistanceBetweenObjects(playerIter,BANETO_TARGET)
                if distance and distance < 6 and distance ~= 0 and not UnitOnTaxi(playerIter) and playerIter ~= BANETO_Object("player") and UnitGUID(playerIter) and BANETO_ObjectName(playerIter) ~= "" and BANETO_ObjectName(playerIter) ~= " " then
                    local nameA = BANETO_ObjectName(playerIter) or "playerName"
                    local nameB = BANETO_ObjectName(BANETO_TARGET) or "nodeName"
                    if nameA and nameA ~= "Unknown" then
                        BANETO_PrintState("Ninja node detected, if this is wrong, please report in discord: ".. nameB .. " " .. nameA .. " distance: ".. distance)
                        return true
                    end
                end
            end
        end
    end
end

