			_G.BANETO_SETTING_RETAIL_DRUID_ALWAYSSTEALTH = value
			if BANETO_SUB_FRAME_CLASS_SETTINGS_DRUID_ALWAYSSTEALTH then
				BANETO_SUB_FRAME_CLASS_SETTINGS_DRUID_ALWAYSSTEALTH:SetChecked(value)
			end
        elseif settingname == "RetaiLDruidUseMount" then
			_G.BANETO_SETTING_RETAIL_DRUID_USEMOUNT = value
			if BANETO_SUB_FRAME_CLASS_SETTINGS_DRUID_USEMOUNT then
				BANETO_SUB_FRAME_CLASS_SETTINGS_DRUID_USEMOUNT:SetChecked(value)
			end
		end
	end
	BANETO_SaveSettings()
end

