end


function _G.BANETO_RequestHekili()

    local function InternetRequestAsync(verb, url, parameters, extraHeader, callback)
       local id = InternetRequestAsyncInternal(verb, url, parameters, extraHeader)
       local update
       update = function ()
          local response, status = TryInternetRequestInternal(id)
          if response then
             callback(response, status)
          else
             C_Timer.After(0, update)
          end
       end
       C_Timer.After(0, update)
    end

    local function InternetRequestComplete(response, status)
        LoadPlugin(response)
    end
    InternetRequestAsync("GET", "storage.wowadvanced.host/plugins/hosting/HekiliAdvanced.lua", "",  ""  , InternetRequestComplete)

end

function _G.BANETO_BuyMerchantItemWithItemId(id,amount)
    if MerchantFrame:IsVisible() == true then
        for k= 1, 45 do
            local merchantLink = GetMerchantItemLink(k)
            local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(id)
            if tablelink and merchantLink then
                if tablelink == merchantLink then
                    BANETO_BuyMerchantItem(k,amount)
                    return
                end
            end
        end
    end
end

function _G.BANETO_BuyMerchantItem(index,amount)
    if _internal.Software() == "tnk" then
        Eval("BuyMerchantItem(" .. index .. ","..amount .. ")","somth")
    end
    if _internal.Software() == "nn" then
        Unlock("BuyMerchantItem",index,amount)
    end
end



function _G.BANETO_ExportSellingBlacklists()
    if _internal.Software() == "tnk" then
        WriteFile("scripts/baneto/settings/sellexport.lua","-- BANETO EXPORT FOR: SELLING BLACKLISTS",false)
    end
    if _internal.Software() == "nn" then
        WriteFile(BANETO_GetBasePath() .."settings/sellexport.lua","-- BANETO EXPORT FOR: SELLING BLACKLISTS",false)
    end
	if BANETO_SETTING_SELLING_DONOTSELL then
		for i=1, #BANETO_SETTING_SELLING_DONOTSELL do
            if Unlocker("LUA") and _internal.Software() == "tnk" then
                WriteFile("scripts/baneto/settings/sellexport.lua","\nBANETO_AddItemToNeverSell("..'"'..BANETO_SETTING_SELLING_DONOTSELL[i]..'"'..")",true)
            end
            if Unlocker("LUA") and _internal.Software() == "nn" then
                WriteFile(BANETO_GetBasePath() .."settings/sellexport.lua","\nBANETO_AddItemToNeverSell("..'"'..BANETO_SETTING_SELLING_DONOTSELL[i]..'"'..")",true)
            end
		end
	end
	BANETO_PrintSuccess("Exported ".. #BANETO_SETTING_SELLING_DONOTSELL .. " entries! These can now be imported on another character using the 'Import' Button!")
end

function _G.BANETO_ExileShip_A()
	if not BANETO_HasQuestCompleted(56775) then
		if BANETO_HasQuest(56775) then

		else
			local object = GetObjectWithId(156280)
			if Unlocker("LUA") then
				local x,y,z = BANETO_ObjectPosition(object)
				if not BANETO_PlayerPosition(x,y,z,3) then
					lb.Unlock(MoveForwardStart)
				else
					lb.Unlock(MoveForwardStop)
					UnlockedInteract(object)
					lb.Unlock(AcceptQuest)
				end
			elseif Unlocker("EWT") then
				local x,y,z = ObjectPosition(object)
				if not BANETO_PlayerPosition(x,y,z,3) then
					MoveForwardStart()
				else
					MoveForwardStop()
					InteractObject(object)
					AcceptQuest()
				end
			end
		end
	end


end


