function _G.BANETO_ExportUnstuckRoutes()
	if BANETO_UNSTUCK_ROUTES_TABLE then
        if _internal.Software() == "tnk" then
            WriteFile("scripts/baneto/settings/unstucksexport.lua","-- BANETO EXPORT FOR: UNSTUCK ROUTES! Do not copy into your settings files! The only way to use this is the Import button ingame.",false)
        end
        if _internal.Software() == "nn" then
            WriteFile(BANETO_GetBasePath() .."settings/unstucksexport.lua","-- BANETO EXPORT FOR: UNSTUCK ROUTES! Do not copy into your settings files! The only way to use this is the Import button ingame.",false)
        end
		for i=1, #BANETO_UNSTUCK_ROUTES_TABLE do
		    --BANETO_PrintBambo(BANETO_UNSTUCK_ROUTES_TABLE[i][1])
		    local route = BANETO_UNSTUCK_ROUTES_TABLE[i]
		    for q=1,#route do
		        local routeTriggerRadius = route[q][4] or 5
                if Unlocker("LUA") and _internal.Software() == "tnk" then
                    WriteFile("scripts/baneto/settings/unstucksexport.lua","\nBANETO_ImportUnstuckRoute("..i..","..route[q][1] .."," ..route[q][2] .. "," ..route[q][3].. "," .. routeTriggerRadius..")",true)
                end
                if Unlocker("LUA") and _internal.Software() == "nn" then
                    WriteFile(BANETO_GetBasePath() .."settings/unstucksexport.lua","\nBANETO_ImportUnstuckRoute("..i..","..route[q][1] .."," ..route[q][2] .. "," ..route[q][3].. "," ..routeTriggerRadius ..")",true)
                end
            end
		end
	end
	if BANETO_UNSTUCK_ROUTES_TABLE and #BANETO_UNSTUCK_ROUTES_TABLE then
	    BANETO_PrintSuccess("Exported ".. #BANETO_UNSTUCK_ROUTES_TABLE .. " entries! These can now be imported on another character using the 'Import' Button!")
	else
	    BANETO_PrintError("No unstuck routes available that could be exported!")
	end
end

function _G.BANETO_ImportUnstuckRoutes()
    if not BANETO_ISRUNNING and not BANETO_RECORDING_UNSTUCKROUTE then
        if _internal.Software() == "tnk" then
            loadedContent = ReadFile("scripts/baneto/settings/unstucksexport.lua")
        end
        if _internal.Software() == "nn" then
            loadedContent = ReadFile(BANETO_GetBasePath() .."settings/unstucksexport.lua")
        end
        if loadedContent then
            if _internal.Software() == "tnk" then
                Eval(loadedContent,"importer")
            elseif _internal.Software() == "nn" then
                --local load = loadstring(loadedContent)
                --load()
                RunScript(loadedContent)
            end
            BANETO_PrintSuccess("Imported your unstuck routes! Now a total of: " .. #BANETO_UNSTUCK_ROUTES_TABLE .. " entries.")
            numRoutesLastImport = nil
            numRoutesLastIndex = nil
            BANETO_SaveSettings()
        else
            BANETO_PrintError("No data found that can be imported!")
        end
    else
        BANETO_PrintError("Stop the tool and do not record any unstuck paths before importing.")
	end
end

function _G.BANETO_ImportUnstuckRoute(index,x,y,z,radiusTrigger)
    if not IMPORTING_ROUTES_DELAY or IMPORTING_ROUTES_DELAY < GetTime() then
        BANETO_UNSTUCK_ROUTES_TABLE = {}
        IMPORTING_ROUTES_DELAY = GetTime()+0.2
    end
    BANETO_DefineUnstuck(index,x,y,z,radiusTrigger)
end

