BANETO_SETTING_LANDINGSPOTS={}
function _G.BANETO_RecordLandingspot(x,y,z,map)
    --check 20 yards around this spot for existing landingspots
    for i = 1, #BANETO_SETTING_LANDINGSPOTS do
        local xX,yY,zZ,mapMap = BANETO_SETTING_LANDINGSPOTS[i][1],BANETO_SETTING_LANDINGSPOTS[i][2],BANETO_SETTING_LANDINGSPOTS[i][3],BANETO_SETTING_LANDINGSPOTS[i][4]
        local dist = BANETO_GetDistance3D(x,y,z,xX,yY,zZ)
        if mapMap and map and mapMap == map and dist and 20 > dist then
            return false
        end
    end
    table.insert(BANETO_SETTING_LANDINGSPOTS,{x,y,z,map})
    BANETO_SaveSettings()
end

BANETO_SETTING_LANDINGSPOTS_PROFILE={}
function _G.BANETO_RecordProfileLandingspot(x,y,z,map)
    --check 20 yards around this spot for existing landingspots
    for i = 1, #BANETO_SETTING_LANDINGSPOTS_PROFILE do
        local xX,yY,zZ,mapMap = BANETO_SETTING_LANDINGSPOTS_PROFILE[i][1],BANETO_SETTING_LANDINGSPOTS_PROFILE[i][2],BANETO_SETTING_LANDINGSPOTS_PROFILE[i][3],BANETO_SETTING_LANDINGSPOTS_PROFILE[i][4]
        local dist = BANETO_GetDistance3D(x,y,z,xX,yY,zZ)
        if mapMap and map and mapMap == map and dist and 20 > dist then
            return false
        end
    end
    table.insert(BANETO_SETTING_LANDINGSPOTS_PROFILE,{x,y,z,map})
    BANETO_SaveSettings()
end

function _G.BANETO_DeleteClosestLandingspot()
    local bestDistance = 99999999
    local bestIndex;
    local currentmap = BANETO_GetMapId()
    local xp,yp,zp = BANETO_ObjectPosition("player")
    for i = 1, #BANETO_SETTING_LANDINGSPOTS do
        local x,y,z,map = BANETO_SETTING_LANDINGSPOTS[i][1],BANETO_SETTING_LANDINGSPOTS[i][2],BANETO_SETTING_LANDINGSPOTS[i][3],BANETO_SETTING_LANDINGSPOTS[i][4]
        if map == currentmap then
            local d = BANETO_GetDistance3D(xp,yp,zp,x,y,z)
            if d and d < bestDistance then
                bestDistance = d
                bestIndex = i
            end
        end
    end
    if bestIndex then
        BANETO_PrintSuccess("Deleted landing spot.")
        table.remove(BANETO_SETTING_LANDINGSPOTS,bestIndex)
        BANETO_SaveSettings()
    else
        BANETO_PrintError("No landing spots in storage.")
    end
end


function _G.BANETO_ExportLandingSpots()
    if _internal.Software() == "tnk" then
        WriteFile("scripts/baneto/settings/landingexport.lua","-- BANETO EXPORT FOR: LANDINGSPOTS",false)
    end
    if _internal.Software() == "nn" then
        WriteFile(BANETO_GetBasePath() .."settings/landingexport.lua","-- BANETO EXPORT FOR: LANDINGSPOTS",false)
    end
	if BANETO_SETTING_LANDINGSPOTS then
		for i=1, #BANETO_SETTING_LANDINGSPOTS do
            if Unlocker("LUA") and _internal.Software() == "tnk" then
                WriteFile(BANETO_GetBasePath() .."settings/landingexport.lua","\nBANETO_RecordLandingspot("..BANETO_SETTING_LANDINGSPOTS[i][1] .. "," .. BANETO_SETTING_LANDINGSPOTS[i][2].. "," ..BANETO_SETTING_LANDINGSPOTS[i][3].. "," ..BANETO_SETTING_LANDINGSPOTS[i][4]..")",true)
            end
            if Unlocker("LUA") and _internal.Software() == "nn" then
                WriteFile(BANETO_GetBasePath() .."settings/landingexport.lua","\nBANETO_RecordLandingspot("..BANETO_SETTING_LANDINGSPOTS[i][1] .. "," .. BANETO_SETTING_LANDINGSPOTS[i][2].. "," ..BANETO_SETTING_LANDINGSPOTS[i][3].. "," ..BANETO_SETTING_LANDINGSPOTS[i][4]..")",true)
            end
		end
	end
	BANETO_PrintSuccess("Exported ".. #BANETO_SETTING_LANDINGSPOTS .. " entries! These can now be imported on another character using the 'Import' Button!")
end

function _G.BANETO_ImportLandingSpots()
    if _internal.Software() == "tnk" then
        loadedContent = ReadFile("scripts/baneto/settings/landingexport.lua")
    end
    if _internal.Software() == "nn" then
        loadedContent = ReadFile(BANETO_GetBasePath() .."settings/landingexport.lua")
    end
	if loadedContent then
		if _internal.Software() == "tnk" then
			Eval(loadedContent,"importer")
	    elseif _internal.Software() == "nn" then
	        --local load = loadstring(loadedContent)
	        --load()
            RunScript(loadedContent)
		end
		BANETO_PrintSuccess("Imported your landing list. Now a total of: " .. #BANETO_SETTING_LANDINGSPOTS .. " entries.")
	else
		BANETO_PrintError("No data found that can be imported!")
	end
end

