	if not corruptionCheck1 or corruptionCheck1 == "" or corruptionCheck1 == nil then
		return true
	end
end

function _G.BANETO_CheckHomeMailbox()
    if (BANETO_SETTING_MAILBOX_X and BANETO_SETTING_MAILBOX_X ~= 0) or (BANETO_SETTING_MAILBOX_Y and BANETO_SETTING_MAILBOX_Y ~= 0) or (BANETO_SETTING_MAILBOX_Z and BANETO_SETTING_MAILBOX_Z ~= 0) then
        if BANETO_SETTING_MAILBOX_ID and BANETO_SETTING_MAILBOX_ID ~= 0 then
            return true
        end
    end
end

function _G.BANETO_GetMyMaster()
    if Unlocker("LUA") then
        local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
        t = {}
        for i = 1,#objects do
            local name = BANETO_ObjectName(objects[i])
            if BANETO_SETTINGS_MASTERNAME and BANETO_SETTINGS_MASTERNAME == name and not UnitIsDeadOrGhost(objects[i]) then
                return objects[i]
            end
        end
    end
end

function _G.BANETO_MakesHsUsageSense()

    if GetItemCount(6948) == 0 then
        return false
    end
    if not IsFlying() then
        if _G.BANETO_DEFINED_VENDOR_INNKEEPER and _G.BANETO_DEFINED_VENDOR_INNKEEPER[1] and BANETO_SETTING_INNKEEPER_CURRENT_BINDING and _G.BANETO_DEFINED_VENDOR_INNKEEPER[1][4] == BANETO_SETTING_INNKEEPER_CURRENT_BINDING then
            if not BANETO_PlayerPosition(_G.BANETO_DEFINED_VENDOR_INNKEEPER[1][1],_G.BANETO_DEFINED_VENDOR_INNKEEPER[1][2],_G.BANETO_DEFINED_VENDOR_INNKEEPER[1][3],190) then
                return true
            end
        else
            return true
        end
    end
end
