function _G.BANETO_IsLossOfControl(unit)
    for i = 1, C_LossOfControl.GetActiveLossOfControlDataCount() do
        local event = C_LossOfControl.GetActiveLossOfControlData(i)
        local self = "player"
        if event and event.locType ~= "SCHOOL_INTERRUPT" and UnitIsUnit(unit, self) then
            return true
        end
    end
    return false
end

function _G.BANETO_UseMotes()
    if (not BANETO_MOTES_USAGE_DELAYER or BANETO_MOTES_USAGE_DELAYER < GetTime()) and BANETO_SETTING_AUTOCOMBINE and BANETO_SETTING_AUTOCOMBINE == true and BANETO_State ~= "REGEN" and BANETO_State ~= "FIGHTING" and BANETO_State ~= "CLEAR-PATH" and not MerchantFrame:IsVisible() then
        BANETO_MOTES_USAGE_DELAYER = GetTime()+0.5
        if GetItemCount(190315) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190315)
        elseif GetItemCount(190320) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190320)
        elseif GetItemCount(190322) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190322)
        elseif GetItemCount(190326) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190326)
        elseif GetItemCount(190328) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190328)
        elseif GetItemCount(190330) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190330)
        elseif GetItemCount(190451) >= 10 then
            DRUID_FORM_DELAYER_PULSE= GetTime()+4
            BANETO_UseItem(190451)
        end
    end
end

