function _G.BANETO_TraceLineForBlacklisterDebug()
    _G.BANETO_BLACKLIST_TRACELINES = {}
    C_Timer.NewTicker(6,function()
        _G.BANETO_BLACKLIST_TRACELINES = {}
    end)
end

function BANETO_TraceLineForBlacklister(x1,y1,z1,x2,y2,z2, hitFlag)
	local a,b,c
    if BANETO_Software() == "nn" then
    	a, b, c = BANETO_TraceLine(x1, y1, z1, x2, y2, z2, hitFlag)
    elseif BANETO_Software() =="tnk" then
    	a, b, c = app.TraceLine(x1, y1, z1, x2, y2, z2, hitFlag)
    end

    if _G.BANETO_BLACKLIST_TRACELINES then
        local input = {{x1,y1,z1},{x2,y2,z2},{a,b,c}}
        table.insert(_G.BANETO_BLACKLIST_TRACELINES,input)
    end
    return a,b,c
end

function BANETO_UnitClassification(obj)
	return UnlockedTargetClassification(obj)
end

function BANETO_GetUnitIsFriend(Unit, otherUnit)
	if not UnitIsVisible(Unit) or not UnitIsVisible(otherUnit) then
        return false
    end
	return UnitIsFriend(Unit,otherUnit)
end


function _G.BANETO_IsInsideNode(object)
    local x1, y1, z1 = BANETO_ObjectPosition(object)
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local heightOffest = 3
    local suaqreLength = 5
    local lineHeight = 200 --70
    if not x1 or not y1 or not z1 then
        return false
    end
    local a1,b1,c1 = BANETO_TraceLineForBlacklister(x1+suaqreLength,y1-suaqreLength,z1+heightOffest,x1,y1,z1+lineHeight, hitFlags)
    local a2,b2,c2 = BANETO_TraceLineForBlacklister(x1-suaqreLength,y1+suaqreLength,z1+heightOffest,x1,y1,z1+lineHeight, hitFlags)
    local a3,b3,c3 = BANETO_TraceLineForBlacklister(x1-suaqreLength,y1-suaqreLength,z1+heightOffest,x1,y1,z1+lineHeight, hitFlags)
    local a4,b4,c4 = BANETO_TraceLineForBlacklister(x1+suaqreLength,y1+suaqreLength,z1+heightOffest,x1,y1,z1+lineHeight, hitFlags)
    local aCenter,bCenter,cCenter = BANETO_TraceLineForBlacklister(x1,y1,z1+heightOffest,x1,y1,z1+lineHeight, hitFlags)
    if BANETO_Software() == "nn" and not BANETO_IsJin() then
        if (c1 ~= nil) and (c2 ~= nil) and (c3 ~= nil) and (c4 ~= nil) and (cCenter ~= nil) then
            return true
        else
            return false
        end
    elseif BANETO_Software() == "nn" and BANETO_IsJin() then
        if c1 and c2 and c3 and c4 and cCenter then
            return true
        else
            return false
        end
    elseif BANETO_Software() == "tnk" then
        if not ObjectIsOutdoors(object) then
            return true
        end
        if (c1 and c1 ~= 0) and (c2 and c2 ~= 0) and (c3 and c3 ~= 0) and (c4 and c4 ~= 0) and (cCenter and cCenter ~= 0) then
            if _G.BANETO_DEBUG_BLACKLIST_BUG then
                print("C1: "..c1)
                print("C2: "..c2)
                print("C3: "..c3)
                print("C4: "..c4)
                print("CC: "..cCenter)
            end
            return true
        else
            return false
        end
    end
end



function BANETO_IsUnderwater(object)
    local heightOffest = 2
    local lineHeight = 200
    local x1, y1, z1Uw = BANETO_ObjectPosition(object)
    local hitFlags = 0x20000 --Liquid
    if x1 and y1 and z1Uw then
        local a,b,c = BANETO_TraceLineForBlacklister(x1,y1,z1Uw+heightOffest,x1,y1,z1Uw+heightOffest+lineHeight, hitFlags)
        if BANETO_Software() == "nn" and not BANETO_IsJin() then
            if c ~= nil then
                return true
            else
                return false
            end
        elseif BANETO_Software() == "nn" and BANETO_IsJin() then
            if c then
                return true
            else
                return false
            end
        elseif BANETO_Software() == "tnk" then
            if c and c ~= 0 then
                return true
            else
                return false
            end
        end
	end
end


function BANETO_IsEzMineNearObject(object, radius)
    local eliteNearObj = false
    local x,y,z = BANETO_ObjectPosition(object)
    local AllObjects = BANETO_GetObjctsTkr()
    for k in pairs(AllObjects) do
        local obj = AllObjects[k]
        local id = BANETO_ObjectId(obj)
        if BANETO_ObjectType(obj) == 8 and (id == 413905 or id == 413886 or id == 413895) then
            local xUnit,yUnit,zUnit = BANETO_ObjectPosition(obj)
            if yUnit and id and id ~= 197397 then
                local distance = BANETO_GetDistance3D(x, y, z, xUnit, yUnit,zUnit )
                if distance and distance <= radius then
                    eliteNearObj = true
                    break
                end
            end
        end
    end
    return eliteNearObj
end


function BANETO_IsEliteNearObject(object, radius)
    local eliteNearObj = false
    local x,y,z = BANETO_ObjectPosition(object)
    local AllObjects = BANETO_GetObjctsTkr()
    for k in pairs(AllObjects) do
        local obj = AllObjects[k]
        local id = BANETO_ObjectId(obj)
        if BANETO_ObjectType(obj) == 5 then
            local xUnit,yUnit,zUnit = BANETO_ObjectPosition(obj)
            local unitClass = BANETO_UnitClassification(obj);
            if unitClass ==  "worldboss" or unitClass ==  "rareelite" or unitClass ==  "elite" then
                local moblevel = UnitLevel(obj) or 0
                local r = UnlockedTargetReaction(obj)
                if not BANETO_GetUnitIsFriend("player",obj) and yUnit and id and id ~= 197397 and moblevel+20 >= UnitLevel("player") and BANETO_UnitHealth(obj) >= 2 and (r == 1 or r == 2) then
                    local distance = BANETO_GetDistance3D(x, y, z, xUnit, yUnit,zUnit )
                    if distance and distance <= radius then
                        eliteNearObj = true
                        break
                    end
                end
            end
        end
    end
    return eliteNearObj
end


function BANETO_BlacklistNode()
    local AllObjects = BANETO_GetObjctsTkr()
    for k in pairs(AllObjects) do
        local SpecificObject = AllObjects[k]
		local objectId = BANETO_ObjectId(SpecificObject)
        if (BANETO_IsGatheringNodeRaw(objectId) or BANETO_IsCustomGatherObject(objectId)) and BANETO_ObjectType(SpecificObject) == 8 then
			local name = BANETO_ObjectName(SpecificObject)
			if not BANETO_IsGuidContainedInGuidBlacklist(SpecificObject) then
				if BANETO_SETTING_GATHER_SKIPCAVENODES == true and BANETO_IsInsideNode(SpecificObject)  then
                    if not IsUnitInWhitelistArea(SpecificObject) then
                        BANETO_AddMobToGuidBlacklist(SpecificObject)
                        if BANETO_TARGET and BANETO_TARGET == SpecificObject then
                            BANETO_TARGET = nil
                        end
                        if BANETO_GetState() == "GATHER" then
                            BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                        end
                        BANETO_Print(name.. " Added to GUID Blacklist for this Session (Reason: Node Inside)")
                    end
				end
                if BANETO_SETTING_GATHER_SKIPWATERNODES == true and BANETO_IsUnderwater(SpecificObject)  then
                    if not IsUnitInWhitelistArea(SpecificObject) then
                        BANETO_AddMobToGuidBlacklist(SpecificObject)
                        if BANETO_TARGET and BANETO_TARGET == SpecificObject then
                            BANETO_TARGET = nil
                        end
                        if BANETO_GetState() == "GATHER" then
                            BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                        end
                        BANETO_Print(name.. " Added to GUID Blacklist for this Session (Reason: Underwater)")
                    end
                end
				if BANETO_SETTING_GATHER_SKIPNEARELITES == true and BANETO_IsEliteNearObject(SpecificObject,30) and objectId ~= 382075 then
                    if not IsUnitInWhitelistArea(SpecificObject) then
                        BANETO_AddMobToGuidBlacklist(SpecificObject)
                        if BANETO_TARGET and BANETO_TARGET == SpecificObject then
                            BANETO_TARGET = nil
                        end
                        if BANETO_GetState() == "GATHER" then
                            BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                        end
                        BANETO_Print(name.. " Added to GUID Blacklist for this Session (Reason: Node near Elite)")
                    end
				end
                if BANETO_SETTING_OVERLOAD_EZMINE == false and BANETO_IsEzMineNearObject(SpecificObject,10) and objectId ~= 382075 then
                    if not IsUnitInWhitelistArea(SpecificObject) then
                        BANETO_AddMobToGuidBlacklist(SpecificObject)
                        if BANETO_TARGET and BANETO_TARGET == SpecificObject then
                            BANETO_TARGET = nil
                        end
                        if BANETO_GetState() == "GATHER" then
                            BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                        end
                        BANETO_Print(name.. " Added to GUID Blacklist for this Session (Reason: Node near EZ-MINE)")
                    end
                end
			end
        end
    end
end

