function _G.BANETO_MissionControlInvString()
    local s = ""
    local t = {}
	for i = 0, NUM_BAG_SLOTS+1 do
		for z = 1, GetContainerNumSlots(i) do
            local idInBag = GetContainerItemID(i, z)
            if idInBag  then
                local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(idInBag)
                if itemName and not t[itemName] then
                    t[itemName] = GetItemCount(idInBag)
                end
            end
        end
    end
    for i, v in pairs(t) do
        s = s..v.. "x "..i..";"
    end
    return s
end
function _G.BANETO_SendChatMessage(chatmessage,channel,language,recipient)
    SendChatMessage(chatmessage ,channel, language, recipient)
    local date = date()
    local log = date.. " " .. UnitName("player") .. " (YOU) TO " .. recipient .. ": " .. chatmessage.. "\n"
    local logDc = UnitName("player") .. " (YOU) WHISPERED TO " .. recipient .. ": " .. chatmessage.. "\n"
    if BANETO_SETTING_WHISPERLOGGING == true and _internal.Software() == "nn" then
        if not FileExists(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt") then
            WriteFile(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt","",false)
        end
         WriteFile(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt", log, true)
    end
    if BANETO_SETTING_WHISPERLOGGING == true and _internal.Software() == "tnk" then
        if not FileExists("scripts/baneto/logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt") then
            WriteFile("scripts/baneto/logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt","",false)
        end
        WriteFile("scripts/baneto/logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt", log, true)
    end
    if BANETO_SETTING_DISCORD_WHISPER and BANETO_SETTING_DISCORD_WHISPER == true then
        BANETO_DiscordSendWhisperOutgoing(logDc)
    end
    BANETO_MC_WHISPERS = BANETO_MC_WHISPERS .. log .. ";"
end


function _G.BANETO_McAction(action,actionArg)
    if actionArg == "none" then
        actionArg = ""
    end

    if action == "jump" then
        BANETO_JumpOrAscendStart()
    elseif action == "vendor" then
        BANETO_VisionTriggers("SELL")
    elseif action == "start" then
        BANETO_Start()
    elseif action == "stop" then
        BANETO_Stop()
    elseif action == "hearthstone" then
        BANETO_UNSTUCK_HEARTHSTONE=true
    elseif action == "logout" then
        BANETO_StopMovement()
        BANETO_DelayMeshPathing(21)
        BANETO_Logout()
    elseif action == "reload" then
        -- BANETO_RunMacroText("/reload")
        -- reloadUi()
        -- C_Timer.After(3,reloadUi)
    elseif action == "shutdown" then
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            Eval("ForceQuit()","asdas")
        end
        if Unlocker("LUA") and _internal.Software() == "nn" then
            Unlock("ForceQuit","")
        end
    elseif action == "repair" then
        _G.BANETO_VISION_TRIGGER_REPAIR = true
    elseif action == "mail" then
        _G.BANETO_MAIL_NEEDED = true
    elseif action == "load" then
        BANETO_PrintBambo("TEST MC LOAD 3: "..actionArg)
        _G.BANETO_LoadProfile(actionArg,true)
    elseif action == "whisper" then
        if BANETO_LAST_SENDER then
            BANETO_SendChatMessage(actionArg ,"WHISPER" ,"COMMON" ,BANETO_LAST_SENDER)
        else
            BANETO_PrintError("Mission Control - Whisper failed. No recipient.")
            return false
        end
    end
    if action ~= "none" then
        BANETO_PrintSuccess("Mission Control - " .. action .. " "..actionArg)
    end
end

function _G.BANETO_ForceQuit()
    if Unlocker("LUA") and _internal.Software() == "tnk" then
        Eval("ForceQuit()","asdas")
    elseif  _internal.Software() == "nn" then
        Unlock("ForceQuit","")
    end
end
function _G.BANETO_IsPluginEnabled(name)
    return _G["BANETO_PLUGIN_CHECKBOX_"..name]:GetChecked(true)
