function _G.BANETO_EnablePlugin(name)
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:SetChecked(true)
    BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST[name] = _G["BANETO_PLUGIN_CHECKBOX_"..name]:GetChecked()
    BANETO_SaveSettings()
end
function _G.BANETO_DisablePlugin(name)
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:SetChecked(false)
    BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST[name] = _G["BANETO_PLUGIN_CHECKBOX_"..name]:GetChecked()
    BANETO_SaveSettings()
end

