function _G.BANETO_MissionControl()
    local money = GetMoney()
    local gold = math.floor(GetMoney()/10000)
    money = GetMoney()-gold*10000
    local silver = math.floor(money/100)
    money = GetMoney()-gold*10000-silver*100
    local copper = money
    local targetInfo;
    if UnitExists("target") then
        targetInfo = BANETO_ObjectName("target") or "unknown target name"
    else
        targetInfo = "No Target"
    end
    local race, raceEn = UnitRace("player")
    local _, _, class = UnitClass("player")
    local mc = {
        username = BANETO_CREDENTIAL_USERNAME,
        password = BANETO_CREDENTIAL_PASSWORD,
        charactername = UnitName("player"),
        expansion = WOW_PROJECT_ID,
        faction = UnitFactionGroup("player"),
        gold = gold,
        silver = silver,
        copper = copper,
        profilename = BANETO_GetProfileName() or "No Profile",
        state = BANETO_GetState(),
        xpperhour = BANETO_GetXpPerHour(),
        deaths = BANETO_COUNT_DEATH,
        realm = GetRealmName(),
        race = raceEn,
        notMoving = BANETO_MissionControlSpeedCheck(),
        whispers = BANETO_MC_WHISPER_COUNT,
        whispersMsg = BANETO_MC_WHISPERS,
        characterClass = class,
        zone = GetZoneText(),
        subZone = GetSubZoneText(),
        bagslotsTotal = BANETO_GetTotalBagSlots(),
        bagslotsFree = BANETO_GetFreeBagSlots(),
        items = BANETO_MissionControlInvString(),
        level = UnitLevel("player"),
        stucks = BANETO_MC_COUNT_STUCKS,
        xpmax = UnitXPMax("player"),
        xpcurrent = UnitXP("player"),
        dead = BANETO_IsDeadOrGhost() or false,
        nodes = BANETO_GetCountGatherNode() or 0,
        hpCurrent = UnitHealth("player"),
        hpMax = UnitHealthMax("player"),
        players = CountPlayersAroundMe(200),
        sessionTime = BANETO_GetSessionTime(),
        armor = BANETO_GetArmorPercentage(),
        targetname = targetInfo,
        mounted = IsMounted(),
        flying = IsFlying(),
        swimming = IsSwimming(),
        indoors = IsIndoors(),
        rawgold = BANETO_GetRawgoldPerHour(),
        digsites = BANETO_GetDigsitesCompletedCount()
    }
    if _G.TEST_MC_EMPTY_PAYLOAD then
        mc = {
            username = BANETO_CREDENTIAL_USERNAME,
            password = BANETO_CREDENTIAL_PASSWORD
         }
    end
    return mc
end
