function _G.BANETO_DfLures()
    if (not _G.BANETO_BOBBER_LUREAPPLY_DELAY or _G.BANETO_BOBBER_LUREAPPLY_DELAY < GetTime()) and BANETO_GetUnitSpeed("player") == 0 and BANETO_SETTING_FISHLURES and BANETO_SETTING_FISHLURES == true and not UnitChannelInfo("player") and not UnitCastingInfo("player") and BANETO_SETTING_FISHINGPOLE and not BANETO_HasSlBaitApplied() and not BANETO_HasDfBaitApplied() and (not GuildBankFrame or not GuildBankFrame:IsVisible()) then

        if not BANETO_LURE_START_DELAY then
            BANETO_LURE_START_DELAY=GetTime()+1
            BANETO_ANGLE_WAIT_TIME = GetTime()+5
        end
        if not LootFrame:IsVisible() and BANETO_LURE_START_DELAY < GetTime()  then
            local hasBobber,_ = BANETO_GetBestBobberItem()
            if not BANETO_BOBBER_USINGLURE and hasBobber then
                local bobberItem,bobberDelay = BANETO_GetBestBobberItem()
                if not bobberDelay then
                    bobberDelay = 600
                end
                BANETO_UseItem(bobberItem)
                BANETO_BOBBER_USINGLURE = true
                BANETO_ANGLE_WAIT_TIME = GetTime()+5
                scalebellydelay = GetTime()+5
                BANETO_DelayStateTick(3)
                BANETO_PrintState("Use Lure item: ".. bobberItem .. " with delay: "..bobberDelay)
                C_Timer.After(0.5,function()
                    local bobberItem,bobberDelay = BANETO_GetBestBobberItem()
                    if not bobberDelay then
                        bobberDelay = 600
                    end
                    _G.BANETO_BOBBER_LUREAPPLY_DELAY = GetTime()+bobberDelay
                    BANETO_PrintState("Use Lure item on pole: "..bobberItem)
                    BANETO_RunMacroText("/use 28")
                    BANETO_ANGLE_WAIT_TIME = GetTime()+5
                    scalebellydelay = GetTime()+5
                    BANETO_LURE_START_DELAY = nil
                    BANETO_BOBBER_USINGLURE = nil
                end)
            end
        end
    end
end

function _G.BANETO_AddRecipientToFl()
    local recipient = BANETO_GetMailRecipient()
    if _internal.Software() == "nn" then
        Unlock("pcall", C_FriendList.AddFriend, recipient)
    else
        Eval("pcall(C_FriendList.AddFriend,[[" .. recipient .. "]])", "")
    end
    BANETO_PrintSuccess("Added "..recipient.. " to friend list (mailing)!")
end

function _G.BANETO_FindBestSwarmLanding(swarm)
    waterHits = {}
    groundHits = {}
    local noHits = {}
    local bestPosition;

    local x,y,z = BANETO_ObjectPosition(swarm)
    if x and y and z then
        for q = 1,7 do
            if groundHits[1] then
                break
            end
            local checkDistance = 12+q
            local xA,yA,zA = x+checkDistance,y,z
            local xB,yB,zB = x-checkDistance,y,z
            local xC,yC,zC = x,y+checkDistance,z
            local xD,yD,zD = x,y-checkDistance,z
            local xE,yE,zE = x+checkDistance/math.sqrt(2),y+checkDistance/math.sqrt(2),z
            local xF,yF,zF = x-checkDistance/math.sqrt(2),y-checkDistance/math.sqrt(2),z
            local xG,yG,zG = x+checkDistance/math.sqrt(2),y-checkDistance/math.sqrt(2),z
            local xH,yH,zH = x-checkDistance/math.sqrt(2),y+checkDistance/math.sqrt(2),z

            local xA2,yA2,zA2 = x+checkDistance/math.sqrt(5),y+checkDistance*2/math.sqrt(5),z
            local xB2,yB2,zB2 = x+checkDistance*2/math.sqrt(5),y+checkDistance/math.sqrt(5),z
            local xC2,yC2,zC2 = x+checkDistance*2/math.sqrt(5),y-checkDistance/math.sqrt(5),z
            local xD2,yD2,zD2 = x+checkDistance/math.sqrt(5),y-checkDistance*2/math.sqrt(5),z

            local xE2,yE2,zE2 = x-checkDistance*2/math.sqrt(5),y+checkDistance/math.sqrt(5),z
            local xF2,yF2,zF2 = x-checkDistance/math.sqrt(5),y+checkDistance*2/math.sqrt(5),z
            local xG2,yG2,zG2 = x-checkDistance*2/math.sqrt(5),y-checkDistance/math.sqrt(5),z
            local xH2,yH2,zH2 = x-checkDistance/math.sqrt(5),y-checkDistance*2/math.sqrt(5),z


            local testPositions = {
                {xA,yA,zA},
                {xB,yB,zB},
                {xC,yC,zC},
                {xD,yD,zD},
                {xE,yE,zE},
                {xF,yF,zF},
                {xG,yG,zG},
                {xH,yH,zH},
                {xA2,yA2,zA2},
                {xB2,yB2,zB2},
                {xC2,yC2,zC2},
                {xD2,yD2,zD2},
                {xE2,yE2,zE2},
                {xF2,yF2,zF2},
                {xG2,yG2,zG2},
                {xH2,yH2,zH2}
            }

            local hitFlagsGround = bit.bor(0x1, 0x10, 0x100, 0x100000)
            local hitFlagsLiquid =  0x20000
            for i = 1,#testPositions do
                local x,y,z = testPositions[i][1],testPositions[i][2],testPositions[i][3]
                local xH1G, yH1G, zH1G = BANETO_TraceLine(x,y,z+10, x,y,z-20, hitFlagsGround)
                local xH1L, yH1L, zH1L = BANETO_TraceLine(x,y,z+10, x,y,z-20, hitFlagsLiquid)
                if xH1G and xH1G ~= 0 and not swarmPosition_blacklists[x] and ((not xH1L) or (xH1L and xH1L == 0 ) or (zH1G+0.5 > zH1L)) then
                    --print("fishing: ground hit with liquid x: "..xH1L)
                    --print("fishing: ground hit with ground x: "..xH1G)
                    table.insert(groundHits,testPositions[i])
                elseif xH1L and xH1L ~= 0 then
                    --print("fishing: liquid hit with liquid x: "..xH1L)
                    table.insert(waterHits,testPositions[i])
                else
                    table.insert(noHits,testPositions[i])
                end
            end
        end
    end
    if groundHits[1] then
        return groundHits[1]
    end
end

