function _G.BANETO_SCAN_GLYPHS()
    if not BANETO_DISCOVERED_GLYPHS then
        BANETO_DISCOVERED_GLYPHS = {}
    end
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    t = {}
    for i = 1,#objects do
        local obj = objects[i]
        local objId = BANETO_ObjectId(obj)
        if obj and objId then
            if not IsUnitBlacklisted(obj) and BANETO_OBJECTS_GLYPHS[objId] and not BANETO_DISCOVERED_GLYPHS[objId] then
                table.insert(t, { obj, GetDistanceBetweenObjects("player", obj) })
            end
        end
    end
    if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
    if t[1] then
        return t[1][1]
    end
end
swarmPosition_blacklists = {}
function _G.BANETO_BlacklistSwarmLanding()
    if swarmPosition and swarmPosition[1] then
        local x,y,z = swarmPosition[1],swarmPosition[2],swarmPosition[3]
        swarmPosition_blacklists[x] = true
        swarmPosition = nil
        if not swarmPosition_timer then
            swarmPosition_timer = true
            C_Timer.After(90,function()
                swarmPosition_timer = nil
                swarmPosition_blacklists = {}
            end)
        end
    end
end
_G.BANETO_SCAN_RANGE_FISHINGSWARMS = 400
function _G.BANETO_SCAN_FISHINGSWARMS()
    local objects = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS
    t = {}
    for i = 1,#objects do
        local obj = objects[i]
        local objId = BANETO_ObjectId(obj)
        if obj and objId then
            if BANETO_IsFishingSwarm(objId) and not IsUnitBlacklisted(obj) then
                local d = GetDistanceBetweenObjects("player", obj)
                if _G.BANETO_SCAN_RANGE_FISHINGSWARMS >= d then
                    table.insert(t, { obj,  d})
                end
            end
        end
    end

	if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if t[1] then
	    local swarmLanding = BANETO_FindBestSwarmLanding(t[1][1])
	    if swarmLanding then
		    return t[1][1],swarmLanding
        else
            BANETO_PrintWarning("Blacklisted fish swarm: no landing position")
            BANETO_AddMobToGuidBlacklist(t[1][1])
        end
	end
end

function _G.BANETO_SaveSettings()
    BANETO_SETTINGS_CACHE = ""
	if BANETO_SettingsCorrupted() and CORRUPTIONFIXISNEEDED then
		if BANETO_SETTING_LASTLOADEDPROFILE then
			BANETO_PrintDev("Saving denied to protect settings file from corruption. Please reload and send the corrupted settings file to bambo! Last used profile: " .. BANETO_SETTING_LASTLOADEDPROFILE)
			return true
		else
			BANETO_PrintDev("Saving denied to protect settings file from corruption! Please reload and send the corrupted settings file to bambo!! Last used profile: " .. "unknown")
			return true
		end
	end
	if (not BANETO_SAVE_DELAYER or BANETO_SAVE_DELAYER < GetTime()) and UnitGUID("player") and BANETO_FIRSTLOAD_TIME+5 < GetTime() and BANETO_LOADED_SETTINGS_FINISHED and not BANETO_WHISPER_CLOSENEEDED and not BANETO_WOWCLOSER_WARNING_1MINUTE then
