            for i=1, #BANETO_SPELL_SETTINGS_TABLE do
                if Unlocker("LUA") and BANETO_SPELL_SETTINGS_TABLE[i][5] == true then
                    BANETO_CacheSettings(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua","\nBANETO_SetSpellSetting("..BANETO_SPELL_SETTINGS_TABLE[i][1]..","..BANETO_SPELL_SETTINGS_TABLE[i][2]..","..BANETO_SPELL_SETTINGS_TABLE[i][3]..","..BANETO_SPELL_SETTINGS_TABLE[i][4]..",true"..")",true)
                else
                    BANETO_CacheSettings(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua","\nBANETO_SetSpellSetting("..BANETO_SPELL_SETTINGS_TABLE[i][1]..","..BANETO_SPELL_SETTINGS_TABLE[i][2]..","..BANETO_SPELL_SETTINGS_TABLE[i][3]..","..BANETO_SPELL_SETTINGS_TABLE[i][4]..",false"..")",true)
                end
            end
        end

		if BANETO_TASK_MANAGER then
			for i=1, #BANETO_TASK_MANAGER do
                if Unlocker("LUA") then
                    BANETO_CacheSettings(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua","\nBANETO_AddTask([["..BANETO_TASK_MANAGER[i][1].."]],"..BANETO_TASK_MANAGER[i][2]..",[["..BANETO_TASK_MANAGER[i][3].."]],".."true" ..")" ,true)
                end
			end
		end

        if BANETO_CUSTOM_TRAVELPOINTS then
            for i=1, #BANETO_CUSTOM_TRAVELPOINTS do
                if Unlocker("LUA") then
                    BANETO_CacheSettings(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua","\nBANETO_DefineCustomTravelVector("..BANETO_CUSTOM_TRAVELPOINTS[i][1]..","..BANETO_CUSTOM_TRAVELPOINTS[i][2]..","..BANETO_CUSTOM_TRAVELPOINTS[i][3]..","..BANETO_CUSTOM_TRAVELPOINTS[i][4]..",".. "[[" ..BANETO_CUSTOM_TRAVELPOINTS[i][5] .."]])",true)
                end
            end
        end

		for i=1, #strings do
			local settingType, settingVariable = strings[i][1],strings[i][2]
			if not settingVariable then
				settingVariable = "nostringinput"
			end
			if settingType and settingVariable then
                if Unlocker("LUA") then
                    BANETO_CacheSettings(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua","\nBANETO_SetSettingString("..settingType..",".."[[" ..settingVariable .."]]" .. ")",true)
                end
			end
		end

		WriteFile(baneto_path_scripts_settings.. UnitGUID("player") .. ".lua",BANETO_SETTINGS_CACHE,false)
        local Length = tablelength(BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST)
        if BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST and Length and Length >= 1 then
            local json = BANETO_JsonEncode(BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST)
            WriteFile(baneto_path_scripts_settings.. UnitGUID("player") .. ".json",json,false)
        end

	else
		if not BANETO_SAVE_QUEUED then
			BANETO_SAVE_QUEUED=true
            BANETO_SAVE_DELAYER = GetTime()+1
		end
	end
end

function _G.BANETO_IsNearProfileSpotsBarrage(spotindexes)
    if not spotindexes then
        if centerIndex and BANETO_DEFINED_CENTERS[centerIndex] then
            local x,y,z,radius = BANETO_DEFINED_CENTERS[centerIndex][1],BANETO_DEFINED_CENTERS[centerIndex][2],BANETO_DEFINED_CENTERS[centerIndex][3],7.5
            if BANETO_PlayerPosition(x,y,z,radius) then
                return true
            else
                return false
            end
        else
            return true
        end
    else
        for i = 1,#spotindexes do
            local spotindex = spotindexes[i]
            if centerIndex and BANETO_DEFINED_CENTERS[centerIndex] and spotindex == centerIndex then
                local x,y,z,radius = BANETO_DEFINED_CENTERS[centerIndex][1],BANETO_DEFINED_CENTERS[centerIndex][2],BANETO_DEFINED_CENTERS[centerIndex][3],7.5
                if BANETO_PlayerPosition(x,y,z,radius) then
                    return true
                else
                    return false
                end
            end
        end
    end
end

function _G.BANETO_IsNearProfileSpots()
    if centerIndex and BANETO_DEFINED_CENTERS[centerIndex] then
        local x,y,z,radius = BANETO_DEFINED_CENTERS[centerIndex][1],BANETO_DEFINED_CENTERS[centerIndex][2],BANETO_DEFINED_CENTERS[centerIndex][3],BANETO_DEFINED_CENTERS[centerIndex][4]+120
        if BANETO_PlayerPosition(x,y,z,radius) then
            return true
        else
            return false
        end
    else
        return true
    end
end

function _G.BANETO_IsFightBlockedByQuester()
	if BANETO_DEFINED_PROFILE_TYPE == "Questing" then
		if BANETO_State == "QUEST-PICKUP" and (BANETO_SETTING_IGNORECOMBATPICKUPQUEST and BANETO_SETTING_IGNORECOMBATPICKUPQUEST == true) then
			return true
		elseif BANETO_State == "QUEST-TURNIN" and (BANETO_SETTING_IGNORECOMBATTURNINQUEST and BANETO_SETTING_IGNORECOMBATTURNINQUEST == true) then
			return true
		end
	end
end

function _G.BANETO_SurviveSpellsCast()


	if not BANETO_CAST_SURVIVAL or BANETO_CAST_SURVIVAL < GetTime() then
		BANETO_CAST_SURVIVAL=GetTime()+0.5
		local _,_,class = UnitClass("player")

        if class and class == 3 then
            local feign_death = 5384
            if BANETO_IsSpellUsable(feign_death) and not BANETO_HasBuff("player",feign_death) and not _G.BANETO_BLOCK_HUNTER_FD then
                if not BANETO_CAST_FEIGNDEATH_SURVIVAL then
                    BANETO_CAST_FEIGNDEATH_SURVIVAL = GetTime()+1
                elseif BANETO_CAST_FEIGNDEATH_SURVIVAL and GetTime() > BANETO_CAST_FEIGNDEATH_SURVIVAL and not UnitCastingInfo("player") and not UnitChannelInfo("player") and not BANETO_HasBuff("player",34477) then
                    local speed = BANETO_GetUnitSpeed("player")
                    if speed == 0 then
                        BANETO_CAST_FEIGNDEATH_SURVIVAL = nil
                        BANETO_CastSpell(feign_death,true)
                        BANETO_CASTED_FEIGNDEATH = true
                        BANETO_CASTED_FEIGNDEATH_QUITTER = nil
                        BANETO_PrintState("FLEE - Hunter feign death")
                    else
                        BANETO_StopMovement()
                        BANETO_DelayMeshPathing(2)
                    end
                end
            end
        end

		if class == 2 then
            local palaBlessingProt = 1022
            local palaBubble = 642
            local palaFreedom = 1044
            if BANETO_IsSpellUsable(palaBlessingProt) and not BANETO_HasBuff("player",palaBlessingProt) then
                BANETO_CastSpell(palaBlessingProt,true)
            elseif BANETO_IsSpellUsable(palaBubble) and not BANETO_HasBuff("player",palaBubble) then
                BANETO_CastSpell(palaBubble,true)
            elseif BANETO_IsSpellUsable(palaFreedom) and not BANETO_HasBuff("player",palaFreedom) then
                BANETO_CastSpell(palaFreedom,true)
            end
        end
        if class == 11 then
            local druidBarksin = 22812
            local druidRejuvenation  = 774
            local travel = 292629
            if BANETO_IsSpellUsable(druidBarksin) and not BANETO_HasBuff("player",druidBarksin) then
                BANETO_CastSpell(druidBarksin, true)
            elseif BANETO_IsSpellUsable(druidRejuvenation) and not BANETO_HasBuff("player",druidRejuvenation) then
                BANETO_CastSpell(druidRejuvenation, true)
            elseif BANETO_IsSpellUsable(travel) and not BANETO_CASTED_RUNAWAY_TRAVELFORM then
                BANETO_CastSpell(travel, true)
            end
        end
        if class == 4 then
            local rogueEvasion = 5277
            local rogueSprint = 2983
            local vanish = 1856
            if BANETO_IsSpellUsable(vanish) and UnitLevel("player") >= 23 then
                BANETO_CastSpell(vanish,true)
            elseif BANETO_IsSpellUsable(rogueEvasion) and not BANETO_HasBuff("player",rogueEvasion) then
                BANETO_CastSpell(rogueEvasion,true)
            elseif BANETO_IsSpellUsable(rogueSprint) and not BANETO_HasBuff("player",rogueSprint) then
                BANETO_CastSpell(rogueSprint,true)
            end
        end
        if class == 5 then
            local priestHot = 139
            local priestShield = 17
            if BANETO_IsSpellUsable(priestHot) and not BANETO_HasBuff("player",priestHot) then
                BANETO_CastSpell(priestHot,true)
            elseif BANETO_IsSpellUsable(priestShield) and not BANETO_HasBuff("player",priestShield) then
                BANETO_CastSpell(priestShield,true)
            end
        end
	end

end

function _G.BANETO_DiscordSendTargeted(name)
    if not name then
        name = "unknown"
    end
    if BANETO_PUSHNOTIFICIATIONS_WEBHOOK and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "Enter your webhook url here!" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "nostringinput" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= nil and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "" then
        local urltarget = BANETO_PUSHNOTIFICIATIONS_WEBHOOK
        local payload = [[{
        "username": "Baneto",
        "avatar_url": "https://baneto-bot.com/assets/img/logo.png",
        "content": ":boom: :boom: :boom: :boom: ]] .. name ..[[ is targeting your bot ]] .. UnitName("player") .. [[ :boom: :boom: :boom: :boom:",
        "embeds": null,
        "attachments": []
        }]]
        local function callb(status)
           if status and (status == 200 or status == 204) then
                BANETO_PrintSuccess("Found someone that targets us: "..name.."! Sending info to discord webhook.")
           else
                BANETO_PrintError("Something is wrong with the discord webhook. ERROR: " .. status)
           end
        end
        BANETO_HttpPost(urltarget,payload,callb)
    end
end

