function _internal.BANETO_DiscordSendData()
    local profilenameDiscord = BANETO_GetProfileName()
    if not profilenameDiscord then
        profilenameDiscord = "No profile"
    end
    local herbs = BANETO_CountItemTypeInBagsForDisc("Herb")
    local leather = BANETO_CountItemTypeInBagsForDisc("Leather")
    local ores = BANETO_CountItemTypeInBagsForDisc("Metal & Stone")
    local goldDiscord = math.floor(GetMoney()/10000)
    local playersAroundDisc = CountPlayersAroundMe(200)

    local xTargetDiscord,yTargetDiscord,zTargetDiscord;
    local xTargetIdDiscord;
    if UnitExists("target") then
        xTargetDiscord,yTargetDiscord,zTargetDiscord = BANETO_ObjectPosition("target")
        xTargetIdDiscord = BANETO_ObjectId("target")
    else
        xTargetDiscord,yTargetDiscord,zTargetDiscord = 0,0,0
        xTargetIdDiscord = 0
    end

    local xPlayerDiscord,yPlayerDiscord,zPlayerDiscord;
    if UnitExists("player") then
        xPlayerDiscord,yPlayerDiscord,zPlayerDiscord = BANETO_ObjectPosition("player")
    else
        xPlayerDiscord,yPlayerDiscord,zPlayerDiscord = 0,0,0
    end
    local bugreportMsgDiscord = BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_REPORTBUG:GetText()
    local usernameDiscord = BANETO_Customer()
    if playersAroundDisc == nil then
        playersAroundDisc = 0
    end
    local localizedClass, englishClass, classIndex = UnitClass("player")
    local tableDiscord = {
      username = "Baneto",
      avatar_url = "https://baneto-bot.com/assets/img/logo.png",
      content = "",
      embeds = { {
        author = {
          name = ""
        },
        title = UnitName("player") .. "--BUGREPORT!!!",
        description = BANETO_GetState(),
        color = 15258703,
        fields = { {
          name = "Profile :scroll:",
          value = profilenameDiscord
        }, {
          name = "Message :clipboard:",
          value = bugreportMsgDiscord
        }, {
          name = "Class :dagger:",
          value = englishClass
        }, {
          name = "Username :lifter:",
          value = usernameDiscord
        }, {
          name = "Player :telescope:",
          value = "X: "..xPlayerDiscord .. " Y: "..yPlayerDiscord .. " Z: "..zPlayerDiscord
        }, {
          name = "Target :telescope:",
          value = "X: "..xTargetDiscord .. " Y: "..yTargetDiscord .. " Z: "..zTargetDiscord .. " ID: " .. xTargetIdDiscord
        }, {
          name = "Zone :map:",
          value = GetZoneText()
        }, {
          name = "Level :star:",
          value = UnitLevel("player")
        }, {
          name = "XP per Hour :checkered_flag:",
          value = BANETO_STAT_XPPERH
        }, {
          name = "Gold :coin:",
          value = goldDiscord
        }, {
          name = "Deaths :skull:",
          value = BANETO_COUNT_DEATH
        }, {
          name = "Free Bagslots :handbag:",
          value = BANETO_GetFreeBagSlots()
        }, {
          name = "Herbs :herb:",
          value = herbs
        }, {
          name = "Ores :rock:",
          value = ores
        }, {
          name = "Leather :ox:",
          value = leather
        }, {
          name = "Session Time: :clock1:",
          value = math.floor(BANETO_GetSessionTime()/60) .. " minutes"
        }, {
          name = "Players near you: :wrestling:",
          value = playersAroundDisc
        } },
        thumbnail = {
          url = ""        },
        footer = {
          text = "Baneto-bot.com",
          icon_url = ""        }
      } }
    }

    local jsonPayload;
    if _internal.Software() == "nn" then
        local JSON = Tinkr.Utils.JSON
        jsonPayload = JSON.encode(tableDiscord)
    elseif _internal.Software() == "tnk" then
        jsonPayload = json.encode(tableDiscord)
    end
    local urltarget = ""    local function callb(status)
       if status and (status == 200 or status == 204) then
            BANETO_PrintSuccess("Sending character & bugreport info to baneto staff...")
       else
            BANETO_PrintError("Something is wrong with the discord webhook for baneto staff reports. ERROR: " .. status)
       end
    end
    BANETO_HttpPost(urltarget,jsonPayload,callb)
end


function _G.BANETO_SurviveSpellsAllowed()

	if BANETO_DEFINED_PROFILE_TYPE == "Traveling" then
		BANETO_SurviveSpellsCast()
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Questing" and BANETO_IsFightBlockedByQuester() then
		BANETO_SurviveSpellsCast()
	end
	if BANETO_State == "FP-TAXI" or BANETO_State == "FP-DISCOVER" or BANETO_State == "PROFTRAIN" or BANETO_State == "TRAIN" or BANETO_State == "HS-BIND"  then
		BANETO_SurviveSpellsCast()
	end
	if BANETO_State == "REPAIR" and BANETO_SETTING_REPAIR_IGNOREFIGHTS and BANETO_SETTING_REPAIR_IGNOREFIGHTS == true then
		BANETO_SurviveSpellsCast()
	end
	if not CRECHE_ROLE and not _G.BLOCK_FLEE_FEIGNDEATH and BANETO_STOPFIGHT_EVADE and BANETO_STOPFIGHT_EVADE > GetTime() then
		BANETO_SurviveSpellsCast()
	end
end

function _G.BANETO_LoadFishy(typeFish)
	if not typeFish then typeFish = "spot" end
	if typeFish == "spot" then
		BANETO_DefineProfileName("Spot-Fishing")
		BANETO_DefineProfileType("Fishing")
		BANETO_DEFINED_PROFILE_TYPE = "Fishing"
        BANETO_FISH_SPOT_X, BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z = nil,nil,nil
        BANETO_FISH_SPOT_ANGLE = nil
		BANETO_CheckVendors()
	elseif typeFish == "skill" then
		BANETO_DefineProfileName("Skill-Fishing")
		BANETO_DefineProfileType("Fishing")
		BANETO_DEFINED_PROFILE_TYPE = "Fishing"
		BANETO_CheckVendors()
	end

end

function _G.BANETO_Interact(unit)
    if (not BANETO_INTERACT_DELAYTIMER or BANETO_INTERACT_DELAYTIMER < GetTime()) and BANETO_IsUnitInteractable(unit)   then
        BANETO_StopMovement()
        ObjectInteract(unit)
        local name = BANETO_ObjectName(unit)
        local distance = GetDistanceBetweenObjects("player",unit)
        if name and distance then
            BANETO_PrintBambo("Interacting with: "..name.. " with distance: "..distance)
        end
        BANETO_INTERACT_DELAYTIMER = GetTime()+2.5
    end
end

function _G.BANETO_InteractNoDelay(unit)
    if (not BANETO_INTERACT_SMALLDELAYTIMER or BANETO_INTERACT_SMALLDELAYTIMER < GetTime()) and BANETO_IsUnitInteractable(unit)   then
        BANETO_StopMovement()
        ObjectInteract(unit)
        local name = BANETO_ObjectName(unit)
        local distance = GetDistanceBetweenObjects("player",unit)
        if name and distance then
            BANETO_PrintBambo("Interacting with no delay: "..name .. " with distance: "..distance)
        end
        BANETO_INTERACT_SMALLDELAYTIMER = GetTime()+0.5
    end
end

