function _G.BANETO_WMB_BobberTest()
    local x,y,z = ObjectPosition("player")
    local radius = 25
    for i = 1, countWMB do
        local object = GetObjectWithIndex(i)
        local x2,y2,z2 = ObjectPosition(object)
        local distance = GetDistanceBetweenPositions(x,y,z,x2,y2,z2)
        local objectId = ObjectID(object)
        if x and x2 then
            if distance < radius and objectId == 35591 then
                print("testbibber")
                return wmbapi.ObjectField(object, 100, "AnimationState")
            end
        end
    end
end


function _G.BANETO_WMB_BobberCheck(object)
    if _internal.Software() == "tnk" then
        local flags, animationFlags = ObjectFlags(object)
        if (animationFlags == 1 and ObjectCreator(object) == BANETO_Object("player")) or BANETO_BOBBERTINK then
            BANETO_BOBBERTINK = true
            return true
        end
    else
        if PlayerObject() == ObjectCreator(object) then
            if BANETO_IsJin() then
                if PlayerObject() == ObjectCreator(object) then
                    if (FishingBobber(object) == 1 or ObjectAnimationFlag(object) == 1) then
                        return true
                    end
                end
            else
                if (FishingBobber(object) or ObjectAnimationFlag(object)) then
                    return true
                end
            end
        end
   end
end

function _G.BANETO_InteractWithBobber()
	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS
		local x,y,z = BANETO_ObjectPosition("player")
		local radius = 25
		for i = 1, #objects do
			local object = objects[i]
			local objectId = ObjectId(object)
            BANETO_BOBBERTINK = nil
            if (objectId == 35591 or objectId == 245190) and ObjectCreator(object) == BANETO_Object("player") then
                return BANETO_Interact(object)
            end
