end

function _G.BANETO_GetBobberPosition()
	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS
        local x,y,z = BANETO_ObjectPosition("player")
		local radius = 45
		for i = 1, #objects do
			local object = objects[i]
			local objectId = BANETO_ObjectId(object)
			if x and objectId == 35591 then
                local x2,y2,z2 = BANETO_ObjectPosition(object)
                local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                local wobber = BANETO_WMB_BobberCheck(object)
				if distance and distance < radius and ObjectCreator(object) == BANETO_Object("player") then
					return x2,y2,z2
				end
			end
		end
	end
end

function _G.BANETO_GetBobberState()
	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS
		local x,y,z = BANETO_ObjectPosition("player")
		local radius = 45
		for i = 1, #objects do
			local object = objects[i]
			local objectId = BANETO_ObjectId(object)
			if x and (objectId == 35591 or objectId == 245190) then
                local x2,y2,z2 = BANETO_ObjectPosition(object)
                local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                local wobber = BANETO_WMB_BobberCheck(object)
				if distance and distance < radius and wobber == true and ObjectCreator(object) == BANETO_Object("player") then
					return true
				end
			end
		end
	end

end

function _G.BANETO_AttemptCombatLooting()

	if BANETO_COMBATLOOTTARGET then
		if Unlocker("LUA")  then
			if not ObjectLootable(BANETO_COMBATLOOTTARGET) then
				BANETO_COMBATLOOTTARGET = nil
			end
		elseif Unlocker("LUA") and CallSecureFunction then
			if not UnitIsLootable(BANETO_COMBATLOOTTARGET) then
				BANETO_COMBATLOOTTARGET = nil
			end
		elseif Unlocker("EWT") then
			if not UnitCanBeLooted(BANETO_COMBATLOOTTARGET) then
				BANETO_COMBATLOOTTARGET = nil
			end
		end
	end



    if StaticPopup1:IsVisible() and (not BANETO_LOOTING_POPUPCLICK_DELAY or BANETO_LOOTING_POPUPCLICK_DELAY < GetTime()) then
        BANETO_LOOTING_POPUPCLICK_DELAY = GetTime() + 3
        --StaticPopup1Button1:Click()
        ConfirmLootSlot(1)
        ConfirmLootSlot(2)
        ConfirmLootSlot(3)
        ConfirmLootSlot(4)
        ConfirmLootSlot(5)
        ConfirmLootSlot(6)
    end
	if not BANETO_COMBATLOOTTARGET then
		BANETO_COMBATLOOTTARGET = BANETO_SCAN_COMBATLOOT()
	else
		if Unlocker("LUA") then
			local x,y,z = BANETO_ObjectPosition(BANETO_COMBATLOOTTARGET)
			if not BANETO_PlayerPosition(x,y,z,3.5) then
			    if not UnitCastingInfo("player") and not UnitChannelInfo("player") then
				    BANETO_MeshTo(x,y,z)
                end
			else
				if not LootFrame:IsVisible() then
					BANETO_Interact(BANETO_COMBATLOOTTARGET)
					BANETO_COMBATLOOTTARGET = nil
					BANETO_LOOT_DELAY = GetTime() + 1.6
				end
			end
		elseif Unlocker("EWT") then
			local x,y,z = ObjectPosition(BANETO_COMBATLOOTTARGET)
			if not BANETO_PlayerPosition(x,y,z,3.5) then
				BANETO_MeshTo(x,y,z)
			else
				if not LootFrame:IsVisible() then
					ObjectInteract(BANETO_COMBATLOOTTARGET)
					BANETO_COMBATLOOTTARGET = nil
					BANETO_LOOT_DELAY = GetTime() + 1.6
				end
			end
		end
		return true
	end
end

_G.BANETO_MULTIPULL_RADIUS = 70

function _G.BANETO_RetailMultipullEnoughTargets()
    if not BANETO_SETTING_ACTIVEENGAGE or BANETO_SETTING_ACTIVEENGAGE == false then
        if not _G.MULTIPULL_ACTIVE_ENGAGE_IS_DISABLED then
            return true
        end
    end
    if BANETO_DEFINED_PROFILE_TYPE ~= "Grinding" then
        return true
    end
    if UnitAffectingCombat("player") and (BANETO_SCAN_SKINNING() or BANETO_SCAN_LOOT()) then
        BANETO_PrintBambo("Retail multipull: CASE A")
        --return true
    end
    if not BANETO_NOTENOUGH_POTENTIAL_MULTIPULLS or BANETO_NOTENOUGH_POTENTIAL_MULTIPULLS < GetTime() then
        BANETO_NOTENOUGH_POTENTIAL_MULTIPULLS = GetTime()+0.5
        local x, y, z = BANETO_ObjectPosition("player")
        local radius = BANETO_MULTIPULL_RADIUS
        local potentialTarget = BANETO_SCAN(x, y, z, radius)
        if not potentialTarget and not BANETO_TARGET then
            BANETO_PrintBambo("Retail multipull: CASE B")
            return true
        end
    end

    if BANETO_SETTING_MULTIPULL_COUNT and BANETO_SETTING_MULTIPULL_COUNT > 1 then
        local numEnemies = GetNumEnemiesAroundUnit("player",100)
        if numEnemies and numEnemies >= BANETO_SETTING_MULTIPULL_COUNT then
            BANETO_PrintBambo("Retail multipull: CASE C")
            return true
        end
    else
        BANETO_PrintBambo("Retail multipull: CASE D")
        return true
    end
end

function _G.BANETO_ClickBetweenMeAndTarget(distance)
    if not distance then
        distance = 10
    end
    if UnitExists("target") then
        local x,y,z = BANETO_ObjectPosition("target")
        local angle = BANETO_GetFacingValue(x,y,z)
        if angle then
            local clickX,clickY,clickZ = BANETO_GetPointInfrontOfUsAngleWithDistance(distance,angle)
            BANETO_ClickPosition(clickX,clickY,clickZ)
        end
    end
end

