function _G.CancelBuff(id)
    if Unlocker("LUA") and id then
        for i = 1, 32 do
            local nameBuffOnPlayer,_,_,_,_,_,_,_,_,buffOnPlayer,_,_,_,_,_ = UnitBuffWrapper("player", i)
            if buffOnPlayer then
                if buffOnPlayer == id then
                    if _internal.Software() == "nn" then
                        Unlock("CancelUnitBuff","player",i)
                    end
                    if _internal.Software() == "tnk" then
                        Eval("CancelUnitBuff('player',".. i .. ")","ss")
                    end
                end
                local spellInfo = C_Spell.GetSpellInfo(id)
                if nameBuffOnPlayer == spellInfo.name then
                    if _internal.Software() == "nn" then
                        Unlock("CancelUnitBuff","player",i)
                    end
                    if _internal.Software() == "tnk" then
                        Eval("CancelUnitBuff('player',".. i .. ")","ss")
                    end
                end
            end
        end
    end
end

