function _G.BANETO_UsePetFeedItem()
	if not BANETO_PETFEED_DELAY or BANETO_PETFEED_DELAY < GetTime() and not BANETO_HasBuff("pet",1539) and not BANETO_IsDrinking() and not BANETO_IsEating() then
		BANETO_PETFEED_DELAY = GetTime()+4
		local foodTypes = GetPetFoodTypes()
		for q = 1, 6 do
			local foodType = select(q,GetPetFoodTypes())
			if foodType then
				for y = 1, #BANETO_ITEMS_PETFOOD[foodType] do
					local petfoodId, petfoodLvl = BANETO_ITEMS_PETFOOD[foodType][y][1],BANETO_ITEMS_PETFOOD[foodType][y][2]
					for i = 0, NUM_BAG_SLOTS+1 do
						for z = 1, GetContainerNumSlots(i) do
							local id = GetContainerItemID(i, z)
							if not petfoodLvl then petfoodLvl = 1 end
							if id == petfoodId and UnitLevel("pet") >= petfoodLvl-5  and UnitLevel("pet")-petfoodLvl <= 30 then
                            if Unlocker("LUA") and _internal.Software() == "tnk" then
                                Eval("C_Container.UseContainerItem(" ..i .. "," .. z .. ")","somth")
                            end
                            if Unlocker("LUA") and _internal.Software() == "nn" then
                                --Unlock("C_Container.UseContainerItem",i,z)
                                Unlock("pcall", C_Container.UseContainerItem, i, z)
                            end
								BANETO_PrintState("[BUFF] Feeding Pet " .. petfoodId .. " and waiting for happyness")
								return true
							end
						end
					end
				end
			end
		end
	end

end

