function _G.BANETO_GetTotalStashableItemCount()
    local counter = 0
    if BANETO_SETTING_GBANK_CLOTH and BANETO_SETTING_GBANK_CLOTH == true then
        for i = 1,#BANETO_ITEMS_CLOTH do
            local itemCount = GetItemCount(BANETO_ITEMS_CLOTH[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_STOREGEMS and BANETO_SETTING_GBANK_STOREGEMS == true then
        for i = 1,#BANETO_ITEMS_GEMS do
            local itemCount = GetItemCount(BANETO_ITEMS_GEMS[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_MEATFISH and BANETO_SETTING_GBANK_MEATFISH == true then
        for i = 1,#BANETO_ITEMS_FISHMEAT do
            local itemCount = GetItemCount(BANETO_ITEMS_FISHMEAT[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_LEATHER and BANETO_SETTING_GBANK_LEATHER == true then
        for i = 1,#BANETO_ITEMS_LEATHER do
            local itemCount = GetItemCount(BANETO_ITEMS_LEATHER[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_ORES and BANETO_SETTING_GBANK_ORES == true then
        for i = 1,#BANETO_ITEMS_ORES do
            local itemCount = GetItemCount(BANETO_ITEMS_ORES[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_HERBS and BANETO_SETTING_GBANK_HERBS == true then
        for i = 1,#BANETO_ITEMS_HERBS do
            local itemCount = GetItemCount(BANETO_ITEMS_HERBS[i])
            counter = counter + itemCount
        end
    end
    if BANETO_SETTING_GBANK_STORECUSTOMS and BANETO_SETTING_GBANK_STORECUSTOMS == true then
        if BANETO_SETTING_STORE_ITEMS then
            for i = 1,#BANETO_SETTING_STORE_ITEMS do
                local itemCount = GetItemCount(BANETO_SETTING_STORE_ITEMS[i])
                counter = counter + itemCount
            end
        end
    end
    return counter
end

function _G.BANETO_FindItemIdByName(name)
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local id = GetContainerItemID(i, z)
            if id then
                local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(id)
                if itemName == name then
                    return id
                end
            end
        end
    end
end

function _G.BANETO_GetNextStashableItemId()
    if BANETO_SETTING_STORE_ITEMS and BANETO_SETTING_GBANK_STORECUSTOMS and BANETO_SETTING_GBANK_STORECUSTOMS == true then
        for i = 1,#BANETO_SETTING_STORE_ITEMS do
            local itemname = BANETO_SETTING_STORE_ITEMS[i]
            local id = BANETO_FindItemIdByName(itemname)
            if id then
                local itemCount = GetItemCount(id)
                if itemCount and itemCount >= 1 then
                    return id
                end
            end
        end
    end
    if BANETO_SETTING_GBANK_CLOTH and BANETO_SETTING_GBANK_CLOTH == true then
        for i = 1,#BANETO_ITEMS_CLOTH do
            local itemCount = GetItemCount(BANETO_ITEMS_CLOTH[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_CLOTH[i]
            end
        end
    end
    if BANETO_SETTING_GBANK_STOREGEMS and BANETO_SETTING_GBANK_STOREGEMS == true then
        for i = 1,#BANETO_ITEMS_GEMS do
            local itemCount = GetItemCount(BANETO_ITEMS_GEMS[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_GEMS[i]
            end
        end
    end
    if BANETO_SETTING_GBANK_MEATFISH and BANETO_SETTING_GBANK_MEATFISH == true then
        for i = 1,#BANETO_ITEMS_FISHMEAT do
            local itemCount = GetItemCount(BANETO_ITEMS_FISHMEAT[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_FISHMEAT[i]
            end
        end
    end
    if BANETO_SETTING_GBANK_LEATHER and BANETO_SETTING_GBANK_LEATHER == true then
        for i = 1,#BANETO_ITEMS_LEATHER do
            local itemCount = GetItemCount(BANETO_ITEMS_LEATHER[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_LEATHER[i]
            end
        end
    end
    if BANETO_SETTING_GBANK_ORES and BANETO_SETTING_GBANK_ORES == true then
        for i = 1,#BANETO_ITEMS_ORES do
            local itemCount = GetItemCount(BANETO_ITEMS_ORES[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_ORES[i]
            end
        end
    end
    if BANETO_SETTING_GBANK_HERBS and BANETO_SETTING_GBANK_HERBS == true then
        for i = 1,#BANETO_ITEMS_HERBS do
            local itemCount = GetItemCount(BANETO_ITEMS_HERBS[i])
            if itemCount and itemCount >= 1 then
                return BANETO_ITEMS_HERBS[i]
            end
        end
    end
end
_G.BANETO_SETTING_STASHING_AMOUNT = 200
_G.BANETO_SETTING_STASHING_GOLD_TRIGGER = 0
function _G.BANETO_IsStashingNeeded()
    local stashCount = BANETO_GetTotalStashableItemCount()
    if stashCount and stashCount > _G.BANETO_SETTING_STASHING_AMOUNT then
        return true
    end
    local epicItemCount = 0
    if epicItemCount and epicItemCount >= 1 and BANETO_SETTING_GBANK_EPICS and BANETO_SETTING_GBANK_EPICS == true then
        return true
    end
    local gold = math.floor(GetMoney()/10000)
    local keepGold = _G.BANETO_STASHING_KEEP_GOLD or 500
    if _G.BANETO_SETTING_STASHING_GOLD_TRIGGER and _G.BANETO_SETTING_STASHING_GOLD_TRIGGER > keepGold and gold >= _G.BANETO_SETTING_STASHING_GOLD_TRIGGER  then
        return true
    end
    return false
end

function _G.BANETO_StashItemsInGuildChest()
    BANETO_PrintDev("Stash Item Func")
    if MerchantFrame:IsVisible() then
        BANETO_PrintWarning("Stashing blocked, vendor menu is open!")
        return false
    end
    if not BANETO_STASH_DELAY then
        BANETO_STASH_DELAY=GetTime()+1
    end
    if BANETO_STASH_DELAY < GetTime() then
        BANETO_STASH_DELAY = GetTime()+0.1

        local money = GetMoney()
        local gold = math.floor(GetMoney()/10000)
        local keepGold = _G.BANETO_STASHING_KEEP_GOLD or 500
        if gold and gold > keepGold and (not depositDelay or depositDelay < GetTime()) and BANETO_SETTING_GBANK_STOREGOLD == true then
            local deposit = gold - keepGold
            DepositGuildBankMoney(deposit*100)
            depositDelay = GetTime()+30
        end

        local itemId = BANETO_GetNextStashableItemId()
        if itemId then
            BANETO_UseItem(itemId)
        end
    end
end

