function _G.BANETO_IsSomeoneTargetingUs(forced)
    if Unlocker("LUA")  then
        local objects = BANETO_OBJTS_TKR_ONLYPLAYERS

        for i=1, #objects do
            local object = objects[i]
            if BANETO_UnitTarget(object) == BANETO_Object("player") and UnitIsPlayer(object) and (not BANETO_IS_TARGETING_US_SCANDELAY or  GetTime() > BANETO_IS_TARGETING_US_SCANDELAY ) then
                BANETO_IS_TARGETING_US_SCANDELAY = GetTime()+2
                if  not UnitAffectingCombat("player") and BANETO_SETTING_SECURITY_IDLEONTARGET and BANETO_SETTING_SECURITY_IDLEONTARGET == true and  (not BANETO_SETTING_SECURITY_IDLEONTARGET_DELAY_MASTER or BANETO_SETTING_SECURITY_IDLEONTARGET_DELAY_MASTER < GetTime()) then
                    BANETO_SETTING_SECURITY_IDLEONTARGET_NEEDED = true
                    BANETO_SETTING_SECURITY_IDLEONTARGET_DELAY_MASTER = GetTime()+90
                    BANETO_LAST_SHERLOCK = BANETO_ObjectName(object)
                end
                if BANETO_SETTING_SECURITY_STEALTHONTARGET and BANETO_SETTING_SECURITY_STEALTHONTARGET == true then
                    BANETO_SETTING_SECURITY_STEALTHONTARGET_NEEDED = true
                    BANETO_LAST_SHERLOCK = BANETO_ObjectName(object)
                end
                if BANETO_SETTING_SECURITY_SOUNDONTARGET and BANETO_SETTING_SECURITY_SOUNDONTARGET == true then
                    BANETO_SETTING_SECURITY_SOUNDONTARGET_NEEDED = true
                    BANETO_LAST_SHERLOCK = BANETO_ObjectName(object)
                end
                if BANETO_SETTING_DISCORD_TARGETED and BANETO_SETTING_DISCORD_TARGETED == true and (not BANETO_DISCORD_TARGET_NOTIFIER_DELAY or GetTime() > BANETO_DISCORD_TARGET_NOTIFIER_DELAY) then
                    BANETO_LAST_SHERLOCK = BANETO_ObjectName(object)
                    if not BANETO_LAST_SHERLOCK then
                        BANETO_LAST_SHERLOCK = "Someone"
                    end
                    BANETO_DiscordSendTargeted(BANETO_LAST_SHERLOCK)
                    BANETO_DISCORD_TARGET_NOTIFIER_DELAY = GetTime()+15
                end
                if vtf_setup or forced then
                    return true,BANETO_ObjectName(object)
                end
            end
        end
    end
end

