function _G.BANETO_IsPetLuabox(unitId)
	if Unlocker("LUA") and unitId then
	    local creator = ObjectCreator(unitId)
        if creator and UnitIsPlayer(creator) and (not BANETO_SETTING_TARGET_PETS or BANETO_SETTING_TARGET_PETS == false) then
            return true
        end
        if _internal.Software() == "nn" then
            --local creator2 = UnitCreator(unitId)
            --if creator2 and UnitIsPlayer(creator2) and (not BANETO_SETTING_TARGET_PETS or BANETO_SETTING_TARGET_PETS == false) then
                --return true
            --end
            local creator3 = UnitSummoner(unitId)
            if creator3 and UnitIsPlayer(creator3) and (not BANETO_SETTING_TARGET_PETS or BANETO_SETTING_TARGET_PETS == false) then
                return true
            end
        end
		local id = BANETO_ObjectId(unitId)
		if id == 9623 or id == 1860 or id == 1861 or id == 1862 or id == 1863 or id == 1864  then
			return true
		end

        for i = 1, 40 do
            local u = BANETO_ObjectToUnit(unitId)
            local auraData = C_UnitAuras.GetAuraDataByIndex(u,i);
            if auraData then
                k = auraData.spellId
                if k then
                    if k == 19581 or k == 65220  or k == 308635 or k == 119904 or k == 21740 or k == 62137 or k == 147358  or k == 295881 or k == 18740 or k == 18741 or k == 19480 or k == 21921 or k == 3716 or k == 18739 or k == 19007 or k == 18730 or k == 19480 or k == 18738 then
                        if BANETO_SETTING_TARGET_PETS == false then
                            return true
                        end
                    end
                end
            end
        end

        if UnitIsOtherPlayersPet and UnitIsOtherPlayersPet("target") then
            return true
        end
		return false
    end
end

