function _G.BANETO_HasPetFeedItem()
	local foodTypes = GetPetFoodTypes()
	for q = 1, 6 do
		local foodType = select(q,GetPetFoodTypes())
		if foodType then
            local foodTypeTable = BANETO_ITEMS_PETFOOD[foodType]
            if foodTypeTable then
                for y = 1, #BANETO_ITEMS_PETFOOD[foodType] do
                    local petfoodId, petfoodLvl = BANETO_ITEMS_PETFOOD[foodType][y][1],BANETO_ITEMS_PETFOOD[foodType][y][2]
                    for i = 0, NUM_BAG_SLOTS+1 do
                        for z = 1, GetContainerNumSlots(i) do
                            local id = GetContainerItemID(i, z)
                            if not petfoodLvl then petfoodLvl = 1 end
                            if id == petfoodId and UnitLevel("pet") >= petfoodLvl-5 and UnitLevel("pet")-petfoodLvl <= 30 and not BANETO_HasBuff("pet",1539) then
                                return true
                            end
                        end
                    end
                end
            end
		end
	end
end

function _G.BANETO_GetItemLocInBags(itemId,minAmount)
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local id = GetContainerItemID(i, z)
            if id == itemId then
                --print("SALVAGE MATCH: ".. id .. " with i: "..i .. " and z: ".. z)
                local containerItemInfo = GetContainerItemInfo(i, z)
                local itemCount = containerItemInfo["stackCount"]
                if not minAmount or (itemCount and itemCount >= minAmount) then
                    local itemLoc = ItemLocation:CreateFromBagAndSlot(i,z)
                    if itemLoc and itemLoc:IsValid() then
                        return itemLoc
                    end
                end
            end
        end
    end
end

