function _G.BANETO_ShouldSalvage()
    local check = BANETO_SETTING_SALVAGE_RECIPE
    if check and check ~= "nostringinput" and check ~= "" and check ~= " " and tonumber(check) ~= nil then
        local salvagables = C_TradeSkillUI.GetSalvagableItemIDs(tonumber(check))
        for i=1,#salvagables do
            local salvagable = salvagables[i]
            local loc = BANETO_GetItemLocInBags(salvagable,5)
            if loc then
                return true
            end
        end
    end
