function _G.BANETO_DfSalvage(spell)
    local salvagables = C_TradeSkillUI.GetSalvagableItemIDs(spell)
    BANETO_Print("Salvage spell id: "..spell)
    for i=1,#salvagables do
        local salvage = salvagables[i]
        local count = GetItemCount(salvage)
        if count and count > 0 then
            local loc = BANETO_GetItemLocInBags(salvage,5)
            if loc then
                BANETO_Print("Salvage item id: ".. salvage)
                BANETO_UpdateLastHardware()
                if _internal.Software() == "tnk" then
                    C_TradeSkillUI.CraftSalvage(spell,1,loc)
                    --Eval("C_TradeSkillUI.CraftSalvage(" ..spell .. ",1," .. loc .. ")","somth")
                else
                    LastHardwareAction(GetTime()*1000)
                    Unlock(C_TradeSkillUI.CraftSalvage, spell, 1, loc)
                end
                return
            end
        end
    end
end
