function _G.BANETO_UseItem(itemid,needsdismount)
	if IsMounted() and needsdismount then
		BANETO_Dismount()
	end
	if not BANETO_USEITEM_DELAYER or BANETO_USEITEM_DELAYER < GetTime() then
	    if BANETO_GetState() == "STASHING" then
	        BANETO_USEITEM_DELAYER = GetTime()+0.1
	    else
	        BANETO_USEITEM_DELAYER = GetTime()+1
	    end
		BANETO_PrintState("Use item: "..itemid)
		if Unlocker("LUA") and (not MailFrame or not MailFrame:IsVisible()) and (not SendMailFrame or not SendMailFrame:IsVisible())  then
            if not MerchantFrame:IsVisible() then
                local form = GetShapeshiftForm()
                local _,_,class = UnitClass("player")
                if form == 0 or ((form == 1 or form == 2 or form == 3) and class == 1)  or (class == 5 and form == 1) or (class == 2 and (form == 1 or form == 2))  or (class == 4) or (class == 6) then
                    for i = 0, NUM_BAG_SLOTS+1 do
                        for z = 1, GetContainerNumSlots(i) do
                            local id = GetContainerItemID(i, z)
                            if id == itemid then
                                if Unlocker("LUA") and _internal.Software() == "tnk" then
                                    Eval("C_Container.UseContainerItem(" ..i .. "," .. z .. ")","somth")
                                end
                                if Unlocker("LUA") and _internal.Software() == "nn" then
                                    --Unlock("C_Container.UseContainerItem",i,z)
                                    Unlock("pcall", C_Container.UseContainerItem, i, z)
                                end
                                return true
                            end
                        end
                    end
                else
                    if needsdismount then
                        BANETO_CancelShapeshift()
                        BANETO_Print("Cancel shapeshift for item usage.")
                    end
                    for i = 0, NUM_BAG_SLOTS+1 do
                        for z = 1, GetContainerNumSlots(i) do
                            local id = GetContainerItemID(i, z)
                            if id == itemid then
                                BANETO_UseContainerItem(i, z)
                                return true
                            end
                        end
                    end
                end
            end
        else
            BANETO_PrintWarning("Using items is blocked because mailbox ui is open.")
        end
	end
end

function _G.BANETO_GetProfessionSkill(name)

	for i=1,GetNumSkillLines() do
		local skillName, isHeader, isExpanded, skillRank, numTempPoints, skillModifier,
			skillMaxRank, isAbandonable, stepCost, rankCost, minLevel, skillCostType,
			skillDescription = GetSkillLineInfo(i)
		if skillName == name then
			return skillRank,skillMaxRank
		end

	end

end

