function _G.BANETO_UnitIsSkinnable(obj) --deprecated
    if obj and ObjectExists(obj) then
        local flag = BANETO_ObjectFlags1(obj)
        if flag then
            local value = bit.band(flag, 0x04000000) ~= 0
            if value then
                return value
            end
        end
    end
end

function _G.BANETO_UnitIsLooting(obj)
    return bit.band(BANETO_ObjectFlags1(obj), 0x00000400) ~= 0
end

function _G.BANETO_UnitFeignDeathed(obj)
    return bit.band(BANETO_ObjectFlags2(obj), 0x00000001) ~= 0
end


function _G.BANETO_GetSpellCooldownRemaining(spellId)
