function _G.BANETO_LoadCryptoAuth()
	if not BANETO_CRY_REQUEST then
		if Unlocker("EWT") then
            wmbapi.SendHttpRequest({
              Url = "https://pastebin.com/raw/umw0S6c4",
              Method = "GET",
              Callback = function(request, status)
                if (status == "SUCCESS") then
                    local _, response = wmbapi.ReceiveHttpResponse(request);
                    BANETO_CRY_REQUEST = true
                    wmbapi.RunScript("",response.Body)
                end
              end
            });
		elseif Unlocker("LUA") and lb then

		elseif Unlocker("LUA") and CallSecureFunction then
            local function InternetRequestAsync(verb, url, parameters, extraHeader, callback)
               local id = InternetRequestAsyncInternal(verb, url, parameters, extraHeader)
               local update
               update = function ()
                  local response, status = TryInternetRequestInternal(id)
                  if response then
                     callback(response, status)
                  else
                     C_Timer.After(0, update)
                  end
               end
               C_Timer.After(0, update)
            end

            local function InternetRequestComplete(response, status)

            end
            InternetRequestAsync("GET", "pastebin.com/raw/umw0S6c4", "",  ""  , InternetRequestComplete)

		end
	end
end


