		if Unlocker("EWT") then
            wmbapi.SendHttpRequest({
              Url = "https://kakashisbanetoprofiles.com/Auth/kakashiauth.lua",
              Method = "GET",
              Callback = function(request, status)
                if (status == "SUCCESS") then
                    local _, response = wmbapi.ReceiveHttpResponse(request);
                    BANETO_KAK_REQUEST = true
                    wmbapi.RunScript("",response.Body)
                end
              end
            });
		elseif Unlocker("LUA") and lb then
			__LB__.HttpAsyncGet("kakashisbanetoprofiles.com", 443, true, "/Auth/kakashiauth.lua",
				function(x)
					if x then
						__LB__.RunString(x)
						BANETO_KAK_REQUEST = true
					end
				end,
				function(y)
				end
			)
		elseif Unlocker("LUA") and CallSecureFunction then
            local function InternetRequestAsync(verb, url, parameters, extraHeader, callback)
               local id = InternetRequestAsyncInternal(verb, url, parameters, extraHeader)
               local update
               update = function ()
                  local response, status = TryInternetRequestInternal(id)
                  if response then
                     callback(response, status)
                  else
                     C_Timer.After(0, update)
                  end
               end
               C_Timer.After(0, update)
            end

            local function InternetRequestComplete(response, status)

            end
            InternetRequestAsync("GET", "kakashisbanetoprofiles.com/Auth/kakashiauth.lua",  "",""  , InternetRequestComplete)
		end
	end
end

function _G.BANETO_IsMiningNode(id)
    for i = 1, #BANETO_OBJECTS_ORES do
        local tableid, minlvl, _ = BANETO_OBJECTS_ORES[i][1],BANETO_OBJECTS_ORES[i][2],BANETO_OBJECTS_ORES[i][3]
        if tableid == id then
            return true
        end
    end
end

function _G.BANETO_FindMountInBags()

	for k = 1, #BANETO_MOUNTS do
		local mount = BANETO_MOUNTS[k]
		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				local id = GetContainerItemID(i, z)
				if id == mount then
					return id
				end
			end
		end
	end

end

function _G.BANETO_RetailMountRangeCheck()
    if BANETO_FLYING_PROFILE and BANETO_FLYING_PROFILE == true and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) and not IsMounted() and not IsFlying() then
        return true
    end
    if Unlocker("LUA") then
        local destination = BANETO_GetLuaBoxDestination()
        if destination and BANETO_LUABOX_DESTINATION and  BANETO_LUABOX_DESTINATION[1] and BANETO_LUABOX_DESTINATION[2] and BANETO_LUABOX_DESTINATION[3] then
            local xP,yP,zP = BANETO_ObjectPosition("player")
            local distance = BANETO_GetDistance3D(xP,yP,zP,destination[1],destination[2],destination[3])
            if distance and distance > 60 then
                return true
            end
        end
    elseif Unlocker("EWT") then
        if BANETO_EWT_DESTINATION and  BANETO_EWT_DESTINATION[1] and BANETO_EWT_DESTINATION[2] and BANETO_EWT_DESTINATION[3] then
            local xP,yP,zP = ObjectPosition("player")
            local distance = GetDistanceBetweenPositions(xP,yP,zP,BANETO_EWT_DESTINATION[1],BANETO_EWT_DESTINATION[2],BANETO_EWT_DESTINATION[3])
            if distance and distance > 60 then
                return true
            end
        end
    end
    return false
end

function _G.BANETO_LuaboxUnstucker()
	if BANETO_ONCHOPPER and BANETO_ONCHOPPER == true then
		return false
	end

	--ACT ON TOO MANY JUMPS
	if BANETO_LUABOXUNSTUCK_JUMPCOUNT then
        local startTime, duration, enable = GetItemCooldown(6948)
        local _, _, class = UnitClass("player")
		if BANETO_LUABOXUNSTUCK_JUMPCOUNT >= 4 and not BANETO_UNSTUCKING_CANCELSHAPESHIFT_BLOCK and (IsMounted() or (class == 11 and GetShapeshiftDruid() ~= 0) or (BANETO_TARGET and BANETO_State ~= "FP-DISCOVER")) then
		    local _, _, class = UnitClass("player")
			if IsMounted() or (class == 11 and GetShapeshiftDruid() ~= 0)  then
                if GetShapeshiftDruid() ~= 0 then
                    CancelShapeshift()
                end
				BANETO_LUABOXUNSTUCK_JUMPCOUNT = nil

				BANETO_Dismount()
				BANETO_StopMovement()
				if BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK== true then
				    BANETO_PrintState("Dismount/Cancel Shapeshift to Unstuck! Blacklisting mounting for 20 Seconds!")
				    BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+20
				else
				    BANETO_PrintState("Dismount/Cancel Shapeshift to Unstuck! Blacklisting mounting for 15 Seconds!")
				    BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+16
				end
                if Unlocker("LUA") and _internal.Software() == "tnk" then
                    Eval("ClearTarget()","asjas")
                end
                if Unlocker("LUA") and _internal.Software() == "nn" then
                    Unlock("ClearTarget","")
                end
			elseif BANETO_TARGET and BANETO_State ~= "FP-DISCOVER" then
				BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
				BANETO_PrintState("Blacklisting GUID - Possible Stuck detected")
				BANETO_LUABOXUNSTUCK_JUMPCOUNT = nil
				BANETO_TARGET = nil
				BANETO_StopMovement()
				if BANETO_State == "GATHER" then
                    if Unlocker("EWT") then
                        BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                    elseif Unlocker("LUA") then
                        BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = BANETO_ObjectPosition("player")
                    end
                    return
				end
			end
	    elseif BANETO_LUABOXUNSTUCK_JUMPCOUNT >= 4  and not MerchantFrame:IsVisible() and not SendMailFrame:IsVisible() and not UnitAffectingCombat("player") and duration and duration == 0 and not BANETO_TARGET and not IsMounted() and BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true and (class ~= 11 or GetShapeshiftDruid() == 0 or BANETO_UNSTUCKING_CANCELSHAPESHIFT_BLOCK) then
	        BANETO_EMERGENCY_STUCK_HS = true
	        BANETO_LUABOXUNSTUCK_JUMPCOUNT = nil
		end
	end

	if not  BANETO_LUABOXUNSTUCK_DELAY or  BANETO_LUABOXUNSTUCK_DELAY < GetTime() then
		BANETO_LUABOXUNSTUCK_DELAY = GetTime()+0.15
		if not BANETO_LUABOX_LAST_X then
			BANETO_LUABOX_LAST_X, BANETO_LUABOX_LAST_Y, BANETO_LUABOX_LAST_Z = BANETO_ObjectPosition("player")
		end
		if BANETO_LUABOX_LAST_X then
			local currentX, currentY, currentz = BANETO_ObjectPosition("player")
			if BANETO_GetDistance3D(currentX, currentY, currentz,BANETO_LUABOX_LAST_X, BANETO_LUABOX_LAST_Y, BANETO_LUABOX_LAST_Z) < 2 then
				if not BANETO_LUABOXUNSTUCK_COUNT then
					BANETO_LUABOXUNSTUCK_COUNT = 0
				end
				BANETO_LUABOXUNSTUCK_COUNT = BANETO_LUABOXUNSTUCK_COUNT+1
			else
				BANETO_LUABOXUNSTUCK_COUNT=nil
			end
			if BANETO_LUABOXUNSTUCK_COUNT == 5 then
				BANETO_LUABOXUNSTUCK_COUNT = nil
				if not BANETO_LUABOXUNSTUCK_JUMPCOUNT then
					BANETO_LUABOXUNSTUCK_JUMPCOUNT = 1
				end
				BANETO_LUABOXUNSTUCK_JUMPCOUNT = BANETO_LUABOXUNSTUCK_JUMPCOUNT+1
				BANETO_LUABOX_LAST_X = nil
				BANETO_LUABOX_LAST_Y = nil
				BANETO_LUABOX_LAST_Z = nil
				BANETO_JumpAllowed = true
				if not IsSwimming() then

					--[[ BANETO_StopMovement() --]]
				end
			end
		end
	end
	if not BANETO_LUABOXUNSTUCK_RESETDELAY then
		BANETO_LUABOXUNSTUCK_RESETDELAY = GetTime()+3
	end
	if BANETO_LUABOXUNSTUCK_RESETDELAY < GetTime() then
		BANETO_LUABOXUNSTUCK_RESETDELAY = GetTime()+3
		BANETO_LUABOXUNSTUCK_COUNT = nil
		BANETO_LUABOX_LAST_X = nil
		BANETO_LUABOX_LAST_Y = nil
		BANETO_LUABOX_LAST_Z = nil
	end
end

