function _G.BANETO_IsUnitInteractable(unit)
    local obId = BANETO_ObjectId(unit)
    return obId == 35591 or obId == 382075 or obId == 197397 or obId == 245190 or BANETO_Software() == "tnk" or UnitIsInteractable(unit)
end

function _G.BANETO_ObstacleCheckRight()
    local x1,y1,z1 = BANETO_ObjectPosition("player")
    local angle = BANETO_GetObjectFacing("player")
    local first = ""
    if angle >= math.pi then
        angle = angle-(math.pi*0.5)
        first = "right"
    else
        angle = angle+(math.pi*0.5)
        first = "left"
    end
    local helper;
    if first == "right" then
        helper = 13
    else
        helper = -13
    end
    local x2,y2,z2 = BANETO_GetPointInfrontOfUsAngleWithDistance(helper,angle)
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+1, x2,y2,z2+1, hitFlags)
    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
        return true
    else
        return false
    end
end

