function _G.BANETO_CheckUnstuckTriggers()
    if (not CHECK_UNSTUCKTRIGGER_DELAY or GetTime() > CHECK_UNSTUCKTRIGGER_DELAY) and BANETO_UNSTUCK_ROUTES_TABLE and BANETO_ISRUNNING then
        CHECK_UNSTUCKTRIGGER_DELAY = GetTime()+0.4
        local x,y,z = BANETO_ObjectPosition("player")
        for i=1,#BANETO_UNSTUCK_ROUTES_TABLE do
            local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
            local xDraw,zDraw,yDraw = cacheTable[1][1],cacheTable[1][2],cacheTable[1][3]
            local distance = BANETO_GetDistance3D(x,y,z,xDraw,zDraw,yDraw )
            local checkDistance = cacheTable[1][4]
            if not checkDistance then
                checkDistance = 5
            end
            if distance and ((checkDistance > distance and not IsFlying()) or (checkDistance+3 > distance and IsFlying())) then
                if not BANETO_UNSTUCK_ROUTE_LAST or BANETO_UNSTUCK_ROUTE_LAST ~= i then
                    BANETO_UNSTUCK_ROUTE_CURRENT = cacheTable
                    BANETO_UNSTUCK_ROUTE_ISACTIVE = true
                    unstuckRouteIndex = 1
                    BANETO_UNSTUCK_ROUTE_LAST=i
                    waPath = nil
                    flyingPath = nil
                    CHECK_UNSTUCKTRIGGER_DELAY = GetTime()+1
                    BANETO_PrintState("Begin of unstuck route: " .. i)
                    C_Timer.After(300,function() BANETO_UNSTUCK_ROUTE_LAST = nil  end)
                    return true
                end
            end
        end
    end

    if (not CHECK_UNSTUCKTRIGGER_DELAY2 or GetTime() > CHECK_UNSTUCKTRIGGER_DELAY2) and BANETO_UNSTUCK_ROUTES_TABLE_PROFILES  and BANETO_ISRUNNING then
        CHECK_UNSTUCKTRIGGER_DELAY2 = GetTime()+0.4
        local x,y,z = BANETO_ObjectPosition("player")
        for i=1,#BANETO_UNSTUCK_ROUTES_TABLE_PROFILES do
            local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[i]
            local xDraw,zDraw,yDraw = cacheTable[1][1],cacheTable[1][2],cacheTable[1][3]
            local distance = BANETO_GetDistance3D(x,y,z,xDraw,zDraw,yDraw )
            local checkDistance = cacheTable[1][4]
            if not checkDistance then
                checkDistance = 5
            end
            if distance and ((checkDistance > distance and not IsFlying()) or (checkDistance+3 > distance and IsFlying())) then
                if not BANETO_UNSTUCK_ROUTE_LAST_PROFILE or BANETO_UNSTUCK_ROUTE_LAST_PROFILE ~= i then
                    BANETO_UNSTUCK_ROUTE_CURRENT = cacheTable
                    BANETO_UNSTUCK_ROUTE_ISACTIVE = true
                    unstuckRouteIndex = 1
                    BANETO_UNSTUCK_ROUTE_LAST_PROFILE = i
                    BANETO_SetWaPathNil("stuck10bbgg")
                    flyingPath = nil
                    CHECK_UNSTUCKTRIGGER_DELAY = GetTime()+1
                    BANETO_PrintState("Begin of profile unstuck route: " .. i)
                    C_Timer.After(300,function() BANETO_UNSTUCK_ROUTE_LAST_PROFILE = nil  end)
                    return true
                end
            end
        end
    end
end

function _G.BANETO_CancelRecordingUnstuckRoute()

    BANETO_SUB_FRAME_SETTINGS_UNSTUCKROUTES_RECORDER:Hide()
    BANETO_RECORDING_UNSTUCKROUTE = nil
    BANETO_UNSTUCKROUTE_CACHE = nil
end

function _G.BANETO_SaveUnstuckRoute()
    if BANETO_UNSTUCKROUTE_CACHE and #BANETO_UNSTUCKROUTE_CACHE > 1 then
        BANETO_SUB_FRAME_SETTINGS_UNSTUCKROUTES_RECORDER:Hide()
        BANETO_RECORDING_UNSTUCKROUTE = nil
        if not BANETO_UNSTUCK_ROUTES_TABLE then
            BANETO_UNSTUCK_ROUTES_TABLE  = {}
        end
        table.insert(BANETO_UNSTUCK_ROUTES_TABLE,BANETO_UNSTUCKROUTE_CACHE)
        BANETO_UNSTUCKROUTE_CACHE = nil
        BANETO_PrintSuccess("Unstuck route was saved!")
        BANETO_SaveSettings()
    else
        BANETO_PrintError("Not enough unstuck spots recorded yet!")
    end
end
function _G.BANETO_GetDeathCount()
    return BANETO_COUNT_DEATH
end
function _G.BANETO_DeleteLastUnstuckSpot()

    if BANETO_UNSTUCKROUTE_CACHE and #BANETO_UNSTUCKROUTE_CACHE > 0 then
        table.remove(BANETO_UNSTUCKROUTE_CACHE, #BANETO_UNSTUCKROUTE_CACHE)
        BANETO_PrintSuccess("Unstuck spot erased! Continue recording spots or save..")
        if #BANETO_UNSTUCKROUTE_CACHE == 0 then
            BANETO_UNSTUCKROUTE_CACHE = nil
        end
    else
        BANETO_UNSTUCKROUTE_CACHE = nil
        BANETO_PrintError("No unstuck spots recorded yet!")
    end
end

function _G.BANETO_ClearProfileUnstucks() --not documented
    if not BANETO_UNSTUCK_ROUTE_ISACTIVE then
        BANETO_UNSTUCK_ROUTES_TABLE_PROFILES = {}
    elseif not BANETO_ClearProfileUnstucks_Timer then
        BANETO_ClearProfileUnstucks_Timer = C_Timer.After(4,function()
            BANETO_ClearProfileUnstucks_Timer = nil
            BANETO_ClearProfileUnstucks()
        end)
    end
end

function _G.BANETO_DefineProfileUnstuck(unstuckid,x,y,z,radiusTrigger)
    if not BANETO_UNSTUCK_ROUTES_TABLE_PROFILES then
        BANETO_UNSTUCK_ROUTES_TABLE_PROFILES = {}
    end
    local copyOfTableProfiles = BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[unstuckid]
    if not copyOfTableProfiles then
        copyOfTableProfiles = {}
    end
    if not radiusTrigger then
        radiusTrigger = 5
    end
    table.insert(copyOfTableProfiles,{x,y,z,radiusTrigger})
    BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[unstuckid] = copyOfTableProfiles
end

function _G.BANETO_DefineUnstuck(unstuckid,x,y,z,radiusTrigger)
    if not BANETO_UNSTUCK_ROUTES_TABLE then
        _G.BANETO_UNSTUCK_ROUTES_TABLE = {}
    end
    local copyOfTable = BANETO_UNSTUCK_ROUTES_TABLE[unstuckid]
    if not copyOfTable then
        copyOfTable = {}
    end
    if not radiusTrigger then
        radiusTrigger = 5
    end
    table.insert(copyOfTable,{x,y,z,radiusTrigger})
    BANETO_UNSTUCK_ROUTES_TABLE[unstuckid] = copyOfTable
end

function _G.BANETO_RecordNewUnstuckSpot()
    if not BANETO_UNSTUCKROUTE_CACHE then
        BANETO_UNSTUCKROUTE_CACHE = {}
    end
    local x,y,z = BANETO_ObjectPosition("player")
    table.insert(BANETO_UNSTUCKROUTE_CACHE,{x,y,z})
    BANETO_PrintSuccess("Unstuck point recorded! You need at least 2.")
end

function _G.BANETO_DeleteLastUnstuckRoute()
    if BANETO_RECORDING_UNSTUCKROUTE then
        BANETO_PrintError("Currently recording an unstuck route, finish that first!")
    else
        if BANETO_UNSTUCK_ROUTES_TABLE and #BANETO_UNSTUCK_ROUTES_TABLE >= 1 then
            table.remove(BANETO_UNSTUCK_ROUTES_TABLE, #BANETO_UNSTUCK_ROUTES_TABLE)
            BANETO_PrintSuccess("Last unstuck route was erased!")
            if #BANETO_UNSTUCK_ROUTES_TABLE == 0 then
                BANETO_UNSTUCK_ROUTES_TABLE = nil
            end
            BANETO_SaveSettings()
        else
            BANETO_PrintError("No unstuck routes recorded!")
        end
    end
end

function _G.BANETO_RecordNewUnstuckRoute()
    if not BANETO_RECORDING_UNSTUCKROUTE then
        BANETO_SUB_FRAME_SETTINGS_UNSTUCKROUTES_RECORDER:Show()
        BANETO_HideAllMainFrames()
        BANETO_RECORDING_UNSTUCKROUTE = true
    else
        BANETO_PrintError("Already recording an unstuck route!")
    end
end

