function _G.BANETO_IsFlyingStuck()
    local speed = BANETO_GetUnitSpeed("player")
    if IsFlying() and (not BANETO_FLY_UNSTUCK_DELAY or BANETO_FLY_UNSTUCK_DELAY < GetTime()) and BANETO_State ~= "RBG-WAIT" and BANETO_State ~= "RBG-JOIN"  then
        BANETO_FLY_UNSTUCK_DELAY = GetTime()+0.4
        if flyingUnstuckCount and flyingUnstuckCount >= 18 then
            if BANETO_GetState() == "GHOST" then
                BANETO_PrintState("Flying stuck as ghost, trying strafe right and turning")
                BANETO_FLYINGASCEND_STOPPER = GetTime()+15
                BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime()+15
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+15
                flyingUnstuckCount = 0
                BANETO_BlockSmoothTurn(4)
                if _internal.Software() == "tnk" then
                    Eval("StrafeRightStart()","somth")
                else
                    Unlock("StrafeRightStart","")
                end
                BANETO_TurnLeftStart()
                C_Timer.After(1,BANETO_JumpOrAscendStart)
                C_Timer.After(2,function()
                    if _internal.Software() == "tnk" then
                     Eval("StrafeRightStop()","somth")
                    else
                     Unlock("StrafeRightStop","")
                    end
                    BANETO_TurnLeftStop()
                end)
                C_Timer.After(4,BANETO_StopMovement)
            else
                if IsMounted() then
                    BANETO_Dismount()
                else
                    CancelShapeshift()
                end
                flyingUnstuckCount = 0
                BANETO_PrintState("Flying stuck, dismount / cancel shapeshift and fall to ground! Block flying for 12 seconds.")
                BANETO_FLYINGASCEND_STOPPER = GetTime()+12
                BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime()+12
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+12
            end
        end
        if not BANETO_LAST_FLY_X then
            --BANETO_PrintBambo("UNSTUCK set x,y,z")
            BANETO_LAST_FLY_X,BANETO_LAST_FLY_Y,BANETO_LAST_FLY_Z = BANETO_ObjectPosition("player")
        elseif BANETO_LAST_FLY_X then
            --BANETO_PrintBambo("CHECK x,y,z")
            local x,y,z = BANETO_ObjectPosition("player")
            local distance = BANETO_GetDistance3D(BANETO_LAST_FLY_X,BANETO_LAST_FLY_Y,BANETO_LAST_FLY_Z,x,y,z)
            local destination = BANETO_GetLuaBoxDestination()
            local destX, destY, destZ
            local distanceToDestin
            if destination then
                destX, destY, destZ =  destination[1], destination[2], destination[3]
                distanceToDestin = BANETO_GetDistance3D(x,y,z,destX, destY, destZ)
            end
            if distance and distance < 7 and distanceToDestin and distanceToDestin > 6 then
                BANETO_PrintBambo("ADD fly stuck COUNT")
                flyingUnstuckCount = flyingUnstuckCount+1
                if flyingUnstuckCount and flyingUnstuckCount >= 5 then
                    return true
                end
            else
                --BANETO_PrintBambo("RESET COUNT" .. distance)
                BANETO_LAST_FLY_X = nil
                flyingUnstuckCount = 0
            end
        end
    end
end

