function _G.BANETO_SetFlyingPitch(val)
    --BANETO_PrintBambo("Set pitch now")
    if BANETO_BLOCK_PITCHING then
        --BANETO_PrintBambo("pitching is blocked atm")
        return
    end
    if val and val > 1.5 then
        val = 1.5
    end
    if val and val < -1.5 then
        val = -1.5
    end
    if BANETO_IsDragonRiding() and not IsSwimming() and BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == true and not DISCONNECT_TESTS2 then
        if pitchwowapistopper then
            pitchwowapistopper = nil
        end
        BANETO_PrintBambo("SmoothPitch")
        if not dragonBlockPitchBlockFace or dragonBlockPitchBlockFace < GetTime() then
            if _internal.Software() == "tnk" then
                BANETO_LAST_PITCH = val
                local currentPitch = BANETO_GetFlyingPitch()
                local abs = math.abs(currentPitch-val)
                if currentPitch > 1.6 or currentPitch < -1.6 or abs < 0.1 then
                    if not banetoStoppitchnwhilecast or banetoStoppitchnwhilecast < GetTime() then
                        Eval("PitchUpStop()","")
                        Eval("PitchDownStop()","")
                        banetoStoppitchnwhilecast = GetTime()+0.75
                    end
                    BANETO_CACHE_PITCHING = nil
                    return false
                end
                banetoStoppitchnwhilecast = nil
                BANETO_FlightLog("New smooth pitch: "..val)
                if currentPitch > val then
                    if not BANETO_CACHE_PITCHING or BANETO_CACHE_PITCHING == "UP" then
                        Eval("PitchUpStop()","")
                        Eval("PitchDownStart()","")
                        BANETO_CACHE_PITCHING = "DOWN"
                    end
                else
                    if not BANETO_CACHE_PITCHING or BANETO_CACHE_PITCHING == "DOWN" then
                        Eval("PitchDownStop()","")
                        Eval("PitchUpStart()","")
                        BANETO_CACHE_PITCHING = "UP"
                    end
                end
            elseif _internal.Software() == "nn" then
                BANETO_LAST_PITCH = val
                local currentPitch = BANETO_GetFlyingPitch()
                local abs = math.abs(currentPitch-val)
                if currentPitch > 1.6 or currentPitch < -1.6 or abs < 0.1 then
                    if not banetoStoppitchnwhilecast or banetoStoppitchnwhilecast < GetTime() then
                        Unlock("PitchUpStop","")
                        Unlock("PitchDownStop","")
                        banetoStoppitchnwhilecast = GetTime()+0.6
                        --BANETO_PrintBambo("stop pitching")
                    end
                    return false
                end
                banetoStoppitchnwhilecast = nil
                BANETO_FlightLog("New smooth pitch: "..val)
                if currentPitch > val then
                    if not BANETO_CACHE_PITCHING or BANETO_CACHE_PITCHING == "UP" then
                        Unlock("PitchUpStop","")
                        Unlock("PitchDownStart","")
                        --BANETO_PrintBambo("pitch down start")
                        BANETO_CACHE_PITCHING = "DOWN"
                    else
                        --BANETO_PrintBambo("pitch down is blocked")
                    end
                else
                    if not BANETO_CACHE_PITCHING or BANETO_CACHE_PITCHING == "DOWN" then
                        Unlock("PitchDownStop","")
                        Unlock("PitchUpStart","")
                        --BANETO_PrintBambo("pitch up")
                        BANETO_CACHE_PITCHING = "UP"
                    else
                        --BANETO_PrintBambo("pitch up is blocked")
                    end
                end
            end
        end
    else
        if _internal.Software() == "tnk" then
            if not pitchwowapistopper and BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == false then
                Eval("PitchUpStop()","")
                Eval("PitchDownStop()","")
                pitchwowapistopper = true
            end
            if (val < 0 and val > 0) then
                BANETO_PrintBambo("PITCHING ERROR -NAND!!!!!!!")
                return false
            end
            if GetPitch() ~= val then
                local tolerance = 0.05  -- Set your desired tolerance range
                local currentPitch = BANETO_GetFlyingPitch("player")
                if math.abs(currentPitch - val) > tolerance then
                    SetPitch(val)
                    BANETO_LogDragonride("Pitch Snap tnk: "..val)
                    BANETO_LAST_PITCH = val
                end
            end
        else
            if not pitchwowapistopper and BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == false then
                Unlock("PitchUpStop","")
                Unlock("PitchDownStop","")
                pitchwowapistopper = true
            end
            if (val < 0 and val > 0) then
                BANETO_PrintBambo("PITCHING ERROR -NAND!!!!!!!")
                return false
            end
            if val and type(val) == "number" then
                local tolerance = 0.05  -- Set your desired tolerance range
                local currentPitch = BANETO_GetFlyingPitch("player")
                if math.abs(currentPitch - val) > tolerance then
                    SetPitch(BANETO_Object("player"),val)
                    BANETO_LAST_PITCH = val
                    BANETO_LogDragonride("Pitch Snap nn: "..val)
                    BANETO_UpdateServerFacing()
                end
            end
        end
    end
end

