function _G.BANETO_DragonWings(isUpdward)
    if not BANETO_DRAGON_WINGS or BANETO_DRAGON_WINGS < GetTime() then
        if BANETO_GetCurrentVigor() >= 1 then
            local forwardsurge = 372608
            local ascendsurge = 372610
            if (isUpdward or BANETO_FlyingRaycastClose() or BANETO_FlyingRaycast()) and BANETO_DragonridingTraceUpward() then

                if SPECIALDRAGONASCEND then
                    BANETO_PrintBambo("SPECIAL DRAGON ASCEND PITCH")
                    BANETO_SetFlyingPitch(1.4)
                    BANETO_BLOCK_PITCHING = true
                    C_Timer.After(0.8,function()
                        BANETO_BLOCK_PITCHING = nil
                        BANETO_SetFlyingPitch(-1.4)
                    end)
                end
                if doubleJumpLiftoff == true then
                    BANETO_JumpOrAscendStart()
                else
                    BANETO_CastSpell(ascendsurge,true)
                end
                BANETO_PrintBambo("Dragon Wings cast: Skyward")
                BANETO_FlightLog("Dragon: Upward")
                BANETO_LogDragonride("Wings Upward")
                if BANETO_DRAGON_ASCEND_SURGE_DELAYER then
                    BANETO_DRAGON_ASCEND_SURGE_DELAYER = nil
                end
                --dragonBlockPitchBlockFace = GetTime()+2
            elseif (not forwardsurgedelay or forwardsurgedelay < GetTime()) and BANETO_DragonridingTraceForward() and BANETO_DragonridingTraceUpwardShort() then
                local race1,race2,otherArg = UnitRace("player")
                BANETO_FlightLog("Dragon: Forward")
                BANETO_LogDragonride("Wings Forward")
                --dragonBlockPitchBlockFace = GetTime()+2
                local clength = 0.01
                if BANETO_DRAGON_ASCEND_SURGE_DELAYER then
                    clength = 0.55
                    BANETO_DRAGON_ASCEND_SURGE_DELAYER = nil
                end
                forwardsurgedelay = GetTime()+2
                C_Timer.After(clength,function()
                    if race2 and race2 == "Dracthyr" and BANETO_GetLocale() == "ruRU" and DRACTHYR_SPECIAL_DRAGONRIDING_SPELLS then
                        BANETO_RunMacroText("/cast Ð ÑÐ²Ð¾Ðº Ð²Ð¿ÐµÑÐµÐ´(ÐÐ¾Ð»ÐµÑÑ Ð½Ð° Ð´ÑÐ°ÐºÐ¾Ð½Ðµ)")
                    elseif race2 and race2 == "Dracthyr" and DRACTHYR_SPECIAL_DRAGONRIDING_SPELLS then
                        BANETO_RunMacroText("/cast Surge Forward(Dragonriding)")
                    else
                        BANETO_CastSpell(forwardsurge,true)
                    end
                    if BANETO_LAST_PITCH then
                        BANETO_PrintBambo("Dragon Wings cast! Forward with pitch: "..BANETO_LAST_PITCH)
                    end
                end)
            end
            --BANETO_JumpOrAscendStart()
            BANETO_DRAGON_WINGS = GetTime()+1.6
        end
    end
end

local updateHandle = nil
local pollRate = 1 / 10
local updatePeriod = 1 / 10

local lastXDragon, lastYDragon, lastZDragon = 0, 0, 0
local lastT = GetTime()
local samples = 0
local maxSamples = 5
local ascentSpell = 372610
local thrillBuff = 377234
local thrillSpeed = 60
local ascentStart = 0
local ascentDuration = 3.5
local ascentBoostMax = 35
local skipped = false
local smoothSpeed = 0

local myTESTForCommunities = CreateFrame("Frame");
myTESTForCommunities:RegisterEvent("CLUB_UPDATED");
myTESTForCommunities:SetScript("OnEvent",
function(self, event, arg1, arg2, spellId, arg4)
    if event == "CLUB_UPDATED" then
        BANETO_PrintBambo("club updated "..arg1)
    end
end);

local myFrame = CreateFrame("Frame");
myFrame:RegisterEvent("UNIT_SPELLCAST_SUCCEEDED");
myFrame:SetScript("OnEvent",
    function(self, event, arg1, arg2, spellId, arg4)
        if event == "UNIT_SPELLCAST_SUCCEEDED" then
            if spellId == ascentSpell then
                ascentStart = GetTime()
            end
            return false
        end
    end);

if not updateHandle then
    updateHandle = C_Timer.NewTicker(pollRate, function()
        BANETO_GetDragonridingSpeed()
    end)
end

function _G.BANETO_GetDragonridingSpeed()

    -- Compute accurate speed if possible
    local instanced = true
    local speed = 0
    local map = C_Map.GetBestMapForUnit("player")
    if map then
        local pX, pY, pZ = BANETO_ObjectPosition("player")
        if pX and pY and pZ then
            instanced = false
            -- Delta position
            local x, y, z = pX, pY, pZ
            local dx = math.abs(x - lastXDragon)
            local dy = math.abs(y - lastYDragon)
            local dz = math.abs(z - lastZDragon)
            lastXDragon = x
            lastYDragon = y
            lastZDragon = z

            -- Delta time
            local dt = GetTime() - lastT
            if dt < updatePeriod then
                -- Rate limit speed updates!
                return false
            elseif dt and dt ~= 0 then
                speed = math.sqrt(dx * dx + dy * dy + dz * dz) / dt
            end
            lastT = GetTime()
        end
    end

    -- Ignore obviously invalid speeds that occur when jumping zones
    if speed > 150 then
        return false
    end

    -- If speed can't be detected, reduce exp-avg window size
    if speed == 0 then
        samples = math.min(1, samples)
    end

    local thrill = C_UnitAuras.GetPlayerAuraBySpellID(thrillBuff)

    -- Override with ascent boost
    local boosting = false
    if thrill and GetTime() < ascentStart + ascentDuration then
        boosting = true
        local progress = (GetTime() - ascentStart) / ascentDuration
        local boost = thrillSpeed + (1 - progress) * ascentBoostMax
        if speed < boost then
            speed = boost
            samples = 0
            skipped = true
        end
    end

    -- Override speed based on Thrill buff
    if speed < thrillSpeed and thrill then
        speed = thrillSpeed
    end

    if speed > thrillSpeed and not thrill then
        speed = thrillSpeed
        samples = 0
        skipped = true
    end

    -- Skip sampling on large apparent speed changes
    if math.abs(speed - smoothSpeed) > 100 then
        if skipped then
            samples = 0
        else
            skipped = true
            return false
        end
    end
    skipped = false

    -- Compute smooth speed
    samples = math.min(maxSamples, samples + 1)
    local lastWeight = (samples - 1) / samples
    local newWeight = 1 / samples
    smoothSpeed = ((smoothSpeed * lastWeight + speed * newWeight) / 7) * 100
    speed = (speed / 7) * 100

    --BANETO_PrintBambo(speed .. smoothSpeed .. boosting .. instanced)
    return speed, smoothSpeed, boosting, instanced

end


