    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local idInBag = GetContainerItemID(i, z)
            if idInBag then
                local itemName, itemLink, itemQuality, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, sellPrice, classID, subclassID, bindType, expansionID, setID, isCraftingReagent = C_Item.GetItemInfo(idInBag)
                print(itemName .. " " .. idInBag)
            end
        end
    end
end
function _G.BANETO_DebugSoulboundItems() --not documented
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local idInBag = GetContainerItemID(i, z)
            if idInBag then
                local itemName, itemLink, itemQuality, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, sellPrice, classID, subclassID, bindType, expansionID, setID, isCraftingReagent = C_Item.GetItemInfo(idInBag)
                if not bindType then
                    bindType = 9
                end
                print(itemName .. " " .. idInBag .. " " .. " " .. bindType)
            end
        end
    end
end

function _G.BANETO_DebugSoulboundItems2()
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local id = GetContainerItemID(i, z)
            local itemLoc = ItemLocation:CreateFromBagAndSlot(i,z)
            local isBound;
            local itemName, itemLink, itemQuality, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, sellPrice, classID, subclassID, bindType, expansionID, setID, isCraftingReagent = C_Item.GetItemInfo(id)
            if itemLoc and itemLoc:IsValid() then
                isBound = C_Item.IsBound(itemLoc)
            end
            if isBound then
                print(itemName .. " " .. id .. " is bound")
            else
                print(itemName .. " " .. id .. " is NOT bound")
            end
        end
    end
end

BANETO_SETTING_AERIAL_HALT = false
_G.BANETO_DRAGON_LEGIT = GetTime()+15
function _G.BANETO_FlyingNavigator()
    local isLegitDragonflight = false
    if (aerialDelay and aerialDelay > GetTime()) or (flyingNavDelay and flyingNavDelay > GetTime()) then
        return
    end
    if _G.BANETO_DRAGON_LEGIT and _G.BANETO_DRAGON_LEGIT > GetTime() then
        _G.BANETO_DRAGON_LEGIT = GetTime()+3
        isLegitDragonflight = true
        banetoGroundDragonStucks = nil
    end
    if BANETO_IsDragonRiding() then
        BANETO_InitDragonRidingValues()
        C_Timer.After(1,function()
            if BANETO_IsDragonRiding() and IsFlying() then
                BANETO_DragonAscendsReset()
            end
        end)
    elseif IsFlying() and not BANETO_IsDragonRiding() then
        BANETO_InitSteadyflightValues()
    end
    BANETO_UpdateServerFacing()
    if (IsFlying() or BANETO_DEEPWATER_FLYING == true) and not BANETO_IsDragonRiding() and BANETO_IsFlyingStuck()  then
        BANETO_FlyingUnstucker()
        return false
    end
    if Unlocker("LUA") then
        local startX, startY, startZ = BANETO_ObjectPosition("player")
        local destination = BANETO_GetLuaBoxDestination()
        local destX, destY, destZ
        local distance
        if destination then
            destX, destY, destZ =  destination[1], destination[2], destination[3]
            distance = BANETO_GetDistance3D(startX, startY, startZ,destX, destY, destZ)
        end
        DRAGONRIDING_FORCEFLY = nil
        if not flyingPath and destX and destY and destZ and startY and startZ and startX  then
            BANETO_FlightLog("Calculate air path")
            if _internal.Software() == "tnk" then
                --flyingPath = Fly:GetFlightRoute(startX, startY, startZ, destX, destY, destZ)
                flyingPath = GeneratePathBamboFlying2(destX,destY,destZ)
                BANETO_LogDragonride("New air path, tnk")
            else
                flyingPath = GeneratePathBamboFlying2(destX,destY,destZ)
                BANETO_LogDragonride("New air path, nn")
            end
            --flyingPathIndex = BANETO_GetCenterIndexInFlyingPath(flyingPath)
            flyingPathIndex = 2
        end
        --local normalDragonspeed,smoothDragonspeed,dragonBoostBuff,dragonIsInstanced = BANETO_GetDragonridingSpeed()
        local thrillBuff = 377234
        local thrill = C_UnitAuras.GetPlayerAuraBySpellID(thrillBuff)
        --local dragonSpeed = BANETO_GetDragonridingSpeed()
        --local neededVigor = BANETO_SETTING_VIGORWAIT
        if flyingPath  and not BANETO_BLOCK_TINKR_FLYING_NAV and distance and distance > 4  then
            local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
            if not flyingPath[flyingPathIndex] then
                BANETO_PrintBambo("No flying path on current flying path index?!")
                return false
            end
            local nextX,nextY,nextZ = flyingPath[flyingPathIndex].x,flyingPath[flyingPathIndex].y,flyingPath[flyingPathIndex].z
            local currentSpeed = BANETO_GetUnitSpeed("player")
            local neededPitch = 0

            local forceland = false;
            if not TIMETOLAND and BANETO_IsDragonRiding() and (BANETO_GetCurrentVigor() == 0 or isLegitDragonflight == false) then
                if isLegitDragonflight == true then
                    TIMETOLAND = GetTime()+6
                else
                    TIMETOLAND = GetTime()+2
                end
            elseif TIMETOLAND and TIMETOLAND<GetTime() and (BANETO_GetCurrentVigor() == 0 or isLegitDragonflight == false) and BANETO_IsDragonRiding() then
                if not forcelandMsg then
                    forcelandMsg = true
                    BANETO_PrintState("Out of Vigor. Force landing.")
                end
                forceland = true
            elseif (TIMETOLAND and BANETO_GetCurrentVigor() > 0 and isLegitDragonflight == true) or not BANETO_IsDragonRiding() then
                TIMETOLAND = nil
                forcelandMsg = nil
            end
            if not BANETO_PITCH_DELAY or BANETO_PITCH_DELAY < GetTime() then
                BANETO_PITCH_DELAY = GetTime()+0.02
                --pitch
                local d = BANETO_GetDistance3D(playerX, playerY, 1,nextX,nextY,1)
                local facing;
                if  nextZ and playerZ and nextZ > playerZ then
                    local h = nextZ-playerZ
                    local alpha = (math.atan(h/d))*180/math.pi
                    local angle = alpha/90*math.pi/2
                    if forceland == true and angle > 0 then
                        BANETO_FlightLog("forced landing pitching")
                        angle = -0.7
                    end
                    BANETO_SetFlyingPitch(angle)
                    facing = BANETO_GetFacingValue(nextX,nextY,nextZ)
                    if facing then
                        --BANETO_PrintBambo("Dragonriding facing A: "..facing)
                        BANETO_SetPlayerAnglesLuabox(facing)
                    end
                elseif  nextZ and playerZ and playerZ >= nextZ then
                    local h = playerZ-nextZ
                    local alpha = (math.atan(h/d))*180/math.pi
                    local angle = alpha/90*(math.pi)/2
                    BANETO_SetFlyingPitch(-angle)
                    facing = BANETO_GetFacingValue(nextX,nextY,nextZ)
                    if facing then
                        --BANETO_PrintBambo("Dragonriding facing B: "..facing)
                        BANETO_SetPlayerAnglesLuabox(facing)
                    end
                end
                local cooldownHalt = BANETO_GetSpellCooldown(403092)
                local currentVigor = BANETO_GetCurrentVigor()
                local maxVigor = BANETO_GetMaxVigor()
                if BANETO_GetState() == "GATHER" and BANETO_SETTING_AERIAL_HALT == true and thrill and maxVigor > currentVigor and BANETO_TARGET and 23 > GetDistanceBetweenObjects("player",BANETO_TARGET) and GetDistanceBetweenObjects("player",BANETO_TARGET) ~= 0 and cooldownHalt and cooldownHalt == 0 and IsFlying() and (not aerialDelay or aerialDelay < GetTime()) then
                    BANETO_AerialHalt()
                    aerialDelay = GetTime()+2.5
                    return
                elseif not aerialDelay or aerialDelay < GetTime() then
                    local currentAngle = BANETO_GetObjectFacing("player")
                    if BANETO_GetCurrentVigor() < maxVigor and BANETO_GetCurrentVigor() < 1 and not thrill and BANETO_IsDragonRiding() and BANETO_IsSpellKnown(425782) and not BANETO_IsDeadOrGhost() then
                        local spellcd = BANETO_GetSpellCooldown(425782)
                        local getSpellCharges = C_Spell.GetSpellCharges(425782)
                        local currentCharges = getSpellCharges.currentCharges
                        if spellcd == 0 and currentCharges > 0 and (BANETO_GetMaxVigor() and BANETO_GetMaxVigor() >= 2 and not BANETO_IsDeadOrGhost() and not BANETO_HasBuff("player",404468)) then
                            BANETO_CastSpell(425782,true)
                            BANETO_LogDragonride("Second wind")
                        end
                    end
                    if currentAngle and facing and not IsFalling() and BANETO_IsDragonRiding() and BANETO_GetCurrentVigor() > 0 and isLegitDragonflight == true then
                        local abs = math.abs(currentAngle-facing)
                        local currentPitch = BANETO_GetFlyingPitch()
                        if distance and distance > 80 and currentPitch and currentPitch < 0 and (abs < 0.25 or abs >= math.pi*2-0.25) and BANETO_SETTING_SURGEFORWARD and BANETO_SETTING_SURGEFORWARD == true and not thrill then
                            BANETO_DragonWings(false)
                        elseif not thrill and (not BANETO_TARGET or nextZ > playerZ) and distance and distance > 15  then
                            BANETO_DragonWings(true)
                        end
                    end
                end
            end


            if (BANETO_PlayerPosition(nextX,nextY,playerZ,9) and BANETO_IsDragonRiding()) or (BANETO_PlayerPosition(nextX,nextY,nextZ,5) and not BANETO_IsDragonRiding()) or (BANETO_IsDragonRiding() and BANETO_PlayerPosition(nextX,nextY,playerZ,10)) or (thrill and BANETO_PlayerPosition(nextX,nextY,playerZ,25))  then
                flyingPathIndex = flyingPathIndex+1
                BANETO_LogDragonride("Flying path index incr")
                --BANETO_PrintBambo("Flying path index : "..flyingPathIndex)
                local pathLength = tablelength(flyingPath)
                if flyingPathIndex > pathLength then
                    flyingPathIndex = pathLength
                    --BANETO_PrintBambo("Flying path index reset: "..flyingPathIndex)
                    BANETO_StopMovement()
                    flyingPath = nil
                    BANETO_LogDragonride("Flying path index reset")
                end
                return false
            end
            if BANETO_GetUnitSpeed("player") == 0 and not BANETO_IsDragonRiding() then
                BANETO_MoveForwardStart()
            end

        elseif not BANETO_IsDragonRiding() then
            local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
            local destination = BANETO_GetLuaBoxDestination()
            if destination then
                local nextX,nextY,nextZ =  destination[1], destination[2], destination[3]
                local currentSpeed = BANETO_GetUnitSpeed("player")
                local neededPitch = 0
                --raycast
                if not BANETO_FLYING_RAYCAST_TICKER or BANETO_FLYING_RAYCAST_TICKER < GetTime() then
                    BANETO_FLYING_RAYCAST_TICKER = GetTime()+0.3
                    local distanceToDestination = BANETO_GetDistance3D(nextX,nextY,nextZ,playerX, playerY, playerZ)
                    if distanceToDestination and distanceToDestination > 45 then
                        if BANETO_FlyingRaycastClose() then
                            if Unlocker("EWT") then
                                MoveForwardStop()
                            elseif Unlocker("LUA") then
                                BANETO_StopMovement()
                            end
                        end
                        if BANETO_FlyingRaycast() and not BANETO_FLYING_AVOID_ASCEND then
                            if Unlocker("EWT") then
                                JumpOrAscendStart()
                            elseif Unlocker("LUA") then
                                BANETO_PrintBambo("Flying raycast hit")
                                if not BANETO_IsDragonRiding() or BANETO_GetCurrentVigor() >= 1 then
                                    BANETO_PrintBambo("Flying raycast jump")
                                    BANETO_JumpOrAscendStart()
                                end
                            end
                            if not BANETO_IsDragonRiding() then
                                BANETO_FLYING_AVOID_ASCEND = true
                                BANETO_FLYING_AVOID_ASCEND_START = GetTime()+7
                            end
                            return false
                        elseif BANETO_FLYING_AVOID_ASCEND and BANETO_FLYING_AVOID_ASCEND == true and (not BANETO_FlyingRaycast() or BANETO_FLYING_AVOID_ASCEND_START < GetTime()) then
                            if Unlocker("EWT") then
                                AscendStop()
                                MoveForwardStart()
                            elseif Unlocker("LUA") then
                                BANETO_AscendStop()
                                BANETO_MoveForwardStart()
                            end
                            BANETO_FLYING_AVOID_ASCEND = nil
                            BANETO_FLYING_AVOID_ASCEND_START = nil
                        end
                        return false
                    end
                end
                if not BANETO_PITCH_DELAY or BANETO_PITCH_DELAY < GetTime() then
                    BANETO_PITCH_DELAY = GetTime()+0.1
                    --pitch
                    local d = BANETO_GetDistance3D(playerX, playerY, 1,nextX,nextY,1)
                    if nextZ and playerZ and nextZ > playerZ then
                        local h = nextZ-playerZ
                        local alpha = (math.atan(h/d))*180/math.pi
                        local angle = alpha/90*math.pi/2
                        BANETO_SetFlyingPitch(angle)
                        local facing = BANETO_GetFacingValue(nextX,nextY,nextZ)
                        if facing then
                            BANETO_SetPlayerAnglesLuabox(facing)
                        end
                    elseif nextZ and playerZ and playerZ >= nextZ then
                        local h = playerZ-nextZ
                        local alpha = (math.atan(h/d))*180/math.pi
                        local angle = alpha/90*(math.pi)/2
                        BANETO_SetFlyingPitch(-angle)
                        local facing = BANETO_GetFacingValue(nextX,nextY,nextZ)
                        if facing then
                            BANETO_SetPlayerAnglesLuabox(facing)
                        end
                    end

                    if not BANETO_PlayerPosition(nextX,nextY,nextZ,4) and not BANETO_IsDragonRiding() then
                        BANETO_WANTED_ANGLE = BANETO_GetFacingValue(nextX,nextY,nextZ)
                        if currentSpeed == 0 and not BANETO_FLYING_AVOID_ASCEND then
                            if _internal.Software() == "tnk" then
                            MoveForwardStart()
                            else
                                Unlock("MoveForwardStart","")
                            end
                            BANETO_PrintBambo("Start flying movement")
                        end
                    end
                end
            end
        end
    end
end

function _G.BANETO_ResetSmoothturnWantedAngle()
    BANETO_WANTED_ANGLE = nil
end

_G.BANETO_FLYING_DISTANCE_GATHER_TRIGGER = 15
_G.BANETO_FLYING_DISTANCE_GENERAL_TRIGGER = 15

function _G.BANETO_IsFlyingAscendNeeded(debug)
    if Unlocker("LUA") then
        local neededVigor = BANETO_SETTING_VIGORWAIT
        if neededVigor == nil then
            neededVigor = 3
        end
        if BANETO_FLYING_PROFILE and BANETO_FLYING_PROFILE == true and not IsIndoors() and (not IsSwimming() or (BANETO_UnitClassNumber("player") == 11 and IsSwimming() and _G.BANETO_SETTING_RETAIL_DRUID_USEMOUNT == false) or BANETO_IsDragonRiding()) and (not BANETO_IsDragonRiding() or ((BANETO_LAVA_ESCAPE or BANETO_LAVA_ESCAPE_VIA_FLY) and BANETO_GetCurrentVigor() and BANETO_GetCurrentVigor() > 0) or DRAGONRIDING_FORCEFLY or BANETO_GetCurrentVigor() >= neededVigor or (UnitAffectingCombat("player") and not BANETO_TARGET and BANETO_GetCurrentVigor() >=1)) and not LootFrame:IsVisible() and not UnitCastingInfo("player") and (BANETO_DEFINED_PROFILE_TYPE ~= "Battleground" or BANETO_State == "BG-JOIN")  and (not BANETO_FLYINGASCEND_STOPPER or GetTime() > BANETO_FLYINGASCEND_STOPPER) and not BANETO_EXECUTE_FLY_ASCEND and (not BANETO_IsDeadOrGhost() or BANETO_FLYING_GHOST == true) and BANETO_State ~= "REGEN" and BANETO_State ~= "FIGHTING" and BANETO_State ~= "BUFF"  then
            if debug then
                BANETO_PrintBambo("ASCEND NEEDED A")
            end
            local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
            local destination = BANETO_GetLuaBoxDestination()
            if destination and (not BANETO_MOUNT_INDOORS_3SECS_STOPPER or BANETO_MOUNT_INDOORS_3SECS_STOPPER < GetTime()) then
                if debug then
                    BANETO_PrintBambo("ASCEND NEEDED B")
                end
                local nextX,nextY,nextZ =  destination[1], destination[2], destination[3]
                local distance = BANETO_GetDistance3D(nextX,nextY,nextZ,playerX, playerY, playerZ)
                local travel = 33943
                if not UnitAffectingCombat("player") or IsMounted() or BANETO_IsFlyableBird() then
                    if debug then
                        BANETO_PrintBambo("ASCEND NEEDED C")
                    end
                    if (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) and BANETO_State == "GATHER" and distance and distance > _G.BANETO_FLYING_DISTANCE_GATHER_TRIGGER then
                        return true
                    end
                    if DRAGONRIDING_FORCEFLY and not UnitCastingInfo("player") then
                        DRAGONRIDING_FORCEFLY = nil
                        return true
                    end
                    if _G.BANETO_IS_GLYPH_PROFILE or ((BANETO_LAVA_ESCAPE or BANETO_LAVA_ESCAPE_VIA_FLY) and BANETO_GetCurrentVigor() and BANETO_GetCurrentVigor() > 0) then
                        return true
                    end
                    if distance and distance > _G.BANETO_FLYING_DISTANCE_GENERAL_TRIGGER and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) then
                        return true
                    end
                    if (nextX and playerX and playerZ and nextZ and nextZ > playerZ) and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) then
                        local difference = nextZ - playerZ
                        if difference and difference >= 20 then
                            return true
                        end
                    end
                end
            end
        end
    end
end

function _G.BANETO_FlyMount()
	if not BANETO_MOUNT_USAGE_DELAY or BANETO_MOUNT_USAGE_DELAY < GetTime() then
		if Unlocker("LUA") then
			BANETO_StopMovement()
			BANETO_LUABOXUNSTUCK_RESETDELAY = GetTime()+4
			BANETO_LUABOXUNSTUCK_COUNT = nil
		end
		local travel = 292629
        local _,_,class = UnitClass("player")
		if BANETO_GetUnitSpeed("player") == 0 and (class ~= 11 or BANETO_SETTING_RETAIL_DRUID_USEMOUNT == true) and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
			BANETO_MOUNT_USAGE_DELAY = GetTime()+4
			C_MountJournal.SummonByID(0)
		elseif BANETO_GetUnitSpeed("player") == 0 and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
		    BANETO_PrintState("Druid flying form.")
			BANETO_MOUNT_USAGE_DELAY = GetTime()+3.5
            if not BANETO_HasBuff("player",travel) and not IsSwimming() then
                BANETO_CastSpell(travel,true)
            elseif not BANETO_HasBuff("player",travel) and IsSwimming() then
                BANETO_JumpOrAscendStart()
                C_Timer.After(0.5,BANETO_JumpOrAscendStart)
                BANETO_PrintBambo("Druid bird in water")
            end
	    else
	        BANETO_StopMovement()
		end
	end
end

function _G.BANETO_DragonAscendsReset()
    if IsFlying() then
        dragonAscendCounter = nil
    end
end



function _G.BANETO_IsEntryInGlobalObjectlist(id)
	for i=1,#BANETO_GLOBAL_CUSTOM_OBJECTS do
		local entry = BANETO_GLOBAL_CUSTOM_OBJECTS[i][1]
		if entry == id then
			return true
		end
	end
end

function _G.BANETO_VisualizeGlobalObjectList()
	local mobIdBlacklistString = ""
	for i = 1, #BANETO_GLOBAL_CUSTOM_OBJECTS do
		mobIdBlacklistString = "|cffACACAC" .. mobIdBlacklistString .. BANETO_GLOBAL_CUSTOM_OBJECTS[i][1] .. ", "
	end
	BANETO_SUB_FRAME_SETTINGS_OBJECTLIST:SetText(mobIdBlacklistString)
end

function _G.BANETO_RemoveCustomObjectIDGlobal(id)
	if BANETO_GLOBAL_CUSTOM_OBJECTS then
		for i=1,#BANETO_GLOBAL_CUSTOM_OBJECTS do
			if BANETO_IsEntryInGlobalObjectlist(id) then
				if BANETO_GLOBAL_CUSTOM_OBJECTS[i][1] == id then
					table.remove(BANETO_GLOBAL_CUSTOM_OBJECTS,i)
                    BANETO_OBJECTS_CHESTS[id] = nil
					BANETO_PrintSuccess("Removed entry ".. id .." from global custom Object List!")
				end
			end
		end
	BANETO_VisualizeGlobalObjectList()
	BANETO_SaveSettings()
	end
end

function _G.BANETO_DefineCustomObjectIDGlobal(id)
	if not BANETO_IsEntryInGlobalObjectlist(id) then
		table.insert(BANETO_GLOBAL_CUSTOM_OBJECTS,{id})
		BANETO_OBJECTS_CHESTS[id] = id
		BANETO_VisualizeGlobalObjectList()
		BANETO_SaveSettings()
	end
end


function _G.BANETO_FlyAscendExecute()
    local _,_,class = UnitClass("player")
    local travel = 292629
    local travelGround = 783
    BANETO_PrintBambo("Ascend Execute A")
    if BANETO_IsDeadOrGhost() then
        if Unlocker("EWT") then
            JumpOrAscendStart()
        elseif Unlocker("LUA") then
            BANETO_JumpOrAscendStart()
        end
        if not IsFlying() then
            BANETO_PrintState("Using flying ghost for ascend. Disable in GENERAL settings if you don't want this!")
        end
        BANETO_STARTED_ASCEND = GetTime()+0.4
    else
        if IsMounted() and (BANETO_HasBuff("player",61425) or BANETO_HasBuff("player",264058) or BANETO_HasBuff("player",61425) or BANETO_HasBuff("player",122708)) then
            BANETO_PrintState("Dismounting Yak/Mammoth for flying")
            BANETO_Dismount()
        end
        if not IsMounted() and not BANETO_HasBuff("player",292629) and not UnitCastingInfo("player") and not UnitCastingInfo("player") then
            BANETO_PrintBambo("Ascend Execute G")
            if not BANETO_ASCENDFLYINGMOUNTMSG or BANETO_ASCENDFLYINGMOUNTMSG < GetTime() then
                BANETO_PrintState("Using flying mount for ascend.")
                BANETO_ASCENDFLYINGMOUNTMSG = GetTime()+10
                BANETO_Wmb_StuckTick = 0
            end
            BANETO_FlyMount()
        elseif not IsFlying() and (IsMounted() or BANETO_IsFlyableBird()) then
            BANETO_PrintBambo("Ascend Execute B")
            if BANETO_LOADVIGOR_DRUIDWATER and BANETO_LOADVIGOR_DRUIDWATER > GetTime() then
                return
            end
            BANETO_PrintBambo("Ascend Execute C")
            if not BANETO_IsDragonRiding() then
                BANETO_PrintBambo("Ascend Execute D")
                BANETO_JumpOrAscendStart()
                if not BANETO_STARTED_ASCEND then
                    BANETO_STARTED_ASCEND = GetTime()+0.4
                end
            elseif not dragonAscendStartDelay or dragonAscendStartDelay < GetTime() then
                BANETO_PrintBambo("Ascend Execute E")
                dragonAscendStartDelay = GetTime()+2
                local neededVigor = BANETO_SETTING_VIGORWAIT
                if neededVigor == nil then
                    neededVigor = 3
                end
                if BANETO_LAVA_ESCAPE or UnitAffectingCombat("player") or BANETO_LAVA_ESCAPE_VIA_FLY then
                    neededVigor = 1
                end
                if BANETO_GetCurrentVigor() >= neededVigor then
                    if BANETO_DragonridingTraceUpward() or (DRAGONTRACE_BACKPADDLE and GetTime() < DRAGONTRACE_BACKPADDLE) then
                        local ascendsurge = 372610
                        --BANETO_CastSpell(ascendsurge,true)
                        BANETO_MoveForwardStop()
                        BANETO_Wmb_LastPos = { } --risky
                        BANETO_Wmb_StuckTick = 0
                        BANETO_Wmb_LastPos_Delay = GetTime()+1
                        BANETO_DRAGON_ASCEND_SURGE_DELAYER = true
                        if IsSwimming() and BANETO_HasBuff("player",292629) then
                            BANETO_DRUID_WATER_ASCEND = true
                            BANETO_PrintBambo("druid is in water ascend")
                        end
                        if IsSwimming() and not BANETO_HasBuff("player",292629) and doubleJumpLiftoff == false then
                            BANETO_DELAY_PRINT_FIGHT_LOG = GetTime()+3
                            C_Timer.NewTicker(0.1,function()
                                BANETO_CastSpell(ascendsurge,true)
                            end,20)
                        end
                        if not BANETO_DRUID_WATER_ASCEND then
                            if BANETO_IsFlyableBird() then
                                BANETO_CastSpell(ascendsurge,true)
                                C_Timer.After(1,BANETO_JumpOrAscendStart)
                            else
                                if doubleJumpLiftoff == false then
                                    BANETO_CastSpell(ascendsurge,true)
                                end
                                BANETO_JumpOrAscendStart()
                                C_Timer.After(0.5,BANETO_JumpOrAscendStart)
                            end
                        end
                        if not dragonAscendCounter then
                            dragonAscendCounter = 1
                        else
                            dragonAscendCounter = dragonAscendCounter+1
                        end

                        if BANETO_IsDragonRiding() then
                            BANETO_MoveBackwardStart()
                            C_Timer.After(0.5,BANETO_MoveBackwardStop)
                        end
                        if dragonAscendCounter >= 11 then
                            BANETO_Dismount()
                            BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime() + 12
                            BANETO_PrintWarning("Dragonriding ascend failed, blacklisting for 12 seconds")
                            BANETO_EXECUTE_FLY_ASCEND = nil
                            BANETO_ISFLYING_MSG = nil
                            dragonAscendCounter = nil
                            return false
                        elseif dragonAscendCounter >= 7 then
                            BANETO_StrafeRightStart()
                            C_Timer.After(0.5,BANETO_StrafeRightStop)
                        elseif dragonAscendCounter >= 3 then
                            BANETO_StrafeLeftStart()
                            C_Timer.After(0.5,BANETO_StrafeLeftStop)
                        end
                        BANETO_PrintBambo("Dragonriding ascend: "..dragonAscendCounter)
                        BANETO_DRAGON_WINGS = GetTime()+1
                        _G.BANETO_DRAGON_LEGIT = GetTime()+5
                        BANETO_LAST_PITCH = nil
                        forwardsurgedelay = GetTime()+2.5
                        if not BANETO_STARTED_ASCEND then
                            BANETO_STARTED_ASCEND = GetTime()+0.4
                        end
                    else
                        BANETO_MoveBackwardStart()
                        C_Timer.After(2,BANETO_MoveBackwardStop)
                        DRAGONTRACE_BACKPADDLE = GetTime()+15
                    end
                else
                    if not BANETO_LOADVIGOR_PRINT or BANETO_LOADVIGOR_PRINT < GetTime() then
                        BANETO_LOADVIGOR_PRINT = GetTime()+5
                        BANETO_GATHER_DEBUG_TIMER = nil
                        BANETO_PrintState("Loading up vigor ".. BANETO_GetCurrentVigor() .."/"..neededVigor)
                        BANETO_StopMovement()
                        flyingPath = nil
                        if IsSwimming() and BANETO_UnitClassNumber("player") == 11 then
                            BANETO_LOADVIGOR_DRUIDWATER = GetTime()+15
                        end
                    end
                end
            end
        else
            BANETO_EXECUTE_FLY_ASCEND = nil
            BANETO_ISFLYING_MSG = nil
        end
        if class == 11 and UnitAffectingCombat("player") and BANETO_HasBuff("player",783) and not IsFlying() and not UnitCastingInfo("player") and not UnitCastingInfo("player") and BANETO_STASRUS_DEBUG_DRUID and BANETO_STASRUS_DEBUG_DRUID == true then
            CancelShapeshift()
            BANETO_PrintState("Trying to debug druid travelform in combat - cancel shapeshift and ascend!")
            BANETO_EXECUTE_FLY_ASCEND = nil
        end
    end
end

function _G.BANETO_GetClosestPathIndex()
		local bestDistance = 99999999
		local bestI = nil
        local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
		for i = 1, #waPath do
			local centerX, centerY, centerZ = waPath[i]["x"],waPath[i]["y"],waPath[i]["z"]
			local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,centerX, centerY, centerZ)
			if distance < bestDistance then
				bestDistance = distance
				bestI = i
			end

			if i ==  #waPath then
				return bestI
			end
		end
end



function castItem(ability)
    local slotIDs = {
        INVSLOT_TRINKET1,
        INVSLOT_TRINKET2,
        INVSLOT_FINGER1,
        INVSLOT_FINGER2,
        INVSLOT_MAINHAND,
        INVSLOT_NECK
    }
    for _, slotID in ipairs(slotIDs) do
        local itemID = GetInventoryItemID('player', slotID)
        if itemID == Hekili_Primary_B1.Ability.item then
            if Hekili_Primary_B1.Ability and _internal.Software() == "nn" then
                Unlock('UseInventoryItem', slotID)
            end
            if Hekili_Primary_B1.Ability and _internal.Software() == "tnk" then
                Eval("UseInventoryItem("..slotID..")", "sht")
            end
            break
        end
    end
end
function GTAOE()
    local x,y,z = ObjectPosition('target')
    BANETO_ClickPosition(x,y,z)
end
function checkpet()
    local classLoc,classEng,classNum = UnitClass("player")
    if classNum == 3 and not UnitIsDeadOrGhost('player') and not IsMounted('player') and not IsPlayerMoving() then
        if (not UnitExists("pet") or BANETO_UnitHealth("pet") <= 0 ) and _G.petReviving then
            BANETO_PrintDev("HEKILI CHECK PET!")
            if _G.revorcall == nil then
                _G.revorcall = false
            end
            if _G.revorcall == false then
                BANETO_CastSpell(883)
                _G.revorcall = true
            elseif _G.revorcall == true then
                BANETO_CastSpell(982)
                _G.revorcall = false
            end
        elseif BANETO_UnitHealth("pet") < 25 and not BANETO_IsSpellOnCooldown(136) and _G.petHealing then
            BANETO_CastSpell(136)
        end
    end
end
function needauto()
    local classLoc,classEng,classNum = UnitClass("player")
    if classNum == 3 and GetSpecialization() == 1 and UnlockedTargetReaction("target") ~= nil and not UnitAffectingCombat('player') and not IsPlayerMoving() and not UnitIsDeadOrGhost('player') then
        BANETO_CastSpell(6603)
    end
end
function stealth()
    if Hekili_Primary_B1.Ability and Hekili_Primary_B1.Ability.copy ~= nil then
        if (Hekili_Primary_B1.Ability.id == 5215 or Hekili_Primary_B1.Ability.id == 1784) and not IsFlying() and BANETO_UnitHealth("player") >= 75 and GetShapeshiftDruid() ~= 3 then
            if not UnitAffectingCombat('player') then
                if Hekili_Primary_B1.Ability then
                    BANETO_CastSpell(Hekili_Primary_B1.Ability.id, true)
                end
            end
        end
    end
end
function _G.formatItemForHekili(itemArg)
    item = item:gsub('%b()', '')
    item = item.gsub(item, '[ \t]+%f[\r\n%z]', '')
    return item
end
function formatAbility(ability)
    ability = ability:gsub('%b()', '')
    ability = string.gsub(ability, '[ \t]+%f[\r\n%z]', '')
    return ability
end
function castnextspell()
    if _G.checkAuto then
        needauto()
    end
    if _G.HEKILI_DEBUGGING_LOGS then
        BANETO_PrintPlugin("HEKILI DEBUG D")
    end
    if Hekili_Primary_B1 and Hekili_Primary_B1.Ability then
        if _G.HEKILI_DEBUGGING_LOGS then
            BANETO_PrintPlugin("HEKILI DEBUG E")
        end
        BANETO_CastSpell(Hekili_Primary_B1.Ability.id, true)
    end
end

function _G.isHekiliLoaded()
    if Hekili_Primary_B1 and GetSpecialization() and GetSpecialization() ~= 0 and GetSpecialization() ~= 5 then
        if not _G.SettingsDone then
            _G.petHealing = false
            _G.petReviving = false
            _G.castGTAOE = true
            _G.useItems = true
            _G.checkAuto = false
            _G.OOCStealth = true
	    _G.hekiliTurn = false
            _G.SettingsDone = true
            BANETO_Print("Hekili loaded & ready to fight...")
        end
        return true
    end
end

function fullCast()
    if not UnitIsDead('target') then
        if UnlockedTargetReaction("target") ~= nil then
            if UnlockedTargetReaction("target") < 5 then
                if not UnitChannelInfo("player") then
                    if Hekili_Primary_B1 and Hekili_Primary_B1.Ability and Hekili_Primary_B1.Ability.link ~= nil and _G.useItems then
                        castItem(Hekili_Primary_B1.Ability)
                        if _G.HEKILI_DEBUGGING_LOGS then
                            BANETO_PrintPlugin("HEKILI DEBUG B")
                        end
                    else
                        if _G.HEKILI_DEBUGGING_LOGS then
                            BANETO_PrintPlugin("HEKILI DEBUG C")
                        end
                       castnextspell()
                    end
                    if _G.castGTAOE then
                        GTAOE()
                    end
                end
            end
        end
    end
end

function _G.BANETO_GossipTalkingForQuest() --not documented
    if GossipFrame.GreetingPanel:IsVisible() then
        local gossip = C_GossipInfo.GetOptions()
        for i = 1, #gossip do
            local gossipEntry = gossip[i]
            if gossipEntry then
                local gossipType = gossipEntry["icon"]
                local gossipOptionId = gossipEntry["gossipOptionID"]
                if gossipType == 132053 then
                    C_GossipInfo.SelectOption(gossipOptionId)
                end
            end
        end
    end
end

