        for i = 1, #gossip do
            local gossipEntry = gossip[i]
            if gossipEntry then
                local gossipType = gossipEntry["icon"]
                local gossipOptionId = gossipEntry["gossipOptionID"]
                if gossipType == 132052 then
                    C_GossipInfo.SelectOption(gossipOptionId)
                end
            end
        end
    end
end



