     local start, duration, _, _ = GetSpellCooldown(spellid)
     return duration
end
function _G.BANETO_Hekili()
    if not _G.petHealing and not _G.petReviving then
    else
        checkpet()
    end
    if _G.OOCStealth then
        stealth()
    end
    start, duration, enabled, modRate = GetSpellCooldown(61304)
    if _G.nocd and duration == 0 and NoRo_IsActive() then
        _G.hekiliTurn = false
    end
    if _G.hekiliTurn and duration == 0 and NoRo_IsActive() then
        if _G.HEKILI_DEBUGGING_LOGS then
            BANETO_PrintPlugin("HEKILI DEBUG A")
        end
        fullCast()
        _G.nocd = true
    end
    if not NoRo or (NoRo_IsActive() == nil or not NoRo_IsActive()) then
        fullCast()
    end
end

