_G.BANETO_DEEPWATER_FLYING = false
SWITCHING_GROUND_TO_FLYING = 0
function _G.UpdateGotoPositionWa()
    if BANETO_DEEPWATER_FLYING == true and IsSwimming() and BANETO_State ~= "BREATH"  then
        BANETO_FlyingNavigator()
        return false
    end
    if not IsFlying() then
        BANETO_InitGroundNavValues()
    end
	if (BANETO_State ~= "GHOST"  or BANETO_FLYING_GHOST == true) and BANETO_State ~= "REGEN" and (not UnitAffectingCombat("player") or IsMounted() or BANETO_HasBuff("player",783) or BANETO_IsFlyableBird()) and (not BANETO_RETAIL_MAMMOTH_DELAY_FLYINGBLOCK or BANETO_RETAIL_MAMMOTH_DELAY_FLYINGBLOCK < GetTime()) then
        if not IsFlying() and BANETO_IsFlyingAscendNeeded() and not IsIndoors() and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) then
            if not BANETO_EXECUTE_FLY_ASCEND_MSGDELAY or BANETO_EXECUTE_FLY_ASCEND_MSGDELAY < GetTime() then
                BANETO_PrintState("Flying ascend start.")
                BANETO_RANDOMJUMP_DELAY = GetTime()+10
                BANETO_EXECUTE_FLY_ASCEND_MSGDELAY = GetTime()+5
            end
            BANETO_EXECUTE_FLY_ASCEND = true
        end
        if SWITCHING_GROUND_TO_FLYING and 4 <= SWITCHING_GROUND_TO_FLYING and not IsFlying() and BANETO_IsDragonRiding() and BANETO_State ~= "GHOST" then
            local vigor = BANETO_GetCurrentVigor()
            if vigor and 0 < vigor and (not vigorEscapeSwitchingNavs or vigorEscapeSwitchingNavs < GetTime()) then
                SWITCHING_GROUND_TO_FLYING = 0
                BANETO_LAVA_ESCAPE_VIA_FLY = true
                vigorEscapeSwitchingNavs = GetTime()+60
                C_Timer.After(6,function()
                    BANETO_LAVA_ESCAPE_VIA_FLY = nil
                end)
            else
                local vigorwait = BANETO_SETTING_VIGORWAIT or 2
                local waitingFor = vigorwait*5
                BANETO_DelayMeshPathing(waitingFor)
                if 10 < waitingFor or waitingFor == 0 then
                    waitingFor = 10
                end
                SWITCHING_GROUND_TO_FLYING=0
                BANETO_PrintWarning("Switching between flying and ground navigation too often! Standing still for ".. waitingFor .." seconds to regain vigor.")
                _G.BANETO_DRAGON_LEGIT = GetTime()
                return false
            end
        end
        if IsFlying() and BANETO_FLYING_PROFILE  and BANETO_FLYING_PROFILE  == true and not BANETO_EXECUTE_FLY_ASCEND then
            if not BANETO_ISFLYING_MSG then
                BANETO_ISFLYING_MSG = true
                BANETO_PrintState("Switching: Ground -> Flying Navigator!")
                SWITCHING_GROUND_TO_FLYING = SWITCHING_GROUND_TO_FLYING+1
                BANETO_LogDragonride("Switching Ground to Flying nav")
            end

            if waPath then
                waPath = nil
            end
            BANETO_FlyingNavigator()
            return false
        elseif BANETO_ISFLYING_MSG and BANETO_ISFLYING_MSG == true and not BANETO_EXECUTE_FLY_ASCEND then
            BANETO_ISFLYING_MSG = nil
        end
        if BANETO_EXECUTE_FLY_ASCEND and BANETO_EXECUTE_FLY_ASCEND == true   and BANETO_State ~= "FIGHTING"  and BANETO_State ~= "CLEAR-PATH"  and not IsFalling() then
            if not flyAscendDelay or flyAscendDelay < GetTime() then
                BANETO_FlyAscendExecute()
                --flyAscendDelay = GetTime()+1
            end
            return false
        end
    else
        BANETO_EXECUTE_FLY_ASCEND = nil
        BANETO_ISFLYING_MSG = nil
    end
    --[[ print(x) --]]
	--[[ BANETO_PrintDev("run go to func ewt") --]]
    local form = GetShapeshiftForm()
	if IsMounted() then
		BANETO_EWT_NODEREACHED_DISTANCE = 2.6
	elseif form and form ~= 0 then
	    BANETO_EWT_NODEREACHED_DISTANCE = 2.2
	else
		BANETO_EWT_NODEREACHED_DISTANCE = 1.1
	end

	if (not BANETO_RESETPATH_DELAY or BANETO_RESETPATH_DELAY < GetTime()) and BANETO_ISRUNNING and not CRECHE_ROLE and BANETO_GetState() ~= "FP-TAXI" then
        if _internal.Software() == "nn" then
            BANETO_RESETPATH_DELAY = GetTime() + 10
        elseif _internal.Software() == "tnk" then
            BANETO_RESETPATH_DELAY = GetTime() + 20
		end
		--waPath = nil
        BANETO_LUABOX_TARGETSTICK = true
		nnAvoidPath = nil
	end

	if waPath ~= nil and not BANETO_IsFlyingAscendNeeded() and not BANETO_EXECUTE_FLY_ASCEND then
        local waPathX;
        local PlayerX, PlayerY, PlayerZ;
        local destX;
        local destY;
        local destZ ;
        forwardsurgedelay = GetTime()+2
        TIMETOLAND = nil
		if _internal.Software() == "tnk" and waPath and #waPath and waPath[#waPath] and waPath[pathIndex] then
            waPathX = waPath[#waPath]["x"]
            PlayerX, PlayerY, PlayerZ = BANETO_ObjectPosition("Player");
            destX = waPath[pathIndex]["x"]
            destY = waPath[pathIndex]["y"]
            destZ = waPath[pathIndex]["z"]
		elseif _internal.Software() == "nn" and waPath and #waPath and waPath[#waPath] and waPath[pathIndex] then
            waPathX = waPath[#waPath]["x"]
            PlayerX, PlayerY, PlayerZ = BANETO_ObjectPosition("Player");
            destX = tonumber(waPath[pathIndex]["x"])
            destY = tonumber(waPath[pathIndex]["y"])
            destZ =  tonumber(waPath[pathIndex]["z"])
		end
        if (destX and destX == 0) or (waPath and pathIndex and waPath[pathIndex] and waPath[pathIndex]["x"] and waPath[pathIndex]["x"] == "") then
            waPath = nil
            waPathBufferCopy = nil
            waPathBuffer = nil
            BANETO_PrintBambo("path is bad, should return early")
            if BANETO_IsDragonRiding() and not IsFlying() then
                BANETO_PrintBambo("Ground dragon path bad, force flying")
                if not banetoGroundDragonStucks then
                    banetoGroundDragonStucks = 1
                else
                    banetoGroundDragonStucks = banetoGroundDragonStucks+1
                    if banetoGroundDragonStucks > 7 then
                        DRAGONRIDING_FORCEFLY = true
                        banetoGroundDragonStucks = nil
                    end
                end
                --BANETO_DelayMeshPathing(3)
            end
        end
        if not IsSwimming() and not IsFlying() then
            if not BANETO_PITCH_DELAY_NEUTRAL or BANETO_PITCH_DELAY_NEUTRAL < GetTime() then
                BANETO_SetFlyingPitch(0)
                BANETO_PITCH_DELAY_NEUTRAL = GetTime()+3+math.random(1,4)
            end
        end
        local playerXYZ = BANETO_GetLuaBoxDestination()
        if not playerXYZ then
            return
        end
        local finalTargetX, finalTargetY, finalTargetZ = playerXYZ[1],playerXYZ[2],playerXYZ[3]
        if IsSwimming() and IsSubmerged() then
            if not BANETO_PITCH_DELAY or BANETO_PITCH_DELAY < GetTime() then
                BANETO_PITCH_DELAY = GetTime()+0.3
                local d = BANETO_GetDistance3D(PlayerX, PlayerY, 1,destX,destY,1)
                if d and destZ > PlayerZ then
                    local h = destZ-PlayerZ
                    local alpha = (math.atan(h/d))*180/math.pi
                    local angle = alpha/90*math.pi/2
                    BANETO_SetFlyingPitch(angle)
                    BANETO_PrintState("Set underwater submerged pitch")
                elseif d and PlayerZ > destZ then
                    local h = PlayerZ-destZ
                    local alpha = (math.atan(h/d))*180/math.pi
                    local angle = alpha/90*(math.pi)/2
                    BANETO_SetFlyingPitch(-angle)
                    BANETO_PrintState("Set underwater submerged pitch")
                end
            end
        end
        if IsSwimming() and BANETO_TARGET and BANETO_PlayerPosition(finalTargetX, finalTargetY,PlayerZ,4) and BANETO_STATE ~= "BREATH" then
            local banetoTargetX, banetoTargetY, banetoTargetZ = BANETO_ObjectPosition(BANETO_TARGET)
            if not BANETO_SWIMMING_DIVE and PlayerZ > banetoTargetZ and (not BANETO_SWIMMING_DIVE_BLOCK or BANETO_SWIMMING_DIVE_BLOCK < GetTime()) then
                BANETO_PrintState("Water Navigator - Diving now")
                BANETO_AscendStop()
                BANETO_SitStandOrDescendStart()
                BANETO_SWIMMING_DIVE = GetTime()+2
                BANETO_SWIMMING_DIVE_BLOCK = GetTime()+1
            end
        end
        if IsSwimming() and BANETO_TARGET and BANETO_PlayerPosition(finalTargetX, finalTargetY,PlayerZ,4) and BANETO_STATE ~= "BREATH" then
            local banetoTargetX, banetoTargetY, banetoTargetZ = BANETO_ObjectPosition(BANETO_TARGET)
            if not BANETO_SWIMMING_DIVE_ASCEND and  banetoTargetZ > PlayerZ  then
                BANETO_PrintState("Water Navigator - Ascend now")
                BANETO_DescendStop()
                BANETO_JumpOrAscendStart()
                BANETO_SWIMMING_DIVE_ASCEND = GetTime()+1
            end
        end
		if not stuckCount then
			stuckCount = 0
		end
        if  waPath and PlayerX and destX and destY and destZ  and pathIndex and waPath[pathIndex] then
            local requiredFacing = BANETO_GetFacingValue(tonumber(waPath[pathIndex]["x"]),tonumber(waPath[pathIndex]["y"]),tonumber(waPath[pathIndex]["z"]))
            if requiredFacing then
                local currentRotation = BANETO_GetObjectFacing("player")
                local abs = math.abs(currentRotation-requiredFacing)
                if abs then
                    --BANETO_PrintBambo("ABS: "..abs)
                else
                    --BANETO_PrintBambo("ABS: nil")
                end
                if abs and (abs < 0.4 or abs > 5.9) then
                    --BANETO_PrintBambo("ABS: Move Forward")
                    BANETO_MoveForwardStart()
                    stopMovementBecauseWrongFacingDelayer = GetTime()+0.4
                elseif (not stopMovementBecauseWrongFacingDelayer or stopMovementBecauseWrongFacingDelayer < GetTime()) then
                    BANETO_StopMovementWithoutDeletingPath()
                end
            else
                BANETO_MoveForwardStart()
            end
        end
        local specialDistance = BANETO_GetDistance3D(PlayerX, PlayerY, 1, destX, destY, 1)
        if waPath and PlayerX and destX and destY and destZ and pathIndex and waPath[pathIndex] and specialDistance and ((specialDistance < BANETO_EWT_NODEREACHED_DISTANCE and pathIndex ~= #waPath) or (specialDistance < BANETO_EWT_NODEREACHED_DISTANCE+1 and pathIndex == #waPath) or pathIndex == 1) then
            pathIndex = pathIndex + 1
            if waPath and pathIndex > #waPath then
                pathIndex = 1
                waPath = nil
                if BANETO_IsDragonRiding() and not IsFlying() then
                    BANETO_PrintBambo("Ground dragon stuck, force flying")
                    if not banetoGroundDragonStucks then
                        banetoGroundDragonStucks = 1
                    else
                        banetoGroundDragonStucks = banetoGroundDragonStucks+1
                        if banetoGroundDragonStucks > 5 then
                            DRAGONRIDING_FORCEFLY = true
                            banetoGroundDragonStucks = nil
                        end
                    end
                    --BANETO_DelayMeshPathing(3)
                end
                BANETO_StopMovement()
            else
                local valu = BANETO_GetFacingValue(tonumber(waPath[pathIndex]["x"]),tonumber(waPath[pathIndex]["y"]),tonumber(waPath[pathIndex]["z"]))
                if valu then
                    BANETO_SetPlayerAnglesLuabox(valu)
                    local currentRotation = BANETO_GetObjectFacing("player")
                    local abs2 = math.abs(currentRotation-valu)
                    if abs2 and (abs2 < 0.4 or abs2 > 5.9) then
                        BANETO_MoveForwardStart()
                    end
                end
            end
        elseif waPath and pathIndex and waPath[pathIndex] then
            if waPath and pathIndex then
		        BANETO_SetPlayerAnglesLuabox(BANETO_GetFacingValue(destX,destY,destZ))
		    end
			if not ewtStuckCheckDelay or ewtStuckCheckDelay < GetTime() then
				ewtStuckCheckDelay = GetTime()+0.01
				if lastX == PlayerX and lastY == PlayerY then
					if not IsSwimming() then
						stuckCount = stuckCount + 1
					end
				 if BANETO_EWT_JUMPTOUNSTUCK_COUNTER and BANETO_EWT_JUMPTOUNSTUCK_COUNTER > 6 and IsMounted() then
					 BANETO_EWT_JUMPTOUNSTUCK_COUNTER = nil
					 BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+25
					 BANETO_Dismount()
					 BANETO_PrintState("Dismount to Unstuck! Blacklist Mounting for 25 Seconds!")
				 end
					if BANETO_EWT_JUMPTOUNSTUCK_COUNTER and BANETO_EWT_JUMPTOUNSTUCK_COUNTER > 7 and BANETO_SETTING_PUSH_STUCKS and BANETO_SETTING_PUSH_STUCKS == true then
						if not EWT_STUCK_PUSH_SENT then
							BANETO_PushNotification("Stuck")
							EWT_STUCK_PUSH_SENT = true
						end
					end
					if stuckCount > 200 then
						BANETO_PrintDev("STUCKJUMP")
						BANETO_JumpAllowed = true
						BANETO_JumpOrAscendStart()
						stuckCount = 0
						if not BANETO_EWT_JUMPTOUNSTUCK_COUNTER then
							BANETO_EWT_JUMPTOUNSTUCK_COUNTER = 0
						end
						BANETO_EWT_JUMPTOUNSTUCK_COUNTER = BANETO_EWT_JUMPTOUNSTUCK_COUNTER+1
						waPath = nil
					end
				end
			end
		end
	else
		if not ewtTargetDebugCount then
			ewtTargetDebugCount = 0
		end
		if (lastX == PlayerX or lastY == PlayerY) and BANETO_ISRUNNING and (BANETO_State == "GRIND" or BANETO_State == "GATHER") then
			--ewtTargetDebugCount = ewtTargetDebugCount + 1
			if ewtTargetDebugCount > 2000 and BANETO_TARGET then
		    elseif not BANETO_TARGET and ewtTargetDebugCount > 2000 then
                BANETO_TARGET = nil
                waPath = nil
                ewtTargetDebugCount = 0
			end
		end
		lastX = PlayerX
		lastY = PlayerY
		lastZ = PlayerZ
	end
end

