function _G.BANETO_IsDragonRiding()
    if BANETO_GetMaxVigor() and (IsMounted() or BANETO_IsFlyableBird()) and not BANETO_IsDeadOrGhost() and BANETO_GetMaxVigor() >= 2 and not BANETO_HasBuff("player",404468) then
        return true
    end
    for i = 1, 40 do
        local name, _, _, _, _, _, _, _, _, SpellID  = UnitBuffWrapper("PLAYER", i)
        if SpellID == nil then return false end
        if SpellID == 368896 or SpellID == 425338 or SpellID == 417888 or SpellID == 427549 or SpellID == 368899 or SpellID == 368893 or SpellID == 360954 or SpellID == 368901 or SpellID == 412088 then
            if not BANETO_HasBuff("player",404468) then
                return true
            end
        end
    end
    return false
end

