function _internal.GetLocalPlayerPath(ex, ey, ez, allowSwim)
  local nodes = {}
  local mapID = select(8, GetInstanceInfo());
  local px, py, pz = GetUnitPosition("player")
  local generatedPath = FindPath(mapID, px, py, pz, ex, ey, ez, false, true, BANETO_WA_ALLOWWATERPATH)
  for i = 1, GetActiveNodeCount() do
    local nodeX,nodeY,nodeZ = GetActiveNodeByIndex(i)
    table.insert(nodes, { nodeX,nodeY,nodeZ });
  end
  return nodes
end

