function _G.BANETO_PathHandlerNn(path)
    local newPathNn = {}
    local maxIterations;
    if #path and #path > 6 then
        maxIterations = 6
    else
        maxIterations = #path-1
    end
    for i = 1,maxIterations do
        local x = path[i]["x"]
        local y = path[i]["y"]
        local z = path[i]["z"]
        local xX = path[i+1]["x"]
        local yY = path[i+1]["y"]
        local zZ = path[i+1]["z"]
        x,y,z,xX,yY,zZ = tonumber(x),tonumber(y),tonumber(z),tonumber(xX),tonumber(yY),tonumber(zZ)
        if x and y and z and yY and zZ and xX then
            local date = date()
            if type(x) == "number" and type(y) == "number" and type(z) == "number"  and type(xX) == "number" and type(yY) == "number" and type(zZ) == "number"  then
                local m = (y-yY)/(x-xX)
                local n = yY-m*xX
                local l = math.sqrt((x-xX)*(x-xX)+(y-yY)*(y-yY))
                local steps = math.floor(l/2)
                for q = 0, steps do
                    local xNeu = x+(xX-x)/steps*q
                    local yNeu = m*xNeu+n
                    local zNeu = (z+zZ)/2
                    local spot = {
                        ["x"]=xNeu,
                        ["y"]=yNeu,
                        ["z"]=zNeu
                    }
                    table.insert(newPathNn,spot)
                end
            end
        end
    end
    if newPathNn and 1 < #newPathNn then
        waPathBuffer = newPathNn
    end
end
