function _G.BANETO_MeshTo(x,y,z)
    if x and y and z then
        --BANETO_PrintBambo("Mesh pathing: ".. x .. y .. z)
    end
    if x == 0 and y == 0 and z == 0 and not UnitCastingInfo("player") then
        BANETO_PrintWarning("MeshTo 0 0 0")
        waPath = nil
        flyingPath = nil
        BANETO_StopMovement()
        if BANETO_TARGET then
            local name = BANETO_ObjectName(BANETO_TARGET)
            if not name then
                name = "Unknown Name"
            end
            BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
            BANETO_PrintWarning("MeshTo 0 0 0 -- something wrong with object/unit: "..name .. " we are now blacklisting it.")
        end
        return false
    end
    if waPathBufferLast then
        if not waPathBufferLastTimer then
            waPathBufferLastTimer = GetTime()+25
        elseif waPathBufferLastTimer and waPathBufferLastTimer > GetTime() then
            waPathBufferLastTimer = nil
            waPathBufferLast = nil
        end
    end
    if BANETO_DELAY_MESHPATHING and  BANETO_DELAY_MESHPATHING > GetTime() then
        if not BANETO_LAVA_ESCAPE and not BANETO_LAVA_ESCAPE_VIA_FLY then
            if Unlocker("EWT") then
                StopEwtMovement()
            elseif Unlocker("LUA") then
                BANETO_StopMovement()
            end
            BANETO_PrintBambo("Mesh pathing is delayed!")
            return false
        end
    end

    if BANETO_SETTING_USELANDINGSPOTS and BANETO_SETTING_USELANDINGSPOTS == true then
        if BANETO_SETTING_USELANDINGSPOTS_TOWN == false or (BANETO_GetState() == "REPAIR" or BANETO_GetState() == "MAIL" or BANETO_GetState() == "AMMO" or BANETO_GetState() == "GOODS" or BANETO_GetState() == "SELL") then
            if IsFlying() then
                local cmap = BANETO_GetMapId()
                local allLandingSpots = BANETO_ConcatenateTables(BANETO_SETTING_LANDINGSPOTS,BANETO_SETTING_LANDINGSPOTS_PROFILE)
                for i=1,#allLandingSpots do
                    local xcheck,ycheck,zcheck,mapcheck = allLandingSpots[i][1],allLandingSpots[i][2],allLandingSpots[i][3],allLandingSpots[i][4]
                    if cmap == mapcheck then
                        local d = BANETO_GetDistance3D(xcheck,ycheck,zcheck,x,y,z)
                        if d and 250 > d then
                            x,y,z = xcheck,ycheck,zcheck
                            LANDING_SPOT_ACTIVE = true
                            LANDING_SPOT = {check,ycheck,zcheck}
                        end
                        if IsFlying() and LANDING_SPOT_ACTIVE and LANDING_SPOT then
                            local xLandingCheckPlayer,yLandingCheckPlayer,zLandingCheckPlayer = BANETO_ObjectPosition("player")
                            local xLandingCheckSpot,yLandingCheckSpot,zLandingCheckSpot= LANDING_SPOT[1],LANDING_SPOT[2],LANDING_SPOT[3]
                            local distancePlayerToLandingSpot = BANETO_GetDistance3D(xLandingCheckSpot,yLandingCheckSpot,zLandingCheckSpot,xLandingCheckPlayer,yLandingCheckPlayer,zLandingCheckPlayer)
                            if distancePlayerToLandingSpot and distancePlayerToLandingSpot < 20 and zLandingCheckPlayer > zLandingCheckSpot then
                                BANETO_SitStandOrDescendStart()
                                BANETO_PrintState("Landing on landing spot. NOW!")
                                C_Timer.After(3,BANETO_DescendStop)
                            end
                        end
                    end
                end
            elseif not IsFlying() and LANDING_SPOT_ACTIVE and LANDING_SPOT then
                local xLandingCheckPlayer,yLandingCheckPlayer,zLandingCheckPlayer = BANETO_ObjectPosition("player")
                local xLandingCheckSpot,yLandingCheckSpot,zLandingCheckSpot= LANDING_SPOT[1],LANDING_SPOT[2],LANDING_SPOT[3]
                local d = BANETO_GetDistance3D(xLandingCheckSpot,yLandingCheckSpot,zLandingCheckSpot,xLandingCheckPlayer,yLandingCheckPlayer,zLandingCheckPlayer)
                if d and d < 20 then
                    BANETO_BlockAllMountingAndFlying(45)
                    BANETO_PrintState("Landing finished, blacklisting flying for 45 seconds.")
                    LANDING_SPOT_ACTIVE = nil
                    LANDING_SPOT = nil
                end
            end
        end
    end


    BANETO_LUABOX_DESTINATION = {x, y, z}
    if BANETO_UNSTUCK_ROUTE_ISACTIVE and BANETO_UNSTUCK_ROUTE_ISACTIVE == true then
        if not unstuckRouteIndex then
            unstuckRouteIndex = 1
        end
        x,y,z = BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][1],BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][2],BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][3]
    end
    if BANETO_STATE_ITERATIONS and BANETO_STATE_ITERATIONS <= 1 and not _G.BANETO_BANKAI_FARM1 and (BANETO_State == "QUEST-PULSE" or BANETO_State == "GRIND") then
        BANETO_PrintBambo("Mesh pathing is delayed due to state iterations")
        return false
    end
    if BANETO_BLOCKMOVING_REICHI then
        BANETO_PrintBambo("Mesh pathing is blocked by reichi!")
        return false
    end
    if not x or not y or not z then
        BANETO_PrintDev("Mesh To Fail C")
        return false
    end
    if x == false and not y then
        BANETO_PrintBambo("Mesh pathing call failed")
        return false
    end
	if BANETO_BLOCKMOVING and BANETO_BLOCKMOVING == true and not BANETO_IsDeadOrGhost() and not BANETO_ANERIKC_FORCEMOVE and not BANETO_ANERIKC_FORCEMOVE_VENDOR and not BANETO_HYPERSPAWN_FORCEMOVE then
        if Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0 then
            BANETO_StopMovement()
        elseif Unlocker("EWT") and BANETO_GetUnitSpeed("player") > 0 then
            StopEwtMovement()
        end
        BANETO_PrintBambo("Mesh pathing call block moving bool")
		return false
	end

    if BANETO_AreWeInLowerOribos() and BANETO_RETAIL_OFFMESH_ORIBOS_DOWN then
        BANETO_RETAIL_OFFMESH_ORIBOS_DOWN = nil
    end
    if BANETO_AreWeInUpperOribos() and BANETO_RETAIL_OFFMESH_ORIBOS_UP then
        BANETO_RETAIL_OFFMESH_ORIBOS_UP = nil
    end

    if not BANETO_ORIBOS_OFFMESH_MASTER or BANETO_ORIBOS_OFFMESH_MASTER < GetTime() then
        if BANETO_AreWeInLowerOribos() and (BANETO_RETAIL_OFFMESH_ORIBOS_UP or BANETO_IsDestinationInUpperOribos()) and BANETO_GetMapId() == 2222  then
            waPath = nil
            ewtPath = nil
            BANETO_OribosGoUp()
            BANETO_PrintBambo("Oribos up")
            BANETO_RETAIL_OFFMESH_ORIBOS_UP = true

            return false
        end
        if BANETO_AreWeInUpperOribos() and (BANETO_RETAIL_OFFMESH_ORIBOS_DOWN or BANETO_IsDestinationInLowerOribos()) and BANETO_GetMapId() == 2222 then
            waPath = nil
            ewtPath = nil
            BANETO_OribosGoDown()
            BANETO_PrintBambo("Oribos down")
            BANETO_RETAIL_OFFMESH_ORIBOS_DOWN = true
            return false
        end
    end

    if BANETO_RETAIL_OFFMESH_ORIBOS_UP or BANETO_RETAIL_OFFMESH_ORIBOS_DOWN then
        BANETO_PrintBambo("Oribos offmesh")
        return false
    end

    if BANETO_EMERGENCY_STUCK_HS and BANETO_EMERGENCY_STUCK_HS == true and not BANETO_IsDeadOrGhost() and not UnitAffectingCombat("player") and not MerchantFrame:IsVisible() and not SendMailFrame:IsVisible() then
        local startTime, duration, enable = GetItemCooldown(6948)
        if BANETO_GetUnitSpeed("player") == 0 and duration == 0 and not UnitCastingInfo("player") then
            BANETO_UseItem(6948)
            BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime()+15
            BANETO_VENDOR_UPDATE_DELAY = GetTime()+10
            BANETO_TAXI_DELAYER = GetTime()+25
            BANETO_PrintState("Full Stuck detected, using hearthstone to unstuck!")
            if BANETO_SETTING_PUSH_STUCK and BANETO_SETTING_PUSH_STUCK == true then
                BANETO_PushNotification("Stuck")
            end
            BANETO_EMERGENCY_STUCK_HS_LASTUSE = GetTime()+11
            BANETO_DelayMeshPathing(10)
            BANETO_Wmb_StuckTick = 0
        elseif BANETO_GetUnitSpeed("player") > 0 then
            if Unlocker("LUA") then
                BANETO_StopMovement()
            elseif Unlocker("EWT") then
                StopEwtMovement()
            end
        end
        if BANETO_EMERGENCY_STUCK_HS_LASTUSE and BANETO_EMERGENCY_STUCK_HS_LASTUSE < GetTime() then
            BANETO_EMERGENCY_STUCK_HS = nil
            BANETO_EMERGENCY_STUCK_HS_LASTUSE = nil
        end
        BANETO_PrintBambo("Hs unstuck block path")
        return
    end



    if Unlocker("EWT") then
        BANETO_WmbUnstucking()
	elseif Unlocker("LUA") then
		BANETO_WaUnstucking()
    end

    local mountrangecheck = BANETO_RetailMountRangeCheck()
	if Unlocker("LUA") and not IsIndoors() and mountrangecheck and mountrangecheck == true and (not BANETO_MOUNT_INDOORS_3SECS_STOPPER or BANETO_MOUNT_INDOORS_3SECS_STOPPER < GetTime()) and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_IsDeadOrGhost() then
        local _,_,class = UnitClass("player")
        if not UnitAffectingCombat("player") and BANETO_GetUnitSpeed("player") == 0 and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not IsMounted() and (class ~= 11 or BANETO_DEFINED_PROFILE_TYPE == "Battleground" or BANETO_SETTING_RETAIL_DRUID_USEMOUNT) then
            if not BANETO_RETAIL_LB_MOUNTSUMMON or BANETO_RETAIL_LB_MOUNTSUMMON < GetTime() then
                local _,_,class = UnitClass("player")
                if GetShapeshiftDruid() ~= 0 and class ~= 5 then
                    CancelShapeshift()
                end
                C_MountJournal.SummonByID(0)
                BANETO_MOUNT_USAGE_DELAY = GetTime()+4
                BANETO_RETAIL_LB_MOUNTSUMMON = GetTime()+4
                if not BANETO_RETAIL_MOUNT_CASTCOUNT then
                    BANETO_RETAIL_MOUNT_CASTCOUNT = 1
                else
                    BANETO_RETAIL_MOUNT_CASTCOUNT = BANETO_RETAIL_MOUNT_CASTCOUNT+1
                end
                if BANETO_RETAIL_MOUNT_CASTCOUNT and BANETO_RETAIL_MOUNT_CASTCOUNT >= 5 then
                    BANETO_STOPMOUNTBECAUSEUNSTUCK= GetTime()+16
                    BANETO_PrintState("Mountspam detected! Blacklisting mounting for 10 seconds!")
                end
            end
            BANETO_PrintBambo("Mesh pathing call return A")
            return false
        elseif not UnitAffectingCombat("player") and BANETO_GetUnitSpeed("player") ~= 0  and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not IsMounted() and (class ~= 11 or BANETO_DEFINED_PROFILE_TYPE == "Battleground" or BANETO_SETTING_RETAIL_DRUID_USEMOUNT) then
            BANETO_StopMovement()
            BANETO_PrintBambo("Mesh pathing call return B")
            return false
        end
        if class == 11 and BANETO_DEFINED_PROFILE_TYPE ~= "Battleground" and BANETO_SETTING_RETAIL_DRUID_USEMOUNT == false then
            if IsMounted() then
                BANETO_Dismount()
            end
            local travel = 292629
            if BANETO_State ~= "FIGHTING" and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_HasBuff("player",travel)then
                if not BANETO_RETAIL_LB_MOUNTSUMMON or BANETO_RETAIL_LB_MOUNTSUMMON < GetTime() then
                    if UnitAffectingCombat("player") then
                        BANETO_IMPROVISED_TRAVELFORM = true
                    end
                    BANETO_CastSpell(travel,true)
                    BANETO_RETAIL_LB_MOUNTSUMMON = GetTime()+1
                    if not BANETO_RETAIL_MOUNT_CASTCOUNT then
                        BANETO_RETAIL_MOUNT_CASTCOUNT = 1
                    else
                        BANETO_RETAIL_MOUNT_CASTCOUNT = BANETO_RETAIL_MOUNT_CASTCOUNT+1
                    end
                    if BANETO_RETAIL_MOUNT_CASTCOUNT and BANETO_RETAIL_MOUNT_CASTCOUNT >= 4 then
                        BANETO_STOPMOUNTBECAUSEUNSTUCK= GetTime()+10
                        BANETO_PrintState("Shapeshift spam detected! Blacklisting shapeshift for 10 seconds!")
                    end
                end
                BANETO_PrintBambo("Mesh pathing call return C")
                return false
            elseif BANETO_State ~= "FIGHTING" and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_HasBuff("player",travel) then
                BANETO_PrintBambo("Mesh pathing call return D")
                return false
            end
        end
    end


	--[[ TRIGGER LUABOX JUMP UNSTUCK --]]
	if  Unlocker("LUA")  and lb then
		BANETO_LuaboxUnstucker()
	end
    if Unlocker("LUA") and (BANETO_GetUnitSpeed("player") <= 0 or not waPath or BANETO_LUABOX_TARGETSTICK)  then
		local map,_ = BANETO_GetMapId()
		BANETO_LUABOX_TARGETSTICK = nil
		local xWmGood,yWmGood,zWmGood,distanceWmGood = x, y, z, 0
		BANETO_LUABOX_DESTINATION = {x, y, z}
		if xWmGood and not IsFlying() and BANETO_DEEPWATER_FLYING == false then
			local PlayerX, PlayerY, PlayerZ = BANETO_ObjectPosition("player")
			BANETO_LUABOX_DESTINATION = {xWmGood,yWmGood,zWmGood}
			BANETO_FlightLog("Generate ground path")
			--BANETO_PrintBambo("Mesh pathing call: generate path")
			local zone = BANETO_GetZoneId()
			if (BANETO_GetState() == "GATHER" or BANETO_GetState() == "GRIND") and _internal.Software() == "nn" and BANETO_TARGET and zone and zone == 2133 then
			    local distanceForGatherFix = GetDistanceBetweenObjects("player",BANETO_TARGET)
			    local speed = BANETO_GetUnitSpeed("player")
			    if distanceForGatherFix and distanceForGatherFix < 15 and speed and speed == 0 then
                    --BANETO_PrintWarning("Make sure mmaps / mesh files are installed. Zaralek")
			    end
			end
			if _internal.Software() == "nn" then
                if PlayerX and PlayerY and xWmGood and yWmGood and type(PlayerX) == "number" and type(xWmGood) == "number" and type(PlayerY) == "number" and type(yWmGood) == "number" then
                    waPath = BANETO_GeneratePath(PlayerX, PlayerY, PlayerZ,xWmGood,yWmGood,zWmGood)
                    waPathBufferCopy = waPathBuffer
                    pathIndex = 1
                end
			else
                local pathcreated = BANETO_GeneratePath(PlayerX, PlayerY, PlayerZ,xWmGood,yWmGood,zWmGood,"mainpath")
                if pathcreated and not BANETO_OLD_TINKR_PATHING then
                    local pathSplitted = BANETO_SplitPath(pathcreated,1,6)
                    waPath, pathTypeBuffer = pathSplitted,_
                    waPathDistance = 0
                    pathIndex = BANETO_GetCenterIndexInPathBankai(pathSplitted,"player")
                    --BANETO_BlockSmoothTurn(2)
                    if pathIndex == 1 and waPath and #waPath >= 2 then
                        pathIndex = 2
                    end
                    if pathIndex then
                        BANETO_PrintBambo("New tinkr mainpath with index: "..pathIndex)
                    end
                elseif pathcreated then
                    pathIndex = 1
                    waPath, pathTypeBuffer = pathcreated,_
                    waPathDistance = 0
                end
			end
		end

       local knows_sizes = {
            [177025] = 5,
            [177019] = 6,
            [183347] = 5,
            [184640] = 5,
            [173164] = 6,
            [173176] = 6,
            [173210] = 6,
            [172942] = 6,
            [175313] = 6,
            [173115] = 6,
            [173171] = 6,
            [175318] = 6
        }
        if _internal.Software() == "nn" and orangelinennwanted and not BANETO_IS_PATHAVOIDANCE_BLOCKED then
            local mapId = BANETO_GetMapId()
            if waPath and #waPath > 2 and (mapId ~= 229 or not omsbld)  then
                local objects = {}
                local px,py,pz = BANETO_ObjectPosition("player")
                for i = 1,#BANETO_OBJTS_TKR_ONLYGAMEOBJECTS do
                    local object = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS[i]
                    local ox, oy, oz = BANETO_ObjectPosition(object)
                    if not IsIndoors() and ox and oy and oz and (not BANETO_TARGET or object ~= BANETO_TARGET) then
                        local id = BANETO_ObjectId(object)
                        local orad = (knows_sizes[id] or  4)
                        table.insert(objects, { ox, oy, oz, orad })
                    end
                end
                for i = 1,#BANETO_OBJTS_TKR_ONLYUNITS do
                    local object = BANETO_OBJTS_TKR_ONLYUNITS[i]
                    local ox, oy, oz = BANETO_ObjectPosition(object)
                    if not IsIndoors() and ox and oy and oz  and UnlockedUnitIsTrivial(object) == false and not UnitAffectingCombat(object) and UnlockedTargetReaction(object) == 2 and not UnitIsPlayer(object) and not UnitIsDeadOrGhost(object)  and BANETO_State ~= "CLEAR-PATH" and BANETO_State ~= "FIGHTING" and BANETO_State ~= "GHOST" then
                        if not BANETO_TARGET then
                            local id = BANETO_ObjectId(object)
                            local orad = 14
                            table.insert(objects, { ox, oy, oz, orad })
                        elseif BANETO_TARGET and object ~= BANETO_TARGET then
                            local xT,yT,zT = BANETO_ObjectPosition(BANETO_TARGET)
                            local distance = BANETO_GetDistance3D(ox, oy, oz,xT,yT,zT )
                            if distance and 31 < distance then
                                local id = BANETO_ObjectId(object)
                                local orad = 14
                                table.insert(objects, { ox, oy, oz, orad })
                            end
                        end
                    end
                end
                for i = 1, #BANETO_GLOBAL_BLACKLIST_SPOTS do
                    local blacklistX, blacklistY, blacklistZ, blacklistRadius = BANETO_GLOBAL_BLACKLIST_SPOTS[i][1],BANETO_GLOBAL_BLACKLIST_SPOTS[i][2],BANETO_GLOBAL_BLACKLIST_SPOTS[i][3],BANETO_GLOBAL_BLACKLIST_SPOTS[i][4]
                    local distance = BANETO_GetDistance3D(blacklistX, blacklistY, blacklistZ,px,py,pz)
                    if blacklistRadius and blacklistRadius < 31 then
                        if distance and blacklistRadius+1 <  distance  then
                            table.insert(objects, { blacklistX, blacklistY, blacklistZ, blacklistRadius })
                        end
                    end
                end
                for i = 1, #BANETO_DEFINED_BLACKLIST_SPOTS do
                    local blacklistX, blacklistY, blacklistZ, blacklistRadius = BANETO_DEFINED_BLACKLIST_SPOTS[i][1],BANETO_DEFINED_BLACKLIST_SPOTS[i][2],BANETO_DEFINED_BLACKLIST_SPOTS[i][3],BANETO_DEFINED_BLACKLIST_SPOTS[i][4]
                    local distance = BANETO_GetDistance3D(blacklistX, blacklistY, blacklistZ,px,py,pz)
                    if blacklistRadius and blacklistRadius < 31 then
                        if distance and blacklistRadius+1 <  distance  then
                            table.insert(objects, { blacklistX, blacklistY, blacklistZ, blacklistRadius })
                        end
                    end
                end
                if not BANETO_BLOCK_PATH_ADJUSTION or BANETO_BLOCK_PATH_ADJUSTION < GetTime() then
                    local extra_buffer = 1.5
                    nnAvoidPath = {}
                    for i, point in ipairs(waPath) do
                        for oi, object in ipairs(objects) do
                            local dist = BANETO_GetDistance3D(tonumber(point.x), tonumber(point.y), tonumber(point.z), tonumber(object[1]), tonumber(object[2]), tonumber(object[3]))
                            if point.x and point.y and point.z and dist and dist ~= 0 and dist < (object[4] * extra_buffer) then
                                local ab = BANETO_GetAnglesBetweenPositions(object[1], object[2], 0, point.x, point.y, 0)
                                local sx, sy, sz = GetPositionFromPosition(point.x, point.y, point.z, (object[4] * extra_buffer) - dist, ab, 0)
                                point.x, point.y, point.z = sx, sy, sz
                                local spot = {
                                    ["x"]=sx,
                                    ["y"]=sy,
                                    ["z"]=sz
                                }
                                if sx and sy and sz and type(sx) == "number" and type(sy) == "number" and type(sz) == "number"  then
                                    table.insert(nnAvoidPath,spot)
                                end
                            end
                        end
                    end
                end
            end
        end
        if _internal.Software() == "tnk" and not BANETO_IS_PATHAVOIDANCE_BLOCKED then
            local ObjectManager = Tinkr.Util.ObjectManager
            local Common = Tinkr.Common
            if waPath and #waPath > 2 then
                local objects = { }
                local px,py,pz = BANETO_ObjectPosition("player")
                for object in ObjectManager:Objects(ObjectManager.Types.GameObject) do
                    local ox, oy, oz = object:position()
                    if not IsIndoors()  and ox and oy and oz and (not BANETO_TARGET or object ~= BANETO_TARGET) then
                        local id = object:id()
                        local orad = (knows_sizes[id] or (object:boundingRadius() or 4))
                        table.insert(objects, { ox, oy, oz, orad })
                    end
                end
                for object in ObjectManager:Objects(ObjectManager.Types.Unit) do
                    local ox, oy, oz = object:position()
                    if not IsIndoors() and ox and oy and oz and UnlockedUnitIsTrivial(object) == false and not UnitAffectingCombat(object) and UnlockedTargetReaction(object) == 2 and not UnitIsPlayer(object) and not UnitIsDeadOrGhost(object)  and BANETO_State ~= "CLEAR-PATH"  and BANETO_State ~= "FIGHTING" and BANETO_State ~= "GHOST" then
                        if not BANETO_TARGET then
                            local id = object:id()
                            local orad = object:boundingRadius()+9 or 14
                            table.insert(objects, { ox, oy, oz, orad })
                        elseif BANETO_TARGET and object ~= BANETO_TARGET then
                            local xT,yT,zT = BANETO_ObjectPosition(BANETO_TARGET)
                            local distance = BANETO_GetDistance3D(ox, oy, oz,xT,yT,zT )
                            if distance and 31 < distance then
                                local id = object:id()
                                local orad = object:boundingRadius()+9 or 14
                                table.insert(objects, { ox, oy, oz, orad })
                            end
                        end
                    end
                end
                for i = 1, #BANETO_GLOBAL_BLACKLIST_SPOTS do
                    local blacklistX, blacklistY, blacklistZ, blacklistRadius = BANETO_GLOBAL_BLACKLIST_SPOTS[i][1],BANETO_GLOBAL_BLACKLIST_SPOTS[i][2],BANETO_GLOBAL_BLACKLIST_SPOTS[i][3],BANETO_GLOBAL_BLACKLIST_SPOTS[i][4]
                    local distance = BANETO_GetDistance3D(blacklistX, blacklistY, blacklistZ,px,py,pz)
                    if blacklistRadius and blacklistRadius < 31 then
                        if distance and blacklistRadius+1 <  distance  then
                            table.insert(objects, { blacklistX, blacklistY, blacklistZ, blacklistRadius })
                        end
                    end
                end
                for i = 1, #BANETO_DEFINED_BLACKLIST_SPOTS do
                    local blacklistX, blacklistY, blacklistZ, blacklistRadius = BANETO_DEFINED_BLACKLIST_SPOTS[i][1],BANETO_DEFINED_BLACKLIST_SPOTS[i][2],BANETO_DEFINED_BLACKLIST_SPOTS[i][3],BANETO_DEFINED_BLACKLIST_SPOTS[i][4]
                    local distance = BANETO_GetDistance3D(blacklistX, blacklistY, blacklistZ,px,py,pz)
                    if blacklistRadius and blacklistRadius < 31 then
                        if distance and blacklistRadius+1 <  distance  then
                            table.insert(objects, { blacklistX, blacklistY, blacklistZ, blacklistRadius })
                        end
                    end
                end
                if not BANETO_BLOCK_PATH_ADJUSTION or BANETO_BLOCK_PATH_ADJUSTION < GetTime() then
                    local extra_buffer = 1.5
                    for i, point in ipairs(waPath) do
                        for oi, object in ipairs(objects) do
                            local dist = FastDistance(point.x, point.y, point.z, object[1], object[2], object[3])
                            if dist < (object[4] * extra_buffer) then
                                local ab = Common.GetAnglesBetweenPositions(object[1], object[2], 0, point.x, point.y, 0)
                                local sx, sy, sz = Common.GetPositionFromPosition(point.x, point.y, point.z, (object[4] * extra_buffer) - dist, ab, 0)
                                point.x, point.y, point.z = sx, sy, sz
                            end
                        end
                    end
                end
            end
        end

	end
end

