function _G.BANETO_MeshToOffmesh(x,y,z)
    if BANETO_STATE_ITERATIONS and BANETO_STATE_ITERATIONS <= 2 and (BANETO_State == "QUEST-PULSE" or BANETO_State == "GRIND") then
        return false
    end


    if BANETO_EMERGENCY_STUCK_HS and BANETO_EMERGENCY_STUCK_HS == true and not BANETO_IsDeadOrGhost() and not UnitAffectingCombat("player") and not MerchantFrame:IsVisible() and not SendMailFrame:IsVisible() then
        local startTime, duration, enable = GetItemCooldown(6948)
        if BANETO_GetUnitSpeed("player") == 0 and duration == 0 and not UnitCastingInfo("player") then
            BANETO_UseItem(6948)
            BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime()+15
            BANETO_VENDOR_UPDATE_DELAY = GetTime()+10
            BANETO_TAXI_DELAYER = GetTime()+25
            BANETO_PrintState("Full Stuck detected, using hearthstone to unstuck!")
            if BANETO_SETTING_PUSH_STUCK and BANETO_SETTING_PUSH_STUCK == true then
                BANETO_PushNotification("Stuck")
            end
            BANETO_EMERGENCY_STUCK_HS_LASTUSE = GetTime()+11
        elseif BANETO_GetUnitSpeed("player") > 0 then
            if Unlocker("LUA") then
                BANETO_StopMovement()
            elseif Unlocker("EWT") then
                StopEwtMovement()
            end
        end
        if BANETO_EMERGENCY_STUCK_HS_LASTUSE and BANETO_EMERGENCY_STUCK_HS_LASTUSE < GetTime() then
            BANETO_EMERGENCY_STUCK_HS = nil
            BANETO_EMERGENCY_STUCK_HS_LASTUSE = nil
        end
        return
    end
    if BANETO_DELAY_MESHPATHING and  BANETO_DELAY_MESHPATHING > GetTime() then
        if Unlocker("EWT") then
            StopEwtMovement()
        elseif Unlocker("LUA") then
            BANETO_StopMovement()
        end
        return false
    end

    if Unlocker("EWT") then
        BANETO_WmbUnstucking()
	elseif Unlocker("LUA")  then
		BANETO_WaUnstucking()
    end

    local mountrangecheck = BANETO_RetailMountRangeCheck()
	if Unlocker("LUA") and not IsIndoors() and mountrangecheck and mountrangecheck == true  and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_IsDeadOrGhost() then
        local _,_,class = UnitClass("player")
        if not UnitAffectingCombat("player") and BANETO_GetUnitSpeed("player") == 0 and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not IsMounted() and (class ~= 11 or BANETO_DEFINED_PROFILE_TYPE == "Battleground" or BANETO_SETTING_RETAIL_DRUID_USEMOUNT) then
            if not BANETO_RETAIL_LB_MOUNTSUMMON or BANETO_RETAIL_LB_MOUNTSUMMON < GetTime() then
                if GetShapeshiftDruid() ~= 0 then
                    CancelShapeshift()
                end
                C_MountJournal.SummonByID(0)
                BANETO_MOUNT_USAGE_DELAY = GetTime()+4
                BANETO_RETAIL_LB_MOUNTSUMMON = GetTime()+4
                if not BANETO_RETAIL_MOUNT_CASTCOUNT then
                    BANETO_RETAIL_MOUNT_CASTCOUNT = 1
                else
                    BANETO_RETAIL_MOUNT_CASTCOUNT = BANETO_RETAIL_MOUNT_CASTCOUNT+1
                end
                if BANETO_RETAIL_MOUNT_CASTCOUNT and BANETO_RETAIL_MOUNT_CASTCOUNT >= 5 then
                    BANETO_STOPMOUNTBECAUSEUNSTUCK= GetTime()+16
                    BANETO_PrintState("Mountspam detected! Blacklisting mounting for 10 seconds!")
                end
            end
            return false
        elseif not UnitAffectingCombat("player") and BANETO_GetUnitSpeed("player") ~= 0  and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not IsMounted() and (class ~= 11 or BANETO_DEFINED_PROFILE_TYPE == "Battleground" or BANETO_SETTING_RETAIL_DRUID_USEMOUNT) then
            BANETO_StopMovement()
            return false
        end
        if class == 11 and BANETO_DEFINED_PROFILE_TYPE ~= "Battleground" and not BANETO_SETTING_RETAIL_DRUID_USEMOUNT then
            if IsMounted() then
                BANETO_Dismount()
            end
            local travel = 292629
            if BANETO_State ~= "FIGHTING" and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_HasBuff("player",travel)then
                if not BANETO_RETAIL_LB_MOUNTSUMMON or BANETO_RETAIL_LB_MOUNTSUMMON < GetTime() then
                    if UnitAffectingCombat("player") then
                        BANETO_IMPROVISED_TRAVELFORM = true
                    end
                    BANETO_CastSpell(travel)
                    BANETO_RETAIL_LB_MOUNTSUMMON = GetTime()+1
                    if not BANETO_RETAIL_MOUNT_CASTCOUNT then
                        BANETO_RETAIL_MOUNT_CASTCOUNT = 1
                    else
                        BANETO_RETAIL_MOUNT_CASTCOUNT = BANETO_RETAIL_MOUNT_CASTCOUNT+1
                    end
                    if BANETO_RETAIL_MOUNT_CASTCOUNT and BANETO_RETAIL_MOUNT_CASTCOUNT >= 4 then
                        BANETO_STOPMOUNTBECAUSEUNSTUCK= GetTime()+10
                        BANETO_PrintState("Shapeshift spam detected! Blacklisting shapeshift for 10 seconds!")
                    end
                end
                return false
            elseif BANETO_State ~= "FIGHTING" and BANETO_SETTING_MOUNT and BANETO_SETTING_MOUNT == true and not BANETO_HasBuff("player",travel) then
                return false
            end
        end
    end


	--[[ TRIGGER LUABOX JUMP UNSTUCK --]]
	if  Unlocker("LUA")  and lb then
		BANETO_LuaboxUnstucker()
	end
	if Unlocker("LUA") and (BANETO_GetUnitSpeed("player") <= 0 or BANETO_LUABOX_TARGETSTICK)  and lb then
		if BANETO_LUABOX_TARGETSTICK and BANETO_LUABOX_TARGETSTICK == true then
			BANETO_LUABOX_TARGETSTICK = nil
		end
		--[[ SET DESTINATION FOR MOUNT DISTANCE CHECK --]]
		if not BANETO_LUABOX_DESTINATION then
			BANETO_LUABOX_DESTINATION = {x,y,z}
		end
		--[[ EXECUTE LUA NAV --]]
		local xGood,yGood,zGood = x,y,z

		if xGood == nil or yGood == nil or zGood == nil then
			xGood,yGood,zGood = x,y,z
		end
		BANETO_PrintDev("meshToFunc " .. xGood.."-"..yGood.."-"..zGood)
		if BANETO_GetDistance3D(xGood,yGood,zGood,BANETO_LUABOX_DESTINATION[1],BANETO_LUABOX_DESTINATION[2],BANETO_LUABOX_DESTINATION[3]) < 2 then
			__LB__.Navigator.MoveTo(xGood,yGood,zGood,1,2,1,true)
		else
			BANETO_StopMovement()
			BANETO_LUABOX_DESTINATION = {xGood,yGood,zGood}
			__LB__.Navigator.MoveTo(xGood,yGood,zGood,1,2,1,true)
		end
	elseif Unlocker("LUA") and (BANETO_GetUnitSpeed("player") <= 0 or not waPath or BANETO_LUABOX_TARGETSTICK)  then

		local map,_ = BANETO_GetMapId()
		BANETO_LUABOX_TARGETSTICK = nil
		local xWmGood,yWmGood,zWmGood,distanceWmGood = x, y, z, 0
		BANETO_LUABOX_DESTINATION = {x, y, z}
		if xWmGood and not IsFlying() and not BANETO_IsFlyingAscendNeeded() and (not BANETO_FLYING_PROFILE and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()))  then
			BANETO_FlightLog("Generate ground path 2")
			local PlayerX, PlayerY, PlayerZ = BANETO_ObjectPosition("player")
			BANETO_LUABOX_DESTINATION = {xWmGood,yWmGood,zWmGood}
			if _internal.Software() == "nn" then
                waPath = BANETO_GeneratePath(PlayerX, PlayerY, PlayerZ,xWmGood,yWmGood,zWmGood)
                pathIndex = 1
			else
                local pathcreated = BANETO_GeneratePath(PlayerX, PlayerY, PlayerZ,xWmGood,yWmGood,zWmGood,"mainpath2")
                if pathcreated then
                    local pathSplitted = BANETO_SplitPath(pathcreated,1,6)
                    waPath, pathTypeBuffer = pathSplitted,_
                    waPathDistance = 0
                    pathIndex = BANETO_GetCenterIndexInPathBankai(pathSplitted,"player")
                    --BANETO_BlockSmoothTurn(2)
                    if pathIndex == 1 and waPath and #waPath >= 2 then
                        pathIndex = 2
                    end
                    if pathIndex then
                        BANETO_PrintBambo("New tinkr mainpath2s with index: "..pathIndex)
                    end
                end
			end
		end
	end
end
function _G.BANETO_GetPathIndex()
    return pathIndex
end

function _G.BANETO_FindBuffFoodInBags()
    if BANETO_REGEN_CACHE_BUFF_FOOD_EMPTY then
        return
    end
    local l = UnitLevel("player")
    for k = 1, #BANETO_ITEMS_BUFFFOOD do
        local idInTable = BANETO_ITEMS_BUFFFOOD[k][1]
        local requiredLevel = BANETO_ITEMS_BUFFFOOD[k][2]
        if not requiredLevel then requiredLevel = 1 end;
        if requiredLevel <= l then
            local amount = GetItemCount(idInTable)
            if amount and amount >= 1 then
                return idInTable
            end
        end
    end
    BANETO_REGEN_CACHE_BUFF_FOOD_EMPTY = true
end

function _G.BANETO_FindBuffFoodInBagsOld()
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            if BANETO_ITEMS_BUFFFOOD then
                for k = 1, #BANETO_ITEMS_BUFFFOOD do
                    local idInBag = GetContainerItemID(i, z)
                    local idInTable = BANETO_ITEMS_BUFFFOOD[k][1]
                    if idInBag == idInTable then
                        local requiredLevel = BANETO_ITEMS_BUFFFOOD[k][2]
                        if requiredLevel <= UnitLevel("player") then
                            return idInBag
                        end
                    end
                end
            end
        end
    end
end
function _G.BANETO_IsInParanoiaStuckMode()
    return BANETO_PARANOIA_TIMESTAMP and BANETO_PARANOIA_TIMESTAMP > GetTime()
end
function _G.BANETO_WmbUnstucking()
    if BANETO_EXECUTE_FLY_ASCEND  or IsFlying() then
        return false
    end
    if not BANETO_Wmb_LastPos_Delay or BANETO_Wmb_LastPos_Delay < GetTime() then
        BANETO_Wmb_LastPos_Delay = GetTime()+1.5
        BANETO_PrintDev("unstuckWmbTick")
        if not BANETO_Wmb_LastPos then
            BANETO_Wmb_LastPos = { }
            local x,y,z = BANETO_ObjectPosition("player")
            table.insert(BANETO_Wmb_LastPos,x)
            table.insert(BANETO_Wmb_LastPos,y)
            table.insert(BANETO_Wmb_LastPos,z)
        else
            local x,y,z = BANETO_ObjectPosition("player")
            local distance = GetDistanceBetweenPositions(x,y,z,BANETO_Wmb_LastPos[1],BANETO_Wmb_LastPos[2],BANETO_Wmb_LastPos[3])
            if distance and distance < 2 then
                if not BANETO_Wmb_StuckTick then
                    BANETO_Wmb_StuckTick = 0
                end
                BANETO_Wmb_StuckTick = BANETO_Wmb_StuckTick+1
            else
                BANETO_Wmb_LastPos = nil
                BANETO_Wmb_StuckTick = 0
                if BANETO_WMB_UNSTUCK_STRAFEBACK then
                    MoveBackwardStop()
                    BANETO_WMB_UNSTUCK_STRAFEBACK = nil
                end
            end
        end
    end
    if BANETO_Wmb_StuckTick and BANETO_Wmb_StuckTick >= 2 and (not BANETO_EMERGENCY_STUCK_HS_LASTUSE or BANETO_EMERGENCY_STUCK_HS_LASTUSE < GetTime()) then


        if (not BANETO_Wmb_JumpDelay or BANETO_Wmb_JumpDelay < GetTime()) and not UnitCastingInfo("player") and BANETO_Wmb_StuckTick < 5 and not UnitCastingInfo("player") and not IsFlying()  then
            BANETO_Wmb_JumpDelay = GetTime()+0.2
            if not BANETO_UNSTUCKJUMPDELAYER or BANETO_UNSTUCKJUMPDELAYER < GetTime() then
                BANETO_JumpOrAscendStart(5)
                BANETO_GroundPathDeleter()
                BANETO_UNSTUCKJUMPDELAYER = GetTime()+2
            end
        end
        if BANETO_Wmb_StuckTick >= 3 and IsMounted() and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) then
            BANETO_Dismount()
            BANETO_PrintState("Baneto seems to be stuck - dismounting and blocking mounting for some seconds.")
            ewtPath = nil
            BANETO_Wmb_StuckTick = 0
            if BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true then
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+30
            else
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+20
            end
        end

        local class,_,_ = UnitClass("player")
        local travel = 292629
        if BANETO_Wmb_StuckTick >= 3 and class == 11 and BANETO_HasBuff("player",travel) and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) then
            CancelShapeshift()
            BANETO_PrintState("Baneto seems to be stuck - cancel shapeshift and blocking shapeshift for some seconds.")
            BANETO_Wmb_StuckTick = 0
            ewtPath = nil
            if BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true then
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+30
            else
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+20
            end
        end

        if BANETO_TARGET  and BANETO_State ~= "FP-DISCOVER"  and  BANETO_Wmb_StuckTick >= 3 and (not BANETO_Wmb_StuckBlacklistDelay or BANETO_Wmb_StuckBlacklistDelay < GetTime()) then
            BANETO_PrintState("Baneto seems to be stuck - blacklisting mob guid. A")
            BANETO_Wmb_StuckBlacklistDelay = GetTime()+5
            BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
            BANETO_Wmb_StuckTick = 0
            BANETO_TARGET = nil
            ClearTarget()
            if BANETO_State == "GATHER" then
                local x,y,z = BANETO_ObjectPosition("player")
                BANETO_GATHER_TARGET_COORDS = { x,y,z }
            end
            ewtPath = nil
        end

        if BANETO_Wmb_StuckTick >= 5 then
            local playerCount;
            if BANETO_SETTING_SECURITY_PARANOIA and BANETO_SETTING_SECURITY_PARANOIA == true then
                playerCount = GetNumPlayersAroundUnit("player",60)
            end
            if BANETO_SETTING_SECURITY_PARANOIA and BANETO_SETTING_SECURITY_PARANOIA == true and playerCount >= 1 then
                local ran = math.random(45,75)
                BANETO_PARANOIA_TIMESTAMP = GetTime()+ran
                BANETO_DelayMeshPathing(ran)
                waPath = nil
                tryX = nil
                BANETO_Wmb_StuckTick = 0
            else
                if not BANETO_WMB_STUCKPADDLE and (not BANETO_WMB_STUCKPADDLE_DELAY or BANETO_WMB_STUCKPADDLE_DELAY < GetTime()) then
                    BANETO_WMB_STUCKPADDLE = true
                    BANETO_MC_COUNT_STUCKS = BANETO_MC_COUNT_STUCKS+1
                    BANETO_WMB_STUCKPADDLE_DELAY = GetTime()+60
                    if centerIndex and BANETO_GetDefinedCenters() then
                        centerIndex=centerIndex+1
                        if centerIndex > #BANETO_GetDefinedCenters() then
                            BANETO_PrintDev("[GRINDSTUCK] RESETTING CENTER INDEX CYCLE. NOW: " .. centerIndex)
                            centerIndex = 1
                        end
                    end
                end
            end
        end

        if BANETO_Wmb_StuckTick >= 7 and not UnitAffectingCombat("player") and BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true then
            StopEwtMovement()
            BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+16
            BANETO_DELAY_MESHPATHING = GetTime()+16
            BANETO_WMB_UNSTUCK_STRAFE = nil
            if BANETO_GetUnitSpeed("player") == 0 and not UnitCastingInfo("player") then
                if IsMounted() then
                    BANETO_Dismount()
                end
                BANETO_UseItem(6948)
                ewtPath = nil
                BANETO_EMERGENCY_STUCK_HS_LASTUSE = GetTime()+11
                BANETO_PrintState("Baneto seems to be stuck completely - using hs.")
            end
        end
        if BANETO_Wmb_StuckTick >= 15 then
            if BANETO_SETTING_PUSH_STUCK and BANETO_SETTING_PUSH_STUCK == true then
                BANETO_PushNotification("Stuck")
            end
            BANETO_Wmb_StuckTick = 0
            BANETO_WMB_STUCKPADDLE_DELAY = GetTime()
            BANETO_CallFullStuckMethod()
            BANETO_DiscordSendStuck()
            ARCH_X,ARCH_Y,ARCH_Z = nil,nil,nil
            BANETO_PrintError("Completely stuck. Are you on mesh? Use hearthstone to unstuck setting. Please report with screenshots / video. Try to go back where your char was able to move, does it work there?")
        end
    end
end

DRAGONRIDE_LOG = ""
function _G.BANETO_LogDragonride(logtext,forced)
    if _G.LOG_DRAGON and (BANETO_IsDragonRiding() or forced) then
        if IsFlying() then
            logtext = logtext .. " (airborn)"
        end
        DRAGONRIDE_LOG = DRAGONRIDE_LOG .. logtext.."\n"
    end
end
function _G.BANETO_LogDragonrideSave()
    if _G.LOG_DRAGON then
        local path = BANETO_GetBasePath() .. 'logfiles/skyridingV3.txt'
        if not FileExists(path) then
            WriteFile(path,DRAGONRIDE_LOG.."\n",false)
        else
            WriteFile(path,DRAGONRIDE_LOG.."\n",true)
        end
    end
end
C_Timer.After(1,function()
    BANETO_LogDragonride("NEW SESSION OF SKYRIDING LOG!",true)
end)



