BANETO_SCANNED_GRAVEYARDS = {}
function _G.BANETO_ScanGraveyards()
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    for i=1,#objects do
        local object = objects[i]
        local distance = GetDistanceBetweenObjects("player",object)
        local name = BANETO_ObjectName(object)
        if name and not BANETO_SCANNED_GRAVEYARDS[name] then
            if name == "Spirit Healer" or name == "Geistheiler" then
                if distance and 50 > distance and UnlockedTargetReaction(object) == 5 then
                    BANETO_SCANNED_GRAVEYARDS[name] = true
                    local x,y,z = BANETO_ObjectPosition(object)
                    local map = BANETO_GetMapId()
                    local fac,_ = UnitFactionGroup("player")
                    local tableDiscord = {
                      username = "Baneto",
                      avatar_url = "https://baneto-bot.com/assets/img/logo.png",
                      content = "{".. x .. ","..y..","..z..","..map..",'"..fac .. "'},",
                      embeds = {}
                    }

                    local jsonPayload;
                    if _internal.Software() == "nn" then
                        local JSON = Tinkr.Utils.JSON
                        jsonPayload = JSON.encode(tableDiscord)
                    elseif _internal.Software() == "tnk" then
                        jsonPayload = json.encode(tableDiscord)
                    end
                    local urltarget = ""                    local function callb(status)
                       if status and (status == 200 or status == 204) then

                       else

                       end
                    end
                    BANETO_HttpPost(urltarget,jsonPayload,callb)
                end
            end
        end
    end
end
