function _G.BANETO_GetClosestGraveyard()
	local continent = BANETO_GetMapId()
	local level = UnitLevel("player")
    local zone = BANETO_GetZoneId()
    local faction,_ = UnitFactionGroup("player")
	if Unlocker("LUA") and BANETO_GRAVEYARDS and #BANETO_GRAVEYARDS then
		local bestDistance = 99999999
		local bestMailX, bestMailY, bestMailZ = nil,nil,nil
		for i = 1, #BANETO_GRAVEYARDS do
			local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
			local mailX, mailY, mailZ,mailMapId,mailfaction = BANETO_GRAVEYARDS[i][1],BANETO_GRAVEYARDS[i][2],BANETO_GRAVEYARDS[i][3],BANETO_GRAVEYARDS[i][4],BANETO_GRAVEYARDS[i][5]
			local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,mailX, mailY, mailZ)
			if distance and distance < bestDistance and mailMapId == continent and mailfaction == faction  then
				bestMailX = mailX
				bestMailY = mailY
				bestMailZ = mailZ
				bestDistance = distance
			end
		end
		return bestMailX,bestMailY,bestMailZ
	end

end

function _G.BANETO_GetClosestMailbox()

    if BANETO_SETTING_MAILBOX_X and BANETO_SETTING_MAILBOX_Y and BANETO_SETTING_MAILBOX_Z and  BANETO_SETTING_MAILBOX_ID and BANETO_CheckHomeMailbox() then
        return BANETO_SETTING_MAILBOX_X, BANETO_SETTING_MAILBOX_Y, BANETO_SETTING_MAILBOX_Z
    end

	local faction,_ = UnitFactionGroup("player")
	local continent = BANETO_GetMapId()
	local level = UnitLevel("player")
    local zone = BANETO_GetZoneId()
    local continentName = BANETO_continentNames[continent]
    local foundVendor = false;
	if faction == "Horde" then
		if continent == 1 then
			BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE["Kalimdor"]
		elseif continent == 0 then
			BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE["Eastern Kingdoms"]
        elseif continent == 530 then
            if level > 40 then
                BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE["Outland"]
            else
                BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE["Eastern Kingdoms"]
            end
        elseif continent == 571 then
            BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE["Northrend"]
        elseif continentName and _G.BANETO_OBJECTS_MAILBOX_HORDE[continentName] then
            BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_HORDE[continentName]
		end
	elseif faction == "Alliance" then
		if continent == 1 then
			BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE["Kalimdor"]
		elseif continent == 0 then
			BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE["Eastern Kingdoms"]
        elseif continent == 530 then
            if level > 40 then
                BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE["Outland"]
            else
                BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE["Kalimdor"]
            end
        elseif continent == 571 then
            BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE["Northrend"]
        elseif continentName and _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[continentName] then
            BANETO_MAILBOX_TABLE = _G.BANETO_OBJECTS_MAILBOX_ALLIANCE[continentName]
		end
	end

	if Unlocker("LUA") and BANETO_MAILBOX_TABLE and #BANETO_MAILBOX_TABLE then
		local bestDistance = 99999999
		local bestMailX, bestMailY, bestMailZ = nil,nil,nil
		for i = 1, #BANETO_MAILBOX_TABLE do
			local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
			local mailX, mailY, mailZ = BANETO_MAILBOX_TABLE[i][1],BANETO_MAILBOX_TABLE[i][2],BANETO_MAILBOX_TABLE[i][3]
			local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,mailX, mailY, mailZ)
			local zoneForMail = BANETO_MAILBOX_TABLE[i][5]
			if distance and distance < bestDistance and zone and zoneForMail and zone == zoneForMail then
				bestMailX = mailX
				bestMailY = mailY
				bestMailZ = mailZ
				bestDistance = distance
				foundVendor = true
				--BANETO_PrintBambo("Found Mailbox in our zone.")
			end
		end
		if not foundVendor or foundVendor == false then
            for i = 1, #BANETO_MAILBOX_TABLE do
                local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
                local mailX, mailY, mailZ = BANETO_MAILBOX_TABLE[i][1],BANETO_MAILBOX_TABLE[i][2],BANETO_MAILBOX_TABLE[i][3]
                local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,mailX, mailY, mailZ)
                if distance and distance < bestDistance then
                    bestMailX = mailX
                    bestMailY = mailY
                    bestMailZ = mailZ
                    bestDistance = distance
                    --BANETO_PrintBambo("Found Mailbox in other zone.")
                end
            end
		end
		return bestMailX,bestMailY,bestMailZ
	end
end

