function _G.BANETO_GetClosestTaxiExit()
	if BANETO_FLIGHTMASTER_KNOWNTABLE2 then
        local bestDistance = 99999999
        local bestNpcX, bestNpcY, bestNpcZ = nil,nil,nil
        local bestNpcId = nil
        for i = 1, #BANETO_FLIGHTMASTER_KNOWNTABLE2 do
            local playerXYZ = BANETO_GetLuaBoxDestination()
            local npcX, npcY, npcZ = BANETO_FLIGHTMASTER_KNOWNTABLE2[i][1],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][2],BANETO_FLIGHTMASTER_KNOWNTABLE2[i][3]
            local npcId = BANETO_FLIGHTMASTER_KNOWNTABLE2[i][4]
            local distance = BANETO_GetDistance3D(playerXYZ[1], playerXYZ[2], playerXYZ[3],npcX, npcY, npcZ)
            if BANETO_IsFlightmasterOnMyContinent(npcId) and not IsUnitIdBlacklisted(npcId) then
                if distance and distance < bestDistance then
                    bestNpcX = npcX
                    bestNpcY = npcY
                    bestNpcZ = npcZ
                    bestNpcId = npcId
                    bestDistance = distance
                end
            end
        end
        return bestNpcX,bestNpcY,bestNpcZ,bestNpcId
	end
end

