function _G.BANETO_IsTaxiNeeded()
	if not BANETO_TAXI_DELAYER or BANETO_TAXI_DELAYER < GetTime() and (not BANETO_TAXI_DELAYER_TOTALBLOCK or BANETO_TAXI_DELAYER_TOTALBLOCK < GetTime())  then
		if BANETO_SETTING_TAXI == true and not BANETO_TAXI_NEEDED and not BANETO_STATEBLOCK_NOPATH_FPTAXI_BLACKLIST  and BANETO_State ~= "FP-TAXI"  and BANETO_State ~= "MOUNT"  and BANETO_State ~= "BUFF"  and BANETO_State ~= "QUEST-MASTER" and BANETO_State ~= "RBG"  and BANETO_State ~= "RBG-WAIT" and BANETO_State ~= "BG-MASTER"   and BANETO_State ~= "GHOST"  then
            local xP,yP,zP = BANETO_ObjectPosition("player")
            local destination = BANETO_GetLuaBoxDestination()
            if destination then
                --local pathPlayerToDestWalk = BANETO_GeneratePathBLABLABLA(xP,yP,zP,destination[1],destination[2],destination[3])
                local distancePlayerToDestWalk = BANETO_GetDistance3D(xP,yP,zP,destination[1],destination[2],destination[3])
                local xEntry,yEntry,zEntry,idEntry = BANETO_GetClosestTaxiEntry()
                if xEntry and yEntry and zEntry and idEntry then
                    local pathPlayerToTaxiEntry = BANETO_GeneratePath(xP,yP,zP,xEntry,yEntry,zEntry,"taxiPlayerToEntry")
                    if pathPlayerToTaxiEntry then
                        local distancePlayerToTaxiEntry = BANETO_GetLengthOfGroundPath(pathPlayerToTaxiEntry)
                        local xExit,yExit,zExit,idExit = BANETO_GetClosestTaxiExit()
                        local pathPlayerFromExitToDestWalk = BANETO_GeneratePath(destination[1],destination[2],destination[3],xExit,yExit,zExit,"taxiPlayerToEntry")
                        if pathPlayerFromExitToDestWalk then
                            local distancePlayerFromExitToDestWalk = BANETO_GetLengthOfGroundPath(pathPlayerFromExitToDestWalk)
                            if distancePlayerFromExitToDestWalk and distancePlayerToTaxiEntry and distancePlayerToTaxiEntry > 0 and distancePlayerToDestWalk and idExit ~= idEntry then
                                if distancePlayerToDestWalk > distancePlayerToTaxiEntry+distancePlayerFromExitToDestWalk then
                                    BANETO_TAXI_CHOSEN_NODENAME = BANETO_GetNodenameByFlightmasterId(idExit)
                                    if BANETO_TAXI_CHOSEN_NODENAME and idEntry and idExit then
                                        BANETO_TAXI_NEEDED = true
                                        if _internal.Software() == "tnk" then
                                            BANETO_PrintState("[TAXI] for tinkr")
                                        else
                                            BANETO_PrintState("[TAXI] for nn")
                                        end
                                        BANETO_PrintState("[TAXI] Determined Taxi Location: " .. BANETO_TAXI_CHOSEN_NODENAME .. " in State: " .. BANETO_State)
                                        BANETO_PrintState("[TAXI] Approaching nearest Flightmaster: " .. BANETO_GetNodenameByFlightmasterId(idEntry))
                                        return true
                                    end
                                end
                            end
                        end
                    end
                end
            end
		end
	end
end

