function _G.BANETO_IsMountNeeded()
	if BANETO_ForceMount and BANETO_ForceMount == true then
		return true
	end
    if BANETO_FLYING_PROFILE and BANETO_FLYING_PROFILE == true and (BANETO_IsFlyableArea() or BANETO_IsDragonRiding()) then
        return true
    end
	if BANETO_SETTING_MOUNT == true then
		if not IsMounted() and not IsIndoors() then
			if Unlocker("LUA") then
				local xP,yP,zP = BANETO_ObjectPosition("player")
				local destination = BANETO_GetLuaBoxDestination()
				if destination then
					local distance = BANETO_GetDistance3D(xP,yP,zP,destination[1],destination[2],destination[3])
				--[[ 	print("DISTANCE: " .. distance) --]]
					if distance > 70 then
						local travel = 783
						local warlockMount = 5784
						local warlockMountBetter = 23161
						local ghostwolf = 2645
						local palamount = 13819
						local aspectOfCheetah = 5118
						if not BANETO_HasBuff("player", travel) and not BANETO_HasBuff("player", warlockMountBetter) and not BANETO_HasBuff("player", palamount) and not BANETO_HasBuff("player", warlockMount) and not BANETO_HasBuff("player", ghostwolf)  and not BANETO_HasBuff("player", aspectOfCheetah) then
							return true
						end
					end
				end
			elseif Unlocker("EWT") then
				local xP,yP,zP =  ObjectPosition("player")
				if totalDist then
					if totalDist > 70 then
						local travel = 783
						local warlockMount = 5784
						local warlockMountBetter = 23161
						local ghostwolf = 2645
						local palamount = 13819
						local aspectOfCheetah = 5118
						if  not BANETO_HasBuff("player", travel) and not BANETO_HasBuff("player", warlockMountBetter) and not BANETO_HasBuff("player", palamount) and not BANETO_HasBuff("player", warlockMount) and not BANETO_HasBuff("player", ghostwolf) and not BANETO_HasBuff("player", aspectOfCheetah)  then
							return true
						end
					end
				end
			end
		end
	end
end

