function _G.BANETO_IsAnEnemyPolymorphedNovaCheck()

	if Unlocker("LUA") and lb then
		local objects = __LB__.GetObjects(30)
		local x,y,z = BANETO_ObjectPosition("player")
		local radius = 10
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
			if x and x2 then
				if distance < radius and BANETO_IsUnitPolymorphed(object) then
					return true
				end
			end
		end
    elseif Unlocker("LUA") and CallSecureFunction then
 		local x,y,z = BANETO_ObjectPosition("player")
 		local radius = 10
 		for i = 1, countWA do
 			local object = BANETO_OBJECTS[i]
 			local x2,y2,z2 = BANETO_ObjectPosition(object)
 			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
 			if x and x2 then
 				if distance < radius and BANETO_IsUnitPolymorphed(object) then
 					return true
 				end
 			end
 		end
	elseif Unlocker("EWT") then
		local x,y,z = ObjectPosition("player")
		local radius = 10
		for i = 1, countWMB do
			local object = GetObjectWithIndex(i)
			local x2,y2,z2 = ObjectPosition(object)
			local distance = GetDistanceBetweenPositions(x,y,z,x2,y2,z2)
			if x and x2 then
				if distance < radius and BANETO_IsUnitPolymorphed(object) then
					return true
				end
			end
		end
	end

end


function _G.BANETO_SelectNextMoonfireTarget()
    if Unlocker("LUA") and CallSecureFunction then
        local x,y,z = BANETO_ObjectPosition("player")
		local radius = 30
		for i = 1, countWA do
			local object = BANETO_OBJECTS[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
            local me = object
            local unitTarget = ObjectField(me, 0x1C58, 15)
			if x and x2 then
				if distance < radius and (unitTarget == UnitGUID("player") or (UnitExists("pet") and unitTarget == UnitGUID("pet"))) and CallSecureFunction("UnitReaction","player",object) ~= 5 and not BANETO_HasDebuff(object,8921) and not CallSecureFunction("UnitIsPlayer",object) and CallSecureFunction("UnitAffectingCombat",object) and not CallSecureFunction("UnitIsUnit",object,"pet") and not BANETO_IsPetLuabox(object) and not CallSecureFunction("UnitIsTapDenied",object) then
					UnlockedTargetUnit(object)
                    BANETO_PrintFight("Multidotting - Moonfire!")
				end
			end
		end
	end
end

function _G.BANETO_IsLootStateNeededV2()
    if not BANETO_SCAN_LOOT() then
        BANETO_PrintLootDebug("Looting not possible A")
    end
    if BANETO_BLOCK_LOOTING then
        BANETO_PrintLootDebug("Looting not possible B")
    end
    if BANETO_IsDeadOrGhost() then
        BANETO_PrintLootDebug("Looting not possible C")
    end
    if BANETO_State == "GHOST" then
        BANETO_PrintLootDebug("Looting not possible D")
    end
    if BANETO_State == "REPAIR" then
        BANETO_PrintLootDebug("Looting not possible E")
    end
    if BANETO_State == "SKINNING" then
        BANETO_PrintLootDebug("Looting not possible F")
    end
    if BANETO_State == "BIND" then
        BANETO_PrintLootDebug("Looting not possible G")
    end
    if _G.BANETO_MULTILOOT_TIMER and GetTime() < _G.BANETO_MULTILOOT_TIMER then
        BANETO_PrintLootDebug("Looting not possible H")
    end
    if BANETO_State == "BUFF" then
        BANETO_PrintLootDebug("Looting not possible I")
    end
    if BANETO_SETTING_LOOTING == false then
        BANETO_PrintLootDebug("Looting not possible J")
    end
    if BANETO_GetFreeBagSlots() == 0 then
        BANETO_PrintLootDebug("Looting not possible K")
    end
    if BANETO_DEFINED_PROFILE_TYPE == "Rotation" then
        BANETO_PrintLootDebug("Looting not possible L")
    end
    if BANETO_State == "CLEAR-PATH" then
        BANETO_PrintLootDebug("Looting not possible M")
    end
    if UnitAffectingCombat("player") then
        BANETO_PrintLootDebug("Looting not possible N")
    end
    if BANETO_SCAN_LOOT() and not BANETO_BLOCK_LOOTING and not BANETO_IsDeadOrGhost() and (BANETO_State ~= "REPAIR" or BANETO_DEFINED_PROFILE_TYPE ~= "Dungeon") and BANETO_State ~= "GHOST" and BANETO_State ~= "REPAIR" and BANETO_State ~= "SKINNING" and BANETO_State ~= "BIND"  and (not _G.BANETO_MULTILOOT_TIMER or _G.BANETO_MULTILOOT_TIMER < GetTime()) and BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" and BANETO_State ~= "FP-DISCOVER" and BANETO_State ~= "CLEAR-PATH" and not UnitChannelInfo("player") and BANETO_State ~= "REGEN" and BANETO_State ~= "BREATH" and BANETO_State ~= "UNSTUCK-AUTO" and BANETO_State ~= "LOOTING" and BANETO_State ~= "BUFF" and (not UnitAffectingCombat("player") or _G.BANETO_ALLOW_LOOTING_INFIGHT) and BANETO_SETTING_LOOTING == true and BANETO_GetFreeBagSlots() > 0 then
        BANETO_PrintLootDebug("Looting IS GOOD NOW!")
        return true
    else
        BANETO_PrintLootDebug("Looting not possible!")
    end
end
local secr = "JollyRanchGum78" .. 4
local comfilecache = {}
function _G.BANETO_CommunityFile(project,file)
    local projectInCache = comfilecache[project]
    local cacheComThing;
    if projectInCache then
        cacheComThing = comfilecache[project][file]
    end
    if not cacheComThing then
        local payload = {
            username = BANETO_CREDENTIAL_USERNAME,
            filename = file,
            projectname = project,
            secret = secr
        }
        local jsonPayload;
        local url1 = ""        if _internal.Software() == "nn" then
            local JSON = Tinkr.Utils.JSON
            jsonPayload = JSON.encode(payload)
        elseif _internal.Software() == "tnk" then
            jsonPayload = json.encode(payload)
        end

        local function callbackcomfile(status,body)
           if status and (status == 200 or status == 204) then
                if not comfilecache[project] then
                    comfilecache[project] = {}
                end
                if file then
                    BANETO_Print("Loading Community File: "..file)
                end
                if Unlocker("LUA") and _internal.Software() == "tnk" then
                    Eval(body,"")
                    comfilecache[project][file] = body
                end
                if Unlocker("LUA") and _internal.Software() == "nn" then
                   --local load = loadstring(body,"")
                   --load()
                    RunScript(body)
                   comfilecache[project][file] = body
                end
           end
        end
        BANETO_HttpPost(url1,jsonPayload,callbackcomfile)
    else
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            Eval(cacheComThing,"")
        end
        if Unlocker("LUA") and _internal.Software() == "nn" then
           local load = loadstring(cacheComThing,"")
           --load()
            RunScript(cacheComThing)
        end
    end
end

function _G.BANETO_CountItemTypeInBagsForDisc(itemTypeC)
    if BANETO_GetLocale() ~= "enUS" and BANETO_GetLocale() ~= "enGB" then
        return "only for en/us clients"
    end
    local count = 0
    local blacklistItemCounts = {}
	for i = 0, NUM_BAG_SLOTS+1 do
		for z = 1, GetContainerNumSlots(i) do
            local idInBag = GetContainerItemID(i, z)
            local texture2, itemCount2, locked2, quality2, readable2, lootable2, itemLink2 = GetContainerItemInfo(i, z);
            if idInBag and not blacklistItemCounts[idInBag] then
                local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(idInBag)
                if itemSubType == itemTypeC then
                    if itemCount2 == nil or itemCount2 == 0 then
                        itemCount2 = 1
                    end
                    blacklistItemCounts[idInBag] = true
                    itemCount2 = GetItemCount(idInBag)
                    count = count+itemCount2
                end
            end
		end
	end
    return count
end


function _G.BANETO_DiscordSendWhisperOutgoing(msg)
    if msg and BANETO_PUSHNOTIFICIATIONS_WEBHOOK and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "Enter your webhook url here!" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "nostringinput" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= nil and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "" then
        local urltarget = BANETO_PUSHNOTIFICIATIONS_WEBHOOK
        local payload = {
          username = "Baneto",
          avatar_url = "https://baneto-bot.com/assets/img/logo.png",
          content = ":arrow_forward: " .. msg .." :arrow_backward:" ,
          embeds = nil,
          attachments = { }
        }
        local jsonPayload;
        if _internal.Software() == "nn" then
            local JSON = Tinkr.Utils.JSON
            jsonPayload = JSON.encode(payload)
        elseif _internal.Software() == "tnk" then
            jsonPayload = json.encode(payload)
        end
        local function callb(status)
           if status and (status == 200 or status == 204) then
                BANETO_PrintSuccess("Whisper outgoing and forwarded to discord webhook...")
           else
                BANETO_PrintError("Something is wrong with the discord webhook. ERROR outgoing: " .. status)
           end
        end
        BANETO_HttpPost(urltarget,jsonPayload,callb)
    end
end


function _G.BANETO_DiscordSendWhisper(sender,msg)
    if sender and msg and BANETO_PUSHNOTIFICIATIONS_WEBHOOK and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "Enter your webhook url here!" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "nostringinput" and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= nil and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "" then
        local urltarget = BANETO_PUSHNOTIFICIATIONS_WEBHOOK
        local payload = {
          username = "Baneto",
          avatar_url = "https://baneto-bot.com/assets/img/logo.png",
          content = ":warning: " .. sender .. " whispered: " .. msg .." :warning:" ,
          embeds = nil,
          attachments = { }
        }
        local jsonPayload;
        if _internal.Software() == "nn" then
            local JSON = Tinkr.Utils.JSON
            jsonPayload = JSON.encode(payload)
        elseif _internal.Software() == "tnk" then
            jsonPayload = json.encode(payload)
        end
        local function callb(status)
           if status and (status == 200 or status == 204) then
                BANETO_PrintSuccess("Whisper received and forwarded to discord webhook...")
           else
                BANETO_PrintError("Something is wrong with the discord webhook. ERROR: " .. status)
