    end
end
function _G.BANETO_GetXpPercent()
    return math.floor((UnitXP("player")/UnitXPMax("player"))*100)
end
function _G.BANETO_DiscordSendStatus()
    local profilenameDiscord = BANETO_GetProfileName()
    if not profilenameDiscord then
        profilenameDiscord = "No profile"
    end
    local herbs = BANETO_CountItemTypeInBagsForDisc("Herb")
    local leather = BANETO_CountItemTypeInBagsForDisc("Leather")
    local ores = BANETO_CountItemTypeInBagsForDisc("Metal & Stone")
    local goldDiscord = math.floor(GetMoney()/10000)
    local playersAroundDisc = CountPlayersAroundMe(200)
    if playersAroundDisc == nil then
        playersAroundDisc = 0
    end
    local state = BANETO_GetState()
    if _G.REAPER_ISRUNNING and _G.REAPER_ISRUNNING == true then
        profilenameDiscord = "Dungeonreaper"
        state = "REAPER"
    end
    local tableDiscord = {
      username = "Baneto",
      avatar_url = "https://baneto-bot.com/assets/img/logo.png",
      content = "",
      embeds = { {
        author = {
          name = ""
        },
        title = UnitName("player"),
        description = state,
        color = 15258703,
        fields = { {
          name = "Profile :scroll:",
          value = profilenameDiscord
        }, {
          name = "Zone :map:",
          value = GetZoneText()
        }, {
          name = "Level :star:",
          value = UnitLevel("player")
        }, {
          name = "XP per Hour :checkered_flag:",
          value = BANETO_STAT_XPPERH
        }, {
          name = "XP % :checkered_flag:",
          value = BANETO_GetXpPercent() .. "%"
        }, {
          name = "Gold :coin:",
          value = goldDiscord
        }, {
          name = "Rawgold per Hour :coin:",
          value = BANETO_GetRawgoldPerHour() or 0
        }, {
          name = "Deaths :skull:",
          value = BANETO_COUNT_DEATH
        }, {
          name = "Free Bagslots :handbag:",
          value = BANETO_GetFreeBagSlots()
        }, {
          name = "Herbs :herb:",
          value = herbs
        }, {
          name = "Ores :rock:",
          value = ores
        }, {
          name = "Leather :ox:",
          value = leather
        }, {
          name = "Session Time: :clock1:",
          value = math.floor(BANETO_GetSessionTime()/60) .. " minutes"
        }, {
          name = "Players near you: :wrestling:",
          value = playersAroundDisc
        } },
        thumbnail = {
          url = ""        },
        footer = {
          text = "Baneto-bot.com",
          icon_url = ""        }
      } }
    }

    local jsonPayload;
    if _internal.Software() == "nn" then
        local JSON = Tinkr.Utils.JSON
        jsonPayload = JSON.encode(tableDiscord)
    elseif _internal.Software() == "tnk" then
        jsonPayload = json.encode(tableDiscord)
    end
    local urltarget = BANETO_PUSHNOTIFICIATIONS_WEBHOOK
    local function callb(status)
       if status and (status == 200 or status == 204) then
            BANETO_PrintSuccess("Sending info to discord webhook...")
       else
            BANETO_PrintError("Something is wrong with the discord webhook. ERROR: " .. status)
       end
    end
    BANETO_HttpPost(urltarget,jsonPayload,callb)

end

