local startTime, endTime, swingDuration
local isSwinging = false
function _G.BANETO_SwingTimer()
    local mainSwinger,offSwinger = UnitAttackSpeed("player")
    if swingDuration then
        return mainSwinger-swingDuration
    else
        return mainSwinger
    end
end

local function OnSwing()
    startTime = GetTime()
    isSwinging = true
end
local function OnUpdateSwing(self, elapsed)
    if isSwinging then
        endTime = GetTime()
        swingDuration = endTime - startTime
    end
end
local function OnEventSwing(self, event, ...)
    if event == "COMBAT_LOG_EVENT_UNFILTERED" then
        local timestamp, subEvent,_ , sourceGUID = CombatLogGetCurrentEventInfo()
        if subEvent == "SWING_DAMAGE" and sourceGUID == UnitGUID("player") then
            OnSwing()
        end
    elseif event == "PLAYER_REGEN_ENABLED" then
        isSwinging = false
    end
end
local swingFrame = CreateFrame("Frame")
swingFrame:SetScript("OnEvent", OnEventSwing)
swingFrame:SetScript("OnUpdate", OnUpdateSwing)
swingFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED")
swingFrame:RegisterEvent("PLAYER_REGEN_ENABLED")

