function _G.BANETO_HasDeBuffWithTimeLeft(unit, spellid)
    for i = 1, 40 do
        local name, icon, count, dispelType, duration, expirationTime, source, isStealable, nameplateShowPersonal,
        spellId, canApplyAura, isBossDebuff, castByPlayer, nameplateShowAll, timeMod = UnitDebuffWrapper(unit, i)
