--BANETO_TakeGuildbankItem(200036)
function _G.BANETO_TakeGuildbankItem(itemIdToGrab)
    local numSlots = GetNumGuildBankTabs()
    for tab = 1, numSlots do
        for slot = 1, 100 do
            local itemLinkTester = GetGuildBankItemLink(tab, slot)
            if itemLinkTester then

                local id = BANETO_GetItemIDFromLink(itemLinkTester)
                if id == 200036 then
                    BANETO_PrintBambo("Test A: "..itemLinkTester)
                    BANETO_PrintBambo("Test B: "..id)
                end
                if id == itemIdToGrab then
                    AutoStoreGuildBankItem(tab, slot)
                    return
                end

            end
        end
    end
end
