function _G.BANETO_BankaiPickupGem()
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local id = GetContainerItemID(i, z)
            if id == 192978 then
                if _internal.Software() == "tnk" then
                    Eval("PickupContainerItem(".. i .. "," .. z .. ")","smoth")
                end
                if _internal.Software() == "nn" then
                    Unlock("pcall", C_Container.PickupContainerItem, i, z)
                end
                return true
            end
        end
    end
end

function _G.BANETO_BankaiSocketing(itemid)
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            local id = GetContainerItemID(i, z)
            if id then
                BANETO_PrintBambo("CHECK: "..id)

            end
            if id and id == itemid then
                C_Container.SocketContainerItem(i, z)
                C_Timer.After(1,BANETO_BankaiPickupGem)
                C_Timer.After(2,function()
                    ClickSocketButton(1)
                end)
                C_Timer.After(3,function()
                    AcceptSockets()
                end)
                return
            end
        end
    end
end

function _G.BANETO_BankaiEnchant()
    local enchants = {
        [173131] = 200044,
        [173134] = 200044,
        [173215] = 199994,
        [172251] = 199976,
        [172257] = 199984
    }
    if not _G.enchantedTableBankai then
        _G.enchantedTableBankai = {}
    end
    if not BANKAI_ENCHANT_DELAY or BANKAI_ENCHANT_DELAY < GetTime() then
        for equipItem,enchantItem in pairs(enchants) do
            if not _G.enchantedTableBankai[equipItem] then
                BANKAI_ENCHANT_DELAY = GetTime()+10
                BANETO_PrintBambo("Enchanting " .. equipItem .. " with " .. enchantItem .. " now")
                BANETO_USEITEM_DELAYER = nil
                BANETO_UseItem(enchantItem)
                _G.enchantedTableBankai[equipItem] = true
                C_Timer.After(2,function()
                    BANETO_UseItem(equipItem)
                end)
                return
            end
        end
    end
end

