function _G.BANETO_HasBuffWithTimeLeft(unit, spellid)
    for i = 1, 40 do
        local name, icon, count, dispelType, duration, expirationTime, source, isStealable, nameplateShowPersonal,
        spellId, canApplyAura, isBossDebuff, castByPlayer, nameplateShowAll, timeMod = UnitBuffWrapper(unit, i)
        if spellId and spellId == spellid and expirationTime then
            return expirationTime - GetTime()
        end
    end
    return nil
end

function _G.BANETO_GetUnitLostHealthAbsolut(unit)
    local currentHealth = UnitHealth(unit)
    local maxHealth = UnitHealthMax(unit)
    return maxHealth - currentHealth
end

function _G.BANETO_GetUnitLostHealthPercent(unit)
    local currentHealth = UnitHealth(unit)
    local maxHealth = UnitHealthMax(unit)
    return (1 - (currentHealth / maxHealth)) * 100
end
_G.BANETO_SETTING_SELECT_ACTIVE_ENEMY_RANGE = 70
function _G.BANETO_SelectActiveEnemyAroundPlayer(radius)

    if BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
        if Unlocker("LUA") and not UnitExists("target")  then
            BANETO_RetargetLowestHealthEnemyInBg()
        end
        return false
    end
    BANETO_PrintBambo("SelectNewTarget!!")
	if Unlocker("LUA") and not UnitExists("target") then
        local objects;
        if BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
            objects = BANETO_GetObjctsTkr()
        else
            objects = BANETO_OBJTS_TKR_ONLYUNITS
        end
		local x,y,z = BANETO_ObjectPosition("player")
		local counter = 0
		t = {}
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
			if x and x2 and (_internal.Software() == "tnk" or ObjectExists(object)) and BANETO_UnitHealth(object) > 0 and  UnitGUID(object) then
                local threat = BANETO_UnitThreatSituation("player",object)
                local threatPet;
                if UnitExists("pet") then
                    threatPet = BANETO_UnitThreatSituation("pet",object)
                end
                if distance < radius and UnlockedTargetCreatureType(object) ~= "Critter" and UnlockedTargetCreatureType(object) ~= "Wild Pet" and BANETO_IsPetLuabox(object) == false and not UnitIsUnit(object,"player") and not UnitIsUnit(object,"pet") and (not UnitIsPlayer(object) or BANETO_DEFINED_PROFILE_TYPE == "Battleground") and not UnitIsTapDenied(object) and (not UnitIsTrivial(object)  or BANETO_SETTING_IGNOREGRAYMOBS == false) and UnlockedTargetCreatureType(object) ~= "Totem" and (threat or BANETO_UnitTarget(object) == Object("player") or (UnitExists("pet") and BANETO_UnitTarget(object) == Object("pet")) or (UnitExists("party1") and BANETO_UnitTarget(object) == Object("party1")) or (UnitExists("party2") and BANETO_UnitTarget(object) == Object("party2")) or (UnitExists("party3") and BANETO_UnitTarget(object) == Object("party3")) or (UnitExists("party4") and BANETO_UnitTarget(object) == Object("party4"))) then
                    if UnitCanAttack("player",object) then
                        table.insert(t, { object, distance })
                    end
				end
				--[[ TOTEM TARGET --]]
				if distance < radius and _G.BANETO_SETTING_ATTACKTOTEMS and _G.BANETO_SETTING_ATTACKTOTEMS == true and UnlockedTargetCreatureType(object) ~= "Critter" and not UnitIsPlayer(object) and UnlockedTargetCreatureType(object) ~= "Wild Pet" and not BANETO_BLOCK_TOTEMSELECTION_AFTER_FIGHT and (UnlockedTargetCreatureType(object) == "Totem" or BANETO_ObjectId(object) == 3844 or BANETO_ObjectId(object) == 2667)  and (UnlockedTargetReaction(object) == 2 or UnlockedTargetReaction(object) == 4) and BANETO_DEFINED_PROFILE_TYPE ~= "Battleground" then
					if UnitCanAttack("player",object) then
                        table.insert(t, { object, distance })
					end
				end
			end
		end
        if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
        if t[1] then
            local target = t[1][1]
            UnlockedTargetUnit(target)
            BANETO_PrintBambo("SelectNewTarget")
        end
	end
end

