function _G.GetNumEnemiesAroundUnit(unit,radius)
    local counter = 0
	if Unlocker("LUA")  then
		local objects = BANETO_OBJTS_TKR_ONLYUNITS
		local x,y,z = BANETO_ObjectPosition(unit)
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
			if x and x2 then
			    local id = BANETO_ObjectId(object)
			    local isDummy = false;
			    if DummyUnits and DummyUnits[id] then
			        isDummy = true
			    end
				if distance and distance < radius and (UnlockedUnitAffectingCombat(object) or isDummy) and UnitReaction("player",object) ~= 5 and not BANETO_IsPetLuabox(object)  then
                    local threat = BANETO_UnitThreatSituation("player",object)
                    if threat or isDummy then
                        counter = counter +1
                    end
				end
			end
		end
	end
	return counter
end

function _G.GetNumElitesAroundUnit(unit,radius)
	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYUNITS
		local x,y,z = BANETO_ObjectPosition(unit)
		local counter = 0
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
			if x and x2 and UnlockedTargetHealth(object) > 1 then
				if distance < radius and UnlockedTargetReaction(object) ~= 5 and (UnlockedTargetClassification(object) == "elite"  or  UnlockedTargetClassification(object) == "rareelite" or  UnlockedTargetClassification(object) == "rare") then
					counter = counter +1
				end
				if i == #objects then
					return counter
				end
			end
		end
	end
end


function _G.BANETO_HasTotemActive(idTotem)
    if not idTotem then
        if Unlocker("LUA")  then
            local objects = BANETO_OBJTS_TKR_ONLYUNITS
            local x,y,z = BANETO_ObjectPosition("player")
            local counter = 0
            for i = 1, #objects do
                local object = objects[i]
                local x2,y2,z2 = BANETO_ObjectPosition(object)
                local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                if distance < 30 and UnlockedTargetCreatureType(object) == "Totem" then
                    return true
                end
            end
        end
    else
        if Unlocker("LUA")  then
            local objects = BANETO_OBJTS_TKR_ONLYUNITS
            local x,y,z = BANETO_ObjectPosition("player")
            local counter = 0
            for i = 1, #objects do
                local object = objects[i]
                local x2,y2,z2 = BANETO_ObjectPosition(object)
                local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                local objId = BANETO_ObjectId(object)
                if distance < 30 and UnlockedTargetCreatureType(object) == "Totem" and objId == idTotem then
                    return true
                end
            end
        end
    end
end

