function _G.GetNumHostileEnemiesAroundVectorNotInfight(x,y,z,radius)
	if Unlocker("LUA")  then
		local objects = BANETO_OBJTS_TKR_ONLYUNITS
		local counter = 0
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			if x and x2 and object then
				local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
				if distance and distance < radius and UnitCanAttack("player",object)  and UnlockedTargetHealth(object) and UnlockedTargetHealth(object) > 0 and UnlockedTargetReaction(object) and UnlockedTargetReaction(object) < 4  and not UnitIsPlayer(object) and not UnitAffectingCombat(object) then
					--[[ passive mobs tagged as hostile? --]]
                    local creatureType = UnlockedTargetCreatureType(object)
					if creatureType and creatureType ~= "Not specified"  and BANETO_ObjectId(object) and BANETO_ObjectId(object) ~= 6 and BANETO_ObjectId(object) ~= 257 and BANETO_ObjectId(object) ~= 80 then
						if BANETO_TARGET  then
							if BANETO_TARGET ~= UnitGUID(object) and BANETO_IsUnitInLos(object) and not BANETO_IsGuidContainedInGuidBlacklist(UnitGUID(object)) and not UnitIsTapDenied(object) and UnlockedTargetClassification(object) ~= "elite"  and  UnlockedTargetClassification(object) ~= "rareelite"  and UnlockedTargetCreatureType ~= "Totem" and not BANETO_IsPetLuabox(object) and UnlockedUnitIsTrivial(object) == false and UnitLevel("player") >= UnitLevel(object)-2  and not IsUnitInBlacklistAreaClearPath(object)  then
								counter = counter + 1
								goodObject = object
							end
						else
							if  UnlockedTargetClassification(object) ~= "elite" and  UnlockedTargetClassification(object) ~= "rareelite" and BANETO_IsUnitInLos(object) and not BANETO_IsGuidContainedInGuidBlacklist(UnitGUID(object)) and not UnitIsTapDenied(object) and not BANETO_IsPetLuabox(object) and UnlockedTargetCreatureType ~= "Totem" and UnlockedUnitIsTrivial(object) == false and UnitLevel("player") >= UnitLevel(object)-2 and not IsUnitInBlacklistAreaClearPath(object)  then
								counter = counter + 1
								goodObject = object
							end
						end
					end
				end
				if i == #objects then
					return counter,goodObject
				end
			else
				BANETO_TARGET = nil
			end
		end
	end
    return 0
end

function _G.BANETO_FindNextAssistPosition()
	local faction,_ = UnitFactionGroup("player")
	if faction == "Horde" then
		BANETO_BGASSIST_EXCLUDEAREAS_SPAWN = {868.71881103516,-493.58364868164,96.574180603027} --[[ MISSING HORDE DATA --]]
	elseif faction == "Alliance" then
		BANETO_BGASSIST_EXCLUDEAREAS_SPAWN = {868.71881103516,-493.58364868164,96.574180603027}
	end

	if Unlocker("LUA") then
		local objects = __LB__.GetObjects(500)
		local x,y,z = BANETO_ObjectPosition("player")
		local counter = 0
		local xTotal = 0
		local yTotal = 0
		local zTotal = 0
		for i = 1, #objects do
			local object = objects[i]
			local x2,y2,z2 = BANETO_ObjectPosition(object)
			local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
			local excludeDistance = BANETO_GetDistance3D(BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[1],BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[2],BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[3],x2,y2,z2)
			if x and x2 then
				if distance < 500 and (not excludeDistance or excludeDistance > 40) and UnlockedTargetHealth(object) > 0 and UnlockedTargetReaction(object) == 5 and __LB__.UnitTagHandler(UnitIsPlayer,object)   then
					xTotal = xTotal + x2
					yTotal = yTotal + y2
					zTotal = zTotal + z2
					counter = counter + 1
				end
				if i == #objects then
					local xAssist, yAssist, zAssist = xTotal/counter, yTotal/counter, zTotal/counter
					local finalX, finalY, finalZ = __LB__.NavMgr_GetClosestPointOnMesh(xAssist, yAssist, zAssist)
					return finalX, finalY, finalZ
				end
			end
		end
	elseif Unlocker("EWT") then
		local x,y,z = ObjectPosition("player")
		local counter = 0
		for i = 1, countWMB do
			local object = GetObjectWithIndex(i)
			local x2,y2,z2 = ObjectPosition(object)
			local distance = GetDistanceBetweenPositions(x,y,z,x2,y2,z2)
			local excludeDistance = GetDistanceBetweenPositions(BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[1],BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[2],BANETO_BGASSIST_EXCLUDEAREAS_SPAWN[3],x2,y2,z2)
			if x and x2 and object then
				if distance < 500 and excludeDistance > 50 and BANETO_UnitHealth(object) > 0 and UnitReaction("player",object) and UnitReaction("player",object) == 5 and UnitIsPlayer(object)  then
					counter = counter +1
				end
				if i == countWMB then
					return counter
				end
			end
		end
	end


end

