			if x and x2 and object then
				local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
				if distance < radius  and not UnitIsDeadOrGhost(object)  and UnlockedTargetHealth(object) < 80 and BANETO_IsUnitOnMesh(object) and UnlockedTargetReaction(object) == 5 and UnitIsPlayer(object) and not UnitIsUnit(object,"player")  then
                    return object
