function _G.BANETO_GetWorstEnemyInBg()
    if BANETO_SETTING_BG_MODE_1 and BANETO_SETTING_BG_MODE_1 == true then
        return false
    end
    if BANETO_SETTING_BG_MODE_2 and BANETO_SETTING_BG_MODE_2 == true then
        return BANETO_GetPossibleHealTargetInBg()
    end
    worstEnemyTable = {}
	if Unlocker("LUA")  then
		local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
		local counter = 0
		local radius = 55
		for i = 1, #objects do
			local object = objects[i]
			if object and (_internal.Software() == "tnk" or ObjectExists(object)) then
				if UnlockedTargetHealth(object) > 6 and not worstEnemy and BANETO_IsUnitOnMesh(object) and UnlockedTargetReaction(object) ~= 5 and UnitIsPlayer(object) and not UnitIsUnit(object,"player")  then
                    local x2,y2,z2 = BANETO_ObjectPosition(object)
                    local x,y,z = BANETO_ObjectPosition("player")
                    local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
                    if distance and distance < radius then
                        table.insert(worstEnemyTable, { object, distance })
                    end
                end
			end
		end
	end

	if #worstEnemyTable > 1 then table.sort(worstEnemyTable, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if worstEnemyTable[1] then
		--[[ ewtPath = nil --BUGGY?? ewt pathing stop? --]]
		return worstEnemyTable[1][1]
	end
end

