function _G.BANETO_RetargetLowestHealthEnemyInBg()
    if Unlocker("LUA") then
        local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
        local x,y,z = BANETO_ObjectPosition("player")
        local radius = 20
        local bestHealth = 100000
        local bestMob = nil
        for i = 1, #objects do
            local object = objects[i]
            local x2,y2,z2 = BANETO_ObjectPosition(object)
            local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
            if x and x2 then
                if distance < radius and (UnlockedTargetReaction(object) == 4 or UnlockedTargetReaction(object) == 2) and UnlockedUnitAffectingCombat(object) and UnitIsPlayer(object) and not UnitIsUnit(object,"pet") and not BANETO_IsPetLuabox(object) then
                    local healthMob = BANETO_UnitHealth(object)
                    if healthMob < bestHealth then
                        bestHealth = healthMob
                        bestMob = object
                    end
                end
            end
        end
        if bestMob == Object("target") then
            BANETO_PrintBambo("already targeting best PLAYER hp wise")
        else
            BANETO_PrintBambo("CHANGING TO best PLAYER hp wise")
            UnlockedTargetUnit(bestMob)
        end
    end
end

