function removeSubstringAfterIdentifier(inputString, identifier)
    local _, index = string.find(inputString, identifier)

    if index then
        return string.sub(inputString, 1, index - 1)
    else
        return inputString
    end
end

function _G.BANETO_FindPlayerObjectWithName(name)
    if name then
        if name == BANETO_ObjectName("player") then
            return BANETO_Object("player")
        end
        name = removeSubstringAfterIdentifier(name, "-")
        local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
        for i = 1, #objects do
            local object = objects[i]
            local n = BANETO_ObjectName(object)
            if n == name or string.find(n,name) then
                return object
            end
        end
    end
end
