function _G.GetNumPossibleEnemiesAroundUnit(unit,radius)
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local x,y,z = BANETO_ObjectPosition(unit)
    local counter = 0
    for i = 1, #objects do
        local object = objects[i]
        local x2,y2,z2 = BANETO_ObjectPosition(object)
        local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
        if x and x2 then
            local reaction = UnlockedTargetReaction(object)
            local hp = UnlockedTargetHealth(object)
            local id = BANETO_ObjectId(object)
            local isDummy = false;
            if DummyUnits and DummyUnits[id] then
                isDummy = true
            end
            if distance and distance < radius and hp and hp > 0 and ((reaction and reaction <= 4 and UnitCanAttack("player",object)) or isDummy) then
                local obId = BANETO_ObjectId(unit)
                if obId and obId ~= 6 and obId ~= 257 and obId ~= 80 then
                    counter = counter + 1
                end
            end
        end
    end
    return counter
end


