BANETO_STAT_LASTXP = 0
BANETO_STAT_LASTGOLD = 0
baneto_rtl_gatherinteract = GetTime()
function _G.BANETO_StashStatsValues()
	local xp = UnitXP("player")
	local gold = GetMoney()
	local BANETO_STAT_XPTOTAL = 0
	local BANETO_STAT_GOLDTOTAL = 0

	if not BANETO_FIRST_XP then
		BANETO_FIRST_XP = xp
	end
	if not BANETO_FIRST_GOLD then
		BANETO_FIRST_GOLD = gold
	end
	if not BANETO_STASHSTATS_TABLE_XP then
		BANETO_STASHSTATS_TABLE_XP = { }
	end
	if not BANETO_STASHSTATS_TABLE_GOLD then
		BANETO_STASHSTATS_TABLE_GOLD = { }
	end
	local xPRaw = xp-BANETO_STAT_LASTXP
	if xPRaw < 0 then
		table.insert(BANETO_STASHSTATS_TABLE_XP,0)
		BANETO_STAT_LASTXP = 0
	else
		table.insert(BANETO_STASHSTATS_TABLE_XP,xPRaw)
		BANETO_STAT_LASTXP = xp
	end

	local goldRaw = gold-BANETO_STAT_LASTGOLD
	if goldRaw < 0 then
		table.insert(BANETO_STASHSTATS_TABLE_GOLD,0)
		BANETO_STAT_LASTGOLD = 0
	else
		table.insert(BANETO_STASHSTATS_TABLE_GOLD,goldRaw)
		BANETO_STAT_LASTGOLD = gold
	end

	BANETO_COUNT_STASH = BANETO_COUNT_STASH +1

	for i=1, #BANETO_STASHSTATS_TABLE_XP do
		BANETO_STAT_XPTOTAL = BANETO_STAT_XPTOTAL+BANETO_STASHSTATS_TABLE_XP[i]
		if i == #BANETO_STASHSTATS_TABLE_XP then
			local BANETO_STAT_XPPERH_RAW = (BANETO_STAT_XPTOTAL-BANETO_FIRST_XP)/BANETO_COUNT_STASH*60
			BANETO_STAT_XPPERH = math.ceil(BANETO_STAT_XPPERH_RAW)
		end
	end

	for i=1, #BANETO_STASHSTATS_TABLE_GOLD do
		BANETO_STAT_GOLDTOTAL = BANETO_STAT_GOLDTOTAL+BANETO_STASHSTATS_TABLE_GOLD[i]
		if i == #BANETO_STASHSTATS_TABLE_GOLD then
			BANETO_STAT_GOLDPERH = (BANETO_STAT_GOLDTOTAL-BANETO_FIRST_GOLD)/BANETO_COUNT_STASH*60
		end
	end
end
function _G.BANETO_GetRawgoldPerHour()
    local result;
    --BANETO_PrintBambo("Rawgold analysis: "..BANETO_STAT_GOLDPERH)
    if 10000<BANETO_STAT_GOLDPERH then
        result = BANETO_STAT_GOLDPERH/10000
    else
        result = 0
    end
    return math.ceil(result)
end
