function _G.BANETO_IsUnitInLos(object)
    local x1, y1, z1 = ObjectPosition('player')
    local x2, y2, z2 = BANETO_ObjectPosition(object)
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local distanceToPlayer = BANETO_GetDistance3D(x1, y1, z1,x2, y2, z2)
    if distanceToPlayer and 5.5 > distanceToPlayer then
        return true
    end
    if x1 and y1 and x2 and y2  and type(x1) == "number" and type(x2) == "number" and type(y1) == "number" and type(y2) == "number"  then
        HITx,HITy,HITz = BANETO_TraceLine(x1, y1, z1+2, x2, y2, z2+2, hitFlags)
        local distance = BANETO_GetDistance3D(HITx,HITy,HITz,x2, y2, z2)
        if HITx and HITx ~= 0 and HITy and HITy ~= 0 and HITz and HITz ~= 0 and distance and distance > 4 then
            return false
        else
            return true
        end
    end
end


