	local freebagslotsBag2,bagType2 = GetContainerNumSlots(2)
	local freebagslotsBag3,bagType3 = GetContainerNumSlots(3)
	local freebagslotsBag4,bagType4 = GetContainerNumSlots(4)
	local count = 0
	count = freebagslotsBag0+freebagslotsBag1+freebagslotsBag2+freebagslotsBag3+freebagslotsBag4
	return count
end
function _G.BANETO_GetFreeBagSlots()
	local freebagslotsBag0,bagType0 = GetContainerNumFreeSlots(0)
	local freebagslotsBag1,bagType1 = GetContainerNumFreeSlots(1)
	local freebagslotsBag2,bagType2 = GetContainerNumFreeSlots(2)
	local freebagslotsBag3,bagType3 = GetContainerNumFreeSlots(3)
	local freebagslotsBag4,bagType4 = GetContainerNumFreeSlots(4)
	local count = 0
	if bagType0 == 0 then
		count = freebagslotsBag0 + count
	end
	if bagType1 == 0 then
		count = freebagslotsBag1 + count
	end
	if bagType2 == 0 then
		count = freebagslotsBag2 + count
	end
	if bagType3 == 0 then
		count = freebagslotsBag3 + count
	end
	if bagType4 == 0 then
		count = freebagslotsBag4 + count
	end
	return count
end

