function _G.CancelShapeshift()
	local _, _, class = UnitClass("player")
	if Unlocker("LUA")  and class ~= 4 then
		BANETO_CancelShapeshift()
	elseif Unlocker("LUA") and CallSecureFunction and class ~= 4 then
	    CallSecureFunction("CancelShapeshiftForm")
	elseif Unlocker("EWT") and class ~= 4 then
		CancelShapeshiftForm()
	end
end


function _G.GetShapeshiftDruid()
    local _,_,class = UnitClass("player")
    if class == 11 then
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            return GetShapeshiftForm()
        end
        if Unlocker("LUA") and _internal.Software() == "nn" and not BANETO_IsJin() then
            return Unlock("GetShapeshiftForm","") --was buggy on jin!
        end
        if Unlocker("LUA") and _internal.Software() == "nn" and BANETO_IsJin() then
            return GetShapeshiftForm()
        end
    end
end


function _G.BANETO_GetBuffCooldown(unit,spellid)
	for i = 1, 32 do
		local nameBuffOnPlayer,_,buffCount,_,_,expire,_,_,_,buffOnPlayer,_,_,_,_,_ = UnitBuffWrapper(unit, i)
		if buffOnPlayer then
			if buffOnPlayer == spellid then
				return expire
			end
            local spellInfo = C_Spell.GetSpellInfo(spellid)
			if spellInfo and nameBuffOnPlayer == spellInfo.name then
				return expire
			end
		end
	end
end


