function _G.BANETO_CountDebuffsRestoDf(unit,debuff,range)
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local count = 0
    for i = 1, #objects do
        local object = objects[i]
        local x,y,z = BANETO_ObjectPosition(object)
        local x2,y2,z2 = BANETO_ObjectPosition(unit)
        local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
        if range >= distance and BANETO_HasDebuffWithOwnerCheck(object,debuff) then
            count=count+1
        end
    end
    return count;
end

function _G.BANETO_CountDebuffsAroundUnit(unit,debuff,range)
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local count = 0
    for i = 1, #objects do
        local object = objects[i]
        local x,y,z = BANETO_ObjectPosition(object)
        local x2,y2,z2 = BANETO_ObjectPosition(unit)
        local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
        if range >= distance and BANETO_HasDebuff(object,debuff) then
            count=count+1
        end
    end
    return count;
end

