function _G.BANETO_IsItemFood(itemid)
    BANETO_PrintBambo("Check is item food!")
    if BANETO_ITEMS_FOOD then
        for k = 1, #BANETO_ITEMS_FOOD do
            local idInTable,_,_ = BANETO_ITEMS_FOOD[k][1]
            if itemid == idInTable then
                return true
            end
        end
        return false
    end
end

function _G.BANETO_IsUnitInfrontOfUs(unit)
    if not UnitExists(unit) and not ObjectExists(unit) then
        return false
    end
    local playerPositionX, playerPositionY, playerPositionZ = BANETO_ObjectPosition("player")
    local playerRotation = BANETO_GetObjectFacing(unit)
    local targetPositionX, targetPositionY, targetPositionZ = BANETO_ObjectPosition("target")
    local targetRotation = BANETO_GetObjectFacing("player")
    local coneFacing;
    if targetRotation > math.pi then
        coneFacing = targetRotation - math.pi
    else
        coneFacing = targetRotation + math.pi
    end
    local a = math.pi/3
    local isInCone = BANETO_IsInsideCone(targetPositionX, targetPositionY, targetPositionZ, playerPositionX, playerPositionY, playerPositionZ, coneFacing, a)
    if not isInCone then
        return false
    else
        return true
    end
end

