function _G.BANETO_FindDrinkInBags()
    if BANETO_REGEN_CACHE_DRINK_EMPTY then
        return
    end
    local lvl = UnitLevel("player")
    for k = 1, #BANETO_ITEMS_DRINK do
        local idInTable,_,_ = BANETO_ITEMS_DRINK[k][1]
        local requiredLevel = BANETO_ITEMS_DRINK[k][2]
        if not requiredLevel then requiredLevel = 1 end;
        if requiredLevel <= lvl then
            local amount = GetItemCount(idInTable)
            if amount and amount >= 1 then
                return idInTable
            end
        end
    end
    BANETO_REGEN_CACHE_DRINK_EMPTY = true
end
function _G.BANETO_FindDrinkInBagsOld()
    --BANETO_PrintBambo("Check drink database id..")
    for i = 0, NUM_BAG_SLOTS+1 do
        for z = 1, GetContainerNumSlots(i) do
            if BANETO_ITEMS_DRINK then
                for k = 1, #BANETO_ITEMS_DRINK do
                    local idInBag = GetContainerItemID(i, z)
                    local idInTable,_,_ = BANETO_ITEMS_DRINK[k][1]
                    if idInBag == idInTable then
                        local requiredLevel = BANETO_ITEMS_DRINK[k][2]
                        if requiredLevel <= UnitLevel("player") then
                            return idInBag
                        end
                    end
                end
            end
        end
    end
end

function _G.BANETO_FindFoodInBags()
