function _G.BANETO_GetFoodAmountInBags()
    if BANETO_FOOD_AMOUNT_GLOBAL then
        return BANETO_FOOD_AMOUNT_GLOBAL
    end
	local counter = 0
	local countedItems = { }
	--BANETO_PrintBambo("Check food database amount!")
    for k = 1, #BANETO_ITEMS_FOOD do
        local itemid = BANETO_ITEMS_FOOD[k][1]
        if GetItemCount(itemid) > 0 and not countedItems[itemid] then
            counter = counter + GetItemCount(itemid)
            countedItems[itemid] = true
        end
    end
    BANETO_FOOD_AMOUNT_GLOBAL = counter
	return counter
end

