local protectedPlugins = {}
function _G.HttpRequestCustomOzPlugin(url)
    local domain = url
    local HTTP = Tinkr.Util.HTTP
    HTTP:Request({
        url = domain,
        method = 'GET',
        callback = function (status, res)
            if status == 200 then
                return res
            end
        end
    })
end
function _internal.BANETO_RequestProtectedPlugin(seller,pluginname)
    if seller == "coffee" then
        if BANETO_IsRunning() then
            if BANETO_GetProfileName() == "AzureSpan_MineHerb_Coffee" then
                if (BANETO_GetCurrentCenterIndex()) then
                    if (BANETO_GetCurrentCenterIndex() >= 30 and BANETO_GetCurrentCenterIndex() <= 35) then

                        local banetoTarget = BANETO_GetTarget()
                        local targetX, targetY, targetZ = BANETO_ObjectPosition(banetoTarget)
                        local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
                        local vigorAmount = BANETO_GetSetting([["VigorWait"]])

                        if (targetZ) then

                            local distanceZ = targetZ - playerZ

                            if (BANETO_IsDragonRiding() and not IsFlying()) then

                                local distanceTotal = GetDistanceBetweenObjects("player",banetoTarget)

                                if distanceTotal <= 160 and distanceTotal > 12 and distanceZ < 40 and vigorAmount ~= 1 then
                                    BANETO_SetSettingInt("VigorWait",1)
                                    BANETO_Print("Next node is close. Turning vigor wait to 1 to get there quicker.")
                                elseif (distanceTotal <= 260 or distanceZ <= 140) and (distanceTotal > 160 or distanceZ > 40) and vigorAmount ~= 2 then
                                    BANETO_SetSettingInt("VigorWait",2)
                                    BANETO_Print("Next node is not too far. Turning vigor wait to 2.")
                                elseif (distanceTotal > 260 or distanceZ > 140) and vigorAmount ~= 3 then
                                    BANETO_SetSettingInt("VigorWait",3)
                                    BANETO_Print("Next node is pretty far. Turning vigor wait back to 3.")
                                elseif distanceZ < 0 and distanceTotal > 10 and vigorAmount ~= 1 and math.abs(playerX-targetX) <= 70 and math.abs(playerY-targetY) <= 70 then
                                    BANETO_SetSettingInt("VigorWait",1)
                                    BANETO_Print("Node detected below us. Turning vigor wait to 1 so we can glide there.")
                                end
                            else
                                if distanceZ >= 155 and vigorAmount ~= 3 then
                                    BANETO_SetSettingInt("VigorWait",3)
                                    BANETO_Print("Next node is high up. Turning vigor wait back to 3.")
                                elseif (distanceZ) < 155 and vigorAmount ~= 2 then
                                    BANETO_SetSettingInt("VigorWait",2)
                                    BANETO_Print("Next node isn't too high. Turning vigor wait to 2.")
                                end
                            end
                        elseif not (targetZ) and vigorAmount ~=3 then
