                local banetoTarget = BANETO_GetTarget()
                local targetX, targetY, targetZ = BANETO_ObjectPosition(banetoTarget)
                local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
                local vigorAmount = BANETO_GetSetting([["VigorWait"]])

                if (targetZ) then

                    local distanceZ = targetZ - playerZ
                    local isWindswept = BANETO_ObjectId(banetoTarget)

                    if (isWindswept == 381202 or isWindswept == 381199 or isWindswept == 381213) and targetZ >=150 then
                        BANETO_AddMobToGuidBlacklist(banetoTarget)
                        BANETO_Print("Blacklisting node. Gathering it would kill us.")
                    else
                        if (BANETO_IsDragonRiding() and not IsFlying()) then

                            local distanceTotal = GetDistanceBetweenObjects("player",banetoTarget)

                            if distanceTotal <= 160 and distanceTotal > 12 and distanceZ < 30 and vigorAmount ~= 1 then
                                BANETO_SetSettingInt("VigorWait",1)
                                BANETO_Print("Next node is close. Turning vigor wait to 1 to get there quicker.")
                            elseif (distanceTotal > 160 or distanceZ > 60) and vigorAmount == 1 then
                                BANETO_SetSettingInt("VigorWait",2)
                                BANETO_Print("Next node is pretty far. Turning vigor wait back to 2.")
                            elseif vigorAmount ~= 1 and math.abs(playerX-targetX) <= 50 and math.abs(playerY-targetY) <= 50 and distanceZ < 0 then
                                BANETO_SetSettingInt("VigorWait",1)
                                BANETO_Print("Node detected below us. Turning vigor wait to 1 to get there quicker.")
                            end
                        else
                            if distanceZ >= 165 and vigorAmount == 2 then
                                BANETO_SetSettingInt("VigorWait",3)
                                BANETO_Print("Next node is high up. Turning vigor wait to 3.")
                            elseif (targetZ - playerZ) < 165 and vigorAmount == 3 then
                                BANETO_SetSettingInt("VigorWait",2)
                                BANETO_Print("Next node isn't too high. Turning vigor wait back to 2.")
                            end
                        end
                    end
                elseif not (targetZ) then
                    if (IsSwimming() or IsSubmerged()) and vigorAmount ~=1 then
                        BANETO_SetSettingInt("VigorWait",1)
                        BANETO_Print("We're not heading to a node and we're in water. Turning vigor wait to 1 to look more human.")
                    elseif not (IsSwimming() or IsSubmerged()) and vigorAmount ~=2 then
                        BANETO_SetSettingInt("VigorWait",2)
                        BANETO_Print("Changing back to default vigor of 2.")
                    end
                end
            end
        end
    end
    if seller == "Reichi1995" then
        if protectedPlugins[pluginname] then
            if pluginname == "ReichiAllianzQuester" and not _internal.BANETO_IsOneZeroCustomer("A_Quest") then
                BANETO_PrintError("Auth error on execute: " .. pluginname)
                return false
            end
            if pluginname == "ReichiHordeQuester" and not _internal.BANETO_IsOneZeroCustomer("H_Quest") then
                BANETO_PrintError("Auth error on execute: " .. pluginname)
                return false
            end
            if Unlocker("EWT") then
                 wmbapi.RunScript("",protectedPlugins[pluginname])
            elseif Unlocker("LUA") then
                 Eval(protectedPlugins[pluginname],"ONEZEROPLUGIN")
            end
        end
        if not BANETO_OZ_REQUEST5 then
            local url = "https://onezero-profiles.cc/src/plgns/" .. pluginname ..".lua"
            protectedPlugins[pluginname] = HttpRequestCustomOzPlugin(url)
            BANETO_OZ_REQUEST5 = true
        end
    end
end

