function _G.BANETO_IsPaidPackInstalled(packName)
    if BANETO_IsPackQuester(packName) then
        local firstProfileName = BANETO_GetFirstProfileOfPack(packName)
        if Unlocker("LUA") and firstProfileName then
            local content = ReadFile(baneto_path_scripts_profiles_quests.. firstProfileName .. ".lua")
            if content and content ~= nil then
                if not BANETO_HAS_PAIDPACK then
                    BANETO_HAS_PAIDPACK = true
                end
                return true
            end
        end
    else
        if Unlocker("LUA") then
            local dirExists = DirectoryExists(baneto_path_scripts_profiles .. packName)
            if dirExists and dirExists == true then
                if not BANETO_HAS_PAIDPACK then
                    BANETO_HAS_PAIDPACK = true
                end
                return true
            end
        end
    end
end


function _G.BANETO_CheckMeshNn()
    if _internal.Software() == "nn" and MESHCHECKWANTEDFORNN then
        local var = FileExists("/mmaps/sl/0169.mmap")
        local var2 = FileExists("/mmaps/sl/0309.mmap")
        local var3 = FileExists("/mmaps/sl/0540.mmap")
        if var or var2 or var3 then
            if not DirectoryExists("/mmaps/wotlk/wotlk") and not DirectoryExists("/mmaps/sl/sl") then
                if DirectoryExists("/mmaps/sl") and DirectoryExists("/mmaps/wotlk") then
                    return true
                else
                    return "some mmaps folders are missing"
                end
            else
                return false,"mmaps folders/files are nested too deep."
            end
        else
            return false,"mmaps files are missing"
        end
    end
end

function _G.BANETO_InstallPaidPack(packName)
    BANETO_PAID_PACK_RELOADER = true
    if Unlocker("LUA") and not BANETO_IsPaidPackInstalled(packName) and not BANETO_IsPackQuester(packName) then
        CreateDirectory(baneto_path_scripts_profiles  .. packName)
    end
    if BANETO_IsPackQuester(packName) then
        for i = 1, #ownedPacksBnt do
            if packName == ownedPacksBnt[i][1] then
                for q = 1, #ownedPacksBnt[i][2] do
                    local profile = ownedPacksBnt[i][2][q]
                    if profile then
                        if Unlocker("LUA") then
                            WriteFile(baneto_path_scripts_profiles_quests .. profile .. ".lua","BANETO_LoadOfficialPaid([[" .. packName .."]],[["..profile.."]])",false)
                        end
                    end
                end
            end
        end
    else
        for i = 1, #ownedPacksBnt do
            if packName == ownedPacksBnt[i][1] then
                for q = 1, #ownedPacksBnt[i][2] do
                    local profile = ownedPacksBnt[i][2][q]
                    if profile then
                        if Unlocker("LUA") then
                            WriteFile(baneto_path_scripts_profiles..packName.. "/".. profile .. ".lua","BANETO_LoadOfficialPaid([[" .. packName .."]],[["..profile.."]])",false)
                        end
                    end
                end
            end
        end
    end
end

