function BANETO_ExecuteLinkAction(action,argument)
    if action and action ~= "none" and (action ~= "load" or not argument) then
        BANETO_Print("DISCORD Action: "..action)
    end
    if action == "load" and argument then
        BANETO_Print("DISCORD Action: "..action .. " "..argument)
        _G.BANETO_LoadProfile(argument,true)
    end
    if action == "target" and argument then
        local objects = BANETO_GetObjctsTkr()
        for i=1, #objects do
            local object = objects[i]
            local name = BANETO_ObjectName(object)
            if name == argument then
                UnlockedTargetUnit(object)
            end
        end
    end
    if action == "whisper" and argument and BANETO_LAST_SENDER then
        BANETO_SendChatMessage(argument ,"WHISPER" ,"COMMON" ,BANETO_LAST_SENDER)
    end
    if action == "vendor" then
        BANETO_VisionTriggers("REPAIR")
    end
    if action == "hearthstone" then
        BANETO_UNSTUCK_HEARTHSTONE=true
    end
    if action == "jump" then
        BANETO_JumpOrAscendStart()
    end
    if action == "start" then
        BANETO_Start()
    end
    if action == "stop" then
        BANETO_Stop()
    end
    if action == "shutdown" then
        BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            Eval("ForceQuit()","asdas")
        elseif  _internal.Software() == "nn" then
            Unlock("ForceQuit","")
        end
    end
    if action == "sleep" then
        BANETO_PrintState("DISCORD sleep begins (10 minutes)")
        BANETO_DelayStateTick(600)
        BANETO_StopMovement()
        waPath = nil
        flyingPath = nil
        C_Timer.After(2,BANETO_StopMovement)
        C_Timer.After(4,BANETO_StopMovement)
    end
    if action == "reload" then
        C_Timer.After(2, reloadUi)
        C_Timer.After(4, reloadUi)
        C_Timer.After(6, reloadUi)
    end
end

function BANETO_GetDiscordLinkActions()
    if BANETO_SETTING_DCBOTLINK and BANETO_SETTING_DCBOTLINK ~= "" and BANETO_SETTING_DCBOTLINK ~= "nostringinput" then
        local payload = {
            discordLink = BANETO_SETTING_DCBOTLINK,
            charname = UnitName("player")
        }
        local jsonPayload;
        local url1 = ""        if _internal.Software() == "nn" then
            local JSON = Tinkr.Utils.JSON
            jsonPayload = JSON.encode(payload)
        elseif _internal.Software() == "tnk" then
            jsonPayload = json.encode(payload)
        end

        local function callbackdiscordlink(status,body)
           if status and (status == 200 or status == 204) then
                local value;
                local actionArg;
                local response;
                if _internal.Software() == "nn" then
                    local JSON = Tinkr.Utils.JSON
                    response = JSON.decode(body)
                elseif _internal.Software() == "tnk" then
                    response = json.decode(body)
                end
                value = response["action"] or "unknownDcActionLuaSide"
                actionArg = response["actionArg"] or "unknownDcActionArgumentLuaSide"
                BANETO_ExecuteLinkAction(value,actionArg)
           end
        end
        BANETO_HttpPost(url1,jsonPayload,callbackdiscordlink)
    end
end

