function _G.HttpRequestCustom(url)
    if _internal.Software() == "tnk" then
        local domain = url
        local HTTP = Tinkr.Util.HTTP
        HTTP:Request({
            url = domain,
            method = 'GET',
            callback = function (status, res)
                if status == 200 then
                    Eval(res, tostring(time))
                end
            end
        })
    elseif _internal.Software() == "nn" then
        local url = url
        local params = {}
        local function callback(status, data)
            if status == 200 then
                local testload = loadstring(data,"")
                --testload()
                RunScript(data)
            end
        end
        HTTP:GET(url, params, callback)
    end
end

