function _G.BANETO_GetBestSeedInBags()
    if GetItemCount(200509) >= 1 and GetItemCooldown(200509) == 0 and not BANETO_USED_SEED_AGITATED then --agitated
        return 200509
    elseif GetItemCount(200508) >= 1 and GetItemCooldown(200508) == 0 and not BANETO_USED_SEED_PROPAGATING  then --propagating
        return 200508
    elseif GetItemCount(200507) >= 1 and GetItemCooldown(200507) == 0 and not BANETO_USED_SEED_DECAYED then --decayed
        return 200507
    elseif GetItemCount(200506) >= 1 and GetItemCooldown(200506) == 0 then --base
        return 200506
    elseif GetItemCount(214561) >= 1 and GetItemCooldown(214561) == 0 then --214561 verdant
        return 214561
    end
end

