function _internal.BANETO_CoffeeProfileHandler(name)
    if not _G.CoffeeProducts then
        BANETO_PrintWarning("Coffee Auth Error Alpha")
        return false
    end
    for i = 1,#_G.CoffeeProducts do
        local profilenames = _G.CoffeeProducts[i]["profilenames"]
        for q = 1, #profilenames do
            local profilename = profilenames[q]
            if profilename == name then
                local packName = _G.CoffeeProducts[i]["packName"]
                local pathToFile = _G.CoffeeProducts[i]["pathToFile"]
                local authTableForPack = _G.CoffeeProducts[i]["authTable"]
                if _internal.BANETO_IsLegitCoffeeUser(packName,authTableForPack) then
                    _internal.BANETO_LoadCoffeeDb("bambo/DF/Questing"..pathToFile..profilename..".lua",packName,profilename)
                end
            end
        end
    end
end

function _internal.BANETO_RequestProtectedProfile(seller,profilename)
	BANETO_ClearProfileData()
    print("seller".. seller)
    print("lua file: ".. profilename)
    if seller == "coffee" then
        _internal.BANETO_CoffeeProfileHandler(profilename)
        return false
    end


    local state,productname = _internal.BANETO_IsOfficialOzProfile(profilename)
    if state and _internal.BANETO_IsOneZeroCustomer(productname) then
        _internal.BANETO_RequestFromOzServer(profilename)

        --BANETO_PrintBambo("Request from OZ: "..profilename)
        return false
    end
    --BANETO_PrintBambo("Not request from OZ: "..profilename)



