function _G.BANETO_LoadProtectedProfile(seller,profilename)
    print("test1")
	_internal.BANETO_RequestProtectedProfile(seller,profilename)
end

function _G.BANETO_AmIGettingAttackedByEnemyPlayer()
    if Unlocker("LUA")  then
        local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
        local x,y,z = BANETO_ObjectPosition("player")
        local radius = 120
        for i = 1, #objects do
            local object = objects[i]
            local x2,y2,z2 = BANETO_ObjectPosition(object)
            local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
            if x and x2 then
                if distance < radius and   UnitIsPlayer(object) and  UnitAffectingCombat(object) and UnlockedTargetReaction(object) ~= 5 and UnitTarget(object) == Object("player") then
                    return true
                end
            end
        end
    end
end

function _G.BANETO_GetDrinkAmountInBags()
	local counter = 0
	local countedItems = { }
    if BANETO_DRINK_AMOUNT_GLOBAL then
        return BANETO_DRINK_AMOUNT_GLOBAL
    end
	--BANETO_PrintBambo("Check drink database amount!")
    for k = 1, #BANETO_ITEMS_DRINK do
        local itemid = BANETO_ITEMS_DRINK[k][1]
        if GetItemCount(itemid) > 0 and not countedItems[itemid] then
            counter = counter + GetItemCount(itemid)
            countedItems[itemid] = true
        end
    end
    BANETO_DRINK_AMOUNT_GLOBAL = counter
	return counter
end


function _G.BANETO_GetBestAmmoType()
