		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				for k = 1, #BANETO_ITEMS_BULLETS do
					local id = GetContainerItemID(i, z)
					local _,amount,_,_,_,_,_,_,_,_ = GetContainerItemInfo(i, z)
					local tableid = BANETO_ITEMS_BULLETS[k][1]
					if id == tableid then
						counter = counter +amount
					end
				end
			end
		end
	end
	if BANETO_SETTING_HUNTER_ARROWS and BANETO_SETTING_HUNTER_ARROWS == true then
