function _G.BANETO_CastSpell(spellid,canMove,target)
    local spellInfo = C_Spell.GetSpellInfo(spellid)
    if spellInfo and (not BANETO_CAST_SPELL_DELAY or BANETO_CAST_SPELL_DELAY < GetTime()) then
        local spellname = spellInfo.name
        local speed = BANETO_GetUnitSpeed("player")
        if speed == 0 or (canMove and canMove == true) then
            if _internal.Software() == "tnk" then
                if target then
                    CastSpellByName(spellname,target)
                else
                    CastSpellByName(spellname)
                end
            else
                if strafeleftdelayer then
                    if BANETO_IsDragonRiding() then
                        --strafeleftdelayer = GetTime()+0.05 might be needed, disabled for halenir
                    else
                        --strafeleftdelayer = GetTime()+0.5 might be needed, disabled for halenir
                    end
                end
                if BANETO_IsJin() then
                    CastSpellByName(spellname, target)
                else
                    if target then
                        C_Timer.Nn.CastSpellByName(spellname, target)
                    else
                        C_Timer.Nn.CastSpellByName(spellname)
                    end
                end
            end
            if spellid ~= 6603 then
                if not UnitCastingInfo("player") then
                    BANETO_PrintFight("Casting " .. spellname)
                end
            else
                BANETO_PrintFight("Melee Attack on Target!")
            end
        else
            BANETO_PrintWarning("Cast " .. spellname  .." denied due to movement.")
        end
    end
end

function _G.BANETO_CastSpellOnGround(spellid,unit)
    BANETO_CastSpell(spellid)
    if Unlocker("LUA") then
        local x,y,z = BANETO_ObjectPosition(unit)
        local name = BANETO_ObjectName(unit)
        BANETO_PrintFight("Casting on ground below: "..name)
        BANETO_ClickPosition(x,y,z)
    end
end

