function _G.BANETO_UnitMana(unit)
	local _,_,class = UnitClass("player")
	local powerType, powerToken, altR, altG, altB = UnitPowerType(unit)
	if class == 1 or class == 4 or class == 3 or class == 6 or GetShapeshiftDruid() == 2 or GetShapeshiftDruid() == 1 or GetShapeshiftDruid() == 3 or powerToken == "LUNAR_POWER" or powerToken == "INSANITY" or powerType == 11 then
