function _G.GetObjectWithIdIncludingBlacklistCheck(id)
    if Unlocker("LUA")  then
        local objects = BANETO_GetObjctsTkr()
        local tObjectWithId = {}
        for i=1, #objects do
            local idO = BANETO_ObjectId(objects[i])
            if idO == id and not BANETO_IsGuidContainedInGuidBlacklist(objects[i]) and not IsUnitIdBlacklisted(idO) then
                table.insert(tObjectWithId, { objects[i], GetDistanceBetweenObjects("player", objects[i]) })
            end
        end
        if #tObjectWithId > 1 then table.sort(tObjectWithId, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
        if tObjectWithId[1] then
            --[[ ewtPath = nil --BUGGY? ewt pathing stop? --]]
            return tObjectWithId[1][1]
        end
    end
end

