            local itemCount,itemNeededCount = GetItemCount(BANETO_AHSHUFFLE_MATERIALS_BUYFROMVENDOR[i][1]),BANETO_AHSHUFFLE_MATERIALS_BUYFROMVENDOR[i][2]*BANETO_AHSHUFFLE_ENDPRODUCT[3]
