function _G.BANETO_ScanIceCracks()
    local icecracks = {}
    local objects = BANETO_GetObjctsTkr()
    local icecrack = 377944
    for i=1, #objects do
        local object = objects[i]
        local id = BANETO_ObjectId(object)
        local range = GetDistanceBetweenObjects("player",object)
        if id == icecrack then
            if not IsUnitBlacklisted(object) then
                table.insert(icecracks, { object, range })
            end
        end
    end
    if #icecracks > 1 then table.sort(icecracks, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
    if icecracks[1] then
        return icecracks[1][1]
    end
end

function _G.BANETO_ScanIceHoles()
    local holes = {}
    local objects = BANETO_GetObjctsTkr()
    local fishingHole = 192631
    local deepFishingHole = 197596
    for i=1, #objects do
        local object = objects[i]
        local id = BANETO_ObjectId(object)
        local range = GetDistanceBetweenObjects("player",object)
        if id == fishingHole or id == deepFishingHole then
            if not IsUnitBlacklisted(object) then
                table.insert(holes, { object, range })
            end
        end
    end
    if #holes > 1 then table.sort(holes, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
    if holes[1] then
        return holes[1][1]
    end
end
function _G.BANETO_SetBanetoTarget(unit)
    BANETO_TARGET = unit
end
function _G.BANETO_IceFishingState()
    local hole = BANETO_ScanIceHoles()
    local crack = BANETO_ScanIceCracks()
    local isCrack = false;
    if hole then
        BANETO_TARGET = hole
    elseif crack then
        BANETO_TARGET = crack
        isCrack = true
    end
    if BANETO_TARGET then
        local dist = GetDistanceBetweenObjects("player",BANETO_TARGET)
        if dist < 9 then
            if IsMounted() then
                BANETO_Dismount()
            end
            BANETO_DfLures()
            if UnitChannelInfo("player") then
                if BANETO_GetBobberState() then
                    BANETO_InteractWithBobber()
                end
            else
                BANETO_StopMovement()
                local speed = BANETO_GetUnitSpeed("player")
                if speed == 0 then
                    BANETO_Interact(BANETO_TARGET)
                    if isCrack == true then
                        BANETO_DelayStateTick(5)
                    end
                end
            end
        else
            local x,y,z = BANETO_ObjectPosition(BANETO_TARGET)
            BANETO_MeshTo(x,y,z)
        end
    else
        if not banetoicecrackprint or banetoicecrackprint < GetTime() then
            BANETO_PrintState("Looking for ice cracks...")
            banetoicecrackprint = GetTime()+5
        end
        local table = {
            {-4242.8984375,-2457.6694335938,955.74346923828,130},
            {-3186.8864746094,-1276.0072021484,824.44323730469,130},
            {-3252.8913574219,-1053.0827636719,824.69702148438,130},
            {-3249.7224121094,-874.25836181641,809.81945800781,130},
            {-3298.1586914062,-718.93060302734,794.81988525391,130},
            {-3287.4411621094,-640.99859619141,794.81988525391,130},
            {-3265.8029785156,-395.22689819336,794.81951904297,130},
            {-3479.9963378906,-492.87954711914,794.81909179688,130}
        }
        if not icecracks_index then
            icecracks_index = BANETO_GetCenterIndexInPath(table)
        end
        local x,y,z = table[icecracks_index][1],table[icecracks_index][2],table[icecracks_index][3]
        if not BANETO_PlayerPosition(x,y,z,40) then
            BANETO_PrintState("Walking to crack spot "..icecracks_index)
            BANETO_MeshTo(x,y,z)
        else
            icecracks_index = icecracks_index+1
            if icecracks_index > #table then
                icecracks_index=1
            end
            BANETO_PrintState("Changing to NEXT crack spot: "..icecracks_index)
        end
    end
end

function _G.BANETO_IceFishing()
    local objects = BANETO_GetObjctsTkr()
    local icecrack = 377944
    local fishingHole = 192631
    local deepFishingHole = 197596
    if UnitChannelInfo("player") then
        if BANETO_GetBobberState() then
            BANETO_InteractWithBobber()
        end
    else
        for i=1, #objects do
            local object = objects[i]
            local id = BANETO_ObjectId(object)
            local range = GetDistanceBetweenObjects("player",object)
            if id == icecrack and range <= 10 then
                BANETO_Interact(object)
            end
            if id == fishingHole and range <= 10 then
                BANETO_Interact(object)
            end
            if id == deepFishingHole and range <= 10 then
                BANETO_Interact(object)
            end
        end
    end
end

