function _G.BANETO_MailHandler()
	--[[ GOLD MAILING --]]
    if SendMailFrame:IsVisible() == false then
        MailFrameTab2:Click()
    end
	if BANETO_SETTING_MAILING_GOLD and not BANETO_SETTING_MAILING_GOLDSENT then
		if BANETO_SETTING_MAILING_GOLD_AMOUNT*10000 < GetMoney() then
			local money = GetMoney()
			local gold = math.floor(GetMoney()/10000)
			money = GetMoney()-gold*10000
			local silver = math.floor(money/100)
			money = GetMoney()-gold*10000-silver*100
			local copper = money
			gold = gold - BANETO_SETTING_MAILING_GOLD_AMOUNT
            if _internal.Software() == "tnk" then
                SetSendMailMoney(gold*10000+silver*100+copper)
                SendMail(BANETO_SETTING_MAIL_RECIPIENT,"Gold for " .. BANETO_SETTING_MAIL_RECIPIENT)
            elseif _internal.Software() == "nn" then
                Unlock("SetSendMailMoney",gold*10000+silver*100+copper)
                Unlock("SendMail",BANETO_SETTING_MAIL_RECIPIENT,"Gold for " .. BANETO_SETTING_MAIL_RECIPIENT)
            end
			if not BANETO_SETTING_MAILING_GOLDSENT then
				BANETO_SETTING_MAILING_GOLDSENT = true
			end
		else
			BANETO_SETTING_MAILING_GOLDSENT = true
		end
	end

	if BANETO_SETTING_MAILING_GOLDSENT or BANETO_SETTING_MAILING_GOLD == false then
		--[[ ITEM MAILING --]]
		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				local id = GetContainerItemID(i, z)
				local itemLoc = ItemLocation:CreateFromBagAndSlot(i,z)
				local isBound;
				if itemLoc and itemLoc:IsValid() then
				    isBound = C_Item.IsBound(itemLoc)
				end
				if not BANETO_IsItemMailBlacklisted(id) and not isBound then
					if not mailStep then
						mailStep = 0
					end
					if id then
                        if Unlocker("LUA") and _internal.Software() == "tnk" then
                            Eval("C_Container.UseContainerItem(" ..i .. "," .. z .. ")","somth")
                        end
                        if Unlocker("LUA") and _internal.Software() == "nn" then
                            --Unlock("C_Container.UseContainerItem",i,z)
                            Unlock("pcall", C_Container.UseContainerItem, i, z)
                        end
						mailStep = mailStep + 1
                        if mailStep >= 12 or (BANETO_MAIL_DELAY and BANETO_MAIL_DELAY-1 < GetTime()) then
							if GetSendMailPrice() >= 60 then
                                if _internal.Software() == "tnk" then
                                    SendMail(BANETO_SETTING_MAIL_RECIPIENT,"Mail for " .. BANETO_SETTING_MAIL_RECIPIENT)
                                elseif _internal.Software() == "nn" then
                                    Unlock("SendMail",BANETO_SETTING_MAIL_RECIPIENT,"Mail for " .. BANETO_SETTING_MAIL_RECIPIENT)
                                end
								mailStep = nil
							end
						end
					end
				end
			end
		end
	end
	if not BANETO_MAIL_DELAY and _G.BANETO_MAIL_NEEDED then
		BANETO_MAIL_DELAY = GetTime()+ 26.00
	end
	if BANETO_MAIL_DELAY then
		if BANETO_MAIL_DELAY < GetTime() and _G.BANETO_MAIL_NEEDED then
			BANETO_MAIL_DONE = true
			_G.BANETO_MAIL_NEEDED = nil
			BANETO_MAIL_DELAY = nil
		end
	end


end

function _G.BANETO_IsItemInBanetoCategories(itemid)

	--[[ ORES --]]
	for i = 1, #BANETO_ITEMS_ORES do
		local item = BANETO_ITEMS_ORES[i]
		if item == itemid then
			return true
		end
	end
	--[[  ENCHANTMATS  --]]
	for i = 1, #BANETO_ITEMS_DISENCHANTMATS do
		local item = BANETO_ITEMS_DISENCHANTMATS[i]
		if item == itemid then
			return true
		end
	end
	--[[  HERB  --]]
	for i = 1, #BANETO_ITEMS_HERBS do
		local item = BANETO_ITEMS_HERBS[i]
		if item == itemid then
			return true
		end
	end
	--[[  LEATHER --]]
	for i = 1, #BANETO_ITEMS_LEATHER do
		local item = BANETO_ITEMS_LEATHER[i]
		if item == itemid then
			return true
		end
	end
	--[[  CLOTH  --]]
	for i = 1, #BANETO_ITEMS_CLOTH do
		local item = BANETO_ITEMS_CLOTH[i]
		if item == itemid then
			return true
		end
	end
end

function _G.BANETO_IsItemMailBlacklisted(itemid)
	if not BANETO_IsItemInAlwaysMailList(itemid) then
		if itemid then
            if conjuredItemIds[itemid] then
                return true
            end
            local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
                itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
                isCraftingReagent = GetItemInfo(itemid)
            if bindType and (bindType == 1 or bindType == 2 or bindType == 3 or bindType == 4) and BANETO_SETTING_MAIL_SOULBOUNDS == false then
                return true
		    end
			--[[ HEARTHSTONE --]]
			if itemid == 6948 or itemid == 212308 or itemid == 212309 or itemid == 212314 or itemid == 124671 then
				return true
			end
			--[[ FOODS --]]
			for i = 1, #BANETO_ITEMS_FOOD do
				local itemidFood = BANETO_ITEMS_FOOD[i][1]
				if itemidFood == itemid then
					return true
				end
			end
			--[[ DRINKS --]]
			for i = 1, #BANETO_ITEMS_DRINK do
				local itemidDrink = BANETO_ITEMS_DRINK[i][1]
				if itemidDrink == itemid then
					return true
				end
			end

			for i = 1, #BANETO_ITEMS_ARROWS do
				local itemidAmmo,_,_ = BANETO_ITEMS_ARROWS[i][1],BANETO_ITEMS_ARROWS[i][2],BANETO_ITEMS_ARROWS[i][3]
				if itemidAmmo == itemid then
					return true
				end
			end

			for i = 1, #BANETO_ITEMS_BULLETS do
				local itemidAmmo,_,_ = BANETO_ITEMS_BULLETS[i][1],BANETO_ITEMS_BULLETS[i][2],BANETO_ITEMS_BULLETS[i][3]
				if itemidAmmo == itemid then
					return true
				end
			end

			--[[  USER DO NOT MAIL LIST --]]
			if BANETO_SETTING_MAILING_DONOTMAIL then
				for i = 1, #BANETO_SETTING_MAILING_DONOTMAIL do
					local itemNameTable = BANETO_SETTING_MAILING_DONOTMAIL[i]
					local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
						itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
						isCraftingReagent = GetItemInfo(itemNameTable)
					local itemName2, itemLink2, itemRarity2, itemLevel2, itemMinLevel2, itemType2, itemSubType2, itemStackCount2,
						itemEquipLoc2, itemIcon2, itemSellPrice2, itemClassID2, itemSubClassID2, bindType2, expacID2, itemSetID2,
						isCraftingReagent2 = GetItemInfo(itemid)
                    if itemLink == itemLink2 or BANETO_WildcardCheck(itemName2,itemNameTable) then
						return true
					end
				end
			end
			--[[  ITEM COLOURS --]]
			local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
				itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
				isCraftingReagent = GetItemInfo(itemid)
			--[[  GRAY  --]]
			if itemRarity == 0 and BANETO_SETTING_MAILING_GRAY == false then
				return true
			end
			--[[  WHITE  --]]
			if itemRarity == 1 and BANETO_SETTING_MAILING_WHITE == false and not BANETO_IsItemInBanetoCategories(itemid) then
				return true
			end
			--[[  GREEN --]]
			if itemRarity == 2 and BANETO_SETTING_MAILING_GREEN == false then
				return true
			end
			--[[  BLUE  --]]
			if itemRarity == 3 and BANETO_SETTING_MAILING_BLUE == false then
				return true
			end
			--[[  PURPLE  --]]
			if itemRarity == 4 and not _G.BANETO_RETAIL_MAIL_EPICS then
				return true
			end
			--[[  ORE --]]
			if BANETO_SETTING_MAILING_ORES == false then
				for i = 1, #BANETO_ITEMS_ORES do
					local item = BANETO_ITEMS_ORES[i]
					if item == itemid then
						return true
					end
				end
			end
			--[[  ENCHANTMATS  --]]
			if BANETO_SETTING_MAILING_ENCHANTMATS == false then
				for i = 1, #BANETO_ITEMS_DISENCHANTMATS do
					local item = BANETO_ITEMS_DISENCHANTMATS[i]
					if item == itemid then
						return true
					end
				end
			end
			--[[  HERB  --]]
			if BANETO_SETTING_MAILING_HERBS == false then
				for i = 1, #BANETO_ITEMS_HERBS do
					local item = BANETO_ITEMS_HERBS[i]
					if item == itemid then
						return true
					end
				end
			end
			--[[  LEATHER --]]
			if BANETO_SETTING_MAILING_LEATHER == false then
				for i = 1, #BANETO_ITEMS_LEATHER do
					local item = BANETO_ITEMS_LEATHER[i]
					if item == itemid then
						return true
					end
				end
			end
			--[[  CLOTH  --]]
			if BANETO_SETTING_MAILING_CLOTH == false then
				for i = 1, #BANETO_ITEMS_CLOTH do
					local item = BANETO_ITEMS_CLOTH[i]
					if item == itemid then
						return true
					end
				end
			end
		end
	end
end

