function _G.BANETO_EternalExtrawunschExecuter()
	if not BANETO_EternalExtrawunsch_UsedPot then
		local potion = 3387
		BANETO_UseItem(potion)
		BANETO_EternalExtrawunsch_UsedPot = true
		BANETO_EternalExtrawunsch_UsedPotTimer = GetTime()+5
	elseif BANETO_EternalExtrawunsch_UsedPotTimer < GetTime() then
		local vanish = 1857
		if BANETO_IsSpellUsable(vanish) and not BANETO_EternalExtrawunsch_UsedVanishTimer then
			BANETO_CastSpell(vanish)
			BANETO_EternalExtrawunsch_UsedVanishTimer = GetTime()+1
		end
		if BANETO_EternalExtrawunsch_UsedVanishTimer and BANETO_EternalExtrawunsch_UsedVanishTimer < GetTime() then
			BANETO_CastSpell(vanish)
			BANETO_EternalExtrawunsch_UsedVanishTimer = nil
			BANETO_EternalExtrawunsch_UsedPotTimer = nil
			BANETO_EternalExtrawunsch_Active = nil
			BANETO_EternalExtrawunsch_UsedPot = nil
		end
	end

end

function _G.BANETO_EternalExtrawunsch()
	if not BANETO_EternalExtrawunsch_Active and not BANETO_EternalExtrawunsch_UsedPotTimer then
		BANETO_EternalExtrawunsch_Active = true
	end
end

