end

function _G.BANETO_SCAN_DEAD()
	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYUNITS
		t = {}
		for i = 1,#objects do
			local object = objects[i]
			local xSpot,ySpot,zSpot = xCord,yCord,zCord
			local x,y,z =  BANETO_ObjectPosition(object)
			local creatureType = UnlockedTargetCreatureType(object)
			if BANETO_UnitHealth(object) <= 0 and creatureType ~= "Mechanical" and creatureType ~= "Mechanisch" and creatureType ~= "Elemental" then
				table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
			end
		end
	end

	if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if t[1] then
		return t[1][1]
	end
end


_G.BANETO_LEVELDIFFERENCE_MOBSCAN = 12
function _G.BANETO_SCAN(xCord,yCord,zCord,radius)
    if BANETO_Anerikc_OnSpotCheck and BANETO_Anerikc_OnSpotCheck() == false then

        return
    end

	if Unlocker("LUA") then
		local objects = BANETO_OBJTS_TKR_ONLYUNITS
		t = {}
        local xSpot,ySpot,zSpot = xCord,yCord,zCord
		for i = 1,#objects do
			local object = objects[i]
			local creatureType = UnlockedTargetCreatureType(object)
			local reac = UnlockedTargetReaction(object)
			if not BANETO_TARGET and BANETO_SETTING_PETBATTLES and BANETO_SETTING_PETBATTLES == true and reac and reac < 5 and not UnitAffectingCombat("player") and (creatureType == "Wild Pet" or creatureType == "UngezÃ¤hmtes Tier") and UnlockedTargetHealth(object) > 0  and not IsUnitBlacklisted(object) then
			    t = {}
			    table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
			    break;
			end
			if  UnlockedTargetHealth(object) > 0  and (not BANETO_BLOCK_SCANS or BANETO_BLOCK_SCANS < GetTime()) and not _G.HANKA_BLOCK_MOBSCAN and (BANETO_SETTING_ACTIVEENGAGE == true or _G.MULTIPULL_ACTIVE_ENGAGE_IS_DISABLED) and BANETO_IsPetLuabox(object) == false and not BANETO_TARGET then
			    if UnitLevel("player") >= UnitLevel(object)-BANETO_LEVELDIFFERENCE_MOBSCAN  and (not BANETO_LOWLEVELMOB_DIFFERENCE or UnitLevel(object) >= UnitLevel("player")-BANETO_LOWLEVELMOB_DIFFERENCE) and (UnlockedTargetReaction(object) == 4 or UnlockedTargetReaction(object) == 2 ) then
                    if creatureType ~= "Critter" and creatureType ~= "Wild Pet" and creatureType ~= "å°å¨ç©" and creatureType ~= "Tier"  and creatureType ~= "Kleintier" then
                        local playerX,playerY,playerZ = BANETO_ObjectPosition("player")
                        local x,y,z =  BANETO_ObjectPosition(object)
                        if x and y and z and playerZ and playerY then
                            if playerZ >= z then
                                zDistance = playerZ - z
                            elseif playerZ < z then
                                zDistance = z - playerZ
                            end
                            if zDistance < BANETO_COMBAT_RANGE+15 and UnitCanAttack("player",object) then
                                if BANETO_GetDistance3D(x,y,z,xSpot,ySpot,zSpot) < radius and not IsUnitBlacklisted(object) and not BANETO_SCAN_SKINNING() then
                                    --[[ BANETO_StopMovement() --]]
                                    local objectId = BANETO_ObjectId(object)
                                    if objectId and not DummyUnits[objectId] then
                                        if UnitAffectingCombat(object) == false or _G.BANETO_ALLOWSCAN_COMBATMOBS or BANETO_SETTING_HYPERSPAWN then
                                            local classification = UnlockedTargetClassification(object)
                                            if BANETO_SETTING_TARGET_ELITES == true and (classification == "elite" or classification == "rareelite" or classification == "rare") then
                                                table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
                                            elseif classification ~= "elite" and  classification ~= "rare" and  classification ~= "rareelite"  then
                                                if BANETO_SETTING_IGNOREGRAYMOBS == true and UnlockedUnitIsTrivial(object) == false  then
                                                    table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
                                                elseif BANETO_SETTING_IGNOREGRAYMOBS == false then
                                                    table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
			    end
			end
		end
	end

	if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if t[1] then
		--[[ ewtPath = nil --BUGGY? ewt pathing stop? --]]
		return t[1][1]
	end

end

