function _G.BANETO_RETAIL_LVL_ROTATION()
    if BANETO_SETTING_HEKILI and BANETO_SETTING_HEKILI == true then
        return false
    end
    if BANETO_GLOBAL_WHITELIST_HEALS and #BANETO_GLOBAL_WHITELIST_HEALS >= 1 and (not BANETO_GLOBAL_WHITELIST_SPELLS_DELAY or BANETO_GLOBAL_WHITELIST_SPELLS_DELAY < GetTime()) and BANETO_UnitHealth("player") < 50 then
        BANETO_GLOBAL_WHITELIST_SPELLS_DELAY = GetTime()+1
        if not BANETO_GLOBAL_WHITELIST_HEALS_ITER then
            BANETO_GLOBAL_WHITELIST_HEALS_ITER = 1
        end
        local spellId = BANETO_GLOBAL_WHITELIST_HEALS[BANETO_GLOBAL_WHITELIST_HEALS_ITER][1]
        BANETO_PrintFight("Custom Whitelist Heal: " .. spellId)
        if not BANETO_IsSpellOnCooldown(spellId) and BANETO_IsSpellUsable(spellId) and (not UnitExists("target") or not BANETO_HasDebuff("target",spellId)) then
            BANETO_CastSpell(spellId)
            BANETO_GLOBAL_WHITELIST_HEALS_ITER = BANETO_GLOBAL_WHITELIST_HEALS_ITER+1
        end
        if BANETO_GLOBAL_WHITELIST_HEALS_ITER > #BANETO_GLOBAL_WHITELIST_HEALS then
            BANETO_GLOBAL_WHITELIST_HEALS_ITER = 1
        end
        return false
    end

    if BANETO_GLOBAL_WHITELIST_SPELLS and #BANETO_GLOBAL_WHITELIST_SPELLS >= 1 and (not BANETO_GLOBAL_WHITELIST_SPELLS_DELAY or BANETO_GLOBAL_WHITELIST_SPELLS_DELAY < GetTime()) then
        BANETO_GLOBAL_WHITELIST_SPELLS_DELAY = GetTime()+1
        if not BANETO_GLOBAL_WHITELIST_SPELLS_ITER then
            BANETO_GLOBAL_WHITELIST_SPELLS_ITER = 1
        end
