        if not BANETO_IsSpellOnCooldown(spellId) and BANETO_IsSpellUsable(spellId) and (not UnitExists("target") or not BANETO_HasDebuff("target",spellId)) then
            BANETO_CastSpell(spellId)
            BANETO_GLOBAL_WHITELIST_SPELLS_ITER = BANETO_GLOBAL_WHITELIST_SPELLS_ITER+1
        end
        if BANETO_GLOBAL_WHITELIST_SPELLS_ITER > #BANETO_GLOBAL_WHITELIST_SPELLS then
            BANETO_GLOBAL_WHITELIST_SPELLS_ITER = 1
        end
        return false
    end


