        if BANETO_IsSpellKnown(charge) and UnitExists("target") and GetDistanceBetweenObjects("player", "target") > 11.5 and BANETO_IsSpellUsable(charge) and (not duration1 or duration1 == 0) and UnitLevel("player") >= 2  then
            BANETO_PrintBambo("warrior charge")
            BANETO_CastSpell(charge,true)
        elseif BANETO_IsSpellKnown(victoryrush) and BANETO_IsSpellUsable(victoryrush) and BANETO_UnitHealth("player") < 70 and BANETO_HasBuff("player",32216) and UnitLevel("player") >= 5 then
            BANETO_CastSpell(victoryrush)
        elseif BANETO_UnitHealth("target") < 20 and UnitPower("player") >= 20 and BANETO_IsSpellKnown(executeA) and BANETO_IsSpellUsable(executeA) and (UnitLevel("player") >= 10 or BANETO_ER_EXECUTE_QUEST) then
                BANETO_CastSpell(executeA)
        elseif BANETO_IsSpellKnown(colossalSmash) and (not BANETO_WARRIOR_COLOSSALSMASH_DELAY or BANETO_WARRIOR_COLOSSALSMASH_DELAY < GetTime()) and BANETO_IsSpellUsable(colossalSmash) and not BANETO_IsSpellOnCooldown(colossalSmash) and UnitLevel("player") >= 19 and not BANETO_HasDebuff("target",colossalSmash)  then
