function _G.BANETO_IsUnitQuestTarget(unit)
    local id = BANETO_ObjectId(unit)
    if BANETO_DEFINED_TARGET_IDS and #BANETO_DEFINED_TARGET_IDS then
        for i=1, #BANETO_DEFINED_TARGET_IDS do
            local wantedid = BANETO_DEFINED_TARGET_IDS[i][1]
            if wantedid == id then
                return true
            end
        end
    end
end
