function _G.BANETO_SCANQUEST(xCord,yCord,zCord,radius)
	if Unlocker("LUA")  then
		local objects = BANETO_GetObjctsTkr()
		t = {}
        local playerX,playerY,playerZ = BANETO_ObjectPosition("player")
		for i = 1,#objects do
			local object = objects[i]
			local xSpot,ySpot,zSpot = xCord,yCord,zCord
            --BANETO_PrintBambo("SCAN QUEST A")
			if object and not BANETO_TARGET and BANETO_IsUnitQuestTarget(object) and (BANETO_UnitHealth(object) > 0 or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GatherObject") and BANETO_IsUnitOnMesh(object) then
				--BANETO_PrintBambo("SCAN QUEST B: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))

                local x,y,z =  BANETO_ObjectPosition(object)
				if z and playerZ >= z then
					zDistance = playerZ - z
				elseif z and  playerZ < z then
					zDistance = z - playerZ
				end
				if zDistance and zDistance < 20 then
					--BANETO_PrintBambo("SCAN QUEST C: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                    if  radius and not UnitIsPlayer(object) and (not BANETO_BLOCK_SCANS or BANETO_BLOCK_SCANS < GetTime()) and BANETO_GetDistance3D(x,y,z,xSpot,ySpot,zSpot) and BANETO_GetDistance3D(x,y,z,xSpot,ySpot,zSpot) < radius then
                        --BANETO_PrintBambo("SCAN QUEST C1: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                        if not IsUnitBlacklisted(object) then
                            --BANETO_PrintBambo("SCAN QUEST C2: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                            --BANETO_PrintBambo("SCAN QUEST D: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                            if (UnitAffectingCombat(object) == false or _G.BANETO_ALLOWSCAN_COMBATMOBS) or OZ_RAREFARM_QUESTSCAN then
                                --BANETO_PrintBambo("SCAN QUEST E: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                                if BANETO_IsPetLuabox(object) == false then
                                    --BANETO_PrintBambo("SCAN QUEST F: " .. BANETO_ObjectName(object) .. " with GUID "..UnitGUID(object))
                                    local distance = GetDistanceBetweenObjects("player", object)
                                    --BANETO_PrintBambo("Added Mob to SCANQUEST List: ".. BANETO_ObjectName(object) .. " with distance "..distance)
                                    table.insert(t, { object, distance })
                                end
                            end
                        end
                    end
				end
			end
		end
	end

	if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if t[1] then
		--[[ ewtPath = nil --BUGGY?s!!. ewt pathing stop? --]]
		return t[1][1]
	end

end

function _G.BANETO_LoadingScreenStart()
    BANETO_StopMovement();
    BANETO_DelayStateTick(12);
    BANETO_DelayMeshPathingNoOverride(12);
    BANETO_Wmb_StuckTick = 0;
    BANETO_WMB_STUCKPADDLE = nil;
    waPath = nil;
    flyingPath = nil;
    BANETO_LUABOX_DESTINATION = nil;
    BANETO_UNSTUCK_ROUTE_ISACTIVE = nil;
    unstuckRouteIndex = nil;
    BANETO_PrintBambo("Loadingscreen start");
end

function _G.BANETO_LoadingScreenEnd()
    C_Timer.NewTicker(1,function()
        if BANETO_IsRunning() then
            BANETO_StopMovement();
            BANETO_DelayStateTick(2);
            BANETO_DelayMeshPathingNoOverride(5);
            BANETO_Wmb_StuckTick = 0;
            BANETO_WMB_STUCKPADDLE = nil;
            waPath = nil;
            flyingPath = nil;
            BANETO_LUABOX_DESTINATION = nil;
            BANETO_PrintBambo("Loadingscreen end");
        end
    end,3)
end

function _G.BANETO_GetQuestStepProgression(questId,step)
    local questInfo = C_QuestLog.GetQuestObjectives(questId)
    if questInfo then
        return questInfo[step]["fulfilled"]
    end
end

function _G.BANETO_UnitManaPercent(unit)
	local _,_,class = UnitClass("player")
    if class == 4 then
        return UnitPower(unit,3)
    end
    if class == 1 or class == 3 or class == 6 or class == 12 then
        return 100
    else
        return (UnitPower(unit,0)/UnitPowerMax(unit,0))*100
    end
end


