function _G.BANETO_WaUnstucking()
    local movementDebuff1 = 321633
    if BANETO_HasDebuff("player",movementDebuff1) then
        return false
    end
    if IsFlying() or  BANETO_DEFINED_PROFILE_TYPE == "Rotation" or BANETO_EXECUTE_FLY_ASCEND or BANETO_IsFlyingAscendNeeded() then
        BANETO_Wmb_StuckTick = 0
        return false
    end
    local neededVigor = BANETO_SETTING_VIGORWAIT
    if neededVigor == nil then
        neededVigor = 3
    end
    if not BANETO_Wmb_LastPos_Delay or BANETO_Wmb_LastPos_Delay < GetTime() then
        --BANETO_PrintBambo("unstuckWmbTick")
        BANETO_Wmb_LastPos_Delay = GetTime()+1
        if not BANETO_Wmb_LastPos then
            BANETO_Wmb_LastPos = { }
            local x,y,z = BANETO_ObjectPosition("player")
            table.insert(BANETO_Wmb_LastPos,x)
            table.insert(BANETO_Wmb_LastPos,y)
            table.insert(BANETO_Wmb_LastPos,z)
        else
            local x,y,z = BANETO_ObjectPosition("player")
            local distance = BANETO_GetDistance3D(x,y,z,BANETO_Wmb_LastPos[1],BANETO_Wmb_LastPos[2],BANETO_Wmb_LastPos[3])
            if distance and distance < 2 then
                if not BANETO_Wmb_StuckTick then
                    BANETO_Wmb_StuckTick = 0
                end
                BANETO_Wmb_StuckTick = BANETO_Wmb_StuckTick+1
                BANETO_BLOCK_PATH_ADJUSTION = GetTime()+10
            else
                BANETO_Wmb_LastPos = nil
                BANETO_Wmb_StuckTick = 0
                if BANETO_WMB_UNSTUCK_STRAFEBACK then
                    MoveBackwardStop()
                    BANETO_WMB_UNSTUCK_STRAFEBACK = nil
                end
            end
        end
    end
    --BANETO_PrintBambo("unstuck WA A")
    if BANETO_Wmb_StuckTick and BANETO_Wmb_StuckTick >= 2 and (not BANETO_EMERGENCY_STUCK_HS_LASTUSE or BANETO_EMERGENCY_STUCK_HS_LASTUSE < GetTime()) then
        --BANETO_PrintBambo("unstuck WA B")
        if (not BANETO_Wmb_JumpDelay or BANETO_Wmb_JumpDelay < GetTime())  and not UnitCastingInfo("player") and BANETO_Wmb_StuckTick < 5 and BANETO_State ~= "FIGHTING" and not UnitCastingInfo("player") and not IsFlying() then
            --BANETO_PrintBambo("unstuck WA C")
            BANETO_Wmb_JumpDelay = GetTime()+0.2
            if not BANETO_UNSTUCKJUMPDELAYER or BANETO_UNSTUCKJUMPDELAYER < GetTime() then
                --BANETO_PrintBambo("unstuck WA D")
                local speed = BANETO_GetUnitSpeed("player")
                if BANETO_IsDragonRiding() and speed > 0 then
                    if not dragonRidingGroundStrafer or dragonRidingGroundStrafer < GetTime() then
                        if not dragonRidingGroundStraferLastLeft then
                            BANETO_StrafeLeftStart()
                            C_Timer.After(1,BANETO_StrafeLeftStop)
                            BANETO_PrintState("Dragonriding ground unstuck left.")
                            dragonRidingGroundStraferLastLeft = true
                        else
                            BANETO_StrafeRightStart()
                            C_Timer.After(1,BANETO_StrafeRightStop)
                            BANETO_PrintState("Dragonriding ground unstuck right.")
                            dragonRidingGroundStraferLastLeft = nil
                            dragonRidingGroundStrafer = GetTime()+15
                        end
                        return false
                    end
                elseif not BANETO_IsDragonRiding() then
                    BANETO_JumpOrAscendStart()
                    BANETO_GroundPathDeleter()
                end
                BANETO_UNSTUCKJUMPDELAYER = GetTime()+2
            end
            BANETO_BLOCK_PATH_ADJUSTION = GetTime()+50
            tryX = nil
            xNova = nil
            xBackpaddle = nil
            baneto_SlopeJumperDelay=GetTime()+15
            if not BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST then
                BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST = 1
            else
                BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST=BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST+1
                if BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST > 2 and not BANETO_TARGET and (BANETO_State == "GRIND" or BANETO_State == "FISHING-SPOT" or BANETO_State == "GATHER") and not _G.BANETO_DO_NOT_SKIP_SPOTS_WHEN_STUCK then
                    local skippedIndex = swarmFishingIndex or centerIndex
                    if not skippedIndex then
                        skippedIndex = 1
                    end
                    BANETO_PrintState("Skipping center index " .. skippedIndex .. " due to stuck!")
                    if BANETO_IsDragonRiding() then
                        DRAGONRIDING_FORCEFLY = true
                    end
                    if BANETO_State == "FISHING-SPOT" then
                        swarmFishingIndex = swarmFishingIndex + 1
                        BANETO_LUABOX_TARGETSTICK=true
                        ewtPathSwitch = true
                        if swarmFishingIndex > #BANETO_GetDefinedCenters() then
                            swarmFishingIndex = 1
                        end
                        BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST = nil
                    else
                        centerIndex = centerIndex + 1
                        BANETO_LUABOX_TARGETSTICK=true
                        ewtPathSwitch = true
                        if centerIndex > #BANETO_GetDefinedCenters() then
                            centerIndex = 1
                        end
                        BANETO_STUCK_JUMPS_FOR_CENTER_INDEX_BLACKLIST = nil
                    end

                end
            end
        end
        --BANETO_PrintBambo("unstuck WA E")
        if BANETO_Wmb_StuckTick >= 5 and (not BANETO_IsDragonRiding() or BANETO_GetCurrentVigor() >= neededVigor) then
            --BANETO_PrintBambo("unstuck WA F")
            if not BANETO_WMB_STUCKPADDLE and (not BANETO_WMB_STUCKPADDLE_DELAY or BANETO_WMB_STUCKPADDLE_DELAY < GetTime()) then
                --BANETO_PrintBambo("unstuck WA G")
                BANETO_WMB_STUCKPADDLE = true
                tryX = nil
                BANETO_WMB_STUCKPADDLE_DELAY = GetTime()+55
                BANETO_BLOCK_PATH_ADJUSTION = GetTime()+50

                if BANETO_IsFollowerDungeonProfileLoaded() and BANETO_GetState() == "GRIND" then
                    _G.followerModeDelay = GetTime()+10
                    if BANETO_HasBuff("player",426756) then
                        BANETO_CastSpell(426756,true)
                    end
                end
            end
        end

        local class,_,_ = UnitClass("player")
        local travel = 783
        if BANETO_Wmb_StuckTick >= 3 and class == 11 and BANETO_HasBuff("player",travel) and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) then
            CancelShapeshift()
            BANETO_PrintState("Baneto seems to be stuck - cancel shapeshift and blocking shapeshift for some seconds.")
            BANETO_Wmb_StuckTick = 0
            waPath = nil
            if BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true then
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+30
            else
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+20
            end
        end

        if BANETO_Wmb_StuckTick >= 3 and IsMounted() and (not BANETO_IsDragonRiding() or BANETO_GetCurrentVigor() >= neededVigor) and (not BANETO_STOPMOUNTBECAUSEUNSTUCK or BANETO_STOPMOUNTBECAUSEUNSTUCK < GetTime()) then
            BANETO_Dismount()
            BANETO_PrintState("Baneto seems to be stuck - dismounting and blocking mounting for some seconds.")
            BANETO_Wmb_StuckTick = 0
            waPath = nil
            if BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true then
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+30
            else
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+20
            end
        end
        if BANETO_TARGET and  BANETO_Wmb_StuckTick >= 4 and (BANETO_BLACKLIST_QUEST_TARGETS_IF_STUCK == true or not BANETO_IsUnitQuestTarget(BANETO_TARGET)) and BANETO_State ~= "FIGHTING"  and not BANETO_IsDragonRiding() and (not BANETO_Wmb_StuckBlacklistDelay or BANETO_Wmb_StuckBlacklistDelay < GetTime()) then
            BANETO_PrintState("Baneto seems to be stuck - blacklisting mob guid. B")
            BANETO_Wmb_StuckBlacklistDelay = GetTime()+5
            if BANETO_GetState() == "FISHING-SPOT" then
                BANETO_PrintWarning("Swarm landing position was bad, trying to blacklist that landing position before having to blaclist the swarm.")
                BANETO_BlacklistSwarmLanding()
            else
                BANETO_AddMobToGuidBlacklist(BANETO_TARGET,"Stuck")
            end
            BANETO_TARGET = nil
            ClearTarget()
            BANETO_Wmb_StuckTick = 0
            waPath = nil
            if BANETO_State == "GATHER" then
                local x,y,z = BANETO_ObjectPosition("player")
                BANETO_GATHER_TARGET_COORDS = { x,y,z }
            end
        end
        local startTimeHs, durationHs, enableHs = GetItemCooldown(6948)
        if BANETO_Wmb_StuckTick >= 7  and not BANETO_IsDeadOrGhost() and (not BANETO_IsDragonRiding() or BANETO_GetCurrentVigor() >= neededVigor) and not UnitAffectingCombat("player") and BANETO_SETTING_USEHS_STUCK and BANETO_SETTING_USEHS_STUCK == true and durationHs and durationHs == 0 then
            BANETO_StopMovement()
            BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+13
            BANETO_DELAY_MESHPATHING = GetTime()+13
            BANETO_WMB_UNSTUCK_STRAFE = nil
            BANETO_UNSTUCK_HEARTHSTONE = true
        end

        if BANETO_Wmb_StuckTick >= 15 and BANETO_IsFollowerDungeonProfileLoaded() and (not BANETO_IsDragonRiding() or BANETO_GetCurrentVigor() >= neededVigor) then
            if BANETO_SETTING_PUSH_STUCK and BANETO_SETTING_PUSH_STUCK == true then
                BANETO_PushNotification("Stuck")
            end
            BANETO_Wmb_StuckTick = 0
            BANETO_WMB_STUCKPADDLE_DELAY = GetTime()
            BANETO_CallFullStuckMethod()
            ARCH_X,ARCH_Y,ARCH_Z = nil,nil,nil
            BANETO_DiscordSendStuck()
            BANETO_PrintError("Completely stuck. Are you on mesh? Report with screenshot or video pls. Try to go back where your char was able to move")
        end
    elseif BANETO_WMB_UNSTUCK_STRAFE and BANETO_WMB_UNSTUCK_STRAFE == "LEFT" then
        StrafeLeftStop()
    elseif BANETO_WMB_UNSTUCK_STRAFE and BANETO_WMB_UNSTUCK_STRAFE == "RIGHT" then
        StrafeRightStop()
        BANETO_WMB_UNSTUCK_STRAFE = nil
    end
end

