function _G.BANETO_SCAN_BGASSIST()
	if Unlocker("LUA") then
		local xCord,yCord,zCord = BANETO_ObjectPosition("player")
		local radius = 70
		local objects = BANETO_OBJTS_TKR_ONLYPLAYERS
		t = {}
		for i = 1,#objects do
			local object = objects[i]
			local xSpot,ySpot,zSpot = xCord,yCord,zCord
			local x,y,z =  BANETO_ObjectPosition(object)
			if  ObjectType(object) == 6
					and UnlockedTargetHealth(object) > 0  and BANETO_IsUnitOnMesh(object)
					and (UnlockedTargetReaction(object) == 4 or UnlockedTargetReaction(object) == 2 )
					and UnlockedTargetCreatureType(object) ~= "Critter" and UnlockedTargetCreatureType(object) ~= "Wild Pet"  and UnlockedTargetCreatureType(object) ~= "å°å¨ç©"  and UnlockedTargetCreatureType(object) ~= "Tier" and UnlockedTargetCreatureType(object) ~= "Totem" and UnlockedUnitAffectingCombat(object) and UnlockedTargetClassification(object) ~= "elite" and UnitIsPlayer(object)  then
                    if BANETO_GetDistance3D(x,y,z,xSpot,ySpot,zSpot) < radius and not IsUnitBlacklisted(object) then
                        if not BANETO_TARGET then
                            --[[ BANETO_StopMovement() --]]
                            if BANETO_IsPetLuabox(object) == false then
                                table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
                            end
                        end
                    end
			end
		end
	end

	if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
	if t[1] then
		--[[ ewtPath = nil --BUGGY? ewt pathing stop? --]]
		return t[1][1]
	end
end

