		return t[1][1]
	end

end

function _G.BANETO_ObjectPosition(object)
    if not object then
        return
    end
    if UnitInVehicle("player") and type(object) == "string" then
        local lowerArg = string.lower(object)
        if lowerArg == "player" then
            object = "vehicle"
        end
    end
    local x,y,z = ObjectPosition(object)
    if x and y and z and object then
        if (x < 0 and x > 0) then
            BANETO_PrintBambo("OBJECT POS X ERROR -NAND!!!!!!!")
            return false
        end
        if (y < 0 and y > 0) then
            BANETO_PrintBambo("OBJECT POS Y ERROR -NAND!!!!!!!")
            return false
        end
        if (z < 0 and z > 0) then
            BANETO_PrintBambo("OBJECT POS Z ERROR -NAND!!!!!!!")
            return false
        end
        if type(x) == "number" and type(y) == "number" and type(z) == "number" then
            return x,y,z
        end
    end
end

function _G.BANETO_GetPointRightOfUsWithDistance(distance)
	if Unlocker("LUA") then
		local x,y,z = BANETO_ObjectPosition("player")
		local facing;
		local facingold = BANETO_GetObjectFacing("player")
        if facingold >= math.pi/2 then
            facing = facingold - math.pi/2
        end
        if facingold < math.pi/2 then
            facing = facingold + 3*math.pi/2
        end
		if facing then
            if 0 < facing and facing <= math.pi/2 then
                local alpha = (90-(facing/(math.pi/2))*90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi/2 < facing and facing <= math.pi then
                local alpha = ((facing/(math.pi))*180-90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi < facing and facing <= 3*math.pi/2 then
                local alpha = (270-(facing/(3*math.pi/2))*270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y - b
                return xNew,yNew,z
            elseif 3*math.pi/2 < facing and facing <= 2*math.pi then
                local alpha = ((facing/(2*math.pi))*360-270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y - b
                return xNew,yNew,z
            end
        end
	end
end

function _G.BANETO_GetPointLeftOfUsWithDistance(distance)
	if Unlocker("LUA") then
		local x,y,z = BANETO_ObjectPosition("player")
		local facing;
		local facingold = BANETO_GetObjectFacing("player")
        if facingold <= 3*math.pi/2 then
            facing = facingold + math.pi/2
        end
        if facingold > 3*math.pi/2 then
            facing = facingold - 3*math.pi/2
        end
		if facing then
            if 0 < facing and facing <= math.pi/2 then
                local alpha = (90-(facing/(math.pi/2))*90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi/2 < facing and facing <= math.pi then
                local alpha = ((facing/(math.pi))*180-90)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y + b
                return xNew,yNew,z
            elseif math.pi < facing and facing <= 3*math.pi/2 then
                local alpha = (270-(facing/(3*math.pi/2))*270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x - a
                local yNew = y - b
                return xNew,yNew,z
            elseif 3*math.pi/2 < facing and facing <= 2*math.pi then
                local alpha = ((facing/(2*math.pi))*360-270)*math.pi/180
                local a = math.sin(alpha)*distance
                local b = math.cos(alpha)*distance
                local xNew = x + a
                local yNew = y - b
                return xNew,yNew,z
            end
        end
	end
end


