function _G.BANETO_GetFacingValue(xMob,yMob,zMob)
	if xMob and yMob and zMob then
		local xPla, yPla, zPla = BANETO_ObjectPosition("player")
        if xPla then
            local a = yMob - yPla
            local b = xMob - xPla

            if a < 0 and b > 0 then
                local value = ((270 + math.atan(b/-a)*180/math.pi)/360)*(2*math.pi)
                return value
            elseif a < 0 and b < 0 then
                local value = ((270 - math.atan(b/a)*180/math.pi)/360)*(2*math.pi)
                return value
            elseif a > 0 and b < 0 then
                local value = ((90 + math.atan(-b/a)*180/math.pi)/360)*(2*math.pi)
                return value
            elseif a > 0 and b > 0 then
                local value = ((90 - math.atan(b/a)*180/math.pi)/360)*(2*math.pi)
                return value
            end
         end
	end
end

