function _G.BANETO_PetBattleLogic()
    --BANETO_PrintBambo("pet battle A")
    local selectedAction = C_PetBattles.GetSelectedAction()
    local activePetIndex = C_PetBattles.GetActivePet(1)
    local activePetHp = (C_PetBattles.GetHealth(1,activePetIndex)/C_PetBattles.GetMaxHealth(1,activePetIndex))*100
    --BANETO_PrintBambo("pet hp pecent: "..activePetHp)
    if not selectedAction then
        BANETO_TARGET = nil
        BANETO_UpdateLastHardware()
        if C_PetBattles.ShouldShowPetSelect() then
            local swap = 1
            if C_PetBattles.CanPetSwapIn(1) then
                BANETO_PrintBambo("Change pet logic 1")
                swap = 1
            elseif C_PetBattles.CanPetSwapIn(2) then
                BANETO_PrintBambo("Change pet logic 2")
                swap = 2
            elseif C_PetBattles.CanPetSwapIn(3) then
                 BANETO_PrintBambo("Change pet logic 3")
                 swap = 3
            end
            if _internal.Software() == "tnk" then
                Eval("C_PetBattles.ChangePet("..swap..")","somth")
            elseif _internal.Software() == "nn" then
                Unlock("pcall", C_PetBattles.ChangePet, swap)
            end
            return
        end
        local action;
        local usable1, cd, cdd = C_PetBattles.GetAbilityState(1, activePetIndex, 1)
        local usable2, cd, cdd = C_PetBattles.GetAbilityState(1, activePetIndex, 2)
        local usable3, cd2, cdd2 = C_PetBattles.GetAbilityState(1, activePetIndex, 3)
        if usable3 and usable3 == true and activePetHp < 70 then
            action = 3
        elseif usable2 and usable2 == true and activePetHp < 70 then
            action = 2
        elseif usable1 and usable1 == true then
            action = 1
        else
            BANETO_PrintBambo("Skip turn pet")
            if _internal.Software() == "tnk" then
                Eval("C_PetBattles.SkipTurn()","somth")
            elseif _internal.Software() == "nn" then
                Unlock("pcall", C_PetBattles.SkipTurn, "")
            end
            return
        end
        if _internal.Software() == "tnk" then
            Eval("C_PetBattles.UseAbility("..action..")","somth")
        elseif _internal.Software() == "nn" then
            Unlock("pcall", C_PetBattles.UseAbility, action)
        end
    end
end


