			local x,y,z =  BANETO_ObjectPosition(object)
			if BANETO_IsUnitOnMesh(object) then
				if not BANETO_IsGuidContainedInGuidBlacklist(object) and BANETO_IsBrdHumanoid(object) then
					table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
				end
			end
		end
	elseif Unlocker("EWT") then
		t = {}
		for i = 0,countWMB do
			local object = GetObjectWithIndex(i)
			local x,y,z =  ObjectPosition(object)
			local playerX, playerY, playerZ = ObjectPosition("player")
			if x then
				if GetDistanceBetweenPositions(playerX, playerY, playerZ,x,y,z) < 10 then
					if BANETO_IsUnitOnMesh(object) then
						if not BANETO_IsGuidContainedInGuidBlacklist(ObjectGUID(object)) and BANETO_IsBrdHumanoid(object) then
							table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
