_G.BANETO_LOOT_SCAN_RANGE = 50
_G.BANETO_LOOT_MULTILOOT_RESET_YARDS = 80
function _G.BANETO_SCAN_LOOT()
    if _G.BANETO_MULTILOOT_TIMER and _G.BANETO_MULTILOOT_TIMER > GetTime() then
        t = {}
    end
    if (not _G.BANETO_MULTILOOT_TIMER or _G.BANETO_MULTILOOT_TIMER < GetTime()) and BANETO_SETTING_LOOTING == true then
        local objects = BANETO_OBJTS_TKR_ONLYUNITS
        t = {}
        local currentIndex = centerIndex or 1
        local xSpot,ySpot,zSpot,radiusSpot;
        if BANETO_GetDefinedCenters()[currentIndex] and BANETO_GetDefinedCenters()[currentIndex][1] then
            xSpot,ySpot,zSpot,radiusSpot = BANETO_GetDefinedCenters()[currentIndex][1],BANETO_GetDefinedCenters()[currentIndex][2],BANETO_GetDefinedCenters()[currentIndex][3],BANETO_GetDefinedCenters()[currentIndex][4]
        end
        for i = 1,#objects do
            local object = objects[i]
            if  ObjectLootable(object) then
                if not IsUnitInBlacklistArea(object) and not BANETO_IsGuidContainedInGuidBlacklist(object) then
                    local distance = GetDistanceBetweenObjects("player", object)
                    if (distance and distance < _G.BANETO_LOOT_SCAN_RANGE)  or (BANETO_TARGET and object == BANETO_TARGET) then
                        if not _G.BANETO_LOOT_SCAN_ONLY_SPOTS or (BANETO_TARGET and BANETO_TARGET == object) then
                            table.insert(t, { object, distance })
                        elseif xSpot then
                            local xLoot,yLoot,zLoot = BANETO_ObjectPosition(object)
                            local distanceLoot = BANETO_GetDistance3D(xLoot,yLoot,zLoot,xSpot,ySpot,zSpot)
                            if xLoot and distanceLoot<radiusSpot then
                                table.insert(t, { object, distance })
                            end
                        end
                    end
                end
            end
        end
        if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
        if t[1] then
            return t[1][1]
        end
    end
end

