function _internal.BANETO_WqmLoadProfile()
    local next = next

    -- We set the global variable needed for World Quests support
    BANETO_RETAIL_WQUEST = true

    -- We check that the world quest table isn't empty
    if BANETO_WORLD_QUESTS_TABLE and (next(BANETO_WORLD_QUESTS_TABLE) ~= nil) then
        local closestQuestID = nil
        local closestQuestDistance = nil
        for questID,value in pairs(BANETO_WORLD_QUESTS_TABLE) do
            local mapID = C_TaskQuest.GetQuestZoneID(questID)
            local questLocationX, questLocationY = C_TaskQuest.GetQuestLocation(questID, mapID)
            local questVector = CreateVector2D(questLocationX, questLocationY)
            local _, world = C_Map.GetWorldPosFromMapPos(mapID, questVector)
            local questWorldX, questWorldY = world:GetXY()
            local closestX,closestY,closestZ = 0,0,0
            local playerX,playerY,playerZ = BANETO_ObjectPosition('player')
            if Unlocker("LUA") then
                closestX,closestY,closestZ = questWorldX, questWorldY, playerZ
            end
            local questDistance = BANETO_GetDistance3D(PlayerX,PlayerY,PlayerZ,closestX,closestY,closestZ)
            if not closestQuestDistance or questDistance < closestQuestDistance then
                closestQuestID = questID
                closestQuestDistance = questDistance
            end
        end
        -- Following call should be used once the files are uploaded to Baneto Server
        --_internal.BANETO_RequestWqProfile(closestQuestID)

        -- Following call is to load a file from Baneto's server
        local profileName = 'OZ_WQ_' .. closestQuestID
        --_internal.requestFile(profileName)
        --BANETO_PrintState("[WQM] Load wq profile: " .. profileName)

        -- following call is to load a file from OZ server
        local url1 = "https://onezero-profiles.com/oz/src/WQ/"..profileName..".lua"
        BANETO_PrintState("Loading wqm profiles: " ..profileName)
        LOADED_FIRST_PROFILE_INIT = true
        BANETO_ClearProfileData()
        HttpRequestCustom(url1)

        -- We remove the quest from the world quest from the BANETO_WORLD_QUESTS_TABLE
        BANETO_WORLD_QUESTS_TABLE[closestQuestID] = nil

        if not BANETO_WAITWQM_REQUEST then
            BANETO_WAITWQM_REQUEST = true
        end
    else
        -- If the world quest table is empty, we call back the world quest manager setup to try to find other world quests
        BANETO_WqmInit()
    end
end


