    local SL_ID = 1550
    local questRequiredTime = 30
    FACTION_ITEMS_MAPPING = {['Ascended']=1804, ['Undying Army']=1805, ['Wild Hunt']=1806, ['Court of Harvesters']=1807}
    FACTION_MAPPING = {['Ascended']=2407, ['Undying Army']=2410, ['Wild Hunt']=2465, ['Court of Harvesters']=2413}
    ANIMA_ITEMS_IDS = {
        [181646]=true,[183723]=true,[181552]=true,[184764]=true,[181478]=true,[184763]=true,[184315]=true,[181743]=true,
        [184379]=true,[181650]=true,[184380]=true,[181549]=true,[184149]=true,[181648]=true,[184147]=true,[181477]=true,
        [184381]=true,[184773]=true,[181545]=true,[184150]=true,[184374]=true,[181541]=true,[184768]=true,[181368]=true,
        [184766]=true,[184363]=true,[181548]=true,[184383]=true,[181645]=true,[184294]=true,[184286]=true,[184378]=true,
        [181745]=true,[184777]=true,[184767]=true,[184384]=true,[181550]=true,[181377]=true,[184774]=true,[184382]=true,
        [184305]=true,[181546]=true,[184775]=true,[181547]=true,[181649]=true,[184362]=true,[184772]=true,[181647]=true,
        [181479]=true,[184519]=true,[184776]=true,[184765]=true,[184371]=true
    }
    PET_ITEMS_IDS = {[163036]=true}
    local next = next
    local supported_WQs = {
        [59600]=true,[60476]=true,[60533]=true,[60564]=true,
        [60649]=true,[60842]=true,[59680]=true,[60837]=true,
        [59717]=true,[61337]=true,[61468]=true,[61141]=true,
        [61520]=true,[61549]=true,[61689]=true,[62235]=true,
        [62451]=true,[57205]=true,[58207]=true,[58437]=true,
        [58505]=true,[61189]=true,[61343]=true,[61353]=true,
        [61539]=true,[61545]=true,[57328]=true,[58084]=true,
        [59789]=true,[59808]=true,[59904]=true,[59905]=true,
        [60574]=true,[59578]=true,[61148]=true,[61342]=true,
        [59585]=true,[60958]=true,[62241]=true,[61411]=true,
        [60654]=true,[57650]=true,[61631]=true,[61967]=true,
        [59902]=true,[61540]=true,[61667]=true,[61477]=true,
        [59642]=true,[61303]=true,[60565]=true,[59804]=true,
        [58975]=true,[59705]=true
    }

    -- We retrieve our filters and format the Whitelist and Blacklist if not empty
    local whitelistQuestsIDs = {}
    local blacklistQuestsIDs = {}

    if (next(BANETO_WQM_WHITELISTS) ~= nil) then
        for key,questID in pairs(BANETO_WQM_WHITELISTS) do
            whitelistQuestsIDs[tonumber(questID)] = true
        end
    end

    if (next(BANETO_WQM_BLACKLISTS) ~= nil) then
        for key,questID in pairs(BANETO_WQM_BLACKLISTS) do
            blacklistQuestsIDs[tonumber(questID)] = true
        end
    end

    local factionFilter = {
        ['Ascended']=BANETO_SETTINGS_WQM_FACTION_ASCENDED,
        ['Undying Army']=BANETO_SETTINGS_WQM_FACTION_UNDYING,
        ['Wild Hunt']=BANETO_SETTINGS_WQM_FACTION_WILDHUNT,
        ['Court of Harvesters']=BANETO_SETTINGS_WQM_FACTION_COURT
    }
    local rewardFilter = {
        ['ANIMA']=BANETO_SETTINGS_WQM_REWARD_ANIMA,
        ['GEAR']=BANETO_SETTINGS_WQM_REWARD_GEAR,
        ['GOLD']=BANETO_SETTINGS_WQM_REWARD_GOLD,
        ['PET']=BANETO_SETTINGS_WQM_REWARD_PET,
        ['REPUTATION']=BANETO_SETTINGS_WQM_REWARD_REP,
        ['CONDUIT']=BANETO_SETTINGS_WQM_REWARD_CONDUIT
    }

    -- We retrieve all child maps from SL
    local SLMaps = C_Map.GetMapChildrenInfo(SL_ID, 3)
    BANETO_WORLD_QUESTS_TABLE = {}

    -- for each map, we retrieve its quests and check them on our filters :
    -- is it a world quest ? what are its rewards ? Is it for the right faction ? Is it blacklisted ?
    if SLMaps then
        for SLMapsKey, SLMapsValue in ipairs(SLMaps) do
            local mapQuests = C_TaskQuest.GetQuestsForPlayerByMapID(SLMapsValue["mapID"])
            if not mapQuests and not BANETO_WQM_RECHECK then
                print('[OneZero - WQM] We couldn\'t find any World Quests for one specific area. Let\'s check one more to be sure.')
                BANETO_WQM_RECHECK = true
                BANETO_WqmInit()
            end
            for mapQuestsKey, mapQuestsValue in ipairs(mapQuests) do
                -- We filter on World Quests
                local questID = mapQuestsValue["questId"]
                if C_QuestLog.IsWorldQuest(questID) then
                    -- We filter on time left before expiring
                    local questTimeLeft = C_TaskQuest.GetQuestTimeLeftMinutes(questID)
                    if not questTimeLeft or questTimeLeft > questRequiredTime then
                        questGrade = 0
                        -- We filter on whitelisted quest IDs
                        if (next(whitelistQuestsIDs) ~= nil) then
                            if not whitelistQuestsIDs[questID] then
                                questGrade = questGrade + 1
                            end
                        end
                        -- We Filter on the Blacklisted quest IDs
                        if (next(blacklistQuestsIDs) ~= nil) and questGrade == 0 then
                            if blacklistQuestsIDs[questID] then
                                questGrade = questGrade + 1
                            end
                        end
                        -- We filter on existing quest profiles
                        if questGrade == 0 and not supported_WQs[questID] then
                            questGrade = questGrade + 1
                        end
                        -- We Filter on the REWARD type
                        if (next(rewardFilter) ~= nil) and questGrade == 0 then
                            local numQuestRewards = GetNumQuestLogRewards(questID)
                            local numQuestCurrencies = GetNumQuestLogRewardCurrencies(questID)
                            local isRewardTypePresent = false
                            for rewardKey, rewardValue in pairs(rewardFilter) do
                                if rewardValue then
                                    if rewardKey == 'ANIMA' or rewardKey == 'PET' or rewardKey == 'GEAR' then
                                        if numQuestRewards > 0 then
                                            for i = 1, numQuestRewards do
                                                local _,_,_,_,_,itemID = GetQuestLogRewardInfo(i,questID)
                                                local inventoryType = C_Item.GetItemInventoryTypeByID(itemID)
                                                if rewardKey == 'ANIMA' and ANIMA_ITEMS_IDS[itemID] then
                                                    isRewardTypePresent = true
                                                elseif rewardKey == 'PET' and PET_ITEMS_IDS[itemID] and not isRewardTypePresent then
                                                    isRewardTypePresent = true
                                                elseif rewardKey == 'GEAR' and inventoryType ~= 0 and not isRewardTypePresent then
                                                    isRewardTypePresent = true
                                                elseif rewardKey == 'CONDUIT' and C_Soulbinds.IsItemConduitByItemInfo(itemID) and not isRewardTypePresent then
                                                    isRewardTypePresent = true
                                                end
                                            end
                                        end
                                    elseif rewardKey == 'REPUTATION' and not isRewardTypePresent then
                                        if numQuestCurrencies > 0 then
                                            for i = 1, numQuestCurrencies do
                                                local _,_,_,currencyID = GetQuestLogRewardCurrencyInfo(i, questID)
                                                for reputationKey, reputationValue in pairs(FACTION_ITEMS_MAPPING) do
                                                    if reputationValue == currencyID then
                                                        isRewardTypePresent = true
                                                    end
                                                end
                                            end
                                        end
                                    elseif rewardKey == 'GOLD' and not isRewardTypePresent then
                                        local money = GetQuestLogRewardMoney(questID)
                                        if money > 0 then
                                            isRewardTypePresent = true
                                        end
                                    end
                                end
                            end
                            if not isRewardTypePresent then
                                questGrade = questGrade + 1
                            end
                        else
                            questGrade = questGrade + 1
                        end
                        -- We Filter on the factions filter
                        if (next(factionFilter) ~= nil) and questGrade == 0 then
                            local isFactionPresent = false
                            local _, factionID = C_TaskQuest.GetQuestInfoByQuestID(questID)
                            for factionKey, factionValue in pairs(factionFilter) do
                                if factionValue and not isFactionPresent then
                                    if factionID == FACTION_MAPPING[factionKey] then
                                        isFactionPresent = true
                                    end
                                end
                            end
                            if not isFactionPresent then
                                questGrade = questGrade + 1
                            end
                        else
                            questGrade = questGrade + 1
                        end
                    else
                        questGrade = 1
                        local questName = C_TaskQuest.GetQuestInfoByQuestID(questID)
                        print('Skipping quest : ' .. questName .. ' as it expires in less than 30 minutes')
                    end
                    if questGrade == 0 then
                        BANETO_WORLD_QUESTS_TABLE[questID] = true
                    end
                end
            end
        end
    end

    -- We check the world quests table and end the process if it's empty - if we found some then we load the best profile
    if (next(BANETO_WORLD_QUESTS_TABLE) ~= nil) then
        _internal.BANETO_WqmLoadProfile()
    else
        -- We set the notification message anyway to not have to check multiple times if it's enabled or not
        local pushNotificationsMessage = nil
        if BANETO_SETTINGS_WQM_NEXTPROFILE and (BANETO_SETTINGS_WQM_NEXTPROFILE ~= "nostringinput" and BANETO_SETTINGS_WQM_NEXTPROFILE ~= "") then
            pushNotificationsMessage = "WqmFinishAndProfileLoad"
            BANETO_LoadProfile(BANETO_SETTINGS_WQM_NEXTPROFILE)
        else
            pushNotificationsMessage = "WqmFinishAndStop"
            BANETO_Stop()
        end

        if BANETO_SETTINGS_WQM_PUSHNOT then
            BANETO_PushNotification(pushNotificationsMessage)
        end
    end
end

BANETO_OBJECTS = nil
function _internal.EnumVisibileObjects()
      local objects = {}
      for i = 1, GetObjectCount() do
        local guid = GetObjectWithIndex(i)
        table.insert(objects,guid)
      end
      BANETO_OBJECTS = objects
      countWA = #BANETO_OBJECTS
      BANETO_PrintBambo("Enumerate mobs")
      C_Timer.After(1, _internal.EnumVisibileObjects);
end

_G.BANETO_SKINNING_SCAN_RANGE = 70
function _G.BANETO_SCAN_SKINNING()
	if BANETO_SETTING_SKINNING == true and not _G.BANETO_IS_TREASURE_PROFILE then
		if Unlocker("LUA") then
			local objects = BANETO_OBJTS_TKR_ONLYUNITS
			tS = {}
            local currentIndex = centerIndex or 1
            local xSpot,ySpot,zSpot,radiusSpot;
            if BANETO_GetDefinedCenters()[currentIndex] and BANETO_GetDefinedCenters()[currentIndex][1] then
                xSpot,ySpot,zSpot,radiusSpot = BANETO_GetDefinedCenters()[currentIndex][1],BANETO_GetDefinedCenters()[currentIndex][2],BANETO_GetDefinedCenters()[currentIndex][3],BANETO_GetDefinedCenters()[currentIndex][4]
            end
			for i = 1,#objects do
				local object = objects[i]
				local x,y,z =  BANETO_ObjectPosition(object)
				local distance = GetDistanceBetweenObjects("player",object)
                if BANETO_Object("target") == object then
                    --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: A")
                end
				if distance and distance < _G.BANETO_SKINNING_SCAN_RANGE or (BANETO_TARGET and object == BANETO_TARGET) then
                    if BANETO_Object("target") == object then
                        --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: B")
                        if BANETO_IsGuidContainedInGuidSkinnedlist(object) then
                            --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: Skinned GUID")
                        end
                        if not ObjectSkinnable(object) then
                            --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: not skinnable")
                        end
                        if IsUnitBlacklisted(object) then
                            --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: blacklisted")
                        end
                        if BANETO_IsGuidContainedInGuidBlacklist(object) then
                            --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: blacklisted guid")
                        end
                    end
                    if ObjectSkinnable(object) and UnlockedTargetCreatureType(object) ~= "Not specified" and UnlockedTargetCreatureType(object) ~= "Mechanical" and UnlockedTargetCreatureType(object) ~= "Mechanisch" and not IsUnitBlacklisted(object) and not BANETO_IsGuidContainedInGuidBlacklist(object)  and (BANETO_IsGuidContainedInGuidPulledlist(object) or BANETO_SETTING_ONLYSKINOWNMOBS == false) and not BANETO_IsGuidContainedInGuidSkinnedlist(object)   then
                        if BANETO_Object("target") == object then
                            --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: C")
                        end
                        if not _G.BANETO_SKINNING_SCAN_ONLY_SPOTS or (BANETO_TARGET and BANETO_TARGET == object) then
                            table.insert(tS, { object, GetDistanceBetweenObjects("player", object) })
                        elseif xSpot then
                            local xLoot,yLoot,zLoot = BANETO_ObjectPosition(object)
                            local distanceLoot = BANETO_GetDistance3D(xLoot,yLoot,zLoot,xSpot,ySpot,zSpot)
                            if BANETO_Object("target") == object then
                                --BANETO_PrintBambo("DISTANCE CENTER TO SKINNABLE: "..distanceLoot .. " --- " .. radiusSpot)
                            end
                            if xLoot and distanceLoot<radiusSpot then
                                table.insert(tS, { object, GetDistanceBetweenObjects("player", object) })
                            end
                        end
                    end
				end
			end
		end

		if tS and #tS > 1 then table.sort(tS, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
		if tS and tS[1] then
			return tS[1][1]
		end
	end
end
