function _G.BANETO_IsGatheringNode(objectid)
    if objectid == 170191 then
        return false
    end
    if objectid == 384292 and BANETO_SETTING_SEEDS == true and BANETO_GetBestSeedInBags() then
        return true
    end
    if objectid == 437383 and BANETO_SETTING_SEEDS == true and BANETO_GetBestSeedInBags() then
        return true
    end
    local name = BANETO_GetProfileName()
	if BANETO_SETTING_HERBALISM == true and BANETO_OBJECTS_HERBS[objectid] then
        local tableObjectId, tableObjectSkill, greyValue = BANETO_OBJECTS_HERBS[objectid][1], BANETO_OBJECTS_HERBS[objectid][2], BANETO_OBJECTS_HERBS[objectid][3]
        local currentSkill = 1000
        if tableObjectId == objectid  and currentSkill >= tableObjectSkill then
            if BANETO_SETTING_IGNOREGREYNODES == false or greyValue == nil then
                return true
            elseif BANETO_SETTING_IGNOREGREYNODES == true and currentSkill < greyValue then
                return true
            end
        end
	end
	if BANETO_SETTING_MINING == true and BANETO_OBJECTS_ORES[objectid] then
        local tableObjectId, tableObjectSkill, greyValue = BANETO_OBJECTS_ORES[objectid][1], BANETO_OBJECTS_ORES[objectid][2], BANETO_OBJECTS_ORES[objectid][3]
        local currentSkill = 1000
        if tableObjectId == objectid  and currentSkill >= tableObjectSkill then
            if BANETO_SETTING_IGNOREGREYNODES == false or greyValue == nil then
                return true
            elseif BANETO_SETTING_IGNOREGREYNODES == true and currentSkill < greyValue then
                return true
            end
        end
	end
	if BANETO_SETTING_GATHERCHESTS == true then
        local tableObjectId = BANETO_OBJECTS_CHESTS[objectid]
        if tableObjectId   then
            return true
        end
	end
end

