function _G.BANETO_PrintObjectsAroundMe(radius)
    if not radius then
        radius = 200
    end
    if Unlocker("LUA") then
        local objects = BANETO_GetObjctsTkr()
        for i = 1,#objects do
            local object = objects[i]
            local name = BANETO_ObjectName(object)
            if not name then
                name = "nameIsNil"
            end
            local id = BANETO_ObjectId(object)
            local distance = GetDistanceBetweenObjects("player",object)
            if distance and distance <= radius then
                if name == "Mailbox" then
                    print("MAILBOX: " .. name .. " ID: " .. id)
                elseif id and name and BANETO_ObjectType(object) == 8 then
                    print("OBJECT: " .. name .. " ID: " .. id)
                elseif id and name and BANETO_ObjectType(object) == 5 then
                    print("UNIT: " .. name .. " ID: " .. id)
                elseif id and name then
                    print("NOTYPE: " .. name .. " ID: " .. id)
                end
            end
        end
    end
end

