function _G.BANETO_TraceLine(x,y,z,XX,YY,ZZ,flags)
    local hitX,hitY,hitZ = TraceLine(x,y,z,XX,YY,ZZ,flags)
    if BANETO_IsJin() then
        if not hitX then
            hitX = false
        end
        if not hitY then
