_G.BANETO_SCAN_GATHER_RANGE = 400
function _G.BANETO_SCAN_GATHERING()
    local foundSomething = false
	if ( BANETO_SETTING_HERBALISM == true or BANETO_SETTING_MINING == true or BANETO_SETTING_GATHERCHESTS == true ) and not _G.BANETO_IS_TREASURE_PROFILE and (not UnitAffectingCombat("player") or BANETO_DEFINED_PROFILE_TYPE ~= "Slavemode") and BANETO_State ~= "GOODS" and BANETO_State ~= "SELL" and BANETO_State ~= "AMMO" and BANETO_State ~= "REPAIR" and BANETO_State ~= "TRAIN" and BANETO_DEFINED_PROFILE_TYPE ~= "Battleground" and BANETO_State ~= "PROFTRAIN" and (not BANETO_GATHER_SCAN_DELAY or BANETO_GATHER_SCAN_DELAY < GetTime()) then
		if Unlocker("LUA") then
		    if BANETO_DEFINED_PROFILE_TYPE == "Slavemode" then
		        _G.BANETO_SCAN_GATHER_RANGE = 45
		    end
			local objects = BANETO_OBJTS_TKR
			tGather = {}
			for i = 1,#objects do
				local object = objects[i]
				local objectID = BANETO_ObjectId(object)
				if object and objectID and (BANETO_ObjectType(object) == 8 or BANETO_IsUnitGatherableMob(object,objectID)) and (BANETO_IsGatheringNode(objectID) or BANETO_IsCustomGatherObject(objectID) or BANETO_IsUnitGatherableMob(object,objectID)) and ((BANETO_IsJin() and Tinkr.GameObjectIsUsable(object,false)) or (_internal.Software() == "nn" and not BANETO_IsJin() and ObjectLootableRaw(object)) or (_internal.Software() == "tnk" and ObjectLootable(object)) or (BANETO_IsUnitGatherableMob(object,objectID) and ObjectSkinnable(object))) then
					local xSpot,ySpot,zSpot = xCord,yCord,zCord
					local x,y,z =  BANETO_ObjectPosition(object)
					local playerX,playerY,playerZ = BANETO_ObjectPosition("player")
                    local scanGatherCounter;
                    if _G.BANETO_SCAN_GATHER_COUNTER then
                        scanGatherCounter = _G.BANETO_SCAN_GATHER_COUNTER[object]
                    end
					if playerZ >= z then
						zDistance = playerZ - z
					elseif playerZ < z then
						zDistance = z - playerZ
					end
					if (zDistance < 35 or (IsFlying() and zDistance < 170 and (not scanGatherCounter or scanGatherCounter < 12) and not BANETO_IsDragonRiding()) or (IsFlying() and (zDistance < 120 or playerZ>z) and BANETO_IsDragonRiding()) ) and not IsUnitBlacklisted(object) and not BANETO_IsGuidContainedInGuidGatherlist(object) then
                        local distance = BANETO_GetDistance3D(x,y,z,playerX,playerY,playerZ)
                        if distance and distance < BANETO_SCAN_GATHER_RANGE then
                            if (objectID ~= 413905 and objectID ~= 413886 and objectID ~= 413895) or (BANETO_SETTING_OVERLOAD_EZMINE and BANETO_SETTING_OVERLOAD_EZMINE == true) then
                                table.insert(tGather, { object, GetDistanceBetweenObjects("player", object) })
                                foundSomething = true
                            end
                        end
					end
				end
			end

		end

		if #tGather > 1 then table.sort(tGather, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
		if tGather[1] then
			return tGather[1][1]
		end
        if not foundSomething or foundSomething == false then
            if IsFlying() then
                BANETO_GATHER_SCAN_DELAY = GetTime()+0.3
            else
                BANETO_GATHER_SCAN_DELAY = GetTime()+0.5
            end

        end
	end
end

