		end

		local currentBlacklistIds = BANETO_DEFINED_BLACKLIST_MOBS
		for i = 1, #BANETO_DEFINED_BLACKLIST_MOBS do
			local blacklistId = BANETO_DEFINED_BLACKLIST_MOBS[i][1]
			if blacklistId == unitId then
				return true
			end
		end
		for i = 1, #BANETO_GLOBAL_BLACKLIST_MOBS do
			local blacklistId = BANETO_GLOBAL_BLACKLIST_MOBS[i][1]
			if blacklistId == unitId then
				return true
