function _G.IsUnitBlacklisted(unit,ignoreAreas)
	if Unlocker("LUA") then
		local unitId = BANETO_ObjectId(unit)
		if unitId == 9238 then
			return true
		end

		local currentBlacklistIds = BANETO_DEFINED_BLACKLIST_MOBS
		for i = 1, #BANETO_DEFINED_BLACKLIST_MOBS do
			local blacklistId = BANETO_DEFINED_BLACKLIST_MOBS[i][1]
			if blacklistId == unitId then
				return true
			end
		end
		for i = 1, #BANETO_GLOBAL_BLACKLIST_MOBS do
			local blacklistId = BANETO_GLOBAL_BLACKLIST_MOBS[i][1]
			if blacklistId == unitId then
				return true
			end
		end
		if BANETO_IsGuidContainedInGuidBlacklist(unit) then
			return true
		end
        if BANETO_IsGuidContainedInGuidPulledlist(unit) and BANETO_State ~= "SKINNING" and BANETO_State ~= "LOOTING"  then
            return true
        end
	end
	if IsUnitInBlacklistArea(unit) and not ignoreAreas then
		return true
	end
end

