function _G.BANETO_IsItemDisenchantBlacklisted(itemid)
	if itemid then
		local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
			itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
			isCraftingReagent = GetItemInfo(itemid)
		if itemType ~= "Armor" and itemid ~= 222486 and itemid ~= 219862 and itemType ~= "Weapon" and itemType ~= "RÃ¼stung" and itemType ~= "Waffe" and itemType ~= "ÐÑÐ¾Ð½Ñ" and itemType ~= "ÐÑÑÐ¶Ð¸Ðµ" and itemid ~= 200946 and itemid ~= 200940 and itemid ~= 200945 and itemid ~= 200941 and itemid ~= 200939 and itemid ~= 200947 and itemid ~= 200942 and itemid ~= 200943 then
			return true
		else
			--[[  USER DO NOT DISENCHANT LISTt --]]
			if BANETO_SETTING_DISENCHANT_DONOTDISENCHANT then
				for i = 1, #BANETO_SETTING_DISENCHANT_DONOTDISENCHANT do
					local itemNameTable = BANETO_SETTING_DISENCHANT_DONOTDISENCHANT[i]
					local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
						itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
						isCraftingReagent = GetItemInfo(itemNameTable)
					local itemName2, itemLink2, itemRarity2, itemLevel2, itemMinLevel2, itemType2, itemSubType2, itemStackCount2,
						itemEquipLoc2, itemIcon2, itemSellPrice2, itemClassID2, itemSubClassID2, bindType2, expacID2, itemSetID2,
						isCraftingReagent2 = GetItemInfo(itemid)
					if itemLink == itemLink2 then
						return true
					end
				end
			end
			--[[  ITEM COLOURS --]]
			local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,
				itemEquipLoc, itemIcon, itemSellPrice, itemClassID, itemSubClassID, bindType, expacID, itemSetID,
				isCraftingReagent = GetItemInfo(itemid)
			--[[  GRAY SELLING --]]
			if itemRarity == 0 then
				return true
			end
			--[[  WHITE SELLING --]]
			if itemRarity == 1 then
				return true
			end
			--[[  GREEN SELLING --]]
			if itemRarity == 2 and BANETO_SETTING_DISENCHANTING_GREEN == false then
				return true
			end
			--[[  BLUE SELLING --]]
			if itemRarity == 3 and BANETO_SETTING_DISENCHANTING_BLUE == false then
				return true
			end
			--[[  PURPLE SELLING --]]
			if itemRarity == 4 and itemid ~= 200946 and itemid ~= 200945 and itemid ~= 200941 and itemid ~= 200939 and itemid ~= 200940 and itemid ~= 200947 and itemid ~= 200942 and itemid ~= 200943 then
				return true
			end
            if itemRarity == 7 then
                return true
            end
		end



	end
end

function _G.BANETO_MarkItemidAsBought(itemid)
	if not BANETO_BOUGHTITEMS then
		BANETO_BOUGHTITEMS = {}
	end
	if #BANETO_BOUGHTITEMS >= 1 then
		for i = 1, #BANETO_BOUGHTITEMS do
			if BANETO_BOUGHTITEMS[i] == itemid then
				return false
			end
		end
	end
	table.insert(BANETO_BOUGHTITEMS,itemid)
end
