		    BANETO_PrintBambo("Item Sell Blacklisted B")
			return true
		end
		--[[ Quest Dwarf Chunk of Boar Meat --]]
		if itemid == 769 and BANETO_PROFILE_NAME == "DunMorogh 1-10" then
		    BANETO_PrintBambo("Item Sell Blacklisted C")
			return true
		end
