		end
		--[[ BANDAGES --]]
		if itemid == 1251 or itemid == 212309 or itemid == 212308 or itemid == 212314 or itemid == 2581 or itemid == 3530 or itemid == 3531 or itemid == 6450 or itemid == 6451  or itemid == 8544 or itemid == 8545  then
		    BANETO_PrintBambo("Item Sell Blacklisted G")
			return true
		end
		--[[ ENCHANTING MATS --]]
		for i = 1, #BANETO_ITEMS_DISENCHANTMATS do
			local item = BANETO_ITEMS_DISENCHANTMATS[i]
			if item == itemid then
				return true
			end
		end

		--[[ BANETO_ITEMS_ARROWS --]]
