function _G.BANETO_UseBandage()
	--[[ BANDAGES --]]
	if BANETO_SETTING_BANDAGES == true then
		if not BAMBO_BandagesInit then
			bandageLinen = GetItemInfo(1251)
			bandageLinenHeavy = GetItemInfo(2581)
			bandageWool = GetItemInfo(3530)
			bandageWoolHeavy = GetItemInfo(3531)
			bandageSilk = GetItemInfo(6450)
			bandageSilkHeavy = GetItemInfo(6451)
			bandageMagecloth = GetItemInfo(8544)
			bandageMageclothHeavy = GetItemInfo(8545)
			bandageRunecloth = GetItemInfo(14529)
			bandageRuneclothHeavy = GetItemInfo(14530)
			BAMBO_BandagesInit = true
		else
			if not BANETO_HasDebuff("player",11196) and not UnitIsDeadOrGhost("player") then
				if not UnitAffectingCombat("player") and BAMBO_BandagesInit == true then
					if BANETO_UnitHealth("player") <= BANETO_SETTING_REGEN_HEALTH then
						if GetItemCount(14530) >= 1 and GetItemCooldown(14530) == 0 then
