function _G.BANETO_UseScrolls()
	if (not BANETO_SCROLL_USAGE_DELAYER or BANETO_SCROLL_USAGE_DELAYER < GetTime()) and (BANETO_SETTING_SCROLLS and BANETO_SETTING_SCROLLS == true) then

		for i=1, #BANETO_ITEMS_SCROLLS["IntScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["IntScrolls"][i][1],BANETO_ITEMS_SCROLLS["IntScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end

		for i=1, #BANETO_ITEMS_SCROLLS["StrengthScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["StrengthScrolls"][i][1],BANETO_ITEMS_SCROLLS["StrengthScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end

		for i=1, #BANETO_ITEMS_SCROLLS["AgilityScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["AgilityScrolls"][i][1],BANETO_ITEMS_SCROLLS["AgilityScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end

		for i=1, #BANETO_ITEMS_SCROLLS["SpiritScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["SpiritScrolls"][i][1],BANETO_ITEMS_SCROLLS["SpiritScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end

		for i=1, #BANETO_ITEMS_SCROLLS["StaminaScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["StaminaScrolls"][i][1],BANETO_ITEMS_SCROLLS["StaminaScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end

		for i=1, #BANETO_ITEMS_SCROLLS["ArmorScrolls"] do
			local scrollId, minLevel = BANETO_ITEMS_SCROLLS["ArmorScrolls"][i][1],BANETO_ITEMS_SCROLLS["ArmorScrolls"][i][2]
			if scrollId and minLevel and UnitLevel("player") >= minLevel and GetItemCount(scrollId) >= 1 then
				BANETO_UseItem(scrollId)
				BANETO_SCROLL_USAGE_DELAYER = GetTime()+1805
				return true
			end
		end
	end
end

local BANETO_WLHEALTHSTONE_USAGE_DELAY = GetTime()
function _G.BANETO_UseWarlockHealthstone()
	if BANETO_WLHEALTHSTONE_USAGE_DELAY < GetTime() and BANETO_ISRUNNING then
		BANETO_WLHEALTHSTONE_USAGE_DELAY = GetTime()+2

		local _,cooldownMinor,_ = GetItemCooldown(5512)
		local _,cooldownLesser,_ = GetItemCooldown(5511)
		if BANETO_UnitHealth("player") <= 35 and GetItemCount(5511) >= 1 and cooldownLesser == 0 then
			BANETO_UseItem(5511,true)
		elseif BANETO_UnitHealth("player") <= 35 and GetItemCount(5512) >= 1 and cooldownMinor == 0 then
			BANETO_UseItem(5512,true)
		end


	end
end


