			end
			--[[ MINOR HEALING --]]
			local _,cooldown,_ = GetItemCooldown(118)
			if BANETO_UnitHealth("player") <= 25 and GetItemCount(118) >= 1 and cooldown == 0 then
				BANETO_UseItem(118,true)
				BANETO_POTION_DELAY = GetTime() + 10
			end
		end

		--[[  Mana pots	 --]]
		if BANETO_SETTING_MANAPOTS == true then
			if BANETO_UnitMana("player") <= 25 then

			--[[ 	if BANETO_UnitMana("player") <= 25 and GetItemCount(13446) > 1 and GetItemCooldown(13446) == 0 then --]]
			--[[ 		RunMacroText('/use Major Mana Potion') --]]
			--[[ 	end --]]
				--[[ Superior Mana Potion --]]
				local _,cooldown,_ = GetItemCooldown(13443)
				if BANETO_UnitMana("player") <= 25 and GetItemCount(13443) >= 1 and cooldown == 0 then
					BANETO_UseItem(13443,true)
					BANETO_POTION_DELAY = GetTime() + 10
				end
				--[[ Greater Mana Potion  --]]
				local _,cooldown,_ = GetItemCooldown(6149)
				if BANETO_UnitMana("player") <= 25 and GetItemCount(6149) >= 1 and cooldown == 0 then
					BANETO_UseItem(6149,true)
					BANETO_POTION_DELAY = GetTime() + 10
				end
				--[[  Mana Potion --]]
				local _,cooldown,_ = GetItemCooldown(3827)
				if BANETO_UnitMana("player") <= 25 and GetItemCount(3827) >= 1 and cooldown == 0 then
					BANETO_UseItem(3827,true)
					BANETO_POTION_DELAY = GetTime() + 10
				end
				--[[  Lesser Mana Potion --]]
				local _,cooldown,_ = GetItemCooldown(3385)
				if BANETO_UnitMana("player") <= 25 and GetItemCount(3385) >= 1 and cooldown == 0 then
					BANETO_UseItem(3385)
					BANETO_POTION_DELAY = GetTime() + 10
				end
				--[[  Minor Mana Potion --]]
				local _,cooldown,_ = GetItemCooldown(2455)
				if BANETO_UnitMana("player") <= 25 and GetItemCount(2455) >= 1 and cooldown == 0 then
					BANETO_UseItem(2455,true)
					BANETO_POTION_DELAY = GetTime() + 10
				end

			end
		end
	end
end

local BANETO_OPEN_ITEM_DELAY = GetTime()
function _G.BANETO_AutoOpenItems()

	if BANETO_OPEN_ITEM_DELAY < GetTime() and not UnitChannelInfo("player") and BANETO_ISRUNNING and BANETO_SETTING_AUTOEOPENITEMS and BANETO_SETTING_AUTOEOPENITEMS == true and not MerchantFrame:IsVisible()  and  (not GuildBankFrame or not GuildBankFrame:IsVisible()) then
		BANETO_OPEN_ITEM_DELAY = GetTime() + 2
        if GetItemCount(217707) and GetItemCount(217707) >= 5 and not UnitAffectingCombat("player") and BANETO_SETTING_AUTOEOPENITEMS and BANETO_SETTING_AUTOEOPENITEMS == true then
            BANETO_UseItem(217707)
            BANETO_PrintState("Auto Combine Imperfect Null Stones: " .. 217707)
            return
        end
		for i=1,#BANETO_ITEMS_AUTOOPEN do
		    local itemid = BANETO_ITEMS_AUTOOPEN[i]
			if GetItemCount(itemid) >= 1 then
				BANETO_UseItem(itemid)
				BANETO_PrintState("Auto Open Item: " .. itemid)
			end
		end
	end
end

function _G.BANETO_HasItem(id)
    return 0 < GetItemCount(id)
end

function _G.BANETO_HasItemToOpen()
    if not IsFlying() and BANETO_GetUnitSpeed("player") == 0 then
        for q = 1, #BANETO_ITEMS_AUTOOPEN do
            local tableId = BANETO_ITEMS_AUTOOPEN[q]
            for i = 0, NUM_BAG_SLOTS+1 do
                for z = 1, GetContainerNumSlots(i) do
                    local id = GetContainerItemID(i, z)
                    if id == tableId and BANETO_SETTING_AUTOEOPENITEMS and BANETO_SETTING_AUTOEOPENITEMS == true then
                        return true
                    end
                end
            end
        end
    end
    if GetItemCount(217707) and GetItemCount(217707) >= 5 and not UnitAffectingCombat("player") and BANETO_SETTING_AUTOEOPENITEMS and BANETO_SETTING_AUTOEOPENITEMS == true then
        return true
    end
end

