function _G.BANETO_DefineCustomTravelVector(x,y,z,mapid,name)

	if not BANETO_CUSTOM_TRAVELPOINTS then
		BANETO_CUSTOM_TRAVELPOINTS = {}
	end
	for i=1, #BANETO_CUSTOM_TRAVELPOINTS do
		local nameTable = BANETO_CUSTOM_TRAVELPOINTS[i][5]
		if name == nameTable then
			BANETO_PrintError("That location name seems to be used already.")
			return
		end
	end


	if #BANETO_CUSTOM_TRAVELPOINTS < 8 then
		table.insert(BANETO_CUSTOM_TRAVELPOINTS,{x,y,z,mapid,name})
		if not yCoordCustomTravel then
			yCoordCustomTravel = -40
		end
		if #BANETO_CUSTOM_TRAVELPOINTS ~= 1 then
			yCoordCustomTravel = yCoordCustomTravel - 20
		end
		local profileName = name
		local BANETO_PROFILES_TRAVELBOATZEP_BUTTON =  CreateFrame("Button", nil, BANETO_SUB_FRAME_TRAVELING)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetPoint("Top", BANETO_SUB_FRAME_TRAVELING, "Topleft", 509, yCoordCustomTravel)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetWidth(185)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetHeight(20)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetNormalFontObject("GameFontNormalSmall")
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetText("|cffC6C5C3" .. profileName)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetFrameLevel(35)
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetScript("OnClick",
			function()
				BANETO_LoadCustomTravelProfile(profileName)
			end
		)
		local htexButtonMain = BANETO_PROFILES_TRAVELBOATZEP_BUTTON:CreateTexture()
		htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
		htexButtonMain:SetAllPoints()
		BANETO_PROFILES_TRAVELBOATZEP_BUTTON:SetHighlightTexture(htexButtonMain)
		BANETO_SaveSettings()
	else
		BANETO_PrintError("More than 8 Spots are currently not supported.")
	end



end


function _G.BANETO_ClearSpellSettingsById(id)
	if #BANETO_SPELL_SETTINGS_TABLE > 1 then
		for i =1,#BANETO_SPELL_SETTINGS_TABLE do
			local tableid = BANETO_SPELL_SETTINGS_TABLE[i][1]
			if tableid == id then
				table.remove(BANETO_SPELL_SETTINGS_TABLE,i)
				return
			end
		end
	end
end

function _G.BANETO_GetUserSettingSpellEnemyHp(spellid)
	if #BANETO_SPELL_SETTINGS_TABLE > 1 then
		for i =1,#BANETO_SPELL_SETTINGS_TABLE do
			local spellidTable = BANETO_SPELL_SETTINGS_TABLE[i][1]
			if spellidTable == spellid then
				local hp = BANETO_SPELL_SETTINGS_TABLE[i][2]
				local mp = BANETO_SPELL_SETTINGS_TABLE[i][3]
				local count = BANETO_SPELL_SETTINGS_TABLE[i][4]
				local state = BANETO_SPELL_SETTINGS_TABLE[i][5]
				if hp then
					return hp
				end
			end
		end
	end
end

