function _G.BANETO_IsSpellBlockedBySettings(spellid)
    if BANETO_GLOBAL_BLACKLIST_SPELLS and #BANETO_GLOBAL_BLACKLIST_SPELLS >= 1 then
        for i=1,#BANETO_GLOBAL_BLACKLIST_SPELLS do
            if spellid == BANETO_GLOBAL_BLACKLIST_SPELLS[i][1] then
                return true
            end
        end
    end
end

function _G.BANETO_SetSpellSetting(id,hp,mp,count,wanted)
	if BANETO_SPELLSETTING_SET_RETAIL_WANTED then
		if not hp then hp = 10 end
		if not mp then mp = 60 end
		if not count then count = 2 end
		if not wanted then wanted = false end
		BANETO_ClearSpellSettingsById(id)
		if not BANETO_SPELL_SETTINGS_TABLE then
			BANETO_SPELL_SETTINGS_TABLE = {}
		else
			table.insert(BANETO_SPELL_SETTINGS_TABLE,{id,hp,mp,count,wanted})
		end

		if id == 3044 then
			if wanted and wanted == true then
				BANETO_SUB_FRAME_CLASSSETTINGS_HUNTER_SPELL_3044:SetChecked(true)
