function _G.BANETO_RepairAllItems()
    if not repairallitemsdelay or repairallitemsdelay < GetTime() then
        repairallitemsdelay = GetTime()+7
        if BANETO_SETTING_REPAIR_GBANK and BANETO_SETTING_REPAIR_GBANK == true then
            C_Timer.After(6,function()
                RepairAllItems(1)
            end)
        else
            C_Timer.After(6,function()
                RepairAllItems()
            end)
        end
    end
end
function _G.BANETO_QuestAcceptLogic()
    if Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0 then
        BANETO_StopMovement()
    elseif Unlocker("EWT") and BANETO_GetUnitSpeed("player") > 0 then
        StopEwtMovement()
    end
