function _G.BANETO_QuestTurninLogic()
    if Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0 then
        BANETO_StopMovement()
    elseif Unlocker("EWT") and BANETO_GetUnitSpeed("player") > 0 then
        StopEwtMovement()
    end
    --[[ NPC INTERACT --]]
    if Unlocker("LUA") and not GossipFrame.GreetingPanel:IsVisible() and not BANETO_QUEST_TURNIN_RETAIL_FIX then
        if BANETO_ObjectForAcceptTurnin and BANETO_ObjectForAcceptTurnin == true and not UnitCastingInfo("player") then
            local object = GetObjectWithId(npcid)
            BANETO_Interact(object)
        elseif not BANETO_ObjectForAcceptTurnin then
            local object = GetObjectWithCoordinates(x, y, z, npcid)
            BANETO_Interact(object)
        end
    elseif Unlocker("EWT") and not GossipFrame.GreetingPanel:IsVisible() and not BANETO_QUEST_TURNIN_RETAIL_FIX then
        if BANETO_ObjectForAcceptTurnin and BANETO_ObjectForAcceptTurnin == true and not UnitCastingInfo("player") then
            local object = GetObjectWithId(npcid)
            ObjectInteract(object)
        elseif not BANETO_ObjectForAcceptTurnin then
            local object = GetObjectWithCoordinates(x, y, z, npcid)
            ObjectInteract(object)
        end
    end
    --[[ UI CLICKS --]]
    if GossipFrame.GreetingPanel:IsVisible() then
        --C_GossipInfo.SelectActiveQuest(1)
    end
    if QuestFrameCompleteButton and QuestFrameCompleteButton:IsVisible() then
        QuestFrameCompleteButton:Click()
    end
    if QuestFrameAcceptButton and QuestFrameAcceptButton:IsVisible() then
        QuestFrameAcceptButton:Click()
    end
    if QuestFrameCompleteQuestButton and QuestFrameCompleteQuestButton:IsVisible() then
        QuestFrameCompleteQuestButton:Click()
    end
    if QuestInfoRewardsFrameQuestInfoItem1:IsVisible() then
        QuestInfoRewardsFrameQuestInfoItem1:Click()
    end
    if QuestFrame.NineSlice and QuestFrame.NineSlice:IsVisible() then
        --SelectActiveQuest(1)
