            CompleteQuest()
        elseif Unlocker("LUA") and _internal.Software() == "nn" then
            Unlock("CompleteQuest","")
        elseif Unlocker("LUA") and _internal.Software() == "tnk" then
            Eval("CompleteQuest()","asdas")
        end
        BANETO_QUEST_TURNIN_RETAIL_FIX = nil
    end
    if not BANETO_QUESTTURNIN_QUESTTITLE_TIMER then
        BANETO_QUESTTURNIN_QUESTTITLE_TIMER = GetTime() + 8
    elseif BANETO_QUESTTURNIN_QUESTTITLE_TIMER < GetTime() then
        QuestFrameCloseButton:Click()
        BANETO_QUESTTURNIN_QUESTTITLE_TIMER = nil
    end


    if BANETO_QUESTTURNIN_QUESTTITLE_TRY and questid then
        SelectActiveQuest(BANETO_QUESTTURNIN_QUESTTITLE_TRY)
        if BANETO_QUESTTURNIN_QUESTTITLE_TRY == 1 then
            if QuestTitleButton1 and QuestTitleButton1:IsVisible() then
                QuestTitleButton1:Click()
            end
            C_GossipInfo.SelectActiveQuest(questid)
            BANETO_QUESTTURNIN_QUESTTITLE_TRY = BANETO_QUESTTURNIN_QUESTTITLE_TRY + 1
        elseif BANETO_QUESTTURNIN_QUESTTITLE_TRY == 2 then
            if QuestTitleButton2 and QuestTitleButton2:IsVisible() then
