        end
    else
        BANETO_QUESTTURNIN_QUESTTITLE_TRY = 1
    end
end

function _G.BANETO_FinishSellingNow()
    BANETO_SELL_DELAY = GetTime()
end

function _G.BANETO_SellItems(forcedsell)
    if not MerchantFrame:IsVisible() then
        BANETO_GossipInkeeper()
    end
    if CanMerchantRepair() and (not BANETO_REPAIRDURINGSELL_DELAY or BANETO_REPAIRDURINGSELL_DELAY < GetTime()) then
        local repairAllCost, canRepair = GetRepairAllCost()
        if repairAllCost < GetMoney() then
            BANETO_RepairAllItems()
            BANETO_REPAIRDURINGSELL_DELAY = GetTime()+30
        end
    end
    if MerchantFrame:IsVisible() and BANETO_SETTING_SELLING_GRAY == true and (not BANETO_SELL_JUNK_DELAY or BANETO_SELL_JUNK_DELAY < GetTime()) and MerchantSellAllJunkButton and MerchantSellAllJunkButton:IsVisible()  and C_MerchantFrame.IsSellAllJunkEnabled() and C_MerchantFrame.GetNumJunkItems() > 0 then
        C_MerchantFrame.SellAllJunkItems()
        BANETO_SELL_JUNK_DELAY = GetTime()+60
        C_Timer.After(1,function()
            C_MerchantFrame.SellAllJunkItems()
        end)
    end

    if MerchantFrame:IsVisible() and (_G.BANETO_VENDOR_NEEDED or BANETO_GetState() == "SLAVE" or BANETO_GOODS_NEEDED or BANETO_AMMO_NEEDED or BANETO_SHFFL_SELL_ENDPRODUCT or _G.BANETO_VISION_TRIGGER_REPAIR or _G.REAPER_ISRUNNING or forcedsell) then
        local moneyBefore = GetMoney()
        for i = 0, NUM_BAG_SLOTS+1 do
            for z = 1, GetContainerNumSlots(i) do
                local id = GetContainerItemID(i, z)
                if (not BANETO_IsItemSellBlacklisted(id) or BANETO_FORCED_ITEMS_FOR_SELL[id]) and not BANETO_IsItemInAlwaysMailList(id) then
                    C_Container.UseContainerItem(i, z)
                end
            end
        end
    end
    if not BANETO_SELL_DELAY and MerchantFrame:IsVisible() then
        BANETO_SELL_DELAY = GetTime()+ 24.00
    end
    if BANETO_SELL_DELAY then
        if BANETO_SELL_DELAY < GetTime() then
            BANETO_LAST_SELL = GetTime()
            _G.BANETO_VENDOR_NEEDED = nil
            BANETO_SELL_DELAY = nil
            _G.BANETO_VISION_TRIGGER_REPAIR = nil
        end
    end
end


function _G.BANETO_LearnSpells()


	if not BANETO_TRAIN_DELAY and BANETO_TRAIN_NEEDED and ClassTrainerFrame:IsVisible() then
		BANETO_TRAIN_DELAY = GetTime()+ 8.00
	end
	if BANETO_TRAIN_DELAY then
		if BANETO_TRAIN_DELAY-6.00 < GetTime()  and BANETO_TRAIN_NEEDED then
			if ClassTrainerFrame:IsVisible() and BANETO_TRAIN_NEEDED then
				for i=1, GetNumTrainerServices() do
					BuyTrainerService(i)
				end
			end
		end

		if BANETO_TRAIN_DELAY < GetTime()  and BANETO_TRAIN_NEEDED then
			BANETO_SetSettingInt("LastTrainerVisitAtLevel",UnitLevel("player"))
			BANETO_TRAIN_NEEDED = nil
			BANETO_TRAIN_DELAY = nil
		end
	end
end

