function _G.BANETO_GetPossibleDisenchantCount()
	local counter = 0
	for i = 0, NUM_BAG_SLOTS+1 do
		for z = 1, GetContainerNumSlots(i) do
			local id = GetContainerItemID(i, z)
			if not BANETO_IsItemDisenchantBlacklisted(id) and id then
				counter = counter+1
			end
		end
	end
	return counter

end

function _G.BANETO_DisenchantItems()
	if not BANETO_DISENCHANT_DELAY then
		BANETO_DISENCHANT_DELAY = GetTime()
	end
	if BANETO_DISENCHANT_DELAY < GetTime() and BANETO_GetUnitSpeed("player") == 0 then
		for i = 0, NUM_BAG_SLOTS+1 do
			for z = 1, GetContainerNumSlots(i) do
				local id = GetContainerItemID(i, z)
				if id and not BANETO_IsItemDisenchantBlacklisted(id) then
					local disenchantSpell = 13262
					if not UnitCastingInfo("player") then
					    BANETO_DISENCHANT_DELAY = GetTime()+5
						BANETO_CastSpell(disenchantSpell,true)
                        BANETO_UseItem(id)
                        return true
					end
				end
			end
		end
	end
end

