function _G.BANETO_BuyPetfood()
	if MerchantFrame:IsVisible() == true and BANETO_GOODS_NEEDED and not BANETO_BOUGHT_PETFOOD then
		for q=1,6 do
			local foodtype = select(q,GetPetFoodTypes())
			if foodtype then
				petFoodTable = BANETO_ITEMS_PETFOOD[foodtype]
			end
			for i = 1, #petFoodTable do
				local petFoodId, petFoodLevel = petFoodTable[i][1],petFoodTable[i][2]
				for k= 1, 45 do
					local merchantLink = GetMerchantItemLink(k)
					local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(petFoodId)
					--[[ print(tablelink) --]]
					if tablelink and merchantLink then
						--[[ print(1) --]]
						if tablelink == merchantLink then
							if not petfoodLvl then petfoodLvl = 1 end
							if petFoodLevel <= UnitLevel("pet") and UnitLevel("pet")-petfoodLvl <= 30 and BANETO_SETTING_HUNTER_PETBUYFOOD and BANETO_SETTING_HUNTER_PETBUYFOOD == true then
								if Unlocker("LUA") then
									__LB__.Unlock(BuyMerchantItem,k, 20*BANETO_SETTING_GOODSAMOUNT_FOOD)
								elseif Unlocker("EWT") then
									BuyMerchantItem(k, 20*BANETO_SETTING_GOODSAMOUNT_FOOD)
								end
								BANETO_PrintState("Buying Pet Food!")
								BANETO_BOUGHT_PETFOOD = true
								return
							end
						end
					end
				end
			end
		end
	end
end

function _G.BANETO_ResetForcedGoods()
    _G.BANETO_GOODS_FORCED=nil
end

function _G.BANETO_BuyGoods()
    BANETO_FOOD_AMOUNT_GLOBAL = nil
    BANETO_DRINK_AMOUNT_GLOBAL = nil
	if not MerchantFrame:IsVisible() then
		BANETO_GossipInkeeper()
	end
	if _G.BANETO_GOODS_FORCED then
        C_Timer.After(15,BANETO_ResetForcedGoods)
    end
	if MerchantFrame:IsVisible() == true and (BANETO_GOODS_NEEDED or BANETO_GetState() == "SLAVE") then
		local drinkAmountInBags = BANETO_GetDrinkAmountInBags()
		if drinkAmountInBags < BANETO_SETTING_GOODSAMOUNT_DRINK*20 then
			for i = 1, #BANETO_ITEMS_DRINK do
				for k= 1, 45 do
					local merchantLink = GetMerchantItemLink(k)
					local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(BANETO_ITEMS_DRINK[i][1])
					if tablelink and merchantLink then
						if tablelink == merchantLink then
							local requiredLevel = BANETO_ITEMS_DRINK[i][2]
							if not requiredLevel then
							    requiredLevel = 1
							end
							if requiredLevel <= UnitLevel("player") or requiredLevel == 1  then
								BANETO_MarkItemidAsBought(BANETO_ITEMS_DRINK[i][1])
                                if _internal.Software() == "tnk" then
                                    Eval("BuyMerchantItem(" .. k .. ", 20)","somth")
                                else
                                    Unlock("BuyMerchantItem",k,20)
                                end
								return
							end
						end
					end
				end
			end
		end

		local foodAmountInBags = BANETO_GetFoodAmountInBags()
		if foodAmountInBags < BANETO_SETTING_GOODSAMOUNT_FOOD*20 then
			for i = 1, #BANETO_ITEMS_FOOD do
				for k= 1, 45 do
					local merchantLink = GetMerchantItemLink(k)
					local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(BANETO_ITEMS_FOOD[i][1])
					--[[ print(tablelink) --]]
					if tablelink and merchantLink then
						--[[ print(1) --]]
						if tablelink == merchantLink then
							local requiredLevel = BANETO_ITEMS_FOOD[i][2]
							if not requiredLevel then
							    requiredLevel = 1
							end
							if requiredLevel <= UnitLevel("player") or  requiredLevel == 1 then
								BANETO_MarkItemidAsBought(BANETO_ITEMS_FOOD[i][1])
                                if _internal.Software() == "tnk" then
                                    Eval("BuyMerchantItem(" .. k .. ", 20)","somth")
                                else
                                    Unlock("BuyMerchantItem",k,20)
                                end
								return
							end
						end
					end
				end
			end
		end
	end

	if not BANETO_BUYGOODS_EXITDELAY and BANETO_GOODS_NEEDED and MerchantFrame:IsVisible() then
		BANETO_BUYGOODS_EXITDELAY = GetTime()+ 10.00
	end

	if 	BANETO_BUYGOODS_EXITDELAY and BANETO_BUYGOODS_EXITDELAY-6 < GetTime() then
 		local _,_,class = UnitClass("player")
		if class == 3 and UnitExists("pet") then
			BANETO_BuyPetfood()
		end
	end

	if BANETO_BUYGOODS_EXITDELAY then
		if BANETO_BUYGOODS_EXITDELAY < GetTime()  and BANETO_GOODS_NEEDED then
			BANETO_GOODS_NEEDED = nil
			BANETO_BUYGOODS_EXITDELAY = nil
		end
	end
end

function _G.BANETO_BuyAmmo()

	if not MerchantFrame:IsVisible() then
		BANETO_GossipInkeeper()
	end

	if MerchantFrame:IsVisible() == true and BANETO_AMMO_NEEDED then
		local ammoAmountInBags = BANETO_GetAmmoAmountInBags()
		if ammoAmountInBags < BANETO_SETTING_HUNTER_AMMO_STACKS*200 then
			if BANETO_SETTING_HUNTER_ARROWS == true then
				for i = 1, #BANETO_ITEMS_ARROWS do
					for k= 1, 45 do
						local merchantLink = GetMerchantItemLink(k)
						local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(BANETO_ITEMS_ARROWS[i][1])
						if tablelink and merchantLink then
							if tablelink == merchantLink then
								local requiredLevel = BANETO_ITEMS_ARROWS[i][2]
								if requiredLevel <= UnitLevel("player") then
									BANETO_MarkItemidAsBought(BANETO_ITEMS_ARROWS[i][1])
									if Unlocker("LUA") then
										Eval("BuyMerchantItem(" .. k .. ", 200)","somth")
									elseif Unlocker("EWT") then
										BuyMerchantItem(k, 200)
									end
									return
								end
							end
						end
					end
				end
			end
			if BANETO_SETTING_HUNTER_BULLETS == true then
				for i = 1, #BANETO_ITEMS_BULLETS do
					for k= 1, 45 do
						local merchantLink = GetMerchantItemLink(k)
						local itemName, tablelink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount, itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(BANETO_ITEMS_BULLETS[i][1])
						if tablelink and merchantLink then
							if tablelink == merchantLink then
								local requiredLevel = BANETO_ITEMS_BULLETS[i][2]
								if requiredLevel <= UnitLevel("player") then
									BANETO_MarkItemidAsBought(BANETO_ITEMS_BULLETS[i][1])
									if Unlocker("LUA") then
										__LB__.Unlock(BuyMerchantItem,k, 200)
									elseif Unlocker("EWT") then
										BuyMerchantItem(k, 200)
									end
									return
								end
							end
						end
					end
				end
			end
		end
	end

	if not BANETO_BUYAMMO_EXITDELAY and BANETO_AMMO_NEEDED and MerchantFrame:IsVisible() then
		BANETO_BUYAMMO_EXITDELAY = GetTime()+ 10.00
	end

	if BANETO_BUYAMMO_EXITDELAY then
		if BANETO_BUYAMMO_EXITDELAY < GetTime()  and BANETO_AMMO_NEEDED then
			BANETO_AMMO_NEEDED = nil
			BANETO_BUYAMMO_EXITDELAY = nil
		end
	end
end



function _G.BANETO_IsEating()
	if BANETO_UnitHealth("player") < 100 and BANETO_State == "REGEN" then
        if BANETO_USED_FOOD_ITEM_TO_REGEN and BANETO_USED_FOOD_ITEM_TO_REGEN == true then
            return true
        end

		local buffs = {29073,29008,28616,26474,26472,26401,26260,25695,25660,24869,24800,24005,22731,18234,18233,18232,
						18231,18230,18229,10257,10256,7737,6410,5007,5005,5004,2639,1131,1129,1127,435,434,433}
		for i = 1, #buffs do
			local buff = buffs[i]
			local hasBuff = BANETO_HasBuff("player",buff)
			if hasBuff == true then
				return true
			end
		end
	end
end

function _G.BANETO_IsDrinking()
	if BANETO_UnitMana("player") < 100 and BANETO_State == "REGEN" then
	    if BANETO_USED_DRINK_ITEM_TO_REGEN and BANETO_USED_DRINK_ITEM_TO_REGEN == true then
	        return true
	    end

		local buffs = {430,431,432,1133,1135,1137,10250,22734,24355,25696,26261,26402,26473,26475,29007}
		for i = 1, #buffs do
			local buff = buffs[i]
			local hasBuff = BANETO_HasBuff("player",buff)
			if hasBuff == true then
				return true
			end
		end
	end
end
