if _internal.Software() == "nn" then
    function _G.FaceDirection(angle,bool)
        if angle and (angle < 0 and angle > 0) then
            BANETO_PrintBambo("FACING ERROR -NAND!!!!!!")
            return false
        end
        if angle and type(angle) == "number"  then
            local currentAngle = BANETO_GetObjectFacing("player")
            local abs = math.abs(currentAngle-angle)
            if angle < 0 then
                BANETO_PrintBambo("Angle is below 0 for facing")
                return false
            end
            if abs and 0.1<abs and not UnitCastingInfo("player") and not UnitCastingInfo("player") and not UnitChannelInfo("player") and not BANETO_IsEating() and not BANETO_IsDrinking() and (not strafeleftdelayer or strafeleftdelayer < GetTime()) then
                SetPlayerFacing(angle)
                if BANETO_IsDragonRiding() then
                    strafeleftdelayer = GetTime()+0.01
                else
                    strafeleftdelayer = GetTime()+0.5
                end
                BANETO_UpdateServerFacing()
            end
        end
    end
end

