function _G.UnitBuffWrapper(unit,spellid)
    local u = BANETO_ObjectToUnit(unit)
    local aura = C_UnitAuras.GetBuffDataByIndex(u,spellid)
    if aura then
        local name = aura.name
        local icon = aura.icon
        local dispelType = aura.dispelName
        local spellId = aura.spellId
        local caster = aura.sourceUnit
        local charges = aura.charges or 1
        return name, icon,charges, dispelType, _, _, _, caster, _, spellId
    end
end
function _G.UnitDebuffWrapper(unit,spellid)
    local u = BANETO_ObjectToUnit(unit)
    local aura = C_UnitAuras.GetDebuffDataByIndex(u,spellid)
    if aura then
        local name = aura.name
        local icon = aura.icon
        local dispelType = aura.dispelName
        local spellId = aura.spellId
        local caster = aura.sourceUnit
        local charges = aura.charges or 1
        return name, icon,charges, dispelType, _, _, _, caster, _, spellId
    end
end
function _G.BANETO_GetBuffDuration(unit,spellid)
	for i = 1, 32 do
		local nameBuffOnPlayer, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, shouldConsolidate, buffOnPlayer  = UnitBuffWrapper(unit, i)
		if buffOnPlayer then
			if buffOnPlayer == spellid then
				return duration
			end
            local spellInfo = C_Spell.GetSpellInfo(spellid)
			if spellInfo and nameBuffOnPlayer == spellInfo.name then
				return duration
			end
		end
	end
end

function _G.BANETO_GetDebuffDuration(unit,spellid)
	for i = 1, 32 do
		local nameBuffOnPlayer, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, buffOnPlayer  = UnitDebuffWrapper(unit, i)
		--[[ print("spell ids "..spellid) --]]
		if buffOnPlayer then
			--[[ print("buffOnPlayer id ".. buffOnPlayer) --]]
			if buffOnPlayer == spellid then
				return duration
			end
			local spellInfo = C_Spell.GetSpellInfo(spellid)
			if spellInfo and nameBuffOnPlayer == spellInfo.name then
				return duration
			end
		end
	end
end

