function _G.BANETO_SetPlayerAnglesLuabox(angle)
    local speed = BANETO_GetUnitSpeed("player")
    local thrillBuff = 377234
    local thrill = C_UnitAuras.GetPlayerAuraBySpellID(thrillBuff)
    if angle and angle > 6.2 then
        angle = 6.2
    end
    if angle and angle < 0 then
        angle = 0
    end
    if angle and BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == true  and (not BANETO_SMOOTHTURN_BLOCK or BANETO_SMOOTHTURN_BLOCK < GetTime()) then
        BANETO_WANTED_ANGLE = angle
        --BANETO_PrintBambo("Facing Smooth: "..angle)
    else
        if (not BANETO_LUABOX_TRYFIXANGLE_DELAY or BANETO_LUABOX_TRYFIXANGLE_DELAY < GetTime()) and angle  and not BANETO_IsEating() and not BANETO_IsDrinking() and (BANETO_State ~= "REGEN" or 0<speed )  then
            local tolerance = 0.05  -- Set your desired tolerance range
            local currentAngle = BANETO_GetObjectFacing("player")
            if math.abs(currentAngle - angle) > tolerance then
                --BANETO_PrintBambo("Facing Snap: "..angle)
                BANETO_LogDragonride("Facing Snap: "..angle)
                if _internal.Software() == "nn" then
                    FaceDirection(angle, true)
                elseif _internal.Software() == "tnk" then
                    SetHeading(angle)
                    -- FaceDirection(angle, true)
                end
            end
            if BANETO_IsDragonRiding() then
                BANETO_LUABOX_TRYFIXANGLE_DELAY = GetTime() + 0.01
            else
                BANETO_LUABOX_TRYFIXANGLE_DELAY = GetTime() + 0.1
            end

        end
    end
end

