function _G.BANETO_GetPlayerCorpsePosition()
	if Unlocker("LUA") then
	    if BANETO_DEFINED_PROFILE_TYPE and BANETO_DEFINED_PROFILE_TYPE == "Dungeon" then
	        return BANETO_DEFINED_ENTRANCE[1][1],BANETO_DEFINED_ENTRANCE[1][2],BANETO_DEFINED_ENTRANCE[1][3]
	    else
	        local tableCorpse;
	        local x,y,z;
	        if _internal.Software() == "tnk" then
	            tableCorpse  = GetCorpseLocation()
	            x,y,z = tableCorpse["x"],tableCorpse["y"],tableCorpse["z"]
	            --BANETO_PrintBambo("x: "..x .. " y: "..y.." z: "..z )
            else
                x,y,z = GetCorpsePosition("player")
            end

            if (x == nil or z == 0) and LAST_KNOWN_X_BEFORE_DEAD then
                if not LAST_KNOWN_X_BEFORE_DEAD_MSG then
                    BANETO_PrintWarning("Corpse location is buggy, using position of death!")
                    LAST_KNOWN_X_BEFORE_DEAD_MSG = true
                end
                x,y,z = LAST_KNOWN_X_BEFORE_DEAD,LAST_KNOWN_Y_BEFORE_DEAD,LAST_KNOWN_Z_BEFORE_DEAD
            end
	        return x,y,z
	    end
	end
end

