       -- load = loadstring(contentPluginsCustomFile,"")
       --load()
        RunScript(contentPluginsCustomFile)
    end
end

function _G.BANETO_IsPlayerBehindTarget()
    if not UnitExists("target") then
        return false
    end
    local playerPositionX, playerPositionY, playerPositionZ = BANETO_ObjectPosition("player")
    local playerRotation = BANETO_GetObjectFacing("player")
    local targetPositionX, targetPositionY, targetPositionZ = BANETO_ObjectPosition("target")
    local targetRotation = BANETO_GetObjectFacing("target")
    local coneFacing;
    if targetRotation > math.pi then
        coneFacing = targetRotation - math.pi
    else
        coneFacing = targetRotation + math.pi
    end
    local a = math.pi/3
    local isInCone = BANETO_IsInsideCone(targetPositionX, targetPositionY, targetPositionZ, playerPositionX, playerPositionY, playerPositionZ, coneFacing, a)
    if not isInCone then
        return false
    else
        return true
    end
end

function _G.BANETO_IsPlayerBehindUnit(unit) --not documented
    if not BANETO_ObjectPosition(unit) then
        return false
    end
    local playerPositionX, playerPositionY, playerPositionZ = BANETO_ObjectPosition("player")
    local playerRotation = BANETO_GetObjectFacing("player")
    local targetPositionX, targetPositionY, targetPositionZ = BANETO_ObjectPosition(unit)
    local targetRotation = BANETO_GetObjectFacing(unit)
    local coneFacing;
    if targetRotation > math.pi then
        coneFacing = targetRotation - math.pi
    else
        coneFacing = targetRotation + math.pi
    end
    local a = math.pi/3
    local isInCone = BANETO_IsInsideCone(targetPositionX, targetPositionY, targetPositionZ, playerPositionX, playerPositionY, playerPositionZ, coneFacing, a)
    if not isInCone then
        return false
    else
        return true
    end
end

function _G.BANETO_IsInsideCone(x,y,z,xX,yY,zZ,f,a)
    if y and yY then
        return math.cos(math.atan2(yY-y,xX-x)-f) > math.cos(a)
    end
end



