function _G.BANETO_CreatePluginCheckbox(name)
    _G["BANETO_PLUGIN_CHECKBOX_"..name] = CreateFrame("CheckButton", "BANETO_PLUGIN_CHECKBOX_"..name, panel_plugins, "ChatConfigCheckButtonTemplate");
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:SetPoint("TOPLEFT", 0, BANETO_PLUGIN_CHECKBOX_Z_AXIS)
    _G["BANETO_PLUGIN_CHECKBOX_"..name].tooltip = name.." will only be executed if this is activated!"
    _G["BANETO_PLUGIN_CHECKBOX_"..name.."Text"]:SetText(name);
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:SetFrameLevel(50)
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:SetScript("OnClick",
    function()
        BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST[name] = _G["BANETO_PLUGIN_CHECKBOX_"..name]:GetChecked()
        BANETO_SaveSettings()
        if not  _G["BANETO_PLUGIN_CHECKBOX_"..name]:GetChecked() then
            BANETO_PrintWarning("We recommend to /reload after disabling plugins.")
        end
    end)
    BANETO_PLUGIN_CHECKBOX_Z_AXIS = BANETO_PLUGIN_CHECKBOX_Z_AXIS-25
    _G["BANETO_PLUGIN_CHECKBOX_"..name]:Hide()
end

function _G.BANETO_LoadPluginJson()
    local read = ReadFile(baneto_path_scripts_settings.. UnitGUID("player") .. ".json")
    if read then
        local jsondecoded = BANETO_JsonDecode(read)
        BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST = jsondecoded
        for i, v in pairs(BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST) do
            if _G["BANETO_PLUGIN_CHECKBOX_"..i] then
                _G["BANETO_PLUGIN_CHECKBOX_"..i]:SetChecked(v)
            end
        end
    end
end


