function _G.BANETO_ExecutePlugins()
    if isTrial == false then
        if not BANETO_CUSTOM_PLUGIN_STRINGS then
            BANETO_CUSTOM_PLUGIN_STRINGS = { }
            if _internal.Software()  == "tnk" or BANETO_IsJin() then
                local files = ListFiles(baneto_path_scripts_plugins)
                if files and #files>0 then
                    for i=1, #files do
                        local filename = files[i]
                        if filename then
                            local startPos, endPos = string.find(filename,".lua")
                            if startPos then
                                BANETO_CUSTOM_PLUGIN_STRINGS[filename] = ReadFile(baneto_path_scripts_plugins .. filename)
                                BANETO_CreatePluginCheckbox(filename)
                            end
                        end
                    end
                end
            end
            if _internal.Software()  == "nn" and not BANETO_IsJin() then
                local files = ListFiles(baneto_path_scripts_plugins.."*.lua")
                if files and #files>0 then
                    for i=1, #files do
                        local filename = files[i]
                        BANETO_CUSTOM_PLUGIN_STRINGS[filename] = ReadFile(baneto_path_scripts_plugins .. filename)
                        BANETO_CreatePluginCheckbox(filename)
                    end
                end
            end
            return false
        elseif BANETO_SETTING_EXECUTEPLUGINS and BANETO_SETTING_EXECUTEPLUGINS == true then
            for i, v in pairs(BANETO_CUSTOM_PLUGIN_STRINGS) do
                local allowed = BANETO_CUSTOM_PLUGIN_USAGE_ALLOWED_LIST[i]
                if Unlocker("LUA") and _internal.Software() == "tnk" and allowed then
                    Eval(v,"BanetoPlugins")
                end
                if Unlocker("LUA") and _internal.Software() == "nn" and allowed then
                   --local load = loadstring(v,"")
                   --load()
                    RunScript(v)
                end
            end
        end
    end
end

function _G.BANETO_IsUnitOnMesh(unit)
	if BANETO_BLOCK_MESH_CHECK and BANETO_BLOCK_MESH_CHECK == true then
		return true
	end
	if Unlocker("LUA") and lb then
		local x,y,z = BANETO_ObjectPosition(unit)
		if lb.NavMgr_IsPositionOnMesh(x,y,z) then
			return true
		end
	elseif Unlocker("LUA") then
		return true
	elseif Unlocker("EWT") then
	    local x,y,z = ObjectPosition(unit)
	    local map = GetMapId()
	    local meshpointinfo = 0
        if meshpointinfo and meshpointinfo == 0 then
            return true
        end
	end

end

