local BANETO_PUSHNOTIFICIATIONS_APPKEY = "aapkahamzpuwwbcyiidhxms7v72omd"

function _internal.BANETO_PushRequestWa(msg)
    local payload = ([[
        {
            "token": "%s",
            "user": "%s",
            "message": "%s"
        }]]):format(BANETO_PUSHNOTIFICIATIONS_APPKEY, BANETO_PUSHNOTIFICIATIONS_USERKEY, msg)

        local function InternetRequestAsync(verb, url, parameters, extraHeader, callback)
           local id = InternetRequestAsyncInternal(verb, url, parameters, extraHeader)
           local update
           update = function ()
              local response, status = TryInternetRequestInternal(id)
              if response then
                 callback(response, status)
              else
                 C_Timer.After(0, update)
              end
           end
           C_Timer.After(0, update)
        end

        local function InternetRequestComplete(response, status)

        end
        InternetRequestAsync("POST", "api.pushover.net/1/messages.json", payload, "Content-Type: application/json" , InternetRequestComplete)
end

