function _G.HttpRequestCustomPushSmartphoneNots(payload)
    if _internal.Software() == "tnk" then
        local HTTP = Tinkr.Util.HTTP
        local url1 = 'https://api.pushover.net/1/messages.json'
        HTTP:Request({
            url = url1,
            method = 'POST',
            body = payload,
            headers = {
                "Content-Type: application/json"
            },
            callback = function (status, res)
                if status == 200 then
                end
            end
        })
    elseif _internal.Software() == "nn" then
        local url1 = 'https://api.pushover.net/1/messages.json'
        local function callbackfunction(status, data)
        end
        HTTP:Request({
            url = url1,
            method = 'POST',
            body = payload,
            headers = {
                "Content-Type: application/json"
            },
            callback = callbackfunction
        })
    end
end

