function _G.BANETO_AddVendor(faction,vendorType,mapname,x,y,z,id,minLevel,itemTable,zoneId)
    if not minLevel then
        minLevel = 1
    end
    if not faction or not vendorType or not mapname or not x or not y or not z or not id or id == 46140 or id == 74228 then
        if BANETO_Customer() == "justin93" then
            if not faction then
                BANETO_PrintError("Failed to add vendor: faction")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: vendorType")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: mapname")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: x")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: y")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: z")
            elseif not faction then
                BANETO_PrintError("Failed to add vendor: id")
            elseif id and (id == 46140 or id == 74228) then
                BANETO_PrintError("Failed to add vendor: id blacklisted")
            end
        end
        return false
    end
    local mapTranslated = BANETO_continentNames[mapname]
    if not mapTranslated then
        BANETO_PrintWarning("Failed to add vendor on continent :" ..mapname)
        return
    end
    --BANETO_PrintBambo("add vendor logic")
    if faction == "Horde" then
        local tableOld = BANETO_NPCS_VENDORS_HORDE[vendorType][mapTranslated]
        if not tableOld then
            BANETO_NPCS_VENDORS_HORDE[vendorType][mapTranslated] = {}
            tableOld = BANETO_NPCS_VENDORS_HORDE[vendorType][mapTranslated]
        end
        table.insert(tableOld,{x,y,z,id,minLevel,itemTable,zoneId})
        BANETO_NPCS_VENDORS_HORDE[vendorType][mapTranslated] = tableOld
    elseif faction == "Alliance" then
        local tableOld = BANETO_NPCS_VENDORS_ALLIANCE[vendorType][mapTranslated]
        if not tableOld then
            BANETO_NPCS_VENDORS_ALLIANCE[vendorType][mapTranslated] = {}
            tableOld = BANETO_NPCS_VENDORS_ALLIANCE[vendorType][mapTranslated]
        end
        table.insert(tableOld,{x,y,z,id,minLevel,itemTable,zoneId})
        BANETO_NPCS_VENDORS_ALLIANCE[vendorType][mapTranslated] = tableOld
    end
    --BANETO_PrintBambo("Added vendors")
end

local customPushNotDelay = GetTime()
function _G.BANETO_PushNotificationText(customText)
    if customPushNotDelay < GetTime() then
        customPushNotDelay = GetTime()+60
        local payload = ([[
            {
                "token": "%s",
                "user": "%s",
                "message": "%s"
            }]]):format(BANETO_PUSHNOTIFICIATIONS_APPKEY, BANETO_PUSHNOTIFICIATIONS_USERKEY, customText)
            if Unlocker("LUA") then
                HttpRequestCustomPushSmartphoneNots(payload)
            end
    end
end
function _G.BANETO_PushNotification(notificationType)
    if notificationType == "Stuck" then
        BANETO_MASTER_PUSHDELAY = GetTime()-1
    end
	if not BANETO_MASTER_PUSHDELAY or BANETO_MASTER_PUSHDELAY < GetTime() then
		BANETO_MASTER_PUSHDELAY = GetTime()+900
		if notificationType == "Test" then
			if not BANETO_TESTED_PUSHSYSTEM then
				BANETO_TESTED_PUSHSYSTEM = true
				BANETO_MASTER_PUSHDELAY = nil
				local payload = ([[
					{
						"token": "%s",
						"user": "%s",
						"message": "%s"
					}]]):format(BANETO_PUSHNOTIFICIATIONS_APPKEY, BANETO_PUSHNOTIFICIATIONS_USERKEY, "Hey " .. UnitName("player") .. " - Baneto connection is successful!")
                if Unlocker("LUA") then
                    HttpRequestCustomPushSmartphoneNots(payload)
                end
				BANETO_PrintSuccess("Test Message was sent out, check your smartphone!")
			else
				BANETO_PrintError("Only one test push notification allowed per session, please /reload!")
			end
		elseif notificationType == "Whisper" then
			local payload = ([[
				{
					"token": "%s",
					"user": "%s",
					"message": "%s"
				}]]):format(BANETO_PUSHNOTIFICIATIONS_APPKEY, BANETO_PUSHNOTIFICIATIONS_USERKEY, UnitName("player") .. " || " .. BANETO_PUSH_PAYLOAD_WHISPERER .. " whispers: "  .. BANETO_PUSH_PAYLOAD_WHISPER)
                if Unlocker("LUA") then
                    HttpRequestCustomPushSmartphoneNots(payload)
                end
        elseif notificationType == "WqmFinishAndStop" then
            local payload = ([[
                {
                    "token": "%s",
                    "user": "%s",
                    "message": "%s"
                }]]):format(BANETO_PUSHNOTIFICIATIONS_APPKEY, BANETO_PUSHNOTIFICIATIONS_USERKEY, UnitName("player") .. " || WQM Finished and stopped bot.")
                if Unlocker("LUA") then
                    HttpRequestCustomPushSmartphoneNots(payload)
