function _G.BANETO_DefineCenter(x,y,z,radius)
	if not BANETO_SETTING_PROFILERANDOMIZER or BANETO_SETTING_PROFILERANDOMIZER == false then
		table.insert(BANETO_DEFINED_CENTERS,{x,y,z,radius})
	else
        local randX,randY,randZ = BANETO_GetRandomPointInCircle(x,y,z,19)
        if randX and randX and randY then
            if (randX < 0 and randX > 0) or (randY < 0 and randY > 0) then
                table.insert(BANETO_DEFINED_CENTERS,{x,y,z,radius})
            else
                if Unlocker("EWT") then
                    table.insert(BANETO_DEFINED_CENTERS,{randX,randY,randZ,radius})
                elseif Unlocker("LUA") then
                    local randX2,randY2,randZ2 = randX,randY,randZ
                    BANETO_PrintBambo("Inserted Spot with radius: " .. radius)
                    table.insert(BANETO_DEFINED_CENTERS,{randX2,randY2,randZ2,radius})
                end
            end
        end
	end
end




local TNK_REMOTE_PATHS = {}
local TNK_REMOTE_PATHS_REQUESTS = {}
function _G.BANETO_GetRemotePath(pathType)
    if TNK_REMOTE_PATHS[pathType] and TNK_REMOTE_PATHS[pathType]["path"] then
        local path = TNK_REMOTE_PATHS[pathType]["path"]
        TNK_REMOTE_PATHS[pathType] = nil
        TNK_REMOTE_PATHS_REQUESTS[pathType] = nil
        return path
    end
end
function _G.BANETO_ClearRemotePaths()
    TNK_REMOTE_PATHS = {}
    TNK_REMOTE_PATHS_REQUESTS = {}
end

function _G.BANETO_SplitPath(path,desiredSegmentLength,maxIterations)
    local smallDistances = {}
    for i = 1, maxIterations do
        if path[i] and path[i+1] then
            local x1, y1, z1 = path[i]["x"], path[i]["y"], path[i]["z"]
            local x2, y2, z2 = path[i+1]["x"], path[i+1]["y"], path[i+1]["z"]
            local dist = BANETO_GetDistance3D(x1, y1, z1, x2, y2, z2)
            local numSegments = math.floor(dist / desiredSegmentLength)

            for j = 1, numSegments do
                local t = j / numSegments
                local newX = x1 + (x2 - x1) * t
                local newY = y1 + (y2 - y1) * t
                local newZ = z1 + (z2 - z1) * t
                table.insert(smallDistances, {x = newX, y = newY, z = newZ})
            end
        end
    end
    return smallDistances
end

local tinkrPathUrl = ""function _G.BANETO_GeneratePath(startX,startY,startZ,x,y,z,pathType)
    BANETO_LogDragonride("New ground path")
    local gen = {};
    local map = BANETO_GetMapId()
    local swimPath = false
    local remote = BANETO_GetRemotePath(pathType)

    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000,0x20000)
    local d = BANETO_GetDistance3D(startX,startY,startZ, x,y,z)
    local hitX,hitY,hitZ = BANETO_TraceLine(startX,startY,startZ+1, x,y,z+1, hitFlags)
    local distanceFromHitToDest;
    if hitX and hitY and hitZ then
        distanceFromHitToDest = BANETO_GetDistance3D(hitX,hitY,hitZ,x,y,z)
    end
    if not IsFlying() and (not hitX or hitX == 0 or (distanceFromHitToDest and 3>distanceFromHitToDest)) and (BANETO_TARGET or BANETO_UNSTUCK_ROUTE_ISACTIVE or BANETO_GetState() == "SLAVE") and d and d < 100 then
        local startOfPath = { ["x"] = startX, ["y"] = startY, ["z"] = startZ }
        local endOfPath = { ["x"] = x, ["y"] = y, ["z"] = z }
        table.insert(gen,startOfPath)
        table.insert(gen,endOfPath)
        BANETO_PrintBambo("Direct ground path")
        return gen
    end

    if remote and _internal.Software() == "tnk" and not BANETO_OLD_TINKR_PATHING then
        return remote
    end
    if TNK_REMOTE_PATHS_REQUESTS[pathType] and _internal.Software() == "tnk" and not BANETO_OLD_TINKR_PATHING  then
        return
    end
    if _internal.Software() == "tnk" and not BANETO_OLD_TINKR_PATHING and pathType and not TNK_REMOTE_PATHS_REQUESTS[pathType] then
        local url = tinkrPathUrl ..map.."?startX=" .. startX .. "&startY=" .. startY .. "&startZ=" .. startZ .. "&endX=" .. x .."&endY=" .. y .. "&endZ=" .. z .."&areaMask=4&terrainCost=1&waterCost=5&lavaCost=10"
        TNK_REMOTE_PATHS_REQUESTS[pathType] = true
        BANETO_PrintBambo("Tinkr test path request for "..pathType)
        local function testpathCallback(status, data)
            if data then
                BANETO_PrintBambo("Tinkr test path response for "..pathType)
                local res = BANETO_JsonDecode(data)
                TNK_REMOTE_PATHS[pathType] = res
            end
            C_Timer.After(3,function()
                TNK_REMOTE_PATHS[pathType] = nil
                TNK_REMOTE_PATHS_REQUESTS[pathType] = nil
            end)
            BANETO_PrintBamb("status of nav: "..status)
        end
        BANETO_HttpGet(url,testpathCallback,header)
        return
    end

    if IsSwimming() then
        local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
        local xH1, yH1, zH1 = BANETO_TraceLine(startX,startY,startZ,x,y,z, hitFlags)
        if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then

        else
            gen = {}
            swimPath = true
            local input = {
                x = startX,
                y = startY,
                z = startZ
            }
            table.insert(gen,input)
            local input2 = {
                x = x,
                y = y,
                z = z
            }
            table.insert(gen,input2)
        end
    end
    if _internal.Software() == "nn" then
        local navCallBack = function(status, response) end
        gen = GenerateLocalPath(map, startX,startY,startZ,x,y,z,navCallBack,true)
    else
        gen,_ = GeneratePath(startX,startY,startZ,x,y,z,map)
    end
    return gen
end

function _G.BANETO_GetLengthOfGroundPath(path)
    local distance = 0;
    if path then
        for pathIndex = 1,#path-1 do
            local pathX = path[pathIndex]["x"]
            local pathY = path[pathIndex]["y"]
            local pathZ = path[pathIndex]["z"]
            local pathXX = path[pathIndex+1]["x"]
            local pathYY = path[pathIndex+1]["y"]
            local pathZZ = path[pathIndex+1]["z"]
            distance = distance + BANETO_GetDistance3D(pathX,pathY,pathZ,pathXX,pathYY,pathZZ)
        end
    end
    return distance
end

