function _G.BANETO_LoadLocalNextQuesterRoutine()
	if not BANETO_INTERNALNEXTQUESTLOAD_DELAY or BANETO_INTERNALNEXTQUESTLOAD_DELAY < GetTime() and BANETO_IsLocalQuester and BANETO_IsLocalQuester == true then
		BANETO_INTERNALNEXTQUESTLOAD_DELAY=GetTime()+1.5
		local questId = BANETO_DEFINED_QUEST_IDS[1][1]
		if BANETO_IsLocalQuester == true and (BANETO_HasQuestCompleted(questId) or (BANETO_HasAllRequiredQuestsFinished() and _G.BANETO_SkipTurnin and _G.BANETO_SkipTurnin == true and BANETO_HasQuest(questId)) or (_G.BANETO_SkipPulse and _G.BANETO_SkipPulse == true and BANETO_HasQuest(questId)) or (BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GrindTo" and UnitLevel("player") >= BANETO_GRINDTOLEVEL_VALUE)) and BANETO_NEXTQUESTPROFILE_NAME then
			if not BANETO_RETAIL_WQUEST then
			    BANETO_LoadQuestProfile(BANETO_NEXTQUESTPROFILE_NAME)
			end
		elseif BANETO_IsLocalQuester == true and (BANETO_HasQuestCompleted(questId) or (_G.BANETO_SkipTurnin and _G.BANETO_SkipTurnin == true and BANETO_HasQuest(questId))) and not BANETO_NEXTQUESTPROFILE_NAME and not BANETO_RETAIL_WQUEST then
			BANETO_PrintState("Quest Profile end reached! Pausing...")
			BANETO_Stop()
		end
	end
end

