function _G.BANETO_CrecheCount()
    local unit = "player"
    local radius = 100
    local counter = 0
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local x,y,z = BANETO_ObjectPosition(unit)
    for i = 1, #objects do
        local object = objects[i]
        local x2,y2,z2 = BANETO_ObjectPosition(object)
        local distance = BANETO_GetDistance3D(x,y,z,x2,y2,z2)
        if x and x2 then
            if distance and distance < radius and UnlockedUnitAffectingCombat(object) and UnitReaction("player",object) ~= 5 and not BANETO_IsPetLuabox(object)  then
                local threat = BANETO_UnitTarget(object)
                if threat == BANETO_Object("player") or (UnitExists("pet") and threat == BANETO_Object("pet")) then
                    counter = counter +1
                end
            end
        end
    end
	return counter
end

