function _G.BANETO_CrecheScan(color)
    local objects = BANETO_OBJTS_TKR_ONLYUNITS
    local t = {}
    for i=1, #objects do
        local object = objects[i]
        if UnlockedTargetHealth(object) > 0 and color and color ~= "purple" and (color ~= "red" or CRECHE_BACK_TO_SPOT) and not BANETO_PlayerPosition(6072.0698242188,-3188.0446777344,123.51190948486,30) and UnlockedTargetCreatureType(object) ~= "Critter" and (UnlockedTargetReaction(object) == 4 or UnlockedTargetReaction(object) == 2 )  then
            local distance = GetDistanceBetweenObjects("player",object)
            if (distance and 25 > distance and not UnitAffectingCombat(object)) or (distance and 50 > distance and color == "red") then
                local num = GetNumPossibleEnemiesAroundUnit(object,20)
                if num and num >= 1 and BANETO_IsUnitInLos(object) then
                    local x,y,z = BANETO_ObjectPosition(object)
                    local checkX,checkY,checkZ = 6204.8090820312,-3240.2216796875,163.82002258301
                    local d = BANETO_GetDistance3D(x,y,z,checkX,checkY,checkZ)
                    if d and d > 6 then
                        table.insert(t, { object, GetDistanceBetweenObjects("player", object) })
                    end
                end
            end
        end
    end
    if #t > 1 then table.sort(t, function(a, b) if a[2] and b[2] then return a[2] < b[2] end end) end
    if t[1] then
        return t[1][1]
    end
end

