function _G.BANETO_FindArcheologyFragments()
    local fragmentIds = {1,2,3,4,5,6,7,8,27,29,229,231,315,350,382,404,406,408,423,424}
    for i=1,#fragmentIds do
        local fragmentId = fragmentIds[i]
        local raceName, raceTextureID, raceItemID, numFragmentsCollected, numFragmentsRequired, maxFragments  = GetArchaeologyRaceInfoByID(fragmentId)
        if numFragmentsCollected and numFragmentsCollected >= numFragmentsRequired and numFragmentsRequired ~= 0 then
            return fragmentId
