    end
end

BANETO_ARCHEOLOGY_CONTINENTS = {
    [1] = 12,
    [0] = 13,
    [530] = 101,
    [2444] = 1978,
    [1220] = 619,
    [1643] = 876
}

function _G.BANETO_FindClosestDigsite()
    local digsites = BANETO_FindAllDigsites() or {}
    local bestdistance = 999999
    local bestIndex;
    local xx,yy,zz = BANETO_ObjectPosition("player")
    for i = 1,#digsites do
        local x,y = digsites[i][2],digsites[i][3]
        local distance = BANETO_GetDistance3D(x,y,1,xx,yy,1)
        if bestdistance > distance then
            bestdistance = distance
            bestIndex = i
        end
    end
    if bestIndex then
        return digsites[bestIndex]
    end
end

function _G.BANETO_GetDigsitesCompletedCount()
    return BANETO_DIGSITES_COMPLETED
end

function _G.BANETO_FindAllDigsites()
    if BANETO_CACHE_DIGSITES then
        return BANETO_CACHE_DIGSITES
    end
    local digsites = {}
    local map = BANETO_ARCHEOLOGY_CONTINENTS[BANETO_GetMapId()]
    local minDistanceSq = 50 -- Minimum distance squared threshold (adjust as needed)
    local playerX,playerY,playerZ = BANETO_ObjectPosition("player")
    for i = 1, 2500 do
        local digsitesForMap = C_ResearchInfo.GetDigSitesForMap(i)
        local mapinfo = C_Map.GetMapInfo(i)
        --BANETO_PrintBambo("test; "..i)
        if digsitesForMap and digsitesForMap[1] and mapinfo.mapType == 3 and mapinfo.parentMapID == map then
            for q = 1, #digsitesForMap do
                local digsite = digsitesForMap[q]
                local name = digsite.name
                local researchSiteID = digsite.researchSiteID
                local _, worldposition = C_Map.GetWorldPosFromMapPos(i, digsite.position)
                local x3d, y3d = worldposition.x, worldposition.y
                local valid = true
                -- Check against existing digsites
                for _, existingDigsites in pairs(digsites) do
                    local dx = x3d - existingDigsites[2]
                    local dy = y3d - existingDigsites[3]
                    local distanceSq = dx * dx + dy * dy
                    if distanceSq < minDistanceSq then
                        valid = false
                        break
                    end
                    if not valid then break end
                end

                if valid and not IsVectorInBlacklistArea(math.floor(x3d),math.floor(y3d),playerZ) then
                    table.insert(digsites, {name, math.floor(x3d), math.floor(y3d), researchSiteID})
                end
            end
        end
    end
    BANETO_CACHE_DIGSITES = digsites
    return digsites
end

function _G.BANETO_ProbeDownFurtherForArcheologySpot(x,y,z)
    local probeX, probeY, probeZ = BANETO_TraceLine(x, y, z-10, x, y, -3000, 0x00100111)
    if probeX and probeX ~= 0 and probeY and probeY ~= 0 and probeZ and probeZ ~= 0 then
        BANETO_PrintBambo("PROBE 2")
        return probeX, probeY, probeZ
    end
    BANETO_PrintBambo("PROBE 1")
    return x,y,z
end
function _G.BANETO_CountMounts()
    local count = 0
    if C_MountJournal.GetNumMounts then
        for i = 1,C_MountJournal.GetNumMounts() do
            local creatureName, spellID, icon, active, isUsable, sourceType, isFavorite, isFactionSpecific, faction, hideOnChar, isCollected = C_MountJournal.GetMountInfo(i)
            if isCollected then
                count = count+1
            end
        end
    end
    return count
end

function _G.BANETO_SolveArtifact(RaceIndex)
    SetSelectedArtifact(RaceIndex);
    SolveArtifact();
end

function _G.BANETO_CanSolveArtifact()
    for i=1, GetNumArchaeologyRaces() do
        local raceName, raceTexture, raceItemID, numFragmentsCollected, numFragmentsRequired, maxFragments = GetArchaeologyRaceInfo(i)
        if maxFragments and maxFragments > 0 and numFragmentsCollected >= numFragmentsRequired and BANETO_AUTO_SOLVE and BANETO_AUTO_SOLVE == true then
            return i
        end
    end
end

function _G.BANETO_ArcheologySite()
    if ARCH_X then
        if not BANETO_PlayerPosition(ARCH_X,ARCH_Y,ARCH_Z,5) then
            BANETO_MeshTo(ARCH_X,ARCH_Y,ARCH_Z)
            BANETO_PrintBambo("Mesh to arch x")
        else
            --ARCH_X,ARCH_Y,ARCH_Z = nil,nil,nil
            BANETO_PrintBambo("Reached arch x")
            BANETO_StopMovement()
            BANETO_Dismount()
            CancelShapeshift()
        end
    end


    local red = GetObjectWithId(206590)
    local yellow = GetObjectWithId(206589)
    local green = GetObjectWithId(204272)

    if ((not red and not yellow and not green) or BANETO_HasBuff("player",210837)) and BANETO_GetUnitSpeed("player") == 0 and BANETO_IsSpellUsable(80451) then
        BANETO_CastSpell(80451)
        BANETO_StopMovement()
        BANETO_DelayMeshPathing(3)
        return true
    end
    if red then
        local facingOfScope = BANETO_GetObjectFacing(red)
        BANETO_PrintBambo("RED SCOPE: "..facingOfScope)
        local x,y,z = BANETO_ObjectPosition(red)
        local XX,YY,ZZ = BANETO_GetPointForArch(x,y,z,40,facingOfScope)
        local _, _, wz = BANETO_TraceLine(XX, YY, 3000, XX, YY, -3000, 0x00100111)
        if not wz then
            wz = ZZ
        end
        ARCH_X,ARCH_Y,ARCH_Z = BANETO_ProbeDownFurtherForArcheologySpot(XX,YY,wz)
    end
    if yellow then
        local facingOfScope = BANETO_GetObjectFacing(yellow)
        BANETO_PrintBambo("YELLOW SCOPE: "..facingOfScope)
        local x,y,z = BANETO_ObjectPosition(yellow)
        local XX,YY,ZZ = BANETO_GetPointForArch(x,y,z,22,facingOfScope)
        local _, _, wz = BANETO_TraceLine(XX, YY, 3000, XX, YY, -3000, 0x00100111)
        if not wz then
            wz = ZZ
        end
        ARCH_X,ARCH_Y,ARCH_Z = BANETO_ProbeDownFurtherForArcheologySpot(XX,YY,wz)
    end
    if green then
        local facingOfScope = BANETO_GetObjectFacing(green)
        BANETO_PrintBambo("GREEN SCOPE: "..facingOfScope)
        local x,y,z = BANETO_ObjectPosition(green)
        local XX,YY,ZZ = BANETO_GetPointForArch(x,y,z,15,facingOfScope)
        local _, _, wz = BANETO_TraceLine(XX, YY, 3000, XX, YY, -3000, 0x00100111)
        if not wz then
            wz = ZZ
        end
        ARCH_X,ARCH_Y,ARCH_Z = BANETO_ProbeDownFurtherForArcheologySpot(XX,YY,wz)
    end

end

function _G.BANETO_GetAndFaceMultiShotTarget()
    if not BANETO_IsTurningLeft() and not BANETO_IsTurningRight() then
        local objects = BANETO_GetUnitsTkr()
        for i=1,#objects do
            local object = objects[i]
            if not UnitAffectingCombat(object) and BANETO_UnitHealth(object) >= 99 and UnitCanAttack("player",object) and GetDistanceBetweenObjects("player",object) < 40 and (UnlockedTargetReaction(object) == 2 or UnlockedTargetReaction(object) == 4) then
                BANETO_WANTED_ANGLE = nil
                local x,y,z = BANETO_ObjectPosition(object)
                local angle = BANETO_GetFacingValue(x,y,z)
                BANETO_BlockSmoothTurn(2)
                BANETO_SetPlayerAnglesLuabox(angle)
                UnlockedTargetUnit(object)
                return object
            end
        end
    end
end

function _G.BANETO_CrecheAfterBarrage()
    BANETO_BlockSmoothTurn(3);
    BANETO_GroundPathDeleter();
    BANETO_StopMovement();
    BANETO_DelayMeshPathing(3);
    C_Timer.After(0.3,BANETO_TurnLeftStart);
    C_Timer.After(0.6,BANETO_TurnLeftStart);
    C_Timer.After(1.2,BANETO_TurnLeftStart);
    C_Timer.After(1.5,BANETO_TurnLeftStart);
    C_Timer.After(3,BANETO_TurnLeftStop)
end

function _internal.BANETO_CrecheLogic(isPuller,color)
    if isPuller then
        if 40 > BANETO_UnitHealth("player") and not BANETO_HasBuff("player",186265) and UnitAffectingCombat("player") then
            BANETO_CastSpell(186265,true)
        end
        CRECHE_ROLE = "PULLER"
        _G.BANETO_RADIUS_GRIND_SPOTS_TRIGGER = 7
        BANETO_SetSTOPFIGHT_EVADE(GetTime()+30)
        local num = BANETO_CrecheCount()
        local scan = BANETO_CrecheScan(color)
        local currenttarget = BANETO_UnitTarget("player")
        if scan and currenttarget and currenttarget ~= scan then
            UnlockedTargetUnit(scan)
        else
            BANETO_ClearTarget()
        end
        local currentCenterIndex = BANETO_GetCurrentCenterIndex()
        local maxCenterIndex = #BANETO_GetDefinedCenters()
        local lastx, lasty, lastz = BANETO_GetDefinedCenters()[maxCenterIndex][1], BANETO_GetDefinedCenters()[maxCenterIndex][2], BANETO_GetDefinedCenters()[maxCenterIndex][3]
        if not CRECHE_BACK_TO_SPOT and currentCenterIndex >= maxCenterIndex and BANETO_PlayerPosition(lastx,lasty,lastz,10) then
            CRECHE_BACK_TO_SPOT = true
        end

        local cooldown = BANETO_GetSpellCooldown(120360)
        if BANETO_PlayerPosition(6300.7397460938,-3273.8024902344,185.5813293457,7) and cooldown and cooldown == 0 then
            BANETO_CastSpell(120360,true)
            BANETO_BlockSmoothTurn(3)
            BANETO_DelayMeshPathing(3)
            C_Timer.After(0.2,BANETO_TurnLeftStart)
            C_Timer.After(3,BANETO_TurnLeftStop)
        end
        if ((num and num >= 4) or CRECHE_BACK_TO_SPOT) and (not CRECHE_DELAY or CRECHE_DELAY < GetTime()) then
            if not _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior  then
                _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior = true
            end
            if not CRECHE_BACK_TO_SPOT then
                CRECHE_BACK_TO_SPOT = true
                BANETO_GroundPathDeleter()
            end
            local x,y,z;
            if color and color == "cyan" then
                x,y,z = 6072.0698242188,-3188.0446777344,123.51190948486
            elseif color and color == "yellow" then
                x,y,z = 6070.9086914062,-3148.5791015625,121.35766601562
            elseif color and color == "red" then
                x,y,z = 6084.0966796875,-3143.228515625,121.48901367188
            elseif color and color == "purple" then
                x,y,z = 6102.9497070312,-3186.1804199219,124.72566223145
            end
            if not BANETO_PlayerPosition(x,y,z,3) then
                local cd = BANETO_GetSpellCooldown(186257)
                if cd and cd == 0 and BANETO_UnitHealth("player") >= 40 then
                    BANETO_CastSpell(186257,true)
                end

                local cdVolley = BANETO_GetSpellCooldown(260243)
                if cdVolley and cdVolley == 0 and ((color == "yellow" and BANETO_PlayerPosition(6204.8090820312,-3240.2216796875,163.82002258301,45)) or (color == "cyan" and BANETO_PlayerPosition(6135.7880859375,-3051.880859375,135.56976318359,30))) then
                    BANETO_CastSpell(260243,true)
                    BANETO_PrintState("Puller volley")
                    C_Timer.After(0.2,function()
                        local cdVolley = BANETO_GetSpellCooldown(260243)
                        if cdVolley == 0 then
                            local px,py,pz = BANETO_ObjectPosition("player")
                            BANETO_ClickPosition(px,py,pz)
                        end
                    end)
                    C_Timer.After(0.5,function()
                        local cdVolley = BANETO_GetSpellCooldown(260243)
                        if cdVolley == 0 then
                            local px,py,pz = BANETO_ObjectPosition("player")
                            BANETO_ClickPosition(px,py,pz)
                        end
                    end)
                end

                if color == "red" or (color == "cyan" and BANETO_PlayerPosition(6094.0263671875,-3116.9462890625,131.27447509766,19)) or (color == "yellow" and cdVolley > 0 and not BANETO_PlayerPosition(6204.8090820312,-3240.2216796875,163.82002258301,65)) then
                    local cooldown = BANETO_GetSpellCooldown(120360)
                    local cooldown2 = BANETO_GetSpellCooldown(34477)
                    if cooldown2 and cooldown2 == 0 and not BANETO_HasBuff("player",186265) then
                        BANETO_CastSpell(34477,true,"pet")
                    end
                    if cooldown and cooldown == 0 and cooldown2 > 0 and not BANETO_HasBuff("player",186265) then
                        BANETO_DelayMeshPathing(3)
                        BANETO_CastSpell(120360,true)
                        BANETO_BlockSmoothTurn(3)
                        C_Timer.After(0.2,BANETO_TurnLeftStart)
                        C_Timer.After(3,BANETO_TurnLeftStop)
                    end
                end
                BANETO_PrintState("Puller is going to fight spot")
                BANETO_MeshTo(x,y,z)
            else
                if not creche_trypetrevive then
                    if UnitIsDeadOrGhost("pet")  or (BANETO_UnitHealth("pet") < 0 and BANETO_UnitHealth("pet") > 0) then
                        BANETO_CastSpell(982,true) --revive
                        BANETO_DelayMeshPathing(6)
                    end
                    creche_trypetrevive = true
                else
                    creche_trypetrevive = nil
                    if not UnitExists("pet") then
                        BANETO_CastSpell(883,true)
                        BANETO_DelayMeshPathing(6)
                    end
                end
                local cooldown = BANETO_GetSpellCooldown(5384)
                BANETO_DelayMeshPathing(2)
                BANETO_StopMovement()
                if cooldown and cooldown == 0 and not BANETO_HasBuff("player", 5384) then
                    BANETO_PrintState("Puller is using feign death")
                    BANETO_CastSpell(5384,true)
                    C_Timer.After(1,function()
                        if not UnitCastingInfo("player") and not UnitChannelInfo("player") then
                            BANETO_CastSpell(5384,true)
                        end
                    end)
                end
                if BANETO_UnitHealth("player") > 85 then
                    CRECHE_BACK_TO_SPOT = nil
                    C_Timer.After(1,function()
                        if UnitExists("pet") then
                            CRECHE_DELAY = GetTime()+10
                        end
                    end)
                elseif not BANETO_HasBuff("player",199483) and BANETO_GetSpellCooldown(199483) == 0 and cooldown > 0 then
                    BANETO_CastSpell(199483)
                end
                BANETO_SetCurrentCenterIndex(1)
                BANETO_PrintState("Puller is at fight spot")
            end
        else
            if not UnitAffectingCombat("player") then
                if not creche_trypetrevive then
                    if UnitIsDeadOrGhost("pet")  or (BANETO_UnitHealth("pet") < 0 and BANETO_UnitHealth("pet") > 0) then
                        BANETO_CastSpell(982,true) --revive
                        BANETO_DelayMeshPathing(6)
                    end
                    creche_trypetrevive = true
                else
                    creche_trypetrevive = nil
                    if not UnitExists("pet") then
                        BANETO_CastSpell(883,true)
                        BANETO_DelayMeshPathing(6)
                    end
                end
            end
            if color and (color == "purple" or color == "red") then
                local xB,yB,zB;
                if color == "purple" then
                    xB,yB,zB = 6010.3208007812,-3111.5288085938,131.57969665527
                elseif color == "red" then
                    xB,yB,zB = 6025.845703125,-3351.0354003906,122.09419250488
                end
                _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior = true
                if not BANETO_PlayerPosition(xB,yB,zB,4) then
                    BANETO_MeshTo(xB,yB,zB)
                else
                    BANETO_StopMovement()
                    local cooldown = BANETO_GetSpellCooldown(120360)
                    local cooldown2 = BANETO_GetSpellCooldown(34477)
                    if cooldown2 and cooldown2 == 0 then
                        BANETO_CastSpell(34477,true,"pet")
                    end
                    if cooldown and cooldown == 0 and cooldown2 > 0 then
                        BANETO_CastSpell(120360,true)
                        BANETO_BlockSmoothTurn(3)
                        C_Timer.After(0.2,BANETO_TurnLeftStart)
                        C_Timer.After(3,BANETO_TurnLeftStop)
                        C_Timer.After(3.5,function()
                            CRECHE_BACK_TO_SPOT = true
                        end)
                    end
                end
            else
                BANETO_PrintState("Puller is looking for mobs")
                _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior = nil
            end
        end
    else


    end
end

