function _G.BANETO_HasAllRequiredQuests()
    if BANETO_RETAIL_WQUEST and BANETO_RETAIL_WQUEST == true then
        return true
    end

	if #BANETO_DEFINED_QUEST_IDS > 0 then
        if BANETO_DEFINED_QUEST_IDS[1] and BANETO_DEFINED_QUEST_IDS[1][1] and BANETO_DEFINED_QUEST_IDS[1][1] == 0 then
            return true
        end
		if BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GrindTo" then
			if UnitLevel("player") < BANETO_GRINDTOLEVEL_VALUE then
				return true
			end
		else
			local counter = 0
			for q=1,#BANETO_DEFINED_QUEST_IDS do
				local definedQuest = BANETO_DEFINED_QUEST_IDS[q][1]
				local num = C_QuestLog.GetLogIndexForQuestID(definedQuest)
				if (num and num > 1) or BANETO_HasQuestCompleted(definedQuest) then
					counter = counter + 1
				end
				if q == #BANETO_DEFINED_QUEST_IDS and counter >= #BANETO_DEFINED_QUEST_IDS then
					return true
				end
			end
		end
	end
end

function _G.BANETO_HasAllRequiredQuestsFinished()  --[[  FEHLER DRIN --]]
	local counter = 0
	for q=1,#BANETO_DEFINED_QUEST_IDS do
		if BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "TalkTo" then
			counter = counter + 1
		elseif BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "KillAndLoot" or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "Escort" or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GatherObject" or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "UseItemOnLocation"  or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "UseItemOnNpc"  or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "UseSpellOnNpc"  or BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "UseSpellOnLocation" then
			local definedQuest = BANETO_DEFINED_QUEST_IDS[1][1]
			if BANETO_GetQuestIndexById(definedQuest) then
				bamboQuestingFinishedBoolean = C_QuestLog.ReadyForTurnIn(definedQuest)
			end
			if (bamboQuestingFinishedBoolean and bamboQuestingFinishedBoolean == true) or BANETO_HasQuestCompleted(definedQuest) then
				counter = counter + 1
			end
		elseif BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GrindTo" then
			if UnitLevel("player") >= BANETO_GRINDTOLEVEL_VALUE then
				return true
			end
		end
		if q == #BANETO_DEFINED_QUEST_IDS and counter >= #BANETO_DEFINED_QUEST_IDS then
			return true
		end
	end
end

function _G.BANETO_HasQuestCompleted(questid)
	local completedQuests = C_QuestLog.GetAllCompletedQuestIDs()
	for i=1,#completedQuests do
		if completedQuests[i] == questid then
			return true
		end
	end
end


function _G.BANETO_AreAllRequiredQuestCompleted()
	if #BANETO_DEFINED_QUESTSTEP_TYPES >= 1 then
		if BANETO_DEFINED_QUESTSTEP_TYPES[1][1] == "GrindTo" then
			if UnitLevel("player") >= BANETO_GRINDTOLEVEL_VALUE then
				return true
			end
		else
			local counter = 0
			for q=1,#BANETO_DEFINED_QUEST_IDS do
				if BANETO_HasQuestCompleted(BANETO_DEFINED_QUEST_IDS[q][1]) then
					counter = counter + 1
				end
				if q == #BANETO_DEFINED_QUEST_IDS and counter >= #BANETO_DEFINED_QUEST_IDS then
					return true
				end
			end
		end
	else
		return true
	end
end

