    if BANETO_PROFILE_NAME and not BANETO_QUEST_DB[BANETO_PROFILE_NAME] and not string.find(BANETO_PROFILE_NAME, '^OZWQ.*') then
        BANETO_IsLocalQuester = true
        return false
    end
	for i=1, #BANETO_QUEST_DB[BANETO_PROFILE_NAME] do
		local questStep, questIds, questType,questForClass = BANETO_QUEST_DB[BANETO_PROFILE_NAME][i][1],BANETO_QUEST_DB[BANETO_PROFILE_NAME][i][2],BANETO_QUEST_DB[BANETO_PROFILE_NAME][i][3],BANETO_QUEST_DB[BANETO_PROFILE_NAME][i][4]
		if questType == "NormalQuest" then
			local questId = questIds[1]
			if not BANETO_HasQuestCompleted(questId) then
				return questStep
			end
		elseif questType == "ExcludeClassQuest" then
			local questId = questIds[1]
			local _,_,compareclass =  UnitClass("player")
			if not BANETO_HasQuestCompleted(questId) and  compareclass ~= questForClass then
				return questStep
			end
		elseif questType == "TurninQuest" then
			for i = 1, #questIds do
				local questId = questIds[i]
				if not BANETO_HasQuestCompleted(questId) then
					return questStep
				end
			end
		elseif questType == "PickupQuest" then
			for i = 1, #questIds do
				local questId = questIds[i]
				if questId and BANETO_GetQuestIndexById(questIds[1]) then
					local bamboQuestingFinishedBoolean = C_QuestLog.ReadyForTurnIn(questIds[1])
					if (not BANETO_HasQuest(questId) and not BANETO_HasQuestCompleted(questId)) or bamboQuestingFinishedBoolean == false then
						return questStep
					end
				elseif questId and not BANETO_GetQuestIndexById(questIds[1]) then
					if not BANETO_HasQuest(questId) and not BANETO_HasQuestCompleted(questId) then
						return questStep
					end
				end
			end
		elseif questType == "SkipTurninQuest" then
			local questId = questIds[1]
			if questId and BANETO_GetQuestIndexById(questId) then
				local bamboQuestingFinishedBoolean = C_QuestLog.ReadyForTurnIn(questId)
				if bamboQuestingFinishedBoolean == false  then
					return questStep
				end
			end
		elseif questType == "GrindQuest" then
			if UnitLevel("player") < questIds then --[[ questIds equals level --]]
				return questStep
			end
		end
	end
end



function _G.BANETO_LoadLibraryQuest(routine,step)
    if routine == "Exiles Reach Alliance" then
        BANETO_DefineProfileName("Exiles Reach Alliance")
        BANETO_DefineProfileType("Questing")
        BANETO_CheckVendors()
        if BANETO_GetMapId() ~= 2175  or BANETO_GetZoneId() == 1726 then
            message("Please move to exiles reach island to use this profile. NOT the ship!")
            BANETO_Stop()
        end

        if step == "21.MonkClassQuest1" then
            BANETO_DefineCenter(317.14950561523,-2299.3542480469,83.941688537598,130)
            BANETO_DefineQuestPickupNPC(180.72604370117,-2280.5830078125,81.847854614258,156885)
            BANETO_DefineQuestTurninNPC(318.67196655273,-2299.7172851562,83.996780395508,164835)
            BANETO_DefineQuestStepType([[GatherObject]])
            BANETO_DefineQuestId(59347)
            BANETO_DefineQuestTargetId(164835)
            BANETO_RETAIL_GOSSIP_QUEST = true
            function _G.BANETO_ExecuteCustomQuestPulse()
                BANETO_GossipTalkingForQuest()
            end
        elseif step == "21.MonkClassQuest2" then
            BANETO_DefineCenter(332.69482421875,-2328.8864746094,91.368812561035,120)
            BANETO_DefineQuestPickupNPC(318.67196655273,-2299.7172851562,83.996780395508,164835)
            BANETO_DefineQuestTurninNPC(187.38282775879,-2288.8784179688,81.611404418945,156807)
            BANETO_DefineQuestStepType([[UseSpellOnNpc]])
            BANETO_DefineQuestTargetId(115080)
            BANETO_DefineQuestTargetId(167537)
            BANETO_DefineQuestTargetId(167546)
            BANETO_DefineQuestTargetId(164865)
            BANETO_DefineQuestTargetId(174977)
            BANETO_DefineQuestId(59349)
            _G.BANETO_ExecuteCustomQuestPulse_Fighting = true
            function _G.BANETO_ExecuteCustomQuestPulse()
                BANETO_PrintBambo("Boo quest")
                BANETO_USESPELLONNPC_HP_PERCENT = BANETO_UnitHealth("player")
                if UnitExists("target") and UnitAffectingCombat("player") then
                    BANETO_CastSpell(115080)
                end
            end
        end

	    if step == "12.WarlockClassQuest1" then
            BANETO_DefineCenter(397.208984375,-2296.6787109375,108.36158752441,130)
            BANETO_DefineQuestPickupNPC(183.41841125488,-2278.0207519531,81.931701660156,156801)
            BANETO_DefineQuestTurninNPC(409.21353149414,-2297.6579589844,110.64172363281,163246)
            BANETO_DefineQuestTargetId(167478)
            BANETO_DefineQuestTargetId(163209)
            BANETO_DefineQuestTargetId(350998)
            BANETO_DefineQuestTargetId(342259)
            BANETO_DefineQuestStepType([[GatherObject]])
            BANETO_DefineQuestId(58962)
            BANETO_GatherOnlyOneTime = true
            function _G.BANETO_ExecuteCustomQuestPulse()
                if GossipFrame.GreetingPanel:IsVisible() then
                    C_GossipInfo.SelectOption(1)
                    BANETO_GossipTalkingForQuest()
                end
                local itemCount = GetItemCount(174947)
                if itemCount and itemCount >= 1 and (not BANETO_ER_WARLOCK_SUMMON or BANETO_ER_WARLOCK_SUMMON < GetTime()) then
                   BANETO_UseItem(174947)
                   BANETO_ER_WARLOCK_SUMMON = GetTime()+15
                end
                if not DELAY_WARLOCK_RESETGUIDBLACKLISTS or DELAY_WARLOCK_RESETGUIDBLACKLISTS < GetTime() then
                    DELAY_WARLOCK_RESETGUIDBLACKLISTS = GetTime()+30
                    BANETO_ClearGuidBlacklist()
                end
                local seiten = GetObjectWithId(167478)
                if seiten and not ROGUE_EXILES_INTERACTING_DONE then
                    _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior = true
                    local x,y,z = BANETO_ObjectPosition(seiten)
                    if not BANETO_PlayerPosition(x,y,z,5) then
                        BANETO_MeshTo(x,y,z)
                    else
                        BANETO_StopMovement()
                        BANETO_Interact(seiten)
                        C_GossipInfo.SelectOption(52639)
                        --C_GossipInfo.SelectOption(52645)
                        C_Timer.After(3,function()
                            _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior = nil
                            ROGUE_EXILES_INTERACTING_DONE = true
                        end)
                    end
                end
            end
        end
        if step == 100 then
            BANETO_DefineCenter(103.88489532471,-2423.0314941406,90.066253662109,120)
            BANETO_DefineQuestPickupNPC(102.61284637451,-2420.6320800781,90.117858886719,156280)
