                BANETO_PrintBambo("BOAR PULSE")
                if UnitInVehicle("player") then
                    if not BOAR_CHARGE_DELAY or BOAR_CHARGE_DELAY < GetTime() then
                        BANETO_RunMacroText("/click OverrideActionBarButton1")
                        BOAR_CHARGE_DELAY = GetTime()+3
                    end
                    _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior = true
