                    if not BOAR_INDEX_SPOT then
                        BOAR_INDEX_SPOT = 1
                    end
                    if vectorarray[BOAR_INDEX_SPOT] then
                        local x,y,z = vectorarray[BOAR_INDEX_SPOT][1],vectorarray[BOAR_INDEX_SPOT][2],vectorarray[BOAR_INDEX_SPOT][3]
                        if not BANETO_PlayerPosition(x,y,z,8) then
                            BANETO_MeshTo(x,y,z)
