function _G.BANETO_AbandonQuest(Questid)
    if _internal.Software() == "tnk" then
	    C_QuestLog.AbandonQuest(Questid)
	else
	    Unlock("C_QuestLog.AbandonQuest",Questid)
	end
end

function _G.BANETO_AbandonAllQuests()
    if _internal.Software() == "tnk" then
        for i=1,20 do
            SelectQuestLogEntry(i);
            SetAbandonQuest();
            AbandonQuest();
        end
	else
        for i=1,20 do
            SelectQuestLogEntry(i);
            Unlock("SetAbandonQuest","")
            Unlock("AbandonQuest","")
        end
	end
end

function _G.BANETO_HasQuest(Questid)
	local num = C_QuestLog.GetLogIndexForQuestID(Questid)
	if num and num >= 1 then
		return true
	end
end

function _G.BANETO_GetQuestIndexById(Questid)
	return C_QuestLog.GetLogIndexForQuestID(Questid)
end


function _G.BANETO_GetNextQuestPickupData()
	if #BANETO_DEFINED_QUEST_IDS > 0 and BANETO_DEFINED_QUEST_PICKUP_NPCS[1][1] then
		for i=1,#BANETO_DEFINED_QUEST_IDS do
			if not BANETO_HasQuest(BANETO_DEFINED_QUEST_IDS[i][1]) and not BANETO_HasQuestCompleted(BANETO_DEFINED_QUEST_IDS[i][1]) then
				return BANETO_DEFINED_QUEST_PICKUP_NPCS[i][1],BANETO_DEFINED_QUEST_PICKUP_NPCS[i][2],BANETO_DEFINED_QUEST_PICKUP_NPCS[i][3],BANETO_DEFINED_QUEST_PICKUP_NPCS[i][4],BANETO_DEFINED_QUEST_IDS[i][1]
			end
		end
	end
end

function _G.BANETO_GetNextQuestTurninData()
	if #BANETO_DEFINED_QUEST_IDS > 0 and BANETO_DEFINED_QUEST_TURNIN_NPCS[1][1] then
		for i=1,#BANETO_DEFINED_QUEST_IDS do
			if BANETO_HasQuest(BANETO_DEFINED_QUEST_IDS[i][1]) then
				return BANETO_DEFINED_QUEST_TURNIN_NPCS[i][1],BANETO_DEFINED_QUEST_TURNIN_NPCS[i][2],BANETO_DEFINED_QUEST_TURNIN_NPCS[i][3],BANETO_DEFINED_QUEST_TURNIN_NPCS[i][4],BANETO_DEFINED_QUEST_IDS[i][1]
			end
		end
	end
end

function _G.BANETO_DefineFishingSpotAndAngle(x,y,z,angle)
    BANETO_FISH_SPOT_X,BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z = x,y,z
	BANETO_FISH_SPOT_ANGLE  = angle
end


function _G.BANETO_DefineProfileTravelVector(x,y,z)
	BANETO_DEFINED_PROFILE_TRAVELVECTOR = {x,y,z}
end

function _G.BANETO_GetDefinedVendor(type)
	if type == "SELL" then
		return _G.BANETO_DEFINED_VENDOR_SELL
	elseif type == "REPAIR" then
		return _G.BANETO_DEFINED_VENDOR_REPAIR
	elseif type == "GOODS" then
		return _G.BANETO_DEFINED_VENDOR_GOODS
	elseif type == "AMMO" then
		return _G.BANETO_DEFINED_VENDOR_AMMO
	end

end

function _G.BANETO_LoadLocalProfile(profilename)
	BANETO_PrintWarning('DEPRECATED Function! Use /run BANETO_LoadProfile("name") in the future!')
	BANETO_LoadProfile(profilename)
end

function _G.BANETO_LoadProfile(profilename,trystream)
    local foundprofile = false
    if Unlocker("LUA") then
        continent = BANETO_GetMapId()
    elseif Unlocker("EWT") then
        continent,_,_ = GetMapId()
    end
    if Unlocker("LUA") then
        local content = ReadFile(baneto_path_scripts_profiles.. profilename .. ".lua")
        if content then
            if _internal.Software() == "tnk" then
                Eval(content,"loadprofile")
            else
                --local load = loadstring(content,"")
                --load()
                RunScript(content)
            end
            foundprofile = true
            if continent == BANETO_DEFINED_PROFILECONTINENT then
                BANETO_PrintProfile("Custom Profile loaded - " ..  profilename)
                foundprofile = true
            elseif BANETO_DEFINED_PROFILECONTINENT and BANETO_DEFINED_PROFILECONTINENT ~= nil then
                BANETO_PrintError("Wrong Continent for this profile!")
                BANETO_ClearProfileData()
                foundprofile = true
            end
        else
            for w=1,#BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS do
                local subfolder = BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS[w]
                local content = ReadFile(baneto_path_scripts_profiles .. subfolder .. "/" .. profilename .. ".lua")
                if content then
                    if _internal.Software() == "tnk" then
                        Eval(content,"loadprofile")
                    else
                        --local load = loadstring(content,"")
                        --load()
                        RunScript(content)
                    end
                    foundprofile = true
                    if continent == BANETO_DEFINED_PROFILECONTINENT then
                        BANETO_PrintProfile("Custom Profile loaded - " ..  profilename)
                        foundprofile = true
                    elseif BANETO_DEFINED_PROFILECONTINENT and BANETO_DEFINED_PROFILECONTINENT ~= nil then
                        BANETO_PrintError("Wrong Continent for this profile!")
                        BANETO_ClearProfileData()
                        BANETO_Stop()
                        foundprofile = true
                    end
                end
            end
        end
    end

    if Unlocker("LUA") and not foundprofile then
        local content = ReadFile(baneto_path_scripts_profiles_quests.. profilename .. ".lua")
        if content then
            if _internal.Software() == "tnk" then
                Eval(content,"loadprofile")
            else
                --local load = loadstring(content,"")
                --load()
                RunScript(content)
            end
            foundprofile = true
        end
    end
    if foundprofile and foundprofile == true and BANETO_SETTING_IGNOREPROFILENPCS and BANETO_SETTING_IGNOREPROFILENPCS == true then
        _G.BANETO_DEFINED_VENDOR_SELL = { }
        _G.BANETO_DEFINED_VENDOR_REPAIR = { }
        _G.BANETO_DEFINED_VENDOR_GOODS = { }
        _G.BANETO_DEFINED_VENDOR_AMMO = {}
        _G.BANETO_DEFINED_VENDOR_QUEST = { }
        BANETO_CheckVendors()
    end
    BANETO_PrintBambo("Test bambo load profile A")
    if trystream then
        BANETO_PrintBambo("Test bambo load profile B")
    end
    if not foundprofile and not trystream then
        BANETO_PrintError("Something went wrong, could not find file: " .. profilename .. " - open the profile in a text editor and compare filename with defined profilename. They have to match!")
    end
    if not foundprofile and trystream then
        local myString = string.lower(profilename)
        _internal.requestFile(myString)
    end
    return foundprofile
end

function _G.BANETO_LoadQuestProfile(profilename)
	BANETO_ClearProfileData()
	BANETO_LoadProfile(profilename)
	BANETO_IsLocalQuester = true
end




function _G.BANETO_GetLastProfileFiles()
    if BANETO_SETTING_LAST_LOADED_PROFILES then
        local split = BANETO_SplitString(BANETO_SETTING_LAST_LOADED_PROFILES,";")
        return split
    end
end

function _G.BANETO_SplitString(inputString, delimiter)
    local result = {}
    for match in (inputString..delimiter):gmatch("(.-)"..delimiter) do
        if match and match ~= "nostringinput" and match ~= "" then
            table.insert(result, match)
        end
    end
    return result
end

function _G.BANETO_HideAllProfilesInterfaceNew()
    for i = 1,#BANETO_NEW_PROFILES_BUTTONS do
        if BANETO_NEW_PROFILES_BUTTONS[i] then
            BANETO_NEW_PROFILES_BUTTONS[i]:Hide()
        end
    end

    if BANETO_NEW_PROFILES_BUTTONS_LAST_FILES then
        for i = 1,#BANETO_NEW_PROFILES_BUTTONS_LAST_FILES do
            if BANETO_NEW_PROFILES_BUTTONS_LAST_FILES[i] then
                BANETO_NEW_PROFILES_BUTTONS_LAST_FILES[i]:Hide()
            end
        end
    end
end

