                                    BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO2:Hide()
                                    BANETO_SUB_FRAME_PROJECTS_SCROLLBOX:Show()
                                    BANETO_SUB_FRAME_PROFILES_NEW_TXT_MYPROJECTS:Show()
                              end
                        )
                        profilebutton:SetScript("OnClick",
                              function()
                                    BANETO_LoadProfile(theName)
                                    if not BANETO_SETTING_LAST_LOADED_PROFILES then
                                        BANETO_SETTING_LAST_LOADED_PROFILES = ""
                                    end
                                    local newval = theName .. ";" .. BANETO_SETTING_LAST_LOADED_PROFILES
                                    BANETO_SetSettingString("LastLoadedProfiles",newval)
                                    BANETO_HideAllProfilesInterfaceNew()
                                    BANETO_BuildProfileListInterfaceNew()
                              end
                        )
                        local htexButtonMain = profilebutton:CreateTexture()
                        htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
                        htexButtonMain:SetAllPoints()
                        profilebutton:SetHighlightTexture(htexButtonMain)
                        if isFolder then
                            local ntexButtonMain = profilebutton:CreateTexture()
                            ntexButtonMain:SetColorTexture(0, 0, 1, 0.2)
                            ntexButtonMain:SetAllPoints()
                            profilebutton:SetNormalTexture(ntexButtonMain)
                        end
                        jsonsStartY = jsonsStartY - 20
                    end
                end
            end
        end


        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILENAME = BANETO_SUB_FRAME_PROFILES_NEW:CreateFontString(nil, "OVERLAY", "GameFontNormal")
