        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEFACTION:SetFont("GameFontNormal", 18)
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEFACTION:Hide()

        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILECONTINENT = BANETO_SUB_FRAME_PROFILES_NEW:CreateFontString(nil, "OVERLAY", "GameFontNormal")
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILECONTINENT:SetPoint("TOP", 155, -90)
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILECONTINENT:SetText("Continent")
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILECONTINENT:SetFont("GameFontNormal", 18)
