        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO1:SetPoint("TOP", 155, -105)
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO1:SetText("Info1")
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO1:SetFont("GameFontNormal", 18)
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO1:Hide()
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO2 = BANETO_SUB_FRAME_PROFILES_NEW:CreateFontString(nil, "OVERLAY", "GameFontNormal")
