        BANETO_SUB_FRAME_PROFILES_NEW_TXT_PROFILEINFO2:Hide()


        BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES = BANETO_SUB_FRAME_PROFILES_NEW:CreateFontString(nil, "OVERLAY", "GameFontNormal")
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES:SetPoint("TOP", 155, -200)
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES:SetText("Last Files")
        BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES:SetWidth(300)
