            BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES:SetFont("GameFontNormal", 18)
        else
            BANETO_SUB_FRAME_PROFILES_NEW_TXT_LASTFILES:SetFont("Fonts\\MORPHEUS.ttf", 18)
        end





        local jsonsStartYLastFiles = -220
        local lastloadedfiles = BANETO_GetLastProfileFiles()
        if lastloadedfiles then
            for i = 1,13 do
                local theName = lastloadedfiles[i]
                if theName and theName ~= "" then
                    BANETO_NEW_PROFILES_BUTTONS_LAST_FILES[i] = CreateFrame("Button", nil, BANETO_SUB_FRAME_PROFILES_NEW)
                    local profilebutton = BANETO_NEW_PROFILES_BUTTONS_LAST_FILES[i]
                    profilebutton:SetPoint("TOP", 155, jsonsStartYLastFiles)
                    profilebutton:SetWidth(291)
                    profilebutton:SetHeight(20)
                    profilebutton:SetNormalFontObject("GameFontNormalSmall")
                    profilebutton:SetText("|cffC6C5C3"..theName)

                    profilebutton:SetFrameLevel(36)
                    profilebutton:SetScript("OnClick",
                          function()
                                BANETO_LoadProfile(theName)
                          end
                    )
                    local htexButtonMain = profilebutton:CreateTexture()
                    htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
                    htexButtonMain:SetAllPoints()
                    profilebutton:SetHighlightTexture(htexButtonMain)

                    jsonsStartYLastFiles = jsonsStartYLastFiles - 20
                end
            end
        end
    end
end

