function _G.BANETO_BuildProfileListQuesting()



	BANETO_PROFILES_QUESTROUTINES = {
		["Horde"] = {
			["Kalimdor"] = {""},
			["Eastern Kingdoms"] = {""},
			["Exiles Reach"] = {"Exiles Reach Horde"}
		},
		["Alliance"] = {
			["Kalimdor"] = {""},
			["Eastern Kingdoms"] = {""},
			["Exiles Reach"] = {"Exiles Reach Alliance"}
		}

	}

	BANETO_PROFILES_QUESTROUTINES_TWW = {
	    "Exiles Reach Horde","Exiles Reach Alliance","Death Knight Startzone","Pandaren Questline", "Unlock Dragonriding", "TWW Quester"
	}



	BANETO_PROFILES_ClassQuests = {
		["Horde"] = {
			["Kalimdor"] = {""},
			["Eastern Kingdoms"] = {""}
		},
		["Alliance"] = {
			["Kalimdor"] = {""},
			["Eastern Kingdoms"] = {""}
		}
	}


	local faction,_ = UnitFactionGroup("player")
	if Unlocker("LUA") then
		continent = BANETO_GetMapId()
	elseif Unlocker("EWT") then
		continent,_,_ = GetMapId()
	end

    if BANETO_PROFILES_QUESTROUTINES_TWW then
        local xCoord = 0
        local yCoord = -40
        for i=1,#BANETO_PROFILES_QUESTROUTINES_TWW do
            if i ~= 1 then
                yCoord = yCoord - 20
            end
            local profileName = BANETO_PROFILES_QUESTROUTINES_TWW[i]
            local BANETO_PROFILES_QUESTING_BUTTON =  CreateFrame("Button", nil, BANETO_SUB_FRAME_QUESTING)
            BANETO_PROFILES_QUESTING_BUTTON:SetPoint("Top", BANETO_SUB_FRAME_QUESTING, "Topleft", 97, yCoord)
            BANETO_PROFILES_QUESTING_BUTTON:SetWidth(185)
            BANETO_PROFILES_QUESTING_BUTTON:SetHeight(20)
            BANETO_PROFILES_QUESTING_BUTTON:SetNormalFontObject("GameFontNormalSmall")
            BANETO_PROFILES_QUESTING_BUTTON:SetText("|cffC6C5C3" .. profileName)
            BANETO_PROFILES_QUESTING_BUTTON:SetFrameLevel(35)



            BANETO_PROFILES_QUESTING_BUTTON:SetScript("OnClick",
                  function()
                        if profileName == "Death Knight Startzone" then
                            if BANETO_IsDirectoryInstalled("Death Knight Questline") then
                                BANETO_LoadProfile("DK_00 Start")
                            else
                                BANETO_PrintError("Please get the FREE DK Quester from the community store first. You can find it under the name Death Knight Questline")
                            end
                            return
                        end
                        if profileName == "Unlock Dragonriding" then
                            if BANETO_IsDirectoryInstalled("Dragonriding Questline") then
                                local faction,_ = UnitFactionGroup("player")
                                if faction == "Horde" and BANETO_GetMapId() == 1 then
                                    BANETO_LoadProfile("OrgrimmarBoost-1-Dragonriding")
                                elseif faction == "Alliance" and BANETO_GetMapId() == 0 then
                                    BANETO_LoadProfile("StormwindBoost-1-Dragonriding")
                                elseif faction == "Alliance" and BANETO_GetMapId() == 2444 then
                                    BANETO_LoadProfile("Waking-Shore-2pickup-Dragonriding")
                                elseif faction == "Horde" and BANETO_GetMapId() == 2444 then
                                    BANETO_LoadProfile("Horde-Shore-2pickup-Dragonriding")
                                else
                                    BANETO_PrintError("Please start dragonriding questline in waking shore.")
                                end
                            else
                                BANETO_PrintError("Please get the FREE Dragonriding Questline from the community store first. You can find it under the name Dragonriding Questline")
                            end
                            return
                        end
                        if profileName == "TWW Quester" then
                            if BANETO_IsDirectoryInstalled("TWW Intro Quester") then
                                BANETO_LoadProfile("[ISM][N]_001_TheWarWithin")
                            else
                                BANETO_PrintError("Please get the FREE TWW Intro Quester from the community store first (made by Mahdionism). You can find it by searching for TWW.")
                            end
                            return
                        end
                        if profileName == "Pandaren Questline" then
                            if BANETO_IsDirectoryInstalled("Pandaren Questline") then
                                BANETO_LoadProfile("Panda_00 Start")
                            else
                                BANETO_PrintError("Please get the FREE Panda Quester from the community store first. You can find it under the name Pandaren Questline")
                            end
                            return
                        end
                        BANETO_LoadLibraryQuest(profileName,1)
