function _G.BANETO_BuildProfileListLocalQuestProfiles()

	if not BANETO_PROFILES_LOCALQUESTPROFILES then
		BANETO_PROFILES_LOCALQUESTPROFILES = {}
	end
    if Unlocker("LUA") then
         local files;
         if _internal.Software() == "tnk"  or BANETO_IsJin() then
            files = ListFiles(baneto_path_scripts_profiles_quest_direct)
         else
            files = ListFiles(baneto_path_scripts_profiles_quest_direct .."/*.lua")
         end
         if files and #files then
            for i=1, #files do
                local filename = files[i]
                for q in string.gmatch(filename, "[^%.]+") do
                    if q ~= "lua" then
                        table.insert(BANETO_PROFILES_LOCALQUESTPROFILES,q)
                    end
                end
            end
        end
    end

	if #BANETO_PROFILES_LOCALQUESTPROFILES == 0 then
			yCoord = -25
			local BANETO_PROFILES_LOCALPROFILES_BUTTON =  CreateFrame("Button", nil, BANETO_SUB_FRAME_QUESTING_QUESTSTEPS_1)
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetPoint("Top", BANETO_SUB_FRAME_QUESTING_QUESTSTEPS_1, "Topleft", 98, yCoord)
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetWidth(188)
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetHeight(20)
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetNormalFontObject("GameFontNormalSmall")
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetText("|cffC6C5C3No local profiles available!")
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetFrameLevel(35)
			BANETO_PROFILES_LOCALPROFILES_BUTTON:SetScript("OnClick",
				function()
					if BANETO_GetLocale() ~= "koKR" and not BANETO_CHINA_YF then
						BANETO_PrintWarning('If you want to create own questing profiles use the "TOOLS" Tab. On www.baneto-wow.com you can also get new profiles!')
					else
						BANETO_PrintWarning('If you want to create own questing profiles use the "TOOLS" Tab.')
					end
				end
			)
			local htexButtonMain = BANETO_PROFILES_LOCALPROFILES_BUTTON:CreateTexture()
			htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
			htexButtonMain:SetAllPoints()
