        BANETO_PROFILES_LOCALPROFILES_SUB29 = {}
        table.insert(BANETO_PROFILES_LOCALPROFILES_SUB29,"[BACK]")
    end
    if not BANETO_PROFILES_LOCALPROFILES_SUB30 then
        BANETO_PROFILES_LOCALPROFILES_SUB30 = {}
        table.insert(BANETO_PROFILES_LOCALPROFILES_SUB30,"[BACK]")
    end
    if Unlocker("LUA")  then
         local subfolders;
         if _internal.Software() == "tnk"  or BANETO_IsJin() then
            subfolders  = ListDirectories(baneto_path_scripts_profiles_direct)
         else
            subfolders  = ListDirectories(baneto_path_scripts_profiles.."*")
         end
        if subfolders and #subfolders then
            subfolders = BANETO_SortTableOfStringsAlphabetically(subfolders)
        end
        for i=1, #subfolders do
            local subfolder = subfolders[i]
             if subfolder ~= "quests" and (not BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER or BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER < 30 or BANETO_NEW_PROFILE_SELECTOR_ACTIVE) then
                table.insert(BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS,subfolder)
                local payload = {
                    name = subfolder,
                    isFolder = true,
                    faction = "",
                    continent = "",
                    info1 = "",
                    info2 = ""
                }
                table.insert(BANETO_NEW_PROFILES_TABLE,payload)
                if not BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER then
                    BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER = 1
                else
                    BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER=BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER+1
                end
                 local files;
                 if _internal.Software() == "tnk"  or BANETO_IsJin() then
                    files = ListFiles(baneto_path_scripts_profiles .. subfolder)
                 else
                    files = ListFiles(baneto_path_scripts_profiles .. subfolder.."/*.lua")
                 end

                 if files and 0 < #files   then
                     files = BANETO_SortTableOfStringsAlphabetically(files)
                    for x=1,#files do
                        for q in string.gmatch(files[x], "[^%.]+") do
                            if q ~= "lua" then
                                local payload = {
                                    name = q,
                                    isFolder = false,
                                    faction = "Unknown Faction",
                                    continent = "Unknown Map",
                                    info1 = "Unknown Type",
                                    info2 = "Local profile file",
                                    parentFolder = subfolder
                                }
                                table.insert(BANETO_NEW_PROFILES_TABLE,payload)
                            end
                        end
                        if BANETO_PROFILES_LOCALPROFILES_SUBFOLDERS_COUNTER == 1 then
                            local filename = files[x]
                            for q in string.gmatch(filename, "[^%.]+") do
                                if q ~= "lua" then
                                    table.insert(BANETO_PROFILES_LOCALPROFILES_SUB1,q)
                                    table.insert(BANETO_PROFILES_LOCALPROFILES_MASTERLIST,q)
                                end
                            end

