function _G.BANETO_IsFollowerDungeonProfileLoaded() --not documented
    local list = {
        ["FOLLOWER_DUNGEONS_10to80"] = true,
        ["FOLLOWER_DUNGEONS_Uldaman"] = true,
        ["FOLLOWER_DUNGEONS_Rookery"] = true,
        ["FOLLOWER_DUNGEONS_Stonevault"] = true,
        ["FOLLOWER_DUNGEONS_DarkflameCleft"] = true
    }
    local p = BANETO_GetProfileName()
    return list[p]
end

