function _G.BANETO_LoadProfileDescription(profilusNamus)
	ETERNAL_TEMP_PROFILENAME_STORAGE = profilusNamus

	if profilusNamus == "[E]_Valley_1to3" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("The Beginning Zone in the Valley of Trials - farming lvl 1-2 Boars.")
	elseif profilusNamus == "[E]_Valley_3to6" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the uppder side of the previous Profile (1-3) farming lvl 2-4 Scorpids, Familiars and Boars.")
	elseif profilusNamus == "[E]_Senjin_6to9" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is in the North/Western direction of Senjin farming lvl 5/6 Scorpids and Boar and also few lvl 7 Drudges (Centaur).")
	elseif profilusNamus == "[E]_Durotar_6to8" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the Southern Side of Senjin farming mostly lvl 6-7 Boars and Scorpids.")
	elseif profilusNamus == "[E]_Durotar_8to10" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the Western Side of Senjin farming mostly lvl 7 Boars.")
	elseif profilusNamus == "[E]_Durotar_10to12" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is at the Border to the Barrens farming mostly lvl 7-11 Boars and Scorpids.")
	elseif profilusNamus == "[E]_Mulgore_RedCloud_1to3" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("The Beginning Zone farming lvl 1/2 Plainstriders. ")
	elseif profilusNamus == "[E]_Mulgore_Lions_3to5" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("In the South Side of Red Cloud Mesa farming lvl 3 Lions.")
	elseif profilusNamus == "[E]_Mulgore_Battleboars_5to6" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("In front of the Brambleblade Ravine farming lvl 3/4 Battleboards.")
	elseif profilusNamus == "[E]_Mulgore_BloodhoofLoop_6to8" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("In the Western Side of Bloodhoof Village farming lvl 5-7 Plainstriders and Wolves.")
	elseif profilusNamus == "[E]_Mulgore_Blood_6to8_ALT" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("Directly next to Bloodhoof Village farming lvl 5-7 Plainstriders and Wolves.")
	elseif profilusNamus == "[E]_Mulgore_GoldenPlains_8to10" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("In the Golden Plains, farming lvl 7-9 Buzzards, Plainstriders, Wolves and Lions")
	elseif profilusNamus == "[E]_Mulgore_RedRocks_10to12" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("A Spot near the Red Rocks farming lvl 9/10 Bristlebacks's. Densely covered Spot!")
	elseif profilusNamus == "[E]_Mulgore_UpMulgore_10to12" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("Upper Mulgore farming lvl 8-10 Buzzards, Wolves, Lions and Plainstriders")
	elseif profilusNamus == "[E]_Barrens_12to15" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is arround Crossraods and farms lvl 11-12 Dinos, Plainstriders and few Lions. Two Lion Camps are blacklisted.")
	elseif profilusNamus == "[E]_Barrens_15to18" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is in the upper Side of Crossraods farming lvl 14-15 Zebras, Giraffes, Dinos and few lvl 11/12 Plainstriders.")
	elseif profilusNamus == "[E]_Barrens_15to18_Lake_ALT" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This is a alternative 15-18 Route with slightly higher lvl Mob range farming 12-16 Plainstriders, Giraffes and Zebras and also farming 13/14 Centaurs near the Lake. A densely covered Route and also passes the lake with empty 5 Yards Waypoint (to not let him swim across the whole Lake).")
	elseif profilusNamus == "[E]_Barrens_18to21" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is at the upper Side of Ratchet farming mostly lvl 16-18 and also few lvl 14-15 Giraffes, Dinos, Lions, Plainstriders and Zebras.")
	elseif profilusNamus == "[E]_Barrens_21to24" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is at the upper Side of Camp Taurajo farming lvl 18/19 Stormscouts, Hyenas, Giraffes and few lvl 20 Hatchlings and also few lvl 16 Plainstriders. This Spot is densely covered.")
	elseif profilusNamus == "[E]_Barrens_22to25" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Route is surrounding Camp Taurajo and farms lvl 20/21 Thunderheads, Zebras, Hatchlings. The 4x Kodos which are patrolling through the Spots are blacklisted.")
	elseif profilusNamus == "[E]_Barrens_25to27" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is at the Southern Side of Barrens, at the Border to Thousend Needles farming mostly lvl 22-24 Hyenas, Stormhides and Hatchlings. The 4x Kodos which are patrolling through the Spots are blacklisted.")
	elseif profilusNamus == "[E]_Stonetalon_20to23_South" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("The Long Route (20-23) is Split into the Southern Part with slightly lower lvl Mobs (17+).")
	elseif profilusNamus == "[E]_Stonetalon_20to23_North" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("The Long Route (20-23) is Split into the Northern Part with slightly higher lvl Mobs (18+).")
	elseif profilusNamus == "[E]_Stonetalon_20to23_Long" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("A huge Route through the Winshear Crag farming mostly 19/20 Spiders, Venture Humanoids in the Northern Part. and 18/19 Venture Humanoids in the Southern Party. Cathing also the lvl 17/18 Spiders in the Southern Part.")
	elseif profilusNamus == "[E]_Stonetalon_23to26_Beasts" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Profile is in the Northern Side of Sun Rocket Retreat and farms only lvl 21-23 Beast's. The Spawn Rate is good, the Mobs will respawn after the path finnishes. The unreachable Beast uppon the Hills are blacklisted.")
	elseif profilusNamus == "[E]_Ashenvale_24to27_Camp_RISK" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("!HIGH RISK! This is a densely covered Camp Spot, with alot of Mobs. Try it out if your setup will handle this :P")
	elseif profilusNamus == "[E]_Ashenvale_25to28" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the West Side of the River farming 23-25 Spiders and Wolves. The Yetis in the upper Side are blacklisted.")
	elseif profilusNamus == "[E]_Ashenvale_28to31_long" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the Raynewood Retreat, farming lvl 24-26 Bears and Spiders and will also go in to the Satyr Camp farming 26/26 Satyr's. It is a densely covered Spot. Making a bigger Circle to Catch also the Spiders and Bears in the Northern direction.")
	elseif profilusNamus == "[E]_Ashenvale_28to31_Short" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("Similar Route to the previous one (29-31) but focusing only to the Satyr Camp without the Northern direction farming the Bears and Spiders.")
	elseif profilusNamus == "[E]_Ashenvale_31to33_Deamons" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the South/East Side of Splintertree post farming mostly lvl 29/30 Deamons.")
	elseif profilusNamus == "[E]_Shimmering_31to34" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("In the West of Shimmering Flats farming lvl 30-33 Turtles, Buzzards and Crocs.")
	elseif profilusNamus == "[E]_Shimmering_34to37_Turtles" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is directly next to the previous Route (31-34) and it farms mostly 34/35 Turtles, few Spiders and Elementals. Provides a good gp/h. Buzzard Camp in the middle of the path is Blacklisted. Passing it with with a low yard Waypoint.")
	elseif profilusNamus == "[E]_Dustwallow_35to38_ALT_RISK" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("!HIGH RISK! This Spot is in the Northern Side of Dustwallow farming lvl 36/37 Dinos. It is just an experimental alternative Option with a high xp/h ratio. The Camp is blacklisted and the Yards of the Waypoints are adjusted - to not let Baneto run inside the Camp. ")
	elseif profilusNamus == "[E]_Dustwallow_36to40" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This spot is in the upper Side of Brackenwall Village farming lvl 35/36 Crocs, Dinos, Spiders and Roamers. Passing also a Spider Camp (lvl 35), Waypoint Yards are optimized to only catch few of them and not letting it run into the whole Camp.")
	elseif profilusNamus == "[E]_Dustwallow_39to42" then
		BANETO_MAIN_FRAME_PAIDPROFILE_EXPLANATION_TEXT:SetText("This Spot is in the Southern Side of Dustwallow upper the Stonemaul Ruins. Farming mostly 37-39 Oozes, Dinos, Crocs and Spiders. It is a densely covered Area. ")
	elseif profilusNamus == "[E]_Dustwallow_39to42_Same" then
