function _G.BANETO_BuildProfileListEternal()
	if Unlocker("LUA") then
		continent = BANETO_GetMapId()
	elseif Unlocker("EWT") then
		continent,_,_ = GetMapId()
	end

	if continent == 1 then
		BANETO_PROFILES_ETERNAL_GRINDING_HORDE = {
			"[E]_Valley_1to3","[E]_Valley_3to6","[E]_Senjin_6to9","[E]_Durotar_6to8","[E]_Durotar_8to10","[E]_Durotar_10to12",
