			"[E]_Mulgore_GoldenPlains_8to10","[E]_Mulgore_RedRocks_10to12",
			"[E]_Mulgore_UpMulgore_10to12",
			"[E]_Barrens_12to15","[E]_Barrens_15to18","[E]_Barrens_15to18_Lake_ALT","[E]_Barrens_18to21","[E]_Barrens_21to24",
			"[E]_Barrens_22to25","[E]_Barrens_25to27",
			"[E]_Stonetalon_20to23_South","[E]_Stonetalon_20to23_North","[E]_Stonetalon_20to23_Long","[E]_Stonetalon_23to26_Beasts",
			"[E]_Ashenvale_24to27_Camp_RISK","[E]_Ashenvale_25to28","[E]_Ashenvale_28to31_long","[E]_Ashenvale_28to31_Short","[E]_Ashenvale_31to33_Deamons",
			"[E]_Shimmering_31to34","[E]_Shimmering_34to37_Turtles",
			"[E]_Dustwallow_35to38_ALT_RISK","[E]_Dustwallow_36to40","[E]_Dustwallow_39to42","[E]_Dustwallow_39to42_Same","[E]_Dustwallow_40to43_Ooze",
			"[E]_Tanaris_41to44","[E]_Tanaris_41to44_Long","[E]_Tanaris_43to46_Turtles","[E]_Tanaris_44to47","[E]_Tanaris_46to49","H_Tanaris_45to48_Bigger_Alternative",
			"[E]_Tanaris_48to51_Ogres_RISK","[E]_Tanaris_49to53",
			"[E]_Feralas_42to45_BearsWolves","[E]_Feralas_42to44_WPaw_RISK","[E]_Feralas_43to47","[E]_Feralas_47to50",
			"[E]_Feralas_47to50_ELE_NoMage","[E]_Feralas_46to49_ALT","[E]_Feralas_47to50_Hippo_RISK",
			"[E]_Felwood_50to53_West","[E]_Felwood_50to53_East",
			"[E]_Ungoro_53to56","[E]_Ungoro_53to55_Without_Dino","[E]_Ungoro_53to55_With_Dino_ALT","[E]_Ungoro_55to58",
			"[E]_Winterspring_55to58",
			"[E]_Winterspring_58to60"
		}
	elseif continent == 0 then
		BANETO_PROFILES_ETERNAL_GRINDING_HORDE = {
			"[E]_Tirisfal_1to3","[E]_Tirisfal_2to4_Spiders","[E]_Tirisfal_3to6","[E]_Tirisfal_6to8",
			"[E]_Tirisfal_8to10","[E]_Tirisfal_10to12","[E]_Tirisfal_12to15_ALT",
			"[E]_Silverpine_12to14","[E]_Silverpine_14to17","[E]_Silverpine_15to18_Alternative","[E]_Silverpine_16to19",
			"[E]_Silverpine_18to21",
			"[E]_Hilsbrad_21to23","[E]_Hilsbrad_23to26","[E]_Hilsbrad_25to28",
			"[E]_Hilsbrad_27to30",
			"[E]_Arathi_30to33","[E]_Arathi_30to33_Alternative","[E]_Arathi_33to35","[E]_Arathi_33to36",
			"[E]_Arathi_33to36_Alternative","[E]_Arathi_36to40",
			"[E]_SwampSorrows_36to38","[E]_SwampSorrows_38to41_ALT",
			"[E]_SwampSorrows_38to41_Bigger","[E]_SwampSorrows_41to44",
			"[E]_Hinterlands_43to46","[E]_Hinterlands_45to49_Alternative",
			"[E]_Hinterlands_46to49","[E]_Hinterlands_49to52","[E]_Hinterlands_50to53_Turtles",
			"[E]_SearingGorge_46to48","[E]_SearingGorge_48to51",
			"[E]_BlastedLands_48to51",
			"[E]_WesternPlague_53to56",
			"[E]_EasternPlaguelands_56to58","[E]_EasternPlaguelands_58to60"
		}
	else
		BANETO_PROFILES_ETERNAL_GRINDING_HORDE = {
			"Wrong Profile Continent","Only Eastern Kingdoms","or Kalimdor"
		}
	end

	if #BANETO_PROFILES_ETERNAL_GRINDING_HORDE > 2 then
		local xCoord = 0
		local yCoord = -5
		for i=1,#BANETO_PROFILES_ETERNAL_GRINDING_HORDE do
			if i ~= 1 then
				yCoord = yCoord - 20
			end
			local profileName = BANETO_PROFILES_ETERNAL_GRINDING_HORDE[i]
			if i < 18 then
				local BANETO_PROFILES_GRINDING_BUTTON =  CreateFrame("Button", nil, BANETO_MAIN_FRAME_PAIDPROFILE_LISTBACK)
				BANETO_PROFILES_GRINDING_BUTTON:SetPoint("Top", BANETO_MAIN_FRAME_PAIDPROFILE_LISTBACK, "Topleft", 100, yCoord)
