				BANETO_PROFILES_GRINDING_BUTTON:SetFrameLevel(35)



				BANETO_PROFILES_GRINDING_BUTTON:SetScript("OnClick",
					function()
						BANETO_LoadProfileDescription(profileName)
					end
				)

				local htexButtonMain = BANETO_PROFILES_GRINDING_BUTTON:CreateTexture()
				htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
				htexButtonMain:SetAllPoints()
				BANETO_PROFILES_GRINDING_BUTTON:SetHighlightTexture(htexButtonMain)
			elseif i < 35 then
				if i == 18 then
					yCoord = -5
				end
				local BANETO_PROFILES_GRINDING_BUTTON =  CreateFrame("Button", nil, BANETO_MAIN_FRAME_PAIDPROFILE_LISTBACK)
				BANETO_PROFILES_GRINDING_BUTTON:SetPoint("Top", BANETO_MAIN_FRAME_PAIDPROFILE_LISTBACK, "Topleft", 300, yCoord)
				BANETO_PROFILES_GRINDING_BUTTON:SetWidth(200)
				BANETO_PROFILES_GRINDING_BUTTON:SetHeight(20)
				BANETO_PROFILES_GRINDING_BUTTON:SetNormalFontObject("GameFontNormalSmall")
				BANETO_PROFILES_GRINDING_BUTTON:SetText("|cffC6C5C3" .. profileName)
				BANETO_PROFILES_GRINDING_BUTTON:SetFrameLevel(35)

				BANETO_PROFILES_GRINDING_BUTTON:SetScript("OnClick",
					function()
						BANETO_LoadProfileDescription(profileName)
					end
				)

				local htexButtonMain = BANETO_PROFILES_GRINDING_BUTTON:CreateTexture()
				htexButtonMain:SetColorTexture(1, 1, 1, 0.2)
				htexButtonMain:SetAllPoints()
