function _G.BANETO_HealFriendlyTarget()
    if not BANETO_OVERHEAL_PREVENTER_SLAVE or BANETO_OVERHEAL_PREVENTER_SLAVE < GetTime() then
        if UnitExists("target") and BANETO_IsTargetInLos() and BANETO_UnitHealth("target") > 1  and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
            BANETO_OVERHEAL_PREVENTER_SLAVE = GetTime() +1.5
            if BANETO_GetUnitSpeed("player") > 0 then
                if Unlocker("LUA") then
                    BANETO_StopMovement()
                elseif Unlocker("EWT") then
                    StopEwtMovement()
                end
            end
            local _, _, class = UnitClass("player")
            if class == 5 then
                local flash_heal = 2061
                local heal = 2050
                local shieldSpell = 17
                local shield = 6788
                local hot = 139
                local healBigger = 2054
                if BANETO_IsSpellUsable(hot) and not BANETO_HasBuff("target",hot) then
                    BANETO_CastSpell(hot,true)
                end
                if BANETO_IsSpellUsable(flash_heal) then
                    BANETO_CastSpell(flash_heal,true)
                elseif BANETO_IsSpellUsable(healBigger) then
                    BANETO_CastSpell(healBigger,true)
                elseif BANETO_IsSpellUsable(heal) then
                    BANETO_CastSpell(heal,true)
                end
            elseif class == 2 then
                local heal, flash_of_light = 639,19750
                if BANETO_IsSpellUsable(heal) and (BANETO_UnitHealth("target") < 20 or BANETO_DEFINED_PROFILE_TYPE ~= "Battleground") then
                    BANETO_CastSpell(heal, true)
                elseif BANETO_IsSpellUsable(flash_of_light) then
                    BANETO_CastSpell(flash_of_light, true)
                end
            elseif class == 11 then
                if GetShapeshiftDruid() ~= 0 then
                    CancelShapeshift()
                    print("C")
                end
                local regrowth, rejuvenation, healingTouch = 8936,2091,5185
                if BANETO_IsSpellUsable(regrowth)  and not BANETO_HasBuff("target", regrowth) then
                    BANETO_CastSpell(regrowth, true)
                elseif BANETO_IsSpellUsable(rejuvenation) and not BANETO_HasBuff("target", rejuvenation)  then
                    BANETO_CastSpell(rejuvenation, true)
                elseif BANETO_IsSpellUsable(healingTouch) then
                    BANETO_CastSpell(healingTouch, true)
                end
            end
            if (BANETO_UnitHealth("target") >= 95 or BANETO_UnitHealth("target") <= 1) and BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" then
                BANETO_ClearTarget()
                BANETO_SpellStopCasting()
            end
        elseif UnitExists("target") and not BANETO_IsTargetInLos() and BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" and BANETO_UnitHealth("target") > 1  then
            if Unlocker("LUA") then
                local x,y,z = BANETO_ObjectPosition("target")
                BANETO_MeshTo(x,y,z)
            end
        end
    end
end

function _G.BANETO_LoadArcheologyModule(code)
    if code and code == "najsu3hhasd83" then
        BANETO_DefineProfileName("ArcheologyModule")
        BANETO_DefineProfileType("Archeology")
        BANETO_PrintWarning("If some digites cause issues, you can add large blacklist areas around them with settings -> blacklisting!")
    end
    StaticPopupDialogs["solveselector"] = {
        text = "Auto solve artifacts?",
        button1 = "Yes",
        button2 = "No",
        OnAccept = function()
            BANETO_SetSettingBool("AutoSolve",true)
        end,
        OnCancel = function()
            BANETO_SetSettingBool("AutoSolve",false)
        end,
        timeout = 0,
        whileDead = true,
        hideOnEscape = true,
    }
    if not UnitAffectingCombat("player") then
        StaticPopup_Show("solveselector")
        C_Timer.After(8,function()
            StaticPopup_Hide("solveselector")
        end)
    end
end
function _G.BANETO_IsProfileLoaded()

	if BANETO_SETTING_IGNOREPROFILENPCS and BANETO_SETTING_IGNOREPROFILENPCS == true then
		_G.BANETO_DEFINED_VENDOR_SELL = { }
		_G.BANETO_DEFINED_VENDOR_REPAIR = { }
		_G.BANETO_DEFINED_VENDOR_GOODS = { }
		_G.BANETO_DEFINED_VENDOR_AMMO = {}
		_G.BANETO_DEFINED_VENDOR_QUEST = { }
	end
    if BANETO_DEFINED_PROFILE_TYPE == "Archeology" then
        if BANETO_CheckVendors() then
            return true
        end
    end
    if BANETO_DEFINED_PROFILE_TYPE == "Slavemode" then
        if BANETO_CheckVendors() then
            return true
        end
    end
	if BANETO_DEFINED_PROFILE_TYPE == "Grinding" then
		if BANETO_DEFINED_CENTERS[1] then
			if BANETO_CheckVendors() then
				return true
			end
		end
	end
	if BANETO_DEFINED_PROFILE_TYPE == "BRD" then
		return true
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Fishing" then
		return true
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Rotation" then
		return true
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
        return true
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Traveling" then
		return true
	end
	if BANETO_DEFINED_PROFILE_TYPE == "Questing" then
		if BANETO_CheckVendors() then
			return true
		end
	end
end

function _G.BANETO_IsRepairNeeded()
	if BANETO_SETTING_REPAIR == true then
        if _G.BANETO_VISION_TRIGGER_REPAIR and _G.BANETO_VISION_TRIGGER_REPAIR == true then
            return true
        end
        if BANETO_WEAPON_REPAIR and BANETO_WEAPON_REPAIR == true then
            return true
        end
        if DurabilityWeapon:IsVisible() and not BANETO_BLOCK_WEAPONREPAIR_FORCE then
            BANETO_WEAPON_REPAIR = true
            return true
        end
		local valuecounter = 0
		local valueTotal = 0
        local repairValue = BANETO_SETTING_REPAIR_VALUE
        if repairValue == 100 then
            repairValue = 99
        end
		for i=1,19 do
			local current, maximum = GetInventoryItemDurability(i)
			if current and maximum then
				local value = current/maximum
				valueTotal = valueTotal + value
				valuecounter = valuecounter +1
			end

			if i == 19 then
				--[[ BANETO_PrintDev("Estimated Armor Value: " .. (valueTotal/valuecounter)) --]]
				if (valueTotal/valuecounter) < (repairValue/100) then
					return true
				end
			end

		end
	end

end

function _G.BANETO_GetArmorPercentage()
	local valuecounter = 0
	local valueTotal = 0
	for i=1,19 do
		local current, maximum = GetInventoryItemDurability(i)
		if current and maximum then
			local value = current/maximum
			valueTotal = valueTotal + value
			valuecounter = valuecounter +1
		end

		if i == 19 then
			local result = (valueTotal/valuecounter)*100
			return math.floor(result)
		end

	end

end

