	UnlockedTargetUnit = function (...) return ... and lb.UnitTagHandler(TargetUnit, ...) or false end


	UnlockedUnitAffectingCombat = function (...) return ... and lb.UnitTagHandler(UnitAffectingCombat, ...) or false end

	UnlockedTargetHealth = function (...) return ... and lb.UnitTagHandler(UnitHealth, ...) or false end

	UnlockedTargetNpcFlags = function (...) return ... and lb.UnitTagHandler(UnitNpcFlags, ...) or false end

	UnlockedTargetReaction = function (...) return ... and lb.UnitTagHandler(UnitReaction, "player",...) or false end

	UnlockedTargetCreatureType = function (...) return ... and lb.UnitTagHandler(UnitCreatureType, ...) or false end

	UnlockedTargetCreatureTypeId = function (...) return ... and lb.UnitTagHandler(UnitCreatureTypeID, ...) or false end

	UnlockedTargetClassification = function (...) return ... and lb.UnitTagHandler(UnitClassification, ...) or false end

	UnlockedInteract = function (...) return lb.Unlock(lb.ObjectInteract, ...) end

	UnlockedUnitIsTrivial = function (...) return ... and lb.UnitTagHandler(UnitIsTrivial, ...) or false end
elseif Unlocker("LUA") and CallSecureFunction then
	UnlockedTargetUnit = function (...) return ... and CallSecureFunction(TargetUnit, ...) or false end


	UnlockedUnitAffectingCombat = function (...) return ... and CallSecureFunction(UnitAffectingCombat, ...) or false end

	UnlockedTargetHealth = function (...) return ... and CallSecureFunction(UnitHealth, ...) or false end

	UnlockedTargetNpcFlags = function (...) return ... and CallSecureFunction(UnitNpcFlags, ...) or false end

	UnlockedTargetReaction = function (...) return ... and CallSecureFunction(UnitReaction, "player",...) or false end

	UnlockedTargetCreatureType = function (...) return ... and CallSecureFunction(UnitCreatureType, ...) or false end

	UnlockedTargetCreatureTypeId = function (...) return ... and CallSecureFunction(UnitCreatureTypeID, ...) or false end

	UnlockedTargetClassification = function (...) return ... and CallSecureFunction(UnitClassification, ...) or false end

	UnlockedInteract = function (...) return CallSecureFunction(ObjectInteract, ...) end

	UnlockedUnitIsTrivial = function (...) return ... and CallSecureFunction(UnitIsTrivial, ...) or false end
elseif Unlocker("LUA") then
	function _G.UnlockedTargetReaction(unit)
		return UnitReaction('player',unit)
	end
    function _G.UnlockedUnitIsTrivial(unit)
        return UnitIsTrivial(unit)
    end
    function _G.UnlockedTargetHealth(unit)
        local hp = UnitHealth(unit)
        if hp == nil then
            hp = 0
        end
        return hp
    end
    function _G.UnlockedTargetCreatureTypeId(unit)
        return UnitCreatureTypeID(unit)
    end
    function _G.UnlockedTargetCreatureType(unit)
        if _internal.Software() == "nn"then
            local value = UnitCreatureTypeId(unit)
            if value == 1 then
                return "Beast"
            elseif value == 2 then
                return "Dragonkin"
            elseif value == 3 then
                return "Demon"
            elseif value == 4 then
                return "Elemental"
            elseif value == 5 then
                return "Giant"
            elseif value == 6 then
                return "Undead"
            elseif value == 7 then
                return "Humanoid"
            elseif value == 8 then
                return "Critter"
            elseif value == 9 then
                return "Mechanical"
            elseif value == 10 then
                return "Not specified"
            elseif value == 11 then
                return "Totem"
            elseif value == 12 then
                return "Non-combat Pet"
            elseif value == 13 then
                return "Gas Cloud"
            elseif value == 14 then
                return "Wild Pet"
            else
                return value
            end
        else
            return UnitCreatureType(unit)
        end
    end
    function _G.UnlockedTargetClassification(unit)
        return UnitClassification(unit)
    end
    function _G.UnlockedTargetUnit(unit)
        if not BANETO_DELAY_TARGETING or BANETO_DELAY_TARGETING < GetTime() then
            TargetUnit(unit)
        end
    end
end

if Unlocker("EWT") then

	function UnlockedTargetCreatureType(unit)
		return UnitCreatureType(unit)
	end
	function UnlockedTargetCreatureTypeId(unit)
		return UnitCreatureTypeID(unit)
	end

end

