function _G.BANETO_GetNodenameByFlightmasterId(id)
	return BANETO_TAXI_NODENAMES[id]
end

function _G.BANETO_UseTaxiNode(destinationNodeName)
	if not BANETO_TAXINODE_USAGE_DELAY or BANETO_TAXINODE_USAGE_DELAY < GetTime() then
		BANETO_TAXINODE_USAGE_DELAY = GetTime()+3
		for i=1, NumTaxiNodes() do
			local nodeName = TaxiNodeName(i)
			if nodeName and nodeName == destinationNodeName then
                TakeTaxiNode(i)
			end
		end
	end
end

function _G.TestTaxi()
    TakeTaxiNode(10)
end
_G.BANETO_RACIAL_TROLL_HP = 40
function _G.BANETO_UseRacials()
	if BANETO_SETTING_RACIALSKILLS == true and not IsMounted() and BANETO_RETAIL_RACIALS_READY then
		local orcRacial = 20572
		local trollRacial = 26297
		local trollRacial2 = 20554
		local dwarfRacial = 20594
		if BANETO_IsSpellUsable(orcRacial) and UnitAffectingCombat("player") and BANETO_State ~= "REPAIR" then
			BANETO_CastSpell(orcRacial,"spell")
			BANETO_HUNTER_AUTOSHOT_ACTIVE = nil
		elseif BANETO_IsSpellUsable(trollRacial) and UnitAffectingCombat("player") and BANETO_UnitHealth("player") < BANETO_RACIAL_TROLL_HP and BANETO_State ~= "REPAIR" then
			BANETO_CastSpell(trollRacial,"spell")
		elseif BANETO_IsSpellUsable(trollRacial2) and UnitAffectingCombat("player") and BANETO_UnitHealth("player") < BANETO_RACIAL_TROLL_HP and BANETO_State ~= "REPAIR" then
			BANETO_CastSpell(trollRacial2,"spell")
		elseif BANETO_IsSpellUsable(dwarfRacial) and UnitAffectingCombat("player") and BANETO_UnitHealth("player") < 50 then
			BANETO_CastSpell(dwarfRacial,"spell")
		end
	end
end

