function _G.BANETO_HighestDruidForm()
	if BANETO_IsSpellKnown(768) or BANETO_HasBuff("player", 768) then
		return "Cat"
	elseif BANETO_IsSpellKnown(5487) or BANETO_HasBuff("player", 5487) then
		return "Bear"
	else
		return "Human"
	end
end

function _G.BANETO_PlayerPosition(x,y,z,distance)
    if not BANETO_TARGET and (not x or not y or not z) then
        return false
    end
	if Unlocker("LUA") and x and y and z and distance then
		local xP, yP, zP = BANETO_ObjectPosition("player")
		local calculatedDistance = BANETO_GetDistance3D(xP,yP,zP,x,y,z)
		if calculatedDistance == nil then
		    calculatedDistance = 1337
		end
		if distance and calculatedDistance and calculatedDistance > distance then
			return false
		elseif distance and calculatedDistance then
			return true
		end
	elseif Unlocker("EWT") and x and y and z and distance then
		local xP, yP, zP = ObjectPosition("player")
		if GetDistanceBetweenPositions(xP,yP,zP,x,y,z) and GetDistanceBetweenPositions(xP,yP,zP,x,y,z) > distance then
			return false
		else
			return true
		end
	end

end

function _G.BANETO_LoadRotaOnlyMode()
	if not BANETO_ISRUNNING then
		BANETO_ClearProfileData()
		BANETO_DefineProfileName("ROTATION-ONLY-MODE")
		BANETO_DefineProfileType("Rotation")
		BANETO_ISRUNNING_ROTATIONONLYMODE = true
		BANETO_BUTTON_STARTSTOP:Click()
	else
		BANETO_PrintError("Baneto is already running.")
	end
end

_G.BANETO_1CLICKFARMER_RANGE = 400
function _G.BANETO_Load1ClickFarm(withstart)
	if not BANETO_ISRUNNING then
		BANETO_ClearProfileData()
		BANETO_DefineProfileName("1-CLICK-INSTANT-FARM")
		BANETO_DefineProfileType("Grinding")
		BANETO_ISRUNNING_1CLICKFARM = true
		if Unlocker("LUA") then
			local x,y,z = BANETO_ObjectPosition("player")
			BANETO_DefineCenter(x,y,z, _G.BANETO_1CLICKFARMER_RANGE)
		elseif Unlocker("EWT") then
			local x,y,z = ObjectPosition("player")
			BANETO_DefineCenter(x,y,z, _G.BANETO_1CLICKFARMER_RANGE)
		end
		BANETO_CheckVendors()
		if withstart then
		    BANETO_Start()
        end
	else
		BANETO_PrintError("Baneto is already running.")
	end
end

function _G.BANETO_UpdateVendors60Seconds()
	if not BANETO_VENDOR_UPDATE_DELAY or BANETO_VENDOR_UPDATE_DELAY < GetTime() then
		BANETO_VENDOR_UPDATE_DELAY = GetTime()+30
		if BANETO_NPCDB_AUTO_SELL == true then
			_G.BANETO_DEFINED_VENDOR_SELL = { }
			BANETO_DefineSellVendor(BANETO_GetClosestNpc("Sell"))
		end
		if BANETO_NPCDB_AUTO_REPAIR == true then
			_G.BANETO_DEFINED_VENDOR_REPAIR = { }
			BANETO_DefineRepairVendor(BANETO_GetClosestNpc("Repair"))
		end
		if BANETO_NPCDB_AUTO_GOODS == true then
			_G.BANETO_DEFINED_VENDOR_GOODS = { }
			BANETO_DefineGoodsVendor(BANETO_GetClosestNpc("Goods"))
		end
		if BANETO_NPCDB_AUTO_AMMO == true then
			_G.BANETO_DEFINED_VENDOR_AMMO = { }
			BANETO_DefineAmmoVendor(BANETO_GetClosestNpc("Ammo"))
		end
        BANETO_CheckVendors()
	end
end

function _G.BANETO_CheckVendors()
    local xVendorCheck,y,z = BANETO_ObjectPosition("player")
    if not xVendorCheck then
        BANETO_PrintWarning("Vendor check failed, could not find player x coordinate. Retrying soon...")
        return false
    end
	if not _G.BANETO_DEFINED_VENDOR_SELL[1]  or not _G.BANETO_DEFINED_VENDOR_SELL[1][1] then
		BANETO_DefineSellVendor(BANETO_GetClosestNpc("Sell"))
		if not BANETO_ISRUNNING_1CLICKFARM and BANETO_DEFINED_PROFILE_TYPE ~= "Questing"  and (not NPC_DATABASE_INFO_PRINT or NPC_DATABASE_INFO_PRINT < GetTime())  then
			BANETO_PrintProfile("BANETO will use a database NPC for SELL!")
            NPC_DATABASE_INFO_PRINT = GetTime()+300
		end
		BANETO_NPCDB_AUTO_SELL = true

	end
	if not _G.BANETO_DEFINED_VENDOR_REPAIR[1]  or not _G.BANETO_DEFINED_VENDOR_REPAIR[1][1] then
		BANETO_DefineRepairVendor(BANETO_GetClosestNpc("Repair"))
		if not BANETO_ISRUNNING_1CLICKFARM and BANETO_DEFINED_PROFILE_TYPE ~= "Questing"  and (not NPC_DATABASE_INFO_PRINT or NPC_DATABASE_INFO_PRINT < GetTime())  then
			BANETO_PrintProfile("BANETO will use a database NPC for REPAIR!")
            NPC_DATABASE_INFO_PRINT = GetTime()+300
		end
		BANETO_NPCDB_AUTO_REPAIR = true

	end
	if not _G.BANETO_DEFINED_VENDOR_GOODS[1]  or not _G.BANETO_DEFINED_VENDOR_GOODS[1][1] then
		BANETO_DefineGoodsVendor(BANETO_GetClosestNpc("Goods"))
		if not BANETO_ISRUNNING_1CLICKFARM and BANETO_DEFINED_PROFILE_TYPE ~= "Questing" and (not NPC_DATABASE_INFO_PRINT or NPC_DATABASE_INFO_PRINT < GetTime())  then
			BANETO_PrintProfile("BANETO will use a database NPC for GOODS!")
            NPC_DATABASE_INFO_PRINT = GetTime()+300
		end
		BANETO_NPCDB_AUTO_GOODS = true
	end
	return true

end

function _G.BANETO_DragonridingTraceUpward()
    local x1,y1,z1 = BANETO_ObjectPosition("player")
    local x2,y2,z2 = BANETO_ObjectPosition("player")
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+1, x2,y2,z2+25, hitFlags)
    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
        return false
    else
        return true
    end
end

function _G.BANETO_DragonridingTraceUpwardShort()
    local x1,y1,z1 = BANETO_ObjectPosition("player")
    local x2,y2,z2 = BANETO_ObjectPosition("player")
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1, x2,y2,z2+6, hitFlags)
    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
        return false
    else
        return true
    end
end

function _G.BANETO_DragonridingTraceForward()
    local x1,y1,z1 = BANETO_ObjectPosition("player")
    local x2,y2,z2 = BANETO_GetPointInfrontOfUsWithDistance(25)
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1, x2,y2,z2-6, hitFlags)
    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
        return false
    else
        return true
    end
end

function _G.BANETO_GePlayerAngle()
    return BANETO_GetObjectFacing("player")
end

function _G.BANETO_GetClosestNpc(npctype)
	local faction,_ = UnitFactionGroup("player")
	if Unlocker("LUA") then
		continent = BANETO_GetMapId()
	elseif Unlocker("EWT") then
		continent,_,_ = GetMapId()
	end
	--BANETO_PrintBambo("Check npc db!")
	local continentName = BANETO_continentNames[continent]
	if faction == "Horde" then
		if continent == 1 then
			BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["Kalimdor"]
		elseif continent == 0 then
			BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["Eastern Kingdoms"]
        elseif continent == 2222 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["The Shadowlands"]
        elseif continent == 571 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["Northrend"]
        elseif continent == 1642 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["Zuldazar"]
        elseif continent == 2601 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype]["Khaz Algar"]
        elseif continentName and BANETO_NPCS_VENDORS_HORDE[npctype] and BANETO_NPCS_VENDORS_HORDE[npctype][continentName] then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_HORDE[npctype][continentName]
		end
	elseif faction == "Alliance" then
		if continent == 1 then
			BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["Kalimdor"]
		elseif continent == 0 then
			BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["Eastern Kingdoms"]
        elseif continent == 2222 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["The Shadowlands"]
        elseif continent == 571 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["Northrend"]
        elseif continent == 1642 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["Zuldazar"]
        elseif continent == 2601 then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype]["Khaz Algar"]
        elseif continentName and BANETO_NPCS_VENDORS_ALLIANCE[npctype] and BANETO_NPCS_VENDORS_ALLIANCE[npctype][continentName] then
            BANETO_NPCS_VENDOR_TABLE = BANETO_NPCS_VENDORS_ALLIANCE[npctype][continentName]
		end
	end
    local zone = BANETO_GetZoneId()
    local foundVendor = false;
	if Unlocker("LUA") and BANETO_NPCS_VENDOR_TABLE then
		local bestDistance = 99999999
		local bestNpcX, bestNpcY, bestNpcZ = nil,nil,nil
		for i = 1, #BANETO_NPCS_VENDOR_TABLE do
			local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
			local npcX, npcY, npcZ = BANETO_NPCS_VENDOR_TABLE[i][1],BANETO_NPCS_VENDOR_TABLE[i][2],BANETO_NPCS_VENDOR_TABLE[i][3]
			local npcId = BANETO_NPCS_VENDOR_TABLE[i][4]
			local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,npcX, npcY, npcZ)
			local zoneIdForVendor = BANETO_NPCS_VENDOR_TABLE[i][7]
			if distance < bestDistance and not IsVendorOrTrainerBlacklisted(npcId) and zone and zoneIdForVendor and zoneIdForVendor == zone then
				bestNpcX = npcX
				bestNpcY = npcY
				bestNpcZ = npcZ
				bestNpcId = npcId
				bestDistance = distance
				--BANETO_PrintBambo("Found vendor in current zone")
				foundVendor = true
			end
		end
		if not foundVendor or foundVendor == false then
            for i = 1, #BANETO_NPCS_VENDOR_TABLE do
                local playerX, playerY, playerZ = BANETO_ObjectPosition("player")
                local npcX, npcY, npcZ = BANETO_NPCS_VENDOR_TABLE[i][1],BANETO_NPCS_VENDOR_TABLE[i][2],BANETO_NPCS_VENDOR_TABLE[i][3]
                local npcId = BANETO_NPCS_VENDOR_TABLE[i][4]
                local distance = BANETO_GetDistance3D(playerX, playerY, playerZ,npcX, npcY, npcZ)
                local zoneIdForVendor = BANETO_NPCS_VENDOR_TABLE[i][7]
                if distance < bestDistance and not IsVendorOrTrainerBlacklisted(npcId) then
                    bestNpcX = npcX
                    bestNpcY = npcY
                    bestNpcZ = npcZ
                    bestNpcId = npcId
                    bestDistance = distance
                    --BANETO_PrintBambo("Found vendor in other zone")
                end
            end
		end
		return bestNpcX,bestNpcY,bestNpcZ,bestNpcId
	end
end
    if _internal.Software() == "tnk" then
        local Draw = Tinkr.Util.Draw:New()
        local Common = Tinkr.Common
        local ObjectManager = Tinkr.Util.ObjectManager

        Draw:Sync(function(draw)
            local px, py, pz = ObjectPosition('player')
            if not px or not py or not pz then
                return
            end

            if BANETO_DRAW_CIRCLES and #BANETO_DRAW_CIRCLES >= 1 then
                for i=1,#BANETO_DRAW_CIRCLES do
                    local xDraw,zDraw,yDraw,radius,col = BANETO_DRAW_CIRCLES[i][1],BANETO_DRAW_CIRCLES[i][2],BANETO_DRAW_CIRCLES[i][3],BANETO_DRAW_CIRCLES[i][4],BANETO_DRAW_CIRCLES[i][5]
                    draw:SetColor(col)
                    draw:Circle(xDraw,zDraw,yDraw, radius,rad(10))
                end
            end
            if BANETO_DRAW_LINE and #BANETO_DRAW_LINE >= 1 then
                for i=1,#BANETO_DRAW_LINE do
                    local xDraw,zDraw,yDraw,xXDraw,zZDraw,yYDraw,col = BANETO_DRAW_LINE[i][1],BANETO_DRAW_LINE[i][2],BANETO_DRAW_LINE[i][3],BANETO_DRAW_LINE[i][4],BANETO_DRAW_LINE[i][5],BANETO_DRAW_LINE[i][6],BANETO_DRAW_LINE[i][7]
                    draw:SetColor(col)
                    draw:Line(xDraw,zDraw,yDraw, xXDraw,zZDraw,yYDraw, 300)
                end
            end
            if BANETO_DRAW_TEXT and #BANETO_DRAW_TEXT >= 1 then
                for i=1,#BANETO_DRAW_TEXT do
                    local xDraw,zDraw,yDraw,text,col = BANETO_DRAW_TEXT[i][1],BANETO_DRAW_TEXT[i][2],BANETO_DRAW_TEXT[i][3],BANETO_DRAW_TEXT[i][4],BANETO_DRAW_TEXT[i][5]
                    draw:SetColor(col)
                    draw:Text(text,"GameFontNormal", xDraw, zDraw, yDraw)
                end
            end

            if REAPER_SETTING_VISUALS == true then
                for i=1,#REAPER_DEFINED_SPOTS do
                    local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS[i][1],REAPER_DEFINED_SPOTS[i][2],REAPER_DEFINED_SPOTS[i][3],REAPER_DEFINED_SPOTS[i][4],REAPER_DEFINED_SPOTS[i][5]
                    draw:SetColor(draw.colors.white)
                    draw:Text("Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                    if type == "Waypoint" then
                        draw:Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Waitpoint" then
                        draw:SetColor(draw.colors.yellow)
                        draw:Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Fightpoint" then
                        draw:SetColor(draw.colors.red)
                        draw:Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Interactpoint" then
                        draw:SetColor(draw.colors.blue)
                        draw:Text("Interactpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    end
                end
                if REAPER_ENTRANCE then
                    local x,y,z = REAPER_ENTRANCE[1],REAPER_ENTRANCE[2],REAPER_ENTRANCE[3]
                    draw:SetColor(draw.colors.white)
                    draw:Text("ENTRANCE!","GameFontNormal", x,y,z+3)
                    draw:Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                end
                if REAPER_EXIT then
                    local x,y,z = REAPER_EXIT[1],REAPER_EXIT[2],REAPER_EXIT[3]
                    draw:SetColor(draw.colors.white)
                    draw:Text("EXIT!","GameFontNormal", x,y,z+3)
                    draw:Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                end

                if #REAPER_DEFINED_SPOTS_EDITOR > 0 then
                    for i=1,#REAPER_DEFINED_SPOTS_EDITOR do
                        local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS_EDITOR[i][1],REAPER_DEFINED_SPOTS_EDITOR[i][2],REAPER_DEFINED_SPOTS_EDITOR[i][3],REAPER_DEFINED_SPOTS_EDITOR[i][4],REAPER_DEFINED_SPOTS_EDITOR[i][5]
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                        if type == "Waypoint" then
                            draw:Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Waitpoint" then
                            draw:SetColor(draw.colors.yellow)
                            draw:Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Fightpoint" then
                            draw:SetColor(draw.colors.red)
                            draw:Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        end
                    end
                end
                if REAPER_ENTRANCE_EDITOR then
                    local x,y,z = REAPER_ENTRANCE_EDITOR[1],REAPER_ENTRANCE_EDITOR[2],REAPER_ENTRANCE_EDITOR[3]
                    if x and y and z then
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-ENTRANCE!","GameFontNormal", x,y,z+3)
                        draw:Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end
                if REAPER_EXIT_EDITOR then
                    local x,y,z = REAPER_EXIT_EDITOR[1],REAPER_EXIT_EDITOR[2],REAPER_EXIT_EDITOR[3]
                    if x and y and z then
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-EXIT!","GameFontNormal",x,y,z+3)
                        draw:Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end

            end


            if BANETO_EDITOR_GRINDGATHER_RECORDCLICK == true then
                -- draw the cursor position in world
                local mx, my, mz = Common.ScreenToWorld(GetCursorPosition())
                draw:SetColor(draw.colors.white)
                draw:Circle(mx, my, mz, 0.5)
            end
            local playerHeight = ObjectHeight('player')
            local playerRadius = ObjectBoundingRadius('player')
            local combatReach = ObjectCombatReach('player')

            local rotation = BANETO_GetObjectFacing("player")
            local rx, ry, rz = RotateVector(px, py, pz, rotation, playerRadius)

            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE and #BANETO_UNSTUCK_ROUTES_TABLE >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            draw:SetColor(draw.colors.pink)
                            draw:Text('Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                draw:Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                     draw:SetColor(draw.colors.yellow)
                                     draw:Circle(xDraw,zDraw,yDraw-0.5, radius1)
                                end
                            end
                            if z == #cacheTable then
                                draw:Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            draw:SetColor(draw.colors.pink)
                            draw:Circle(xDraw,zDraw,yDraw,2.0)
                        end
                    end
                end
            end
            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE_PROFILES and #BANETO_UNSTUCK_ROUTES_TABLE_PROFILES >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE_PROFILES do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            draw:SetColor(draw.colors.pink)
                            draw:Text('P-Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                draw:Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                     draw:SetColor(draw.colors.yellow)
                                     draw:Circle(xDraw,zDraw,yDraw-0.5, radius1)
                                end
                            end
                            if z == #cacheTable then
                                draw:Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            draw:SetColor(draw.colors.pink)
                            draw:Circle(xDraw,zDraw,yDraw,2.0)
                        end
                    end
                end
            end
            if BANETO_RECORDING_UNSTUCKROUTE then
                if not BANETO_UNSTUCKROUTE_CACHE then
                    draw:SetColor(draw.colors.red)
                    draw:Text('Record 1st spot in stuck area', "GameFontNormal", px, py, pz-2)
                    draw:SetColor(draw.colors.pink)
                    draw:Circle(px, py, pz,2.0)
                else
                    for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                        local xDraw,zDraw,yDraw = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                        draw:SetColor(draw.colors.pink)
                        draw:Text('Unstuck-Spot: ' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                        draw:Circle(xDraw,zDraw,yDraw,2.0)
                    end
                    if #BANETO_UNSTUCKROUTE_CACHE >= 1 then
                        for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                            if i == #BANETO_UNSTUCKROUTE_CACHE then
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = px, py, pz
                                local maxD = 300
                                draw:SetColor(draw.colors.grey)
                                draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                            else
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = BANETO_UNSTUCKROUTE_CACHE[i+1][1],BANETO_UNSTUCKROUTE_CACHE[i+1][2],BANETO_UNSTUCKROUTE_CACHE[i+1][3]
                                local maxD = 300
                                draw:SetColor(draw.colors.pink)
                                draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                            end
                        end
                    end
                end
            end
            if BANETO_SETTING_VISUAL_PATH == true then
                if IsFlying() and BANETO_IsRunning() then
                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_ObjectPosition("player")
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+1, x2,y2,z2+25, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        draw:SetColor(draw.colors.red)
                    else
                        draw:SetColor(draw.colors.green)
                    end
                    local maxD = 150
                    draw:Line(x1, y1, z1+1, x2, y2, z2+25, maxD)

                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_GetPointInfrontOfUsWithDistance(25)
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1, x2,y2,z2-6, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        draw:SetColor(draw.colors.red)
                    else
                        draw:SetColor(draw.colors.green)
                    end
                    local maxD = 150
                    draw:Line(x1, y1, z1, x2, y2, z2-6, maxD)
                end
                if waterHits and #waterHits and BANETO_State == "FISHING-SPOT" then
                    for i = 1,#waterHits do
                        local x,y,z = waterHits[i][1],waterHits[i][2],waterHits[i][3]
                        draw:SetColor(draw.colors.blue)
                        draw:Text('.', "GameFontNormal", x,y,z)
                    end
                end
                if groundHits and #groundHits and BANETO_State == "FISHING-SPOT" then
                    for i = 1,#groundHits do
                        local x,y,z = groundHits[i][1],groundHits[i][2],groundHits[i][3]
                        draw:SetColor(draw.colors.green)
                        draw:Text('.', "GameFontNormal", x,y,z)
                    end
                end

                if BANETO_ESCAPE_PATH and #BANETO_ESCAPE_PATH > 1 and BANETO_State == "FLEE" then
                    for i=1,#BANETO_ESCAPE_PATH-1 do
                        local x1, y1, z1 = BANETO_ESCAPE_PATH[i][1],BANETO_ESCAPE_PATH[i][2],BANETO_ESCAPE_PATH[i][3]
                        local x2, y2, z2 = BANETO_ESCAPE_PATH[i+1][1],BANETO_ESCAPE_PATH[i+1][2],BANETO_ESCAPE_PATH[i+1][3]
                        local maxD = 200
                        draw:SetColor(draw.colors.red)
                        draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end

                if waPath and #waPath > 1 then
                    for i=pathIndex,#waPath-1 do
                        local x1, y1, z1 = waPath[i].x,waPath[i].y,waPath[i].z
                        if i == 1 then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = waPath[i+1].x,waPath[i+1].y,waPath[i+1].z
                        local maxD = 300
                        draw:SetColor(draw.colors.white)
                        draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end

                if flyingPath then
                    for i=flyingPathIndex,#flyingPath-1 do
                        local x1, y1, z1 = flyingPath[i].x,flyingPath[i].y,flyingPath[i].z
                        if i == flyingPathIndex then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = flyingPath[i+1].x,flyingPath[i+1].y,flyingPath[i+1].z
                        local maxD = 300
                        draw:SetColor(draw.colors.white)
                        draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end
            end
            if BANETO_SETTING_VISUAL_SPOTS == true then
                local centers = BANETO_GetDefinedCenters()
                local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                local centerSpotDistanceForDraw = 99999
                if centers and #centers and #centers >= 50 then
                    centerSpotDistanceForDraw = 200
                end
                for i=1,#centers do
                    local xDraw,zDraw,yDraw,radiusDraw = centers[i][1],centers[i][2],centers[i][3],centers[i][4]
                    local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,xPlayer, yPlayer, zPlayer)
                    if distance and centerSpotDistanceForDraw >= distance then
                        if i == centerIndex or (swarmFishingIndex and swarmFishingIndex == i) then
                            draw:SetColor(draw.colors.orange)
                            draw:Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --draw:Circle(xDraw,zDraw,yDraw,1.0)
                        else
                            draw:SetColor(draw.colors.white)
                            draw:Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --draw:Circle(xDraw,zDraw,yDraw,1.0)
                        end
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                            draw:SetColor(draw.colors.yellow)
                            draw:Circle(xDraw, zDraw, yDraw, radiusDraw)
                        end
                    end
                end
                local centerslanding = BANETO_SETTING_LANDINGSPOTS
                if centerslanding and #centerslanding then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslanding do
                        local xDraw,zDraw,yDraw,map = centerslanding[i][1],centerslanding[i][2],centerslanding[i][3],centerslanding[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                draw:SetColor(draw.colors.yellow)
                                draw:Text('LANDING #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                local centerslandingP = BANETO_SETTING_LANDINGSPOTS_PROFILE
                if centerslandingP and #centerslandingP then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslandingP do
                        local xDraw,zDraw,yDraw,map = centerslandingP[i][1],centerslandingP[i][2],centerslandingP[i][3],centerslandingP[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                draw:SetColor(draw.colors.yellow)
                                draw:Text('LANDING-PROFILE #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Center" then
                            draw:SetColor(draw.colors.blue)
                        else
                            draw:SetColor(draw.colors.white)
                        end
                        draw:Text('EDITOR-SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                        draw:Circle(xDraw,zDraw,yDraw,1.0)
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                             draw:SetColor(draw.colors.yellow)
                             draw:Circle(xDraw, zDraw, yDraw, radiusDraw)
                        end
                    end
                end
                if BANETO_DEFINED_FIGHT_CENTERS and #BANETO_DEFINED_FIGHT_CENTERS > 0 then
                    local xDraw,zDraw,yDraw = BANETO_DEFINED_FIGHT_CENTERS[1][1],BANETO_DEFINED_FIGHT_CENTERS[1][2],BANETO_DEFINED_FIGHT_CENTERS[1][3]
                    draw:Text('FIGHT-SPOT!', "GameFontNormal", xDraw,zDraw,yDraw)
                end
            end
            if _G.BANETO_BLACKLIST_TRACELINES  then
                for i=1,#_G.BANETO_BLACKLIST_TRACELINES do
                    local x,y,z = _G.BANETO_BLACKLIST_TRACELINES[i][1][1],_G.BANETO_BLACKLIST_TRACELINES[i][1][2],_G.BANETO_BLACKLIST_TRACELINES[i][1][3]
                    local xx,yy,zz = _G.BANETO_BLACKLIST_TRACELINES[i][2][1],_G.BANETO_BLACKLIST_TRACELINES[i][2][2],_G.BANETO_BLACKLIST_TRACELINES[i][2][3]
                    local xxx,yyy,zzz = _G.BANETO_BLACKLIST_TRACELINES[i][3][1],_G.BANETO_BLACKLIST_TRACELINES[i][3][2],_G.BANETO_BLACKLIST_TRACELINES[i][3][3]
                    if x and y and z and xx and yy and zz then
                        draw:SetColor(draw.colors.white)
                        draw:Line(x,y,z,xx,yy,zz,500)
                    end
                    if xxx and yyy and zzz then
                        draw:SetColor(draw.colors.red)
                        draw:Circle(xxx,yyy,zzz,1)
                    end
                end
            end

            if BANETO_EDITOR_MOVE_spotIndex then
                draw:SetColor(draw.colors.blue)
                draw:Text('Selected ' .. BANETO_EDITOR_MOVE_spotType .. ' Spot: ' .. BANETO_EDITOR_MOVE_spotIndex, "GameFontNormal", px, py, pz+1)
                draw:Text('Press shift to clear selection', "GameFontNormal", px, py, pz)
                draw:Text('Press alt to delete selected spot', "GameFontNormal", px, py, pz-0.4)
            end

            if BANETO_SETTING_VISUAL_BLACKLISTS == true then
                for i=1,#BANETO_DEFINED_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_DEFINED_BLACKLIST_SPOTS[i][1],BANETO_DEFINED_BLACKLIST_SPOTS[i][2],BANETO_DEFINED_BLACKLIST_SPOTS[i][3],BANETO_DEFINED_BLACKLIST_SPOTS[i][4]
                    draw:SetColor(draw.colors.white)
                    draw:Text('P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    draw:SetColor(draw.colors.red)
                    draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                for i=1,#BANETO_GLOBAL_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_GLOBAL_BLACKLIST_SPOTS[i][1],BANETO_GLOBAL_BLACKLIST_SPOTS[i][2],BANETO_GLOBAL_BLACKLIST_SPOTS[i][3],BANETO_GLOBAL_BLACKLIST_SPOTS[i][4]
                    draw:SetColor(draw.colors.white)
                    draw:Text('G-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    draw:SetColor(draw.colors.red)
                    draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Blacklist" then
                            draw:SetColor(draw.colors.blue)
                        else
                            draw:SetColor(draw.colors.white)
                        end
                        draw:Text('EDITOR-P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                        draw:SetColor(draw.colors.red)
                        draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                    end
                end
            end

            if (BANETO_SETTING_VISUAL_UNITESP and BANETO_SETTING_VISUAL_UNITESP == true) then
                for object in ObjectManager:Objects() do
                    if(ObjectType(object) == 5) then
                        local name = BANETO_ObjectName(object)
                        local height = ObjectHeight(object) or 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = Common.Distance(px, py, pz, x, y, z)
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColorFromObject(object)
                                local hx, hy, hz = BANETO_TraceLine(px, py, pz + playerHeight, x, y, z + height, Common.HitFlags.All)
                                if hx ~= 0 or hy ~= 0 or hz ~= 0 then
                                    draw:SetAlpha(48)
                                else
                                    draw:SetAlpha(196)
                                end

                                local angleBetween = Common.GetAnglesBetweenPositions(px, py, pz, x, y, z)
                                local sx, sy, sz = Common.GetPositionFromPosition(px, py, pz, playerRadius, angleBetween, 0)
                                local id = BANETO_ObjectId(object) or 0
                                draw:Text((name or "Obj") .. " (" .. Common.Round(distance, 1) .. "-" ..id..")", "GameFontNormal", x, y, z + height)
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_PLAYERESP and BANETO_SETTING_VISUAL_PLAYERESP == true) then
                for object in ObjectManager:Objects() do
                    if(ObjectType(object) == 6 or ObjectType(object) == 7) then
                        local name = BANETO_ObjectName(object)
                        local height = ObjectHeight(object) or 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = Common.Distance(px, py, pz, x, y, z)
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColorFromObject(object)
                                local hx, hy, hz = BANETO_TraceLine(px, py, pz + playerHeight, x, y, z + height, Common.HitFlags.All)
                                if hx ~= 0 or hy ~= 0 or hz ~= 0 then
                                    draw:SetAlpha(48)
                                else
                                    draw:SetAlpha(196)
                                end

                                local angleBetween = Common.GetAnglesBetweenPositions(px, py, pz, x, y, z)
                                local sx, sy, sz = Common.GetPositionFromPosition(px, py, pz, playerRadius, angleBetween, 0)
                                local id = BANETO_ObjectId(object) or 0
                                draw:Text((name or "Obj") .. " (" .. Common.Round(distance, 1) .. ")", "GameFontNormal", x, y, z + height)
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_OBJECTESP and BANETO_SETTING_VISUAL_OBJECTESP == true) then
                for object in ObjectManager:Objects() do
                    if(ObjectType(object) ~= 6 and ObjectType(object) ~= 5 and ObjectType(object) ~= 7) then
                        local name = BANETO_ObjectName(object)
                        local height = ObjectHeight(object) or 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = Common.Distance(px, py, pz, x, y, z)
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColorFromObject(object)
                                local hx, hy, hz = BANETO_TraceLine(px, py, pz + playerHeight, x, y, z + height, Common.HitFlags.All)
                                if hx ~= 0 or hy ~= 0 or hz ~= 0 then
                                    draw:SetAlpha(48)
                                else
                                    draw:SetAlpha(196)
                                end

                                local angleBetween = Common.GetAnglesBetweenPositions(px, py, pz, x, y, z)
                                local sx, sy, sz = Common.GetPositionFromPosition(px, py, pz, playerRadius, angleBetween, 0)
                                local id = BANETO_ObjectId(object) or 0
                                draw:Text((name or "Obj") .. " (" .. Common.Round(distance, 1) .. "-" ..id..")", "GameFontNormal", x, y, z + height)
                            end
                        end
                    end
                end
            end
            if ARCH_X and ARCH_Y and ARCH_Z then
                draw:SetColor(draw.colors.white)
                draw:Text("ARCH-SPOT","GameFontNormal", ARCH_X, ARCH_Y, ARCH_Z)
            end
        end)

        Draw:Enable()
    elseif _internal.Software() == "nn" and not BANETO_IsJin() then


        local Draw = Tinkr.Utils.Draw:New()
        Draw:Sync(function(draw)
            local px, py, pz = BANETO_ObjectPosition('player')

            if ARCH_X and ARCH_Y and ARCH_Z then
                draw:SetColor(draw.colors.white)
                draw:Text("ARCH-SPOT","GameFontNormal", ARCH_X, ARCH_Y, ARCH_Z)
            end

            if BANETO_DRAW_CIRCLES and #BANETO_DRAW_CIRCLES >= 1 then
                for i=1,#BANETO_DRAW_CIRCLES do
                    local xDraw,zDraw,yDraw,radius,col = BANETO_DRAW_CIRCLES[i][1],BANETO_DRAW_CIRCLES[i][2],BANETO_DRAW_CIRCLES[i][3],BANETO_DRAW_CIRCLES[i][4],BANETO_DRAW_CIRCLES[i][5]
                    draw:SetColor(col)
                    draw:Circle(xDraw,zDraw,yDraw, radius,rad(10))
                end
            end
            if BANETO_DRAW_LINE and #BANETO_DRAW_LINE >= 1 then
                for i=1,#BANETO_DRAW_LINE do
                    local xDraw,zDraw,yDraw,xXDraw,zZDraw,yYDraw,col = BANETO_DRAW_LINE[i][1],BANETO_DRAW_LINE[i][2],BANETO_DRAW_LINE[i][3],BANETO_DRAW_LINE[i][4],BANETO_DRAW_LINE[i][5],BANETO_DRAW_LINE[i][6],BANETO_DRAW_LINE[i][7]
                    draw:SetColor(col)
                    draw:Line(xDraw,zDraw,yDraw, xXDraw,zZDraw,yYDraw, 300)
                end
            end
            if BANETO_DRAW_TEXT and #BANETO_DRAW_TEXT >= 1 then
                for i=1,#BANETO_DRAW_TEXT do
                    local xDraw,zDraw,yDraw,text,col = BANETO_DRAW_TEXT[i][1],BANETO_DRAW_TEXT[i][2],BANETO_DRAW_TEXT[i][3],BANETO_DRAW_TEXT[i][4],BANETO_DRAW_TEXT[i][5]
                    draw:SetColor(col)
                    draw:Text(text,"GameFontNormal", xDraw, zDraw, yDraw)
                end
            end

            if REAPER_SETTING_VISUALS == true then
                for i=1,#REAPER_DEFINED_SPOTS do
                    local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS[i][1],REAPER_DEFINED_SPOTS[i][2],REAPER_DEFINED_SPOTS[i][3],REAPER_DEFINED_SPOTS[i][4],REAPER_DEFINED_SPOTS[i][5]
                    draw:SetColor(draw.colors.white)
                    draw:Text("Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                    if type == "Waypoint" then
                        draw:Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Waitpoint" then
                        draw:SetColor(draw.colors.yellow)
                        draw:Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Fightpoint" then
                        draw:SetColor(draw.colors.red)
                        draw:Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Interactpoint" then
                        draw:SetColor(draw.colors.blue)
                        draw:Text("Interactpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    end
                end
                if REAPER_ENTRANCE then
                    local x,y,z = REAPER_ENTRANCE[1],REAPER_ENTRANCE[2],REAPER_ENTRANCE[3]
                    draw:SetColor(draw.colors.white)
                    draw:Text("ENTRANCE!","GameFontNormal", x,y,z+3)
                    draw:Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                end
                if REAPER_EXIT then
                    local x,y,z = REAPER_EXIT[1],REAPER_EXIT[2],REAPER_EXIT[3]
                    draw:SetColor(draw.colors.white)
                    draw:Text("EXIT!","GameFontNormal", x,y,z+3)
                    draw:Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                end

                if #REAPER_DEFINED_SPOTS_EDITOR > 0 then
                    for i=1,#REAPER_DEFINED_SPOTS_EDITOR do
                        local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS_EDITOR[i][1],REAPER_DEFINED_SPOTS_EDITOR[i][2],REAPER_DEFINED_SPOTS_EDITOR[i][3],REAPER_DEFINED_SPOTS_EDITOR[i][4],REAPER_DEFINED_SPOTS_EDITOR[i][5]
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                        if type == "Waypoint" then
                            draw:Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Waitpoint" then
                            draw:SetColor(draw.colors.yellow)
                            draw:Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Fightpoint" then
                            draw:SetColor(draw.colors.red)
                            draw:Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        end
                    end
                end
                if REAPER_ENTRANCE_EDITOR then
                    local x,y,z = REAPER_ENTRANCE_EDITOR[1],REAPER_ENTRANCE_EDITOR[2],REAPER_ENTRANCE_EDITOR[3]
                    if x and y and z then
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-ENTRANCE!","GameFontNormal", x,y,z+3)
                        draw:Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end
                if REAPER_EXIT_EDITOR then
                    local x,y,z = REAPER_EXIT_EDITOR[1],REAPER_EXIT_EDITOR[2],REAPER_EXIT_EDITOR[3]
                    if x and y and z then
                        draw:SetColor(draw.colors.white)
                        draw:Text("EDITOR-EXIT!","GameFontNormal",x,y,z+3)
                        draw:Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end

            end





            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE and #BANETO_UNSTUCK_ROUTES_TABLE >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            draw:SetColor(draw.colors.pink)
                            draw:Text('Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                draw:Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                     draw:SetColor(draw.colors.yellow)
                                     draw:Circle(xDraw,zDraw,yDraw-0.5, radius1,rad(10))
                                end
                            end
                            if z == #cacheTable then
                                draw:Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            draw:SetColor(draw.colors.pink)
                            draw:Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                        end
                    end
                end
            end
            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE_PROFILES and #BANETO_UNSTUCK_ROUTES_TABLE_PROFILES >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE_PROFILES do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            draw:SetColor(draw.colors.pink)
                            draw:Text('P-Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                draw:Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                     draw:SetColor(draw.colors.yellow)
                                     draw:Circle(xDraw,zDraw,yDraw-0.5, radius1,rad(10))
                                end
                            end
                            if z == #cacheTable then
                                draw:Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            draw:SetColor(draw.colors.pink)
                            draw:Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                        end
                    end
                end
            end
            if BANETO_Customer() == "bambo" and BANETO_ISRUNNING then
                if xSlope and ySlope and zSlope  then
                    local maxD = 300
                    draw:SetColor(draw.colors.grey)
                    draw:Line(px, py, pz+0.9, xSlope, ySlope, zSlope, maxD)
                end
                if xSlope2 and ySlope2 and zSlope2  then
                    local maxD = 300
                    draw:SetColor(draw.colors.grey)
                    draw:Line(px, py, pz+3, xSlope2, ySlope2, zSlope2, maxD)
                end
            end
            if BANETO_RECORDING_UNSTUCKROUTE then
                if not BANETO_UNSTUCKROUTE_CACHE then
                    draw:SetColor(draw.colors.red)
                    draw:Text('Record 1st spot in stuck area', "GameFontNormal", px, py, pz-2)
                    draw:SetColor(draw.colors.pink)
                    draw:Circle(px, py, pz,2.0,rad(10))
                else
                    for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                        local xDraw,zDraw,yDraw = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                        draw:SetColor(draw.colors.pink)
                        draw:Text('Unstuck-Spot: ' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                        draw:Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                    end
                    if #BANETO_UNSTUCKROUTE_CACHE >= 1 then
                        for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                            if i == #BANETO_UNSTUCKROUTE_CACHE then
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = px, py, pz
                                local maxD = 300
                                draw:SetColor(draw.colors.grey)
                                draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                            else
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = BANETO_UNSTUCKROUTE_CACHE[i+1][1],BANETO_UNSTUCKROUTE_CACHE[i+1][2],BANETO_UNSTUCKROUTE_CACHE[i+1][3]
                                local maxD = 300
                                draw:SetColor(draw.colors.pink)
                                draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                            end
                        end
                    end
                end
            end

            if BANETO_SETTING_VISUAL_PATH == true then
                if IsFlying() and BANETO_IsRunning() then
                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_ObjectPosition("player")
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+1, x2,y2,z2+25, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        draw:SetColor(draw.colors.red)
                    else
                        draw:SetColor(draw.colors.green)
                    end
                    local maxD = 150
                    draw:Line(x1, y1, z1+1, x2, y2, z2+25, maxD)

                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_GetPointInfrontOfUsWithDistance(25)
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1, x2,y2,z2-6, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        draw:SetColor(draw.colors.red)
                    else
                        draw:SetColor(draw.colors.green)
                    end
                    local maxD = 150
                    draw:Line(x1, y1, z1, x2, y2, z2-6, maxD)
                end
                if groundHits and #groundHits and BANETO_State == "FISHING-SPOT" then
                    for i = 1,#groundHits do
                        local x,y,z = groundHits[i][1],groundHits[i][2],groundHits[i][3]
                        draw:SetColor(draw.colors.green)
                        draw:Text('.', "GameFontNormal", x,y,z)
                    end
                end

                if BANETO_ESCAPE_PATH and #BANETO_ESCAPE_PATH > 1 and BANETO_State == "FLEE" then
                    for i=1,#BANETO_ESCAPE_PATH-1 do
                        local x1, y1, z1 = BANETO_ESCAPE_PATH[i][1],BANETO_ESCAPE_PATH[i][2],BANETO_ESCAPE_PATH[i][3]
                        local x2, y2, z2 = BANETO_ESCAPE_PATH[i+1][1],BANETO_ESCAPE_PATH[i+1][2],BANETO_ESCAPE_PATH[i+1][3]
                        local maxD = 200
                        draw:SetColor(draw.colors.red)
                        draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end

                if waPathBufferCopy and #waPathBufferCopy > 1 and not IsFlying() and waPath then
                    local xPlayer,yPlayer,zPlayer = BANETO_ObjectPosition("player")
                    for i=pathIndex,#waPathBufferCopy-1 do
                        local x1, y1, z1 = waPathBufferCopy[i].x,waPathBufferCopy[i].y,waPathBufferCopy[i].z
                        if i == 1 then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = waPathBufferCopy[i+1].x,waPathBufferCopy[i+1].y,waPathBufferCopy[i+1].z
                        local maxD = 150
                        x1,y1,z1,x2,y2,z2 = tonumber(x1),tonumber(y1),tonumber(z1),tonumber(x2),tonumber(y2),tonumber(z2)
                        if type(x1) == "number" and type(y1) == "number" and type(z1) == "number"  and type(x2) == "number" and type(y2) == "number"  and type(z2) == "number" then
                            local distance = BANETO_GetDistance3D(x1, y1, z1,xPlayer,yPlayer,zPlayer)
                            if distance and distance < maxD then
                                draw:SetColor(draw.colors.white)
                                draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                            end
                        end
                    end
                end
                if nnAvoidPath and #nnAvoidPath > 1 and not IsFlying() then
                    for i=1,#nnAvoidPath-1 do
                        local x1, y1, z1 = nnAvoidPath[i].x,nnAvoidPath[i].y,nnAvoidPath[i].z
                        local x2, y2, z2 = nnAvoidPath[i+1].x,nnAvoidPath[i+1].y,nnAvoidPath[i+1].z
                        local maxD = 150
                        draw:SetColor(draw.colors.orange)
                        x1,y1,z1,x2,y2,z2 = tonumber(x1),tonumber(y1),tonumber(z1),tonumber(x2),tonumber(y2),tonumber(z2)
                        if x1 ~= x2 and type(x1) == "number" and type(y1) == "number" and type(z1) == "number"  and type(x2) == "number" and type(y2) == "number"  and type(z2) == "number" then
                            draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                        end
                    end
                end

                if flyingPath then
                    for i=flyingPathIndex,#flyingPath-1 do
                        local x1, y1, z1 = flyingPath[i].x,flyingPath[i].y,flyingPath[i].z
                        if i == flyingPathIndex then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = flyingPath[i+1].x,flyingPath[i+1].y,flyingPath[i+1].z
                        local maxD = 300
                        draw:SetColor(draw.colors.white)
                        draw:Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end
            end
            if _G.BANETO_BLACKLIST_TRACELINES  then
                for i=1,#_G.BANETO_BLACKLIST_TRACELINES do
                    local x,y,z = _G.BANETO_BLACKLIST_TRACELINES[i][1][1],_G.BANETO_BLACKLIST_TRACELINES[i][1][2],_G.BANETO_BLACKLIST_TRACELINES[i][1][3]
                    local xx,yy,zz = _G.BANETO_BLACKLIST_TRACELINES[i][2][1],_G.BANETO_BLACKLIST_TRACELINES[i][2][2],_G.BANETO_BLACKLIST_TRACELINES[i][2][3]
                    local xxx,yyy,zzz = _G.BANETO_BLACKLIST_TRACELINES[i][3][1],_G.BANETO_BLACKLIST_TRACELINES[i][3][2],_G.BANETO_BLACKLIST_TRACELINES[i][3][3]
                    if x and y and z and xx and yy and zz then
                        draw:SetColor(draw.colors.white)
                        draw:Line(x,y,z,xx,yy,zz,500)
                    end
                    if xxx and yyy and zzz then
                        draw:SetColor(draw.colors.red)
                        draw:Circle(xxx,yyy,zzz,1,rad(10))
                    end
                end
            end
            if BANETO_SETTING_VISUAL_SPOTS == true then
                local centers = BANETO_GetDefinedCenters()
                local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                local centerSpotDistanceForDraw = 99999
                if centers and #centers and #centers >= 50 then
                    centerSpotDistanceForDraw = 200
                end
                for i=1,#centers do
                    local xDraw,zDraw,yDraw,radiusDraw = centers[i][1],centers[i][2],centers[i][3],centers[i][4]
                    local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,xPlayer, yPlayer, zPlayer)
                    if distance and centerSpotDistanceForDraw >= distance then
                        if i == centerIndex or (swarmFishingIndex and swarmFishingIndex == i) then
                            draw:SetColor(draw.colors.orange)
                            draw:Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --draw:Circle(xDraw,zDraw,yDraw,1.0)
                        else
                            draw:SetColor(draw.colors.white)
                            draw:Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --draw:Circle(xDraw,zDraw,yDraw,1.0)
                        end
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                            draw:SetColor(draw.colors.yellow)
                            draw:Circle(xDraw, zDraw, yDraw, radiusDraw)
                        end
                    end
                end

                local centerslanding = BANETO_SETTING_LANDINGSPOTS
                if centerslanding and #centerslanding then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslanding do
                        local xDraw,zDraw,yDraw,map = centerslanding[i][1],centerslanding[i][2],centerslanding[i][3],centerslanding[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                draw:SetColor(draw.colors.yellow)
                                draw:Text('LANDING #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                local centerslandingP = BANETO_SETTING_LANDINGSPOTS_PROFILE
                if centerslandingP and #centerslandingP then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslandingP do
                        local xDraw,zDraw,yDraw,map = centerslandingP[i][1],centerslandingP[i][2],centerslandingP[i][3],centerslandingP[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                draw:SetColor(draw.colors.yellow)
                                draw:Text('LANDING-PROFILE #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Center" then
                            draw:SetColor(draw.colors.blue)
                        else
                            draw:SetColor(draw.colors.white)
                        end
                        draw:Text('EDITOR-SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                        --draw:Circle(xDraw,zDraw,yDraw,1.0)
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                             draw:SetColor(draw.colors.yellow)
                             draw:Circle(xDraw, zDraw, yDraw, radiusDraw,rad(10))
                        end
                    end
                end
                if BANETO_DEFINED_FIGHT_CENTERS and #BANETO_DEFINED_FIGHT_CENTERS > 0 then
                    local xDraw,zDraw,yDraw = BANETO_DEFINED_FIGHT_CENTERS[1][1],BANETO_DEFINED_FIGHT_CENTERS[1][2],BANETO_DEFINED_FIGHT_CENTERS[1][3]
                    draw:Text('FIGHT-SPOT!', "GameFontNormal", xDraw,zDraw,yDraw)
                end
            end

            if BANETO_EDITOR_MOVE_spotIndex then
                draw:SetColor(draw.colors.blue)
                draw:Text('Selected ' .. BANETO_EDITOR_MOVE_spotType .. ' Spot: ' .. BANETO_EDITOR_MOVE_spotIndex, "GameFontNormal", px, py, pz+1)
                draw:Text('Press shift to clear selection', "GameFontNormal", px, py, pz)
                draw:Text('Press alt to delete selected spot', "GameFontNormal", px, py, pz-0.4)
            end

            if BANETO_SETTING_VISUAL_BLACKLISTS == true then
                for i=1,#BANETO_DEFINED_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_DEFINED_BLACKLIST_SPOTS[i][1],BANETO_DEFINED_BLACKLIST_SPOTS[i][2],BANETO_DEFINED_BLACKLIST_SPOTS[i][3],BANETO_DEFINED_BLACKLIST_SPOTS[i][4]
                    draw:SetColor(draw.colors.white)
                    draw:Text('P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    draw:SetColor(draw.colors.red)
                    draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                for i=1,#BANETO_GLOBAL_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_GLOBAL_BLACKLIST_SPOTS[i][1],BANETO_GLOBAL_BLACKLIST_SPOTS[i][2],BANETO_GLOBAL_BLACKLIST_SPOTS[i][3],BANETO_GLOBAL_BLACKLIST_SPOTS[i][4]
                    draw:SetColor(draw.colors.white)
                    draw:Text('G-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    draw:SetColor(draw.colors.red)
                    draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Blacklist" then
                            draw:SetColor(draw.colors.blue)
                        else
                            draw:SetColor(draw.colors.white)
                        end
                        draw:Text('EDITOR-P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                        draw:SetColor(draw.colors.red)
                        draw:Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                    end
                end
            end

            if (BANETO_SETTING_VISUAL_UNITESP and BANETO_SETTING_VISUAL_UNITESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYUNITS do
                    local object = BANETO_OBJTS_TKR_ONLYUNITS[i]
                    if(ObjectType(object) == 5) then
                        local name = BANETO_ObjectName(object)
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColor(draw.colors.white)
                                local id = BANETO_ObjectId(object) or 0
                                draw:Text((name or "Obj") .. " (" .. distance .. "y-" ..id..")", "GameFontNormal", x, y, z )
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_PLAYERESP and BANETO_SETTING_VISUAL_PLAYERESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYPLAYERS do
                    local object = BANETO_OBJTS_TKR_ONLYPLAYERS[i]
                    if(ObjectType(object) == 6 or ObjectType(object) == 7) then
                        local name = BANETO_ObjectName(object)
                        local height = 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColor(draw.colors.red)
                                draw:Text((name or "Obj") .. " (" .. distance .. "y)", "GameFontNormal", x, y, z)
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_OBJECTESP and BANETO_SETTING_VISUAL_OBJECTESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYGAMEOBJECTS do
                    local object = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS[i]
                    if(ObjectType(object) ~= 6 and ObjectType(object) ~= 5 and ObjectType(object) ~= 7) then
                        local name = BANETO_ObjectName(object)
                        local height = 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                draw:SetColor(draw.colors.yellow)
                                local id = BANETO_ObjectId(object) or 0
                                draw:Text((name or "Obj") .. " (" .. distance .. "y-" ..id..")", "GameFontNormal", x, y, z + height)
                            end
                        end
                    end
                end
            end
        end)

        Draw:Enable()
    elseif _internal.Software() == "nn" and BANETO_IsJin() then

        local Draw = Tinkr.Utils.Draw
        Draw.Sync(function(draw)
            local px, py, pz = BANETO_ObjectPosition('player')

            if ARCH_X and ARCH_Y and ARCH_Z then
                Draw.SetColor(Draw.colors.white)
                Draw.Text("ARCH-SPOT","GameFontNormal", ARCH_X, ARCH_Y, ARCH_Z)
            end

            if BANETO_DRAW_CIRCLES and #BANETO_DRAW_CIRCLES >= 1 then
                for i=1,#BANETO_DRAW_CIRCLES do
                    local xDraw,zDraw,yDraw,radius,col = BANETO_DRAW_CIRCLES[i][1],BANETO_DRAW_CIRCLES[i][2],BANETO_DRAW_CIRCLES[i][3],BANETO_DRAW_CIRCLES[i][4],BANETO_DRAW_CIRCLES[i][5]
                    Draw.SetColor(col)
                    Draw.Circle(xDraw,zDraw,yDraw, radius,rad(10))
                end
            end
            if BANETO_DRAW_LINE and #BANETO_DRAW_LINE >= 1 then
                for i=1,#BANETO_DRAW_LINE do
                    local xDraw,zDraw,yDraw,xXDraw,zZDraw,yYDraw,col = BANETO_DRAW_LINE[i][1],BANETO_DRAW_LINE[i][2],BANETO_DRAW_LINE[i][3],BANETO_DRAW_LINE[i][4],BANETO_DRAW_LINE[i][5],BANETO_DRAW_LINE[i][6],BANETO_DRAW_LINE[i][7]
                    Draw.SetColor(col)
                    Draw.Line(xDraw,zDraw,yDraw, xXDraw,zZDraw,yYDraw, 300)
                end
            end
            if BANETO_DRAW_TEXT and #BANETO_DRAW_TEXT >= 1 then
                for i=1,#BANETO_DRAW_TEXT do
                    local xDraw,zDraw,yDraw,text,col = BANETO_DRAW_TEXT[i][1],BANETO_DRAW_TEXT[i][2],BANETO_DRAW_TEXT[i][3],BANETO_DRAW_TEXT[i][4],BANETO_DRAW_TEXT[i][5]
                    Draw.SetColor(col)
                    Draw.Text(text,"GameFontNormal", xDraw, zDraw, yDraw)
                end
            end

            if REAPER_SETTING_VISUALS == true then
                for i=1,#REAPER_DEFINED_SPOTS do
                    local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS[i][1],REAPER_DEFINED_SPOTS[i][2],REAPER_DEFINED_SPOTS[i][3],REAPER_DEFINED_SPOTS[i][4],REAPER_DEFINED_SPOTS[i][5]
                    Draw.SetColor(Draw.colors.white)
                    Draw.Text("Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                    if type == "Waypoint" then
                        Draw.Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Waitpoint" then
                        Draw.SetColor(Draw.colors.yellow)
                        Draw.Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Fightpoint" then
                        Draw.SetColor(Draw.colors.red)
                        Draw.Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    elseif type == "Interactpoint" then
                        Draw.SetColor(Draw.colors.blue)
                        Draw.Text("Interactpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                    end
                end
                if REAPER_ENTRANCE then
                    local x,y,z = REAPER_ENTRANCE[1],REAPER_ENTRANCE[2],REAPER_ENTRANCE[3]
                    Draw.SetColor(Draw.colors.white)
                    Draw.Text("ENTRANCE!","GameFontNormal", x,y,z+3)
                    Draw.Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                end
                if REAPER_EXIT then
                    local x,y,z = REAPER_EXIT[1],REAPER_EXIT[2],REAPER_EXIT[3]
                    Draw.SetColor(Draw.colors.white)
                    Draw.Text("EXIT!","GameFontNormal", x,y,z+3)
                    Draw.Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                end

                if #REAPER_DEFINED_SPOTS_EDITOR > 0 then
                    for i=1,#REAPER_DEFINED_SPOTS_EDITOR do
                        local xDraw,zDraw,yDraw,value,type = REAPER_DEFINED_SPOTS_EDITOR[i][1],REAPER_DEFINED_SPOTS_EDITOR[i][2],REAPER_DEFINED_SPOTS_EDITOR[i][3],REAPER_DEFINED_SPOTS_EDITOR[i][4],REAPER_DEFINED_SPOTS_EDITOR[i][5]
                        Draw.SetColor(Draw.colors.white)
                        Draw.Text("EDITOR-Spot: ".. i,"GameFontNormal", xDraw, zDraw, yDraw+3)
                        if type == "Waypoint" then
                            Draw.Text("Waypoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Waitpoint" then
                            Draw.SetColor(Draw.colors.yellow)
                            Draw.Text("Waitpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        elseif type == "Fightpoint" then
                            Draw.SetColor(Draw.colors.red)
                            Draw.Text("Fightpoint","GameFontNormal", xDraw, zDraw, yDraw+2)
                        end
                    end
                end
                if REAPER_ENTRANCE_EDITOR then
                    local x,y,z = REAPER_ENTRANCE_EDITOR[1],REAPER_ENTRANCE_EDITOR[2],REAPER_ENTRANCE_EDITOR[3]
                    if x and y and z then
                        Draw.SetColor(Draw.colors.white)
                        Draw.Text("EDITOR-ENTRANCE!","GameFontNormal", x,y,z+3)
                        Draw.Text("Outside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end
                if REAPER_EXIT_EDITOR then
                    local x,y,z = REAPER_EXIT_EDITOR[1],REAPER_EXIT_EDITOR[2],REAPER_EXIT_EDITOR[3]
                    if x and y and z then
                        Draw.SetColor(Draw.colors.white)
                        Draw.Text("EDITOR-EXIT!","GameFontNormal",x,y,z+3)
                        Draw.Text("Inside Dungeon","GameFontNormal", x,y,z+2)
                    end
                end

            end





            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE and #BANETO_UNSTUCK_ROUTES_TABLE >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            Draw.SetColor(Draw.colors.pink)
                            Draw.Text('Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                Draw.Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                    Draw.SetColor(Draw.colors.yellow)
                                    Draw.Circle(xDraw,zDraw,yDraw-0.5, radius1,rad(10))
                                end
                            end
                            if z == #cacheTable then
                                Draw.Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            Draw.SetColor(Draw.colors.pink)
                            Draw.Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                        end
                    end
                end
            end
            if BANETO_SETTING_VISUAL_UNSTUCKS == true and BANETO_UNSTUCK_ROUTES_TABLE_PROFILES and #BANETO_UNSTUCK_ROUTES_TABLE_PROFILES >= 1 then
                for i=1,#BANETO_UNSTUCK_ROUTES_TABLE_PROFILES do
                    local cacheTable = BANETO_UNSTUCK_ROUTES_TABLE_PROFILES[i]
                    for z=1,#cacheTable do
                        local xDraw,zDraw,yDraw,radius1 = cacheTable[z][1],cacheTable[z][2],cacheTable[z][3],cacheTable[z][4]
                        local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,px, py, pz)
                        if distance and 100 > distance then
                            Draw.SetColor(Draw.colors.pink)
                            Draw.Text('P-Unstuck-Spot: ' .. i .. '#' .. z, "GameFontNormal", xDraw,zDraw,yDraw)
                            if z == 1 then
                                Draw.Text('TRIGGER', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                                if radius1 and BANETO_SETTING_VISUAL_CENTERRADII then
                                    Draw.SetColor(Draw.colors.yellow)
                                    Draw.Circle(xDraw,zDraw,yDraw-0.5, radius1,rad(10))
                                end
                            end
                            if z == #cacheTable then
                                Draw.Text('END', "GameFontNormal", xDraw,zDraw,yDraw-0.5)
                            end
                            Draw.SetColor(Draw.colors.pink)
                            Draw.Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                        end
                    end
                end
            end
            if BANETO_Customer() == "bambo" and BANETO_ISRUNNING then
                if xSlope and ySlope and zSlope  then
                    local maxD = 300
                    Draw.SetColor(Draw.colors.grey)
                    Draw.Line(px, py, pz+0.9, xSlope, ySlope, zSlope, maxD)
                end
                if xSlope2 and ySlope2 and zSlope2  then
                    local maxD = 300
                    Draw.SetColor(Draw.colors.grey)
                    Draw.Line(px, py, pz+3, xSlope2, ySlope2, zSlope2, maxD)
                end
            end
            if BANETO_RECORDING_UNSTUCKROUTE then
                if not BANETO_UNSTUCKROUTE_CACHE then
                    Draw.SetColor(Draw.colors.red)
                    Draw.Text('Record 1st spot in stuck area', "GameFontNormal", px, py, pz-2)
                    Draw.SetColor(Draw.colors.pink)
                    Draw.Circle(px, py, pz,2.0,rad(10))
                else
                    for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                        local xDraw,zDraw,yDraw = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                        Draw.SetColor(Draw.colors.pink)
                        Draw.Text('Unstuck-Spot: ' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                        Draw.Circle(xDraw,zDraw,yDraw,2.0,rad(10))
                    end
                    if #BANETO_UNSTUCKROUTE_CACHE >= 1 then
                        for i=1,#BANETO_UNSTUCKROUTE_CACHE do
                            if i == #BANETO_UNSTUCKROUTE_CACHE then
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = px, py, pz
                                local maxD = 300
                                Draw.SetColor(Draw.colors.grey)
                                Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                            else
                                local x1, y1, z1 = BANETO_UNSTUCKROUTE_CACHE[i][1],BANETO_UNSTUCKROUTE_CACHE[i][2],BANETO_UNSTUCKROUTE_CACHE[i][3]
                                local x2, y2, z2 = BANETO_UNSTUCKROUTE_CACHE[i+1][1],BANETO_UNSTUCKROUTE_CACHE[i+1][2],BANETO_UNSTUCKROUTE_CACHE[i+1][3]
                                local maxD = 300
                                Draw.SetColor(Draw.colors.pink)
                                Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                            end
                        end
                    end
                end
            end

            if BANETO_SETTING_VISUAL_PATH == true then
                if IsFlying() and BANETO_IsRunning() then
                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_ObjectPosition("player")
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1+1, x2,y2,z2+25, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        Draw.SetColor(Draw.colors.red)
                    else
                        Draw.SetColor(Draw.colors.green)
                    end
                    local maxD = 150
                    Draw.Line(x1, y1, z1+1, x2, y2, z2+25, maxD)

                    local x1,y1,z1 = BANETO_ObjectPosition("player")
                    local x2,y2,z2 = BANETO_GetPointInfrontOfUsWithDistance(25)
                    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000)
                    local xH1, yH1, zH1 = BANETO_TraceLine(x1, y1, z1, x2,y2,z2-6, hitFlags)
                    if xH1 and xH1 ~= 0 and yH1 and yH1 ~= 0 and zH1 and zH1 ~= 0 then
                        Draw.SetColor(Draw.colors.red)
                    else
                        Draw.SetColor(Draw.colors.green)
                    end
                    local maxD = 150
                    Draw.Line(x1, y1, z1, x2, y2, z2-6, maxD)
                end
                if groundHits and #groundHits and BANETO_State == "FISHING-SPOT" then
                    for i = 1,#groundHits do
                        local x,y,z = groundHits[i][1],groundHits[i][2],groundHits[i][3]
                        Draw.SetColor(Draw.colors.green)
                        Draw.Text('.', "GameFontNormal", x,y,z)
                    end
                end

                if BANETO_ESCAPE_PATH and #BANETO_ESCAPE_PATH > 1 and BANETO_State == "FLEE" then
                    for i=1,#BANETO_ESCAPE_PATH-1 do
                        local x1, y1, z1 = BANETO_ESCAPE_PATH[i][1],BANETO_ESCAPE_PATH[i][2],BANETO_ESCAPE_PATH[i][3]
                        local x2, y2, z2 = BANETO_ESCAPE_PATH[i+1][1],BANETO_ESCAPE_PATH[i+1][2],BANETO_ESCAPE_PATH[i+1][3]
                        local maxD = 200
                        Draw.SetColor(Draw.colors.red)
                        Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end

                if waPathBufferCopy and #waPathBufferCopy > 1 and not IsFlying() and waPath then
                    local xPlayer,yPlayer,zPlayer = BANETO_ObjectPosition("player")
                    for i=pathIndex,#waPathBufferCopy-1 do
                        local x1, y1, z1 = waPathBufferCopy[i].x,waPathBufferCopy[i].y,waPathBufferCopy[i].z
                        if i == 1 then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = waPathBufferCopy[i+1].x,waPathBufferCopy[i+1].y,waPathBufferCopy[i+1].z
                        local maxD = 150
                        x1,y1,z1,x2,y2,z2 = tonumber(x1),tonumber(y1),tonumber(z1),tonumber(x2),tonumber(y2),tonumber(z2)
                        if type(x1) == "number" and type(y1) == "number" and type(z1) == "number"  and type(x2) == "number" and type(y2) == "number"  and type(z2) == "number" then
                            local distance = BANETO_GetDistance3D(x1, y1, z1,xPlayer,yPlayer,zPlayer)
                            if distance and distance < maxD then
                                Draw.SetColor(Draw.colors.white)
                                Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                            end
                        end
                    end
                end
                if nnAvoidPath and #nnAvoidPath > 1 and not IsFlying() then
                    for i=1,#nnAvoidPath-1 do
                        local x1, y1, z1 = nnAvoidPath[i].x,nnAvoidPath[i].y,nnAvoidPath[i].z
                        local x2, y2, z2 = nnAvoidPath[i+1].x,nnAvoidPath[i+1].y,nnAvoidPath[i+1].z
                        local maxD = 150
                        Draw.SetColor(Draw.colors.orange)
                        x1,y1,z1,x2,y2,z2 = tonumber(x1),tonumber(y1),tonumber(z1),tonumber(x2),tonumber(y2),tonumber(z2)
                        if x1 ~= x2 and type(x1) == "number" and type(y1) == "number" and type(z1) == "number"  and type(x2) == "number" and type(y2) == "number"  and type(z2) == "number" then
                            Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                        end
                    end
                end

                if flyingPath then
                    for i=flyingPathIndex,#flyingPath-1 do
                        local x1, y1, z1 = flyingPath[i].x,flyingPath[i].y,flyingPath[i].z
                        if i == flyingPathIndex then
                            x1,y1,z1 = BANETO_ObjectPosition("player")
                        end
                        local x2, y2, z2 = flyingPath[i+1].x,flyingPath[i+1].y,flyingPath[i+1].z
                        local maxD = 300
                        Draw.SetColor(Draw.colors.white)
                        Draw.Line(x1, y1, z1, x2, y2, z2, maxD)
                    end
                end
            end
            if _G.BANETO_BLACKLIST_TRACELINES  then
                for i=1,#_G.BANETO_BLACKLIST_TRACELINES do
                    local x,y,z = _G.BANETO_BLACKLIST_TRACELINES[i][1][1],_G.BANETO_BLACKLIST_TRACELINES[i][1][2],_G.BANETO_BLACKLIST_TRACELINES[i][1][3]
                    local xx,yy,zz = _G.BANETO_BLACKLIST_TRACELINES[i][2][1],_G.BANETO_BLACKLIST_TRACELINES[i][2][2],_G.BANETO_BLACKLIST_TRACELINES[i][2][3]
                    local xxx,yyy,zzz = _G.BANETO_BLACKLIST_TRACELINES[i][3][1],_G.BANETO_BLACKLIST_TRACELINES[i][3][2],_G.BANETO_BLACKLIST_TRACELINES[i][3][3]
                    if x and y and z and xx and yy and zz then
                        Draw.SetColor(Draw.colors.white)
                        Draw.Line(x,y,z,xx,yy,zz,500)
                    end
                    if xxx and yyy and zzz then
                        Draw.SetColor(Draw.colors.red)
                        Draw.Circle(xxx,yyy,zzz,1,rad(10))
                    end
                end
            end
            if BANETO_SETTING_VISUAL_SPOTS == true then
                local centers = BANETO_GetDefinedCenters()
                local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                local centerSpotDistanceForDraw = 99999
                if centers and #centers and #centers >= 50 then
                    centerSpotDistanceForDraw = 200
                end
                for i=1,#centers do
                    local xDraw,zDraw,yDraw,radiusDraw = centers[i][1],centers[i][2],centers[i][3],centers[i][4]
                    local distance = BANETO_GetDistance3D(xDraw,zDraw,yDraw,xPlayer, yPlayer, zPlayer)
                    if distance and centerSpotDistanceForDraw >= distance then
                        if i == centerIndex or (swarmFishingIndex and swarmFishingIndex == i) then
                            Draw.SetColor(Draw.colors.orange)
                            Draw.Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --Draw.Circle(xDraw,zDraw,yDraw,1.0)
                        else
                            Draw.SetColor(Draw.colors.white)
                            Draw.Text('SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                            --Draw.Circle(xDraw,zDraw,yDraw,1.0)
                        end
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                            Draw.SetColor(Draw.colors.yellow)
                            Draw.Circle(xDraw, zDraw, yDraw, radiusDraw)
                        end
                    end
                end

                local centerslanding = BANETO_SETTING_LANDINGSPOTS
                if centerslanding and #centerslanding then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslanding do
                        local xDraw,zDraw,yDraw,map = centerslanding[i][1],centerslanding[i][2],centerslanding[i][3],centerslanding[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                Draw.SetColor(Draw.colors.yellow)
                                Draw.Text('LANDING #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                local centerslandingP = BANETO_SETTING_LANDINGSPOTS_PROFILE
                if centerslandingP and #centerslandingP then
                    local cmap = BANETO_GetMapId()
                    local xPlayer, yPlayer, zPlayer = ObjectPosition("player")
                    for i=1,#centerslandingP do
                        local xDraw,zDraw,yDraw,map = centerslandingP[i][1],centerslandingP[i][2],centerslandingP[i][3],centerslandingP[i][4]
                        if map == cmap then
                            local di = BANETO_GetDistance3D(xPlayer, yPlayer, zPlayer,xDraw,zDraw,yDraw)
                            if di and 100>di then
                                Draw.Text('LANDING-PROFILE #' .. i, "GameFontNormal", xDraw,zDraw,yDraw)
                            end
                        end
                    end
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Center" then
                            Draw.SetColor(Draw.colors.blue)
                        else
                            Draw.SetColor(Draw.colors.white)
                        end
                        Draw.Text('EDITOR-SPOT: ' .. i.." - ".. radiusDraw .. "y", "GameFontNormal", xDraw,zDraw,yDraw)
                        --Draw.Circle(xDraw,zDraw,yDraw,1.0)
                        if BANETO_SETTING_VISUAL_CENTERRADII and BANETO_SETTING_VISUAL_CENTERRADII == true then
                            Draw.SetColor(Draw.colors.yellow)
                            Draw.Circle(xDraw, zDraw, yDraw, radiusDraw,rad(10))
                        end
                    end
                end
                if BANETO_DEFINED_FIGHT_CENTERS and #BANETO_DEFINED_FIGHT_CENTERS > 0 then
                    local xDraw,zDraw,yDraw = BANETO_DEFINED_FIGHT_CENTERS[1][1],BANETO_DEFINED_FIGHT_CENTERS[1][2],BANETO_DEFINED_FIGHT_CENTERS[1][3]
                    Draw.Text('FIGHT-SPOT!', "GameFontNormal", xDraw,zDraw,yDraw)
                end
            end

            if BANETO_EDITOR_MOVE_spotIndex then
                Draw.SetColor(Draw.colors.blue)
                Draw.Text('Selected ' .. BANETO_EDITOR_MOVE_spotType .. ' Spot: ' .. BANETO_EDITOR_MOVE_spotIndex, "GameFontNormal", px, py, pz+1)
                Draw.Text('Press shift to clear selection', "GameFontNormal", px, py, pz)
                Draw.Text('Press alt to delete selected spot', "GameFontNormal", px, py, pz-0.4)
            end

            if BANETO_SETTING_VISUAL_BLACKLISTS == true then
                for i=1,#BANETO_DEFINED_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_DEFINED_BLACKLIST_SPOTS[i][1],BANETO_DEFINED_BLACKLIST_SPOTS[i][2],BANETO_DEFINED_BLACKLIST_SPOTS[i][3],BANETO_DEFINED_BLACKLIST_SPOTS[i][4]
                    Draw.SetColor(Draw.colors.white)
                    Draw.Text('P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    Draw.SetColor(Draw.colors.red)
                    Draw.Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                for i=1,#BANETO_GLOBAL_BLACKLIST_SPOTS do
                    local xDraw,zDraw,yDraw,radiusDraw = BANETO_GLOBAL_BLACKLIST_SPOTS[i][1],BANETO_GLOBAL_BLACKLIST_SPOTS[i][2],BANETO_GLOBAL_BLACKLIST_SPOTS[i][3],BANETO_GLOBAL_BLACKLIST_SPOTS[i][4]
                    Draw.SetColor(Draw.colors.white)
                    Draw.Text('G-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                    Draw.SetColor(Draw.colors.red)
                    Draw.Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                end
                if #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS > 0 then
                    for i=1,#BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS do
                        local xDraw,zDraw,yDraw,radiusDraw = BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][1],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][2],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][3],BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[i][4]
                        if BANETO_EDITOR_MOVE_spotIndex and BANETO_EDITOR_MOVE_spotIndex == i and BANETO_EDITOR_MOVE_spotType == "Blacklist" then
                            Draw.SetColor(Draw.colors.blue)
                        else
                            Draw.SetColor(Draw.colors.white)
                        end
                        Draw.Text('EDITOR-P-BLACKLIST-SPOT: ' .. radiusDraw .. ' yards', "GameFontNormal", xDraw,zDraw,yDraw)
                        Draw.SetColor(Draw.colors.red)
                        Draw.Circle(xDraw,zDraw,yDraw,radiusDraw,rad(10))
                    end
                end
            end

            if (BANETO_SETTING_VISUAL_UNITESP and BANETO_SETTING_VISUAL_UNITESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYUNITS do
                    local object = BANETO_OBJTS_TKR_ONLYUNITS[i]
                    if(ObjectType(object) == 5) then
                        local name = BANETO_ObjectName(object)
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                Draw.SetColor(Draw.colors.white)
                                local id = BANETO_ObjectId(object) or 0
                                Draw.Text((name or "Obj") .. " (" .. distance .. "y-" ..id..")", "GameFontNormal", x, y, z )
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_PLAYERESP and BANETO_SETTING_VISUAL_PLAYERESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYPLAYERS do
                    local object = BANETO_OBJTS_TKR_ONLYPLAYERS[i]
                    if(ObjectType(object) == 6 or ObjectType(object) == 7) then
                        local name = BANETO_ObjectName(object)
                        local height = 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                Draw.SetColor(Draw.colors.red)
                                Draw.Text((name or "Obj") .. " (" .. distance .. "y)", "GameFontNormal", x, y, z)
                            end
                        end
                    end
                end
            end
            if (BANETO_SETTING_VISUAL_OBJECTESP and BANETO_SETTING_VISUAL_OBJECTESP == true) then
                for i=1, #BANETO_OBJTS_TKR_ONLYGAMEOBJECTS do
                    local object = BANETO_OBJTS_TKR_ONLYGAMEOBJECTS[i]
                    if(ObjectType(object) ~= 6 and ObjectType(object) ~= 5 and ObjectType(object) ~= 7) then
                        local name = BANETO_ObjectName(object)
                        local height = 1
                        local x, y, z = ObjectPosition(object)
                        if x and y and z then
                            local distance = math.ceil(BANETO_GetDistance3D(px, py, pz, x, y, z))
                            if distance < _G.BANETO_OBJECT_DRAW_DISTANCES then
                                Draw.SetColor(Draw.colors.yellow)
                                local id = BANETO_ObjectId(object) or 0
                                Draw.Text((name or "Obj") .. " (" .. distance .. "y-" ..id..")", "GameFontNormal", x, y, z + height)
                            end
                        end
                    end
                end
            end
        end)

        Draw.Enable(0)

    end
