	local evadeListener = CreateFrame("Frame")
	evadeListener:RegisterEvent("UNIT_COMBAT")
	evadeListener:SetScript("OnEvent", function(self, event, time, arg1, arg2, arg3, ...)
		if event == "UNIT_COMBAT" and (BANETO_State == "FIGHTING" or BANETO_State == "CLEAR-PATH") then
			if arg1 == "EVADE" or arg2 == "EVADE" or arg3 == "EVADE" then
				BANETO_PrintError("EVADE detected! Blacklisting Mob and moving away! Fighting blocked for 10 Seconds.")
				if BANETO_TARGET then
				    if Unlocker("LUA") then
				        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
				    elseif Unlocker("EWT") then
				        local guid = ObjectGUID(BANETO_TARGET)
				        BANETO_AddMobToGuidBlacklist(guid)
				    end
                    BANETO_ClearTarget()
					BANETO_TARGET = nil
				end
				BANETO_STOPFIGHT_EVADE = GetTime()+15
				if BANETO_DEFINED_PROFILE_TYPE == "Grinding" then
					BANETO_State = "GRIND"
					BANETO_TARGET = nil
					BANETO_GATHER_DELAY = nil
					BANETO_GATHER_DEBUG_TIMER = nil
					BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
					if Unlocker("LUA") and lb  then
						__LB__.Unlock(ClearTarget)
					elseif CallSecureFunction then
					    CallSecureFunction("ClearTarget")
					elseif Unlocker("EWT") then
						ClearTarget()
					end
				end
				if BANETO_DEFINED_PROFILE_TYPE == "Traveling" then
					BANETO_State = "TRAVEL"
					BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
				end
				if BANETO_DEFINED_PROFILE_TYPE == "Questing" then
					BANETO_State = "QUEST-MASTER"
					BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
					if Unlocker("LUA") then
						BANETO_ClearTarget()
					elseif Unlocker("EWT") then
						ClearTarget()
					end
				end
				if BANETO_DEFINED_PROFILE_TYPE == "Fishing" then
                    if BANETO_PROFILE_NAME == "Skill-Fishing" then
                        BANETO_State = "FISHING-SKILL"
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    else
                        BANETO_State = "FISHING-SPOT"
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    end
				end
			end
		end
	end)

    function _G.BANETO_FilterAiAnswer(msg)
        local result1 = msg:gsub('"', '')
        local result2 = result1:gsub('scrub', 'dude')
        local result3 = result2:gsub('noob', 'dude')
        local result = result3:gsub('git gud', 'try')
        return result
    end

    local function BANETO_AiResponder(sender,msg)
            local startPos, endPos = string.find(msg, "guild")
            if (BANETO_AI_WHISPER_COUNT[sender] and BANETO_AI_WHISPER_COUNT[sender] > 3) or startPos or msg == "np" or msg == "Np" or msg == "ty" or msg == "bye" or (BANETO_BLOCK_AI_WHISPER_REPLY and BANETO_BLOCK_AI_WHISPER_REPLY > GetTime()) then
                return false
            end
            local payloadTable = {
                sender = sender,
                message = msg,
                tok = "7f2WTaP1DpNfmAZlLKtl0aUMaurw88Zr4FhQ2NbqwseiYlkyLx0ufYKtutRGCjYe"
            }
            --lang = BANETO_GetLocale(),
            --tick = BANETO_AI_WHISPER_COUNT[sender] or 1,
            --to = UnitName("player"),
            local payload = BANETO_JsonEncode(payloadTable)
            local url1 = 'http://anotherwhisper.com:8370/req/response'
            local function callbackfunction(status, data)
                if status == 200 then
                    BANETO_PrintBambo("AI ANSWER 200")
                    local response = BANETO_JsonDecode(data)
                    if BANETO_IsRunning() and response and response.reply then
                        local random = math.random(4,7)
                        local answer = BANETO_FilterAiAnswer(response.reply)
                        C_Timer.After(random,function()
                            BANETO_SendChatMessage(answer ,"WHISPER" ,"COMMON" ,sender)
                        end)
                    end
                    if BANETO_AI_WHISPER_TIMERS[sender] then
                        BANETO_AI_WHISPER_TIMERS[sender]:Cancel()
                    end
                elseif status == 201 then
                    BANETO_PrintBambo("AI ANSWER 201")
                    if BANETO_AI_WHISPER_TIMERS[sender] then
                        BANETO_AI_WHISPER_TIMERS[sender]:Cancel()
                    end
                    local random = math.random(5,9)
                    BANETO_AI_WHISPER_TIMERS[sender] = C_Timer.NewTimer(random,function()
                        BANETO_PrintBambo("AI ANSWER 202 RETRIGGER")
                        BANETO_AiResponder(sender,msg)
                    end)
                else
                    BANETO_PrintBambo("AI ANSWER ".. status)
                end
            end
            if BANETO_AI_WHISPER_COUNT[sender] then
                BANETO_AI_WHISPER_COUNT[sender] = BANETO_AI_WHISPER_COUNT[sender]+1
            else
                BANETO_AI_WHISPER_COUNT[sender] = 2
            end
            if _internal.Software() == "tnk" then
                local HTTP = Tinkr.Util.HTTP
                HTTP:Request({
                    url = url1,
                    method = 'POST',
                    body = payload,
                    headers = {
                        "Content-Type: application/json",
                        "Authorization: Bearer 39ff42f00f6c307ab4a9d723c44fdb98dfbdf4d9267ecd6f4b80d38fec8a5cb7"
                    },
                    callback = callbackfunction
                })
            elseif _internal.Software() == "nn" then
                HTTP:Request({
                    url = url1,
                    method = 'POST',
                    body = payload,
                    headers = {
                        "Content-Type: application/json",
                        "Authorization: Bearer 39ff42f00f6c307ab4a9d723c44fdb98dfbdf4d9267ecd6f4b80d38fec8a5cb7"
                    },
                    callback = callbackfunction
                })
            end
    end

    BANETO_MC_WHISPERS = ""
    BANETO_MC_WHISPER_COUNT = 0
    BANETO_AI_WHISPER_COUNT = { }
    BANETO_AI_WHISPER_TIMERS = { }
	local WhisperListener = CreateFrame("Frame")
	WhisperListener:RegisterEvent("CHAT_MSG_WHISPER")
	WhisperListener:SetScript("OnEvent", function(self, event, msg, sender, ...)
		if event == "CHAT_MSG_WHISPER" then
		    BANETO_LAST_SENDER = sender

            BANETO_MC_WHISPER_COUNT = BANETO_MC_WHISPER_COUNT+1

		    local date = date()
		    local input = date .. " " .. sender .. " said " .. msg .. ";"
		    BANETO_MC_WHISPERS = BANETO_MC_WHISPERS .. input

		end
		if event == "CHAT_MSG_WHISPER" and BANETO_SETTING_WHISPERLOGGING == true then
			if Unlocker("LUA") and _internal.Software() == "tnk"  then
		         local date = date()
				 WriteFile("scripts/baneto/logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt",date.. " " .. sender .. ": " .. msg.. "\n" ,true)
			end
            if Unlocker("LUA") and _internal.Software() == "nn"  then
                 local date = date()
                 if not FileExists(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt") then
                    WriteFile(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt","",false)
                 end
                 WriteFile(BANETO_GetBasePath() .."logfiles/Whisperlog-" .. BANETO_ObjectName("player") .. ".txt",date.. " " .. sender .. ": " .. msg.. "\n" ,true)
            end
		end

		if event == "CHAT_MSG_WHISPER" and BANETO_SETTING_PUSH_WHISPER and BANETO_SETTING_PUSH_WHISPER == true then
			BANETO_PUSH_PAYLOAD_WHISPERER = sender
			BANETO_PUSH_PAYLOAD_WHISPER = msg
			BANETO_PushNotification("Whisper")
		end
		if event == "CHAT_MSG_WHISPER" and BANETO_SETTING_DISCORD_WHISPER and BANETO_SETTING_DISCORD_WHISPER == true then
			BANETO_DiscordSendWhisper(sender,msg)
		end

		if BANETO_SETTING_WOWCLOSERWHISPER and BANETO_SETTING_WOWCLOSERWHISPER == true and event == "CHAT_MSG_WHISPER" then
			if not BANETO_WOWCLOSER_WHISPER_COUNT then
				BANETO_WOWCLOSER_WHISPER_COUNT = 0
			end
			if not BANETO_WOWCLOSER_WHISPER_LIMIT then
				BANETO_WOWCLOSER_WHISPER_LIMIT = 1
			end
			BANETO_WOWCLOSER_WHISPER_COUNT = BANETO_WOWCLOSER_WHISPER_COUNT +1
			if BANETO_WOWCLOSER_WHISPER_COUNT >= BANETO_WOWCLOSER_WHISPER_LIMIT then
				BANETO_WHISPER_CLOSENEEDED = true
			end
		end

        local fullName,fullRealm = UnitFullName("player")
		if BANETO_AUTORESPONDER and BANETO_AUTORESPONDER == true and BANETO_ISRUNNING and sender ~= fullName.."-"..fullRealm then
		    BANETO_PrintBambo("Whisper event AI from "..sender .. " for " .. fullName.."-"..fullRealm)
            BANETO_AiResponder(sender,msg)
		end


	end)


--[[ CREATE SETTINGS FOLDER --]]
	local function BANETO_SettingsFolder()
        if Unlocker("LUA") and _internal.Software() == "tnk" then
            local folders = ListDirectories("scripts")
            for i = 1,#folders do
                local folder = folders[i]
                if folder == "settings" then
                    return true
                end
            end
        end
		if Unlocker("LUA") and _internal.Software() == "nn" then
			local folders = ListDirectories(BANETO_GetBasePath() .."*")
			for i = 1,#folders do
				local folder = folders[i]
				if folder == "settings" then
					return true
				end
			end
		end
	end

	if not BANETO_SettingsFolder() then
		if Unlocker("LUA") and _internal.Software() == "tnk" then
			CreateDirectory("scripts/baneto/settings")
		end
        if Unlocker("LUA") and _internal.Software() == "nn" then
            CreateDirectory(BANETO_GetBasePath() .."settings")
        end
	end

