function _internal.BANETO_CheckClassForInstall(supportedClasses)
    if supportedClasses == "" then
        return true
    end
    local class,classEn,classNum = UnitClass("player")
    if classEn == "DemonHunter" or classEn == "Demon Hunter" or classEn == "Demonhunter" or classEn == "DEMONHUNTER" then
        classEn = "DEMON"
    end
    local startPos, endPos = string.find(supportedClasses, classEn)
    if startPos then
        return true
    end
end
function _internal.BANETO_RequestPaidComListingsResponse(res)
    for key, value in pairs(res) do
        local projectname = key
        local publicname = value.publicname
        local installtype = value.installType
        local profilesRaw = value.files
        local supportedClasses = value.supportedClasses or ""
        if _internal.BANETO_CheckClassForInstall(supportedClasses) then
            if publicname == "Death Knight Questline" then
                BANETO_PrintBambo("checking listing install: "..projectname .. " aka publicly known as " .. publicname)
            end
            BANETO_IsPaidListingInstalled(projectname,publicname,profilesRaw,installtype)
        end
    end
end

function _G.BANETO_WildcardCheck(itemname,wildcardString)
    local isWildcardString, endPos = string.find(wildcardString, "*")
    if isWildcardString then
        local resultString = string.gsub(wildcardString, "%*", "")
        local isWildcardFound, endPos = string.find(itemname, resultString)
        if isWildcardFound then
            return true
        end
    end
end

function _G.BANETO_IsGroupRegenerating()
    if (UnitExists("party1") and BANETO_IsUnitDeadOrGhost("party1")) or (UnitExists("party2") and BANETO_IsUnitDeadOrGhost("party2")) or (UnitExists("party3") and BANETO_IsUnitDeadOrGhost("party3")) or (UnitExists("party4") and BANETO_IsUnitDeadOrGhost("party4")) or (UnitExists("party5") and BANETO_IsUnitDeadOrGhost("party5")) then
        return true
    end

    if UnitExists("party1") and not UnitAffectingCombat("party1") and (BANETO_IsEatingDung("party1") or BANETO_IsDrinkingDung("party1") or BANETO_UnitHealth("party1") < 85) then
        return true
    end
    if UnitExists("party2") and not UnitAffectingCombat("party2") and (BANETO_IsEatingDung("party2") or BANETO_IsDrinkingDung("party2") or BANETO_UnitHealth("party2") < 85) then
        return true
    end
    if UnitExists("party3") and not UnitAffectingCombat("party3") and (BANETO_IsEatingDung("party3") or BANETO_IsDrinkingDung("party3") or BANETO_UnitHealth("party3") < 85) then
        return true
    end
    if UnitExists("party4") and not UnitAffectingCombat("party4") and (BANETO_IsEatingDung("party4") or BANETO_IsDrinkingDung("party4") or BANETO_UnitHealth("party4") < 85) then
        return true
    end
    if UnitExists("party5") and not UnitAffectingCombat("party5") and (BANETO_IsEatingDung("party5") or BANETO_IsDrinkingDung("party5") or BANETO_UnitHealth("party5") < 85) then
        return true
    end

end

function _internal.BANETO_RequestPaidComListings()
    local jsonPayload;
    local payload = {username = BANETO_Customer()}
    local url1 = ""    if _internal.Software() == "nn" then
        local JSON = Tinkr.Utils.JSON
        jsonPayload = JSON.encode(payload)
    elseif _internal.Software() == "tnk" then
        jsonPayload = json.encode(payload)
    end

    local function callbackdiscordlink(status,body)
       if status and (status == 200 or status == 204) then
            local response;
            if _internal.Software() == "nn" then
                local JSON = Tinkr.Utils.JSON
                response = JSON.decode(body)
            elseif _internal.Software() == "tnk" then
                response = json.decode(body)
            end
            _internal.BANETO_RequestPaidComListingsResponse(response)
       end
    end
    BANETO_HttpPost(url1,jsonPayload,callbackdiscordlink)
end


C_Timer.After(3,_internal.BANETO_RequestPaidComListings)

