if not BANETO_STATES_LOADED then

    BANETO_STATE_DELAY = GetTime()
    BANETO_RANDOMJUMP_DELAY = GetTime() + 15
    local BANETO_ENGADEDMOBS_RESETDELAY = GetTime()
    local BANETO_ITEMDELETER_DELAY = GetTime()
    local BANETO_TRIEDAMBUSH_RESTDELAY = GetTime()
    local BANETO_EWTPATHRESETFORMOBS = GetTime()
    local BANETO_LUAPATHRESETFORMOBS = GetTime()
    local BANETO_PETSPAWNWARLOCK_DELAY = GetTime()
    local BANETO_AUTOLOADPROFILES_DELAY = GetTime()
    local BANETO_CrackCheckTimer = GetTime() + 10
    local BANETO_ASCEND_STOPPER = GetTime()
    local HUNTER_REVIVE_DELAY = GetTime()
    BANETO_MOUNT_INDOORS_3SECS_STOPPER = GetTime()
    BANETO_ROGUEGOUGE_INPUT = 1
    BANETO_MAGE_POLY_DELAY = GetTime()
    --[[ ROTATION EXECUTER --]]
    function _G.BANETO_StateHandler(self)
        if _G.BANETO_OFF then
            return false
        end
        if BANETO_SWIMMING_DIVE and BANETO_SWIMMING_DIVE < GetTime()  then
            BANETO_DescendStop()
            BANETO_PrintState("Water Navigator - Dive stop")
            BANETO_SWIMMING_DIVE = nil
        end
        if BANETO_SWIMMING_DIVE_ASCEND and BANETO_SWIMMING_DIVE_ASCEND < GetTime()  then
            BANETO_AscendStop()
            BANETO_PrintState("Water Navigator - Ascend stop")
            BANETO_SWIMMING_DIVE_ASCEND = nil
        end
        if BANETO_STARTED_ASCEND and BANETO_STARTED_ASCEND < GetTime() and not UnitCastingInfo("player") and IsFlying() and not IsSwimming() then
            if Unlocker("EWT") then
                AscendStop()
            elseif Unlocker("LUA") then
                BANETO_AscendStop()
            end
            BANETO_PrintBambo("Stop ascend")
            BANETO_EXECUTE_FLY_ASCEND = nil
            BANETO_STARTED_ASCEND = nil
        end

        if flyingPath then
            if flyingPathDeleter and GetTime() > flyingPathDeleter then
                flyingPath = nil
                flyingPathDeleter = nil
            elseif not flyingPathDeleter then
                if BANETO_IsDragonRiding() then
                    flyingPathDeleter=GetTime()+5
                else
                    flyingPathDeleter=GetTime()+10
                end

            end
        end
        --[[ ON UPDATE FUNCTIONS --]]
        if (BANETO_ISRUNNING or REAPER_ISRUNNING) and BANETO_DISCORD_DELAY and BANETO_DISCORD_DELAY < GetTime() and BANETO_SETTING_DISCORD_STATUSUPDATE and BANETO_SETTING_DISCORD_STATUSUPDATE == true and BANETO_PUSHNOTIFICIATIONS_WEBHOOK and BANETO_PUSHNOTIFICIATIONS_WEBHOOK ~= "Enter your webhook url here!" then
            BANETO_DiscordSendStatus()
            BANETO_DISCORD_DELAY = GetTime()+_G.BANETO_DISCORD_DELAY_LENGTH
        end
        if (not globalFoodDrinkCounter or globalFoodDrinkCounter < GetTime()) or BANETO_State == "GOODS" then
            BANETO_FOOD_AMOUNT_GLOBAL = nil
            BANETO_DRINK_AMOUNT_GLOBAL = nil
            globalFoodDrinkCounter = GetTime()+10
        end
        if _internal.Software() == "nn" and BANETO_ISRUNNING  and not BANETO_BOBBER_RDY  and BANETO_DEFINED_PROFILE_TYPE == "Fishing" and (BANETO_GetBobberState() and BANETO_GetBobberState() == true) then
            BANETO_BOBBER_RDY = true
        end

        if not BANETO_GUID_BLACKLIST_DELETER or GetTime() > BANETO_GUID_BLACKLIST_DELETER then
            if not UnitAffectingCombat("player") and not BANETO_TARGET then
                BANETO_PrintState("Deleting blacklist guid tables - 600 seconds passed")
                BANETO_ClearGuidBlacklist()
                BANETO_GUID_BLACKLIST_DELETER = GetTime()+600
            end
        end

        if BANETO_ISRUNNING and BANETO_UNSTUCK_HEARTHSTONE and BANETO_UNSTUCK_HEARTHSTONE == true and not IsFlying() and not IsFalling() and not UnitAffectingCombat("player") then
            if BANETO_GetUnitSpeed("player") == 0 and not UnitCastingInfo("player") and not IsFalling() then
                if IsMounted() then
                    BANETO_Dismount()
                end
                BANETO_CancelShapeshift()
                BANETO_StopMovement()
                C_Timer.After(1.5,function()
                    BANETO_UseItem(6948)
                    BANETO_Wmb_StuckTick = 0
                    BANETO_WMB_STUCKPADDLE = nil
                end)
                BANETO_UNSTUCK_HEARTHSTONE = nil
                BANETO_Wmb_StuckTick = 0
                BANETO_DelayMeshPathing(15)
                BANETO_DelayGroundUnstucking(15)
                waPath = nil
                BANETO_Wmb_LastPos_Delay = GetTime()+15
                BANETO_WMB_STUCKPADDLE = nil
                BANETO_EMERGENCY_STUCK_HS_LASTUSE = GetTime()+11
                BANETO_PrintState("Baneto seems to be stuck completely or discord action - using hearthstone.")
            end
        end
        if BANETO_ISRUNNING and (BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" or BANETO_Customer() == "bambo") and not IsFlying()  then
            BANETO_SlopeJumper()
        end
        if BANETO_State ~= "IDLE" and BANETO_PRINTSPAM_STATE then
            print("STATE: " .. BANETO_State)
        end
        if BANETO_SETTING_NORO and BANETO_SETTING_NORO == true and not BANETO_NORO_REQUESTED then
            BANETO_NORO_REQUESTED = true
            C_Timer.After(3,BANETO_LoadNoro)
        end
        if not BANETO_OBJTS_TKR_DELAY or BANETO_OBJTS_TKR_DELAY < GetTime() then
            if _internal.Software() == "tnk" then
                BANETO_OBJTS_TKR_ONLYGAMEOBJECTS = Objects(8)
                BANETO_OBJTS_TKR_ONLYPLAYERS = Objects(6)
                BANETO_OBJTS_TKR_ONLYUNITS = Objects(5)
                BANETO_OBJTS_TKR = Objects()
                if IsFlying() then
                    BANETO_OBJTS_TKR_DELAY = GetTime()+0.5
                else
                    BANETO_OBJTS_TKR_DELAY = GetTime()+0.5
                end
            else
                BANETO_OBJTS_TKR_ONLYGAMEOBJECTS = ObjectManager("GameObject")
                BANETO_OBJTS_TKR_ONLYPLAYERS = ObjectManager("Player")
                BANETO_OBJTS_TKR_ONLYUNITS = ObjectManager("Unit")
                BANETO_OBJTS_TKR = Objects()
                if IsFlying() then
                    BANETO_OBJTS_TKR_DELAY = GetTime()+0.5
                else
                    BANETO_OBJTS_TKR_DELAY = GetTime()+1
                end
            end
        end
        BANETO_EDITOR_RecordPath()
        if BANETO_RECORDED_CLICKSPOT_THIS_ITER then
            local leftMouseDown = IsMouseButtonDown("LeftButton")
            if leftMouseDown == false then
                BANETO_RECORDED_CLICKSPOT_THIS_ITER = false
            end
        end
        if BANETO_EDITOR_GRINDGATHER_RECORDCLICK == true then
            local leftMouseDown = IsMouseButtonDown("LeftButton")
            if leftMouseDown == true and not BANETO_RECORDED_CLICKSPOT_THIS_ITER then
                BANETO_RECORDED_CLICKSPOT_THIS_ITER = true
                local clickX,clickY,clickZ;
                if _internal.Software() == "tnk" then
                    local Common = Tinkr.Common
                    clickX,clickY,clickZ = Common.ScreenToWorld(GetCursorPosition())
                else
                    clickX,clickY,clickZ = LastTerrainClick()
                end
                local radius = tonumber(BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_SPOTRANGE:GetText())
                table.insert(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,{clickX,clickY,clickZ,radius})
                BANETO_PrintSuccess("Recorded Spot (Click)! X: " .. clickX .. " Y:" .. clickY .. " Z:" .. clickZ .. " RADIUS: " .. radius)
                BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
            end
        end
        BANETO_CombatRangeModifier()

        if BANETO_ISRUNNING and not IsFlying() and BANETO_IS_FLYING then
            BANETO_CAST_SPELL_DELAY = GetTime()+0.25
            BANETO_IS_FLYING = nil
        end
        if BANETO_ISRUNNING and IsFlying() and not BANETO_IS_FLYING then
            BANETO_CAST_SPELL_DELAY = GetTime()+0.25
            BANETO_IS_FLYING = true
        end

        if Unlocker("EWT") and BANETO_ISRUNNING then
            UpdateGotoPosition()
        end
        if Unlocker("LUA") and BANETO_ISRUNNING and BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" then
            UpdateGotoPositionWa()
        end
        if BANETO_TAXI_CONTINENT then
            if Unlocker("LUA") then
                local cont = BANETO_GetMapId()
                if cont ~= BANETO_TAXI_CONTINENT then
                    BANETO_TAXI_INIT = nil
                    BANETO_TaxiInitFunc()
                end

            elseif Unlocker("EWT") then
                local cont = GetMapId()
                if cont ~= BANETO_TAXI_CONTINENT then
                    BANETO_TAXI_INIT = nil
                    BANETO_TaxiInitFunc()
                end
            end
         end
        if BANETO_MAIN_FRAME_SHORT_STATS and not BANETO_MAIN_FRAME_SHORT_STATS:IsVisible() and BANETO_SETTINGS_STATSTOGGLE and BANETO_SETTINGS_STATSTOGGLE == true then
            BANETO_MAIN_FRAME_SHORT_STATS:Show()
        elseif BANETO_MAIN_FRAME_SHORT_STATS and BANETO_MAIN_FRAME_SHORT_STATS:IsVisible() and (not BANETO_SETTINGS_STATSTOGGLE or BANETO_SETTINGS_STATSTOGGLE == false) then
            BANETO_MAIN_FRAME_SHORT_STATS:Hide()
        end


        if IsFalling() and not IsFlying() and Unlocker("LUA")and BANETO_ASCEND_STOPPER < GetTime() then
            BANETO_ASCEND_STOPPER = GetTime() + 0.5
            BANETO_AscendStop()
        end



        --[[ SWIM Mounting STOPPER --]]
        if IsSwimming() and not BANETO_WATER_MOUNT_BLOCKER then
            BANETO_WATER_MOUNT_BLOCKER = true
            BANETO_WATER_MOUNT_BLOCKER_TIMER = GetTime() + 15
        elseif not IsSwimming() and BANETO_WATER_MOUNT_BLOCKER then
            if BANETO_WATER_MOUNT_BLOCKER_TIMER < GetTime() then
                BANETO_WATER_MOUNT_BLOCKER_TIMER = nil
                BANETO_WATER_MOUNT_BLOCKER = nil
            end
        end

        --[[ Temp Mounting STOPPER --]]
        if IsMounted() and not BANETO_TEMP_MOUNT_BLOCKER then
            BANETO_TEMP_MOUNT_BLOCKER = true
            BANETO_TEMP_MOUNT_BLOCKER_TIMER = GetTime() + 5
        elseif not IsMounted() and BANETO_TEMP_MOUNT_BLOCKER then
            if BANETO_TEMP_MOUNT_BLOCKER_TIMER < GetTime() then
                BANETO_TEMP_MOUNT_BLOCKER_TIMER = nil
                BANETO_TEMP_MOUNT_BLOCKER = nil
            end
        end


        --[[ BANETO ENGAGED MOB RESET --]]
        if BANETO_EWTPATHRESETFORMOBS < GetTime() and BANETO_ISRUNNING and BANETO_TARGET and Unlocker("EWT") and BANETO_GetUnitSpeed("player") > 0 and BANETO_State ~= "REPAIR" then
            BANETO_EWTPATHRESETFORMOBS = GetTime() + 0.5
            if BANETO_TARGET and GetDistanceBetweenObjects("player", BANETO_TARGET) > BANETO_COMBAT_RANGE then
                local x, y, z = ObjectPosition(BANETO_TARGET)
                --[[ StopEwtMovement() --]]
                ewtPath = nil
                BANETO_MeshTo(x, y, z, 2)
            end
        end

        if BANETO_LUAPATHRESETFORMOBS < GetTime() and BANETO_ISRUNNING and BANETO_TARGET and Unlocker("LUA") then
            if BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
                BANETO_LUAPATHRESETFORMOBS = GetTime() + 0.2
            else
                BANETO_LUAPATHRESETFORMOBS = GetTime() + 0.3
            end

            if UnitExists("target") and BANETO_IsTargetInLos() then
                BANETO_LUABOX_TARGETSTICK = true
            end


        end


        if not BANETO_SL_FIRSTFLIGHTMASTER_INIT and UnitLevel("player") >= 60 and BANETO_FIRSTLOAD_TIME and BANETO_FIRSTLOAD_TIME+4 < GetTime() then
            if not BANETO_IsFlightmasterIdKnownV2(162666) then
                BANETO_DefineKnownFlightmasterV2(-1907.1423339844,1210.3004150391,5451.5102539062,162666)
            end
            if not BANETO_IsFlightmasterIdKnownV2(159127) then
                BANETO_DefineKnownFlightmasterV2(-4163.7290039062,-4628.126953125,6534.154296875,159127)
            end
            if not BANETO_IsFlightmasterIdKnownV2(157540) then
                BANETO_DefineKnownFlightmasterV2(2574.1389160156,-2516.8627929688,3307.515625,157540)
            end
            if not BANETO_IsFlightmasterIdKnownV2(158526) then
                BANETO_DefineKnownFlightmasterV2(-3388.9045410156,5457.9350585938,4275.7368164062,158526)
            end
            if not BANETO_IsFlightmasterIdKnownV2(165164) then
                BANETO_DefineKnownFlightmasterV2(-6146.4790039062,-211.80207824707,5581.9184570312,165164)
            end
            BANETO_SL_FIRSTFLIGHTMASTER_INIT = true
        end

        if BANETO_ENGADEDMOBS_RESETDELAY < GetTime() and BANETO_ISRUNNING then
            BANETO_ENGADEDMOBS_RESETDELAY = GetTime() + 360
            if BANETO_ENGADEDMOBS then
                BANETO_ENGADEDMOBS = nil
            end
        end

        if BANETO_ISRUNNING and BANETO_SETTING_PUSH_STATUS and BANETO_SETTING_PUSH_STATUS == true then
            if not BANETO_STATUSUPDATE_TIMER then
                BANETO_STATUSUPDATE_TIMER=GetTime()+_G.BANETO_SETTING_PUSHOVER_TIMER
            elseif BANETO_STATUSUPDATE_TIMER < GetTime() then
                BANETO_MASTER_PUSHDELAY = nil
                BANETO_STATUSUPDATE_TIMER = nil
                BANETO_PushNotification("Status")
            end
        end



        if BANETO_ITEMDELETER_DELAY < GetTime() and BANETO_ISRUNNING and BANETO_SETTING_ITEMDELETION == true then
            if not UnitAffectingCombat("player") and not BANETO_IsDeadOrGhost() then
                BANETO_ITEMDELETER_DELAY = GetTime() + 10
                BANETO_DeleteItems()
            end
        end

        if BANETO_TRIEDAMBUSH_RESTDELAY < GetTime() and BANETO_ISRUNNING then
            BANETO_TRIEDAMBUSH_RESTDELAY = GetTime() + 60
            if BANETO_ROGUE_TRIEDAMBUSH == true then
                BANETO_ROGUE_TRIEDAMBUSH = nil
            end
        end

        if BANETO_WHISPER_CLOSENEEDED and BANETO_WHISPER_CLOSENEEDED == true and BANETO_ISRUNNING then
            if not BANETO_CLOSENEEDED_WHISPER_TIME then
                BANETO_CLOSENEEDED_WHISPER_TIME = GetTime()+5
                BANETO_PrintState("Too many whispers, baneto will close now!")
            elseif BANETO_CLOSENEEDED_WHISPER_TIME < GetTime() then
                BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
                if Unlocker("LUA") and _internal.Software() == "tnk" then
                    Eval("ForceQuit()","asdas")
                elseif  _internal.Software() == "nn" then
                    Unlock("ForceQuit","")
                end
            end
        end

        if BANETO_SETTING_WOWCLOSERDEATHS and BANETO_SETTING_WOWCLOSERDEATHS == true and BANETO_ISRUNNING then
            if BANETO_COUNT_DEATH and BANETO_WOWCLOSER_DEATH_LIMIT and BANETO_COUNT_DEATH >= BANETO_WOWCLOSER_DEATH_LIMIT then
                if not BANETO_CLOSENEEDED_DEATH_TIME then
                    BANETO_CLOSENEEDED_DEATH_TIME = GetTime()+10
                    if BANETO_SETTING_WOWCLOSERDEATHS_COUNTONLYPVP and BANETO_SETTING_WOWCLOSERDEATHS_COUNTONLYPVP == true then
                        BANETO_PrintState("Too many PVP deaths, baneto will close now!")
                    else
                        BANETO_PrintState("Too many deaths, baneto will close now!")
                    end
                elseif BANETO_CLOSENEEDED_DEATH_TIME < GetTime() then
                    BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
                    if Unlocker("LUA") and _internal.Software() == "tnk" then
                        Eval("ForceQuit()","asdas")
                    elseif  _internal.Software() == "nn" then
                        Unlock("ForceQuit","")
                    end
                end
            end
        end

        if ((BANETO_SETTING_WOWCLOSERLEVEL and BANETO_WOWCLOSER_LEVEL_LIMIT and BANETO_SETTING_WOWCLOSERLEVEL == true) or BANETO_CLOSER_WILL_FIRE == true) and BANETO_ISRUNNING then
            if UnitLevel("player") >= BANETO_WOWCLOSER_LEVEL_LIMIT then
                if not BANETO_CLOSENEEDED_LEVEL_TIME then
                    BANETO_CLOSENEEDED_LEVEL_TIME = GetTime()+10
                    BANETO_PrintState("Reached our wanted level, baneto will close now!")
                    BANETO_SetSettingBool("WowCloserLevel", false)
                    BANETO_CLOSER_WILL_FIRE = true
                elseif BANETO_CLOSENEEDED_LEVEL_TIME and BANETO_CLOSENEEDED_LEVEL_TIME < GetTime() then
                    BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
                    if Unlocker("LUA") and _internal.Software() == "tnk" then
                        Eval("ForceQuit()","asdas")
                    elseif  _internal.Software() == "nn" then
                        Unlock("ForceQuit","")
                    end
                end
            end
        end

        if isTrial == false and not LOADED_FIRST_PROFILE_INIT and BANETO_LOADED_SETTINGS_FINISHED and BANETO_LOADED_SETTINGS_FINISHED == true and BANETO_SETTING_LASTLOADEDPROFILE and BANETO_SETTING_LASTLOADEDPROFILE ~= "nostringinput" then
            BANETO_ReloadLastProfile()
            LOADED_FIRST_PROFILE_INIT = true
        end

        if not BANETO_ISRUNNING and BANETO_SETTING_RELOGBEHAVIORNEEDED == true and ((BANETO_SETTING_LASTLOADEDPROFILE and BANETO_SETTING_LASTLOADEDPROFILE ~= "nostringinput") or BANETO_IsProfileLoaded()) then
            if not BANETO_RELOG_INPROCESS then
                BANETO_PrintState("Executing Relogging Protocoll...")
                BANETO_RELOG_INPROCESS = true
                BANETO_RELOADPROFILE_DELAY = GetTime()+BANETO_IDLETIME_AFTER_RELOG
                BANETO_StopMovement()
            end
            if BANETO_IsLastProfileATaskInTaskmanager() and not BANETO_TRIED_TASKMANGER_RESTART then
                if not BANETO_TASKMANAGER_RESTART_DELAYER then
                    BANETO_TASKMANAGER_RESTART_DELAYER = GetTime()+9
                elseif BANETO_TASKMANAGER_RESTART_DELAYER and BANETO_TASKMANAGER_RESTART_DELAYER < GetTime() then
                    BANETO_StartTaskmanager()
                    BANETO_TRIED_TASKMANGER_RESTART = true
                    BANETO_TASKMANAGER_RESTART_DELAYER = nil
                end
            else
                if BANETO_RELOG_INPROCESS == true then
                    BANETO_ReloadAndStartLastProfile()
                end
            end
        else
            BANETO_RELOG_INPROCESS = nil
        end



        if BANETO_WOWLOGOUT_TIMESTAMP and BANETO_SETTING_WOWOUTLOGGER_MINUTES and BANETO_SETTING_WOWOUTLOGGER and BANETO_SETTING_WOWOUTLOGGER == true then
            if BANETO_WOWLOGOUT_TIMESTAMP-60 < GetTime() and not BANETO_WOWOUTLOGGER_WARNING_1MINUTE then
                if not BANETO_WOWOUTLOGGER_WARNING_1MINUTE then
                    BANETO_WOWOUTLOGGER_WARNING_1MINUTE = true
                    BANETO_PrintWarning("Due to your RELOGGING SETTINGS baneto will logout in 60 seconds!")
                end
            elseif BANETO_WOWLOGOUT_TIMESTAMP < GetTime()  and not UnitAffectingCombat("player") and not IsFlying() then
                BANETO_SetSettingBool("IsRelogBehaviorNeeded",true)
                if not BANETO_LOGOUT_DELAY then
                    BANETO_LOGOUT_DELAY = GetTime()+3
                    BANETO_PrintWarning("Due to your SECURITY SETTINGS baneto will logout now!")
                elseif BANETO_LOGOUT_DELAY < GetTime()  and not LOGGING_OUT_ALREADY then
                    LOGGING_OUT_ALREADY = true
                    BANETO_Logout()
                end
            end
        end

        if BANETO_WOWCLOSER_TIMESTAMP and BANETO_SETTING_WOWCLOSER_MINUTES and BANETO_SETTING_WOWCLOSER and BANETO_SETTING_WOWCLOSER == true then
            if BANETO_WOWCLOSER_TIMESTAMP-300 < GetTime() and not BANETO_WOWCLOSER_WARNING_5MINUTE then
                if not BANETO_WOWCLOSER_WARNING_5MINUTE then
                    BANETO_WOWCLOSER_WARNING_5MINUTE = true
                    BANETO_PrintWarning("Due to your SECURITY SETTINGS baneto will close in 5 minutes!")
                end
            elseif BANETO_WOWCLOSER_TIMESTAMP-180 < GetTime() and not BANETO_WOWCLOSER_WARNING_3MINUTE then
                if not BANETO_WOWCLOSER_WARNING_3MINUTE then
                    BANETO_WOWCLOSER_WARNING_3MINUTE = true
                    BANETO_PrintWarning("Due to your SECURITY SETTINGS baneto will close in 180 seconds!")
                end
            elseif BANETO_WOWCLOSER_TIMESTAMP-60 < GetTime() and not BANETO_WOWCLOSER_WARNING_1MINUTE then
                if not BANETO_WOWCLOSER_WARNING_1MINUTE then
                    BANETO_WOWCLOSER_WARNING_1MINUTE = true
                    BANETO_PrintWarning("Due to your SECURITY SETTINGS baneto will close in 60 seconds!")
                end
            elseif BANETO_WOWCLOSER_TIMESTAMP < GetTime() then
                BANETO_SetSettingBool("IsRelogBehaviorNeeded",false)
                if not BANETO_QUIT_DELAY then
                    BANETO_QUIT_DELAY = GetTime()+3
                    BANETO_PrintWarning("Due to your SECURITY SETTINGS baneto will close now!")
                elseif BANETO_QUIT_DELAY < GetTime() then
                    if Unlocker("LUA") and _internal.Software() == "tnk" then
                        Eval("ForceQuit()","asdas")
                    elseif  _internal.Software() == "nn" then
                        Unlock("ForceQuit","")
                    end
                end
            end
        end


        if BANETO_BUFF_RESET_NEEDED then
            if not BANETO_BUFF_RESET_NEEDED_INDEX then
                BANETO_BUFF_RESET_NEEDED_INDEX = 1
                BANETO_PrintState("Removing all buffs on you due to wow interface error: SPELL_AURA_BOUNCED !")
            end
            if not BUFF_RESET_DELAY_TIMER or BUFF_RESET_DELAY_TIMER < GetTime() then
                BUFF_RESET_DELAY_TIMER = GetTime() + 0.1
                local nameBuffOnPlayer,_,_,_,_,_,_,_,_,buffOnPlayer,_,_,_,_,_ = UnitBuffWrapper("player", BANETO_BUFF_RESET_NEEDED_INDEX)
                if buffOnPlayer then
                    CancelBuff(buffOnPlayer)
                end
                BANETO_BUFF_RESET_NEEDED_INDEX = BANETO_BUFF_RESET_NEEDED_INDEX + 1
                if BANETO_BUFF_RESET_NEEDED_INDEX >= 32 then
                    BANETO_BUFF_RESET_NEEDED = false
                    BANETO_BUFF_RESET_NEEDED_INDEX = nil
                end
            end
        end

        if not BANETO_STATS_STASH_DELAY or BANETO_STATS_STASH_DELAY < GetTime()  then
            if not BANETO_COUNT_STASH then
                BANETO_COUNT_STASH = 1
            end
            BANETO_STATS_STASH_DELAY = GetTime()+60
            BANETO_StashStatsValues()
        end
        if BANETO_LOOP_PLUGINS == true then
            if not BANETO_PLUGIN_DELAY or BANETO_PLUGIN_DELAY < GetTime() then
                BANETO_PLUGIN_DELAY = GetTime()+_G.BANETO_PluginTickTime
                BANETO_ExecutePlugins()
            end
        elseif not BANETO_LOADEDPLUGINS_ONLY_ONCE then
            BANETO_ExecutePlugins()
            BANETO_LOADEDPLUGINS_ONLY_ONCE = true
        end

        if BANETO_SAVE_QUEUED and BANETO_SAVE_QUEUED == true then
            if BANETO_SAVE_DELAYER and BANETO_SAVE_DELAYER < GetTime() then
                BANETO_SaveSettings()
                BANETO_SAVE_QUEUED = nil
            end
        end


        if BANETO_SETTINGS_STATSTOGGLE and BANETO_SETTINGS_STATSTOGGLE == true and BANETO_State and BANETO_MAIN_FRAME_SHORT_STATS_TEXT:IsVisible() and BANETO_STAT_XPPERH and BANETO_COUNT_DEATH then
            local nodes = BANETO_GetCountGatherNode()
            local digs = BANETO_GetDigsitesCompletedCount()
            if nodes and 5 < nodes and BANETO_SHOW_GATHER_NODE_IN_INFOBAR and BANETO_GetState() ~= "ARCH" then
                BANETO_MAIN_FRAME_SHORT_STATS_TEXT:SetText("|cff0872B2" .. BANETO_State .. "|cffB9B9B9 | " .. "NODES: " .. nodes .. " | " .. "â : " .. BANETO_COUNT_DEATH)
            elseif digs and digs >= 1 and BANETO_GetState() == "ARCH" then
                BANETO_MAIN_FRAME_SHORT_STATS_TEXT:SetText("|cff0872B2" .. BANETO_State .. "|cffB9B9B9 | " .. "DIGS: " .. digs .. " | " .. "â : " .. BANETO_COUNT_DEATH)
            else
                BANETO_MAIN_FRAME_SHORT_STATS_TEXT:SetText("|cff0872B2" .. BANETO_State .. "|cffB9B9B9 | " .. "XP/H: " .. BANETO_STAT_XPPERH .. " | " .. "â : " .. BANETO_COUNT_DEATH)
            end

            if BANETO_DEFINED_PROFILE_TYPE and BANETO_DEFINED_PROFILE_TYPE == "Questing" and BANETO_DEFINED_QUESTSTEP_TYPES and BANETO_DEFINED_QUESTSTEP_TYPES[1] and BANETO_DEFINED_QUESTSTEP_TYPES[1][1] then
                BANETO_MAIN_FRAME_SHORT_QUESTINFO_TEXT:Show()
                if not BANETO_CURRENT_QUEST_STEP then
                    BANETO_CURRENT_QUEST_STEP = BANETO_GetNextQuestStep()
                    C_Timer.After(15,function()
                        BANETO_CURRENT_QUEST_STEP = nil
                    end)
                end
                local step = BANETO_CURRENT_QUEST_STEP or 0
                local questid = 0;
                local queststep = BANETO_DEFINED_QUESTSTEP_TYPES[1][1]
                if not step or step == false then
                    step = 0
                end
                if BANETO_DEFINED_QUEST_IDS and BANETO_DEFINED_QUEST_IDS[1] and BANETO_DEFINED_QUEST_IDS[1][1] then
                    questid = BANETO_DEFINED_QUEST_IDS[1][1]
                    if not questid or questid == 99999 then
                        questid = 0
                    end
                end
                if queststep == "GrindTo" and BANETO_GRINDTOLEVEL_VALUE then
                    queststep = queststep .. " " .. BANETO_GRINDTOLEVEL_VALUE
                end
                if type(step) == "number" and step > 0 then
                    BANETO_MAIN_FRAME_SHORT_QUESTINFO_TEXT:SetText("|cffB9B9B9" .. "Step: " .. step .. " | " .. "Quest-Id: " .. questid .. " | " .. "Type: " .. queststep)
                else
                    BANETO_MAIN_FRAME_SHORT_QUESTINFO_TEXT:SetText("|cffB9B9B9" .. "Quest-Id: " .. questid .. " | " .. "Type: " .. queststep)
                end
            else
                BANETO_MAIN_FRAME_SHORT_QUESTINFO_TEXT:Hide()
            end

        end

        if StaticPopup1Button2:IsVisible() and BANETO_IsRunning() and BANETO_REJECT_GROUPINVITE_NEEDED and BANETO_REJECT_GROUPINVITE_WANTED and BANETO_REJECT_GROUPINVITE_WANTED == true then
            local delayTime = 0.01
            if BANETO_REJECT_GROUPINVITE_WANTED_DELAY and BANETO_REJECT_GROUPINVITE_WANTED_DELAY == true then
                delayTime = 2
            end
            C_Timer.After(delayTime,function()
                StaticPopup1Button2:Click()
                BANETO_REJECT_GROUPINVITE_NEEDED = nil
                BANETO_PrintState("Rejecting Party Request!")
            end)
        end

        if not BANETO_ISRUNNING and BANETO_DoesUserHaveWrongSetupSloader()  then
            BANETO_Print("[SETUP] Wrong setup! You are using a script loader to load baneto AND baneto addon at the same time. Please delete the baneto addon folder inside your wow directory!")
            BANETO_Bricked = true
        end


        if Unlocker("EWT") and BANETO_STATE_DELAY < GetTime()  then
            countWMB, isUpdatedWMB, addedObjectsWMB, removedObjectsWMB = GetObjectCount()
        end

        if BANETO_SETTING_HEKILI and BANETO_SETTING_HEKILI == true and not HEKILI_REQUESTED and DirectoryExists(GetWowDirectory() .. "Interface/Addons/Hekili") and CallSecureFunction then
            BANETO_RequestHekili()
            BANETO_PrintState("Loading Hekili advanced...")
            HEKILI_REQUESTED = true
        elseif (BANETO_SETTING_HEKILI and BANETO_SETTING_HEKILI == true) and (not CallSecureFunction or not DirectoryExists(GetWowDirectory() .. "Interface/Addons/Hekili")) then
            BANETO_SetSettingBool("Hekili", false)
            BANETO_PrintError("Force disabled hekili setting! Missing hekili addon or wrong unlocker.")
        end
        if BANETO_SETTING_HEKILI and BANETO_SETTING_HEKILI == true and Hekili and (BANETO_ISRUNNING and not IsMounted()) then
            Hekili.Pause = false
        elseif BANETO_SETTING_HEKILI and BANETO_SETTING_HEKILI == true and Hekili and (not BANETO_ISRUNNING or IsMounted()) then
            Hekili.Pause = true
        end

        if _internal.Software() == "nn" then
            BANETO_SMOOTHTURN_CHECKABS = 0.1
        else
            BANETO_SMOOTHTURN_CHECKABS = 0.1
        end
        if (_internal.Software() == "nn" or _internal.Software() == "tnk") and (not BANETO_SMOOTHTURN_BLOCK or BANETO_SMOOTHTURN_BLOCK < GetTime() )  then
            if BANETO_WANTED_ANGLE  and BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == true and (BANETO_ISRUNNING or REAPER_ISRUNNING) and not UnitOnTaxi("player") and BANETO_DEFINED_PROFILE_TYPE ~= "Rotation" then
                local current = 0
                current = BANETO_GetObjectFacing("player")
                if current then
                    local abs = math.abs(current - BANETO_WANTED_ANGLE)
                    local diff = current - BANETO_WANTED_ANGLE
                    if _G.BANETO_SMOOTHTURN_DEBUG and abs <= BANETO_SMOOTHTURN_CHECKABS then
                        print(abs)
                    end
                    if abs and abs<=BANETO_SMOOTHTURN_CHECKABS then
                        --BANETO_PrintBambo("Smooth stop "..abs)
                        BANETO_WANTED_ANGLE = nil
                        BANETO_TurnRightStop()
                        BANETO_TurnLeftStop()
                    elseif abs then
                        if diff < 0 then
                            diff = diff+6.2
                        end
                        if diff < 3.1 then
                            --BANETO_PrintBambo("Smooth right ABS: "..abs .. " DIFF: " .. diff)
                            BANETO_TurnLeftStop()
                            BANETO_TurnRightStart()
                        elseif diff < 6.2 then
                            --BANETO_PrintBambo("Smooth left ABS: "..abs .. " DIFF: " .. diff)
                            BANETO_TurnRightStop()
                            BANETO_TurnLeftStart()
                        end
                        if not UnitCastingInfo("player") and _internal.Software() == "nn" and not UnitChannelInfo("player") and not BANETO_IsEating() and not BANETO_IsDrinking() and (not strafeleftdelayer or strafeleftdelayer < GetTime()) then
                            BANETO_UpdateServerFacing()
                            strafeleftdelayer = GetTime()+0.5
                        end
                    end
                end
            end
        end

        if BANETO_UNSTUCK_ROUTE_ISACTIVE and BANETO_UNSTUCK_ROUTE_ISACTIVE == true then
            if not unstuckRouteIndex then
                unstuckRouteIndex = 1
            end
            local x,y,z = BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][1],BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][2],BANETO_UNSTUCK_ROUTE_CURRENT[unstuckRouteIndex][3]
            BANETO_MeshTo(x,y,z)
            if BANETO_PlayerPosition(x,y,z,4) or (IsFlying() and BANETO_PlayerPosition(x,y,z,7)) then
                unstuckRouteIndex = unstuckRouteIndex+1
                waPath = nil
                if unstuckRouteIndex > #BANETO_UNSTUCK_ROUTE_CURRENT then
                    BANETO_UNSTUCK_ROUTE_ISACTIVE = nil
                    unstuckRouteIndex = nil
                    BANETO_StopMovement()
                    BANETO_TurnLeftStop()
                    BANETO_TurnRightStop()
                    BANETO_DelayMeshPathing(3)
                end
            end
        else
            BANETO_CheckUnstuckTriggers()
        end

        if Unlocker("EWT") and BANETO_FIRSTLOAD_TIME and BANETO_FIRSTLOAD_TIME+2 < GetTime() then
            mapId, zoneId = GetMapId()
            loaded = IsMeshLoaded(mapId)
            if (not loaded or loaded == false) and MapExists(mapId) then
                LoadMap(mapId)
                BANETO_PrintState("Loading bntnav for map: " .. mapId)
            end
        end
        if BANETO_PAID_PACK_RELOADER and BANETO_PAID_PACK_RELOADER == true and not UnitAffectingCombat("player") then
            if not BANETO_PAID_PACK_RELOADER_TIMER then
                BANETO_PAID_PACK_RELOADER_TIMER = GetTime()+6
                BANETO_PrintState("Installing projects to LOCAL PROFILES, reloading in a few seconds!")
            elseif BANETO_PAID_PACK_RELOADER_TIMER and BANETO_PAID_PACK_RELOADER_TIMER < GetTime() and not UnitAffectingCombat("player") then
                -- BANETO_RunMacroText("/reload")
            end
        end
        if BANETO_FIRSTLOAD_TIME and BANETO_FIRSTLOAD_TIME+4 < GetTime() and BANETO_FIRSTLOAD_TIME > GetTime()-20 and not BANETO_ISRUNNING and ownedPacksBnt and #ownedPacksBnt >= 1 then
            for i=1,#ownedPacksBnt do
                local pack = ownedPacksBnt[i][1]
                if pack then
                    if not BANETO_IsPaidPackInstalled(pack) then
                        BANETO_InstallPaidPack(pack)
                        return false
                    end
                end
            end
        end
        if (not BANETO_SETTING_MOUNT or BANETO_SETTING_MOUNT == false) and BANETO_FLYING_PROFILE and BANETO_FLYING_PROFILE == true then
            BANETO_PrintWarning("Baneto is force enabling mounting because you have the flying navigation enabled!")
            BANETO_SetSettingBool("Mounting",true)
        end
        if BANETO_FLYING_UNSTUCK_INPROCESS and BANETO_FLYING_UNSTUCK_INPROCESS < GetTime() then
            BANETO_FLYING_UNSTUCK_INPROCESS = nil
            if Unlocker("LUA") and _internal.Software() == "tnk" then
                Eval("StrafeLeftStop()","somth")
            end
            if Unlocker("LUA") and _internal.Software() == "nn" then
                Unlock("StrafeLeftStop","")
            end
            BANETO_AscendStop()
        elseif BANETO_FLYING_UNSTUCK_INPROCESS and BANETO_FLYING_UNSTUCK_INPROCESS > GetTime() then
            BANETO_JumpOrAscendStart()
            return false
        end

        if not BANETO_IsDeadOrGhost() then
            BANETO_RESSSPIRIT_ONCE = nil
            BANETO_LAST_GHOST_ENTER = nil
        end
        local speed = BANETO_GetUnitSpeed("player")
        if 0<speed then
            BANETO_MC_LAST_SPEED = GetTime()
        end
        if BANETO_TAXI_CACHE_POS_X and BANETO_GetState() ~= "FP-TAXI" then
            local x,y,z = BANETO_ObjectPosition("player")
            local dist = BANETO_GetDistance3D(x,y,z,BANETO_TAXI_CACHE_POS_X,BANETO_TAXI_CACHE_POS_Y,BANETO_TAXI_CACHE_POS_Z)
            if dist and 200 < dist then
                BANETO_TAXI_CACHE_POS_X = nil
                BANETO_TAXI_CACHE_POS_Y = nil
                BANETO_TAXI_CACHE_POS_Z = nil
                BANETO_TAXI_CACHE_EXIT = nil
                BANETO_TAXI_CACHE_ENTRY = nil
            end
        end

        if _G.BANETO_ExecuteCustomMasterPulse ~= nil then
            _G.BANETO_ExecuteCustomMasterPulse()
        end


        if not _G.BANETO_SETTINGS_RETAIL_ONLY_INSTANT_FACING then
            if not BANETO_IsDragonRiding() and BANETO_SETTING_SMOOTHTURN == false then
                BANETO_SetSettingBool("Smoothturn", true)
            elseif BANETO_IsDragonRiding() and BANETO_SETTING_SMOOTHTURN == true then
                BANETO_SetSettingBool("Smoothturn", false)
                BANETO_TurnLeftStop()
                BANETO_TurnRightStop()
            end
        elseif BANETO_SETTING_SMOOTHTURN == true then
            BANETO_SetSettingBool("Smoothturn", false)
        end

        if BANETO_EDITOR_MOVE_spotIndex and IsShiftKeyDown() then
            BANETO_EDITOR_MOVE_spotIndex = nil
            BANETO_EDITOR_MOVE_spotType = nil
        end
        if BANETO_EDITOR_MOVE_spotIndex and IsAltKeyDown() then
            if BANETO_EDITOR_MOVE_spotType == "Center" then
                table.remove(BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS,BANETO_EDITOR_MOVE_spotIndex)
            elseif BANETO_EDITOR_MOVE_spotType == "Blacklist" then
                table.remove(BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS,BANETO_EDITOR_MOVE_spotIndex)
            end
            BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_RECORDSPOTS:SetText(L["Recorded Spots: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS)
            BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_TITLE_BLACKLISTEDAREAS:SetText(L["Blacklisted Areas: "] .. #BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS)
            BANETO_EDITOR_MOVE_spotIndex = nil
            BANETO_EDITOR_MOVE_spotType = nil
        end
        if BANETO_MOUSE_LEFT_IS_DOWN and BANETO_EDITOR_GRINDGATHER_RECORDCLICK == false and BANETO_SUB_FRAME_TOOLS_MOVESPOTS:GetChecked() == true then
            local clickX,clickY,clickZ = BANETO_LastClick()
            if not BANETO_EDITOR_MOVE_spotIndex then
                BANETO_EDITOR_MOVE_spotIndex, BANETO_EDITOR_MOVE_spotType = BANETO_FindClosestEditorSpot(clickX,clickY,clickZ)
            end
            if BANETO_EDITOR_MOVE_spotIndex then
                if BANETO_EDITOR_MOVE_spotType == "Center" then
                    if not BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[BANETO_EDITOR_MOVE_spotIndex] then
                        BANETO_EDITOR_MOVE_spotIndex = nil
                        BANETO_EDITOR_MOVE_spotType = nil
                        return
                    end
                    BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[BANETO_EDITOR_MOVE_spotIndex][1] = clickX
                    BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[BANETO_EDITOR_MOVE_spotIndex][2] = clickY
                    BANETO_EDITOR_GRINDGATHER_STORAGE_CENTERS[BANETO_EDITOR_MOVE_spotIndex][3] = clickZ
                elseif BANETO_EDITOR_MOVE_spotType == "Blacklist" then
                    if not BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[BANETO_EDITOR_MOVE_spotIndex] then
                        BANETO_EDITOR_MOVE_spotIndex = nil
                        BANETO_EDITOR_MOVE_spotType = nil
                        return
                    end
                    BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[BANETO_EDITOR_MOVE_spotIndex][1] = clickX
                    BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[BANETO_EDITOR_MOVE_spotIndex][2] = clickY
                    BANETO_EDITOR_GRINDGATHER_STORAGE_BLACKLIST_SPOTS[BANETO_EDITOR_MOVE_spotIndex][3] = clickZ
                end
            end
        end

        if BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID and BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID:IsVisible() and GetQuestID()  and BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID:GetText() == "0" then
            local questId = GetQuestID()
            BANETO_DEVTOOLS_GRINDGATHEREDITOR_SUBFRAME_EDITBOX_QUESTID:SetText(questId)
        end
        if (not BANETO_SETTING_DISABLECOMBATROUTINE or BANETO_SETTING_DISABLECOMBATROUTINE == false) and not isHekiliLoaded() then
            BANETO_SetSettingBool("DisableCombatRoutine", true)
        end
        if BANETO_SETTING_DISABLECOMBATROUTINE and BANETO_SETTING_DISABLECOMBATROUTINE == true and isHekiliLoaded() then
            BANETO_SetSettingBool("DisableCombatRoutine", false)
        end
        if BANETO_ISRUNNING and BANETO_DRUID_WATER_ASCEND and not IsSwimming() and (not BANETO_LOADVIGOR_DRUIDWATER or BANETO_LOADVIGOR_DRUIDWATER < GetTime()) then
            BANETO_DRUID_WATER_ASCEND = nil
            local ascendsurge = 372610
            C_Timer.NewTicker(0.1,function()
                BANETO_CastSpell(ascendsurge,true)
            end,15)
            C_Timer.NewTicker(0.1,BANETO_JumpOrAscendStart,15)
        end
        if BANETO_ISRUNNING and BANETO_DRUID_WATER_ASCEND and IsFlying() then
            BANETO_DRUID_WATER_ASCEND = nil
