    function _G.BANETO_HowManyBagsEquipped()
        local counter = 0
        for i = 0, NUM_BAG_SLOTS+1 do
            if GetContainerNumSlots(i) > 0 then
                counter = counter + 1
            end
        end
        return counter
    end

