            local function OnEventLava(self, event)
                local a,b,c,d,e,f,g,h,i,j,k,l,m,n = CombatLogGetCurrentEventInfo()
                if i and i == "Corrupt Living Water" and BANETO_GetProfileName() == "JadeTemple_Short2" then
                    BANETO_PrintWarning("Corrupt Living Water, avoiding by moving away now!!!")
                end
                if _G.DEBUG_LAVA then
                    print("COMBAT EVENT DEBUG")
                    if a then
                        print("A: "..a)
                    end
                    if b then
                        print("B: "..b)
                    end
                    if c then
                        print("C: true")
                    else
                        print("C: false")
                    end
                    print("D: "..d)
                    if e then
                        print("E: "..e)
                    end
                    if f then
                        print("F: "..f)
                    end
                    if g then
                        print("G: "..g)
                    end
                    if h then
                        print("H: "..h)
                    end
                    if i then
                        print("I: "..i)
                    end
                    if j then
                        print("J: "..j)
                    end
                    if k then
                        print("K: "..k)
                    end
                    if l then
                        print("L: "..l)
                    end
                    if m then
                        print("M: "..m)
                    end
                    if n then
                        print("N: "..n)
                    end
                end
                if not _G.BANETO_BLOCK_LAVA_DETECTION and b and b == "SPELL_PERIODIC_DAMAGE" and m and m == "Lava" and BANETO_IsRunning() and not IsFlying() then
                    if (not BANETO_LAVA_DELAY or BANETO_LAVA_DELAY < GetTime()) then
                        if not BANETO_LAVA_ESCAPE then
                            BANETO_PrintWarning("The floor is lava. Trying to escape for 5 seconds.")
                            BANETO_LAVA_ESCAPE = true
                            C_Timer.After(4.5,function()
                                BANETO_LAVA_ESCAPE = nil
                                BANETO_LAVA_DELAY = GetTime()+7
                                lavaEscapeVector = nil
                                BANETO_LAVA_ESCAPE_VIA_FLY = nil
                                flyingPath = nil
                                waPath = nil
                            end)

                        end
                    else
                        BANETO_LAVA_ESCAPE_VIA_FLY = true
                        BANETO_PrintWarning("The floor is lava. Trying to make it through by delaying REGENERATING and FIGHTING.")
                        if BANETO_GetUnitSpeed("player") == 0 and not UnitCastingInfo("player") and IsMounted() then
                            BANETO_JumpOrAscendStart()
                        end
                        C_Timer.After(4.5,function()
                            BANETO_LAVA_ESCAPE_VIA_FLY = nil
                        end)
                        BANETO_SetSTOPFIGHT_EVADE(GetTime()+3)
                        if BANETO_GetState() == "FIGHTING" then
                            BANETO_SetFIGHTING_EMERGENCY_LEAVE(true)
                        end
                    end
                    waPath = nil
                    BANETO_LAST_LAVA = GetTime()
                end
            end

