            local GatherInterruptDismount = CreateFrame("Frame")
            GatherInterruptDismount:RegisterUnitEvent("UNIT_SPELLCAST_INTERRUPTED", "player")
            GatherInterruptDismount:RegisterUnitEvent("UNIT_SPELLCAST_SUCCEEDED", "player")

            GatherInterruptDismount:SetScript("OnEvent", function(self, event, ...)
                local _, _, spellID = ...
                -- remember BANETO_IsCastingGathering() !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
                if event == 'UNIT_SPELLCAST_INTERRUPTED' and (spellID == 441327 or spellID == 423341 or spellID == 366260 or spellID == 265845 or spellID == 265834 or spellID == 265849 or spellID == 366252 or spellID == 265823 or spellID == 265841 or spellID == 265843 or spellID == 265825 or spellID == 74519) and not eventHandleLimiter then
                    if miningorHerbingInterrupt then
                        miningorHerbingInterrupt = miningorHerbingInterrupt + 1
                        BANETO_PrintState("Gathering interrupted: " .. miningorHerbingInterrupt)
                    else
                        miningorHerbingInterrupt = 1
                        BANETO_PrintState("Gathering interrupted: " .. miningorHerbingInterrupt)
                    end
                    BANETO_INTERACT_SMALLDELAYTIMER = nil
                    baneto_rtl_gatherinteract = GetTime()
                    eventHandleLimiter = true
                    if miningorHerbingInterrupt >= _G.BANETO_GATHER_INTERRUPTS_BEFORE_DISMOUNT then
                        if BANETO_FIGHT_BLOCKED_BY_GATHER and BANETO_FIGHT_BLOCKED_BY_GATHER == true and BANETO_LAST_GATHER_NODE then
                            BANETO_AddMobToGuidBlacklist(BANETO_LAST_GATHER_NODE)
                            BANETO_LAST_GATHER_NODE = nil
                            BANETO_TARGET = nil
                            BANETO_PrintState("Gathering interrupted " .. _G.BANETO_GATHER_INTERRUPTS_BEFORE_DISMOUNT .. " times, dismounting now.")
                            miningorHerbingInterrupt = nil
                        else
                            BANETO_Dismount()
                            CancelShapeshift()
                            BANETO_PrintState("Gathering interrupted " .. _G.BANETO_GATHER_INTERRUPTS_BEFORE_DISMOUNT .. " times, dismounting now.")
                            miningorHerbingInterrupt = nil
                        end
                    end
                    C_Timer.After(1,function()
                        eventHandleLimiter = nil
                    end)
                end
            end)


