            --[[ AUTO FACE MOB DEBUGGERs --]]
            local FaceMobDebuggerFame = CreateFrame("Frame")
            function FaceMobDebuggerFame:OnEvent(event, key, state)
                if state == ERR_BADATTACKFACING or state == "Target needs to be in front of you." or state == SPELL_FAILED_UNIT_NOT_INFRONT or state == "Ziel muss sich vor euch befinden." or state == "Ihr seht in die falsche Richtung." or state == "You are facing the wrong way!" then
                    if BANETO_ISRUNNING and (not ERR_BADATTACKFACING_DELAY or ERR_BADATTACKFACING_DELAY < GetTime()) then
                        if Unlocker("LUA") and UnitExists("target")  and not _G.BANETO_BLOCK_FACING_FIXES and (BANETO_State == "FIGHTING" or BANETO_State == "CLEAR-PATH" or BANETO_State == "GRIND" or BANETO_State == "QUEST-PULSE" or BANETO_State == "QUEST-MASTER" or BANETO_State == "RBG" ) then
                            local xMob, yMob, zMob = BANETO_ObjectPosition("target")
                            if (not BANETO_SETTING_SMOOTHTURN or BANETO_SETTING_SMOOTHTURN == false) then
                                BANETO_Print("Debug Mob Facing Bug - Fixing with turning")
                                BANETO_TurnRightStop()
                                BANETO_TurnLeftStart()
                                C_Timer.After(0.5,BANETO_TurnStop)
                                --ERR_BADATTACKFACING_DELAY = GetTime()+5
                            end
                            if xMob and yMob and zMob then
                                local angle = BANETO_GetFacingValue(xMob, yMob, zMob)
                                if not angle or (angle < 0 and angle > 0) then
                                    angle = 0
                                    BANETO_PrintError("Facing calculation error. Moving backwards to fix it.")
                                    BANETO_MoveBackwardStart()
                                    C_Timer.After(0.5,BANETO_MoveBackwardStop)
                                else
                                    if not FACING_PROBLEM_COUNTER then
                                        FACING_PROBLEM_COUNTER = 0
                                    end
                                    if BANETO_GetUnitSpeed("player") == 0 then
                                        FACING_PROBLEM_COUNTER = FACING_PROBLEM_COUNTER+1
                                    end
                                    if FACING_PROBLEM_COUNTER and FACING_PROBLEM_COUNTER >= 5 and not _G.BANETO_BLOCK_FACING_FIXES and not BANETO_SETTING_HYPERSPAWN then
                                        if not FACING_PROBLEM_BACKWARDS then
                                            _G.BANETO_MOVEMENTSTOPDELAYTIME = GetTime()+1
                                            BANETO_MoveBackwardStart()
                                            BANETO_PrintError("FACING PROBLEM 5 TIMES: Starting to backpaddle for 1 second")
                                            C_Timer.After(0.5,BANETO_MoveBackwardStart)
                                            C_Timer.After(1,BANETO_MoveBackwardStop)
                                            FACING_PROBLEM_COUNTER = nil
                                            FACING_PROBLEM_BACKWARDS = true
                                        else
                                            _G.BANETO_MOVEMENTSTOPDELAYTIME = GetTime()+2
                                            BANETO_MoveForwardStart()
                                            BANETO_PrintError("FACING PROBLEM 5 TIMES: Starting to forwardpaddle for 2 seconds")
                                            C_Timer.After(0.5,BANETO_MoveForwardStart)
                                            C_Timer.After(2,BANETO_MoveForwardStop)
                                            FACING_PROBLEM_COUNTER = nil
                                            FACING_PROBLEM_BACKWARDS = nil
                                        end
                                    end
                                end
                                if _internal.Software() == "tnk" then
                                    BANETO_SetPlayerAnglesLuabox(angle)
                                    BANETO_WANTED_ANGLE = angle
                                else
                                    BANETO_SetPlayerAnglesLuabox(angle)
                                    BANETO_WANTED_ANGLE = angle
                                end
                            end
                        end
                    end
                end
            end

            FaceMobDebuggerFame:RegisterEvent("UI_ERROR_MESSAGE")
            FaceMobDebuggerFame:SetScript("OnEvent", FaceMobDebuggerFame.OnEvent)
        end
        --[[ AUTO EQUIP BAGS --]]
        if BANETO_SETTING_AUTOEQUIP_BAGS == true then
            local amountBagsEquipped = BANETO_HowManyBagsEquipped()
            if amountBagsEquipped < 5 then
                for i = 0, NUM_BAG_SLOTS+1 do
                    for z = 1, GetContainerNumSlots(i) do
                        for k = 1, #BANETO_ITEMS_BAGS do
                            local id = GetContainerItemID(i, z)
                            local tableId = BANETO_ITEMS_BAGS[k][1]
                            if tableId == id then
                                if Unlocker("LUA") and _internal.Software() == "tnk" then
                                    Eval("C_Container.UseContainerItem(" ..i .. "," .. z .. ")","somth")
                                end
                                if Unlocker("LUA") and _internal.Software() == "nn" then
                                    --Unlock("C_Container.UseContainerItem",i,z)
                                    Unlock("pcall", C_Container.UseContainerItem, i, z)
                                end
                            end
                        end
                    end
                end
            end
        end
        if BANETO_HUNTER_SPAMBLOCK_PETISNOTDEAD and BANETO_HUNTER_SPAMBLOCK_PETISNOTDEAD == true and UnitExists("pet") then
            BANETO_HUNTER_SPAMBLOCK_PETISNOTDEAD = nil
        end
        if BANETO_HUNTER_SPAMBLOCK_NOPET and BANETO_HUNTER_SPAMBLOCK_NOPET == true and UnitExists("pet") then
            BANETO_HUNTER_SPAMBLOCK_NOPET = nil
        end

        --[[ --------------------QUEST STATES----------------------------------- --]]

        if BANETO_State == "QUEST-MASTER"  and BANETO_State ~= "FP-TAXI" then
            BANETO_PrintBambo("Quest master")
            if _G.BANETO_ExecuteCustomQuestPulse ~= nil and _G.BANETO_ExecuteCustomQuestPulse_Questmaster and _G.BANETO_ExecuteCustomQuestPulse_Questmaster == true then
                _G.BANETO_ExecuteCustomQuestPulse()
                if _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior and _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior == true then
                    return true
                end
            end

            if BANETO_IsCurrentSpell(6991) then
                BANETO_UsePetFeedItem()
            end

            --[[ CLOSE FORGOTTEN GOSSIPS --]]
            if QuestFrameDetailPanel:IsVisible() then
                QuestFrameCloseButton:Click()
            end
            if GossipFrame.GreetingPanel:IsVisible() then
                GossipFrameCloseButton:Click()
            end


            --[[ MASTER TIMER LOAD NEW STEP --]]
            if not BANETO_QUEST_MASTER_TIMER then
                BANETO_QUEST_MASTER_TIMER = GetTime() + 5
            end
            if BANETO_QUEST_MASTER_TIMER > GetTime() and not BANETO_IsLocalQuester and (not BANETO_INTERNALNEXTQUESTLOAD_DELAY or BANETO_INTERNALNEXTQUESTLOAD_DELAY < GetTime()) then
                if BANETO_GetNextQuestStep() then
                    BANETO_QUEST_MASTER_TIMER = nil
                    BANETO_LoadLibraryQuest(BANETO_PROFILE_NAME, BANETO_GetNextQuestStep())
