            local missing2 = GetObjectWithIdIncludingBlacklistCheck(278477)
            local draenei = GetObjectWithIdIncludingBlacklistCheck(207188)
            local orc = GetObjectWithIdIncludingBlacklistCheck(207187)
            local nerub = GetObjectWithIdIncludingBlacklistCheck(203078)
            local vrykul = GetObjectWithIdIncludingBlacklistCheck(207189)
            local somethingA = GetObjectWithIdIncludingBlacklistCheck(246811)
            local somethingB = GetObjectWithIdIncludingBlacklistCheck(268453)
            local somethingC = GetObjectWithIdIncludingBlacklistCheck(268440)
            local highmountainA = GetObjectWithIdIncludingBlacklistCheck(268450)
            local highmountainB = GetObjectWithIdIncludingBlacklistCheck(246804)
            local artifact = nightelf or fossil or troll or dwarven or somethingElse or missing1 or missing2 or draenei or orc or nerub or vrykul or somethingA or somethingB or somethingC or highmountainA or highmountainB
            if artifact then
                BANETO_TARGET = artifact
                local x,y,z = BANETO_ObjectPosition(artifact)
                if not BANETO_PlayerPosition(x,y,z,5) then
                    BANETO_MeshTo(x,y,z)
                else
                    BANETO_Dismount()
                    CancelShapeshift()
                    BANETO_StopMovement()
                    BANETO_Interact(artifact)
                end
                return false
            end

            if CanScanResearchSite() then
                BANETO_ArcheologySite()
            else
                local digsite = BANETO_FindClosestDigsite()
                if digsite then
                    local name,x,y,researchId = digsite[1],digsite[2],digsite[3],digsite[4]
                    local _, _, wz = TraceLine(x, y, 3000, x, y, -3000, 0x00100111)
                    if not wz then
                        _,_,wz = BANETO_ObjectPosition("player")
                        wz = wz+50
                    end
                    if not BANETO_DIGISTE_INFO_SPAM or BANETO_DIGISTE_INFO_SPAM < GetTime() then
                        BANETO_DIGISTE_INFO_SPAM = GetTime()+20
                        ARCH_X = nil
                        BANETO_PrintState("ARCHEOLOGY: Going to digsite "..name)
                    end
                    BANETO_MeshTo(x,y,wz)
                else
                    BANETO_PrintError("No digsite found for this map!?")
                end
            end
        end

        if BANETO_State == "LOOTING"  then

            if _G.BANETO_ExecuteCustomQuestPulse ~= nil and _G.BANETO_ExecuteCustomQuestPulse_Looting and _G.BANETO_ExecuteCustomQuestPulse_Looting == true then
                _G.BANETO_ExecuteCustomQuestPulse()
                if _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior and _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior == true then
                    return true
                end
            end
            BANETO_LOOTARANG_ITERA = math.random(1,2)
            if (BANETO_LOOTARANG_ITERA and BANETO_LOOTARANG_ITERA == 1) or not PlayerHasToy(60854) then
                if BANETO_SETTING_LOOTARANAG and BANETO_SETTING_LOOTARANAG == true and PlayerHasToy(109167) then
                    if Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0 then
                        BANETO_StopMovement()
                    end
                    if Unlocker("LUA") and (not BANETO_SETTING_LOOTARANAG_DELAY or BANETO_SETTING_LOOTARANAG_DELAY < GetTime()) then
                        if _internal.Software() == "tnk" then
                            Eval("UseToy(60854)","asdasd")
                        end
                        if _internal.Software() == "nn" then
                            Unlock("UseToy",60854)
                        end
                        BANETO_SETTING_LOOTARANAG_DELAY = GetTime()+2
                        if not BANETO_SETTING_LOOTARANAG_USECOUNT then
                            BANETO_SETTING_LOOTARANAG_USECOUNT = 1
                        else
                            BANETO_SETTING_LOOTARANAG_USECOUNT = BANETO_SETTING_LOOTARANAG_USECOUNT+1
                        end
                    end
                    return true
                end
            elseif BANETO_LOOTARANG_ITERA and BANETO_LOOTARANG_ITERA == 2 then
                if BANETO_SETTING_LOOTARANAG and BANETO_SETTING_LOOTARANAG == true and PlayerHasToy(60854) then
                    if Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0 then
                        BANETO_StopMovement()
                    elseif Unlocker("EWT")  and BANETO_GetUnitSpeed("player") > 0 then
                        StopEwtMovement()
                    end
                    if Unlocker("LUA") and (not BANETO_SETTING_LOOTARANAG_DELAY or BANETO_SETTING_LOOTARANAG_DELAY < GetTime()) then
                        if _internal.Software() == "tnk" then
                            Eval("UseToy(60854)","asdasd")
                        end
                        if _internal.Software() == "nn" then
                            Unlock("UseToy",60854)
                        end
                        BANETO_SETTING_LOOTARANAG_DELAY = GetTime()+2
                        if not BANETO_SETTING_LOOTARANAG_USECOUNT then
                            BANETO_SETTING_LOOTARANAG_USECOUNT = 1
                        else
                            BANETO_SETTING_LOOTARANAG_USECOUNT = BANETO_SETTING_LOOTARANAG_USECOUNT+1
                        end
                    end
                    return true
                end
            end

            if UnitChannelInfo("player") or UnitCastingInfo("player") then
                if Unlocker("LUA") then
                    BANETO_StopMovement()
                elseif Unlocker("EWT") then
                    StopEwtMovement()
                end
                return false
            end
            if not BANETO_LOOTING_POPUPCLICK_DELAY or BANETO_LOOTING_POPUPCLICK_DELAY < GetTime() then
                BANETO_LOOTING_POPUPCLICK_DELAY = GetTime() + 3
                for i=1, GetNumLootItems() do
                    if LootSlotHasItem(i) then
                        LootSlot(i)
                        ConfirmLootSlot(i)
                    end
                end
            end
            if not BANETO_TARGET then
                BANETO_TARGET = BANETO_SCAN_LOOT()
            end
            if BANETO_TARGET then

                if BANETO_IsGuidContainedInGuidBlacklist(BANETO_TARGET) then
                    BANETO_TARGET = nil
                end
                if not BANETO_LOOT_DEBUG_TIMER2 then
                    BANETO_LOOT_DEBUG_TIMER2 = GetTime() + 25
                end
                if BANETO_LOOT_DEBUG_TIMER2 < GetTime() then
                    if BANETO_TARGET then
                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                        BANETO_TARGET = nil
                        BANETO_LOOT_DEBUG_TIMER2 = nil
                        BANETO_JumpOrAscendStart()
                        BANETO_PrintState("Blacklisted Loot Object - Possible Stuck 25 seconds elapsed")
                    end
                end
                if Unlocker("LUA") then
                    local x, y, z = BANETO_ObjectPosition(BANETO_TARGET)
                    if not x or not y or not z then
                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                        BANETO_TARGET = nil
                        return false
                    end
                    if not BANETO_PlayerPosition(x, y, z, 5) then
                        BANETO_MeshTo(x, y, z)
                        if BANETO_PlayerPosition(x, y, z, 16) and not BANETO_PlayerPosition(x, y, z, 5) then
                            if not BANETO_LOOT_DEBUG_TIMER then
                                BANETO_LOOT_DEBUG_TIMER = GetTime() + 25
                            end
                            if BANETO_LOOT_DEBUG_TIMER < GetTime() then
                                if BANETO_TARGET then
                                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                                    BANETO_TARGET = nil
                                    BANETO_PrintState("Blacklisted Loot Object - Possible Stuck")
                                end
                            end
                        end
                    else
                        if IsMounted() then
                            BANETO_Dismount()
                        end
                        if BANETO_GetUnitSpeed("player") ~= 0 then
                            BANETO_StopMovement()
                        end
                        if (not BANETO_LOOT_DELAY or BANETO_LOOT_DELAY < GetTime()) and GetUnitSpeed("player") == 0 then
                            BANETO_LUABOXUNSTUCK_COUNT = nil
                            BANETO_LOOT_DELAY = GetTime() + 1
                            if not LootFrame:IsVisible() then
                                BANETO_InteractNoDelay(BANETO_TARGET)
                                if _G.BANETO_SKIP_LOOT_AFTER_INTERACT then
                                    C_Timer.After(1,function()
                                        local t = BANETO_TARGET
                                        BANETO_AddMobToGuidBlacklist(t)
                                    end)
                                end
                                waPath = nil
                                BANETO_LOOT_DEBUG_TIMER = nil
                                if BANETO_SETTING_MULTILOOT and BANETO_SETTING_MULTILOOT == true then
                                    _G.BANETO_MULTILOOT_TIMER = GetTime()+_G.BANETO_SETTING_MULTILOOT_DELAY
                                    _G.BANETO_MULTILOOT_LASTVECTOR = {}
                                    _G.BANETO_MULTILOOT_LASTVECTOR[1],_G.BANETO_MULTILOOT_LASTVECTOR[2],_G.BANETO_MULTILOOT_LASTVECTOR[3] = BANETO_ObjectPosition("player")
                                end
                                C_Timer.After(0.5,function()
                                    if BANETO_GetState() == "LOOTING" and BANETO_TARGET then
                                        BANETO_TARGET = nil
                                    end
                                end)
                            end
                        end
                    end
                end
            end
        end

        if BANETO_State == "FP-DISCOVER" then
            if not BANETO_TARGET then
               BANETO_TARGET = BANETO_SCAN_FPMASTER_SL()
                if BANETO_TARGET then
                    if Unlocker("LUA") and lb then
                        local name = lb.ObjectName(BANETO_TARGET)
                         BANETO_PrintState("Found Flightmaster to discover: " .. name )
                    elseif  Unlocker("LUA") then
                          local name = BANETO_ObjectName(BANETO_TARGET)
                           BANETO_PrintState("Found Flightmaster to discover: " .. name )
                    elseif Unlocker("EWT") then
                        local name = ObjectName(BANETO_TARGET)
                        BANETO_PrintState("Found Flightmaster to discover: " .. name )
                    end
                end
            end
            if BANETO_TARGET then
                local x, y, z = BANETO_ObjectPosition(BANETO_TARGET)
                if not BANETO_PlayerPosition(x, y, z, 3) then
                    BANETO_MeshTo(x, y, z)
                else
                    local _, _, class = UnitClass("player")
                    if class == 11 or class == 7 then
                        CancelShapeshift()
                    end
                    if BANETO_GetUnitSpeed("player") == 0 then
                        if IsMounted() then
                            BANETO_Dismount()
                        end
                        if Unlocker("LUA") then
                            BANETO_Interact(BANETO_TARGET)
                            local id = BANETO_ObjectId(BANETO_TARGET)
                            local x,y,z = BANETO_ObjectPosition(BANETO_TARGET)
                            BANETO_DefineKnownFlightmasterV2(x,y,z,id)
                            BANETO_FPDISCOVER_NEEDED = nil
                            BANETO_FPDISCOVER_DONE = true
                        elseif Unlocker("EWT") then
                            ObjectInteract(BANETO_TARGET)
                            local id = ObjectID(BANETO_TARGET)
                            local x,y,z = ObjectPosition(BANETO_TARGET)
                            BANETO_DefineKnownFlightmasterV2(x,y,z,id)
                            BANETO_FPDISCOVER_NEEDED = nil
                            BANETO_FPDISCOVER_DONE = true
                        end
                    else
                        BANETO_StopMovement()
                    end
                end
            else
                BANETO_FPDISCOVER_NEEDED = nil
                if not BANETO_FPDISCOVER_ERROR then
                    BANETO_FPDISCOVER_ERROR=true
                    BANETO_PrintError("Problem in Flightmaster Discovery, trying our best to reach the target! " )
                end
            end
        end

        if BANETO_State == "FP-TAXI" then
            local x, y, z, id = BANETO_GetClosestTaxiEntry()
            if not UnitOnTaxi("player") and not BANETO_TAXIFLIGHT_BEGAN and BANETO_TAXI_NEEDED and (not BANETO_TAXI_DELAYER or BANETO_TAXI_DELAYER < GetTime())then
                if Unlocker("EWT") and not ewtPath then
                    if not BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER and not BANETO_PlayerPosition(x, y, z,4) then
                        BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER=GetTime()+21
                    elseif BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER and BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER < GetTime() and not BANETO_PlayerPosition(x, y, z,4) then
                        BANETO_PrintError("No path found for state: " .. BANETO_State .. " | Blacklisting the state for this session!")
                        BANETO_STATEBLOCK_NOPATH_FPTAXI_BLACKLIST = true
                        BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER = nil
                    elseif BANETO_PlayerPosition(x, y, z,4)  then
                        BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER = nil
                    end
                elseif Unlocker("EWT") and ewtPath and BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER then
                    BANETO_STATEBLOCK_NOPATH_FPTAXI_TIMER = nil
                end
                local x, y, z, id = BANETO_GetClosestTaxiEntry()
                if not BANETO_PlayerPosition(x, y, z, 3.5) then
                    BANETO_MeshTo(x, y, z)
                    if BANETO_REACHED_TAXI_ENTRY then
                        BANETO_REACHED_TAXI_ENTRY = nil
                    end
                else
                    if not BANETO_REACHED_TAXI_ENTRY and not UnitOnTaxi("player") and not UnitAffectingCombat("player") then
                        BANETO_REACHED_TAXI_ENTRY = true
                        BANETO_REACHED_TAXI_ENTRY_TIME = GetTime()+11
                    elseif BANETO_REACHED_TAXI_ENTRY_TIME < GetTime() and not UnitOnTaxi("player") and not UnitAffectingCombat("player") then
                        BANETO_REACHED_TAXI_ENTRY = nil
                        BANETO_REACHED_TAXI_ENTRY_TIME = nil
                        BANETO_TAXI_DELAYER_TOTALBLOCK = GetTime()+3600
                        BANETO_TAXI_NEEDED = nil
                        BANETO_TAXIFLIGHT_BEGAN = nil
                        BANETO_PrintState("[TAXI] Blacklisted Taxi Usage for 60 Minutes due to missing money or other problems!")
                    end

                    local _, _, class = UnitClass("player")
                    if class == 11 then
                        CancelShapeshift()
                    end
                    if BANETO_GetUnitSpeed("player") == 0 then
                        if IsMounted() then
                            BANETO_Dismount()
                        end
                        if Unlocker("LUA") then
                            local object = GetObjectWithCoordinates( x, y, z, id)
                            if object then
                                BANETO_Interact(object)
                                BANETO_UseTaxiNode(BANETO_TAXI_CHOSEN_NODENAME)
                            end
                        elseif Unlocker("EWT") then
                            local object = GetObjectWithCoordinates( x, y, z, id)
                            if object then
                                ObjectInteract(object)
                                BANETO_UseTaxiNode(BANETO_TAXI_CHOSEN_NODENAME)
                            end
                        end
                    else
                        BANETO_StopMovement()
                    end
                end
            elseif UnitOnTaxi("player") and not BANETO_TAXIFLIGHT_BEGAN then
                BANETO_TAXIFLIGHT_BEGAN = true
                BANETO_REACHED_TAXI_ENTRY = nil
                BANETO_REACHED_TAXI_ENTRY_TIME = nil
            elseif UnitOnTaxi("player") and BANETO_TAXIFLIGHT_BEGAN then
                BANETO_TAXI_DELAYER_TOTALBLOCK = GetTime()+3
            elseif not UnitOnTaxi("player") and BANETO_TAXIFLIGHT_BEGAN then
                if TaxiFrame and TaxiFrame:IsVisible() then
                    TaxiFrameCloseButton:Click()
                end
                BANETO_TAXIFLIGHT_BEGAN = nil
                BANETO_TAXI_NEEDED = nil
                BANETO_TAXI_DELAYER_TOTALBLOCK=GetTime()+15
                BANETO_STOPMOUNTBECAUSEUNSTUCK = GetTime()+5
                BANETO_TAXI_FINISHED_LEAVESTATE = true
                BANETO_PrintState("[TAXI] Thanks for flying with Baneto Airlines, we hope you had a good flight!")
                if FlightMapFrameCloseButton and FlightMapFrameCloseButton:IsVisible() then
                    FlightMapFrameCloseButton:Click()
                end
            end
        end

        if BANETO_State == "ROTATION" then

            if UnitExists("target") and GetDistanceBetweenObjects("player", "target") <= BANETO_COMBAT_RANGE and BANETO_UnitHealth("target") > 0 then
                if IsMounted()  and BANETO_SETTING_IGNORECOMBATWHENMOUNTED == false then
                    BANETO_Dismount()
                end
                local _,_,class =  UnitClass("player")
                if class == 11 then
                    local travel = 292629

                    if BANETO_HasBuff("player",travel) then
                        CancelBuff(travel)

                    end
                    if GetShapeshiftForm() == 3 then
                        CancelShapeshift()
                    end
                end
                if BANETO_SETTING_DISABLECOMBATROUTINE and BANETO_SETTING_DISABLECOMBATROUTINE == true and not isHekiliLoaded() and (not BANETO_SETTING_DISABLECOMBATROUTINE_WARN or BANETO_SETTING_DISABLECOMBATROUTINE_WARN < GetTime()) then
                    BANETO_PrintError("Rotation mode is useless if you do not use hekili addon. If you use noro, that works even with baneto being disabled!")
                    BANETO_SETTING_DISABLECOMBATROUTINE_WARN = GetTime()+10
                    BANETO_Stop()
                end
                if Unlocker("LUA") then
                    if not BANETO_SETTING_DISABLECOMBATROUTINE or BANETO_SETTING_DISABLECOMBATROUTINE == false then
                        InactiveRotation()
                    end
                elseif Unlocker("EWT") then
                    if not BANETO_SETTING_DISABLECOMBATROUTINE or BANETO_SETTING_DISABLECOMBATROUTINE == false then
                        InactiveRotation()
                    end
                end
            end
        end

        local guildchestH = GetObjectWithId(206603)
        local guildchestA = GetObjectWithId(206602)
        local mobcountStash = GetNumHostileEnemiesAroundUnit("player",55)
        local _,stashSpellCooldown,_ = GetSpellCooldown(83958)

        if BANETO_State ~= "STASHING" and not IsFlying() and (not stashSpellCooldown or stashSpellCooldown == 0 or _G.BANETO_BLOCK_MOBILE_GUILD_CHEST) and (not mobcountStash or mobcountStash == 0) and BANETO_IsStashingNeeded() and not UnitAffectingCombat("player") and not BANETO_IsDeadOrGhost() and (not BANETO_STASHING_MASTER_DELAY or BANETO_STASHING_MASTER_DELAY < GetTime() or guildchestH or guildchestA) and (BANETO_State == "GRIND" or BANETO_State == "QUEST-PULSE" or BANETO_State == "FISHING-SPOT") then
            if Unlocker("EWT") then
                StopEwtMovement()
            elseif Unlocker("LUA") then
                BANETO_StopMovement()
            end
            BANETO_State = "STASHING"
            GUILD_BANK_FULL_COUNTER = nil
            BANETO_PrintState("Begin guild bank stashing!")
            BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            BANETO_ENTER_STASHING_TIME = GetTime()
            BANETO_FLYINGASCEND_STOPPER = GetTime()+12
            xG,yG,zG = nil,nil,nil
            xG2,yG2,zG2 = nil,nil,nil
        end
        local gold = math.floor(GetMoney()/10000)

        if BANETO_State == "STASHING" and (BANETO_GetTotalStashableItemCount() > 0 or (_G.BANETO_SETTING_STASHING_GOLD_TRIGGER ~= 0 and gold >= _G.BANETO_SETTING_STASHING_GOLD_TRIGGER)) then
            if _G.BANETO_BLOCK_MOBILE_GUILD_CHEST then
                return true
            end
            local guildchestH = GetObjectWithId(206603)
            local guildchestA = GetObjectWithId(206602)
            local guidchestSpell = 83958
            BANETO_StopMovement()
            waPath = nil
            flyingPath = nil
            if IsMounted() and not IsFlying() then
                BANETO_Dismount()
            elseif IsFlying() then
                BANETO_SitStandOrDescendStart()
                BANETO_FORCEDESCEND_GATHER = true
            else
                if BANETO_FORCEDESCEND_GATHER and BANETO_FORCEDESCEND_GATHER == true then
                    BANETO_DescendStop()
                    BANETO_FORCEDESCEND_GATHER = nil
                end
                if (guildchestA or guildchestH) and stashSpellCooldown ~= 0 then
                    if guildchestA then
                        xG,yG,zG = BANETO_ObjectPosition(guildchestA)
                    elseif guildchestH then
                        xG2,yG2,zG2 = BANETO_ObjectPosition(guildchestH)
                    end
                    if (xG and not BANETO_PlayerPosition(xG,yG,zG,5)) or (xG2 and not BANETO_PlayerPosition(xG2,yG2,zG2 ,5)) then
                        if xG then
                            BANETO_MeshTo(xG,yG,zG)
                        else
                            BANETO_MeshTo(xG2,yG2,zG2)
                        end
                    else
                        if Unlocker("EWT") and BANETO_GetUnitSpeed("player") > 0 then
                            StopEwtMovement()
                        elseif Unlocker("LUA") and BANETO_GetUnitSpeed("player") > 0  then
                            BANETO_StopMovement()
                        end
                        if GuildBankFrame and GuildBankFrame:IsVisible() then
                            if not BANETO_STASH_DELAY then
                                BANETO_STASH_DELAY = GetTime()+1
                            end
                            BANETO_StashItemsInGuildChest()
                        else
                            if guildchestA then
                                BANETO_Interact(guildchestA)
                            end
                            if guildchestH then
                                BANETO_Interact(guildchestH)
                            end
                        end
                    end
                elseif (not BANETO_STASHING_SPAWN_DELAY or BANETO_STASHING_SPAWN_DELAY < GetTime()) then
                    if stashSpellCooldown and stashSpellCooldown == 0 then
                        BANETO_CastSpell(guidchestSpell,true)
                        BANETO_STASHING_SPAWN_DELAY = GetTime()+5
                    end
                end
            end
        elseif (BANETO_State == "STASHING" and BANETO_GetTotalStashableItemCount() == 0 and (_G.BANETO_SETTING_STASHING_GOLD_TRIGGER == 0 or _G.BANETO_SETTING_STASHING_GOLD_TRIGGER>gold)) or (BANETO_State == "STASHING" and BANETO_ENTER_STASHING_TIME+60 < GetTime()) then
            BANETO_ROGUE_TRIEDAMBUSH = nil
            BANETO_PrintState("End guild bank stashing!")
            BANETO_TAXI_DELAYER = GetTime()+2.5
            BANETO_STASHING_MASTER_DELAY = GetTime()+600
            BANETO_MOBSCAN_1MINUTE_DEBUGGER = nil
            BANETO_FIGHTING_EMERGENCY_LEAVE = nil
            if BANETO_SETTING_GBANK_LONGDELAY and BANETO_SETTING_GBANK_LONGDELAY == true then
                BANETO_PrintState("Stashing finished. LONG Delay for stashing. At least 1,5h delay.")
                local random = math.random(100,1800)
                BANETO_STASHING_MASTER_DELAY = GetTime()+4800+random
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Grinding" then
                BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(15, 31)
                if _G.BANETO_MORE_JUMPS then
                    BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(2, _G.BANETO_MORE_JUMPS)
                end
                BANETO_State = "GRIND"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
                BANETO_State = "BG-MASTER"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Slavemode" then
                BANETO_State = "SLAVE"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "BRD" then
                BANETO_State = "BRD-MASTER"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Traveling" then
                BANETO_State = "TRAVEL"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Questing" then
                BANETO_State = "QUEST-MASTER"
                BANETO_TARGET = nil
                BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
            end
            if BANETO_DEFINED_PROFILE_TYPE == "Fishing" then
                if BANETO_PROFILE_NAME == "Skill-Fishing" then
                    BANETO_State = "FISHING-SKILL"
                    BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                else
                    BANETO_State = "FISHING-SPOT"
                    BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                end
            end
        end

        if BANETO_State == "SKINNING" then
            if _G.BANETO_ExecuteCustomQuestPulse ~= nil and _G.BANETO_ExecuteCustomQuestPulse_Looting and _G.BANETO_ExecuteCustomQuestPulse_Looting == true then
                _G.BANETO_ExecuteCustomQuestPulse()
                if _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior and _G.BANETO_ExecuteCustomQuestPulse_SkipNormalBehavior == true then
                    return true
                end
            end

            if UnitChannelInfo("player") or UnitCastingInfo("player") then
                if Unlocker("LUA") then
                    BANETO_StopMovement()
                elseif Unlocker("EWT") then
                    StopEwtMovement()
                end
                return false
            end
            --[[ print(5) --]]
            if not BANETO_TARGET then
                BANETO_TARGET = BANETO_SCAN_SKINNING()
                if BANETO_TARGET then
                    BANETO_SKIN_STOPP_TIMER = nil
                end
            end
            if not BANETO_SKIN_DELAY then
                BANETO_SKIN_DELAY = GetTime()
            end
            if BANETO_TARGET then
                --[[ print(6) --]]
                local x, y, z = BANETO_ObjectPosition(BANETO_TARGET)
                if ObjectSkinnable(BANETO_TARGET) then

                else
                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                    BANETO_TARGET = nil
                    return false
                end
                if not x then
                    if Unlocker("LUA") then
                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                        BANETO_TARGET = nil
                        return false
                    end

                end

                if not BANETO_PlayerPosition(x, y, z, _G.BANETO_SKINNING_DISTANCE) then
                    --[[ print(7) --]]
                    --[[ print(x) --]]
                    BANETO_MeshTo(x, y, z)
                    if BANETO_SKIN_STOPP_TIMER then
                       BANETO_SKIN_STOPP_TIMER = nil
                    end
                else
                    if IsFlying() then
                        BANETO_SitStandOrDescendStart()
                        BANETO_FLYINGASCEND_STOPPER = GetTime()+0.5
                        BANETO_FORCEDESCEND_GATHER = true
                    else
                        if BANETO_FORCEDESCEND_GATHER and BANETO_FORCEDESCEND_GATHER == true then
                            BANETO_DescendStop()
                            BANETO_FORCEDESCEND_GATHER=nil
                        end
                        if BANETO_GetUnitSpeed("player") > 0 then
                            if Unlocker("LUA") then
                                BANETO_StopMovement()
                            elseif Unlocker("EWT") then
                                StopEwtMovement()
                            end
                        end
                        --[[ print(8) --]]
                        if BANETO_GetUnitSpeed("player") == 0 and not UnitCastingInfo("player") then
                            if IsMounted() then
                                BANETO_Dismount()
                            end
                            if BANETO_SKIN_DELAY < GetTime() then
                                BANETO_SKIN_DELAY = GetTime() + BANETO_CUSTOM_SKINNING_DELAY
                                if Unlocker("LUA") then
                                    if ObjectSkinnable(BANETO_TARGET) or BANETO_ObjectId(BANETO_TARGET) ==  348935 then
                                        BANETO_Interact(BANETO_TARGET)
                                        --BANETO_PrintBambo("Skinning - Interact 1")
                                        BANETO_LAST_SKIN_GUID = BANETO_TARGET
                                        if not BANETO_SKIN_STOPP_TIMER then
                                            --BANETO_PrintBambo("Skinning - Interact Stop Timer Start")
                                            BANETO_SKIN_STOPP_TIMER = GetTime()+BANETO_SKIN_STOPP_TIMER_DELAY
                                        end
                                    end
                                end
                            end
                            if BANETO_SKIN_STOPP_TIMER and BANETO_SKIN_STOPP_TIMER < GetTime() and BANETO_TARGET then
                                if ObjectSkinnable(BANETO_TARGET) or BANETO_SKIN_STOPP_TIMER+9 < GetTime() then
                                    if not ObjectSkinnable(BANETO_TARGET)  then
                                        BANETO_AddMobToGuidSkinnedlist(BANETO_TARGET)
                                        BANETO_TARGET = nil
                                        BANETO_SKIN_STOPP_TIMER = nil
                                        --BANETO_PrintBambo("Skinning - Mob skinned list")
                                    elseif BANETO_SKIN_STOPP_TIMER and BANETO_SKIN_STOPP_TIMER+9 < GetTime() then
                                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                                        BANETO_TARGET = nil
                                        BANETO_SKIN_STOPP_TIMER = nil
                                        --BANETO_Print("SKINNING mob seems to be problematic, blacklisting it!")
                                    elseif not UnitCastingInfo("player") and not UnitCastingInfo("player") then
                                        BANETO_Interact(BANETO_TARGET)
                                        --BANETO_PrintBambo("Skinning - Interact 2")
                                        BANETO_LAST_SKIN_GUID = BANETO_TARGET
                                    end
                                    return
                                elseif Unlocker("LUA") and  BANETO_TARGET and not UnitCastingInfo("player") and not UnitCastingInfo("player") and not LootFrame:IsVisible() then
                                    BANETO_Interact(BANETO_TARGET)
                                    --BANETO_PrintBambo("Skinning - Interact 3")
                                    BANETO_LAST_SKIN_GUID = BANETO_TARGET
                                end
                            end
                        end
                    end
                end
            end
        end

        if BANETO_State == "SLAVE" then
            local master = BANETO_GetMyMaster()
            if not UnitCastingInfo("player") and BANETO_HasItemToOpen() and not UnitChannelInfo("player") then
                BANETO_PrintState("Auto opening items in SLAVE state")
                BANETO_AutoOpenItems()
            end
            if master then
                if BANETO_SETTING_RANDOMJUMPS == true and not IsFlying() and not IsFalling() and not BANETO_EXECUTE_FLY_ASCEND then
                    if BANETO_RANDOMJUMP_DELAY < GetTime() and (not GetShapeshiftDruid() or GetShapeshiftDruid() == 0) and not IsFlying() and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
                        BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(15, 35)
                        if _G.BANETO_MORE_JUMPS then
                            BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(2, _G.BANETO_MORE_JUMPS)
                        end
                        if Unlocker("EWT") then
                            BANETO_JumpAllowed = true
                            JumpOrAscendStart()
                        elseif Unlocker("LUA") then
                            BANETO_JumpAllowed = true
                            BANETO_JumpOrAscendStart(22)
                        elseif CallSecureFunction then
                            BANETO_JumpAllowed = true
                            CallSecureFunction("JumpOrAscendStart")
                        end
                    end
                end
                if not BANETO_MASTER_FOUND then
