                if Unlocker("LUA") then
                    if not UnlockedUnitAffectingCombat(master) or (BANETO_FORCE_FOLLOW_MASTER and BANETO_GetUnitSpeed(master) > 0 and slavemodeplus == true) then
                        BANETO_LUABOX_TARGETSTICK = true
                        local masterstarget = BANETO_UnitTarget(master)
                        if masterstarget and UnlockedTargetReaction(masterstarget) == 5 and not BANETO_IsPetLuabox(masterstarget) and not UnitIsPlayer(masterstarget) and GetDistanceBetweenObjects(master,masterstarget) < 10 then
                            BANETO_Print("Slave will copy master's npc behavior now.")
                            local dist = GetDistanceBetweenObjects("player",masterstarget)
                            if dist < 6 then
                                BANETO_StopMovement()
                                if not slaveInteractDelay or slaveInteractDelay < GetTime() then
                                    BANETO_InteractNoDelay(masterstarget)
                                    slaveInteractDelay = GetTime()+8
                                end
                                if not BANETO_SLAVE_SELL_START_DELAY then
                                    BANETO_SLAVE_SELL_START_DELAY = GetTime()+4
                                end
