                            BANETO_StopMovement()
                            BANETO_PrintBambo("SLAVE ---- Stop following Master")
                        end
                    elseif UnlockedUnitAffectingCombat(master) or (BANETO_IsGroupAffectingCombat() and BANETO_SETTING_HEALERSLAVE and BANETO_SETTING_HEALERSLAVE == true) then

                        local rogueStealth = 1785
                        local druidStealth = 5215
                        if BANETO_HasBuff("player",druidStealth) then
                            CancelBuff(druidStealth)
                        end
                        if BANETO_HasBuff("player",rogueStealth) then
                            CancelBuff(rogueStealth)
                        end

                        BANETO_PrintBambo("SLAVE ---- Master/group IS IN COMBAT!!!")
                        BANETO_LUABOX_TARGETSTICK = true
                        if BANETO_SETTING_HEALERSLAVE and BANETO_SETTING_HEALERSLAVE == true then
                            BANETO_PrintBambo("SLAVE ---- Is healer")
                            if (not  BANETO_TARGETDELAY_HEALERSLAVE or BANETO_TARGETDELAY_HEALERSLAVE < GetTime()) and BANETO_SETTING_ACTIVEENGAGE and BANETO_SETTING_ACTIVEENGAGE == true then
                                BANETO_TARGETDELAY_HEALERSLAVE = GetTime()+0.5
                                if BANETO_UnitHealth("player") < 95 then
                                    UnlockedTargetUnit("player")
                                    BANETO_PrintBambo("TARGETING: H")
                                elseif BANETO_UnitHealth(master) and BANETO_UnitHealth(master) < 95 then
                                    UnlockedTargetUnit(master)
                                elseif UnitExists("party1") and BANETO_UnitHealth("party1") < 95 then
                                    UnlockedTargetUnit("party1")
                                    BANETO_PrintBambo("TARGETING: H")
                                elseif UnitExists("party2") and BANETO_UnitHealth("party2") < 95 then
                                    UnlockedTargetUnit("party2")
                                elseif UnitExists("party3") and BANETO_UnitHealth("party3") < 95 then
                                    UnlockedTargetUnit("party3")
                                elseif UnitExists("party4") and BANETO_UnitHealth("party4") < 95 then
                                    UnlockedTargetUnit("party4")
                                elseif UnitExists("party5") and BANETO_UnitHealth("party5") < 95 then
                                    UnlockedTargetUnit("party5")
                                else
                                    BANETO_PrintBambo("TARGETING: H")
                                    UnlockedTargetUnit(master)
                                end
                            end
                            if UnitExists("target") and BANETO_UnitHealth("target") <= 95 then
                                local xMob, yMob, zMob = BANETO_ObjectPosition("target")
                                if BANETO_PlayerPosition(xMob, yMob, zMob, BANETO_COMBAT_RANGE) then
                                    local speed = BANETO_GetUnitSpeed("player")
                                    if speed and 0<speed then
                                        BANETO_StopMovement()
                                    else
                                        BANETO_SetPlayerAnglesLuabox(BANETO_GetFacingValue(xMob, yMob, zMob))
                                        if BANETO_SETTING_DISABLECOMBATROUTINE == false then
                                            BANETO_HealFriendlyTarget()
                                            if IsMounted() then
                                                BANETO_Dismount()
                                            end
                                        end
                                    end
                                elseif not UnitCastingInfo("player")  and not UnitChannelInfo("player") then
                                    BANETO_MeshTo(xMob, yMob, zMob)
                                end
                            end
                        else
                            BANETO_PrintBambo("SLAVE ---- Is damage")
                            local masterstarget = BANETO_UnitTarget(master)
                            if masterstarget and BANETO_SETTING_ACTIVEENGAGE and BANETO_SETTING_ACTIVEENGAGE == true then
                                local nameTargetOfMaster = BANETO_ObjectName(masterstarget)
                                if not nameTargetOfMaster then
                                    nameTargetOfMaster = "unknown"
                                end
                                BANETO_PrintBambo("SLAVE ---- targeting master target: "..nameTargetOfMaster)
                                UnlockedTargetUnit(masterstarget)
                            else
                                BANETO_PrintBambo("SLAVE ---- master target NOT FOUND OR ACTIVE ENGAGING DISABLED")
                            end
                            BANETO_PrintBambo("TARGETING: I")
                            if UnitExists("target") and UnlockedUnitAffectingCombat(masterstarget)  then
                                local xMob, yMob, zMob = BANETO_ObjectPosition("target")
                                if BANETO_IsTargetInLos() and  BANETO_PlayerPosition(xMob, yMob, zMob, BANETO_COMBAT_RANGE)  then
                                    BANETO_StopMovement()
                                    BANETO_PrintBambo("SLAVE ---- attacking master target")
                                    BANETO_SetPlayerAnglesLuabox(BANETO_GetFacingValue(xMob, yMob, zMob))
                                    if IsMounted() then
                                        BANETO_Dismount()
                                    end
                                    if BANETO_SETTING_DISABLECOMBATROUTINE == false then
