                elseif BANETO_IsSpellUsable(aura) and not BANETO_HasBuff(p, aura) and not BANETO_IsSpellKnown(sancAura) then
                    BANETO_CastSpell(aura, true)
                end
                if BANETO_IsSpellUsable(bom) and not BANETO_HasBuff(p, bom) then
                    BANETO_CastSpell(bom, true)
                end
            end

