                        BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = ObjectPosition("player")
                    elseif Unlocker("LUA") then
                        BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = BANETO_ObjectPosition("player")
                    end
                    return
                end
            end
            if not BANETO_TARGET then
                BANETO_PrintBambo("GATHER mssing target")
                baneto_rtl_gatherinteract = GetTime()+1
            end
            if UnitCastingInfo("player") and BANETO_TARGET and not ObjectLootable(BANETO_TARGET) then
                local spell, rank, displayName, icon, startTime, endTime, isTradeSkill, castID, interrupt = UnitCastingInfo("player")
