                    elseif Unlocker("LUA") then
                        BANETO_GATHER_TARGET_COORDS[1],BANETO_GATHER_TARGET_COORDS[2],BANETO_GATHER_TARGET_COORDS[3] = BANETO_ObjectPosition("player")
                    end
                    return
                end
                local objectId = BANETO_ObjectId(BANETO_TARGET)
                local rangeInteract =  5.8
                if objectId and objectId == 382075 then
                    rangeInteract = 4
                end
                if IsFlying() and not BANETO_IsDragonRiding() and not BANETO_PlayerPosition(x, y, z,20) then
                    z = z+10
                    y = y+1
                end
                if not BANETO_PlayerPosition(x, y, z,rangeInteract) then
                    BANETO_MeshTo(x, y, z)
                    if BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT then
                        BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT = nil
                    end
