                        BANETO_DescendStop()
                        BANETO_FORCEDESCEND_GATHER=nil
                    end
                else
                    BANETO_StopMovement()
                    waPath = nil
                    flyingPath = nil
                    local objectid = BANETO_ObjectId(BANETO_TARGET)
                    if objectid == 384292 then
                        if not UnitCastingInfo("player") then
                            local seed = BANETO_GetBestSeedInBags()
                            if not BANETO_IsDragonRiding() and IsMounted() then
                                BANETO_Dismount()
                            end
                            CancelShapeshift()
