                                if seed == 200509 then
                                    BANETO_USED_SEED_AGITATED = true
                                    BANETO_PrintState("Used agitated seed. Blacklisting item 200509 for this session.")
                                elseif seed == 200508 then
                                    --BANETO_USED_SEED_PROPAGATING = true
                                    --BANETO_PrintState("Used propagating seed. Blacklisting item 200508 for this session.")
                                elseif seed == 200507 then
                                    --BANETO_USED_SEED_DECAYED = true
                                    --BANETO_PrintState("Used decayed seed. Blacklisting item 200507 for this session.")
                                end
                                if BANETO_TARGET and BANETO_ObjectId(BANETO_TARGET) == 384292 then
                                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                                    BANETO_ClearTarget()
                                    BANETO_TARGET = nil
                                end
                            end)
                            return false
                        end
                    end
                    if objectid == 437383 then
                        if not UnitCastingInfo("player") then
                            local seed = BANETO_GetBestSeedInBags()
                            if not BANETO_IsDragonRiding() and IsMounted() then
                                BANETO_Dismount()
                            end
                            CancelShapeshift()
                            BANETO_DelayMeshPathing(8)
                            BANETO_UseItem(seed)
                            C_Timer.After(2, function()

                                if BANETO_TARGET and BANETO_ObjectId(BANETO_TARGET) == 437383 then
                                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                                    BANETO_ClearTarget()
                                    BANETO_TARGET = nil
                                end
                            end)
                            return false
                        end
                    end
                    if BANETO_IsDragonRiding() and BANETO_TARGET and not UnitCastingInfo("player") then
