                            BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT = GetTime()+8
                        elseif BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT and BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT < GetTime() then
                            BANETO_Dismount()
                            CancelShapeshift()
                            waPath = nil
                            flyingPath = nil
