                                LAST_NOT_POSSIBLE_GATHER = BANETO_TARGET
                            else
                                if LAST_NOT_POSSIBLE_GATHER == BANETO_TARGET then
                                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                                    BANETO_TARGET = nil
                                end
                                LAST_NOT_POSSIBLE_GATHER = nil
                            end
                            BANETO_PrintState("Dragonriding emergency dismount, close to gather node but no landing possible?")
                            return false
                        end
                    else
                        BANETO_GATHER_DRAGONRIDE_EMERGNCY_DISMOUNT = nil
                    end
                    BANETO_PrintDev("Stop movement, we are at gather node..")
                    if BANETO_TARGET and not BANETO_IsUnitGatherableMob(BANETO_TARGET,objectid) and ((BANETO_Software() == "nn" and not BANETO_IsJin() and not ObjectLootableRaw(BANETO_TARGET)) or (BANETO_Software() == "tnk" and not ObjectLootable(BANETO_TARGET)) or (BANETO_IsJin() and not Tinkr.GameObjectIsUsable(BANETO_TARGET,false))) then
                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                        BANETO_TARGET = nil
                        BANETO_PrintDev("return false in gather due to object not lootable")
                        return false
                    end
                    local _, _, class = UnitClass("player")

                    local numEnemiesGather = GetNumEnemiesAroundUnit("player",7)
                    local travel = 292629
                    local overload,overloadType;
                    if BANETO_OBJECTS_DF_OVERLOADS[objectid] then
                        overload,overloadType = BANETO_OBJECTS_DF_OVERLOADS[objectid][1],BANETO_OBJECTS_DF_OVERLOADS[objectid][2]
                    end
                    if overload and overloadType and (not BANETO_OVERLOAD_TRY or BANETO_OVERLOAD_TRY < 7) and BANETO_SETTING_OVERLOAD and BANETO_SETTING_OVERLOAD == true and BANETO_CheckOverload(overloadType) and BANETO_IsSpellUsable(overload) and ( not overloadDelay or overloadDelay < GetTime() ) then
                        local cooldownOverload,_,_,_ = GetSpellCooldown(overload)
                        if cooldownOverload and cooldownOverload == 0 then
                            if BANETO_Customer() == "bambo" then
                                BANETO_Stop()
                                return false
                            end
                            --overloadDelay = GetTime()+3
                            BANETO_LAST_OVERLOAD = GetTime()+90
                            BANETO_StopMovement()
                            if not BANETO_IsDragonRiding() and IsMounted() then
                                BANETO_Dismount()
                            end
                            if overloadType == "Lambent" then
                                BANETO_SetSTOPFIGHT_EVADE(GetTime()+10)
                                BANETO_DelayMeshPathing(3.5)
                                BANETO_PrintState("Lambent Overload, blocking FIGHTING state to focus on spores. Delaying movement & fighting + force mounting.")
                                BANETO_SetFIGHTING_EMERGENCY_LEAVE(true)
                                C_Timer.After(3.2,function()
                                    if not IsMounted() and not UnitAffectingCombat("player") and not UnitCastingInfo("player") then
                                        BANETO_FlyMount()
                                    end
                                end)
                                waPath = nil
                                flyingPath = nil
                            end
                            if overloadType == "crystalized" then
                                C_Timer.After(3,function()
                                    BANETO_OVERLOADED_CRYSTALLIZED_LAST = GetTime()+30
                                end)
                            end
                            if overloadType == "altered" or overloadType == "weeping" then
                                BANETO_PrintState("Altered or Weeping: Cooldowns needed to fight mob!")
                                BANETO_DelayMeshPathing(15)
                                C_Timer.After(6,function()
                                    BANETO_Dismount()
                                    CancelShapeshift()
                                end)
                                C_Timer.After(6,BANETO_OverloadCombatCooldowns)
                                C_Timer.After(9,BANETO_OverloadCombatCooldowns)
                                C_Timer.After(12,BANETO_OverloadCombatCooldowns)
                            end
                            if overloadType == "Metamorphic" then
                                BANETO_DelayMeshPathing(3.5)
