                    if IsMounted() and not _G.BANETO_BLOCK_GATHER_DISMOUNT and not BANETO_IsDragonRiding() and not BANETO_HasBuff("player",buff_demonsteel)  and not BANETO_HasBuff("player",travel) and (BANETO_IsMiningNode(objectid) or not BANETO_HasBuff("player",134359)) then
                         BANETO_Dismount()
                         BANETO_PrintBambo("GATHER dismount")
                    elseif BANETO_HasBuff("player",travel) and BANETO_IsMiningNode(objectid) then
                        CancelShapeshift()
                        BANETO_PrintBambo("GATHER cancelshapeshif")
                    elseif BANETO_GetUnitSpeed("player") == 0 then
                        --BANETO_PrintBambo("GATHER speed 0")
                        if BANETO_Plugin_GatherInteract ~= nil then
                            BANETO_Plugin_GatherInteract()
                        end

                        if IsFlying() then
                            BANETO_SitStandOrDescendStart()
                            BANETO_FORCEDESCEND_GATHER = true
                            if not BANETO_LANDING_GATHER_STRAFE then
                                BANETO_LANDING_GATHER_STRAFE = true
                                C_Timer.After(2,function()
                                    if not BANETO_IsDragonRiding() and IsFlying() and not UnitCastingInfo("player") and BANETO_GetState() == "GATHER" and BANETO_TARGET and GetDistanceBetweenObjects("player",BANETO_TARGET) < 10 then
                                        BANETO_StrafeLeftStart()
                                        C_Timer.After(0.1,BANETO_StrafeLeftStop)
                                        C_Timer.After(0.2,BANETO_StrafeRightStart)
                                        C_Timer.After(0.3,BANETO_StrafeRightStop)
                                        BANETO_PrintWarning("Trouble landing? LANDING WIGGLE NOW!")
                                    end
                                end)
                            end
                        else
