                                if not UnitCastingInfo("player") and BANETO_TARGET and not BANETO_IsGuidContainedInGuidGatherlist(BANETO_TARGET) and (ObjectLootable(BANETO_TARGET) or BANETO_IsUnitGatherableMob(BANETO_TARGET,objectid)  or (BANETO_IsJin() and Tinkr.GameObjectIsUsable(BANETO_TARGET,false))) and GetTime() > baneto_rtl_gatherinteract   then
                                    BANETO_LAST_GATHER_NODE = BANETO_TARGET
                                    BANETO_InteractNoDelay(BANETO_TARGET)
