                                    baneto_rtl_gatherinteract = GetTime()+2.2
                                    BANETO_GATHER_MISSING_X_COUNTER = nil
                                end
                                if UnitCastingInfo("player") and baneto_rtl_gatherinteract then
                                    if BANETO_OBJECTS_ORES[objectId] then
