                                        baneto_rtl_gatherinteract = GetTime()+2.2
                                    else
                                        BANETO_PrintBambo("gather delay add HERB")
                                        baneto_rtl_gatherinteract = GetTime()+2.2
                                    end
                                end
                                if BANETO_LUABOXUNSTUCK_JUMPCOUNT then
                                    BANETO_LUABOXUNSTUCK_JUMPCOUNT = nil
                                end
                            end
                        end
                    end
                end
            end
        end

        --[[ EXECUTE MOUNT --]]
        if BANETO_State == "MOUNT" then

            if BANETO_ForceMount and BANETO_ForceMount == true and IsMounted() then
                BANETO_ForceMount = nil
            end

            if Unlocker("EWT") then
                StopEwtMovement()
                ewtPath = nil
            elseif Unlocker("LUA") then
                BANETO_StopMovement()
            end
            local travel = 783
            if BANETO_HasMount() and not BANETO_HasBuff("player",travel) then
                local _, _, class = UnitClass("player")
                if class == 11 then
                    CancelShapeshift()

                end
            end
            BANETO_Mount()
        end

        --[[ EXECUTE GRIND --]]
        if BANETO_State == "GRIND" and BANETO_GetDefinedCenters() then
            if BANETO_ExecuteCustomGrindPulse ~= nil then
                BANETO_ExecuteCustomGrindPulse()
                if _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior and _G.BANETO_ExecuteCustomGrindPulse_SkipNormalBehavior == true then
                    return true
                end
            end

            if _G.BANETO_IS_GLYPH_PROFILE then
                local glyph = BANETO_SCAN_GLYPHS()
                if glyph then
                    local glyphId = BANETO_ObjectId(glyph)
                    BANETO_PrintState("Found glyph, moving to glyph: "..glyphId)
                    local x,y,z = BANETO_ObjectPosition(glyph)
                    if not BANETO_PlayerPosition(x,y,z,6) then
                        BANETO_MeshTo(x,y,z)
                    else
                        BANETO_PrintSuccess("We got it! Glyph: "..glyphId)
                        BANETO_DISCOVERED_GLYPHS[glyphId] = true
                    end
                    return false
                end
            end
            local spore = GetObjectWithId(203919) --407240
            if spore then
                BANETO_LAST_OVERLOAD = GetTime()+5
            end
            if BANETO_LAST_OVERLOAD and GetTime() < BANETO_LAST_OVERLOAD  then
                local eliteHerbFrozen = GetObjectWithIdIncludingBlacklistCheck(197397)
                local titanportal = GetObjectWithId(196763)
                local isSpore = false
                if spore then
                    eliteHerbFrozen = spore
                    isSpore = true
                end
                if eliteHerbFrozen and BANETO_SETTING_HERBALISM and BANETO_SETTING_HERBALISM == true then
                    local x,y,z = BANETO_ObjectPosition(eliteHerbFrozen)
                    local distance = GetDistanceBetweenObjects("player",eliteHerbFrozen)
                    if distance and distance < 250 then
                        if not isSpore then
                            UnlockedTargetUnit(eliteHerbFrozen)
                        end
                        BANETO_TARGET = eliteHerbFrozen
                        BANETO_LUABOX_TARGETSTICK = true
