                                BANETO_MeshTo(x,y,z)
                            end
                        else
                            if not isSpore then
                                BANETO_Dismount()
                                BANETO_Interact(eliteHerbFrozen)
                            end
                        end
                        BANETO_PrintState("GRIND - Overload herb: walking to/attacking!")
                        return false
                    end
                elseif titanportal  and BANETO_SETTING_MINING and BANETO_SETTING_MINING == true and not UnitCastingInfo("player") and (not BANETO_TITANPORTAL_DELAY or BANETO_TITANPORTAL_DELAY < GetTime()) and not IsUnitBlacklisted(titanportal) and ashdasuhdauisdhasudphasefdihs then
                    local x,y,z = BANETO_ObjectPosition(titanportal)
                    local distance = GetDistanceBetweenObjects("player",titanportal)
                    if distance and distance < 20 then
                        BANETO_LUABOX_TARGETSTICK = true
                        UnlockedTargetUnit(titanportal)
                        BANETO_TARGET = titanportal
                        if not BANETO_PlayerPosition(x,y,z,5) then
