                        end
                        BANETO_PrintState("GATHER - Titan touched portal: walking to/interacting!")
                        return false
                    end
                end
            end
            local myX,myY,myZ = BANETO_ObjectPosition("player")
            local activeIndex = BANETO_GetActiveCenterIndex()
            if not activeIndex then
                activeIndex = 1
            end
            local spotX,spotY,spotZ = BANETO_GetDefinedCenters()[activeIndex][1],BANETO_GetDefinedCenters()[activeIndex][2],BANETO_GetDefinedCenters()[activeIndex][3]
            if BANETO_IsDragonRiding() and IsFlying() then
                local distance = BANETO_GetDistance3D(myX,myY,1,spotX,spotY,1)
                local newIndex = activeIndex+1
                if  distance and distance < 60 then
                    if newIndex > #BANETO_GetDefinedCenters() then
                        newIndex = 1
                    end
                    waPath = nil
                    flyingPath = nil
                    BANETO_SetCurrentCenterIndex(newIndex)
