                BANETO_ClearTarget()
                --[[ print(7) --]]
            end
            if not centerIndex then
                centerIndex = BANETO_GetCenterIndexForGrinder()
            end
            if not DRUID_FORM_DELAYER_PULSE or DRUID_FORM_DELAYER_PULSE < GetTime() then
                DRUID_FORM_DELAYER_PULSE= GetTime()+15

            end

            if BANETO_TARGET then
                if not BANETO_MOBSCAN_1MINUTE_DEBUGGER then
                    BANETO_MOBSCAN_1MINUTE_DEBUGGER = GetTime() + 63
                end
                --[[ print(BANETO_MOBSCAN_1MINUTE_DEBUGGER - GetTime() .. "debug spam, dont worry") --]]
                if BANETO_MOBSCAN_1MINUTE_DEBUGGER < GetTime() then

                    BANETO_MOBSCAN_1MINUTE_DEBUGGER = nil
                end
            else
                BANETO_MOBSCAN_1MINUTE_DEBUGGER = nil
                --[[ print("no target - debugger nil") --]]
            end

            if BANETO_SETTING_RANDOMJUMPS == true and not IsFlying() and not IsFalling() and not BANETO_EXECUTE_FLY_ASCEND then
                if BANETO_RANDOMJUMP_DELAY < GetTime() and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
                    BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(15, 35)
                    if _G.BANETO_MORE_JUMPS then
                        BANETO_RANDOMJUMP_DELAY = GetTime() + math.random(2, _G.BANETO_MORE_JUMPS)
                    end
