                    elseif Unlocker("LUA") then
                        BANETO_JumpAllowed = true
                        BANETO_JumpOrAscendStart()
                    end
                end
            end
            if BANETO_TARGET then
                if BANETO_TARGET ~= Object("target") then
                    BANETO_PrintDev("[GRIND] TARGET ~= UnitGuid('target'), TARGETTING!")
                    UnlockedTargetUnit(BANETO_TARGET)
                    BANETO_PrintBambo("TARGETING: J")
                end
            end
