                --BANETO_PrintBambo("GHOST STATE " )
                if BANETO_REACHED_CORPSE_TIMER then
                    --BANETO_PrintBambo("ReachedCorpseTime.. " .. BANETO_REACHED_CORPSE_TIMER)
                end
                if BANETO_GHOSTSTOPONCE then
                    --BANETO_PrintBambo("BANETO_GHOSTSTOPONCE.. ")
                end
                if BANETO_REACHED_CORPSE then
                    BANETO_PrintBambo("BANETO_REACHED_CORPSE.. " )
                end
                if BANETO_GHOSTFUCKUP_FIX then
                    --BANETO_PrintBambo("BANETO_GHOSTFUCKUP_FIX.. " )
                end
                if BANETO_HasDebuff("player", 8326) then
                    --[[ 60 rezz no matter what --]]
                    --BANETO_Print("Spirit healer debugging - check A.")
                    if ((BANETO_SETTING_RESSSPIRITHEALER and BANETO_SETTING_RESSSPIRITHEALER == true) or BANETO_RESSSPIRIT_ONCE) and (not _G.SPIRIT_MESHTO_DEBUGGER or _G.SPIRIT_MESHTO_DEBUGGER  < 1800) then
                        --BANETO_Print("Spirit healer debugging - check B.")
                        local spirit = GetObjectWithId(6491)
                        if spirit then
                            BANETO_Print("spirit1")
                            BANETO_LUABOX_TARGETSTICK = true
                            flyingPath = nil
                            C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            local x,y,z = BANETO_ObjectPosition(spirit)
                            if BANETO_PlayerPosition(x,y,z,10) then
                                if IsFlying() then
                                    BANETO_SitStandOrDescendStart()
                                end
                            end
                            if not BANETO_PlayerPosition(x,y,z,5) then
                                BANETO_MeshTo(x,y,z)
                                local distance = GetDistanceBetweenObjects("player",spirit)
                                if not _G.SPIRIT_MESHTO_DEBUGGER then
                                    _G.SPIRIT_MESHTO_DEBUGGER = 1
                                else
                                    _G.SPIRIT_MESHTO_DEBUGGER = _G.SPIRIT_MESHTO_DEBUGGER+1
                                end
                                BANETO_Print("spirit1 MeshTo at distance: "..distance .. " with count " .._G.SPIRIT_MESHTO_DEBUGGER)
                            else
                                BANETO_StopMovement()
                                BANETO_Interact(spirit)
                                BANETO_Print("spirit1 Interact")
                                BANETO_DelayMeshPathing(5)
                                BANETO_StopMovement()
                                C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            end
                            return false
                        end
                        local spirit2 = GetObjectWithId(65183)
                        if spirit2 then
                            BANETO_Print("spirit2")
                            flyingPath = nil
                            BANETO_LUABOX_TARGETSTICK = true
                            C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            local x,y,z = BANETO_ObjectPosition(spirit2)
                            if not BANETO_PlayerPosition(x,y,z,5) then
                                BANETO_MeshTo(x,y,z)
                                local distance = GetDistanceBetweenObjects("player",spirit2)
                                if not _G.SPIRIT_MESHTO_DEBUGGER then
                                    _G.SPIRIT_MESHTO_DEBUGGER = 1
                                else
                                    _G.SPIRIT_MESHTO_DEBUGGER = _G.SPIRIT_MESHTO_DEBUGGER+1
                                end
                                BANETO_Print("spirit2 MeshTo at distance: "..distance .. " with count " .._G.SPIRIT_MESHTO_DEBUGGER)
                            else
                                BANETO_StopMovement()
                                BANETO_Interact(spirit2)
                                BANETO_Print("spirit2 Interact")
                                BANETO_DelayMeshPathing(5)
                                BANETO_StopMovement()
                                C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            end
                            return false
                        end
                        local spirit3 = GetObjectWithId(39660)
                        if not spirit3 then
                            spirit3 = GetObjectWithId(203706)
                        end
                        if spirit3 then
                            BANETO_PrintState("spirit3")
                            flyingPath = nil
                            C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            BANETO_LUABOX_TARGETSTICK = true
                            local x,y,z = BANETO_ObjectPosition(spirit3)
                            if not BANETO_PlayerPosition(x,y,z,5) then
                                BANETO_MeshTo(x,y,z)
                                local distance = GetDistanceBetweenObjects("player",spirit3)
                                if not _G.SPIRIT_MESHTO_DEBUGGER then
                                    _G.SPIRIT_MESHTO_DEBUGGER = 1
                                else
                                    _G.SPIRIT_MESHTO_DEBUGGER = _G.SPIRIT_MESHTO_DEBUGGER+1
                                end
                                BANETO_Print("spirit3 MeshTo at distance: "..distance .. " with count " .._G.SPIRIT_MESHTO_DEBUGGER)
                            else
                                BANETO_StopMovement()
                                BANETO_Interact(spirit3)
                                BANETO_Print("spirit3 Interact")
                                BANETO_DelayMeshPathing(5)
                                BANETO_StopMovement()
                                C_PlayerInteractionManager.ConfirmationInteraction(Enum.PlayerInteractionType.SpiritHealer)
                            end
                            return false
                        end
                    elseif (BANETO_SETTING_RESSSPIRITHEALER and BANETO_SETTING_RESSSPIRITHEALER == true) or BANETO_RESSSPIRIT_ONCE then
                        --BANETO_Print("Spirit healer debugging - check C.")
                        BANETO_PrintWarning("Spirit ress failed, pausing now, continuing in 2 seconds")
                        _G.SPIRIT_MESHTO_DEBUGGER = nil
                        BANETO_Stop()
                        C_Timer.After(2,BANETO_Start)
                    end
                    --BANETO_Print("Spirit healer debugging - check D.")
                    if BANETO_REACHED_CORPSE then
                        if not BANETO_REACHED_CORPSE_TIMER then
                            BANETO_REACHED_CORPSE_TIMER = GetTime() + 60
                        end
                        local x, y, z = BANETO_GetPlayerCorpsePosition()
                        if BANETO_REACHED_CORPSE_TIMER < GetTime() then
                            if not BANETO_PlayerPosition(x, y, z, 15) then
                                BANETO_MeshTo(x, y, z)
                            else
                                BANETO_REACHED_CORPSE_TIMER = nil
                                if StaticPopup1Button1:IsVisible() then
                                    StaticPopup1Button1:Click()
                                end
                            end
                        end
                    end

                    if not BANETO_GHOSTSTOPONCE and not BANETO_REACHED_CORPSE then
                        if not BANETO_GHOSTSTOPONCE_DELAY then
                            BANETO_GHOSTSTOPONCE_DELAY= GetTime()+0.5
                        elseif BANETO_GHOSTSTOPONCE_DELAY < GetTime() then
                            if Unlocker("LUA") then
                             BANETO_StopMovement()
                            elseif Unlocker("EWT") then
                                StopEwtMovement()
                            end
                            if BANETO_FLYING_GHOST and BANETO_FLYING_GHOST == true and (not BANETO_SETTING_RESSSPIRITHEALER or BANETO_SETTING_RESSSPIRITHEALER == false) then
                                BANETO_JumpOrAscendStart()
                            end
                            BANETO_GHOSTSTOPONCE_DELAY = nil
                            BANETO_GHOSTSTOPONCE = true
                        end
                    end

                    local xUn, yUn, zUn = BANETO_GetPlayerCorpsePosition()
                    local x, y, z = BANETO_GetClosestPointOnMesh(xUn, yUn, zUn)
                    if not BANETO_PlayerPosition(x, y, z, 40) and not BANETO_REACHED_CORPSE and BANETO_GHOSTSTOPONCE then
                        BANETO_MeshTo(x, y, z)
                    elseif not  BANETO_PlayerPosition(x, y, z, 40) and BANETO_REACHED_CORPSE and BANETO_GHOSTSTOPONCE then
                        BANETO_REACHED_CORPSE = nil
                        BANETO_PrintState("Reseting ghost cycle. Distance to body is increasing.")
                        BANETO_StopMovement()
                        ewtPath = nil
                        waPath = nil
                    elseif (BANETO_PlayerPosition(x, y, z, 40) and not IsFlying() and not BANETO_SETTING_RESSNEARCORPSE) or BANETO_REACHED_CORPSE == true or (BANETO_PlayerPosition(x, y, z, 7) and (BANETO_SETTING_RESSNEARCORPSE == true or IsFlying())) then
                        if not BANETO_REACHED_CORPSE then
                            BANETO_REACHED_CORPSE = true
                            BANETO_GHOSTSTOPONCE = nil
                            if (not BANETO_SETTING_RESSNEARCORPSE or BANETO_SETTING_RESSNEARCORPSE == false) and BANETO_GHOSTFUCKUP_FIX  then
                                BANETO_PrintState("Finding secure ressurection spot...")
                            else
                                BANETO_PrintState("Resurrecting near corpse...")
                            end
                            BANETO_StopMovement()
                            ewtPath = nil
                            waPath = nil
                            flyingPath = nil
                        end
                        if StaticPopup1:IsVisible() and (BANETO_IsReviveSecure() or (BANETO_REACHED_CORPSE_TIMER and BANETO_REACHED_CORPSE_TIMER < GetTime())) then
                            if StaticPopup1Button1:IsVisible() then
                                StaticPopup1Button1:Click()
                            end
                        end

                        local corpseX, corpseY, corpseZ = BANETO_GetPlayerCorpsePosition()
                        if not tryX then
                            tryX, tryY, tryZ = BANETO_GetRandomPointInCircleNEW(corpseX, corpseY, corpseZ, 40)
                        end
                        if tryX and not BANETO_PlayerPosition(tryX, tryY, tryZ, 4) and (not BANETO_SETTING_RESSNEARCORPSE or BANETO_SETTING_RESSNEARCORPSE == false) and BANETO_GHOSTFUCKUP_FIX and not BANETO_IsReviveSecure() then
                            BANETO_MeshTo(tryX, tryY, tryZ)
                            BANETO_PrintDev("GhostStep1")
                        elseif tryX and BANETO_PlayerPosition(tryX, tryY, tryZ, 4) then
                            BANETO_PrintDev("GhostStep2")
                            BANETO_StopMovement()
                            tryX = nil
                        else
                            BANETO_PrintDev("GhostStep3")
                            BANETO_StopMovement()
                        end

                    end
                end
            end
        end

        if BANETO_State == "REGEN" then
            if IsFlying() then
                BANETO_SitStandOrDescendStart()
                BANETO_ISDESCEND_REGEN = true
                return false
            elseif BANETO_ISDESCEND_REGEN then
                BANETO_DescendStop()
                BANETO_ISDESCEND_REGEN = nil
            end
            if IsMounted() then
                BANETO_Dismount()
                return false
            end
            --[[ DETECT HEAL PET HUNTER --]]
            local heal_pet = 136
            local _,_,class = UnitClass("player")
            if UnitExists("pet") and class == 3 and BANETO_UnitHealth("pet") <= 75 and BANETO_IsSpellUsable(heal_pet) and GetDistanceBetweenObjects("player", "pet") < 20 and not UnitAffectingCombat("player") and not BANETO_IsEating() and not BANETO_IsDrinking() and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                BANETO_CastSpell(heal_pet)
                return false
            end


            if (BANETO_IsEating() or BANETO_IsDrinking()) and (not BANETO_RETAIL_ROGUEREGENSTEALTH or BANETO_RETAIL_ROGUEREGENSTEALTH < GetTime()) then
                if not BANETO_HasBuff("player",20580) and not BANETO_HasBuff("player",8874) and not BANETO_HasBuff("player",1784) then
                    if BANETO_IsSpellUsable(20580) and not BANETO_IsSpellKnown(1784) then
                        BANETO_CastSpell(20580, true)
                        BANETO_RETAIL_ROGUEREGENSTEALTH = GetTime()+11
                    elseif BANETO_IsSpellUsable(1784) and BANETO_SETTING_ROGUE_STEALTHREGEN and BANETO_SETTING_ROGUE_STEALTHREGEN == true then
                        BANETO_CastSpell(1784, true)
                        BANETO_RETAIL_ROGUEREGENSTEALTH = GetTime()+11
                    end
                end
            end



            --[[ HUNTER --]]
            local _, _, class = UnitClass("player")
            if class == 3 then
                local summon_pet = 883
                if not UnitExists("pet") and BANETO_IsSpellUsable(summon_pet) and not BANETO_HUNTER_SPAMBLOCK_NOPET and not UnitChannelInfo("player") and not UnitCastingInfo("player") and not BANETO_IsDrinking() and not BANETO_IsEating() then
                    if not BANETO_HUNTER_SUMMONPET_DELAY or BANETO_HUNTER_SUMMONPET_DELAY < GetTime() then
                        BANETO_CastSpell(summon_pet, true)
                        BANETO_HUNTER_SUMMONPET_DELAY = GetTime() + 11.5
                    end
                end
            end

            --[[  GO INTO FIGHT IF ATTACKED / LEAVE REGEN STATE --]]
            if UnitAffectingCombat("player") then
                if BANETO_STATE_ENTER_DISENCHANT_DELAY then
                    BANETO_STATE_ENTER_DISENCHANT_DELAY = nil
                end

                if BANETO_ISBANDAGING then
                    BANETO_ISBANDAGING = nil
                end

                if BANETO_SETTING_REPAIR_IGNOREFIGHTS == false then
                    if BANETO_State ~= "FIGHTING" then
                        BANETO_State = "FIGHTING"
                        if Unlocker("EWT") then
                            StopEwtMovement()
                        end
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    end
                elseif (BANETO_SETTING_REPAIR_IGNOREFIGHTS == true and BANETO_IsRepairNeeded()) then
                    if BANETO_State ~= "REPAIR" then
                        BANETO_State = "REPAIR"
                        if Unlocker("EWT") then
                            StopEwtMovement()
                        end
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    end
                elseif (BANETO_SETTING_REPAIR_IGNOREFIGHTS == true and not BANETO_IsRepairNeeded()) then
                    if BANETO_State ~= "FIGHTING" then
                        BANETO_State = "FIGHTING"
                        if Unlocker("EWT") then
                            StopEwtMovement()
                        end
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    end
                end
            end

            local currentSpeed, runSpeed, flightSpeed, swimSpeed = GetUnitSpeed("player")
            if currentSpeed > 0 then
                BANETO_DelayStateTick(0.5)
                waPath = nil
                flyingPath = nil
                BANETO_StopMovement()
                return false
            end


            --[[ BANDAGE --]]
            if BANETO_SETTING_BANDAGES == true and BANETO_HasBandageInInventory() and BANETO_UnitHealth("player") < BANETO_SETTING_REGEN_HEALTH and not BANETO_HasDebuff("player", 11196) then
                BANETO_UseBandage()
                if not BANETO_ISBANDAGING then
                    BANETO_ISBANDAGING = true
                end
            end

            --[[ DETECT BANDAGE WAS USED --]]
            if BANETO_ISBANDAGING and BANETO_HasDebuff("player", 11196) then
                BANETO_ISBANDAGING = nil
            end

            local consumeShadows =  17767
            if UnitExists("pet") and BANETO_UnitHealth("pet") <= 70 and BANETO_IsSpellUsable(consumeShadows) and GetDistanceBetweenObjects("player", "pet") < 20 and not UnitAffectingCombat("player") and not BANETO_IsEating() and not BANETO_IsDrinking() and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                BANETO_CastSpell(consumeShadows)
            end



            --[[ HEAL CLASSES WITHOUT FOOD But full mana --]]
            local chosenFood = BANETO_FindFoodInBags()
            if (not chosenFood or BANETO_SETTING_REGEN_USEFOOD == false) and not BANETO_IsEating() and not BANETO_IsDrinking() then
                if BANETO_UnitMana("player") > BANETO_SETTING_REGEN_MANA and BANETO_UnitHealth("player") < BANETO_SETTING_REGEN_HEALTH then
                    local _, _, class = UnitClass("player")
                    if class == 11 then
                        if class == 11 then
                            CancelShapeshift()
                        end
                        local regrowth = 8936
                        local rejuv = 2091
                        if BANETO_IsSpellUsable(regrowth) and BANETO_GetUnitSpeed("player") == 0 and not BANETO_HasBuff("player", regrowth) and (not BANETO_HEALINGREGENSTATE_DRUID_DELAY or BANETO_HEALINGREGENSTATE_DRUID_DELAY <= GetTime()) then
                            BANETO_CastSpell(regrowth, true)
                            BANETO_HEALINGREGENSTATE_DRUID_DELAY = GetTime() + 1
                        end
                    elseif class == 5 then
                        local priestHot = 139
                        local priestHeal = 2061
                        if BANETO_IsSpellUsable(priestHeal) and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
                            if not BANETO_PRIEST_REGEN_HEALDELAY or BANETO_PRIEST_REGEN_HEALDELAY < GetTime() then
                                BANETO_PRIEST_REGEN_HEALDELAY = GetTime()+2.5
                                BANETO_CastSpell(priestHeal, true)
                            end
                        end
                    elseif class == 10 then
                        local vivify = 116670
                        if BANETO_IsSpellUsable(vivify) and UnitLevel("player") >= 4 then
                            BANETO_CastSpell(vivify, true)
                        end
                    elseif class == 2 then
                        local flashOfLight = 19750
                        if BANETO_IsSpellUsable(flashOfLight) and UnitLevel("player") >= 4 then
                            BANETO_CastSpell(flashOfLight, true)
                        end
                    elseif class == 7 then
                        local shamanHeilendeWoge = 8004
                        if BANETO_IsSpellUsable(shamanHeilendeWoge) and UnitLevel("player") >= 4 then
                            BANETO_CastSpell(shamanHeilendeWoge, true)
                        end
                    end
                end
            end

            if not BANETO_IsEating() and not BANETO_IsWellFed() and BANETO_UnitHealth("player") < BANETO_SETTING_REGEN_HEALTH and BANETO_SETTING_REGEN_USEBUFFFOOD == true and not UnitChannelInfo("player") and not BANETO_ISBANDAGING and not UnitCastingInfo("player") and not IsSwimming() then
                local chosenFoodBuff = BANETO_FindBuffFoodInBags()
                if chosenFoodBuff then
                    local _, _, class = UnitClass("player")
                    if class == 11 or class == 7 then
                        CancelShapeshift()
                    end
                    local id = chosenFoodBuff
                    BANETO_PrintState("Eating buff food: "..id)
                    BANETO_USEITEM_DELAYER = nil
                    BANETO_UseItem(id,true)
                    BANETO_EATINGDRINKING_RETAIL_DELAY = GetTime()+BANETO_EATINGDRINKING_RETAIL_DELAY_AMOUNT
                    BANETO_USED_FOOD_ITEM_TO_REGEN = true
                    return
                end
            end

            if not BANETO_IsEating()  and BANETO_GetUnitSpeed("player") == 0 and BANETO_UnitHealth("player") < BANETO_SETTING_REGEN_HEALTH and BANETO_SETTING_REGEN_USEFOOD == true and not UnitChannelInfo("player") and not BANETO_ISBANDAGING and not UnitCastingInfo("player") and not IsSwimming() and (not BANETO_EATINGDRINKING_RETAIL_DELAY or BANETO_EATINGDRINKING_RETAIL_DELAY < GetTime()) then
                if chosenFood then
                    local _, _, class = UnitClass("player")
                    if class == 11 or class == 7 then
                        CancelShapeshift()
                    end
                    local id = chosenFood
                    BANETO_PrintState("Eating: "..id)
                    BANETO_USEITEM_DELAYER = nil
                    BANETO_UseItem(id,true)
                    BANETO_EATINGDRINKING_RETAIL_DELAY = GetTime()+BANETO_EATINGDRINKING_RETAIL_DELAY_AMOUNT
                    BANETO_USED_FOOD_ITEM_TO_REGEN = true
                    return
                end
            end
            if not BANETO_IsDrinking() and BANETO_GetUnitSpeed("player") == 0 and BANETO_UnitMana("player") < BANETO_SETTING_REGEN_MANA and BANETO_SETTING_REGEN_USEDRINK == true and not UnitChannelInfo("player") and not BANETO_ISBANDAGING and not UnitCastingInfo("player") and not IsSwimming() and (not BANETO_EATINGDRINKING_RETAIL_DELAY or BANETO_EATINGDRINKING_RETAIL_DELAY < GetTime()) then
                local chosenDrink = BANETO_FindDrinkInBags()
                if chosenDrink then
                    local _, _, class = UnitClass("player")
                    if class == 11 or class == 7 then
                        CancelShapeshift()
                    end
                    local id = chosenDrink
                    BANETO_PrintState("Drinking: "..id)
                    BANETO_USEITEM_DELAYER = nil
                    BANETO_UseItem(id,true)
                    BANETO_EATINGDRINKING_RETAIL_DELAY = GetTime()+21
                    BANETO_USED_DRINK_ITEM_TO_REGEN = true
                    return
                end
            end
        end

        if BANETO_State == "REPAIR" then
            if BANETO_IsInFollowerDungeon() then
                BANETO_PrintState("We are in REPAIR state: leaving follower dungeon first.")
                LFGTeleport(true)
                return
            end
            if BANETO_DRAGONRIDING_FIX_FOR_SELL_AND_REPAIR_DISMOUNT and BANETO_DRAGONRIDING_FIX_FOR_SELL_AND_REPAIR_DISMOUNT < GetTime() then
                BANETO_DRAGONRIDING_FIX_FOR_SELL_AND_REPAIR_DISMOUNT = GetTime()+600
                BANETO_Dismount()
                BANETO_MoveBackwardStart()
                C_Timer.After(1,BANETO_MoveBackwardStart)
                _G.BANETO_MOVEMENTSTOPDELAYTIME = GetTime()+10
                BANETO_PrintWarning("REPAIR STATE FOR OVER 10 mins -> DISMOUNTING ONCE")
                return
            end
            local x, y, z, id = BANETO_GetDefinedVendor("REPAIR")[1][1], BANETO_GetDefinedVendor("REPAIR")[1][2], BANETO_GetDefinedVendor("REPAIR")[1][3], BANETO_GetDefinedVendor("REPAIR")[1][4]
            if x and y and z and id and (not baneto_vendor_infodelay or baneto_vendor_infodelay < GetTime()) then
                BANETO_PrintState("VENDOR INFO - ".. BANETO_State .. " X: " .. x  .. " Y: " .. y  .. " Z: " .. z .. " ID: " .. id )
                baneto_vendor_infodelay=GetTime()+60
            end
            local objectForPathing = GetObjectWithId(id)
            if objectForPathing then
                x, y, z = BANETO_ObjectPosition(objectForPathing)
            end
            if BANETO_SETTING_MAMMOTH and BANETO_SETTING_MAMMOTH == true and not IsIndoors() and not UnitAffectingCombat("player") then
                if GetShapeshiftDruid() ~= 0 and not UnitCastingInfo("player") and not IsMounted() then
                    CancelShapeshift()
                end
                flyingPath = nil
                BANETO_GroundPathDeleter()
                BANETO_EXECUTE_FLY_ASCEND = nil
                if IsMounted() and (not BANETO_HasBuff("player",61425) and not BANETO_HasBuff("player",264058) and not BANETO_HasBuff("player",61425)  and not BANETO_HasBuff("player",122708)) then
                    BANETO_Dismount()
                end
                if not IsMounted() then
                    BANETO_CheckMammothSpammer()
                    if Unlocker("LUA") then
                        BANETO_StopMovement()
                    elseif Unlocker("EWT") then
                        StopEwtMovement()
                    end
                end
                if not IsMounted() and (not BANETO_RETAIL_MAMMOTH_DELAY or BANETO_RETAIL_MAMMOTH_DELAY < GetTime()) and not MOUNTMAMMOTHTRY  then
                    BANETO_CastSpell(61424)
                    MOUNTMAMMOTHTRY = 1
                    BANETO_RETAIL_MAMMOTH_DELAY = GetTime()+3
                    BANETO_RETAIL_MAMMOTH_COUNTER = BANETO_RETAIL_MAMMOTH_COUNTER+1
                elseif not IsMounted() and (not BANETO_RETAIL_MAMMOTH_DELAY or BANETO_RETAIL_MAMMOTH_DELAY < GetTime()) and MOUNTMAMMOTHTRY and MOUNTMAMMOTHTRY == 1  then
                    BANETO_CastSpell(122708)
                    BANETO_RETAIL_MAMMOTH_DELAY = GetTime()+3
                    BANETO_RETAIL_MAMMOTH_COUNTER = BANETO_RETAIL_MAMMOTH_COUNTER+1
                    MOUNTMAMMOTHTRY = 2
                elseif not IsMounted() and (not BANETO_RETAIL_MAMMOTH_DELAY or BANETO_RETAIL_MAMMOTH_DELAY < GetTime()) and MOUNTMAMMOTHTRY and MOUNTMAMMOTHTRY == 2 then
                    BANETO_CastSpell(264058)
                    BANETO_RETAIL_MAMMOTH_DELAY = GetTime()+3
