                end
                 if not BANETO_Shuffle_DoWeHaveAllItems() and not BANETO_SHFL_CRAFTINGMODE then
                    if not BANETO_Shuffle_CheckedGbank then
                        local x,y,z,id = BANETO_AHSHUFFLE_GUILDBANK[1],BANETO_AHSHUFFLE_GUILDBANK[2],BANETO_AHSHUFFLE_GUILDBANK[3],BANETO_AHSHUFFLE_GUILDBANK[4]
                        if not BANETO_PlayerPosition(x,y,z,2.5) then
