                                        elseif BANETO_Shuffle_NextStepDelay and BANETO_Shuffle_NextStepDelay < GetTime() then
                                            BANETO_Shuffle_NextStepDelay = nil
                                            BANETO_Shuffle_CheckedAh = true
                                        end
                                    end
                                end
                            else
