        end

        if BANETO_State == "UNSTUCK-AUTO" then
            if BANETO_TAXI_NEEDED or BANETO_TAXIFLIGHT_BEGAN then
                BANETO_TAXIFLIGHT_BEGAN = nil
                BANETO_TAXI_NEEDED = nil
            end
            if not BANETO_AUTOUNSTUCKCIRCLE_X then
                if Unlocker("LUA") then
                    local x, y, z = BANETO_ObjectPosition("player")
                    local x2, y2, z2 = BANETO_GetRandomPointOnCircleNEW(x, y, z, 12)
                    BANETO_AUTOUNSTUCKCIRCLE_X, BANETO_AUTOUNSTUCKCIRCLE_Y, BANETO_AUTOUNSTUCKCIRCLE_Z = BANETO_GetClosestPointOnMesh(x2, y2, z2)
                    BANETO_StopMovement()
                elseif Unlocker("EWT") then
                end
            else
                if not BANETO_PlayerPosition(BANETO_AUTOUNSTUCKCIRCLE_X, BANETO_AUTOUNSTUCKCIRCLE_Y, BANETO_AUTOUNSTUCKCIRCLE_Z, 3) then
                    BANETO_MeshTo(BANETO_AUTOUNSTUCKCIRCLE_X, BANETO_AUTOUNSTUCKCIRCLE_Y, BANETO_AUTOUNSTUCKCIRCLE_Z)
                else
                    if Unlocker("LUA") then
                        BANETO_StopMovement()
                        BANETO_LUABOXUNSTUCK_JUMPCOUNT = nil
                    elseif Unlocker("EWT") then
                        StopEwtMovement()
                    end
                    BANETO_AUTOUNSTUCKCIRCLE_X, BANETO_AUTOUNSTUCKCIRCLE_Y, BANETO_AUTOUNSTUCKCIRCLE_Z = nil, nil, nil
                    if BANETO_DEFINED_PROFILE_TYPE == "Grinding" then
                        BANETO_State = "GRIND"
                        BANETO_TARGET = nil
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    elseif BANETO_DEFINED_PROFILE_TYPE == "Battleground" then
                        BANETO_State = "BG-MASTER"
                        BANETO_TARGET = nil
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    elseif BANETO_DEFINED_PROFILE_TYPE == "Traveling" then
                        BANETO_State = "TRAVEL"
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    elseif BANETO_DEFINED_PROFILE_TYPE == "Questing" then
                        BANETO_State = "QUEST-MASTER"
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    elseif BANETO_DEFINED_PROFILE_TYPE == "BRD" then
                        BANETO_State = "BRD-MASTER"
                        BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                    end
                    if BANETO_DEFINED_PROFILE_TYPE == "Fishing" then
                        if BANETO_PROFILE_NAME == "Skill-Fishing" then
                            BANETO_State = "FISHING-SKILL"
                            BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                        else
                            BANETO_State = "FISHING-SPOT"
                            BANETO_MAINTEXTS_STATE:SetText("|cffC6C5C3State: |cff0872B2" .. BANETO_State)
                        end
                    end
                end
            end
        end
        if BANETO_State ~= "FISHING-SPOT" and (BANETO_ANGLE_WAIT_TIME or CURRENTSWARM_TIMER) then
            BANETO_ANGLE_WAIT_TIME = nil
            CURRENTSWARM_TIMER = nil
        end
        if BANETO_State == "FISHING-SPOT" then
            --BANETO_PrintBambo("fishing spot: state")
            if not UnitCastingInfo("player") and BANETO_HasItemToOpen() and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                BANETO_AutoOpenItems()
                BANETO_PrintState("Auto opening items in FISHING-SPOT state.")
                return false
            end
            local name, text, texture, startTimeMS, endTimeMS, isTradeSkill, notInterruptible, spellId = UnitChannelInfo("player")
            if spellId and spellId == 392270 then
                BANETO_SpellStopCasting()
                BANETO_PrintState("Looking for lunkers, but we do not want that. Cancel.")
                return false
            end
            if BANETO_SETTING_SWARMFISHING and BANETO_SETTING_SWARMFISHING == true and (not BANETO_SWARM_BREAK or BANETO_SWARM_BREAK < GetTime()) then
                if not BANETO_TARGET then
                    BANETO_PrintBambo("Find new swarm")
                    swarmPosition = nil
                    BANETO_TARGET,swarmPosition = BANETO_SCAN_FISHINGSWARMS()
                else
                    BANETO_PrintBambo("Check current swarm")
                    local xSwarmCheck,ySwarmCheck,zSwarmCheck = BANETO_ObjectPosition(BANETO_TARGET)
                    if not xSwarmCheck or not ySwarmCheck or not zSwarmCheck or not swarmPosition or not BANETO_ObjectExists(BANETO_TARGET) then
                        BANETO_TARGET = nil
                        BANETO_PrintState("Setting swarm to nil.")
                    end
                end
                if BANETO_TARGET then
                    if BANETO_CheckNinjaSwarm() then
                        BANETO_AddMobToGuidBlacklist(BANETO_TARGET,"SwarmNinja")
                        BANETO_TARGET = nil
                        CURRENTSWARM_TIMER = nil
                        BANETO_PrintState("Blacklisting current fishing swarm, ninja swarm!")
                    end
                end
                if not CURRENTSWARM_TIMER then
                    CURRENTSWARM_TIMER = GetTime()+150
                end
                if BANETO_TARGET and CURRENTSWARM_TIMER and CURRENTSWARM_TIMER < GetTime() and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                    BANETO_AddMobToGuidBlacklist(BANETO_TARGET)
                    BANETO_TARGET = nil
                    CURRENTSWARM_TIMER = nil
                    BANETO_PrintState("Blacklisting current fishing swarm, 150 seconds elapsed!")
                    return false
                end
                local centers = BANETO_GetDefinedCenters()
                local playerX,playerY,playerZ = BANETO_ObjectPosition("player")
                if BANETO_TARGET and swarmPosition and not IsSwimming() and not IsFalling() and not UnitAffectingCombat("player") then
                    local x,y,z = swarmPosition[1],swarmPosition[2],swarmPosition[3]
                    local xSwarm,ySwarm,zSwarm = BANETO_ObjectPosition(BANETO_TARGET)
                    local xBobber,yBobber,zBobber = BANETO_GetBobberPosition()
                    if xBobber and yBobber and zBobber and xSwarm and ySwarm then
                        local distanceBobberToSwarm = BANETO_GetDistance3D(xBobber,yBobber,zBobber,xSwarm,ySwarm,zSwarm)
                        local d = GetDistanceBetweenObjects("player",BANETO_TARGET)
                        if d and d < 60 and distanceBobberToSwarm and distanceBobberToSwarm ~= 0 and distanceBobberToSwarm > 4.5 and (UnitCastingInfo("player") or UnitChannelInfo("player")) then
                            BANETO_PrintState("Interrupting fishing cast, bobber is not within range of fishing pool!")
                            BANETO_SpellStopCasting()
                        end
                    end
                    local distanceSwarm = BANETO_GetDistance3D(xSwarm,ySwarm,zSwarm,playerX,playerY,playerZ)
                    --BANETO_PrintBambo("Distance to swarm: "..distanceSwarm)
                    if distanceSwarm and distanceSwarm <= 16 and distanceSwarm >= 10 and not IsSwimming() and not IsFlying() and not IsFalling() then
                        BANETO_FISH_SPOT_X, BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z = playerX,playerY,playerZ
                    else
                        BANETO_FISH_SPOT_X, BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z = x,y,z
                    end
                elseif centers and 0 < #centers then
                    --BANETO_PrintBambo("swarm fishing: movement")
                    if not swarmFishingIndex then
                        swarmFishingIndex = BANETO_GetCenterIndexForGrinder()
                    end
                    CURRENTSWARM_TIMER = nil
                    local x, y, z = centers[swarmFishingIndex][1], centers[swarmFishingIndex][2], centers[swarmFishingIndex][3]
                    if (not BANETO_PlayerPosition(x,y,z,_G.BANETO_RADIUS_GRIND_SPOTS_TRIGGER) and not IsFlying()) or (not BANETO_PlayerPosition(x,y,playerZ,_G.BANETO_RADIUS_GRIND_SPOTS_TRIGGER_FLYING) and IsFlying()) then
                        BANETO_MeshTo(x,y,z)
                    else
                        swarmFishingIndex=swarmFishingIndex+1
                        if #centers < swarmFishingIndex then
                            swarmFishingIndex = 1
                        end
                        waPath = nil
                        flyingPath = nil
                    end
                    return false
                else
                    CURRENTSWARM_TIMER = nil
                    BANETO_PrintWarning("No fishing swarm found, and no profile spots to move to! Maybe you should disable swarm fishing in GATHERING settings?")
                    return false
                end
            else
                if not ANTI_AFK_FISHING then
                    ANTI_AFK_FISHING = true
                    BANETO_PrintState("Started fishing anti-afk!")
                    local randomSeconds = math.random(3,6)
                    C_Timer.NewTicker(randomSeconds,function()
                        if BANETO_GetState() == "FISHING-SPOT" and UnitIsAFK("player") and BANETO_SETTING_SWARMFISHING == false and not UnitCastingInfo("player") and BANETO_GetUnitSpeed("player") == 0 then
                            BANETO_TurnLeftStart()
                            BANETO_TurnLeftStop()
                            BANETO_DelayStateTick(1)
                            BANETO_UpdateServerFacing()
                            BANETO_UpdateLastHardware()
                            C_Timer.After(0.1,BANETO_TurnLeftStart)
                            C_Timer.After(0.11,BANETO_TurnLeftStop)
                            C_Timer.After(0.15,BANETO_StopMovement)
                            C_Timer.After(0.2,function()
                                BANETO_SetPlayerAnglesLuabox(BANETO_FISH_SPOT_ANGLE)
                            end)
                        end
                    end)
                end
            end
            if BANETO_SETTING_ICEFISHING and BANETO_SETTING_ICEFISHING == true then
                BANETO_IceFishingState()
                return false
            end
            --BANETO_PrintBambo("fishing spot: set angle and fish spot")
            if not BANETO_FISH_SPOT_X and not BANETO_FISH_SPOT_ANGLE and BANETO_SETTING_SWARMFISHING == false then
                if Unlocker("LUA") then
                    BANETO_FISH_SPOT_X,BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z = BANETO_ObjectPosition("player")
                    BANETO_FISH_SPOT_ANGLE = BANETO_GetObjectFacing("player")
                    BANETO_FISH_ANGLE_DELAY = nil
                end
            end
            local distanceCheck = 3
            if BANETO_SETTING_SWARMFISHING and BANETO_SETTING_SWARMFISHING == true then
                distanceCheck = 4
            end
            if BANETO_ANGLE_WAIT_TIME and not BANETO_PlayerPosition(BANETO_FISH_SPOT_X,BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z,distanceCheck) then
                BANETO_ANGLE_WAIT_TIME = nil
                BANETO_FISH_ANGLE_DELAY = nil
            end
            if BANETO_FISH_SPOT_X and BANETO_FISH_SPOT_Y and BANETO_FISH_SPOT_Z and BANETO_PlayerPosition(BANETO_FISH_SPOT_X,BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z,distanceCheck) then
                --BANETO_PrintBambo("fishing spot: ready")
                if GetShapeshiftDruid() ~= 0 then
                    CancelShapeshift()
                    waPath = nil
                    flyingPath = nil
                    BANETO_StopMovement()
                    BANETO_DelayStateTick(0.5)
                end
                if IsMounted() and (not BANETO_FISH_SPOT_DISMOUNT_DELAY or BANETO_FISH_SPOT_DISMOUNT_DELAY < GetTime()) then
                    BANETO_FISH_SPOT_DISMOUNT_DELAY = GetTime()+5
                    BANETO_Dismount("47")
                    waPath = nil
                    flyingPath = nil
                    BANETO_StopMovement()
                    BANETO_DelayStateTick(0.5)
                    return false
                end
                if not BANETO_ANGLE_WAIT_TIME then
                    BANETO_ANGLE_WAIT_TIME = GetTime()+3
                    if BANETO_SETTING_SMOOTHTURN and BANETO_SETTING_SMOOTHTURN == true then
                        BANETO_ANGLE_WAIT_TIME = GetTime()+4
                    end
                end
                if BANETO_SETTING_SWARMFISHING and BANETO_SETTING_SWARMFISHING == true and BANETO_TARGET  then
                    local x,y,z = BANETO_ObjectPosition(BANETO_TARGET)
                    local angle = BANETO_GetFacingValue(x,y,z)
                    BANETO_SetPlayerAnglesLuabox(angle)
                    BANETO_FISH_SPOT_ANGLE = angle
                end
                if not BANETO_FISH_ANGLE_DELAY or BANETO_FISH_ANGLE_DELAY < GetTime() then
                    BANETO_FISH_ANGLE_DELAY = GetTime()+1
                    if  BANETO_FISH_SPOT_ANGLE then
                        BANETO_SetPlayerAnglesLuabox(BANETO_FISH_SPOT_ANGLE)
                    end
                end

                BANETO_DfLures()

                local chumBuff = 377850
                local scalebelly = 194730
                if (not BANETO_HasBuff("player",chumBuff) or doubleChum) and BANETO_SETTING_FISHBAITS and BANETO_SETTING_FISHBAITS == true and BANETO_SETTING_SWARMFISHING == false and GetItemCount(scalebelly) >= 1 and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                    local itemcooldown = GetItemCooldown(scalebelly)
                    BANETO_PrintState("Scalebelly baits: checks!")
                    if itemcooldown == 0 and (not scalebellydelay or scalebellydelay < GetTime()) and BANETO_ANGLE_WAIT_TIME and BANETO_ANGLE_WAIT_TIME < GetTime() then
                        BANETO_PrintState("Scalebelly baits ready!")
                        BANETO_UseItem(scalebelly)
                        scalebellydelay = GetTime()+4
                        BANETO_ANGLE_WAIT_TIME = GetTime()+4.5
                        if not doubleChum then
                            doubleChum = 9
                        elseif doubleChum and doubleChum > 1 then
                            doubleChum = doubleChum-1
                        elseif doubleChum and doubleChum == 1 then
                            doubleChum = nil
                            BANETO_ANGLE_WAIT_TIME = GetTime()+2
                        end
                    else
                        BANETO_PrintState("Scalebelly baits on cooldown...")
                    end
                end
                --BANETO_PrintBambo("fishing spot: scalebellys done")
                if not BANETO_BOBBER_RDY and BANETO_IsSpellUsable(7620) and not BANETO_GetBobberState() and not UnitCastingInfo("player") and not UnitChannelInfo("player") and not LootFrame:IsVisible() then
                    if BANETO_ANGLE_WAIT_TIME < GetTime() then
                        if BANETO_SETTING_SWARMBREAKS and BANETO_SETTING_SWARMBREAKS == true and BANETO_SETTING_SWARMFISHING and BANETO_SETTING_SWARMFISHING == true then
                            if not BANETO_NEXT_SWARM_BREAK or BANETO_NEXT_SWARM_BREAK < GetTime() then
                                BANETO_NEXT_SWARM_BREAK = GetTime()+900
                                BANETO_SWARM_BREAK = GetTime()+240
                                BANETO_PrintState("4 Minute swarm break starting... You can disable this setting in GATHERING settings!")
                            end
                        end
                        if IsSwimming() and BANETO_SETTING_SWARMFISHING and BANETO_SETTING_SWARMFISHING == true and swarmPosition then
                            if not SWARMFISHING_TRIES_IN_WATER then
                                SWARMFISHING_TRIES_IN_WATER = 1
                            else
                                SWARMFISHING_TRIES_IN_WATER = SWARMFISHING_TRIES_IN_WATER + 1
                            end
                            if SWARMFISHING_TRIES_IN_WATER and 4 < SWARMFISHING_TRIES_IN_WATER then
                                BANETO_BlacklistSwarmLanding()
                                BANETO_PrintWarning("We are in water, trying to reach land before fishing swarm.")
                                SWARMFISHING_TRIES_IN_WATER = nil
                            end
                        end
                        BANETO_CastSpell(7620, true)
                        BANETO_FISH_THISTIME_FAIL = nil
                        BANETO_BOBBER_RDY = nil
                        BANETO_BOBBER_INTERACT_DELAY = nil
                        local numRanFish = math.random(1,5)
                        BANETO_FISH_START_TIME = GetTime()+24+numRanFish
                    end
                elseif BANETO_BOBBER_RDY or  ((BANETO_GetBobberState() and BANETO_GetBobberState() == true) or (BANETO_FISH_START_TIME and BANETO_FISH_START_TIME < GetTime())) and not LootFrame:IsVisible() then
                    if not BANETO_BOBBER_INTERACT_DELAY then
                        BANETO_BOBBER_INTERACT_DELAY = GetTime() + 0.5
                        local randomNum = math.random(1,150)
                        if _internal.Software() == "nn" and not BANETO_BOBBER_RDY then
                            BANETO_BOBBER_RDY = true
                        end
                        if randomNum and randomNum == 137 then
                            BANETO_FISH_THISTIME_FAIL = true
                        end
                    end
                    if BANETO_BOBBER_INTERACT_DELAY < GetTime() and not BANETO_FISH_THISTIME_FAIL then
                        BANETO_InteractWithBobber()
                        BANETO_BOBBER_RDY = nil
                        BANETO_BOBBER_INTERACT_DELAY = nil
                    elseif BANETO_BOBBER_INTERACT_DELAY < GetTime() and BANETO_FISH_THISTIME_FAIL then
                        BANETO_BOBBER_RDY = nil
                        BANETO_BOBBER_INTERACT_DELAY = nil
                    end
                end
                --BANETO_PrintBambo("fishing spot: fishing procedure done")
            else
                BANETO_MeshTo(BANETO_FISH_SPOT_X,BANETO_FISH_SPOT_Y,BANETO_FISH_SPOT_Z)
            end
        end

        if BANETO_State == "FISHING-SKILL" then

			if not BANETO_FISHINGSKILL_INIT then
				local faction,_ = UnitFactionGroup("player")
				if faction == "Horde" then
					BANETO_FISHINGSKILL_TRAINER = {2000.6202392578,-4659.6557617188,26.412420272827,3332}
					BANETO_FISHINGSKILL_SUPPLIER = {1995.4099121094,-4662.3173828125,26.807653427124,3333 }
                    BANETO_FISHINGSKILL_INIT = true
				elseif faction == "Alliance" then
					BANETO_FISHINGSKILL_TRAINER = {-8802.5732421875,767.46313476563,96.338310241699,5493}
					BANETO_FISHINGSKILL_SUPPLIER = {-8803.9375,765.68872070313,96.337409973145,5494 }
                    BANETO_FISHINGSKILL_INIT = true
				end
			end

            if not UnitCastingInfo("player") and BANETO_HasItemToOpen() and not UnitChannelInfo("player") and not UnitCastingInfo("player") then
                BANETO_AutoOpenItems()
            end

			local skillFishing = BANETO_GetProfessionSkill(L["Fishing"])
            if not skillFishing or skillFishing == 0 then
                if not BANETO_PlayerPosition(BANETO_FISHINGSKILL_TRAINER[1],BANETO_FISHINGSKILL_TRAINER[2],BANETO_FISHINGSKILL_TRAINER[3],3) then
                    BANETO_MeshTo(BANETO_FISHINGSKILL_TRAINER[1],BANETO_FISHINGSKILL_TRAINER[2],BANETO_FISHINGSKILL_TRAINER[3])
                else
                    local object = GetObjectWithCoordinates(BANETO_FISHINGSKILL_TRAINER[1],BANETO_FISHINGSKILL_TRAINER[2],BANETO_FISHINGSKILL_TRAINER[3],BANETO_FISHINGSKILL_TRAINER[4])
                    if object then
                        if not ClassTrainerFrame or not ClassTrainerFrame:IsVisible() then
                            if Unlocker("LUA") then
                                BANETO_Interact(object)
                            elseif Unlocker("EWT") then
                                ObjectInteract(object)
                            end
                            BANETO_GossipTrainer()
                        else
                            for i=1, GetNumTrainerServices() do
                                BuyTrainerService(i)
                            end
                        end
                    end
                end
            elseif GetItemCount(6256) <= 0 and GetItemCount(6365) <= 0  then
                if not BANETO_PlayerPosition(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3],3) then
                    BANETO_MeshTo(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3])
                else
                    local object = GetObjectWithCoordinates(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3],BANETO_FISHINGSKILL_SUPPLIER[4])
                    if object then
                        if not MerchantFrame or not MerchantFrame:IsVisible() then
                            if Unlocker("LUA") then
                                BANETO_Interact(object)
                            elseif Unlocker("EWT") then
                                ObjectInteract(object)
                            end
                            if  GossipTitleButton1 and GossipTitleButton1:IsVisible() then
                                GossipTitleButton1:Click()
                            end
                        else
                            if not BANETO_BUYROD_DELAY or BANETO_BUYROD_DELAY < GetTime() then
                                BANETO_BUYROD_DELAY = GetTime()+5
                                if Unlocker("LUA") and not BANETO_BOUGHT_ROD and lb then
                                    __LB__.Unlock(BuyMerchantItem,4, 1)
                                elseif Unlocker("LUA") and not BANETO_BOUGHT_ROD then
                                   Eval("BuyMerchantItem(4,1)","somth")
                                elseif Unlocker("EWT") and not BANETO_BOUGHT_ROD  then
                                    BuyMerchantItem(4, 1)
                                end
                                MerchantFrameCloseButton:Click()
                                BANETO_BOUGHT_ROD = true
                                return true
                            end
                        end
                    end
                end
            elseif GetItemCount(6529) <= 0  then
                if not BANETO_PlayerPosition(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3],3) then
                    BANETO_MeshTo(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3])
                else
                    local object = GetObjectWithCoordinates(BANETO_FISHINGSKILL_SUPPLIER[1],BANETO_FISHINGSKILL_SUPPLIER[2],BANETO_FISHINGSKILL_SUPPLIER[3],BANETO_FISHINGSKILL_SUPPLIER[4])
                    if object then
                        if not MerchantFrame or not MerchantFrame:IsVisible() then
                            if Unlocker("LUA") then
                                BANETO_Interact(object)
                            elseif Unlocker("EWT") then
                                ObjectInteract(object)
                            end
                            if  GossipTitleButton1 and GossipTitleButton1:IsVisible() then
                                GossipTitleButton1:Click()
                            end
                        else
                            if not BANETO_BUYROD_DELAY or BANETO_BUYROD_DELAY < GetTime() then
                                BANETO_BUYROD_DELAY = GetTime()+5
                                if Unlocker("LUA") and lb  then
                                    __LB__.Unlock(BuyMerchantItem,5, 10)
                                else

                                    if _internal.Software() == "tnk" then
                                        Eval("BuyMerchantItem(5,10)","somth")
                                    else
                                        Unlock("BuyMerchantItem()",5,10)
                                    end
                                end
                                MerchantFrameCloseButton:Click()
                                return true
                            end
                        end
                    end
                end
            else
                if BANETO_BOUGHT_ROD == true then
                    if MerchantFrameCloseButton:IsVisible() then
                        MerchantFrameCloseButton:Click()
                    else
                        BANETO_UseItem(6256)
                        BANETO_BOUGHT_ROD = nil
                    end

                end

				if GetShapeshiftDruid() ~= 0 then
					CancelShapeshift()
				end
				if IsMounted() then
					BANETO_Dismount()
				end
                if BANETO_IsSpellUsable(7620) and not BANETO_GetBobberState() and not UnitCastingInfo("player") and not UnitChannelInfo("player") then
                    BANETO_CastSpell(7620, true)
                    BANETO_BOBBER_INTERACT_DELAY = nil
                    local numRanFish = math.random(1,5)
                    BANETO_FISH_START_TIME = GetTime()+24+numRanFish
                elseif (BANETO_GetBobberState() and BANETO_GetBobberState() == true) or (BANETO_FISH_START_TIME and BANETO_FISH_START_TIME < GetTime()) then
                    if not BANETO_BOBBER_INTERACT_DELAY then
                        BANETO_BOBBER_INTERACT_DELAY = GetTime() + 0.5
                    end
                    if BANETO_BOBBER_INTERACT_DELAY < GetTime() then
                        BANETO_InteractWithBobber()
                        BANETO_BOBBER_INTERACT_DELAY = nil
                    end
                end
			end
        end


end



