    local function BANETO_GetAccountId()
        if _internal.Software() == "nn" then
            local string = GetWowAccount()
            if not string or string == "" then
                return "nnGLITCH"
            else
                return string
            end
        else
            if not _G.TINKRLOADBUG then
                --_G.TINKRLOADBUG = "tinkrBug"..math.random(1,5000)
            end
            local string = _G.TINKRLOADBUG or GetAccountId()
            if not string or string == "" then
                return ClientRandom()
            else
                return string
            end
        end
    end


