                    if BANETO_PROFILEEDITOR_MODE == "GRIND/GATHER" then
                        BANETO_EDITOR_GRINDGATHER_LoadProfile()
                    elseif BANETO_PROFILEEDITOR_MODE == "QUESTER" then
                        BANETO_EDITOR_QUESTER_LoadProfile()
                    end
                else
                    BANETO_PrintError("Stop BANETO before trying to edit profiles!")
                end
            end)

