    BANETO_TASK_ADD:SetText("ADD TASK")
    BANETO_TASK_ADD:SetNormalFontObject("GameFontNormalSmall")
    BANETO_TASK_ADD:SetScript("OnClick",
            function()
                local taskProfilename = BANETO_SUB_FRAME_SETTINGS_ADDPROFILENAME_TASK:GetText()
                local taskDuration = BANETO_SUB_FRAME_SETTINGS_ADDPROFILEDURATION_TASK:GetText()
                local taskType = "Grind/Gather/Quest"
                local taskIsLocal = true
                if not taskDuration or not taskProfilename or taskProfilename == "" or taskDuration == "" or taskDuration == "Minutes" or taskProfilename == "Enter Profilename..." or tonumber(taskDuration) == nil or tonumber(taskDuration) <= 0 then
                    BANETO_PrintError("Enter a profilename and task duration in minutes before adding the task!")
                else
                    if BANETO_TASK_MANAGER and #BANETO_TASK_MANAGER >= 1 then
                        if BANETO_TASK_MANAGER and #BANETO_TASK_MANAGER >= 10 then
                            BANETO_PrintError("Currently 10 tasks are the maximum!")
                            return false
                        end
                        if BANETO_BLOCK_TASK_DUPLICATES then
                            for i = 1,#BANETO_TASK_MANAGER do
                                if taskType == BANETO_TASK_MANAGER[i][1] and taskProfilename == BANETO_TASK_MANAGER[i][3]   then
                                    BANETO_PrintError("Task seems to be a duplicate?!")
                                    return false
                                end
                            end
                        end
                    end

                    BANETO_AddTask(taskType,taskDuration,taskProfilename,taskIsLocal)
                    BANETO_PrintSuccess("Sucessfully added & saved your task! " .. taskProfilename)
                    BANETO_SUB_FRAME_SETTINGS_ADDPROFILENAME_TASK:SetText("Enter Profilename...")
                    BANETO_SUB_FRAME_SETTINGS_ADDPROFILEDURATION_TASK:SetText("Minutes")
                end

            end)

    ntex = BANETO_TASK_ADD:CreateTexture()
