                if Unlocker("LUA") then
                    local x,y,z = BANETO_ObjectPosition("player")
                    local mapid = BANETO_GetMapId()
                    local name = BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:GetText()
                    if name ~= "Enter Locationname..." and name ~= "" then
                        BANETO_DefineCustomTravelVector(x,y,z,mapid,name)
                        BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:SetText("Enter Locationname...")
                        BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:ClearFocus()
                        BANETO_PrintSuccess("Stored location data for new custom travel location: " .. name)
                    else
                        BANETO_PrintError("Please enter a name for your custom travel location first!")
                    end
                elseif Unlocker("EWT") then
                    local x,y,z = ObjectPosition("player")
                    local mapid = GetMapId()
                    local name = BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:GetText()
                    if name ~= "Enter Locationname..." and name ~= "" then
                        BANETO_DefineCustomTravelVector(x,y,z,mapid,name)
                        BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:SetText("Enter Locationname...")
                        BANETO_SUB_FRAME_TRAVELING_CUSTOMTRAVELPOINT_TITLE_EDITBOX:ClearFocus()
                        BANETO_PrintSuccess("Stored location data for new custom travel location: " .. name)
                    else
                        BANETO_PrintError("Please enter a name for your custom travel location first!")
                    end
                end

            end)
