    BANETO_QUICKTRAVEL_BUTTON_MAPCLICK:SetNormalFontObject("GameFontNormalSmall")
    BANETO_QUICKTRAVEL_BUTTON_MAPCLICK:SetScript("OnClick",
            function()
                if BANETO_IsRunning() then
                    BANETO_PrintError("Stop baneto before using click map quick traveling.")
                else
                    if not WorldMapFrame or not WorldMapFrame.ScrollContainer:IsVisible() then
                        MinimapCluster.ZoneTextButton:Click()
                    end
                    if not BANETO_CLICK_MAP_HOOK then
                        BANETO_CLICK_MAP_HOOK = true
                        WorldMapFrame.ScrollContainer:HookScript("OnMouseUp", function(self, button)
                            BANETO_PrintBambo("Map click")
                            if button == "LeftButton" and BANETO_CLICK_MAP_LISTENER and BANETO_CLICK_MAP_LISTENER == true then
                                --Normalize cursor Pos
                                local cx, cy = self:GetNormalizedCursorPosition()
                                --grab world pos from map pos
                                local cont, wPos = C_Map.GetWorldPosFromMapPos(WorldMapFrame:GetMapID(), CreateVector2D(cx, cy))
                                if wPos then
                                    local wx, wy = wPos:GetXY()
                                    local _, _, wz = TraceLine(wx, wy, 3000, wx, wy, -3000, 0x00100111)
                                    if not wz then
                                        _,_,wz = BANETO_ObjectPosition("player")
                                    end
                                    BANETO_DefineProfileName("Map Click")
                                    BANETO_DefineProfileType("Traveling")
                                    BANETO_DefineProfileTravelVector(wx,wy,wz)
                                    BANETO_Start()
                                    WorldMapFrameCloseButton:Click()
                                end
                            end
                        end)
                    end
                    BANETO_CLICK_MAP_LISTENER = true
                end
            end)
