    -- BOTTOM TEXT - Traveling
    BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT = CreateFrame("Frame", BANETO_SUB_FRAME_GOLDFARMS, BANETO_SUB_FRAME_GOLDFARMS)
    BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT = BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetPoint("Bottom", BANETO_SUB_FRAME_GOLDFARMS, 0, 0)
    BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetFont("GameFontNormal", 15)

    -- SUB FRAME - Traveling - FACTION/CONTINENT LOGIC
    local _, faction = UnitFactionGroup("player")
    if Unlocker("LUA") then
        continent = BANETO_GetMapId()
    elseif Unlocker("EWT") then
        continent, _, _ = GetMapId()
    end
    if faction == "Horde" then
        if continent == 1 then
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetText("CATEGORY: Goldfarming | FACTION: Horde | CONTINENT: Kalimdor")
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetFont("GameFontNormal", 11)
        elseif continent == 0 then
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetText("CATEGORY: Goldfarming | FACTION: Horde | CONTINENT: Eastern Kingdoms")
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetFont("GameFontNormal", 11)
        end
    elseif faction == "Alliance" then
        if continent == 1 then
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetText("CATEGORY: Goldfarming | FACTION: Alliance | CONTINENT: Kalimdor")
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetFont("GameFontNormal", 11)
        elseif continent == 0 then
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetText("CATEGORY: Goldfarming | FACTION: Alliance | CONTINENT: Eastern Kingdoms")
            BANETO_SUB_FRAME_GOLDFARMS_BOTTOMTEXT:SetFont("GameFontNormal", 11)
        end
    end
    BANETO_BuildProfileListGoldfarming()




