_G.BANETO_FLYINGPATH_ZOFFSET = 0
function _G.GeneratePathBamboFlying2(x,y,z)
    local bamboPath = {}
    local cubesSize = 20
    _G.matrix = nil
    local px, py, pz = BANETO_ObjectPosition('player')
    local centerX, centerY, centerZ = px, py, pz
    local start = { ["x"] = centerX, ["y"] = centerY, ["z"] = centerZ+1 }
    table.insert(bamboPath,start)
    blackListPathingNodes = {}
    table.insert(blackListPathingNodes, {centerX,centerY,centerZ})
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000,0x20000)
    local hitX,hitY,hitZ = BANETO_TraceLine(px, py, pz, x,y,z, hitFlags)
    local distanceFromHitToDest;
    if hitX and hitY and hitZ then
      distanceFromHitToDest = GetDistance3D(hitX,hitY,hitZ,x,y,z)
    end
    if not hitX or hitX == 0 or (distanceFromHitToDest and 10>distanceFromHitToDest) then
        local endOfPath = { ["x"] = x, ["y"] = y, ["z"] = z }
        table.insert(bamboPath,endOfPath)
        return bamboPath
    end
    local iterationsMax = 50
    local newPath = true;
    local distanceToDest = GetDistance3D(px, py, 1,x,y,1)
    if distanceToDest and distanceToDest > 100 and pz > z then
        z = pz + BANETO_FLYINGPATH_ZOFFSET
        BANETO_PrintBambo("Flying special case Z Axis")
    end
    for i = 1, iterationsMax do
        local lastX,lastY,lastZ = bamboPath[#bamboPath]["x"],bamboPath[#bamboPath]["y"],bamboPath[#bamboPath]["z"]
        local distanceGoal = GetDistance3D(x,y,z,lastX,lastY,lastZ)
        if distanceGoal > cubesSize+10 then
            local neighbours,neighboursBad = GenerateAllNeighboursToPoint(lastX,lastY,lastZ,cubesSize)
            local nextIndex;
            if newPath and newPath == true then
                --BANETO_PrintBambo("FLYINGPATH - FIND BEST NEIGHBOUR IN CUBE: "..i.."/"..iterationsMax)
                neighbours,neighboursBad = GenerateAllNeighboursToPoint2(lastX,lastY,lastZ,cubesSize,blackListPathingNodes)
                nextIndex = FindBestNeighbourToVector(x,y,z,neighbours,cubesSize)
                if nextIndex then
                    --BANETO_Print("FLYINGPATH - BEST NEIGHBOUR FOUND: "..nextIndex)
                else
                    --BANETO_Print("FLYINGPATH - NO BEST NEIGHBOUR POSSIBL")
                end
            else
                neighbours,neighboursBad = GenerateAllNeighboursToPoint(lastX,lastY,lastZ,cubesSize)
                nextIndex = FindClosestNeighbourToVector(x,y,z,neighbours)
            end
            if nextIndex then
                local centerX, centerY, centerZ = neighbours[nextIndex]["x"],neighbours[nextIndex]["y"],neighbours[nextIndex]["z"]
                local next = { ["x"] = centerX, ["y"] = centerY, ["z"] = centerZ }
                table.insert(blackListPathingNodes, {centerX,centerY,centerZ})
                if BANETO_Customer() == "bambo" then
                    --BANETO_Print("FLYINGPATH - ADDING PATH NODE: "..centerX..","..centerY..","..centerZ)
                end
                table.insert(bamboPath,next)
                index = nextIndex
            end
        else
            local next = { ["x"] = x, ["y"] = y, ["z"] = z }
            table.insert(bamboPath,next)
            break
        end
    end

    return bamboPath
end

function GetDistance3D(X, Y, Z, XX, YY, ZZ)
    local dist;
    if X and XX and Y and YY and Z and ZZ then
        dist = math.sqrt((X-XX)*(X-XX) + (Y-YY)*(Y-YY) + (Z-ZZ)*(Z-ZZ))
        if dist == nil then
            dist = 0
        end
        if (dist < 0 and dist > 0) then
            BANETO_PrintBambo("DISTANCE CALC ERROR -NAND!!!d!!!!")
            return 0
        end
        return	dist
    end
end
function tablelength(T)
      local count = 0
      for j in pairs(T) do
        count = count + 1
      end
      return count
end


function FindClosestNeighbourToVector(x,y,z,neighbours)
   local bestDistance = 99999999
   local bestI = nil
   for i in pairs(neighbours) do
       local centerX, centerY, centerZ, nodeId = neighbours[i]["x"],neighbours[i]["y"],neighbours[i]["z"],neighbours[i]["nodeId"]
       local distance = GetDistance3D(x,y,z,centerX, centerY, centerZ)
       if distance < bestDistance  then
           bestDistance = distance
           bestI = i
       end
   end
   return bestI
end


_G.BANETO_POINTSFORNONHIT = 1
_G.BANETO_POINTSFORNONHIT_UNDER_EXTRA = 0
function FindBestNeighbourToVector(x,y,z,neighbours,cubesSize)
    local bestDistance = 99999999
    local bestI = nil
    local points = {}
    local helperPoints;

    local pointsForNonHit = BANETO_POINTSFORNONHIT
    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000,0x20000)
    for i in pairs(neighbours) do
        points[i] = 0
        local centerX, centerY, centerZ, nodeId = neighbours[i]["x"],neighbours[i]["y"],neighbours[i]["z"],neighbours[i]["nodeId"]
        local distance = GetDistance3D(x,y,z,centerX, centerY, centerZ)

        local xHUnder, yHUnder, zHUnder = BANETO_TraceLine(centerX, centerY, centerZ, centerX, centerY, centerZ-cubesSize*2, hitFlags)
        local xHUpper, yHUpper, zHUpper = BANETO_TraceLine(centerX, centerY, centerZ, centerX, centerY, centerZ+cubesSize*2, hitFlags)
        local xHNorth, yHNorth, zHNorth = BANETO_TraceLine(centerX, centerY, centerZ, centerX+cubesSize*2, centerY, centerZ, hitFlags)
        local xHEast, yHEast, zHEast = BANETO_TraceLine(centerX, centerY, centerZ, centerX, centerY+cubesSize*2, centerZ, hitFlags)
        local xHSouth, yHSouth, zHSouth = BANETO_TraceLine(centerX, centerY, centerZ, centerX-cubesSize*2, centerY, centerZ, hitFlags)
        local xHWest, yHWest, zHWest = BANETO_TraceLine(centerX, centerY, centerZ, centerX, centerY-cubesSize*2, centerZ, hitFlags)
        if distance > 200 then
            if (_internal.Software() == "nn" and xHUnder == false) or (_internal.Software() == "tnk" and xHUnder+yHUnder+zHUnder == 0) then
                points[i] = points[i]+pointsForNonHit+BANETO_POINTSFORNONHIT_UNDER_EXTRA
            end
            if (_internal.Software() == "nn" and xHUpper == false) or (_internal.Software() == "tnk" and xHUpper+yHUpper+zHUpper == 0) then
                points[i] = points[i]+pointsForNonHit
            end
            if (_internal.Software() == "nn" and xHNorth == false) or (_internal.Software() == "tnk" and xHNorth+yHNorth+zHNorth == 0) then
                points[i] = points[i]+pointsForNonHit
            end
            if (_internal.Software() == "nn" and xHEast == false) or (_internal.Software() == "tnk" and xHEast+yHEast+zHEast == 0) then
                points[i] = points[i]+pointsForNonHit
            end
            if (_internal.Software() == "nn" and xHSouth == false) or (_internal.Software() == "tnk" and xHSouth+yHSouth+zHSouth == 0) then
                points[i] = points[i]+pointsForNonHit
            end
            if (_internal.Software() == "nn" and xHWest == false) or (_internal.Software() == "tnk" and xHWest+yHWest+zHWest == 0) then
                points[i] = points[i]+pointsForNonHit
            end
        end
        if distance < bestDistance  then
            points[i] = points[i]-distance
            helperPoints = points[i]
            bestI = i
        end
    end

    for q in pairs(points) do
        local point = points[q]
        if point > helperPoints then
            helperPoints = point
            bestI = q
        end
    end

    return bestI,currentPath
end

function GenerateAllNeighboursToPoint2(lastX,lastY,lastZ,cubesSize,blackList)
    local returnTable = {}
    local returnTableBlacklisted = {}
    local centerX, centerY, centerZ = lastX,lastY,lastZ

    local hitFlags = bit.bor(0x1, 0x10, 0x100, 0x100000,0x20000)

    local allNeighbours = {}
    local input = {}
    local nodeId;
    if not _G.matrix then
        _G.matrix = {}
    end
    input = {["x"] = centerX+cubesSize,["y"] = centerY,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX+cubesSize,["y"] = centerY+cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX,["y"] = centerY+cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX-cubesSize,["y"] = centerY+cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX-cubesSize,["y"] = centerY,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX-cubesSize,["y"] = centerY-cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX,["y"] = centerY-cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)
    input = {["x"] = centerX+cubesSize,["y"] = centerY-cubesSize,["z"] = centerZ,["nodeId"] = #_G.matrix+1}
    table.insert(allNeighbours,input)
    table.insert(_G.matrix,input)

    input = {["x"] = centerX+cubesSize,["y"] = centerY,["z"] = centerZ+cubesSize,["nodeId"] = #_G.matrix+1}
