                    if xCompare and xCompare == centerXX and yCompare == centerYY and zCompare == centerZZ then
                        foundInPath = true
                    end
                end
            end
            if foundInPath == false then
                returnTable[i] = allNeighbours[i]
            end
        else
            returnTableBlacklisted[i] = allNeighbours[i]
        end
    end
    if returnTable and #returnTable == 0 then
        --BANETO_Print("FLYINGPATH - NO NEIGHBOURS IN CUBE: EMERGENCY ESCAPE STEP: " .. #returnTable)
    end
    return returnTable,returnTableBlacklisted
end


