function FindAllNeighbourPointsInMatrix(matrix,id,radius)
    local returnTable = {}
    local returnTableBlacklisted = {}
    local centerX, centerY, centerZ = matrix[id]["x"],matrix[id]["y"],matrix[id]["z"]
    local c = 0
    local hitFlags = Tinkr.Common.HitFlags.All
    for i = 1,#matrix do
        local centerXX, centerYY, centerZZ = matrix[i]["x"],matrix[i]["y"],matrix[i]["z"]
        local distance = GetDistance3D(centerX, centerY, centerZ,centerXX, centerYY, centerZZ)
        if distance < radius then
            local xH1, yH1, zH1 = BANETO_TraceLine(centerX, centerY, centerZ, centerXX, centerYY, centerZZ, hitFlags)
            if xH1+yH1+zH1 == 0 then
                returnTable[i] = matrix[i]
                c = c+1
            else
                returnTableBlacklisted[i] = matrix[i]
            end
        elseif distance < radius then

        end
        if c >= 7 then
            break
        end
    end
    return returnTable,returnTableBlacklisted
end

function FindClosestPointInMatrix(matrix,x,y,z)
    local bestDistance = 99999999
    local bestI = nil
    for i = 1, #matrix do
        local centerX, centerY, centerZ = matrix[i]["x"],matrix[i]["y"],matrix[i]["z"]
        local distance = GetDistance3D(x,y,z,centerX, centerY, centerZ)
        if distance < bestDistance and 0<distance  then
            bestDistance = distance
            bestI = i
        end

        if i ==  #matrix then
            return bestI
        end
    end
end

function _G.GenerateMatrix(x,y,z,buffer,distanceBetween)
    local px, py, pz = BANETO_ObjectPosition('player')
    local generatedMatrix = {}
    local generatedX = {}
    local generatedY = {}
    local generatedZ = {}
    if not buffer then
        buffer = 50
    end
    if not distanceBetween then
        distanceBetween = 10
    end
    --apply buffer
    if px < x then
        px = px-buffer
        x = x+buffer
    else
        px = px+buffer
        x = x-buffer
    end
    if py < y then
        py = py-buffer
        y = y+buffer
    else
        py = py+buffer
        y = y-buffer
    end
    if pz < z then
        pz = pz-buffer
        z = z+buffer
    else
        pz = pz+buffer
        z = z-buffer
    end

    --add points
    if px < x then
        while(px < x) do
            table.insert(generatedX,px)
            px = px+distanceBetween
        end
    else
        while(px > x) do
            table.insert(generatedX,px)
            px = px-distanceBetween
        end
    end
    if py < y then
        while(py < y) do
            table.insert(generatedY,py)
            py = py+distanceBetween
        end
    else
        while(py > y) do
            table.insert(generatedY,py)
            py = py-distanceBetween
        end
    end
    if pz < z then
        while(pz < z) do
            table.insert(generatedZ,pz)
            pz = pz+distanceBetween
        end
    else
        while(pz > z) do
            table.insert(generatedZ,pz)
            pz = pz-distanceBetween
        end
    end

    for i=1,#generatedX do
        for j=1,#generatedY do
            for k = 1,#generatedZ do
                local xToPut,yToPut,zToPut = generatedX[i],generatedY[j],generatedZ[k]
                local input =  {    ["x"] = xToPut,
                                    ["y"] = yToPut,
                                    ["z"] = zToPut,
                                    ["nodeId"] = #generatedMatrix+1
                                }
                table.insert(generatedMatrix,input)
            end
        end
    end
    _G.matrix = generatedMatrix
    return generatedMatrix
end

